struct MeshData
{
    static constexpr std::size_t kReusableVertexCapacity = 4096;
    static constexpr std::size_t kReusableIndexCapacity = 6144;

    std::vector<Vertex> vertices;
    std::vector<std::uint32_t> indices;

    MeshData()
    {
        vertices.reserve(4096);
        indices.reserve(6144);
    }

    void clear()
    {
        vertices.clear();
        indices.clear();
    }

    void trimForReuse()
    {
        trimVector(vertices, kReusableVertexCapacity);
        trimVector(indices, kReusableIndexCapacity);
    }

    bool empty() const
    {
        return vertices.empty() || indices.empty();
    }

    [[nodiscard]] std::size_t retainedBytes() const noexcept
    {
        return vertices.capacity() * sizeof(Vertex) +
               indices.capacity() * sizeof(std::uint32_t);
    }

private:
    template <typename T>
    static void trimVector(std::vector<T>& values, std::size_t targetCapacity)
    {
        if (values.capacity() <= targetCapacity * 2)
        {
            values.clear();
            return;
        }

        std::vector<T> trimmed;
        trimmed.reserve(targetCapacity);
        values.swap(trimmed);
    }
};

enum class ChunkState : std::uint8_t
{
    Empty = 0,
    Generating,
    Meshing,
    Ready,
    Uploaded,
    Remeshing
};

enum class ExactChunkResidencyMode : std::uint8_t
{
    CpuAuthoritative = 0,
    GpuResidentNonlocal,
    CpuMaterializing,
    GpuPendingRetire
};

const char* chunkStateLabel(ChunkState state) noexcept
{
    switch (state)
    {
    case ChunkState::Empty:
        return "Empty";
    case ChunkState::Generating:
        return "Generating";
    case ChunkState::Meshing:
        return "Meshing";
    case ChunkState::Ready:
        return "Ready";
    case ChunkState::Uploaded:
        return "Uploaded";
    case ChunkState::Remeshing:
        return "Remeshing";
    }
    return "Unknown";
}

const char* exactChunkResidencyModeLabel(ExactChunkResidencyMode mode) noexcept
{
    switch (mode)
    {
    case ExactChunkResidencyMode::CpuAuthoritative:
        return "CpuAuthoritative";
    case ExactChunkResidencyMode::GpuResidentNonlocal:
        return "GpuResidentNonlocal";
    case ExactChunkResidencyMode::CpuMaterializing:
        return "CpuMaterializing";
    case ExactChunkResidencyMode::GpuPendingRetire:
        return "GpuPendingRetire";
    }
    return "Unknown";
}

const char* chunkGameplayAuthorityLabel(ChunkGameplayAuthority authority) noexcept
{
    switch (authority)
    {
    case ChunkGameplayAuthority::LocalGameplay:
        return "LocalGameplay";
    case ChunkGameplayAuthority::HandoffToGpu:
        return "HandoffToGpu";
    case ChunkGameplayAuthority::GpuStreaming:
        return "GpuStreaming";
    }
    return "Unknown";
}

std::string exactGpuSeamMaskLabel(std::uint8_t mask)
{
    if (mask == 0u)
    {
        return "none";
    }

    std::string label;
    auto append = [&label](const char* name)
    {
        if (!label.empty())
        {
            label += '|';
        }
        label += name;
    };

    if ((mask & (1u << 0u)) != 0u)
    {
        append("+X");
    }
    if ((mask & (1u << 1u)) != 0u)
    {
        append("-X");
    }
    if ((mask & (1u << 2u)) != 0u)
    {
        append("+Y");
    }
    if ((mask & (1u << 3u)) != 0u)
    {
        append("-Y");
    }
    if ((mask & (1u << 4u)) != 0u)
    {
        append("+Z");
    }
    if ((mask & (1u << 5u)) != 0u)
    {
        append("-Z");
    }

    return label;
}

