inline constexpr std::uint32_t kInvalidExactGpuDrawRecordIndex = std::numeric_limits<std::uint32_t>::max();
inline constexpr std::uint32_t kExactChunkSizeX = kChunkSizeX;
inline constexpr std::uint32_t kExactChunkSizeY = kChunkSizeY;
inline constexpr std::uint32_t kExactChunkSizeZ = kChunkSizeZ;
inline constexpr std::uint32_t kExactChunkColumnCount = kExactChunkSizeX * kExactChunkSizeZ;
inline constexpr std::uint32_t kExactChunkVoxelCount = kExactChunkSizeX * kExactChunkSizeY * kExactChunkSizeZ;
inline constexpr std::uint32_t kExactChunkHaloFaceVoxelCount = kExactChunkSizeX * kExactChunkSizeY;
inline constexpr std::uint32_t kExactChunkHaloVoxelCount = 6u * kChunkSizeX * kChunkSizeY;
inline constexpr std::uint32_t kExactChunkPlaneCount = 102u;
inline constexpr std::uint32_t kExactGpuInitialFaceCapacity = 256u;
// Keep exact pages materially larger than the original water-era baseline so a full
// 48-radius window does not devolve into thousands of tiny page-sized render/cull dispatches.
inline constexpr std::size_t kDefaultExactFaceCapacity = 65536u;
inline constexpr std::size_t kMaxOutstandingExactGpuBuilds = 2048u;
inline constexpr std::size_t kMaxOutstandingExactGpuBatches = 16u;
inline constexpr int kRenderSpatialBucketSizeChunks = 8;
inline constexpr std::uint32_t kExactGpuLightPropagationPassCount = 15u;
inline constexpr std::uint8_t kExactGpuSeamPosXBit = 1u << 0u;
inline constexpr std::uint8_t kExactGpuSeamNegXBit = 1u << 1u;
inline constexpr std::uint8_t kExactGpuSeamPosYBit = 1u << 2u;
inline constexpr std::uint8_t kExactGpuSeamNegYBit = 1u << 3u;
inline constexpr std::uint8_t kExactGpuSeamPosZBit = 1u << 4u;
inline constexpr std::uint8_t kExactGpuSeamNegZBit = 1u << 5u;
inline constexpr std::uint32_t kExactCompletionStatusCompletedBit = 1u << 0u;
inline constexpr std::uint32_t kExactCompletionStatusOverflowBit = 1u << 1u;
inline constexpr std::uint32_t kExactCompletionStatusZeroFacesBit = 1u << 2u;
inline constexpr std::uint32_t kExactCompletionStatusAllocatorExhaustedBit = 1u << 3u;
inline constexpr std::uint32_t kExactCompletionStatusHasOpaqueFacesBit = 1u << 4u;
inline constexpr std::uint32_t kExactCompletionStatusHasTranslucentFacesBit = 1u << 5u;
inline constexpr std::uint32_t kExactDrawRecordFlagHasOpaqueFaces = 1u << 0u;
inline constexpr std::uint32_t kExactDrawRecordFlagHasTranslucentFaces = 1u << 1u;
inline constexpr std::uint32_t kExactChunkAllocationPhasePrepassSubmitted = 1u;
inline constexpr std::uint32_t kExactChunkAllocationPhaseEmitSubmitted = 2u;
inline constexpr std::size_t kExactGpuReserveFreePageWatermark = 16u;
inline constexpr std::uint32_t kInvalidExactGpuAllocatorFreePageSlot = std::numeric_limits<std::uint32_t>::max();

[[nodiscard]] constexpr std::uint8_t oppositeExactGpuSeamBit(std::uint8_t seamBit) noexcept
{
    switch (seamBit)
    {
    case kExactGpuSeamPosXBit: return kExactGpuSeamNegXBit;
    case kExactGpuSeamNegXBit: return kExactGpuSeamPosXBit;
    case kExactGpuSeamPosYBit: return kExactGpuSeamNegYBit;
    case kExactGpuSeamNegYBit: return kExactGpuSeamPosYBit;
    case kExactGpuSeamPosZBit: return kExactGpuSeamNegZBit;
    case kExactGpuSeamNegZBit: return kExactGpuSeamPosZBit;
    default: return 0u;
    }
}

[[nodiscard]] constexpr std::uint32_t exactDrawRecordFlagsFromCompletionStatus(
    std::uint32_t statusFlags) noexcept
{
    std::uint32_t recordFlags = 0u;
    if ((statusFlags & kExactCompletionStatusHasOpaqueFacesBit) != 0u)
    {
        recordFlags |= kExactDrawRecordFlagHasOpaqueFaces;
    }
    if ((statusFlags & kExactCompletionStatusHasTranslucentFacesBit) != 0u)
    {
        recordFlags |= kExactDrawRecordFlagHasTranslucentFaces;
    }
    return recordFlags;
}

