inline bool storeFirstBenchmarkTimestamp(std::atomic<long long>& current, std::uint64_t micros) noexcept
{
    long long expected = 0;
    const long long value = static_cast<long long>(micros);
    return current.compare_exchange_strong(expected,
                                           value,
                                           std::memory_order_relaxed,
                                           std::memory_order_relaxed);
}

[[nodiscard]] inline std::uint64_t loadBenchmarkTimestamp(const std::atomic<long long>& current) noexcept
{
    const long long value = current.load(std::memory_order_relaxed);
    return value > 0 ? static_cast<std::uint64_t>(value) : 0u;
}




























// ChunkManager::Impl methods (to be filled)

ChunkManager::Impl::Impl(unsigned seed)
    : worldgenProfile_(terrain::WorldgenProfile::load("assets/worldgen.toml")),
      biomeDatabase_("assets/biomes"),
      globalSeaLevel_(worldgenProfile_.seaLevel),
      noise_(worldgenProfile_.effectiveSeed(seed)),
      shouldStop_(false),
      viewDistance_(renderSettings_.exactChunks),
      targetViewDistance_(renderSettings_.exactChunks)
{
    const unsigned effectiveSeed = worldgenProfile_.effectiveSeed(seed);

    noise_.reseed(effectiveSeed);

    if (biomeDatabase_.biomeCount() == 0)
    {
        throw std::runtime_error("Biome database is empty");
    }

    const auto& climateGeneratorName = worldgenProfile_.climateGenerator;
    std::unique_ptr<terrain::ClimateGenerator> climateGenerator;
    if (climateGeneratorName == "legacy" || climateGeneratorName == "voronoi"
        || climateGeneratorName == "noise_voronoi")
    {
        climateGenerator = std::make_unique<terrain::NoiseVoronoiClimateGenerator>(
            biomeDatabase_, worldgenProfile_, effectiveSeed, kChunkSizeX, kBiomeSizeInChunks);
    }
    else
    {
        throw std::runtime_error("Unsupported climate_generator '" + climateGeneratorName
                                 + "' in assets/worldgen.toml");
    }

    constexpr std::size_t kClimateCacheFragments = 128;
    constexpr std::size_t kSurfaceCacheFragments = 192;

    climateMap_ = std::make_unique<terrain::ClimateMap>(std::move(climateGenerator), kClimateCacheFragments);

    surfaceMap_ = std::make_unique<terrain::SurfaceMap>(
        std::make_unique<terrain::MapGenV1>(biomeDatabase_, *climateMap_, worldgenProfile_, effectiveSeed),
        kSurfaceCacheFragments);

    terrainGenerator_ = std::make_unique<terrain::TerrainGenerator>(
        *climateMap_,
        *surfaceMap_,
        biomeDatabase_,
        globalSeaLevel_,
        [this](int worldX, int worldZ, int slabMin, int slabMax) {
            return this->sampleColumnReadyOrThrow(worldX, worldZ, slabMin, slabMax);
        });

    structureRegistry_.clear();

    gActiveVerticalRadius.store(kVerticalStreamingConfig.minRadiusChunks, std::memory_order_relaxed);
    farTerrainManager_.setEnabled(false);
    farTerrainManager_.setDistanceBlocks(0);
    farTerrainManager_.setFogStartBlocks(renderSettings_.fogStartBlocks);
    farTerrainManager_.setSeaLevel(globalSeaLevel_);
    terrain::FarLodWorldgenTables farLodTables =
        terrain::buildFarLodWorldgenTables(biomeDatabase_, worldgenProfile_, effectiveSeed);
    const auto& treeDensityOffsets = noise_.octaveOffsets();
    for (std::size_t i = 0; i < farLodTables.header.treeDensityOctaveOffsets.size(); ++i)
    {
        farLodTables.header.treeDensityOctaveOffsets[i].x = treeDensityOffsets[i].x;
        farLodTables.header.treeDensityOctaveOffsets[i].y = treeDensityOffsets[i].y;
    }
    farTerrainManager_.setWorldgenTables(farLodTables);
    farTerrainManager_.setStructureFieldSources(
        [this](int worldX, int worldZ)
        {
            return this->sampleColumnReadyOrThrow(worldX, worldZ);
        },
        [this](int worldX, int worldZ, const ColumnSample& sample)
        {
            if (!sample.dominantBiome)
            {
                return BlockId::Air;
            }
            const terrain::TerrainColumnBlocks blocks =
                terrain::resolveTerrainColumnBlocks(*sample.dominantBiome, sample, worldX, worldZ, globalSeaLevel_);
            return blocks.surfaceBlock;
        },
        [this](int worldX, int worldZ) noexcept
        {
            return noise_.fbm(static_cast<float>(worldX) * 0.05f,
                              static_cast<float>(worldZ) * 0.05f,
                              4,
                              0.55f,
                              2.0f);
        });
    farTerrainManager_.setBenchmarkMetrics(&benchmarkMetrics_);
    const unsigned concurrency = std::max(2u, std::thread::hardware_concurrency());
    farWorkerCount_ = static_cast<int>(std::clamp(concurrency / 3u, 1u, 4u));
    farTerrainManager_.setWorkerCount(static_cast<std::size_t>(farWorkerCount_));
    kFarPlane = computeFarPlaneForDistanceBlocks(chunksToBlocks(renderSettings_.exactChunks));
    startWorkerThreads();
}

ChunkManager::Impl::~Impl()
{
    setRenderSynchronization(nullptr, 0);
    stopExactPlanBuild();
    stopWorkerThreads();
    stopExactGpuWorkerThread();
    farTerrainManager_.shutdown();
    clear();
    destroyBufferPages();
    freeExactGpuScratchSlices_.clear();
    exactGpuContext_.shutdown();
    resetExactGpuEmitBuffers();
    exactGpuChunkAllocationRecords_.clear();
    exactGpuBlockUvBuffer_.Reset();
    exactGpuEmptyVoxelBuffer_.Reset();
    uploadContext_.shutdown();
}

void ChunkManager::Impl::initializeRendering(ID3D12Device* device)
{
    stopExactGpuWorkerThread();
    device_ = device;
    dxgiAdapter_.Reset();
    if (device_ != nullptr)
    {
        Microsoft::WRL::ComPtr<IDXGIFactory6> factory;
        if (SUCCEEDED(CreateDXGIFactory2(0, IID_PPV_ARGS(&factory))))
        {
            Microsoft::WRL::ComPtr<IDXGIAdapter1> adapter;
            if (SUCCEEDED(factory->EnumAdapterByLuid(device_->GetAdapterLuid(), IID_PPV_ARGS(&adapter))))
            {
                adapter.As(&dxgiAdapter_);
            }
        }
    }
    uploadContext_.initialize(device_.Get());
    exactGpuContext_.initialize(device_.Get());
    exactGpuContext_.setReadbackEnabled(true);
    resetExactGpuEmitBuffers();
    exactGpuChunkAllocationRecords_.assign(exactGpuContext_.maxExactGpuBuildBatches(), {});
    exactGpuEmitConfig_.buildRecordCount =
        static_cast<std::uint32_t>(exactGpuChunkAllocationRecords_.size());
    noteExactGpuEmitConfigRefresh();
    exactGpuBlockUvSrvDescriptorIndex_ = FarLodGpuContext::kInvalidDescriptorIndex;
    freeExactGpuScratchSlices_.clear();
    freeExactGpuScratchSlices_.reserve(exactGpuContext_.maxExactGpuBuildBatches());
    for (std::uint32_t sliceIndex = 0; sliceIndex < exactGpuContext_.maxExactGpuBuildBatches(); ++sliceIndex)
    {
        freeExactGpuScratchSlices_.push_back(sliceIndex);
    }
    farTerrainManager_.setDevice(device_.Get());
    rebuildExactGpuBlockUvBuffer();
    ensureExactGpuEmptyVoxelBuffer();
    destroyBufferPages();
    startExactGpuWorkerThread();
}

void ChunkManager::Impl::rebuildExactGpuBlockUvBuffer()
{
    exactGpuBlockUvBuffer_.Reset();
    exactGpuBlockUvCount_ = 0;
    exactGpuBlockUvBufferState_ = D3D12_RESOURCE_STATE_COMMON;
    if (device_ == nullptr || !blockAtlasConfigured_)
    {
        exactGpuBlockUvSrvDescriptorIndex_ = FarLodGpuContext::kInvalidDescriptorIndex;
        exactGpuEmitConfig_.blockFaceUvDescriptorIndex = exactGpuBlockUvSrvDescriptorIndex_;
        noteExactGpuEmitConfigRefresh();
        return;
    }

    std::vector<FarTerrainManager::GpuBlockFaceUv> uvTable;
    uvTable.resize(toIndex(BlockId::Count) * kBlockFaceCount);
    for (std::size_t blockIndex = 0; blockIndex < toIndex(BlockId::Count); ++blockIndex)
    {
        const BlockUVSet& uvSet = blockUVTable_[blockIndex];
        for (std::size_t faceIndex = 0; faceIndex < kBlockFaceCount; ++faceIndex)
        {
            const FaceUV& faceUv = uvSet.faces[faceIndex];
            uvTable[blockIndex * kBlockFaceCount + faceIndex] =
                FarTerrainManager::GpuBlockFaceUv{faceUv.base, faceUv.size};
        }
    }

    const std::uint64_t bufferBytes =
        static_cast<std::uint64_t>(uvTable.size() * sizeof(FarTerrainManager::GpuBlockFaceUv));
    exactGpuBlockUvBuffer_ = createDefaultBuffer(device_.Get(), bufferBytes, D3D12_RESOURCE_STATE_COMMON);
    if (exactGpuBlockUvBuffer_ == nullptr)
    {
        return;
    }

    std::byte* uploadMapped = nullptr;
    Microsoft::WRL::ComPtr<ID3D12Resource> upload =
        createUploadBuffer(device_.Get(), bufferBytes, uploadMapped);
    if (upload == nullptr || uploadMapped == nullptr)
    {
        exactGpuBlockUvBuffer_.Reset();
        return;
    }

    std::memcpy(uploadMapped, uvTable.data(), static_cast<std::size_t>(bufferBytes));
    if (uploadContext_.ready() && uploadContext_.begin())
    {
        uploadContext_.transition(exactGpuBlockUvBuffer_.Get(),
                                  D3D12_RESOURCE_STATE_COMMON,
                                  D3D12_RESOURCE_STATE_COPY_DEST);
        uploadContext_.copyBuffer(exactGpuBlockUvBuffer_.Get(), 0, upload.Get(), 0, bufferBytes);
        uploadContext_.transition(exactGpuBlockUvBuffer_.Get(),
                                  D3D12_RESOURCE_STATE_COPY_DEST,
                                  D3D12_RESOURCE_STATE_COMMON);
        uploadContext_.flush(nullptr);
        uploadContext_.waitForIdle();
    }
    upload->Unmap(0, nullptr);
    exactGpuBlockUvCount_ = static_cast<std::uint32_t>(uvTable.size());
    if (exactGpuBlockUvSrvDescriptorIndex_ == FarLodGpuContext::kInvalidDescriptorIndex)
    {
        exactGpuBlockUvSrvDescriptorIndex_ = exactGpuContext_.allocatePersistentDescriptorRange(1u);
    }
    exactGpuContext_.writePersistentStructuredSrvDescriptor(
        exactGpuBlockUvSrvDescriptorIndex_,
        exactGpuBlockUvBuffer_.Get(),
        0,
        exactGpuBlockUvCount_,
        static_cast<std::uint32_t>(sizeof(FarTerrainManager::GpuBlockFaceUv)));
    exactGpuEmitConfig_.blockFaceUvDescriptorIndex = exactGpuBlockUvSrvDescriptorIndex_;
    noteExactGpuEmitConfigRefresh();
}

void ChunkManager::Impl::ensureExactGpuEmptyVoxelBuffer()
{
    exactGpuEmptyVoxelBuffer_.Reset();
    exactGpuEmptyVoxelBufferState_ = D3D12_RESOURCE_STATE_COMMON;
    if (device_ == nullptr)
    {
        return;
    }

    const std::uint64_t bufferBytes =
        static_cast<std::uint64_t>(kChunkSizeX * kChunkSizeY * kChunkSizeZ * sizeof(std::uint32_t));
    exactGpuEmptyVoxelBuffer_ =
        createDefaultBuffer(device_.Get(), bufferBytes, D3D12_RESOURCE_STATE_COMMON);
    if (exactGpuEmptyVoxelBuffer_ == nullptr)
    {
        return;
    }

    std::byte* uploadMapped = nullptr;
    Microsoft::WRL::ComPtr<ID3D12Resource> upload =
        createUploadBuffer(device_.Get(), bufferBytes, uploadMapped);
    if (upload == nullptr || uploadMapped == nullptr)
    {
        exactGpuEmptyVoxelBuffer_.Reset();
        return;
    }

    std::memset(uploadMapped, 0, static_cast<std::size_t>(bufferBytes));
    if (uploadContext_.ready() && uploadContext_.begin())
    {
        uploadContext_.transition(exactGpuEmptyVoxelBuffer_.Get(),
                                  D3D12_RESOURCE_STATE_COMMON,
                                  D3D12_RESOURCE_STATE_COPY_DEST);
        uploadContext_.copyBuffer(exactGpuEmptyVoxelBuffer_.Get(), 0, upload.Get(), 0, bufferBytes);
        uploadContext_.transition(exactGpuEmptyVoxelBuffer_.Get(),
                                  D3D12_RESOURCE_STATE_COPY_DEST,
                                  D3D12_RESOURCE_STATE_COMMON);
        uploadContext_.flush(nullptr);
        uploadContext_.waitForIdle();
    }
    upload->Unmap(0, nullptr);
}

bool ChunkManager::Impl::ensureExactGpuFreePageReserve(std::size_t minFreePageCount)
{
    if (device_ == nullptr || !exactGpuContext_.ready())
    {
        return false;
    }

    std::lock_guard<std::mutex> lock(bufferPageMutex_);
    while (freeExactGpuPageCount_ < minFreePageCount)
    {
        ChunkBufferPage reservePage{};
        try
        {
            reservePage = createBufferPage(1u, 1u, ChunkBufferPageUsage::ExactGpu);
        }
        catch (const std::exception&)
        {
            return false;
        }

        bufferPages_.push_back(std::move(reservePage));
        noteExactGpuEmitConfigRefresh();
        noteExactGpuPageMetadataChange(static_cast<std::uint32_t>(bufferPages_.size() - 1u));
        ++freeExactGpuPageCount_;
    }

    return true;
}

bool ChunkManager::Impl::ensureChunkExactGpuBuildResourcesLocked(Chunk& chunk)
{
    if (device_ == nullptr || !exactGpuContext_.ready())
    {
        return false;
    }

    const std::uint32_t sparseVoxelCount =
        static_cast<std::uint32_t>(chunk.gpuExactSparseVoxels.size());
    if (sparseVoxelCount > 0 &&
        (chunk.exactGpu.sparseVoxelBuffer == nullptr ||
         chunk.exactGpu.sparseVoxelCapacity < sparseVoxelCount))
    {
        const std::uint64_t sparseBytes =
            static_cast<std::uint64_t>(std::max<std::uint32_t>(sparseVoxelCount, 1u)) *
            sizeof(GpuExactSparseVoxel);
        chunk.exactGpu.sparseVoxelBuffer =
            createDefaultBuffer(device_.Get(), sparseBytes, D3D12_RESOURCE_STATE_COMMON);
        chunk.exactGpu.sparseVoxelState = D3D12_RESOURCE_STATE_COMMON;
        chunk.exactGpu.sparseVoxelCapacity = sparseVoxelCount;
    }

    const std::uint64_t voxelBytes =
        static_cast<std::uint64_t>(kChunkSizeX * kChunkSizeY * kChunkSizeZ) * sizeof(std::uint32_t);
    if (chunk.exactGpu.voxelBuffer == nullptr)
    {
        chunk.exactGpu.voxelBuffer = createDefaultBuffer(device_.Get(),
                                                         voxelBytes,
                                                         D3D12_RESOURCE_STATE_COMMON,
                                                         D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
        chunk.exactGpu.voxelState = D3D12_RESOURCE_STATE_COMMON;
    }
    const std::uint64_t haloBytes =
        static_cast<std::uint64_t>(kExactChunkHaloVoxelCount) * sizeof(std::uint32_t);
    if (chunk.exactGpu.haloBuffer == nullptr)
    {
        chunk.exactGpu.haloBuffer = createDefaultBuffer(device_.Get(),
                                                        haloBytes,
                                                        D3D12_RESOURCE_STATE_COMMON,
                                                        D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
        chunk.exactGpu.haloState = D3D12_RESOURCE_STATE_COMMON;
    }
    if (chunk.exactGpu.lightScratchBuffer == nullptr)
    {
        chunk.exactGpu.lightScratchBuffer = createDefaultBuffer(device_.Get(),
                                                                voxelBytes,
                                                                D3D12_RESOURCE_STATE_COMMON,
                                                                D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
        chunk.exactGpu.lightScratchState = D3D12_RESOURCE_STATE_COMMON;
    }
    if (chunk.exactGpu.seamBuffer == nullptr)
    {
        chunk.exactGpu.seamBuffer = createDefaultBuffer(device_.Get(),
                                                        haloBytes,
                                                        D3D12_RESOURCE_STATE_COMMON,
                                                        D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
        chunk.exactGpu.seamState = D3D12_RESOURCE_STATE_COMMON;
    }

    return chunk.exactGpu.voxelBuffer != nullptr &&
           chunk.exactGpu.haloBuffer != nullptr &&
           chunk.exactGpu.seamBuffer != nullptr &&
           chunk.exactGpu.lightScratchBuffer != nullptr &&
           (sparseVoxelCount == 0 || chunk.exactGpu.sparseVoxelBuffer != nullptr);
}

