void ChunkManager::Impl::setRenderDistance(int distance) noexcept
{
    setExactRenderDistanceChunks(distance);
}

void ChunkManager::Impl::setExactRenderDistanceChunks(int chunks) noexcept
{
    try
    {
        const int clampedDistance = std::clamp(chunks, 1, kMaxExactRenderDistanceChunks);
        renderSettings_.exactChunks = clampedDistance;
        startupExactPreloadChunks_ = std::min(startupExactPreloadChunks_, renderSettings_.exactChunks);
        if (renderSettings_.totalChunks < renderSettings_.exactChunks)
        {
            renderSettings_.totalChunks = renderSettings_.exactChunks;
        }
        if (!startupEnabled_ || !startupState_.preloadStarted || startupState_.phase == StreamingPhase::SteadyState)
        {
            targetViewDistance_ = clampedDistance;
            startupState_.exactNearCurrentChunks = clampedDistance;
        }
        else
        {
            startupState_.exactNearCurrentChunks = std::min(startupState_.exactNearCurrentChunks, clampedDistance);
            targetViewDistance_ = std::min(startupState_.exactNearCurrentChunks, clampedDistance);
        }
        farTerrainManager_.setEnabled(renderSettings_.totalChunks > renderSettings_.exactChunks);
        farTerrainManager_.setDistanceBlocks(chunksToBlocks(renderSettings_.totalChunks));
        kFarPlane = computeFarPlaneForDistanceBlocks(
            chunksToBlocks(std::max(renderSettings_.exactChunks, renderSettings_.totalChunks)));
        if (chunks != clampedDistance)
        {
            std::cout << "Exact render distance request " << chunks << " clamped to " << clampedDistance << " chunks"
                      << std::endl;
        }

        if (viewDistance_ > targetViewDistance_)
        {
            viewDistance_ = targetViewDistance_;
        }

        const long long width = static_cast<long long>(renderSettings_.exactChunks) * 2ll + 1ll;
        const long long totalColumns = width * width;
        std::cout << "Exact render distance set to: configured=" << renderSettings_.exactChunks
                  << " scheduling=" << targetViewDistance_
                  << " chunks (total exact columns: " << totalColumns << ")" << std::endl;
        trimChunkPoolToBudget();
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error setting exact render distance: " << ex.what() << std::endl;
    }
}

void ChunkManager::Impl::setTotalRenderDistanceChunks(int chunks) noexcept
{
    try
    {
        renderSettings_.totalChunks = std::clamp(chunks, 1, kMaxTotalRenderDistanceChunks);
        startupState_.farCurrentBlocks = 0;
        farTerrainManager_.setEnabled(renderSettings_.totalChunks > renderSettings_.exactChunks);
        farTerrainManager_.setDistanceBlocks(chunksToBlocks(renderSettings_.totalChunks));
        if (renderSettings_.totalChunks > renderSettings_.exactChunks)
        {
            std::cout << "LOD render distance active: exact " << renderSettings_.exactChunks
                      << " chunks, total " << renderSettings_.totalChunks << " chunks." << std::endl;
        }
        kFarPlane = computeFarPlaneForDistanceBlocks(
            chunksToBlocks(std::max(renderSettings_.exactChunks, renderSettings_.totalChunks)));
    }
    catch (const std::exception& ex)
    {
        std::cerr << "Error setting total render distance: " << ex.what() << std::endl;
    }
}

void ChunkManager::Impl::setNearRenderDistance(int chunks) noexcept
{
    setExactRenderDistanceChunks(chunks);
}

void ChunkManager::Impl::setFarRenderDistanceBlocks(int blocks) noexcept
{
    setTotalRenderDistanceChunks(blocksToChunkRadiusCeil(blocks));
}

void ChunkManager::Impl::setFogStartBlocks(int blocks) noexcept
{
    renderSettings_.fogStartBlocks = std::max(blocks, 0);
    farTerrainManager_.setFogStartBlocks(renderSettings_.fogStartBlocks);
}

void ChunkManager::Impl::setFarTerrainEnabled(bool enabled)
{
    (void)enabled;
    // Legacy far-terrain toggles are obsolete. LOD now follows Exact/Total distance settings.
    startupState_.farCurrentBlocks = 0;
    farTerrainManager_.setEnabled(renderSettings_.totalChunks > renderSettings_.exactChunks);
    farTerrainManager_.setDistanceBlocks(chunksToBlocks(renderSettings_.totalChunks));
    trimChunkPoolToBudget();
    std::cout << "[ChunkManager] Legacy far-terrain toggle is obsolete. LOD follows Exact/Total render distance."
              << std::endl;
}

bool ChunkManager::Impl::farTerrainEnabled() const noexcept
{
    return renderSettings_.totalChunks > renderSettings_.exactChunks;
}

void ChunkManager::Impl::setLodEnabled(bool enabled)
{
    setFarTerrainEnabled(enabled);
}

bool ChunkManager::Impl::lodEnabled() const noexcept
{
    return renderSettings_.totalChunks > renderSettings_.exactChunks;
}

BlockId ChunkManager::Impl::blockAt(const glm::ivec3& worldPos) const noexcept
{
    BlockId overlayBlock = BlockId::Air;
    if (tryGetBlockEditOverlay(worldPos, overlayBlock))
    {
        return overlayBlock;
    }

    const glm::ivec3 chunkCoord = worldToChunkCoords(worldPos.x, worldPos.y, worldPos.z);
    auto chunk = getChunkShared(chunkCoord);
    if (!chunk)
    {
        return BlockId::Air;
    }

    if (worldPos.y < chunk->minWorldY || worldPos.y > chunk->maxWorldY)
    {
        return BlockId::Air;
    }
    const glm::ivec3 local = localBlockCoords(worldPos, chunkCoord);
    if (!chunk->cpuDataResident.load(std::memory_order_acquire) ||
        chunk->blocks.size() != static_cast<std::size_t>(kChunkBlockCount))
    {
        return BlockId::Air;
    }
    const int localY = worldPos.y - chunk->minWorldY;
    return chunk->blocks[blockIndex(local.x, localY, local.z)];

}

LightSample ChunkManager::Impl::lightAt(const glm::ivec3& worldPos) const noexcept
{
    const std::uint8_t packed = packedLightAtWorld(worldPos);
    return LightSample{skyLightFromPacked(packed), blockLightFromPacked(packed)};
}

glm::vec3 ChunkManager::Impl::findSafeSpawnPosition(float worldX, float worldZ) const
{
    const int baseX = static_cast<int>(std::floor(worldX));
    const int baseZ = static_cast<int>(std::floor(worldZ));

    auto mergeHeight = [](int current, int candidate)
    {
        if (candidate == ColumnManager::kNoHeight)
        {
            return current;
        }
        if (current == ColumnManager::kNoHeight)
        {
            return candidate;
        }
        return std::max(current, candidate);
    };

    const auto fallbackSpawnPosition = [&]() -> glm::vec3
    {
        int highestSolid = columnManager_.highestSolidBlock(baseX, baseZ);
        int predictedHeight = ColumnManager::kNoHeight;
        if (tryGetPredictedColumnHeight({floorDiv(baseX, kChunkSizeX), floorDiv(baseZ, kChunkSizeZ)}, predictedHeight))
        {
            highestSolid = mergeHeight(highestSolid, predictedHeight);
        }
        if (highestSolid == ColumnManager::kNoHeight)
        {
            highestSolid = 0;
        }

        const int clearanceHeight = static_cast<int>(std::ceil(kPlayerHeight)) + 2;
        const int spawnFeetY = highestSolid + 1 + clearanceHeight;
        std::cout << "Predicted spawn at height: " << (spawnFeetY + kCameraEyeHeight)
                  << " (feet at: " << spawnFeetY << ")" << std::endl;
        return glm::vec3(worldX, static_cast<float>(spawnFeetY) + kCameraEyeHeight, worldZ);
    };

    const DependencyPriority dependencyPriority = DependencyPriority::Critical;
    const JobServiceClass serviceClass = JobServiceClass::InitialVisible;
    constexpr auto kSpawnDependencyWaitTimeout = std::chrono::seconds(2);
    const auto waitStart = std::chrono::steady_clock::now();
    while (!shouldStop_.load(std::memory_order_acquire) && !spawnFootprintReady(baseX, baseZ))
    {
        (void)requestSpawnFootprintDependencies(baseX, baseZ, dependencyPriority, serviceClass);
        if (std::chrono::steady_clock::now() - waitStart >= kSpawnDependencyWaitTimeout)
        {
            std::cout << "Spawn dependency wait timed out; using predicted fallback." << std::endl;
            return fallbackSpawnPosition();
        }
        std::this_thread::sleep_for(std::chrono::milliseconds(1));
    }

    if (!spawnFootprintReady(baseX, baseZ))
    {
        return fallbackSpawnPosition();
    }

    try
    {
        int highestSolid = columnManager_.highestSolidBlock(baseX, baseZ);
        const ColumnSample baseSample = sampleColumnReadyOrThrow(baseX, baseZ);
        auto sampleColumnAt = [&](int worldX, int worldZ) -> ColumnSample
        {
            return sampleColumnReadyOrThrow(worldX, worldZ);
        };
        auto computeDefaultTreeDensity = [&](int worldX, int worldZ) noexcept
        {
            return noise_.fbm(static_cast<float>(worldX) * 0.05f,
                              static_cast<float>(worldZ) * 0.05f,
                              4,
                              0.55f,
                              2.0f);
        };
        auto resolvedSurfaceBlockAt = [&](int worldX, int worldZ, const ColumnSample& sample) -> BlockId
        {
            if (!sample.dominantBiome)
            {
                return BlockId::Air;
            }
            const terrain::TerrainColumnBlocks blocks =
                terrain::resolveTerrainColumnBlocks(*sample.dominantBiome, sample, worldX, worldZ, globalSeaLevel_);
            return blocks.surfaceBlock;
        };

    auto predictTreeCanopyTop = [&](int originX, int originZ, const ColumnSample& columnSample, int targetX, int targetZ) -> int
    {
        if (!columnSample.dominantBiome || !columnSample.dominantBiome->generatesTrees)
        {
            return ColumnManager::kNoHeight;
        }

        if (columnSample.dominantWeight < kTreeBiomeWeightThreshold)
        {
            return ColumnManager::kNoHeight;
        }

        const int groundWorldY = columnSample.surfaceY;
        if (groundWorldY <= 2)
        {
            return ColumnManager::kNoHeight;
        }

        const BiomeDefinition& biome = *columnSample.dominantBiome;

        if (terrain::isTaigaBiome(biome))
        {
            if (!shouldSpawnTaigaSpruce(biome, originX, groundWorldY, originZ))
            {
                return ColumnManager::kNoHeight;
            }

            int anchorGroundY = std::numeric_limits<int>::min();
            for (int trunkX = 0; trunkX < 2; ++trunkX)
            {
                for (int trunkZ = 0; trunkZ < 2; ++trunkZ)
                {
                    const ColumnSample trunkSample = sampleColumnReadyOrThrow(originX + trunkX, originZ + trunkZ);
                    if (!trunkSample.dominantBiome || !terrain::isTaigaBiome(*trunkSample.dominantBiome))
                    {
                        return ColumnManager::kNoHeight;
                    }
                    if (trunkSample.dominantWeight < kTreeBiomeWeightThreshold)
                    {
                        return ColumnManager::kNoHeight;
                    }

                    const terrain::TerrainColumnBlocks blocks =
                        terrain::resolveTerrainColumnBlocks(*trunkSample.dominantBiome,
                                                            trunkSample,
                                                            originX + trunkX,
                                                            originZ + trunkZ,
                                                            globalSeaLevel_);
                    if (blocks.surfaceBlock != BlockId::Grass && blocks.surfaceBlock != BlockId::Podzol)
                    {
                        return ColumnManager::kNoHeight;
                    }

                    if (anchorGroundY == std::numeric_limits<int>::min())
                    {
                        anchorGroundY = trunkSample.surfaceY;
                    }
                    else if (trunkSample.surfaceY != anchorGroundY)
                    {
                        return ColumnManager::kNoHeight;
                    }
                }
            }

            for (int dx = -2; dx <= 3; ++dx)
            {
                for (int dz = -2; dz <= 3; ++dz)
                {
                    const ColumnSample neighborSample = sampleColumnReadyOrThrow(originX + dx, originZ + dz);
                    if (!neighborSample.dominantBiome)
                    {
                        return ColumnManager::kNoHeight;
                    }
                    if (std::abs(neighborSample.surfaceY - anchorGroundY) > 1)
                    {
                        return ColumnManager::kNoHeight;
                    }
                }
            }

            const int trunkHeight = taigaSpruceTrunkHeight(originX, anchorGroundY, originZ);
            const int bareTrunkHeight = taigaSpruceBareTrunkHeight(originX, anchorGroundY, originZ);
            const int canopyBaseWorld = anchorGroundY + bareTrunkHeight + 1;
            const int canopyTopWorld = anchorGroundY + trunkHeight;
            const int totalLayers = std::max(1, canopyTopWorld - canopyBaseWorld + 1);

            int highestCover = ColumnManager::kNoHeight;
            if (targetX >= originX && targetX <= originX + 1 &&
                targetZ >= originZ && targetZ <= originZ + 1)
            {
                highestCover = canopyTopWorld + 1;
            }

            for (int worldY = canopyBaseWorld; worldY <= canopyTopWorld; ++worldY)
            {
                const int layerFromBottom = worldY - canopyBaseWorld;
                const int radius = taigaSpruceLeafRadiusForLayer(layerFromBottom, totalLayers);
                if (taigaSpruceLeafOccupiesCell(originX,
                                               originZ,
                                               targetX,
                                               targetZ,
                                               radius,
                                               layerFromBottom,
                                               totalLayers))
                {
                    highestCover = std::max(highestCover, worldY);
                }
            }

            return highestCover;
        }

        if (biome.id == "dark_forest")
        {
            DarkOakTreeCandidate darkOakCandidate{};
            if (!tryBuildDarkOakCandidate(originX,
                                          originZ,
                                          columnSample,
                                          sampleColumnAt,
                                          resolvedSurfaceBlockAt,
                                          computeDefaultTreeDensity,
                                          darkOakCandidate))
            {
                return ColumnManager::kNoHeight;
            }

            if (darkOakHasSpacingConflict(darkOakCandidate,
                                          sampleColumnAt,
                                          resolvedSurfaceBlockAt,
                                          computeDefaultTreeDensity))
            {
                return ColumnManager::kNoHeight;
            }

            int highestCover = ColumnManager::kNoHeight;
            forEachDarkOakTreeBlock(darkOakCandidate.originX,
                                    darkOakCandidate.originZ,
                                    darkOakCandidate.groundWorldY,
                                    darkOakCandidate.trunkHeight,
                                    BlockId::DarkOakLog,
                                    BlockId::DarkOakLeaves,
                                    [&](int blockX, int blockY, int blockZ, BlockId) {
                                        if (blockX == targetX && blockZ == targetZ)
                                        {
                                            highestCover = std::max(highestCover, blockY);
                                        }
                                        return false;
                                    });
            return highestCover;
        }

        if (biome.id == "savanna")
        {
            AcaciaTreeCandidate acaciaCandidate{};
            if (!tryBuildAcaciaCandidate(originX,
                                         originZ,
                                         columnSample,
                                         sampleColumnAt,
                                         resolvedSurfaceBlockAt,
                                         computeDefaultTreeDensity,
                                         acaciaCandidate))
            {
                return ColumnManager::kNoHeight;
            }

            if (acaciaHasSpacingConflict(acaciaCandidate,
                                         sampleColumnAt,
                                         resolvedSurfaceBlockAt,
                                         computeDefaultTreeDensity))
            {
                return ColumnManager::kNoHeight;
            }

            int highestCover = ColumnManager::kNoHeight;
            forEachAcaciaTreeBlock(acaciaCandidate.originX,
                                   acaciaCandidate.originZ,
                                   acaciaCandidate.groundWorldY,
                                   acaciaCandidate.trunkHeight,
                                   BlockId::AcaciaLog,
                                   BlockId::AcaciaLeaves,
                                   [&](int blockX, int blockY, int blockZ, BlockId) {
                                       if (blockX == targetX && blockZ == targetZ)
                                       {
                                           highestCover = std::max(highestCover, blockY);
                                       }
                                       return false;
                                   });
            return highestCover;
        }

        DefaultTreeCandidate candidate{};
        if (!tryBuildDefaultTreeCandidate(originX,
                                          originZ,
                                          columnSample,
                                          sampleColumnAt,
                                          computeDefaultTreeDensity,
                                          candidate))
        {
            return ColumnManager::kNoHeight;
        }

        if (defaultTreeHasSpacingConflict(candidate, sampleColumnAt, computeDefaultTreeDensity))
        {
            return ColumnManager::kNoHeight;
        }

        int highestCover = ColumnManager::kNoHeight;
        if (targetX == originX && targetZ == originZ)
        {
            highestCover = candidate.groundWorldY + candidate.trunkHeight;
        }

        const int canopyBaseWorld = candidate.groundWorldY + candidate.trunkHeight - 3;
        const int canopyTopWorld = candidate.groundWorldY + candidate.trunkHeight;
        for (int worldY = canopyBaseWorld; worldY <= canopyTopWorld; ++worldY)
        {
            const int layer = worldY - canopyBaseWorld;
            int radius = kDefaultTreeMaxRadius;
            if (worldY >= canopyTopWorld - 1)
            {
                radius = 1;
            }

            for (int dx = -radius; dx <= radius; ++dx)
            {
                for (int dz = -radius; dz <= radius; ++dz)
                {
                    if (std::abs(dx) == radius && std::abs(dz) == radius && radius > 1)
                    {
                        continue;
                    }

                    if (dx == 0 && dz == 0 && worldY <= candidate.groundWorldY + candidate.trunkHeight - 1)
                    {
                        continue;
                    }

                    if (layer == 0 && std::abs(dx) + std::abs(dz) > 3)
                    {
                        continue;
                    }

                    if (originX + dx == targetX && originZ + dz == targetZ)
                    {
                        highestCover = std::max(highestCover, worldY);
                    }
                }
            }
        }

        return highestCover;
    };

        int predictedHighest = ColumnManager::kNoHeight;
        if (baseSample.dominantBiome)
        {
            predictedHighest = mergeHeight(predictedHighest, baseSample.surfaceY);
        }

        for (int originX = baseX - kTaigaSpruceMaxLeafRadius; originX <= baseX + kTaigaSpruceMaxLeafRadius; ++originX)
        {
            for (int originZ = baseZ - kTaigaSpruceMaxLeafRadius; originZ <= baseZ + kTaigaSpruceMaxLeafRadius; ++originZ)
            {
                const ColumnSample originSample =
                    (originX == baseX && originZ == baseZ) ? baseSample : sampleColumnReadyOrThrow(originX, originZ);
                predictedHighest = mergeHeight(predictedHighest,
                                               predictTreeCanopyTop(originX, originZ, originSample, baseX, baseZ));
            }
        }

        highestSolid = mergeHeight(highestSolid, predictedHighest);
        if (highestSolid == ColumnManager::kNoHeight)
        {
            highestSolid = 0;
        }

        const int clearanceHeight = static_cast<int>(std::ceil(kPlayerHeight)) + 2;
        const int spawnFeetY = std::max(highestSolid + 1, baseSample.surfaceY + 2) + clearanceHeight;
        std::cout << "Predicted spawn at height: " << (spawnFeetY + kCameraEyeHeight)
                  << " (feet at: " << spawnFeetY << ")" << std::endl;
        const float fallbackY = static_cast<float>(spawnFeetY) + kCameraEyeHeight;
        return glm::vec3(worldX, fallbackY, worldZ);
    }
    catch (...)
    {
        return fallbackSpawnPosition();
    }
}

void ChunkManager::Impl::beginSpawnPreload(const glm::vec3& spawnPos)
{
    startupState_ = StartupStreamingState{};
    startupState_.phase = StreamingPhase::ExactPreload;
    startupState_.preloadStarted = true;
    startupState_.spawnChunk = worldToChunkCoords(static_cast<int>(std::floor(spawnPos.x)),
                                                  std::max(static_cast<int>(std::floor(spawnPos.y)), 0),
                                                  static_cast<int>(std::floor(spawnPos.z)));
    startupState_.exactNearCurrentChunks = std::clamp(startupExactPreloadChunks_, 1, renderSettings_.exactChunks);
    startupState_.farCurrentBlocks = 0;
    lastMissingChunks_ = 0;
    cachedExactReadyChunks_ = 0;
    cachedExactRequiredChunks_ = 0;
    lastProtectedMissingChunks_ = 0;
    lastProtectedReadyChunks_ = 0;
    lastProtectedRequiredChunks_ = 0;
    protectedPressureActive_ = false;
    severeProtectedPressureActive_ = false;
    stationaryExactFillModeActive_ = false;
    movementEnvelopeForwardXZ_ = normalizePriorityForwardXZ(lastCameraForward_);
    lastCameraForwardXZ_ = normalizePriorityForwardXZ(lastCameraForward_);
    lastHorizontalMovementShift_ = 0;
    lastVerticalMovementShift_ = 0;
    movementEnvelopeStationarySeconds_ = 0.0;
    movementEnvelopeIdleMode_ = false;
    movementEnvelopeTurnActive_ = false;
    lastJobQueuePriorityOrigin_ = startupState_.spawnChunk;
    lastJobQueuePriorityForwardXZ_ = normalizePriorityForwardXZ(lastCameraForward_);
    lastJobQueuePriorityRefreshTime_ = SteadyClock::time_point{};
    targetViewDistance_ = startupState_.exactNearCurrentChunks;
    if (viewDistance_ > targetViewDistance_)
    {
        viewDistance_ = targetViewDistance_;
    }
    lastCenterChunk_ = startupState_.spawnChunk;
    schedulingPriorityOrigin_ = startupState_.spawnChunk;
    stopExactPlanBuild();
    {
        std::lock_guard<std::mutex> lock(exactPlanMutex_);
        activeExactPlan_.reset();
    }
    stopBulkShellOracle();
    resetStreamingFrontier();
    farTerrainManager_.setDistanceBlocks(startupState_.farCurrentBlocks);
    farTerrainManager_.clear();
    if (renderSettings_.totalChunks <= renderSettings_.exactChunks)
    {
        pinWorldgenWindow(startupState_.spawnChunk, renderSettings_.exactChunks);
        resetExactCoverageCache();
    }
}

bool ChunkManager::Impl::isSpawnPreloadReady() const noexcept
{
    return !startupEnabled_ || !startupState_.preloadStarted || startupState_.phase != StreamingPhase::ExactPreload;
}

bool ChunkManager::Impl::playerReleaseReady() const noexcept
{
    return !startupEnabled_ || !startupState_.preloadStarted || startupState_.playerReleaseReady;
}

StreamingPhase ChunkManager::Impl::streamingPhase() const noexcept
{
    if (!startupEnabled_ || !startupState_.preloadStarted)
    {
        return StreamingPhase::SteadyState;
    }

    return startupState_.phase;
}

void ChunkManager::Impl::setStartupEnabled(bool enabled) noexcept
{
    startupEnabled_ = enabled;
    if (!startupEnabled_)
    {
        startupState_.phase = StreamingPhase::SteadyState;
        startupState_.playerReleaseReady = true;
        startupState_.exactNearCurrentChunks = renderSettings_.exactChunks;
        startupState_.farCurrentBlocks = 0;
        targetViewDistance_ = renderSettings_.exactChunks;
        farTerrainManager_.setDistanceBlocks(0);
    }
}

void ChunkManager::Impl::setStartupExactPreloadChunks(int chunks) noexcept
{
    startupExactPreloadChunks_ = std::clamp(chunks, 1, std::max(renderSettings_.exactChunks, 1));
}

bool ChunkManager::Impl::startupEnabled() const noexcept
{
    return startupEnabled_;
}

StreamingStatusSnapshot ChunkManager::Impl::computeStreamingStatusSnapshot() const noexcept
{
    StreamingStatusSnapshot snapshot{};
    const FrontierCoverage frontierCoverage = streamingFrontierCoverageSnapshot();
    snapshot.phase = streamingPhase();
    snapshot.playerReleaseReady = playerReleaseReady();
    snapshot.exactPendingUploads = static_cast<int>(std::min<std::size_t>(
        estimatePendingExactGpuBuilds(),
        static_cast<std::size_t>(std::numeric_limits<int>::max())));
    snapshot.farActiveTiles = farTerrainManager_.activeTileCount();
    snapshot.farDirtyTiles = farTerrainManager_.dirtyTileCount();
    snapshot.farReadyTiles = farTerrainManager_.readyTileCount();
    snapshot.farQueuedTiles = farTerrainManager_.queuedTileCount();
    snapshot.farPendingUploadTiles = farTerrainManager_.pendingUploadTileCount();

    snapshot.exactReadyChunks = cachedExactReadyChunks_;
    snapshot.exactConfiguredRadiusChunks = renderSettings_.exactChunks;
    snapshot.exactSchedulingRadiusChunks = targetViewDistance_;
    {
        std::lock_guard<std::mutex> lock(exactPlanMutex_);
        snapshot.exactTrackedRadiusChunks = exactCoverageCache_.trackedRadiusChunks;
        const std::size_t configuredIndex =
            static_cast<std::size_t>(std::clamp(renderSettings_.exactChunks, 0, kMaxExactRenderDistanceChunks));
        snapshot.exactRequiredChunks =
            exactCoverageCache_.displayRequiredByRadius[configuredIndex];
        snapshot.exactRequiredChunksApproximate = !exactCoverageCache_.authoritativeCountsValid;
        snapshot.exactRequiredChunksAuthoritative =
            exactCoverageCache_.authoritativeCountsValid
                ? exactCoverageCache_.authoritativeRequiredByRadius[configuredIndex]
                : 0;
        snapshot.exactCoverageReconciling = exactCoverageCache_.reconciling || snapshot.exactRequiredChunksApproximate;
    }
    snapshot.exactPlanRadius = snapshot.exactConfiguredRadiusChunks;
    snapshot.exactPlanVisibleRadius = snapshot.exactSchedulingRadiusChunks;
    snapshot.exactPlanPreloadRadius = snapshot.exactTrackedRadiusChunks;
    snapshot.exactProtectedReadyChunks = frontierCoverage.protectedReady;
    snapshot.exactProtectedRequiredChunks = frontierCoverage.protectedRequired;
    snapshot.exactMissingStateChunks = frontierCoverage.exactMissingState;
    snapshot.exactWaitingDependenciesChunks = frontierCoverage.exactWaitingDependencies;
    snapshot.exactQueuedGenerateChunks = frontierCoverage.exactQueuedGenerate;
    snapshot.exactGeneratingChunks = frontierCoverage.exactGenerating;
    snapshot.exactMeshingChunks = frontierCoverage.exactMeshing;

    if (snapshot.exactCoverageReconciling)
    {
        snapshot.blockingReason = "reconciling exact coverage";
    }
    else if (snapshot.playerReleaseReady)
    {
        snapshot.blockingReason = "ready";
    }
    else if (snapshot.exactReadyChunks < snapshot.exactRequiredChunks)
    {
        snapshot.blockingReason = "waiting for exact chunks";
    }
    else if (snapshot.exactPendingUploads > 8)
    {
        snapshot.blockingReason = "waiting for exact gpu builds";
    }
    else
    {
        snapshot.blockingReason = "stabilizing preload";
    }

    maybeLogExactDependencyStallDebug(snapshot);
    return snapshot;
}

StreamingStatusSnapshot ChunkManager::Impl::streamingStatusSnapshot() const noexcept
{
    return computeStreamingStatusSnapshot();
}

void ChunkManager::Impl::maybeLogExactDependencyStallDebug(const StreamingStatusSnapshot& snapshot) const
{
    const bool dependencyCandidate = snapshot.exactWaitingDependenciesChunks > 0;
    const bool exactGpuCandidate =
        snapshot.exactMeshingChunks > 0 ||
        snapshot.exactPendingUploads > 0;
    if (!exactDependencyStallDebugLoggingEnabled())
    {
        return;
    }

    constexpr std::uint64_t kStallPlateauMicros = 8'000'000ull;
    const std::uint64_t nowMicros = steadyMicrosNow();
    const int previousReadyChunks = exactDependencyStallDebugLastReadyChunks_.load(std::memory_order_relaxed);
    if (previousReadyChunks != snapshot.exactReadyChunks)
    {
        exactDependencyStallDebugLastReadyChunks_.store(snapshot.exactReadyChunks, std::memory_order_relaxed);
        exactDependencyStallDebugLastReadyProgressMicros_.store(nowMicros, std::memory_order_relaxed);
    }
    else if (exactDependencyStallDebugLastReadyProgressMicros_.load(std::memory_order_relaxed) == 0u)
    {
        exactDependencyStallDebugLastReadyProgressMicros_.store(nowMicros, std::memory_order_relaxed);
    }
    const std::uint64_t lastReadyProgressMicros =
        exactDependencyStallDebugLastReadyProgressMicros_.load(std::memory_order_relaxed);
    const bool readyBacklogged = snapshot.exactReadyChunks < snapshot.exactRequiredChunks;
    const std::uint64_t readyPlateauMicros =
        (lastReadyProgressMicros != 0u && nowMicros > lastReadyProgressMicros)
            ? (nowMicros - lastReadyProgressMicros)
            : 0u;
    const bool readyPlateau = readyBacklogged && readyPlateauMicros >= kStallPlateauMicros;
    const bool dependencyStall = dependencyCandidate && readyPlateau;
    const bool exactGpuStall = exactGpuCandidate && readyPlateau;
    if (!dependencyStall && !exactGpuStall)
    {
        return;
    }

    constexpr std::uint64_t kLogIntervalMicros = 5'000'000ull;
    std::uint64_t previousMicros = exactDependencyStallDebugLastLogMicros_.load(std::memory_order_relaxed);
    while (previousMicros != 0 && nowMicros > previousMicros && nowMicros - previousMicros < kLogIntervalMicros)
    {
        return;
    }
    while (!exactDependencyStallDebugLastLogMicros_.compare_exchange_weak(previousMicros,
                                                                          nowMicros,
                                                                          std::memory_order_relaxed,
                                                                          std::memory_order_relaxed))
    {
        if (previousMicros != 0 && nowMicros > previousMicros && nowMicros - previousMicros < kLogIntervalMicros)
        {
            return;
        }
    }

    struct WaitingChunkDebugEntry
    {
        glm::ivec3 coord{0};
        std::uint32_t generationEpoch{0};
        bool initialReadyPriority{false};
        bool localInteractionPriority{false};
        std::size_t outstandingDependencyCount{0};
        std::vector<glm::ivec2> missingWorldgenPages;
        std::vector<StructureRegionKey> missingStructureRegions;
    };
    struct ExactGpuQueuedDebugEntry
    {
        glm::ivec3 coord{0};
        std::uint32_t buildVersion{0};
        std::uint32_t generationEpoch{0};
        std::uint64_t inputVersion{0};
        std::uint64_t queuedMicros{0};
        bool rebuildVoxelInputs{false};
        bool prioritizeFront{false};
        bool localInteraction{false};
        bool initialVisible{false};
        bool hasOverlay{false};
    };
    struct ExactGpuBatchPhaseSummary
    {
        std::size_t batchCount{0};
        std::size_t buildCount{0};
        std::uint64_t oldestAgeMicros{0};
    };
    struct ExactGpuBatchOwnershipDebugInfo
    {
        const char* phase{"none"};
        std::uint64_t phaseEnteredMicros{0};
    };
    struct ExactGpuBatchDebugEntry
    {
        glm::ivec3 coord{0};
        const char* phase{"unknown"};
        std::uint32_t buildVersion{0};
        std::uint32_t generationEpoch{0};
        std::uint64_t inputVersion{0};
        std::uint32_t requiredFaceCount{0};
        std::uint32_t faceCapacity{0};
        std::uint8_t pendingNeighborMask{0};
        bool hasAllocation{false};
        std::uint64_t phaseEnteredMicros{0};
    };
    struct ExactGpuChunkDebugEntry
    {
        glm::ivec3 coord{0};
        FrontierDemandState frontierState{FrontierDemandState::Missing};
        bool haveFrontierState{false};
        ChunkState chunkState{ChunkState::Empty};
        int inFlight{0};
        bool hasBlocks{false};
        bool meshReady{false};
        bool exactResident{false};
        bool exactQueued{false};
        bool exactInFlight{false};
        bool inputsDirty{false};
        bool sparseReady{false};
        bool haloDirty{false};
        bool hasOverlay{false};
        bool pendingStructureEdits{false};
        bool localInteraction{false};
        bool initialVisible{false};
        std::uint32_t generationEpoch{0};
        std::uint64_t inputVersion{0};
        std::uint64_t requestedInputVersion{0};
        std::uint64_t readyVersion{0};
        std::uint32_t faceCount{0};
        std::uint32_t recordIndex{kInvalidExactGpuDrawRecordIndex};
        std::uint32_t pageIndex{kInvalidChunkBufferPage};
        std::uint8_t pendingNeighborMask{0};
        std::size_t overlayCount{0};
        std::size_t structureEditCount{0};
        long long requestTimestampMicros{0};
        std::uint64_t readyFenceValue{0};
        std::uint64_t pageLastWriteFenceValue{0};
        std::uint32_t fenceDeferredCount{0};
        std::uint32_t requeueCount{0};
        long long lastFenceDeferredMicros{0};
        long long lastRequeueMicros{0};
        bool blockedByReadyFence{false};
        const char* batchPhase{"none"};
        std::uint64_t batchPhaseEnteredMicros{0};
    };
    struct ExactCoverageDebugSnapshot
    {
        bool active{false};
        bool authoritativeCountsValid{false};
        bool reconciling{false};
        bool movingWindow{false};
        int trackedRadiusChunks{0};
        int verticalRadius{0};
        int coverageColumnsBudget{0};
        int columnsProcessedLastUpdate{0};
        int pendingColumnsBeforeUpdate{0};
        int pendingColumnsAfterUpdate{0};
        int queuedColumns{0};
        int dirtyColumns{0};
        int dirtyPages{0};
        int dirtyRegions{0};
        std::size_t cachedColumns{0};
        double smoothedFrameMs{0.0};
    };
    struct ExactGpuPageDebugEntry
    {
        std::uint32_t pageIndex{kInvalidChunkBufferPage};
        ChunkBufferPageState state{ChunkBufferPageState::Free};
        std::size_t faceCursor{0};
        std::size_t faceCapacity{0};
        std::size_t recordCursor{0};
        std::size_t recordCapacity{0};
        std::size_t recordActiveCount{0};
        std::size_t residentChunks{0};
        std::size_t pendingChunks{0};
        std::size_t liveResidentChunkCount{0};
        std::size_t exactChunkMemberCount{0};
        std::size_t exactPendingPublishCount{0};
        bool sealRequested{false};
        std::uint64_t lastWriteFenceValue{0};
        std::uint64_t retireFenceValue{0};
        std::uint64_t idleAgeMicros{0};
    };

    ExactCoverageDebugSnapshot coverageDebug{};
    {
        std::lock_guard<std::mutex> lock(exactPlanMutex_);
        coverageDebug.active = exactCoverageCache_.active;
        coverageDebug.authoritativeCountsValid = exactCoverageCache_.authoritativeCountsValid;
        coverageDebug.reconciling = exactCoverageCache_.reconciling;
        coverageDebug.movingWindow = exactCoverageCache_.lastMovingWindow;
        coverageDebug.trackedRadiusChunks = exactCoverageCache_.trackedRadiusChunks;
        coverageDebug.verticalRadius = exactCoverageCache_.verticalRadius;
        coverageDebug.coverageColumnsBudget = exactCoverageCache_.lastCoverageColumnsBudget;
        coverageDebug.columnsProcessedLastUpdate = exactCoverageCache_.batch.columnsProcessedLastUpdate;
        coverageDebug.pendingColumnsBeforeUpdate = exactCoverageCache_.lastPendingColumnsBeforeUpdate;
        coverageDebug.pendingColumnsAfterUpdate = exactCoverageCache_.lastPendingColumnsAfterUpdate;
        coverageDebug.queuedColumns = exactCoverageCache_.lastQueuedColumnCount;
        coverageDebug.dirtyColumns = exactCoverageCache_.lastDirtyColumnCount;
        coverageDebug.dirtyPages = exactCoverageCache_.lastDirtyPageCount;
        coverageDebug.dirtyRegions = exactCoverageCache_.lastDirtyRegionCount;
        coverageDebug.cachedColumns = exactCoverageCache_.columnSummaries.size();
        coverageDebug.smoothedFrameMs = exactCoverageCache_.lastSmoothedFrameMs;
    }

    std::vector<WaitingChunkDebugEntry> waitingEntries;
    {
        std::lock_guard<std::mutex> lock(deferredChunkDependencyMutex_);
        waitingEntries.reserve(deferredChunkDependencies_.size());
        for (const auto& [coord, deferred] : deferredChunkDependencies_)
        {
            WaitingChunkDebugEntry entry{};
            entry.coord = coord;
            entry.generationEpoch = deferred.generationEpoch;
            entry.initialReadyPriority = deferred.initialReadyPriority;
            entry.localInteractionPriority = deferred.localInteractionPriority;
            entry.outstandingDependencyCount = deferred.outstandingDependencyCount;
            entry.missingWorldgenPages.reserve(deferred.missingWorldgenPages.size());
            for (const glm::ivec2& pageKey : deferred.missingWorldgenPages)
            {
                entry.missingWorldgenPages.push_back(pageKey);
            }
            entry.missingStructureRegions.reserve(deferred.missingStructureRegions.size());
            for (const StructureRegionKey& regionKey : deferred.missingStructureRegions)
            {
                entry.missingStructureRegions.push_back(regionKey);
            }
            waitingEntries.push_back(std::move(entry));
        }
    }
    std::vector<ExactGpuQueuedDebugEntry> exactGpuQueuedEntries;
    {
        std::lock_guard<std::mutex> lock(const_cast<ChunkManager::Impl*>(this)->pendingExactGpuBuildMutex_);
        exactGpuQueuedEntries.reserve(pendingExactGpuBuildQueue_.size());
        for (const ExactGpuBuildRequest& request : pendingExactGpuBuildQueue_)
        {
            if (!request.chunk)
            {
                continue;
            }

            exactGpuQueuedEntries.push_back(ExactGpuQueuedDebugEntry{
                request.chunk->coord,
                request.buildVersion,
                request.generationEpoch,
                request.inputVersion,
                request.queuedTimestampMicros,
                request.rebuildVoxelInputs,
                request.prioritizeFront,
                shouldKeepLoadedChunkInteractive(*request.chunk, lastCenterChunk_),
                chunkAwaitingInitialVisibleReady(*request.chunk),
                chunkHasBlockEditOverlay(request.chunk->coord)});
        }
    }
    ExactGpuBatchPhaseSummary prepassSummary{};
    ExactGpuBatchPhaseSummary emitSummary{};
    ExactGpuBatchPhaseSummary prepassReadySummary{};
    std::vector<ExactGpuBatchDebugEntry> exactGpuBatchEntries;
    std::unordered_map<glm::ivec3, ExactGpuBatchOwnershipDebugInfo, ChunkHasher> exactGpuBatchOwnership;
    std::size_t exactGpuDirtyPageCount = 0u;
    std::string exactGpuPageSummary;
    std::vector<ExactGpuPageDebugEntry> exactGpuPageEntries;
    {
        std::lock_guard<std::mutex> lock(bufferPageMutex_);
        exactGpuDirtyPageCount = exactGpuDirtyPageIndices_.size();
        exactGpuPageSummary = summarizeChunkBufferPagesLocked();
        exactGpuPageEntries.reserve(16u);
        for (std::uint32_t pageIndex = 0; pageIndex < bufferPages_.size(); ++pageIndex)
        {
            const ChunkBufferPage& page = bufferPages_[pageIndex];
            if (page.usage != ChunkBufferPageUsage::ExactGpu ||
                (page.state == ChunkBufferPageState::Free &&
                 page.pendingChunks == 0u &&
                 page.residentChunks == 0u &&
                 page.recordActiveCount == 0u &&
                 page.exactPendingPublishCount == 0u))
            {
                continue;
            }

            std::uint64_t idleAgeMicros = 0u;
            if (page.lastReservationAt != SteadyClock::time_point{} &&
                SteadyClock::now() > page.lastReservationAt)
            {
                idleAgeMicros = static_cast<std::uint64_t>(
                    std::chrono::duration_cast<std::chrono::microseconds>(
                        SteadyClock::now() - page.lastReservationAt).count());
            }

            exactGpuPageEntries.push_back(ExactGpuPageDebugEntry{
                pageIndex,
                page.state,
                page.faceCursor,
                page.faceCapacity,
                page.recordCursor,
                page.recordCapacity,
                page.recordActiveCount,
                page.residentChunks,
                page.pendingChunks,
                page.liveResidentChunkCount,
                page.exactChunkMemberCount,
                page.exactPendingPublishCount,
                page.sealRequested,
                page.lastWriteFenceValue,
                page.retireFenceValue,
                idleAgeMicros});
        }
    }
    {
        std::lock_guard<std::mutex> lock(const_cast<ChunkManager::Impl*>(this)->pendingExactGpuBuildsMutex_);
        exactGpuBatchEntries.reserve(12u);
        exactGpuBatchOwnership.reserve(256u);
        for (const PendingExactGpuBatch& batch : pendingExactGpuBatches_)
        {
            ExactGpuBatchPhaseSummary* summary = nullptr;
            const char* phaseLabel = "unknown";
            switch (batch.phase)
            {
            case ExactGpuBatchPhase::PrepassSubmitted:
                summary = &prepassSummary;
                phaseLabel = "prepass_submitted";
                break;
            case ExactGpuBatchPhase::PrepassReadyForEmit:
                summary = &prepassReadySummary;
                phaseLabel = "prepass_ready";
                break;
            case ExactGpuBatchPhase::EmitSubmitted:
                summary = &emitSummary;
                phaseLabel = "emit_submitted";
                break;
            }
            if (summary != nullptr)
            {
                ++summary->batchCount;
                summary->buildCount += batch.builds.size();
                if (batch.phaseEnteredMicros > 0u && nowMicros > batch.phaseEnteredMicros)
                {
                    summary->oldestAgeMicros =
                        std::max(summary->oldestAgeMicros, nowMicros - batch.phaseEnteredMicros);
                }
            }

            for (const PendingExactGpuBuild& pending : batch.builds)
            {
                if (!pending.chunk)
                {
                    continue;
                }
                exactGpuBatchOwnership.insert_or_assign(pending.chunk->coord,
                                                        ExactGpuBatchOwnershipDebugInfo{
                                                            phaseLabel,
                                                            batch.phaseEnteredMicros});
                if (exactGpuBatchEntries.size() < 12u)
                {
                    exactGpuBatchEntries.push_back(ExactGpuBatchDebugEntry{
                        pending.chunk->coord,
                        phaseLabel,
                        pending.buildVersion,
                        pending.generationEpoch,
                        pending.inputVersion,
                        pending.requiredFaceCount,
                        pending.faceCapacity,
                        pending.pendingNeighborMask,
                        pending.hasAllocation(),
                        batch.phaseEnteredMicros});
                }
            }
        }
    }

    const auto phaseLabel = [](StreamingPhase phase) noexcept
    {
        switch (phase)
        {
        case StreamingPhase::SpawnResolve:
            return "spawn_resolve";
        case StreamingPhase::ExactPreload:
            return "exact_preload";
        case StreamingPhase::InteractiveNearOnly:
            return "interactive_near_only";
        case StreamingPhase::FarRamp:
            return "far_ramp";
        case StreamingPhase::SteadyState:
            return "steady_state";
        }
        return "unknown";
    };
    const auto worldgenStateLabel = [](WorldgenPageState state) noexcept
    {
        switch (state)
        {
        case WorldgenPageState::Unrequested:
            return "unrequested";
        case WorldgenPageState::Queued:
            return "queued";
        case WorldgenPageState::Building:
            return "building";
        case WorldgenPageState::Ready:
            return "ready";
        case WorldgenPageState::Failed:
            return "failed";
        }
        return "unknown";
    };
    const auto structureStateLabel = [](StructureRegionState state) noexcept
    {
        switch (state)
        {
        case StructureRegionState::Unrequested:
            return "unrequested";
        case StructureRegionState::WaitingOnWorldgenPages:
            return "waiting_pages";
        case StructureRegionState::Queued:
            return "queued";
        case StructureRegionState::Building:
            return "building";
        case StructureRegionState::Ready:
            return "ready";
        case StructureRegionState::Failed:
            return "failed";
        }
        return "unknown";
    };
    const auto frontierStateLabel = [](FrontierDemandState state) noexcept
    {
        switch (state)
        {
        case FrontierDemandState::Missing:
            return "missing";
        case FrontierDemandState::WaitingDependencies:
            return "deps";
        case FrontierDemandState::QueuedGenerate:
            return "qgen";
        case FrontierDemandState::Generating:
            return "gen";
        case FrontierDemandState::Meshing:
            return "mesh";
        case FrontierDemandState::Ready:
            return "ready";
        }
        return "unknown";
    };
    const auto formatChunkCoord = [](const glm::ivec3& coord)
    {
        std::ostringstream stream;
        stream << "(" << coord.x << "," << coord.y << "," << coord.z << ")";
        return stream.str();
    };
    const auto formatPageKey = [](const glm::ivec2& pageKey)
    {
        std::ostringstream stream;
        stream << "(" << pageKey.x << "," << pageKey.y << ")";
        return stream.str();
    };
    const auto formatRegionKey = [](const StructureRegionKey& key)
    {
        std::ostringstream stream;
        stream << "(" << key.regionX << "," << key.regionZ << ")";
        return stream.str();
    };
    const auto exactGpuBatchPhasePriority = [](const char* phase) noexcept
    {
        if (std::string_view(phase) == "prepass_ready")
        {
            return 0;
        }
        if (std::string_view(phase) == "emit_submitted")
        {
            return 1;
        }
        if (std::string_view(phase) == "prepass_submitted")
        {
            return 2;
        }
        return 3;
    };

    std::sort(exactGpuQueuedEntries.begin(),
              exactGpuQueuedEntries.end(),
              [](const ExactGpuQueuedDebugEntry& lhs, const ExactGpuQueuedDebugEntry& rhs)
              {
                  if (lhs.queuedMicros != rhs.queuedMicros)
                  {
                      if (lhs.queuedMicros == 0u)
                      {
                          return false;
                      }
                      if (rhs.queuedMicros == 0u)
                      {
                          return true;
                      }
                      return lhs.queuedMicros < rhs.queuedMicros;
                  }
                  if (lhs.buildVersion != rhs.buildVersion)
                  {
                      return lhs.buildVersion > rhs.buildVersion;
                  }
                  if (lhs.generationEpoch != rhs.generationEpoch)
                  {
                      return lhs.generationEpoch > rhs.generationEpoch;
                  }
                  if (lhs.coord.x != rhs.coord.x)
                  {
                      return lhs.coord.x < rhs.coord.x;
                  }
                  if (lhs.coord.y != rhs.coord.y)
                  {
                      return lhs.coord.y < rhs.coord.y;
                  }
                  return lhs.coord.z < rhs.coord.z;
              });
    std::sort(exactGpuBatchEntries.begin(),
              exactGpuBatchEntries.end(),
              [&exactGpuBatchPhasePriority](const ExactGpuBatchDebugEntry& lhs,
                                            const ExactGpuBatchDebugEntry& rhs)
              {
                  const int lhsPriority = exactGpuBatchPhasePriority(lhs.phase);
                  const int rhsPriority = exactGpuBatchPhasePriority(rhs.phase);
                  if (lhsPriority != rhsPriority)
                  {
                      return lhsPriority < rhsPriority;
                  }
                  if (lhs.requiredFaceCount != rhs.requiredFaceCount)
                  {
                      return lhs.requiredFaceCount > rhs.requiredFaceCount;
                  }
                  if (lhs.coord.x != rhs.coord.x)
                  {
                      return lhs.coord.x < rhs.coord.x;
                  }
                  if (lhs.coord.y != rhs.coord.y)
                  {
                      return lhs.coord.y < rhs.coord.y;
                  }
                  return lhs.coord.z < rhs.coord.z;
              });

    std::sort(waitingEntries.begin(),
              waitingEntries.end(),
              [center = lastCenterChunk_](const WaitingChunkDebugEntry& lhs, const WaitingChunkDebugEntry& rhs)
              {
                  if (lhs.outstandingDependencyCount != rhs.outstandingDependencyCount)
                  {
                      return lhs.outstandingDependencyCount > rhs.outstandingDependencyCount;
                  }
                  const int lhsDistance =
                      std::max(std::abs(lhs.coord.x - center.x), std::abs(lhs.coord.z - center.z));
                  const int rhsDistance =
                      std::max(std::abs(rhs.coord.x - center.x), std::abs(rhs.coord.z - center.z));
                  if (lhsDistance != rhsDistance)
                  {
                      return lhsDistance > rhsDistance;
                  }
                  if (lhs.coord.y != rhs.coord.y)
                  {
                      return lhs.coord.y < rhs.coord.y;
                  }
                  if (lhs.coord.x != rhs.coord.x)
                  {
                      return lhs.coord.x < rhs.coord.x;
                  }
                  return lhs.coord.z < rhs.coord.z;
              });

    std::vector<ExactGpuChunkDebugEntry> exactGpuChunkEntries;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        const std::uint64_t completedGpuFenceValue = exactGpuContext_.completedFenceValue();
        exactGpuChunkEntries.reserve(chunks_.size());
        for (const auto& [coord, chunk] : chunks_)
        {
            if (!chunk)
            {
                continue;
            }

            FrontierDemandState frontierState = FrontierDemandState::Missing;
            bool haveFrontierState = false;
            {
                std::lock_guard<std::mutex> frontierLock(streamingFrontierMutex_);
                auto it = streamingChunkLifecycleStates_.find(coord);
                if (it != streamingChunkLifecycleStates_.end())
                {
                    frontierState = it->second.state;
                    haveFrontierState = true;
                }
            }

            const bool exactQueued = chunk->exactGpuBuildQueued.load(std::memory_order_acquire);
            const bool exactInFlight = chunk->exactGpuBuildInFlight.load(std::memory_order_acquire);
            const bool inputsDirty = chunk->exactGpuInputsDirty.load(std::memory_order_acquire);
            const bool initialVisible = chunkAwaitingInitialVisibleReady(*chunk);
            const bool interesting =
                exactQueued ||
                exactInFlight ||
                inputsDirty ||
                (haveFrontierState && frontierState == FrontierDemandState::Meshing);
            if (!interesting)
            {
                continue;
            }

            const std::size_t overlayCount = chunkBlockEditOverlayCount(coord);

            std::size_t structureEditCount = 0u;
            {
                std::lock_guard<std::mutex> pendingStructureLock(pendingStructureMutex_);
                auto editsIt = pendingStructureEdits_.find(coord);
                if (editsIt != pendingStructureEdits_.end())
                {
                    structureEditCount = editsIt->second.size();
                }
            }

            std::uint64_t pageLastWriteFenceValue = 0u;
            const std::uint32_t pageIndex = chunk->bufferPageIndex.load(std::memory_order_acquire);
            if (pageIndex != kInvalidChunkBufferPage)
            {
                std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
                if (pageIndex < bufferPages_.size())
                {
                    pageLastWriteFenceValue = bufferPages_[pageIndex].lastWriteFenceValue;
                }
            }
            const std::uint64_t readyFenceValue = chunk->exactGpu.readyFenceValue;
            const auto ownershipIt = exactGpuBatchOwnership.find(coord);
            const ExactGpuBatchOwnershipDebugInfo ownership =
                ownershipIt != exactGpuBatchOwnership.end()
                    ? ownershipIt->second
                    : ExactGpuBatchOwnershipDebugInfo{};
            exactGpuChunkEntries.push_back(ExactGpuChunkDebugEntry{
                coord,
                frontierState,
                haveFrontierState,
                chunk->state.load(std::memory_order_acquire),
                chunk->inFlight.load(std::memory_order_acquire),
                chunk->hasBlocks.load(std::memory_order_acquire),
                chunk->meshReady.load(std::memory_order_acquire),
                chunk->exactGpuResident.load(std::memory_order_acquire),
                exactQueued,
                exactInFlight,
                inputsDirty,
                chunk->gpuExactSparseVoxelsReady,
                chunk->exactGpuHaloDirty.load(std::memory_order_acquire),
                overlayCount > 0u,
                structureEditCount > 0u,
                shouldKeepLoadedChunkInteractive(*chunk, lastCenterChunk_),
                initialVisible,
                chunk->generationEpoch.load(std::memory_order_acquire),
                chunk->exactGpuInputsVersion.load(std::memory_order_acquire),
                chunk->exactGpuRequestedInputVersion.load(std::memory_order_acquire),
                chunk->exactGpuReadyVersion.load(std::memory_order_acquire),
                chunk->exactGpuFaceCount.load(std::memory_order_acquire),
                chunk->exactGpuRecordIndex.load(std::memory_order_acquire),
                pageIndex,
                chunk->exactGpuPendingNeighborMask.load(std::memory_order_acquire),
                overlayCount,
                structureEditCount,
                chunk->requestTimestampMicros.load(std::memory_order_acquire),
                readyFenceValue,
                pageLastWriteFenceValue,
                chunk->exactGpuFenceDeferredCount.load(std::memory_order_acquire),
                chunk->exactGpuRequeueCount.load(std::memory_order_acquire),
                chunk->exactGpuLastFenceDeferredMicros.load(std::memory_order_acquire),
                chunk->exactGpuLastRequeueMicros.load(std::memory_order_acquire),
                readyFenceValue != 0u && completedGpuFenceValue < readyFenceValue,
                ownership.phase,
                ownership.phaseEnteredMicros});
        }
    }
    std::sort(exactGpuChunkEntries.begin(),
              exactGpuChunkEntries.end(),
              [center = lastCenterChunk_](const ExactGpuChunkDebugEntry& lhs,
                                          const ExactGpuChunkDebugEntry& rhs)
              {
                  if (lhs.localInteraction != rhs.localInteraction)
                  {
                      return lhs.localInteraction;
                  }
                  const bool lhsVisibleMeshing = lhs.haveFrontierState && lhs.frontierState == FrontierDemandState::Meshing;
                  const bool rhsVisibleMeshing = rhs.haveFrontierState && rhs.frontierState == FrontierDemandState::Meshing;
                  if (lhsVisibleMeshing != rhsVisibleMeshing)
                  {
                      return lhsVisibleMeshing;
                  }
                  if (lhs.exactInFlight != rhs.exactInFlight)
                  {
                      return lhs.exactInFlight;
                  }
                  if (lhs.exactQueued != rhs.exactQueued)
                  {
                      return lhs.exactQueued;
                  }
                  if (lhs.inputsDirty != rhs.inputsDirty)
                  {
                      return lhs.inputsDirty;
                  }
                  const int lhsDistance =
                      std::max(std::abs(lhs.coord.x - center.x), std::abs(lhs.coord.z - center.z));
                  const int rhsDistance =
                      std::max(std::abs(rhs.coord.x - center.x), std::abs(rhs.coord.z - center.z));
                  if (lhsDistance != rhsDistance)
                  {
                      return lhsDistance < rhsDistance;
                  }
                  if (lhs.coord.y != rhs.coord.y)
                  {
                      return lhs.coord.y < rhs.coord.y;
                  }
                  if (lhs.coord.x != rhs.coord.x)
                  {
                      return lhs.coord.x < rhs.coord.x;
                  }
                  return lhs.coord.z < rhs.coord.z;
              });
    const auto exactGpuPageStatePriority = [](ChunkBufferPageState state) noexcept
    {
        switch (state)
        {
        case ChunkBufferPageState::SealedPendingResident: return 0;
        case ChunkBufferPageState::OpenWritable: return 1;
        case ChunkBufferPageState::Retiring: return 2;
        case ChunkBufferPageState::ResidentImmutable: return 3;
        case ChunkBufferPageState::Free: return 4;
        }
        return 5;
    };
    std::sort(exactGpuPageEntries.begin(),
              exactGpuPageEntries.end(),
              [&exactGpuPageStatePriority](const ExactGpuPageDebugEntry& lhs,
                                           const ExactGpuPageDebugEntry& rhs)
              {
                  const std::size_t lhsPressure =
                      lhs.pendingChunks + lhs.liveResidentChunkCount + lhs.exactPendingPublishCount;
                  const std::size_t rhsPressure =
                      rhs.pendingChunks + rhs.liveResidentChunkCount + rhs.exactPendingPublishCount;
                  if (lhsPressure != rhsPressure)
                  {
                      return lhsPressure > rhsPressure;
                  }
                  const int lhsStatePriority = exactGpuPageStatePriority(lhs.state);
                  const int rhsStatePriority = exactGpuPageStatePriority(rhs.state);
                  if (lhsStatePriority != rhsStatePriority)
                  {
                      return lhsStatePriority < rhsStatePriority;
                  }
                  if (lhs.faceCursor != rhs.faceCursor)
                  {
                      return lhs.faceCursor > rhs.faceCursor;
                  }
                  if (lhs.recordCursor != rhs.recordCursor)
                  {
                      return lhs.recordCursor > rhs.recordCursor;
                  }
                  return lhs.pageIndex < rhs.pageIndex;
              });
    std::vector<ExactGpuChunkDebugEntry> exactGpuHotChunkEntries = exactGpuChunkEntries;
    std::sort(exactGpuHotChunkEntries.begin(),
              exactGpuHotChunkEntries.end(),
              [center = lastCenterChunk_](const ExactGpuChunkDebugEntry& lhs,
                                          const ExactGpuChunkDebugEntry& rhs)
              {
                  if (lhs.blockedByReadyFence != rhs.blockedByReadyFence)
                  {
                      return lhs.blockedByReadyFence;
                  }
                  if (lhs.requeueCount != rhs.requeueCount)
                  {
                      return lhs.requeueCount > rhs.requeueCount;
                  }
                  if (lhs.fenceDeferredCount != rhs.fenceDeferredCount)
                  {
                      return lhs.fenceDeferredCount > rhs.fenceDeferredCount;
                  }
                  if (lhs.inputsDirty != rhs.inputsDirty)
                  {
                      return lhs.inputsDirty;
                  }
                  const int lhsDistance =
                      std::max(std::abs(lhs.coord.x - center.x), std::abs(lhs.coord.z - center.z));
                  const int rhsDistance =
                      std::max(std::abs(rhs.coord.x - center.x), std::abs(rhs.coord.z - center.z));
                  if (lhsDistance != rhsDistance)
                  {
                      return lhsDistance < rhsDistance;
                  }
                  if (lhs.coord.y != rhs.coord.y)
                  {
                      return lhs.coord.y < rhs.coord.y;
                  }
                  if (lhs.coord.x != rhs.coord.x)
                  {
                      return lhs.coord.x < rhs.coord.x;
                  }
                  return lhs.coord.z < rhs.coord.z;
              });

    struct ExactGpuQueueSummary
    {
        std::size_t total{0u};
        std::size_t frontPriority{0u};
        std::size_t localInteraction{0u};
        std::size_t initialVisible{0u};
        std::size_t overlay{0u};
        std::size_t background{0u};
        std::size_t rebuildInputs{0u};
        std::size_t belowCamera{0u};
        std::size_t cameraBand{0u};
        std::size_t aboveCamera{0u};
    };
    struct ExactGpuPendingSummary
    {
        std::size_t total{0u};
        std::size_t queued{0u};
        std::size_t inFlight{0u};
        std::size_t dirtyInputs{0u};
        std::size_t residentStale{0u};
        std::size_t localInteraction{0u};
        std::size_t initialVisible{0u};
        std::size_t overlay{0u};
        std::size_t background{0u};
        std::size_t frontierMeshing{0u};
        std::size_t noBlocks{0u};
        std::size_t belowCamera{0u};
        std::size_t cameraBand{0u};
        std::size_t aboveCamera{0u};
    };
    const auto accumulateVerticalBand = [centerY = lastCenterChunk_.y](auto& summary, int chunkY)
    {
        if (chunkY < centerY - 1)
        {
            ++summary.belowCamera;
        }
        else if (chunkY > centerY + 1)
        {
            ++summary.aboveCamera;
        }
        else
        {
            ++summary.cameraBand;
        }
    };

    ExactGpuQueueSummary exactGpuQueueSummary{};
    for (const ExactGpuQueuedDebugEntry& entry : exactGpuQueuedEntries)
    {
        ++exactGpuQueueSummary.total;
        if (entry.prioritizeFront)
        {
            ++exactGpuQueueSummary.frontPriority;
        }
        if (entry.localInteraction)
        {
            ++exactGpuQueueSummary.localInteraction;
        }
        if (entry.initialVisible)
        {
            ++exactGpuQueueSummary.initialVisible;
        }
        if (entry.hasOverlay)
        {
            ++exactGpuQueueSummary.overlay;
        }
        if (!entry.localInteraction && !entry.initialVisible && !entry.hasOverlay)
        {
            ++exactGpuQueueSummary.background;
        }
        if (entry.rebuildVoxelInputs)
        {
            ++exactGpuQueueSummary.rebuildInputs;
        }
        accumulateVerticalBand(exactGpuQueueSummary, entry.coord.y);
    }

    ExactGpuPendingSummary exactGpuPendingSummary{};
    for (const ExactGpuChunkDebugEntry& entry : exactGpuChunkEntries)
    {
        ++exactGpuPendingSummary.total;
        if (entry.exactQueued)
        {
            ++exactGpuPendingSummary.queued;
        }
        if (entry.exactInFlight)
        {
            ++exactGpuPendingSummary.inFlight;
        }
        if (entry.inputsDirty)
        {
            ++exactGpuPendingSummary.dirtyInputs;
        }
        if (entry.exactResident && (entry.inputsDirty || entry.readyVersion != entry.inputVersion))
        {
            ++exactGpuPendingSummary.residentStale;
        }
        if (entry.localInteraction)
        {
            ++exactGpuPendingSummary.localInteraction;
        }
        if (entry.initialVisible)
        {
            ++exactGpuPendingSummary.initialVisible;
        }
        if (entry.hasOverlay)
        {
            ++exactGpuPendingSummary.overlay;
        }
        if (!entry.localInteraction && !entry.initialVisible && !entry.hasOverlay)
        {
            ++exactGpuPendingSummary.background;
        }
        if (entry.haveFrontierState && entry.frontierState == FrontierDemandState::Meshing)
        {
            ++exactGpuPendingSummary.frontierMeshing;
        }
        if (!entry.hasBlocks)
        {
            ++exactGpuPendingSummary.noBlocks;
        }
        accumulateVerticalBand(exactGpuPendingSummary, entry.coord.y);
    }
    std::size_t exactGpuFenceBlockedCount = 0u;
    std::size_t exactGpuRequeuedChunkCount = 0u;
    std::size_t exactGpuDeferredChunkCount = 0u;
    std::size_t exactGpuSparseNotReadyCount = 0u;
    std::size_t exactGpuPendingNeighborCount = 0u;
    for (const ExactGpuChunkDebugEntry& entry : exactGpuChunkEntries)
    {
        if (entry.blockedByReadyFence)
        {
            ++exactGpuFenceBlockedCount;
        }
        if (entry.requeueCount > 0u)
        {
            ++exactGpuRequeuedChunkCount;
        }
        if (entry.fenceDeferredCount > 0u)
        {
            ++exactGpuDeferredChunkCount;
        }
        if ((entry.exactQueued || entry.exactInFlight || entry.inputsDirty) && !entry.sparseReady)
        {
            ++exactGpuSparseNotReadyCount;
        }
        if (entry.pendingNeighborMask != 0u)
        {
            ++exactGpuPendingNeighborCount;
        }
    }

    const auto exactGpuResourceFailureCount = [&](ExactGpuResourceFailureReason reason) -> int
    {
        return exactGpuResourceFailureCounts_[static_cast<std::size_t>(reason)].load(std::memory_order_relaxed);
    };
    const int exactGpuResPrepare =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepareChunkResources);
    const int exactGpuResPrepassPageUpload =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepassPageUploadAlloc);
    const int exactGpuResPrepassDescriptorUpload =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepassDescriptorUploadAlloc);
    const int exactGpuResPrepassSkyLightUpload =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepassSkyLightUploadAlloc);
    const int exactGpuResPrepassVoxelUpload =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepassVoxelUploadAlloc);
    const int exactGpuResPrepassSparseUpload =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepassSparseUploadAlloc);
    const int exactGpuResPrepassAllocationRecordSync =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepassAllocationRecordSync);
    const int exactGpuResPrepassDescriptorBind =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepassDescriptorBind);
    const int exactGpuResPrepassRecordUpload =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::PrepassRecordUploadAlloc);
    const int exactGpuResEmitReservation =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::EmitReservation);
    const int exactGpuResEmitOverflowCounterUpload =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::EmitOverflowCounterUploadAlloc);
    const int exactGpuResEmitMetadataSync =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::EmitMetadataSync);
    const int exactGpuResEmitDescriptorBind =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::EmitDescriptorBind);
    const int exactGpuResEmitAllocationRecordSync =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::EmitAllocationRecordSync);
    const int exactGpuResEmitBuildIndexUpload =
        exactGpuResourceFailureCount(ExactGpuResourceFailureReason::EmitBuildIndexUploadAlloc);
    const int exactGpuResourceFailureTotal =
        exactGpuResPrepare +
        exactGpuResPrepassPageUpload +
        exactGpuResPrepassDescriptorUpload +
        exactGpuResPrepassSkyLightUpload +
        exactGpuResPrepassVoxelUpload +
        exactGpuResPrepassSparseUpload +
        exactGpuResPrepassAllocationRecordSync +
        exactGpuResPrepassDescriptorBind +
        exactGpuResPrepassRecordUpload +
        exactGpuResEmitReservation +
        exactGpuResEmitOverflowCounterUpload +
        exactGpuResEmitMetadataSync +
        exactGpuResEmitDescriptorBind +
        exactGpuResEmitAllocationRecordSync +
        exactGpuResEmitBuildIndexUpload;

    ExactGpuReservationFailureDebugInfo exactGpuReservationFailureInfo{};
    {
        std::lock_guard<std::mutex> lock(exactGpuReservationFailureDebugMutex_);
        exactGpuReservationFailureInfo = lastExactGpuReservationFailure_;
    }
    for (char& ch : exactGpuReservationFailureInfo.exceptionText)
    {
        if (ch == '\r' || ch == '\n')
        {
            ch = ' ';
        }
    }
    const std::uint64_t logNowMicros = steadyMicrosNow();

    std::ostringstream stream;
    stream << "exact_dep_stall_debug"
           << " phase=" << phaseLabel(snapshot.phase)
           << " stall_ms=" << (readyPlateauMicros / 1000u)
           << " ready=" << snapshot.exactReadyChunks << "/" << snapshot.exactRequiredChunks;
    if (snapshot.exactRequiredChunksApproximate)
    {
        stream << "~";
    }
    stream << " deps=" << snapshot.exactWaitingDependenciesChunks
           << " qgen=" << snapshot.exactQueuedGenerateChunks
           << " gen=" << snapshot.exactGeneratingChunks
           << " mesh=" << snapshot.exactMeshingChunks
           << " pending_uploads=" << snapshot.exactPendingUploads
           << " tracked_radius=" << snapshot.exactTrackedRadiusChunks
           << " dep_candidate=" << (dependencyCandidate ? 1 : 0)
           << " gpu_candidate=" << (exactGpuCandidate ? 1 : 0)
           << " blocking=" << (snapshot.blockingReason ? snapshot.blockingReason : "unknown")
           << " deferred_entries=" << waitingEntries.size()
           << " exact_gpu_completed_fence=" << exactGpuContext_.completedFenceValue()
           << " exact_gpu_queue=" << exactGpuQueuedEntries.size()
           << " exact_gpu_dirty_pages=" << exactGpuDirtyPageCount
           << " exact_gpu_temp_exhaust=" << exactGpuReservationTempExhaustions_.load(std::memory_order_relaxed)
           << " exact_gpu_emit_meta_fail=" << exactGpuEmitMetadataSyncFailures_.load(std::memory_order_relaxed)
           << " exact_gpu_alloc_record_fail=" << exactGpuAllocationRecordSyncFailures_.load(std::memory_order_relaxed)
           << " exact_gpu_rb_fail=" << exactGpuBuildReadbackFailures_.load(std::memory_order_relaxed)
           << " exact_gpu_resource_fail=" << exactGpuResourceFailureTotal
           << " exact_gpu_overflow=" << exactGpuBuildOverflows_.load(std::memory_order_relaxed)
           << " exact_gpu_stale_cancel=" << exactGpuBuildStaleCancels_.load(std::memory_order_relaxed)
           << " exact_gpu_submit_budget_rejects=" << exactGpuSubmitBudgetRejects_.load(std::memory_order_relaxed)
           << " exact_gpu_submitted=" << exactGpuBuildsSubmitted_.load(std::memory_order_relaxed)
           << " exact_gpu_committed=" << exactGpuBuildsCommitted_.load(std::memory_order_relaxed)
           << " exact_gpu_prepass_batches=" << prepassSummary.batchCount
           << "/" << prepassSummary.buildCount
           << "@" << (prepassSummary.oldestAgeMicros / 1000u)
           << " exact_gpu_prepass_ready_batches=" << prepassReadySummary.batchCount
           << "/" << prepassReadySummary.buildCount
           << "@" << (prepassReadySummary.oldestAgeMicros / 1000u)
           << " exact_gpu_emit_batches=" << emitSummary.batchCount
           << "/" << emitSummary.buildCount
           << "@" << (emitSummary.oldestAgeMicros / 1000u)
           << " exact_gpu_chunk_samples=" << exactGpuChunkEntries.size()
           << "\n  exact_coverage frame_ms=" << std::fixed << std::setprecision(2) << coverageDebug.smoothedFrameMs
           << " moving_window=" << (coverageDebug.movingWindow ? 1 : 0)
           << " authoritative=" << (coverageDebug.authoritativeCountsValid ? 1 : 0)
           << " reconciling=" << (coverageDebug.reconciling ? 1 : 0)
           << " tracked_radius=" << coverageDebug.trackedRadiusChunks
           << " vertical_radius=" << coverageDebug.verticalRadius
           << " budget=" << coverageDebug.coverageColumnsBudget
           << " processed=" << coverageDebug.columnsProcessedLastUpdate
           << " pending_before=" << coverageDebug.pendingColumnsBeforeUpdate
           << " pending_after=" << coverageDebug.pendingColumnsAfterUpdate
           << " queued=" << coverageDebug.queuedColumns
           << " dirty_columns=" << coverageDebug.dirtyColumns
           << " dirty_pages=" << coverageDebug.dirtyPages
           << " dirty_regions=" << coverageDebug.dirtyRegions
           << " cached_columns=" << coverageDebug.cachedColumns
           << "\n  exact_gpu_queue_summary total=" << exactGpuQueueSummary.total
           << " front=" << exactGpuQueueSummary.frontPriority
           << " local=" << exactGpuQueueSummary.localInteraction
           << " initial=" << exactGpuQueueSummary.initialVisible
           << " overlay=" << exactGpuQueueSummary.overlay
           << " background=" << exactGpuQueueSummary.background
           << " rebuild_inputs=" << exactGpuQueueSummary.rebuildInputs
           << " below_camera=" << exactGpuQueueSummary.belowCamera
           << " camera_band=" << exactGpuQueueSummary.cameraBand
           << " above_camera=" << exactGpuQueueSummary.aboveCamera
           << "\n  exact_gpu_pending_summary total=" << exactGpuPendingSummary.total
           << " queued=" << exactGpuPendingSummary.queued
           << " inflight=" << exactGpuPendingSummary.inFlight
           << " dirty=" << exactGpuPendingSummary.dirtyInputs
           << " resident_stale=" << exactGpuPendingSummary.residentStale
           << " local=" << exactGpuPendingSummary.localInteraction
           << " initial=" << exactGpuPendingSummary.initialVisible
           << " overlay=" << exactGpuPendingSummary.overlay
           << " background=" << exactGpuPendingSummary.background
           << " frontier_mesh=" << exactGpuPendingSummary.frontierMeshing
           << " no_blocks=" << exactGpuPendingSummary.noBlocks
           << " below_camera=" << exactGpuPendingSummary.belowCamera
           << " camera_band=" << exactGpuPendingSummary.cameraBand
           << " above_camera=" << exactGpuPendingSummary.aboveCamera
           << "\n  exact_gpu_stall_signals fence_blocked=" << exactGpuFenceBlockedCount
           << " requeued_chunks=" << exactGpuRequeuedChunkCount
           << " deferred_chunks=" << exactGpuDeferredChunkCount
           << " sparse_not_ready=" << exactGpuSparseNotReadyCount
           << " pending_neighbors=" << exactGpuPendingNeighborCount
           << "\n  exact_gpu_resource_summary prepare=" << exactGpuResPrepare
           << " prepass_page_up=" << exactGpuResPrepassPageUpload
           << " prepass_desc_up=" << exactGpuResPrepassDescriptorUpload
           << " prepass_sky_up=" << exactGpuResPrepassSkyLightUpload
           << " prepass_sparse_up=" << exactGpuResPrepassSparseUpload
           << " prepass_record_sync=" << exactGpuResPrepassAllocationRecordSync
           << " prepass_desc_bind=" << exactGpuResPrepassDescriptorBind
           << " prepass_record_up=" << exactGpuResPrepassRecordUpload
           << " emit_reserve=" << exactGpuResEmitReservation
           << " emit_overflow_up=" << exactGpuResEmitOverflowCounterUpload
           << " emit_meta_sync=" << exactGpuResEmitMetadataSync
           << " emit_desc_bind=" << exactGpuResEmitDescriptorBind
           << " emit_record_sync=" << exactGpuResEmitAllocationRecordSync
           << " emit_index_up=" << exactGpuResEmitBuildIndexUpload;
    if (exactGpuReservationFailureInfo.timestampMicros != 0u)
    {
        const std::uint64_t failureAgeMs =
            exactGpuReservationFailureInfo.timestampMicros < logNowMicros
                ? ((logNowMicros - exactGpuReservationFailureInfo.timestampMicros) / 1000u)
                : 0u;
        stream << "\n  exact_gpu_last_reserve_fail age_ms=" << failureAgeMs
               << " requested_faces=" << exactGpuReservationFailureInfo.requestedFaceCount
               << " page_face_cap=" << exactGpuReservationFailureInfo.pageFaceCapacity
               << " page_record_cap=" << exactGpuReservationFailureInfo.pageRecordCapacity
               << " freeExactGpuPageCount=" << exactGpuReservationFailureInfo.freeExactGpuPageCount
               << " exact_open_writable=" << exactGpuReservationFailureInfo.exactOpenWritablePages
               << " exact_sealed_pending_resident=" << exactGpuReservationFailureInfo.exactSealedPendingResidentPages
               << " exact_resident_immutable=" << exactGpuReservationFailureInfo.exactResidentImmutablePages
               << " exact_free=" << exactGpuReservationFailureInfo.exactFreePages;
        if (!exactGpuReservationFailureInfo.exceptionText.empty())
        {
            stream << " exception=\"" << exactGpuReservationFailureInfo.exceptionText << "\"";
        }
    }
    stream << "\n  exact_gpu_pages " << exactGpuPageSummary;
    const std::size_t exactGpuPageLimit = std::min<std::size_t>(exactGpuPageEntries.size(), 8u);
    for (std::size_t index = 0; index < exactGpuPageLimit; ++index)
    {
        const ExactGpuPageDebugEntry& entry = exactGpuPageEntries[index];
        stream << "\n  exact_gpu_page page=" << entry.pageIndex
               << " state=" << chunkBufferPageStateLabel(entry.state)
               << " faces=" << entry.faceCursor << "/" << entry.faceCapacity
               << " records=" << entry.recordCursor << "/" << entry.recordCapacity
               << " active_records=" << entry.recordActiveCount
               << " resident_chunks=" << entry.residentChunks
               << " pending_chunks=" << entry.pendingChunks
               << " live_resident=" << entry.liveResidentChunkCount
               << " members=" << entry.exactChunkMemberCount
               << " pending_publish=" << entry.exactPendingPublishCount
               << " seal_requested=" << (entry.sealRequested ? 1 : 0)
               << " last_write_fence=" << entry.lastWriteFenceValue
               << " retire_fence=" << entry.retireFenceValue
               << " idle_ms=" << (entry.idleAgeMicros / 1000u);
    }

    const std::size_t queuedLimit = std::min<std::size_t>(exactGpuQueuedEntries.size(), 10u);
    for (std::size_t index = 0; index < queuedLimit; ++index)
    {
        const ExactGpuQueuedDebugEntry& entry = exactGpuQueuedEntries[index];
        const std::uint64_t ageMicros =
            (entry.queuedMicros > 0u && logNowMicros > entry.queuedMicros) ? (logNowMicros - entry.queuedMicros) : 0u;
        stream << "\n  exact_gpu_queue chunk=" << formatChunkCoord(entry.coord)
               << " age_ms=" << (ageMicros / 1000u)
               << " build_ver=" << entry.buildVersion
               << " gen_epoch=" << entry.generationEpoch
               << " input_ver=" << entry.inputVersion
               << " rebuild_inputs=" << (entry.rebuildVoxelInputs ? 1 : 0)
               << " priority=" << (entry.prioritizeFront ? "front" : "back")
               << " local=" << (entry.localInteraction ? 1 : 0)
               << " initial=" << (entry.initialVisible ? 1 : 0)
               << " overlay=" << (entry.hasOverlay ? 1 : 0);
    }

    const std::size_t batchLimit = std::min<std::size_t>(exactGpuBatchEntries.size(), 10u);
    for (std::size_t index = 0; index < batchLimit; ++index)
    {
        const ExactGpuBatchDebugEntry& entry = exactGpuBatchEntries[index];
        stream << "\n  exact_gpu_batch phase=" << entry.phase
               << " chunk=" << formatChunkCoord(entry.coord)
               << " phase_age_ms="
               << ((entry.phaseEnteredMicros > 0u && logNowMicros > entry.phaseEnteredMicros)
                       ? ((logNowMicros - entry.phaseEnteredMicros) / 1000u)
                       : 0u)
               << " build_ver=" << entry.buildVersion
               << " gen_epoch=" << entry.generationEpoch
               << " input_ver=" << entry.inputVersion
               << " req_faces=" << entry.requiredFaceCount
               << " face_cap=" << entry.faceCapacity
               << " pending_neighbors=" << static_cast<int>(entry.pendingNeighborMask)
               << " allocation=" << (entry.hasAllocation ? 1 : 0);
    }

    const std::size_t exactGpuChunkLimit = std::min<std::size_t>(exactGpuChunkEntries.size(), 12u);
    for (std::size_t index = 0; index < exactGpuChunkLimit; ++index)
    {
        const ExactGpuChunkDebugEntry& entry = exactGpuChunkEntries[index];
        stream << "\n  exact_gpu_chunk chunk=" << formatChunkCoord(entry.coord)
               << " frontier=" << (entry.haveFrontierState ? frontierStateLabel(entry.frontierState) : "none")
               << " chunk_state=" << chunkStateLabel(entry.chunkState)
               << " inflight=" << entry.inFlight
               << " local=" << (entry.localInteraction ? 1 : 0)
               << " initial=" << (entry.initialVisible ? 1 : 0)
               << " has_blocks=" << (entry.hasBlocks ? 1 : 0)
               << " mesh_ready=" << (entry.meshReady ? 1 : 0)
               << " resident=" << (entry.exactResident ? 1 : 0)
               << " queued=" << (entry.exactQueued ? 1 : 0)
               << " gpu_inflight=" << (entry.exactInFlight ? 1 : 0)
               << " inputs_dirty=" << (entry.inputsDirty ? 1 : 0)
               << " sparse_ready=" << (entry.sparseReady ? 1 : 0)
               << " halo_dirty=" << (entry.haloDirty ? 1 : 0)
               << " has_overlay=" << (entry.hasOverlay ? 1 : 0)
               << " overlay_count=" << entry.overlayCount
               << " pending_structure=" << (entry.pendingStructureEdits ? 1 : 0)
               << " structure_count=" << entry.structureEditCount
               << " gen_epoch=" << entry.generationEpoch
               << " input_ver=" << entry.inputVersion
               << " requested_ver=" << entry.requestedInputVersion
               << " ready_ver=" << entry.readyVersion
               << " face_count=" << entry.faceCount
               << " record=" << entry.recordIndex
               << " page=" << entry.pageIndex
               << " pending_neighbors=" << static_cast<int>(entry.pendingNeighborMask)
               << " ready_fence=" << entry.readyFenceValue
               << " page_last_write_fence=" << entry.pageLastWriteFenceValue
               << " blocked_by_ready_fence=" << (entry.blockedByReadyFence ? 1 : 0)
               << " defer_count=" << entry.fenceDeferredCount
               << " requeue_count=" << entry.requeueCount
               << " batch_phase=" << entry.batchPhase
               << " batch_age_ms="
               << ((entry.batchPhaseEnteredMicros > 0u && logNowMicros > entry.batchPhaseEnteredMicros)
                       ? ((logNowMicros - entry.batchPhaseEnteredMicros) / 1000u)
                       : 0u)
               << " last_defer_ms="
               << ((entry.lastFenceDeferredMicros > 0 &&
                    static_cast<std::uint64_t>(entry.lastFenceDeferredMicros) < logNowMicros)
                       ? ((logNowMicros - static_cast<std::uint64_t>(entry.lastFenceDeferredMicros)) / 1000u)
                       : 0u)
               << " last_requeue_ms="
               << ((entry.lastRequeueMicros > 0 &&
                    static_cast<std::uint64_t>(entry.lastRequeueMicros) < logNowMicros)
                       ? ((logNowMicros - static_cast<std::uint64_t>(entry.lastRequeueMicros)) / 1000u)
                       : 0u)
               << " req_age_ms="
               << ((entry.requestTimestampMicros > 0 && static_cast<std::uint64_t>(entry.requestTimestampMicros) < logNowMicros)
                       ? ((logNowMicros - static_cast<std::uint64_t>(entry.requestTimestampMicros)) / 1000u)
                       : 0u);
    }
    const std::size_t exactGpuHotChunkLimit = std::min<std::size_t>(exactGpuHotChunkEntries.size(), 6u);
    for (std::size_t index = 0; index < exactGpuHotChunkLimit; ++index)
    {
        const ExactGpuChunkDebugEntry& entry = exactGpuHotChunkEntries[index];
        if (!entry.blockedByReadyFence &&
            entry.requeueCount == 0u &&
            entry.fenceDeferredCount == 0u &&
            !entry.inputsDirty)
        {
            break;
        }

        stream << "\n  exact_gpu_hot_chunk chunk=" << formatChunkCoord(entry.coord)
               << " blocked_by_ready_fence=" << (entry.blockedByReadyFence ? 1 : 0)
               << " requeue_count=" << entry.requeueCount
               << " defer_count=" << entry.fenceDeferredCount
               << " inputs_dirty=" << (entry.inputsDirty ? 1 : 0)
               << " sparse_ready=" << (entry.sparseReady ? 1 : 0)
               << " pending_neighbors=" << static_cast<int>(entry.pendingNeighborMask)
               << " ready_fence=" << entry.readyFenceValue
               << " page_last_write_fence=" << entry.pageLastWriteFenceValue
               << " batch_phase=" << entry.batchPhase
               << " req_age_ms="
               << ((entry.requestTimestampMicros > 0 && static_cast<std::uint64_t>(entry.requestTimestampMicros) < logNowMicros)
                       ? ((logNowMicros - static_cast<std::uint64_t>(entry.requestTimestampMicros)) / 1000u)
                       : 0u);
    }

    const std::size_t entryLimit = std::min<std::size_t>(waitingEntries.size(), 12u);
    for (std::size_t index = 0; index < entryLimit; ++index)
    {
        const WaitingChunkDebugEntry& entry = waitingEntries[index];
        FrontierDemandState frontierState = FrontierDemandState::Missing;
        bool haveFrontierState = false;
        {
            std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
            auto it = streamingChunkLifecycleStates_.find(entry.coord);
            if (it != streamingChunkLifecycleStates_.end())
            {
                frontierState = it->second.state;
                haveFrontierState = true;
            }
        }

        std::shared_ptr<Chunk> chunk;
        {
            std::lock_guard<std::mutex> lock(chunksMutex);
            auto it = chunks_.find(entry.coord);
            if (it != chunks_.end())
            {
                chunk = it->second;
            }
        }

        stream << "\n  chunk=" << formatChunkCoord(entry.coord)
               << " frontier=" << (haveFrontierState ? frontierStateLabel(frontierState) : "none")
               << " dep_outstanding=" << entry.outstandingDependencyCount
               << " dep_pages=" << entry.missingWorldgenPages.size()
               << " dep_regions=" << entry.missingStructureRegions.size()
               << " dep_gen_epoch=" << entry.generationEpoch
               << " initial=" << (entry.initialReadyPriority ? 1 : 0)
               << " local=" << (entry.localInteractionPriority ? 1 : 0);
        if (chunk)
        {
            stream << " chunk_present=1"
                   << " chunk_state=" << chunkStateLabel(chunk->state.load(std::memory_order_acquire))
                   << " chunk_inflight=" << chunk->inFlight.load(std::memory_order_acquire)
                   << " chunk_gen_epoch=" << chunk->generationEpoch.load(std::memory_order_acquire)
                   << " has_blocks=" << (chunk->hasBlocks.load(std::memory_order_acquire) ? 1 : 0)
                   << " mesh_ready=" << (chunk->meshReady.load(std::memory_order_acquire) ? 1 : 0);
        }
        else
        {
            stream << " chunk_present=0";
        }

        for (const glm::ivec2& pageKey : entry.missingWorldgenPages)
        {
            WorldgenPageState state = WorldgenPageState::Unrequested;
            bool dependencyQueued = false;
            bool buildOccupancy = false;
            bool warmStructures = false;
            bool pagePresent = false;
            {
                std::lock_guard<std::mutex> lock(worldgenPageMutex_);
                auto it = worldgenPageEntries_.find(pageKey);
                if (it != worldgenPageEntries_.end())
                {
                    state = it->second.state;
                    dependencyQueued = it->second.dependencyJobQueued;
                    buildOccupancy = it->second.buildOccupancy;
                    warmStructures = it->second.warmStructures;
                    pagePresent = static_cast<bool>(it->second.page);
                }
            }

            stream << "\n    page=" << formatPageKey(pageKey)
                   << " state=" << worldgenStateLabel(state)
                   << " queued=" << (dependencyQueued ? 1 : 0)
                   << " build_occupancy=" << (buildOccupancy ? 1 : 0)
                   << " warm_structures=" << (warmStructures ? 1 : 0)
                   << " page_present=" << (pagePresent ? 1 : 0);
        }

        for (const StructureRegionKey& regionKey : entry.missingStructureRegions)
        {
            StructureRegionState state = StructureRegionState::Unrequested;
            bool dependencyQueued = false;
            std::size_t missingPageCount = 0;
            bool regionPresent = false;
            std::vector<glm::ivec2> regionMissingPages;
            {
                std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
                auto it = structureRegionEntries_.find(regionKey);
                if (it != structureRegionEntries_.end())
                {
                    state = it->second.state;
                    dependencyQueued = it->second.dependencyJobQueued;
                    missingPageCount = it->second.missingWorldgenPages.size();
                    regionPresent = static_cast<bool>(it->second.region);
                    regionMissingPages.reserve(it->second.missingWorldgenPages.size());
                    for (const glm::ivec2& pageKey : it->second.missingWorldgenPages)
                    {
                        regionMissingPages.push_back(pageKey);
                    }
                }
            }

            stream << "\n    region=" << formatRegionKey(regionKey)
                   << " state=" << structureStateLabel(state)
                   << " queued=" << (dependencyQueued ? 1 : 0)
                   << " missing_pages=" << missingPageCount
                   << " region_present=" << (regionPresent ? 1 : 0);

            for (const glm::ivec2& pageKey : regionMissingPages)
            {
                WorldgenPageState pageState = WorldgenPageState::Unrequested;
                bool pageDependencyQueued = false;
                bool buildOccupancy = false;
                bool warmStructures = false;
                bool pagePresent = false;
                {
                    std::lock_guard<std::mutex> lock(worldgenPageMutex_);
                    auto it = worldgenPageEntries_.find(pageKey);
                    if (it != worldgenPageEntries_.end())
                    {
                        pageState = it->second.state;
                        pageDependencyQueued = it->second.dependencyJobQueued;
                        buildOccupancy = it->second.buildOccupancy;
                        warmStructures = it->second.warmStructures;
                        pagePresent = static_cast<bool>(it->second.page);
                    }
                }

                stream << "\n      region_page=" << formatPageKey(pageKey)
                       << " state=" << worldgenStateLabel(pageState)
                       << " queued=" << (pageDependencyQueued ? 1 : 0)
                       << " build_occupancy=" << (buildOccupancy ? 1 : 0)
                       << " warm_structures=" << (warmStructures ? 1 : 0)
                       << " page_present=" << (pagePresent ? 1 : 0)
                       << " outstanding=" << (worldgenPageDependencyHasOutstandingWork(pageKey) ? 1 : 0);
            }
        }
    }

    exactDependencyStallDebugLog(stream.str());
}

LodDiagnosticsSnapshot ChunkManager::Impl::lodDiagnosticsSnapshot(const glm::vec3& cameraPos) const
{
    return farTerrainManager_.diagnosticsSnapshot(cameraPos);
}

void ChunkManager::Impl::writeLodDebugSnapshot(const std::filesystem::path& outputPath,
                                               const glm::vec3& cameraPos) const
{
    farTerrainManager_.writeDebugSnapshot(outputPath, cameraPos);
}

ChunkProfilingSnapshot ChunkManager::Impl::sampleProfilingSnapshot()
{
    ChunkProfilingSnapshot snapshot{};
    const StreamingStatusSnapshot status = computeStreamingStatusSnapshot();
    snapshot.phase = status.phase;

    const int generated = profilingCounters_.generatedChunks.exchange(0, std::memory_order_relaxed);
    const int relit = profilingCounters_.relitChunks.exchange(0, std::memory_order_relaxed);
    const int relightBatches = profilingCounters_.relightBatches.exchange(0, std::memory_order_relaxed);
    const int meshed = profilingCounters_.meshedChunks.exchange(0, std::memory_order_relaxed);
    const int uploaded = profilingCounters_.uploadedChunks.exchange(0, std::memory_order_relaxed);
    const std::uint64_t relightRegionChunks =
        profilingCounters_.relightRegionChunks.exchange(0, std::memory_order_relaxed);
    const std::uint64_t relightChangedChunks =
        profilingCounters_.relightChangedChunks.exchange(0, std::memory_order_relaxed);
    const std::uint64_t relightExternalSnapshotChunks =
        profilingCounters_.relightExternalSnapshotChunks.exchange(0, std::memory_order_relaxed);
    const std::uint64_t relightSkyAboveChunkScans =
        profilingCounters_.relightSkyAboveChunkScans.exchange(0, std::memory_order_relaxed);
    const std::uint64_t relightSkySeedNodes =
        profilingCounters_.relightSkySeedNodes.exchange(0, std::memory_order_relaxed);
    const std::uint64_t relightBlockSeedNodes =
        profilingCounters_.relightBlockSeedNodes.exchange(0, std::memory_order_relaxed);
    const std::uint64_t relightSkyNodesProcessed =
        profilingCounters_.relightSkyNodesProcessed.exchange(0, std::memory_order_relaxed);
    const std::uint64_t relightBlockNodesProcessed =
        profilingCounters_.relightBlockNodesProcessed.exchange(0, std::memory_order_relaxed);

    snapshot.generatedChunks = generated;
    snapshot.relitChunks = relit;
    snapshot.relightBatches = relightBatches;
    snapshot.meshedChunks = meshed;
    snapshot.uploadedChunks = uploaded;
    snapshot.uploadedBytes = profilingCounters_.uploadedBytes.exchange(0, std::memory_order_relaxed);
    snapshot.relightRegionChunks = relightRegionChunks;
    snapshot.relightChangedChunks = relightChangedChunks;
    snapshot.relightExternalSnapshotChunks = relightExternalSnapshotChunks;
    snapshot.relightSkyAboveChunkScans = relightSkyAboveChunkScans;
    snapshot.relightSkySeedNodes = relightSkySeedNodes;
    snapshot.relightBlockSeedNodes = relightBlockSeedNodes;
    snapshot.relightSkyNodesProcessed = relightSkyNodesProcessed;
    snapshot.relightBlockNodesProcessed = relightBlockNodesProcessed;
    snapshot.throttledUploads = profilingCounters_.throttledUploads.exchange(0, std::memory_order_relaxed);
    snapshot.deferredUploads = profilingCounters_.deferredUploads.exchange(0, std::memory_order_relaxed);
    snapshot.uploadAttemptsLastFrame = uploadAttemptsLastFrame_;
    snapshot.uploadQueueScanEntriesLastFrame = uploadQueueScanEntriesLastFrame_;
    snapshot.uploadSkippedExpiredLastFrame = uploadSkippedExpiredLastFrame_;
    snapshot.uploadSkippedNotReadyLastFrame = uploadSkippedNotReadyLastFrame_;
    snapshot.uploadSkippedPendingMeshLastFrame = uploadSkippedPendingMeshLastFrame_;
    snapshot.uploadColumnLimitedLastFrame = uploadColumnLimitedLastFrame_;
    snapshot.uploadBudgetDeferredLastFrame = uploadBudgetDeferredLastFrame_;
    snapshot.uploadRetryFailuresLastFrame = uploadRetryFailuresLastFrame_;
    snapshot.uploadScanLimitHitsLastFrame = uploadScanLimitHitsLastFrame_;
    snapshot.uploadBeginFailuresLastFrame = uploadBeginFailuresLastFrame_;
    snapshot.uploadStalePendingMeshesLastFrame = uploadStalePendingMeshesLastFrame_;
    snapshot.evictedChunks = profilingCounters_.evictedChunks.exchange(0, std::memory_order_relaxed);
    snapshot.verticalRadius = lastVerticalRadius_;
    snapshot.verticalRadiusDelta = lastVerticalRadiusDelta_;
    snapshot.generationBudget = lastGenerationBudget_;
    snapshot.generationJobsIssued = lastGenerationJobsIssued_;
    snapshot.ringExpansionBudget = lastRingBudget_;
    snapshot.ringExpansionsUsed = lastRingExpansionsUsed_;
    snapshot.missingChunks = lastMissingChunks_;
    snapshot.generationBacklogSteps = lastBacklogSteps_;
    snapshot.generationColumnCap =
        (lastColumnCap_ >= std::numeric_limits<int>::max()) ? -1 : std::max(lastColumnCap_, 0);
    snapshot.workerThreads = static_cast<int>(workerThreadCount_);

    const long long genMicros = profilingCounters_.generationMicros.exchange(0, std::memory_order_relaxed);
    const long long relightMicros = profilingCounters_.relightMicros.exchange(0, std::memory_order_relaxed);
    const long long meshMicros = profilingCounters_.meshingMicros.exchange(0, std::memory_order_relaxed);

    if (generated > 0)
    {
        snapshot.averageGenerationMs = static_cast<double>(genMicros) /
                                       (1000.0 * static_cast<double>(generated));
    }
    if (meshed > 0)
    {
        snapshot.averageMeshingMs = static_cast<double>(meshMicros) /
                                    (1000.0 * static_cast<double>(meshed));
    }
    if (relit > 0)
    {
        snapshot.averageRelightMs = static_cast<double>(relightMicros) /
                                    (1000.0 * static_cast<double>(relit));
    }

    snapshot.uploadBudgetBytes = uploadBudgetBytesThisFrame_;
    snapshot.uploadedBytesLastFrame = lastUploadBytesUsed_;
    snapshot.uploadColumnLimit = uploadColumnLimitThisFrame_;
    snapshot.updateMsLastFrame = updateMsLastFrame_;
    snapshot.updateResidualMsLastFrame = updateResidualMsLastFrame_;
    snapshot.denseResidencyMsLastFrame = denseResidencyMsLastFrame_;
    snapshot.verticalRadiusMsLastFrame = verticalRadiusMsLastFrame_;
    snapshot.priorityUpdateMsLastFrame = priorityUpdateMsLastFrame_;
    snapshot.movementEnvelopeMsLastFrame = movementEnvelopeMsLastFrame_;
    snapshot.queuedSkyLightColumnRefreshMsLastFrame = queuedSkyLightColumnRefreshMsLastFrame_;
    snapshot.pendingLocalEditBatchesMsLastFrame = pendingLocalEditBatchesMsLastFrame_;
    snapshot.dedicatedLocalUploadMsLastFrame = dedicatedLocalUploadMsLastFrame_;
    snapshot.queuedRelightRequestsMsLastFrame = queuedRelightRequestsMsLastFrame_;
    snapshot.farTerrainInvalidationMsLastFrame = farTerrainInvalidationMsLastFrame_;
    snapshot.worldgenWindowPinMsLastFrame = worldgenWindowPinMsLastFrame_;
    snapshot.worldgenPrefetchMsLastFrame = worldgenPrefetchMsLastFrame_;
    snapshot.fullRadiusWorldgenDiscoveryMsLastFrame = fullRadiusWorldgenDiscoveryMsLastFrame_;
    snapshot.worldgenDependencyRefillMsLastFrame = worldgenDependencyRefillMsLastFrame_;
    snapshot.bulkShellOracleRefillMsLastFrame = bulkShellOracleRefillMsLastFrame_;
    snapshot.uploadBudgetMsLastFrame = uploadBudgetPrepMsLastFrame_;
    snapshot.missingScanMsLastFrame = missingScanMsLastFrame_;
    snapshot.ensureVolumeMsLastFrame = ensureVolumeMsLastFrame_;
    snapshot.ensureVolumeColumnPrepMsLastFrame = ensureVolumeColumnPrepMsLastFrame_;
    snapshot.ensureVolumeSortMsLastFrame = ensureVolumeSortMsLastFrame_;
    snapshot.ensureVolumeDispatchMsLastFrame = ensureVolumeDispatchMsLastFrame_;
    snapshot.ensureVolumeChunkLookupMsLastFrame = ensureVolumeChunkLookupMsLastFrame_;
    snapshot.ensureVolumeEnqueueMsLastFrame = ensureVolumeEnqueueMsLastFrame_;
    snapshot.schedulingMsLastFrame = schedulingMsLastFrame_;
    snapshot.evictionMsLastFrame = evictionMsLastFrame_;
    snapshot.relightMsLastFrame = relightMsLastFrame_;
    snapshot.uploadMsLastFrame = lastUploadMsUsed_;
    snapshot.uploadQueueAgeMsLastFrame = uploadQueueAgeMsLastFrame_;
    snapshot.uploadQueuePickMsLastFrame = uploadQueuePickMsLastFrame_;
    snapshot.poolTrimMsLastFrame = poolTrimMsLastFrame_;
    snapshot.farTerrainUpdateMsLastFrame = farTerrainUpdateMsLastFrame_;
    snapshot.columnHeightLookupMsLastFrame = columnHeightLookupMsLastFrame_;
    snapshot.columnHeightSampleMsLastFrame = columnHeightSampleMsLastFrame_;
    snapshot.uploadPrepareMsLastFrame = uploadPrepareMsLastFrame_;
    snapshot.uploadContextBeginMsLastFrame = uploadContextBeginMsLastFrame_;
    snapshot.uploadFinalizeMsLastFrame = uploadFinalizeMsLastFrame_;
    snapshot.commitCollectMsLastFrame = commitCollectMsLastFrame_;
    snapshot.commitChunkScanMsLastFrame = commitChunkScanMsLastFrame_;
    snapshot.commitMeshLockWaitMsLastFrame = commitMeshLockWaitMsLastFrame_;
    snapshot.commitMeshLockedMsLastFrame = commitMeshLockedMsLastFrame_;
    snapshot.commitMeshStateMsLastFrame = commitMeshStateMsLastFrame_;
    snapshot.commitPageStateMsLastFrame = commitPageStateMsLastFrame_;
    snapshot.commitReleaseMsLastFrame = commitReleaseMsLastFrame_;
    snapshot.startupStateMsLastFrame = startupStateMsLastFrame_;
    snapshot.benchmarkBookkeepingMsLastFrame = benchmarkBookkeepingMsLastFrame_;
    const std::size_t pendingUploads = pendingUploadsLastFrame_;
    snapshot.pendingUploadChunks = static_cast<int>(
        std::min<std::size_t>(pendingUploads, static_cast<std::size_t>(std::numeric_limits<int>::max())));
    snapshot.jobQueueDepth = static_cast<int>(std::min<std::size_t>(
        jobQueue_.size(),
        static_cast<std::size_t>(std::numeric_limits<int>::max())));
    snapshot.uploadQueueDepth = static_cast<int>(std::min<std::size_t>(
        estimateUploadQueueSize(),
        static_cast<std::size_t>(std::numeric_limits<int>::max())));
    {
        std::lock_guard<std::mutex> lock(columnHeightPrefetchMutex_);
        snapshot.columnPrefetchQueueDepth = static_cast<int>(std::min<std::size_t>(
            pendingWorldgenPageDependencyQueue_.size(),
            static_cast<std::size_t>(std::numeric_limits<int>::max())));
    }
    snapshot.ensureVolumeColumnsVisitedLastFrame = ensureVolumeColumnsVisitedLastFrame_;
    snapshot.ensureVolumeCandidatesBuiltLastFrame = ensureVolumeCandidatesBuiltLastFrame_;
    snapshot.ensureVolumeExistingChunkSkipsLastFrame = ensureVolumeExistingChunkSkipsLastFrame_;
    snapshot.ensureVolumeColumnCapSkipsLastFrame = ensureVolumeColumnCapSkipsLastFrame_;
    {
        std::lock_guard<std::mutex> lock(chunkPoolMutex_);
        snapshot.pooledChunkCount = chunkPool_.size();
        snapshot.pooledChunkBytes = chunkPoolBytes_;
        snapshot.pooledChunkBudgetBytes = chunkPoolBudgetBytes_;
    }
    snapshot.exactGpuBuildReadbackFailures =
        exactGpuBuildReadbackFailures_.exchange(0, std::memory_order_relaxed);
    snapshot.exactGpuBuildResourceFailures =
        exactGpuBuildResourceFailures_.exchange(0, std::memory_order_relaxed);
    snapshot.exactGpuBuildOverflows =
        exactGpuBuildOverflows_.exchange(0, std::memory_order_relaxed);
    snapshot.exactGpuBuildStaleCancels =
        exactGpuBuildStaleCancels_.exchange(0, std::memory_order_relaxed);
    snapshot.exactGpuBuildsSubmitted =
        exactGpuBuildsSubmitted_.load(std::memory_order_relaxed);
    snapshot.exactGpuBuildsCommitted =
        exactGpuBuildsCommitted_.load(std::memory_order_relaxed);
    snapshot.exactGpuMeshReplacements =
        exactGpuMeshReplacements_.load(std::memory_order_relaxed);
    {
        std::lock_guard<std::mutex> statsLock(exactGpuStatsMutex_);
        snapshot.exactGpuSynthMs = lastExactGpuPassTimings_.synthMs;
        snapshot.exactGpuStampMs = lastExactGpuPassTimings_.stampMs;
        snapshot.exactGpuLightMs = lastExactGpuPassTimings_.lightMs;
        snapshot.exactGpuFaceCountMs = lastExactGpuPassTimings_.faceCountMs;
        snapshot.exactGpuFacePrefixMs = lastExactGpuPassTimings_.facePrefixMs;
        snapshot.exactGpuAllocateMs = lastExactGpuPassTimings_.allocateMs;
        snapshot.exactGpuFaceEmitMs = lastExactGpuPassTimings_.faceEmitMs;
        snapshot.exactGpuTotalMs = lastExactGpuPassTimings_.totalMs;
    }
    {
        std::lock_guard<std::mutex> queueLock(pendingExactGpuBuildMutex_);
        snapshot.exactGpuQueuedBuilds = static_cast<int>(std::min<std::size_t>(
            pendingExactGpuBuildQueue_.size(),
            static_cast<std::size_t>(std::numeric_limits<int>::max())));
    }
    {
        std::lock_guard<std::mutex> pendingLock(pendingExactGpuBuildsMutex_);
        std::size_t pendingBuildCount = 0u;
        for (const PendingExactGpuBatch& batch : pendingExactGpuBatches_)
        {
            pendingBuildCount += batch.builds.size();
        }
        snapshot.exactGpuPendingBuilds = static_cast<int>(std::min<std::size_t>(
            pendingBuildCount,
            static_cast<std::size_t>(std::numeric_limits<int>::max())));
    }
    {
        std::lock_guard<std::mutex> lock(bufferPageMutex_);
        for (const ChunkBufferPage& page : bufferPages_)
        {
            if (page.usage != ChunkBufferPageUsage::ExactGpu)
            {
                continue;
            }

            ++snapshot.exactGpuPageCount;
            snapshot.exactGpuPageBytes +=
                page.faceCapacity * 32u +
                page.recordCapacity * sizeof(ExactChunkRenderBatch::GpuCullRecord) +
                page.recordCapacity * sizeof(FarLodGpuContext::ExactDrawRecordMetadata);
        }
    }
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        for (const auto& [coord, chunk] : chunks_)
        {
            (void)coord;
            if (!chunk)
            {
                continue;
            }

            if (chunk->exactGpu.columnBuffer != nullptr)
            {
                snapshot.exactGpuColumnBytes +=
                    static_cast<std::size_t>(kExactChunkColumnCount) * sizeof(GpuExactColumnDescriptor);
            }
            snapshot.exactGpuSparseVoxelBytes +=
                static_cast<std::size_t>(chunk->exactGpu.sparseVoxelCapacity) * sizeof(GpuExactSparseVoxel);
            if (chunk->exactGpu.voxelBuffer != nullptr)
            {
                snapshot.exactGpuVoxelBytes +=
                    static_cast<std::size_t>(kChunkSizeX * kChunkSizeY * kChunkSizeZ) * sizeof(std::uint32_t);
            }
            if (chunk->exactGpu.lightScratchBuffer != nullptr)
            {
                snapshot.exactGpuLightScratchBytes +=
                    static_cast<std::size_t>(kChunkSizeX * kChunkSizeY * kChunkSizeZ) * sizeof(std::uint32_t);
            }
            if (chunk->exactGpu.seamBuffer != nullptr)
            {
                snapshot.exactGpuPageBytes +=
                    static_cast<std::size_t>(kExactChunkHaloVoxelCount) * sizeof(std::uint32_t);
            }
        }
    }
    snapshot.exactGpuScratchBytes = exactGpuContext_.exactScratchSizeBytes();
    snapshot.exactGpuUploadScratchBytes = exactGpuContext_.uploadScratchSizeBytes();
    snapshot.exactGpuReadbackBytes = exactGpuContext_.readbackScratchSizeBytes();
    snapshot.exactGpuTotalBytes =
        snapshot.exactGpuPageBytes +
        snapshot.exactGpuColumnBytes +
        snapshot.exactGpuSparseVoxelBytes +
        snapshot.exactGpuVoxelBytes +
        snapshot.exactGpuLightScratchBytes +
        snapshot.exactGpuScratchBytes +
        snapshot.exactGpuUploadScratchBytes +
        snapshot.exactGpuReadbackBytes;
    snapshot.farBuildMsAverage = farTerrainManager_.averageBuildMs();
    snapshot.lodGpuSynthesisMs = farTerrainManager_.averageGpuSynthesisMs();
    snapshot.lodGpuStampMs = farTerrainManager_.averageGpuStampMs();
    snapshot.lodGpuFaceBuildMs = farTerrainManager_.averageGpuFaceBuildMs();
    snapshot.farCollectMsLastFrame = farTerrainManager_.lastCollectMs();
    snapshot.farUploadMsLastFrame = farTerrainManager_.lastUploadMs();
    snapshot.farActiveTiles = farTerrainManager_.activeTileCount();
    snapshot.farDirtyTiles = farTerrainManager_.dirtyTileCount();
    snapshot.farShellTilesReady = farTerrainManager_.readyTileCount();
    snapshot.farTilesBuilt = farTerrainManager_.builtTilesLastUpdate();
    snapshot.farTilesQueued = farTerrainManager_.queuedTileCount();
    snapshot.farTilesPendingUpload = farTerrainManager_.pendingUploadTileCount();
    if (dxgiAdapter_ != nullptr)
    {
        DXGI_QUERY_VIDEO_MEMORY_INFO localInfo{};
        if (SUCCEEDED(dxgiAdapter_->QueryVideoMemoryInfo(0,
                                                         DXGI_MEMORY_SEGMENT_GROUP_LOCAL,
                                                         &localInfo)))
        {
            snapshot.gpuLocalUsageBytes = static_cast<std::size_t>(localInfo.CurrentUsage);
            snapshot.gpuLocalBudgetBytes = static_cast<std::size_t>(localInfo.Budget);
            snapshot.gpuLocalAvailableForReservationBytes =
                static_cast<std::size_t>(localInfo.AvailableForReservation);
        }

        DXGI_QUERY_VIDEO_MEMORY_INFO nonLocalInfo{};
        if (SUCCEEDED(dxgiAdapter_->QueryVideoMemoryInfo(0,
                                                         DXGI_MEMORY_SEGMENT_GROUP_NON_LOCAL,
                                                         &nonLocalInfo)))
        {
            snapshot.gpuNonLocalUsageBytes = static_cast<std::size_t>(nonLocalInfo.CurrentUsage);
            snapshot.gpuNonLocalBudgetBytes = static_cast<std::size_t>(nonLocalInfo.Budget);
        }
    }
    const StructureRegistryProfilingSnapshot structureSnapshot = structureRegistry_.profilingSnapshot();
    snapshot.structureQueryMs = structureSnapshot.averageQueryMs;
    snapshot.structureCacheHitRate = structureSnapshot.cacheHitRate;
    snapshot.structureRegionsBuilt = structureSnapshot.regionsBuilt;
    snapshot.exactChunksReady = status.exactReadyChunks;
    snapshot.exactChunksPending = std::max(status.exactRequiredChunks - status.exactReadyChunks, 0);
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        for (const auto& [coord, chunk] : chunks_)
        {
            (void)coord;
            if (!chunk)
            {
                continue;
            }

            switch (chunk->residencyMode.load(std::memory_order_acquire))
            {
            case ExactChunkResidencyMode::CpuAuthoritative:
                ++snapshot.exactCpuAuthoritativeChunks;
                break;
            case ExactChunkResidencyMode::GpuResidentNonlocal:
                ++snapshot.exactGpuResidentNonlocalChunks;
                break;
            case ExactChunkResidencyMode::CpuMaterializing:
                ++snapshot.exactCpuMaterializingChunks;
                break;
            case ExactChunkResidencyMode::GpuPendingRetire:
                ++snapshot.exactGpuPendingRetireChunks;
                break;
            }
        }
    }

    return snapshot;
}

void ChunkManager::Impl::setBenchmarkMetricsEnabled(bool enabled) noexcept
{
    benchmarkMetrics_.setEnabled(enabled);
    if (climateMap_)
    {
        climateMap_->setProfilingEnabled(enabled);
    }
    if (surfaceMap_)
    {
        surfaceMap_->setProfilingEnabled(enabled);
    }
    structureRegistry_.setProfilingEnabled(enabled);
}

bool ChunkManager::Impl::benchmarkMetricsEnabled() const noexcept
{
    return benchmarkMetrics_.isEnabled();
}

void ChunkManager::Impl::resetBenchmarkMetrics()
{
    benchmarkMetrics_.reset();
    exactGpuBuildsSubmitted_.store(0, std::memory_order_relaxed);
    exactGpuBuildsCommitted_.store(0, std::memory_order_relaxed);
    exactGpuMeshReplacements_.store(0, std::memory_order_relaxed);
    {
        std::lock_guard<std::mutex> statsLock(exactGpuStatsMutex_);
        lastExactGpuPassTimings_ = {};
    }
    if (climateMap_)
    {
        climateMap_->resetProfiling();
    }
    if (surfaceMap_)
    {
        surfaceMap_->resetProfiling();
    }
    structureRegistry_.resetProfiling();
}

ChunkBenchmarkReport ChunkManager::Impl::benchmarkReport() const
{
    ChunkBenchmarkReport report = benchmarkMetrics_.snapshot();

    if (climateMap_)
    {
        const terrain::ClimateMap::CacheProfilingSnapshot climate = climateMap_->profilingSnapshot();
        report.climateCache.hits = climate.hits;
        report.climateCache.misses = climate.misses;
        report.climateCache.fills = climate.fills;
        const std::uint64_t total = climate.hits + climate.misses;
        if (total > 0)
        {
            report.climateCache.hitRate = static_cast<double>(climate.hits) / static_cast<double>(total);
        }
    }

    if (surfaceMap_)
    {
        const terrain::SurfaceMap::CacheProfilingSnapshot surface = surfaceMap_->profilingSnapshot();
        report.surfaceCache.hits = surface.hits;
        report.surfaceCache.misses = surface.misses;
        report.surfaceCache.fills = surface.fills;
        const std::uint64_t total = surface.hits + surface.misses;
        if (total > 0)
        {
            report.surfaceCache.hitRate = static_cast<double>(surface.hits) / static_cast<double>(total);
        }
    }

    const StructureRegistryProfilingSnapshot structureSnapshot = structureRegistry_.profilingSnapshot();
    report.structureCache.hits = structureSnapshot.cacheHits;
    report.structureCache.misses = structureSnapshot.cacheMisses;
    report.structureCache.fills = structureSnapshot.regionsBuilt;
    report.structureCache.hitRate = structureSnapshot.cacheHitRate;
    report.structureRegionsBuilt = structureSnapshot.regionsBuilt;

    return report;
}

std::string ChunkManager::Impl::biomeNameAt(const glm::vec3& worldPos) const
{
    const int worldX = static_cast<int>(std::floor(worldPos.x));
    const int worldZ = static_cast<int>(std::floor(worldPos.z));
    ColumnSample sample{};
    if (!trySampleColumnOrRequest(sample,
                                  worldX,
                                  worldZ,
                                  std::numeric_limits<int>::min(),
                                  std::numeric_limits<int>::max(),
                                  false,
                                  DependencyPriority::Visible,
                                  JobServiceClass::Standard))
    {
        return "Unknown";
    }
    if (sample.dominantBiome)
    {
        return sample.dominantBiome->name;
    }

    return "Unknown";
}

void ChunkManager::Impl::startWorkerThreads()
{
    shouldStop_.store(false, std::memory_order_release);

    unsigned concurrency = std::thread::hardware_concurrency();
    if (concurrency == 0)
    {
        concurrency = 2;
    }

    const bool exactOnly = renderSettings_.totalChunks <= renderSettings_.exactChunks;
    unsigned desired = 1u;
    if (exactOnly && concurrency >= 16)
    {
        desired = 12u;
    }
    else if (exactOnly && concurrency >= 12)
    {
        desired = 10u;
    }
    else if (exactOnly && concurrency >= 8)
    {
        desired = 8u;
    }
    else if (concurrency >= 16)
    {
        desired = 8u;
    }
    else if (concurrency >= 12)
    {
        desired = 6u;
    }
    else if (concurrency >= 8)
    {
        desired = 5u;
    }
    else if (concurrency >= 6)
    {
        desired = 4u;
    }
    else
    {
        desired = std::max(1u, concurrency > 1 ? concurrency - 1 : 1u);
    }

    if (kVerticalStreamingConfig.maxWorkerThreads > 0)
    {
        desired = std::min(desired, static_cast<unsigned>(kVerticalStreamingConfig.maxWorkerThreads));
    }

    workerThreadCount_ = static_cast<std::size_t>(desired);
    jobQueue_.setWorkerConcurrency(workerThreadCount_);
    workerThreads_.reserve(workerThreadCount_);

    for (std::size_t i = 0; i < workerThreadCount_; ++i)
    {
        workerThreads_.emplace_back(&ChunkManager::Impl::workerThreadFunction, this);
    }

    unsigned prefetchDesired = 1u;
    if (exactOnly)
    {
        prefetchDesired = (workerThreadCount_ >= 12) ? 4u : ((workerThreadCount_ >= 8) ? 3u : 2u);
    }
    else
    {
        prefetchDesired = (workerThreadCount_ >= 6) ? 1u : 0u;
    }

    columnHeightPrefetchWorkerCount_ = static_cast<std::size_t>(prefetchDesired);
    bulkShellOracleWorkerCount_ = exactOnly
        ? ((workerThreadCount_ >= 10) ? 2u : ((workerThreadCount_ >= 8) ? 1u : 0u))
        : 0u;
    refillWorldgenPageDependencyJobs();
    refillBulkShellOracleJobs();
}

void ChunkManager::Impl::startBulkShellOracle(const glm::ivec3& center, int horizontalRadius)
{
    stopBulkShellOracle();

    if (horizontalRadius <= 0 || shouldStop_.load(std::memory_order_acquire) || !surfaceMap_)
    {
        return;
    }

    auto batch = std::make_shared<BulkShellOracleBatch>();
    batch->minChunk = {center.x - horizontalRadius, center.z - horizontalRadius};
    batch->maxChunk = {center.x + horizontalRadius, center.z + horizontalRadius};

    const int minWorldX = batch->minChunk.x * kChunkSizeX;
    const int maxWorldX = (batch->maxChunk.x + 1) * kChunkSizeX - 1;
    const int minWorldZ = batch->minChunk.y * kChunkSizeZ;
    const int maxWorldZ = (batch->maxChunk.y + 1) * kChunkSizeZ - 1;

    const int fragmentSize = terrain::SurfaceFragment::kSize;
    const glm::ivec2 centerFragment{floorDiv(center.x * kChunkSizeX, fragmentSize),
                                    floorDiv(center.z * kChunkSizeZ, fragmentSize)};
    const int minFragmentX = floorDiv(minWorldX, fragmentSize);
    const int maxFragmentX = floorDiv(maxWorldX, fragmentSize);
    const int minFragmentZ = floorDiv(minWorldZ, fragmentSize);
    const int maxFragmentZ = floorDiv(maxWorldZ, fragmentSize);

    batch->fragmentCoords.reserve(static_cast<std::size_t>(maxFragmentX - minFragmentX + 1) *
                                  static_cast<std::size_t>(maxFragmentZ - minFragmentZ + 1));
    for (int fx = minFragmentX; fx <= maxFragmentX; ++fx)
    {
        for (int fz = minFragmentZ; fz <= maxFragmentZ; ++fz)
        {
            batch->fragmentCoords.push_back({fx, fz});
        }
    }

    std::sort(batch->fragmentCoords.begin(),
              batch->fragmentCoords.end(),
              [&centerFragment](const glm::ivec2& lhs, const glm::ivec2& rhs)
              {
                  const int lhsDistance = std::max(std::abs(lhs.x - centerFragment.x),
                                                   std::abs(lhs.y - centerFragment.y));
                  const int rhsDistance = std::max(std::abs(rhs.x - centerFragment.x),
                                                   std::abs(rhs.y - centerFragment.y));
                  if (lhsDistance != rhsDistance)
                  {
                      return lhsDistance < rhsDistance;
                  }
                  if (lhs.x != rhs.x)
                  {
                      return lhs.x < rhs.x;
                  }
                  return lhs.y < rhs.y;
              });

    batch->remainingFragments.store(batch->fragmentCoords.size(), std::memory_order_release);
    bulkShellOracleBatch_ = batch;
    refillBulkShellOracleJobs();
}

void ChunkManager::Impl::stopBulkShellOracle()
{
    if (bulkShellOracleBatch_)
    {
        bulkShellOracleBatch_->nextFragmentIndex.store(bulkShellOracleBatch_->fragmentCoords.size(),
                                                       std::memory_order_release);
    }
    bulkShellOracleBatch_.reset();
}

void ChunkManager::Impl::stopExactPlanBuild()
{
    if (exactPlanBuildThread_.joinable())
    {
        exactPlanBuildThread_.join();
    }

    std::lock_guard<std::mutex> lock(exactPlanMutex_);
    pendingExactPlan_.reset();
    pendingExactPlanKeyValid_ = false;
    pendingExactPlanStatus_ = ExactWindowPlanStatus::Idle;
    activeWindowReplanNeeded_ = false;
    dirtyPlanColumns_.clear();
    dirtyPlanPages_.clear();
    dirtyPlanRegions_.clear();
    activeWindowReplanReason_.clear();
    exactCoverageCache_ = ExactCoverageCacheState{};
}

void ChunkManager::Impl::stopWorkerThreads()
{
    shouldStop_.store(true, std::memory_order_release);
    stopBulkShellOracle();
    {
        std::lock_guard<std::mutex> lock(columnHeightPrefetchMutex_);
        pendingWorldgenPageDependencyQueue_ = {};
        nextWorldgenPageDependencyToken_ = 1;
        nextWorldgenPageDependencySequence_ = 1;
    }
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        structureRegionEntries_.clear();
        pendingStructureRegionDependencyQueue_ = {};
        worldgenPageStructureRegionWaiters_.clear();
        nextStructureRegionDependencyToken_ = 1;
        nextStructureRegionDependencySequence_ = 1;
    }
    {
        std::lock_guard<std::mutex> lock(deferredChunkDependencyMutex_);
        deferredChunkDependencies_.clear();
        worldgenPageWaiters_.clear();
        structureRegionWaiters_.clear();
    }
    std::vector<Job> cancelledJobs = jobQueue_.stop();
    for (const Job& job : cancelledJobs)
    {
        if (job.chunk)
        {
            job.chunk->inFlight.fetch_sub(1, std::memory_order_relaxed);
        }
    }

    for (auto& thread : workerThreads_)
    {
        if (thread.joinable())
        {
            thread.join();
        }
    }
    workerThreads_.clear();
    workerThreadCount_ = 0;
    columnHeightPrefetchWorkerCount_ = 0;
    bulkShellOracleWorkerCount_ = 0;
}

void ChunkManager::Impl::startExactGpuWorkerThread()
{
    if (exactGpuWorkerThread_.joinable() ||
        shouldStop_.load(std::memory_order_acquire) ||
        device_ == nullptr ||
        !exactGpuContext_.ready())
    {
        return;
    }

    exactGpuWorkerStopRequested_.store(false, std::memory_order_release);
    exactGpuWorkerThread_ = std::thread(&ChunkManager::Impl::exactGpuWorkerThreadFunction, this);
}

void ChunkManager::Impl::stopExactGpuWorkerThread()
{
    exactGpuWorkerStopRequested_.store(true, std::memory_order_release);
    wakeExactGpuWorker();
    if (exactGpuWorkerThread_.joinable())
    {
        exactGpuWorkerThread_.join();
    }
    cancelPendingExactGpuBuildsForShutdown();
}

void ChunkManager::Impl::cancelPendingExactGpuBuildsForShutdown()
{
    if (exactGpuContext_.ready())
    {
        exactGpuContext_.waitForIdle();
    }

    std::vector<PendingExactGpuBuild> pendingBuilds;
    {
        std::lock_guard<std::mutex> lock(pendingExactGpuBuildsMutex_);
        for (PendingExactGpuBatch& batch : pendingExactGpuBatches_)
        {
            if (batch.prepassResources.submissionSlot != std::numeric_limits<std::uint32_t>::max())
            {
                exactGpuContext_.releaseSubmissionSlot(batch.prepassResources.submissionSlot);
            }
            if (batch.emitResources.submissionSlot != std::numeric_limits<std::uint32_t>::max())
            {
                exactGpuContext_.releaseSubmissionSlot(batch.emitResources.submissionSlot);
            }
            for (PendingExactGpuBuild& build : batch.builds)
            {
                freeExactGpuScratchSlices_.push_back(build.scratchSliceIndex);
                pendingBuilds.push_back(std::move(build));
            }
        }
        pendingExactGpuBatches_.clear();
    }

    for (PendingExactGpuBuild& pending : pendingBuilds)
    {
        releasePendingExactBuildAllocation(pending, true);

        if (!pending.chunk)
        {
            continue;
        }

        pending.chunk->exactGpuBuildQueued.store(false, std::memory_order_release);
        pending.chunk->exactGpuBuildInFlight.store(false, std::memory_order_release);
        pending.chunk->exactGpuPendingNeighborMask.store(0, std::memory_order_release);
        pending.chunk->exactGpu.reset();
        clearPendingExactGpuBuildCount(*pending.chunk);
        pending.chunk->inFlight.fetch_sub(1, std::memory_order_relaxed);
    }

    std::deque<ExactGpuBuildRequest> queuedBuilds;
    {
        std::lock_guard<std::mutex> lock(pendingExactGpuBuildMutex_);
        queuedBuilds.swap(pendingExactGpuBuildQueue_);
    }

    for (ExactGpuBuildRequest& request : queuedBuilds)
    {
        if (!request.chunk)
        {
            continue;
        }

        const bool wasQueued = request.chunk->exactGpuBuildQueued.exchange(false, std::memory_order_acq_rel);
        request.chunk->exactGpuBuildInFlight.store(false, std::memory_order_release);
        refreshPendingExactGpuBuildCount(*request.chunk);
        if (wasQueued)
        {
            request.chunk->inFlight.fetch_sub(1, std::memory_order_relaxed);
        }
    }

    std::sort(freeExactGpuScratchSlices_.begin(), freeExactGpuScratchSlices_.end());
}

void ChunkManager::Impl::exactGpuWorkerThreadFunction()
{
#ifdef _WIN32
    SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_NORMAL);
#endif
    while (!shouldStop_.load(std::memory_order_acquire) &&
           !exactGpuWorkerStopRequested_.load(std::memory_order_acquire))
    {
        commitPendingExactGpuBuilds();
        bool canMaintainExactGpuReserve = true;
        {
            std::lock_guard<std::mutex> lock(pendingExactGpuBuildsMutex_);
            canMaintainExactGpuReserve =
                std::none_of(pendingExactGpuBatches_.begin(),
                             pendingExactGpuBatches_.end(),
                             [](const PendingExactGpuBatch& batch)
                             {
                                 return batch.phase == ExactGpuBatchPhase::EmitSubmitted &&
                                        batch.emitResources.fenceValue != 0;
                             });
        }
        if (canMaintainExactGpuReserve)
        {
            (void)ensureExactGpuFreePageReserve(kExactGpuReserveFreePageWatermark);
        }
        if (shouldStop_.load(std::memory_order_acquire) ||
            exactGpuWorkerStopRequested_.load(std::memory_order_acquire))
        {
            break;
        }
        submitPendingExactGpuBuilds();

        std::unique_lock<std::mutex> waitLock(exactGpuWorkerMutex_);
        const bool hasPendingWork = exactGpuWorkerHasPendingWork();
        const bool needsLifecycleMaintenance = exactGpuWorkerNeedsLifecycleMaintenance();
        if (!hasPendingWork && !needsLifecycleMaintenance)
        {
            exactGpuWorkerCondition_.wait(waitLock,
                                          [this]
                                          {
                                              return shouldStop_.load(std::memory_order_acquire) ||
                                                     exactGpuWorkerStopRequested_.load(std::memory_order_acquire) ||
                                                     exactGpuWorkerHasPendingWork() ||
                                                     exactGpuWorkerNeedsLifecycleMaintenance();
                                          });
            continue;
        }

        exactGpuWorkerCondition_.wait_for(waitLock,
                                          hasPendingWork ? std::chrono::milliseconds(1)
                                                         : std::chrono::milliseconds(16));
    }
}

void ChunkManager::Impl::wakeExactGpuWorker()
{
    exactGpuWorkerCondition_.notify_all();
}

bool ChunkManager::Impl::exactGpuWorkerHasPendingWork()
{
    {
        std::lock_guard<std::mutex> lock(pendingExactGpuBuildMutex_);
        if (!pendingExactGpuBuildQueue_.empty())
        {
            return true;
        }
    }
    {
        std::lock_guard<std::mutex> lock(pendingExactGpuBuildsMutex_);
        if (!pendingExactGpuBatches_.empty())
        {
            return true;
        }
    }
    return false;
}

bool ChunkManager::Impl::acquireNextWorldgenPageDependency(glm::ivec2& pageKey,
                                                           std::uint64_t& token,
                                                           DependencyPriority& priority,
                                                           JobServiceClass& serviceClass,
                                                           bool& buildOccupancy,
                                                           bool& warmStructures)
{
    while (true)
    {
        WorldgenPageDependencyRequest request{};
        {
            std::lock_guard<std::mutex> queueLock(columnHeightPrefetchMutex_);
            if (pendingWorldgenPageDependencyQueue_.empty())
            {
                return false;
            }

            request = pendingWorldgenPageDependencyQueue_.top();
            pendingWorldgenPageDependencyQueue_.pop();
        }

        std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
        auto entryIt = worldgenPageEntries_.find(request.pageKey);
        if (entryIt == worldgenPageEntries_.end())
        {
            continue;
        }

        WorldgenPageDependencyEntry& entry = entryIt->second;
        if (!entry.dependencyJobQueued ||
            entry.token != request.token ||
            entry.priority != request.priority ||
            entry.serviceClass != request.serviceClass ||
            entry.buildOccupancy != request.buildOccupancy ||
            entry.warmStructures != request.warmStructures)
        {
            continue;
        }

        entry.dependencyJobQueued = false;
        if (worldgenPageSupportSatisfiedLocked(entry, entry.buildOccupancy, entry.warmStructures))
        {
            continue;
        }

        entry.dependencyJobInFlight = true;
        if (entry.state != WorldgenPageState::Ready || !entry.page)
        {
            entry.state = WorldgenPageState::Building;
        }
        pageKey = request.pageKey;
        token = request.token;
        priority = request.priority;
        serviceClass = request.serviceClass;
        buildOccupancy = request.buildOccupancy;
        warmStructures = request.warmStructures;
        return true;
    }
}

bool ChunkManager::Impl::acquireNextStructureRegionDependency(StructureRegionKey& regionKey,
                                                              std::uint64_t& token,
                                                              DependencyPriority& priority,
                                                              JobServiceClass& serviceClass)
{
    while (true)
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        if (pendingStructureRegionDependencyQueue_.empty())
        {
            return false;
        }

        const StructureRegionDependencyRequest request = pendingStructureRegionDependencyQueue_.top();
        pendingStructureRegionDependencyQueue_.pop();

        auto entryIt = structureRegionEntries_.find(request.regionKey);
        if (entryIt == structureRegionEntries_.end())
        {
            continue;
        }

        StructureRegionDependencyEntry& entry = entryIt->second;
        if (!entry.dependencyJobQueued ||
            entry.state != StructureRegionState::Queued ||
            entry.token != request.token ||
            entry.priority != request.priority ||
            entry.serviceClass != request.serviceClass)
        {
            continue;
        }

        entry.dependencyJobQueued = false;
        entry.state = StructureRegionState::Building;
        regionKey = request.regionKey;
        token = request.token;
        priority = request.priority;
        serviceClass = request.serviceClass;
        return true;
    }
}

void ChunkManager::Impl::workerThreadFunction()
{
#ifdef _WIN32
    SetThreadPriority(GetCurrentThread(), THREAD_PRIORITY_NORMAL);
#endif
    while (true)
    {
        try
        {
            Job job = jobQueue_.waitAndPop();
            struct QueueCompletionGuard
            {
                JobQueue& queue;
                JobType type;
                JobServiceClass serviceClass;

                ~QueueCompletionGuard()
                {
                    queue.jobCompleted(type, serviceClass);
                }
            } queueCompletionGuard{jobQueue_, job.type, job.serviceClass};
            processJob(job);
            const std::size_t latencySensitiveBacklog =
                jobQueue_.outstanding(JobServiceClass::InitialVisible) +
                jobQueue_.outstanding(JobServiceClass::LocalInteraction);
            const bool throttleRefinement =
                stationaryExactFillModeActive_ ||
                refinementBackpressureActive_.load(std::memory_order_acquire) &&
                latencySensitiveBacklog > 0;
            if (!throttleRefinement)
            {
                processPendingRelightRequests(1);
            }
        }
        catch (const std::runtime_error&)
        {
            break;
        }
        catch (const std::exception& ex)
        {
            std::cerr << "Worker thread error: " << ex.what() << std::endl;
        }
    }
}

void ChunkManager::Impl::enqueueJob(const std::shared_ptr<Chunk>& chunk,
                                    JobType type,
                                    const glm::ivec3& coord,
                                    std::uint32_t generationEpoch,
                                    bool initialReadyPriority,
                                    JobServiceClass serviceClass)
{
    if (shouldStop_.load(std::memory_order_acquire))
    {
        return;
    }

    if (chunk)
    {
        chunk->inFlight.fetch_add(1, std::memory_order_relaxed);
    }
    if (!jobQueue_.push(Job(type, coord, chunk, generationEpoch, initialReadyPriority, serviceClass)))
    {
        if (chunk)
        {
            chunk->inFlight.fetch_sub(1, std::memory_order_relaxed);
        }
    }
}

void ChunkManager::Impl::processJob(const Job& job)
{
    if (job.type == JobType::WorldgenPageDependency)
    {
        (void)processWorldgenPageDependencyJob();
        refillWorldgenPageDependencyJobs();
        return;
    }
    if (job.type == JobType::StructureRegionDependency)
    {
        (void)processStructureRegionDependencyJob();
        refillStructureRegionDependencyJobs();
        return;
    }
    if (job.type == JobType::BulkShellOracle)
    {
        (void)processBulkShellOracleJob();
        refillBulkShellOracleJobs();
        return;
    }

    std::shared_ptr<Chunk> chunk = job.chunk;
    if (!chunk)
    {
        return;
    }

    struct FlightGuard
    {
        Chunk* chunkPtr;
        explicit FlightGuard(Chunk* ptr) : chunkPtr(ptr) {}
        ~FlightGuard()
        {
            if (chunkPtr)
            {
                chunkPtr->inFlight.fetch_sub(1, std::memory_order_relaxed);
            }
        }
    } guard(chunk.get());

    if (job.type == JobType::Generate)
    {
        struct GenerateJobGuard
        {
            bool previousValue{false};

            GenerateJobGuard()
                : previousValue(gChunkManagerInsideGenerateJob)
            {
                gChunkManagerInsideGenerateJob = true;
            }

            ~GenerateJobGuard()
            {
                gChunkManagerInsideGenerateJob = previousValue;
            }
        } generateJobGuard{};
        setStreamingChunkLifecycleState(job.chunkCoord, FrontierDemandState::Generating);
        const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
        if (benchmarkEnabled)
        {
            const JobQueueSnapshot queueSnapshot = jobQueue_.snapshot();
            const auto recordCount = [&](AtomicCountHistogram& histogram, std::uint16_t value)
            {
                histogram.record(static_cast<std::uint64_t>(value));
            };
            recordCount(benchmarkMetrics_.chunkReadyRequestQueuedGenerateStage,
                        chunk->requestQueuedByType[jobTypeIndex(JobType::Generate)]);
            recordCount(benchmarkMetrics_.chunkReadyRequestQueuedMeshStage,
                        chunk->requestQueuedByType[jobTypeIndex(JobType::Mesh)]);
            recordCount(benchmarkMetrics_.chunkReadyRequestQueuedPrefetchStage,
                        chunk->requestQueuedByType[jobTypeIndex(JobType::WorldgenPageDependency)]);
            recordCount(benchmarkMetrics_.chunkReadyRequestQueuedBulkStage,
                        chunk->requestQueuedByType[jobTypeIndex(JobType::BulkShellOracle)]);
            recordCount(benchmarkMetrics_.chunkReadyRequestLatencySensitiveOutstandingStage,
                        chunk->requestLatencySensitiveOutstanding);
            benchmarkMetrics_.chunkReadyStartQueuedGenerateStage.record(
                static_cast<std::uint64_t>(queueSnapshot.queuedByType[jobTypeIndex(JobType::Generate)]));
            benchmarkMetrics_.chunkReadyStartQueuedMeshStage.record(
                static_cast<std::uint64_t>(queueSnapshot.queuedByType[jobTypeIndex(JobType::Mesh)]));
            benchmarkMetrics_.chunkReadyStartQueuedPrefetchStage.record(
                static_cast<std::uint64_t>(queueSnapshot.queuedByType[jobTypeIndex(JobType::WorldgenPageDependency)]));
            benchmarkMetrics_.chunkReadyStartQueuedBulkStage.record(
                static_cast<std::uint64_t>(queueSnapshot.queuedByType[jobTypeIndex(JobType::BulkShellOracle)]));
            benchmarkMetrics_.chunkReadyStartActiveGenerateStage.record(
                static_cast<std::uint64_t>(queueSnapshot.activeByType[jobTypeIndex(JobType::Generate)]));
            benchmarkMetrics_.chunkReadyStartActiveMeshStage.record(
                static_cast<std::uint64_t>(queueSnapshot.activeByType[jobTypeIndex(JobType::Mesh)]));
            benchmarkMetrics_.chunkReadyStartActivePrefetchStage.record(
                static_cast<std::uint64_t>(queueSnapshot.activeByType[jobTypeIndex(JobType::WorldgenPageDependency)]));
            benchmarkMetrics_.chunkReadyStartActiveBulkStage.record(
                static_cast<std::uint64_t>(queueSnapshot.activeByType[jobTypeIndex(JobType::BulkShellOracle)]));
            const std::size_t latencySensitiveOutstanding =
                queueSnapshot.queuedByService[jobServiceClassIndex(JobServiceClass::InitialVisible)] +
                queueSnapshot.activeByService[jobServiceClassIndex(JobServiceClass::InitialVisible)] +
                queueSnapshot.queuedByService[jobServiceClassIndex(JobServiceClass::LocalInteraction)] +
                queueSnapshot.activeByService[jobServiceClassIndex(JobServiceClass::LocalInteraction)];
            benchmarkMetrics_.chunkReadyStartLatencySensitiveOutstandingStage.record(
                static_cast<std::uint64_t>(latencySensitiveOutstanding));
            storeFirstBenchmarkTimestamp(chunk->generateStartTimestampMicros, steadyMicrosNow());
        }
        const auto generateStart = SteadyClock::now();
        const bool published = generateChunkBlocks(*chunk, job.generationEpoch);
        const auto generateEnd = SteadyClock::now();
        const auto generateMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(generateEnd - generateStart).count();
        profilingCounters_.generationMicros.fetch_add(generateMicros, std::memory_order_relaxed);
        profilingCounters_.generatedChunks.fetch_add(1, std::memory_order_relaxed);
        if (benchmarkEnabled)
        {
            benchmarkMetrics_.generateStage.recordMicros(static_cast<std::uint64_t>(generateMicros));
            benchmarkMetrics_.generatedChunks.fetch_add(1, std::memory_order_relaxed);
        }

        if (!published)
        {
            return;
        }

        if (benchmarkEnabled)
        {
            storeFirstBenchmarkTimestamp(chunk->generateDoneTimestampMicros, steadyMicrosNow());
        }

        const double generatedChunkNowSeconds = static_cast<double>(steadyMicrosNow()) / 1'000'000.0;
        const ChunkGameplayAuthority gameplayAuthority =
            desiredChunkGameplayAuthority(*chunk, lastCenterChunk_, generatedChunkNowSeconds);
        chunk->gameplayAuthority.store(gameplayAuthority, std::memory_order_release);
        refreshPendingExactGpuBuildCount(*chunk);

        if (chunk->hasBlocks.load(std::memory_order_acquire))
        {
            const bool useExactGpuVisuals =
                device_ != nullptr &&
                exactGpuContext_.ready() &&
                gameplayAuthority == ChunkGameplayAuthority::GpuStreaming;
            chunk->pendingMeshRefresh.store(false, std::memory_order_release);
            setStreamingChunkLifecycleState(job.chunkCoord, FrontierDemandState::Meshing);
            if (benchmarkEnabled)
            {
                storeFirstBenchmarkTimestamp(chunk->meshQueuedTimestampMicros, steadyMicrosNow());
            }
            if (useExactGpuVisuals)
            {
                chunk->state.store(ChunkState::Meshing, std::memory_order_release);
                if (!queueChunkForPreparedExactGpuBuild(chunk))
                {
                    queueChunkForExactGpuRefresh(chunk);
                }
            }
            else
            {
                chunk->state.store(ChunkState::Remeshing, std::memory_order_release);
                enqueueJob(chunk,
                           JobType::Mesh,
                           job.chunkCoord,
                           0,
                           true,
                           JobServiceClass::InitialVisible);
            }
            if (shouldTrackRecentEditChunk(chunk->coord))
            {
                std::ostringstream stream;
                stream << (useExactGpuVisuals ? "generate -> exact gpu refresh chunk=(" : "generate -> first mesh chunk=(")
                       << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z << ")";
                appendRecentEditDebugEvent(stream.str());
            }
        }
        else
        {
            chunk->state.store(ChunkState::Uploaded, std::memory_order_release);
            chunk->meshReady.store(false, std::memory_order_release);
            chunk->indexCount.store(0, std::memory_order_release);
            publishChunkReady(*chunk);
            if (shouldTrackRecentEditChunk(chunk->coord))
            {
                std::ostringstream stream;
                stream << "generate empty chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z << ")";
                appendRecentEditDebugEvent(stream.str());
            }
        }
    }
    else if (job.type == JobType::Mesh)
    {
        if (!chunk->meshReady.load(std::memory_order_acquire))
        {
            setStreamingChunkLifecycleState(job.chunkCoord, FrontierDemandState::Meshing);
        }
        if (benchmarkMetrics_.isEnabled())
        {
            storeFirstBenchmarkTimestamp(chunk->meshStartTimestampMicros, steadyMicrosNow());
        }
        const auto meshStart = SteadyClock::now();
        chunk->pendingMeshRefresh.store(false, std::memory_order_release);
        buildChunkMeshAsync(*chunk);
        const auto meshEnd = SteadyClock::now();
        const auto meshMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(meshEnd - meshStart).count();
        chunk->meshVersion.fetch_add(1, std::memory_order_acq_rel);
        profilingCounters_.meshingMicros.fetch_add(meshMicros, std::memory_order_relaxed);
        profilingCounters_.meshedChunks.fetch_add(1, std::memory_order_relaxed);
        if (benchmarkMetrics_.isEnabled())
        {
            benchmarkMetrics_.meshStage.recordMicros(static_cast<std::uint64_t>(meshMicros));
            benchmarkMetrics_.meshedChunks.fetch_add(1, std::memory_order_relaxed);
        }
        if (benchmarkMetrics_.isEnabled())
        {
            storeFirstBenchmarkTimestamp(chunk->meshDoneTimestampMicros, steadyMicrosNow());
        }

        const bool meshEmpty = chunk->meshData.empty();
        if (meshEmpty)
        {
            chunk->state.store(ChunkState::Uploaded, std::memory_order_release);
            publishChunkReady(*chunk);
        }
        else
        {
            chunk->state.store(ChunkState::Ready, std::memory_order_release);
        }

        if (shouldTrackRecentEditChunk(chunk->coord))
        {
            std::ostringstream stream;
            stream << "mesh done chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z
                   << ") empty=" << (meshEmpty ? "yes" : "no")
                   << " pendingRefresh=" << (chunk->pendingMeshRefresh.load(std::memory_order_acquire) ? "yes" : "no");
            appendRecentEditDebugEvent(stream.str());
        }

        if (chunk->pendingMeshRefresh.exchange(false, std::memory_order_acq_rel))
        {
            glm::ivec3 interactionCenter{0};
            {
                std::lock_guard<std::mutex> priorityLock(schedulingPriorityMutex_);
                interactionCenter = schedulingPriorityOrigin_;
            }
            chunk->state.store(ChunkState::Remeshing, std::memory_order_release);
            enqueueJob(chunk,
                       JobType::Mesh,
                       job.chunkCoord,
                       0,
                       chunkAwaitingInitialVisibleReady(*chunk),
                       classifyJobServiceClass(chunkAwaitingInitialVisibleReady(*chunk),
                                               shouldKeepLoadedChunkInteractive(*chunk, interactionCenter),
                                               false));
            if (shouldTrackRecentEditChunk(chunk->coord))
            {
                std::ostringstream stream;
                stream << "mesh result superseded chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z << ")";
                appendRecentEditDebugEvent(stream.str());
            }
            return;
        }

        if (chunk->meshData.empty())
        {
            recycleChunkGPU(*chunk);
            chunk->meshReady.store(false, std::memory_order_release);
            chunk->indexCount.store(0, std::memory_order_release);
            if (shouldTrackRecentEditChunk(chunk->coord))
            {
                std::ostringstream stream;
                stream << "mesh empty -> recycle GPU chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z << ")";
                appendRecentEditDebugEvent(stream.str());
            }
            return;
        }

        if (chunk->state.load(std::memory_order_acquire) == ChunkState::Ready)
        {
            queueChunkForLocalCpuUpload(chunk);
        }
    }
}

ChunkPriorityKey ChunkManager::Impl::buildUploadPriorityKey(const glm::ivec3& coord,
                                                            const glm::ivec3& origin,
                                                            const glm::vec3& forward) const noexcept
{
    const glm::vec2 forwardXZ = normalizePriorityForwardXZ(forward);
    const int dx = coord.x - origin.x;
    const int dy = coord.y - origin.y;
    const int dz = coord.z - origin.z;
    const int horizontalDistance = std::max(std::abs(dx), std::abs(dz));
    const int verticalDistance = std::abs(dy);

    int supportBucket = 3;
    if (horizontalDistance == 0 && verticalDistance <= 8)
    {
        supportBucket = 0;
    }
    else if (horizontalDistance <= 1 && coord.y >= origin.y - 2 && coord.y <= origin.y + 2)
    {
        supportBucket = 1;
    }
    else if (horizontalDistance <= 2 && verticalDistance <= 2)
    {
        supportBucket = 2;
    }

    float facingDot = 1.0f;
    const glm::vec2 delta(static_cast<float>(dx), static_cast<float>(dz));
    if (glm::dot(delta, delta) > kEpsilon)
    {
        facingDot = glm::dot(glm::normalize(delta), forwardXZ);
    }

    int forwardBucket = 2;
    if (facingDot >= 0.5f)
    {
        forwardBucket = 0;
    }
    else if (facingDot >= -0.2f)
    {
        forwardBucket = 1;
    }

    return ChunkPriorityKey{
        supportBucket,
        horizontalDistance,
        forwardBucket,
        verticalDistance,
        std::abs(dx) + verticalDistance + std::abs(dz)};
}

UploadQueueBucket ChunkManager::Impl::classifyUploadQueueBucket(const Chunk& chunk,
                                                                const glm::ivec3& origin,
                                                                const glm::vec3& forward,
                                                                bool retryBucket) const noexcept
{
    if (retryBucket)
    {
        return UploadQueueBucket::Retry;
    }

    if (chunkAwaitingInitialVisibleReady(chunk))
    {
        return UploadQueueBucket::InitialVisible;
    }

    if (isChunkInLocalInteractionIsland(chunk.coord, origin) ||
        shouldTrackRecentEditChunk(chunk.coord))
    {
        return UploadQueueBucket::InitialVisible;
    }

    const ChunkPriorityKey priority = buildUploadPriorityKey(chunk.coord, origin, forward);
    const int frontSpan = std::max(6, targetViewDistance_ / 4);
    const bool nearSupport = priority.supportBucket <= 2;
    const bool frontVisible = priority.forwardBucket == 0 &&
                              priority.horizontalDistance <= frontSpan &&
                              priority.verticalDistance <= std::max(4, lastVerticalRadius_ / 2);
    return (nearSupport || frontVisible) ? UploadQueueBucket::NearFrontVisible : UploadQueueBucket::Background;
}

std::shared_ptr<Chunk> ChunkManager::Impl::popNextChunkForUpload()
{
    glm::ivec3 priorityOrigin{0};
    glm::vec3 priorityForward{0.0f, 0.0f, -1.0f};
    {
        std::lock_guard<std::mutex> priorityLock(schedulingPriorityMutex_);
        priorityOrigin = schedulingPriorityOrigin_;
        priorityForward = schedulingPriorityForward_;
    }

    std::lock_guard<std::mutex> lock(uploadQueueMutex_);
    for (std::size_t bucketIndex = 0; bucketIndex < uploadQueues_.size(); ++bucketIndex)
    {
        auto& queue = uploadQueues_[bucketIndex];
        while (!queue.empty())
        {
            UploadQueueEntry entry = queue.top();
            queue.pop();
            ++uploadQueueScanEntriesLastFrame_;

            const std::shared_ptr<Chunk> chunk = entry.chunk.lock();
            if (!chunk)
            {
                ++uploadSkippedExpiredLastFrame_;
                continue;
            }

            if (!chunk->queuedForUpload.load(std::memory_order_acquire) ||
                chunk->uploadQueueTicket.load(std::memory_order_acquire) != entry.ticket)
            {
                continue;
            }

            const UploadQueueBucket desiredBucket = classifyUploadQueueBucket(*chunk, priorityOrigin, priorityForward, false);
            if (desiredBucket != static_cast<UploadQueueBucket>(bucketIndex) &&
                desiredBucket != UploadQueueBucket::Retry)
            {
                const std::uint64_t ticket = nextUploadQueueTicket_++;
                chunk->uploadQueueTicket.store(ticket, std::memory_order_release);
                chunk->queuedUploadBucket.store(static_cast<std::uint8_t>(desiredBucket), std::memory_order_release);
                uploadQueues_[uploadQueueBucketIndex(desiredBucket)].push(UploadQueueEntry{
                    chunk,
                    buildUploadPriorityKey(chunk->coord, priorityOrigin, priorityForward),
                    ticket,
                    nextUploadQueueSequence_++});
                continue;
            }

            const std::uint8_t queuedBucket = chunk->queuedUploadBucket.load(std::memory_order_acquire);
            if (queuedUploadCount_ > 0)
            {
                --queuedUploadCount_;
            }
            if (queuedBucket == static_cast<std::uint8_t>(UploadQueueBucket::InitialVisible) &&
                initialVisibleUploadCount_ > 0)
            {
                --initialVisibleUploadCount_;
            }
            chunk->queuedForUpload.store(false, std::memory_order_release);
            chunk->queuedUploadBucket.store(std::numeric_limits<std::uint8_t>::max(), std::memory_order_release);
            chunk->uploadQueueTicket.store(0, std::memory_order_release);
            return chunk;
        }
    }

    return nullptr;
}

void ChunkManager::Impl::queueChunkForLocalCpuUpload(const std::shared_ptr<Chunk>& chunk, bool retryBucket)
{
    if (!chunk)
    {
        return;
    }
    const bool activeLocalEditOwnership =
        chunk->lastLocalEditMicros.load(std::memory_order_acquire) > 0 ||
        chunk->handoffTargetRevision.load(std::memory_order_acquire) > 0;
    if (chunkUsesCpuNearRendering(*chunk) && activeLocalEditOwnership)
    {
        queueChunkForDedicatedLocalUpload(chunk);
        return;
    }
    if (!shouldKeepLoadedChunkInteractive(*chunk, lastCenterChunk_))
    {
        return;
    }

    glm::ivec3 priorityOrigin{0};
    glm::vec3 priorityForward{0.0f, 0.0f, -1.0f};
    {
        std::lock_guard<std::mutex> priorityLock(schedulingPriorityMutex_);
        priorityOrigin = schedulingPriorityOrigin_;
        priorityForward = schedulingPriorityForward_;
    }

    const UploadQueueBucket bucket = classifyUploadQueueBucket(*chunk, priorityOrigin, priorityForward, retryBucket);
    const std::uint8_t desiredBucket = static_cast<std::uint8_t>(bucket);

    std::lock_guard<std::mutex> lock(uploadQueueMutex_);
    if (chunk->queuedForUpload.load(std::memory_order_acquire))
    {
        const std::uint8_t existingBucket = chunk->queuedUploadBucket.load(std::memory_order_acquire);
        if (existingBucket <= desiredBucket)
        {
            return;
        }

        if (desiredBucket == static_cast<std::uint8_t>(UploadQueueBucket::InitialVisible) &&
            existingBucket != static_cast<std::uint8_t>(UploadQueueBucket::InitialVisible))
        {
            ++initialVisibleUploadCount_;
        }
    }
    else
    {
        ++queuedUploadCount_;
        if (desiredBucket == static_cast<std::uint8_t>(UploadQueueBucket::InitialVisible))
        {
            ++initialVisibleUploadCount_;
        }
    }

    const std::uint64_t ticket = nextUploadQueueTicket_++;
    chunk->queuedForUpload.store(true, std::memory_order_release);
    chunk->queuedUploadBucket.store(desiredBucket, std::memory_order_release);
    chunk->uploadQueueTicket.store(ticket, std::memory_order_release);
    uploadQueues_[uploadQueueBucketIndex(bucket)].push(UploadQueueEntry{
        chunk,
        buildUploadPriorityKey(chunk->coord, priorityOrigin, priorityForward),
        ticket,
        nextUploadQueueSequence_++});
    storeFirstBenchmarkTimestamp(chunk->uploadQueuedTimestampMicros, steadyMicrosNow());

    if (shouldTrackRecentEditChunk(chunk->coord))
    {
        std::ostringstream stream;
        stream << "queue upload chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z
               << ") idx=" << chunk->indexCount.load(std::memory_order_acquire)
               << " bucket=" << static_cast<int>(desiredBucket);
        appendRecentEditDebugEvent(stream.str());
    }
}

void ChunkManager::Impl::requeueChunkForLocalCpuUpload(const std::shared_ptr<Chunk>& chunk, bool retryBucket)
{
    queueChunkForLocalCpuUpload(chunk, retryBucket);
}

void ChunkManager::Impl::queueChunkForCommit(const std::shared_ptr<Chunk>& chunk, UINT64 uploadFenceValue)
{
    if (!chunk || uploadFenceValue == 0)
    {
        return;
    }

    std::lock_guard<std::mutex> lock(pendingCommitQueueMutex_);
    if (chunk->queuedForCommit.load(std::memory_order_acquire))
    {
        return;
    }

    const std::uint64_t ticket = nextCommitQueueTicket_++;
    chunk->queuedForCommit.store(true, std::memory_order_release);
    chunk->commitQueueTicket.store(ticket, std::memory_order_release);
    pendingCommitQueue_.push_back(PendingCommitQueueEntry{chunk, ticket, uploadFenceValue});
}

std::size_t ChunkManager::Impl::nextPowerOfTwo(std::size_t value) noexcept
{
    if (value <= 1)
    {
        return 1;
    }

    value -= 1;
    value |= value >> 1;
    value |= value >> 2;
    value |= value >> 4;
    value |= value >> 8;
    value |= value >> 16;
#if SIZE_MAX > 0xffffffffu
    value |= value >> 32;
#endif
    return value + 1;
}

const char* ChunkManager::Impl::chunkBufferPageStateLabel(ChunkBufferPageState state) noexcept
{
    switch (state)
    {
    case ChunkBufferPageState::Free: return "free";
    case ChunkBufferPageState::OpenWritable: return "open_writable";
    case ChunkBufferPageState::SealedPendingResident: return "sealed_pending_resident";
    case ChunkBufferPageState::ResidentImmutable: return "resident_immutable";
    case ChunkBufferPageState::Retiring: return "retiring";
    default: return "unknown";
    }
}

const char* ChunkManager::Impl::chunkBufferPageUsageLabel(ChunkBufferPageUsage usage) noexcept
{
    switch (usage)
    {
    case ChunkBufferPageUsage::CpuUpload: return "cpu_upload";
    case ChunkBufferPageUsage::ExactGpu: return "exact_gpu";
    default: return "unknown";
    }
}

std::string ChunkManager::Impl::summarizeChunkBufferPagesLocked() const
{
    struct Totals
    {
        std::size_t count{0};
        std::size_t residentChunks{0};
        std::size_t pendingChunks{0};
        std::uint64_t bytes{0};
    };

    Totals free{};
    Totals openWritable{};
    Totals sealedPendingResident{};
    Totals residentImmutable{};
    Totals retiring{};

    auto accumulate = [](Totals& totals, const ChunkBufferPage& page)
    {
        ++totals.count;
        totals.residentChunks += page.residentChunks;
        totals.pendingChunks += page.pendingChunks;
        if (page.usage != ChunkBufferPageUsage::ExactGpu &&
            page.vertexBuffer != nullptr)
        {
            totals.bytes += static_cast<std::uint64_t>(page.vertexCapacity * sizeof(Vertex));
        }
        if (page.usage != ChunkBufferPageUsage::ExactGpu &&
            page.indexBuffer != nullptr)
        {
            totals.bytes += static_cast<std::uint64_t>(page.indexCapacity * sizeof(std::uint32_t));
        }
        if (page.drawRecordBuffer != nullptr)
        {
            totals.bytes +=
                static_cast<std::uint64_t>(
                    page.recordCapacity *
                    ((page.usage == ChunkBufferPageUsage::ExactGpu)
                         ? sizeof(ExactChunkRenderBatch::GpuCullRecord)
                         : sizeof(ChunkRenderBatch::GpuCullRecord)));
        }
        if (page.drawRecordMetadataBuffer != nullptr)
        {
            totals.bytes +=
                static_cast<std::uint64_t>(page.recordCapacity * sizeof(FarLodGpuContext::ExactDrawRecordMetadata));
        }
        if (page.faceDescriptorBuffer != nullptr)
        {
            totals.bytes += static_cast<std::uint64_t>(page.faceCapacity * 32u);
        }
        if (page.usage != ChunkBufferPageUsage::ExactGpu &&
            page.vertexUploadBuffer != nullptr)
        {
            totals.bytes += static_cast<std::uint64_t>(page.vertexCapacity * sizeof(Vertex));
        }
        if (page.usage != ChunkBufferPageUsage::ExactGpu &&
            page.indexUploadBuffer != nullptr)
        {
            totals.bytes += static_cast<std::uint64_t>(page.indexCapacity * sizeof(std::uint32_t));
        }
    };

    for (const ChunkBufferPage& page : bufferPages_)
    {
        switch (page.state)
        {
        case ChunkBufferPageState::Free: accumulate(free, page); break;
        case ChunkBufferPageState::OpenWritable: accumulate(openWritable, page); break;
        case ChunkBufferPageState::SealedPendingResident: accumulate(sealedPendingResident, page); break;
        case ChunkBufferPageState::ResidentImmutable: accumulate(residentImmutable, page); break;
        case ChunkBufferPageState::Retiring: accumulate(retiring, page); break;
        default: break;
        }
    }

    auto appendTotals = [](std::ostringstream& stream, const char* label, const Totals& totals)
    {
        stream << ' ' << label
               << "{pages=" << totals.count
               << ",residentChunks=" << totals.residentChunks
               << ",pendingChunks=" << totals.pendingChunks
               << ",mib=" << std::fixed << std::setprecision(2)
               << (static_cast<double>(totals.bytes) / (1024.0 * 1024.0))
               << "}";
    };

    std::ostringstream stream;
    stream << "exact upload pages total=" << bufferPages_.size();
    appendTotals(stream, "free", free);
    appendTotals(stream, "open_writable", openWritable);
    appendTotals(stream, "sealed_pending_resident", sealedPendingResident);
    appendTotals(stream, "resident_immutable", residentImmutable);
    appendTotals(stream, "retiring", retiring);
    return stream.str();
}

void ChunkManager::Impl::ensureChunkBufferPageUploadBuffers(ChunkBufferPage& page)
{
    if (page.vertexUploadBuffer == nullptr)
    {
        page.vertexUploadBuffer = createUploadBuffer(device_.Get(),
                                                     static_cast<std::uint64_t>(page.vertexCapacity * sizeof(Vertex)),
                                                     page.mappedVertexData);
    }

    if (page.indexUploadBuffer == nullptr)
    {
        page.indexUploadBuffer = createUploadBuffer(device_.Get(),
                                                    static_cast<std::uint64_t>(page.indexCapacity * sizeof(std::uint32_t)),
                                                    page.mappedIndexData);
    }
}

void ChunkManager::Impl::releaseChunkBufferPageUploadBuffers(ChunkBufferPage& page) noexcept
{
    page.vertexUploadBuffer.Reset();
    page.indexUploadBuffer.Reset();
    page.mappedVertexData = nullptr;
    page.mappedIndexData = nullptr;
}

std::uint64_t ChunkManager::Impl::exactGpuEmitConfigBytes() noexcept
{
    return sizeof(FarLodGpuContext::ExactEmitConfig);
}

std::uint64_t ChunkManager::Impl::exactGpuPageMetadataBytes(std::size_t pageCount) noexcept
{
    return static_cast<std::uint64_t>(pageCount) * sizeof(FarLodGpuContext::ExactPageGpuMetadata);
}

FarLodGpuContext::ExactPageGpuMetadata ChunkManager::Impl::buildExactGpuPageMetadata(
    std::uint32_t pageIndex,
    const ChunkBufferPage& page) noexcept
{
    FarLodGpuContext::ExactPageGpuMetadata metadata{};
    metadata.pageIndex = pageIndex;
    metadata.state = static_cast<std::uint32_t>(page.state);
    metadata.recordCapacity = static_cast<std::uint32_t>(page.recordCapacity);
    metadata.faceDescriptorUavDescriptorIndex = page.exactFaceDescriptorUavDescriptorIndex;
    metadata.drawRecordUavDescriptorIndex = page.exactDrawRecordUavDescriptorIndex;
    metadata.drawRecordMetadataUavDescriptorIndex = page.exactDrawRecordMetadataUavDescriptorIndex;
    return metadata;
}

void ChunkManager::Impl::resetExactGpuEmitBuffers() noexcept
{
    exactGpuEmitConfigBuffer_.Reset();
    exactGpuPageMetadataBuffer_.Reset();
    exactGpuChunkAllocationRecordBuffer_.Reset();
    exactGpuEmitConfigBufferState_ = D3D12_RESOURCE_STATE_COMMON;
    exactGpuPageMetadataBufferState_ = D3D12_RESOURCE_STATE_COMMON;
    exactGpuChunkAllocationRecordBufferState_ = D3D12_RESOURCE_STATE_COMMON;
    exactGpuEmitConfig_ = {};
    exactGpuDirtyPageIndices_.clear();
    exactGpuPageMetadataQueued_.clear();
    exactGpuEmitConfigDirty_ = true;
    exactGpuPageMetadataCapacity_ = 0;
    exactGpuChunkAllocationRecordCapacity_ = 0;
    exactGpuBlockUvSrvDescriptorIndex_ = FarLodGpuContext::kInvalidDescriptorIndex;
}

void ChunkManager::Impl::noteExactGpuPageMetadataChange(std::uint32_t pageIndex) noexcept
{
    if (pageIndex >= bufferPages_.size())
    {
        noteExactGpuEmitConfigRefresh();
        return;
    }

    if (exactGpuPageMetadataQueued_.size() < bufferPages_.size())
    {
        exactGpuPageMetadataQueued_.resize(bufferPages_.size(), 0u);
    }
    if (exactGpuPageMetadataQueued_[pageIndex] != 0u)
    {
        return;
    }

    exactGpuPageMetadataQueued_[pageIndex] = 1u;
    exactGpuDirtyPageIndices_.push_back(pageIndex);
}

void ChunkManager::Impl::noteExactGpuEmitConfigRefresh() noexcept
{
    exactGpuEmitConfigDirty_ = true;
}

void ChunkManager::Impl::queueAllExactGpuPageMetadataChanges() noexcept
{
    if (exactGpuPageMetadataQueued_.size() < bufferPages_.size())
    {
        exactGpuPageMetadataQueued_.resize(bufferPages_.size(), 0u);
    }
    for (std::uint32_t pageIndex = 0; pageIndex < bufferPages_.size(); ++pageIndex)
    {
        noteExactGpuPageMetadataChange(pageIndex);
    }
}

void ChunkManager::Impl::updateExactGpuChunkAllocationRecord(const PendingExactGpuBuild& pending,
                                                             std::uint32_t requiredFaceCount,
                                                             std::uint32_t reservedFaceCapacity,
                                                             std::uint32_t phase,
                                                             std::uint32_t statusFlags,
                                                             std::uint32_t centerVoxelSrvDescriptorIndex,
                                                             std::uint32_t haloSrvDescriptorIndex) noexcept
{
    if (pending.scratchSliceIndex >= exactGpuChunkAllocationRecords_.size())
    {
        return;
    }

    FarLodGpuContext::ExactChunkAllocationRecord& record =
        exactGpuChunkAllocationRecords_[pending.scratchSliceIndex];
    std::memset(&record, 0, sizeof(record));
    if (!pending.chunk)
    {
        return;
    }

    record.chunkWorldMinX = pending.chunk->coord.x * kChunkSizeX;
    record.chunkWorldMinY = pending.chunk->minWorldY;
    record.chunkWorldMinZ = pending.chunk->coord.z * kChunkSizeZ;
    record.phase = phase;
    record.statusFlags = statusFlags;
    record.buildVersion = pending.buildVersion;
    record.generationEpoch = pending.generationEpoch;
    record.requiredFaceCount = requiredFaceCount;
    record.pageIndex = pending.allocation.pageIndex;
    record.recordIndex = pending.allocation.recordIndex;
    record.faceBase = static_cast<std::uint32_t>(pending.allocation.faceOffset);
    record.reservedFaceCapacity = reservedFaceCapacity;
    record.centerVoxelSrvDescriptorIndex = centerVoxelSrvDescriptorIndex;
    record.haloSrvDescriptorIndex = haloSrvDescriptorIndex;
    record.inputVersionLo = static_cast<std::uint32_t>(pending.inputVersion & 0xffffffffu);
    record.inputVersionHi = static_cast<std::uint32_t>(pending.inputVersion >> 32u);
}

void ChunkManager::Impl::clearExactGpuChunkAllocationRecord(std::uint32_t scratchSliceIndex) noexcept
{
    if (scratchSliceIndex >= exactGpuChunkAllocationRecords_.size())
    {
        return;
    }

    std::memset(&exactGpuChunkAllocationRecords_[scratchSliceIndex],
                0,
                sizeof(exactGpuChunkAllocationRecords_[scratchSliceIndex]));
}

bool ChunkManager::Impl::ensureExactGpuEmitBuffers(std::size_t pageCount)
{
    if (device_ == nullptr)
    {
        return false;
    }

    const std::uint32_t requiredPageCapacity = static_cast<std::uint32_t>(
        std::max<std::size_t>(1u, nextPowerOfTwo(std::max<std::size_t>(pageCount, 1u))));
    try
    {
        if (exactGpuEmitConfigBuffer_ == nullptr)
        {
            exactGpuEmitConfigBuffer_ = createDefaultBuffer(device_.Get(),
                                                            exactGpuEmitConfigBytes(),
                                                            D3D12_RESOURCE_STATE_COMMON);
            setDebugObjectName(exactGpuEmitConfigBuffer_.Get(), L"ExactGpuEmitConfig");
            exactGpuEmitConfigBufferState_ = D3D12_RESOURCE_STATE_COMMON;
            exactGpuEmitConfigDirty_ = true;
        }
        if (exactGpuPageMetadataBuffer_ == nullptr ||
            exactGpuPageMetadataCapacity_ < requiredPageCapacity)
        {
            exactGpuPageMetadataBuffer_ = createDefaultBuffer(
                device_.Get(),
                exactGpuPageMetadataBytes(requiredPageCapacity),
                D3D12_RESOURCE_STATE_COMMON);
            setDebugObjectName(exactGpuPageMetadataBuffer_.Get(), L"ExactGpuPageMetadata");
            exactGpuPageMetadataBufferState_ = D3D12_RESOURCE_STATE_COMMON;
            exactGpuPageMetadataCapacity_ = requiredPageCapacity;
            queueAllExactGpuPageMetadataChanges();
        }
    }
    catch (const std::exception&)
    {
        return false;
    }

    return exactGpuEmitConfigBuffer_ != nullptr &&
           exactGpuPageMetadataBuffer_ != nullptr;
}

bool ChunkManager::Impl::ensureExactGpuChunkAllocationRecordBuffer()
{
    if (device_ == nullptr)
    {
        return false;
    }

    const std::uint32_t requiredCapacity =
        static_cast<std::uint32_t>(std::max<std::size_t>(1u, exactGpuContext_.maxExactGpuBuildBatches()));
    if (exactGpuChunkAllocationRecords_.size() < requiredCapacity)
    {
        exactGpuChunkAllocationRecords_.resize(requiredCapacity);
        exactGpuEmitConfig_.buildRecordCount =
            static_cast<std::uint32_t>(exactGpuChunkAllocationRecords_.size());
        noteExactGpuEmitConfigRefresh();
    }

    if (exactGpuChunkAllocationRecordBuffer_ != nullptr &&
        exactGpuChunkAllocationRecordCapacity_ >= requiredCapacity)
    {
        return true;
    }

    try
    {
        exactGpuChunkAllocationRecordBuffer_ = createDefaultBuffer(
            device_.Get(),
            static_cast<std::uint64_t>(requiredCapacity) *
                sizeof(FarLodGpuContext::ExactChunkAllocationRecord),
            D3D12_RESOURCE_STATE_COMMON,
            D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
        setDebugObjectName(exactGpuChunkAllocationRecordBuffer_.Get(), L"ExactGpuChunkAllocationRecords");
        exactGpuChunkAllocationRecordBufferState_ = D3D12_RESOURCE_STATE_COMMON;
        exactGpuChunkAllocationRecordCapacity_ = requiredCapacity;
    }
    catch (const std::exception&)
    {
        return false;
    }

    return exactGpuChunkAllocationRecordBuffer_ != nullptr;
}

bool ChunkManager::Impl::syncExactGpuEmitMetadata(
    std::vector<FarLodGpuContext::ScratchAllocation>& ownedUploads,
    ExactGpuEmitMetadataSyncDebugInfo* debugInfo)
{
    if (debugInfo != nullptr)
    {
        *debugInfo = {};
    }
    std::lock_guard<std::mutex> lock(bufferPageMutex_);

    if (!ensureExactGpuEmitBuffers(bufferPages_.size()))
    {
        return false;
    }

    if (debugInfo != nullptr)
    {
        debugInfo->dirtyPageCount = exactGpuDirtyPageIndices_.size();
    }

    const auto transitionForCopyDest = [&](ID3D12Resource* resource,
                                           D3D12_RESOURCE_STATES& currentState)
    {
        exactGpuContext_.transition(resource, currentState, D3D12_RESOURCE_STATE_COPY_DEST);
        currentState = D3D12_RESOURCE_STATE_COPY_DEST;
    };
    const auto transitionForCommon = [&](ID3D12Resource* resource,
                                         D3D12_RESOURCE_STATES& currentState)
    {
        exactGpuContext_.transition(resource, currentState, D3D12_RESOURCE_STATE_COMMON);
        currentState = D3D12_RESOURCE_STATE_COMMON;
    };

    if (exactGpuEmitConfigDirty_)
    {
        exactGpuEmitConfig_.pageCount = static_cast<std::uint32_t>(bufferPages_.size());
        exactGpuEmitConfig_.buildRecordCount =
            static_cast<std::uint32_t>(exactGpuChunkAllocationRecords_.size());
        exactGpuEmitConfig_.blockFaceUvDescriptorIndex = exactGpuBlockUvSrvDescriptorIndex_;
        const FarLodGpuContext::ScratchAllocation stateUpload =
            exactGpuContext_.allocateUpload(exactGpuEmitConfigBytes(),
                                            alignof(FarLodGpuContext::ExactEmitConfig));
        if (stateUpload.resource == nullptr || stateUpload.cpuPtr == nullptr)
        {
            return false;
        }

        std::memcpy(stateUpload.cpuPtr, &exactGpuEmitConfig_, sizeof(exactGpuEmitConfig_));
        ownedUploads.push_back(stateUpload);
        if (debugInfo != nullptr)
        {
            debugInfo->uploadBytes += static_cast<std::size_t>(exactGpuEmitConfigBytes());
        }
        transitionForCopyDest(exactGpuEmitConfigBuffer_.Get(), exactGpuEmitConfigBufferState_);
        exactGpuContext_.copyBuffer(exactGpuEmitConfigBuffer_.Get(),
                                    0,
                                    stateUpload.resource,
                                    stateUpload.offset,
                                    exactGpuEmitConfigBytes());
        transitionForCommon(exactGpuEmitConfigBuffer_.Get(), exactGpuEmitConfigBufferState_);
    }

    if (!exactGpuDirtyPageIndices_.empty())
    {
        transitionForCopyDest(exactGpuPageMetadataBuffer_.Get(),
                              exactGpuPageMetadataBufferState_);
        for (const std::uint32_t pageIndex : exactGpuDirtyPageIndices_)
        {
            if (pageIndex >= bufferPages_.size())
            {
                continue;
            }

            const FarLodGpuContext::ExactPageGpuMetadata metadata =
                buildExactGpuPageMetadata(pageIndex, bufferPages_[pageIndex]);
            const FarLodGpuContext::ScratchAllocation upload =
                exactGpuContext_.allocateUpload(sizeof(FarLodGpuContext::ExactPageGpuMetadata),
                                                alignof(FarLodGpuContext::ExactPageGpuMetadata));
            if (upload.resource == nullptr || upload.cpuPtr == nullptr)
            {
                transitionForCommon(exactGpuPageMetadataBuffer_.Get(),
                                    exactGpuPageMetadataBufferState_);
                return false;
            }

            std::memcpy(upload.cpuPtr, &metadata, sizeof(metadata));
            ownedUploads.push_back(upload);
            if (debugInfo != nullptr)
            {
                debugInfo->uploadBytes += sizeof(FarLodGpuContext::ExactPageGpuMetadata);
            }
            exactGpuContext_.copyBuffer(
                exactGpuPageMetadataBuffer_.Get(),
                static_cast<std::uint64_t>(pageIndex) * sizeof(FarLodGpuContext::ExactPageGpuMetadata),
                upload.resource,
                upload.offset,
                sizeof(FarLodGpuContext::ExactPageGpuMetadata));
        }
        transitionForCommon(exactGpuPageMetadataBuffer_.Get(),
                            exactGpuPageMetadataBufferState_);
    }

    for (const std::uint32_t pageIndex : exactGpuDirtyPageIndices_)
    {
        if (pageIndex < exactGpuPageMetadataQueued_.size())
        {
            exactGpuPageMetadataQueued_[pageIndex] = 0u;
        }
    }
    exactGpuDirtyPageIndices_.clear();
    exactGpuEmitConfigDirty_ = false;
    return true;
}

bool ChunkManager::Impl::syncExactGpuChunkAllocationRecords(
    std::span<const std::uint32_t> scratchSliceIndices,
    std::vector<FarLodGpuContext::ScratchAllocation>& ownedUploads)
{
    if (scratchSliceIndices.empty())
    {
        return true;
    }
    if (!ensureExactGpuChunkAllocationRecordBuffer())
    {
        return false;
    }

    exactGpuContext_.transition(exactGpuChunkAllocationRecordBuffer_.Get(),
                                exactGpuChunkAllocationRecordBufferState_,
                                D3D12_RESOURCE_STATE_COPY_DEST);
    exactGpuChunkAllocationRecordBufferState_ = D3D12_RESOURCE_STATE_COPY_DEST;
    for (const std::uint32_t sliceIndex : scratchSliceIndices)
    {
        if (sliceIndex >= exactGpuChunkAllocationRecords_.size())
        {
            continue;
        }

        const FarLodGpuContext::ScratchAllocation upload =
            exactGpuContext_.allocateUpload(sizeof(FarLodGpuContext::ExactChunkAllocationRecord),
                                            alignof(FarLodGpuContext::ExactChunkAllocationRecord));
        if (upload.resource == nullptr || upload.cpuPtr == nullptr)
        {
            exactGpuContext_.transition(exactGpuChunkAllocationRecordBuffer_.Get(),
                                        exactGpuChunkAllocationRecordBufferState_,
                                        D3D12_RESOURCE_STATE_COMMON);
            exactGpuChunkAllocationRecordBufferState_ = D3D12_RESOURCE_STATE_COMMON;
            return false;
        }

        std::memcpy(upload.cpuPtr,
                    &exactGpuChunkAllocationRecords_[sliceIndex],
                    sizeof(FarLodGpuContext::ExactChunkAllocationRecord));
        ownedUploads.push_back(upload);
        exactGpuContext_.copyBuffer(
            exactGpuChunkAllocationRecordBuffer_.Get(),
            static_cast<std::uint64_t>(sliceIndex) * sizeof(FarLodGpuContext::ExactChunkAllocationRecord),
            upload.resource,
            upload.offset,
            sizeof(FarLodGpuContext::ExactChunkAllocationRecord));
    }
    exactGpuContext_.transition(exactGpuChunkAllocationRecordBuffer_.Get(),
                                exactGpuChunkAllocationRecordBufferState_,
                                D3D12_RESOURCE_STATE_COMMON);
    exactGpuChunkAllocationRecordBufferState_ = D3D12_RESOURCE_STATE_COMMON;
    return true;
}

void ChunkManager::Impl::enqueueExactDrawRecordInactive(std::uint32_t pageIndex,
                                                        std::uint32_t recordIndex,
                                                        bool residentRecord)
{
    if (recordIndex == kInvalidExactGpuDrawRecordIndex ||
        pageIndex == kInvalidChunkBufferPage)
    {
        return;
    }

    UINT64 pageEpoch = 0;
    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        if (pageIndex >= bufferPages_.size())
        {
            return;
        }

        ChunkBufferPage& page = bufferPages_[pageIndex];
        if (page.usage != ChunkBufferPageUsage::ExactGpu ||
            page.drawRecordBuffer == nullptr)
        {
            return;
        }

        pageEpoch = page.drawRecordEpoch;
        if (residentRecord)
        {
            if (page.liveResidentChunkCount > 0)
            {
                --page.liveResidentChunkCount;
            }
            ++page.inactiveResidentRecordCount;
        }
    }

    if (pageEpoch == 0)
    {
        return;
    }

    std::lock_guard<std::mutex> lock(pendingExactDrawRecordClearsMutex_);
    pendingExactDrawRecordClears_.push_back(PendingExactDrawRecordClear{
        pageIndex,
        recordIndex,
        pageEpoch});
}

void ChunkManager::Impl::drainPendingExactDrawRecordClears()
{
    std::vector<PendingExactDrawRecordClear> clears;
    {
        std::lock_guard<std::mutex> lock(pendingExactDrawRecordClearsMutex_);
        if (pendingExactDrawRecordClears_.empty())
        {
            return;
        }
        clears.swap(pendingExactDrawRecordClears_);
    }

    std::unique_lock<std::mutex> exactLock(exactGpuExecutionMutex_);
    if (!exactGpuContext_.begin())
    {
        std::lock_guard<std::mutex> lock(pendingExactDrawRecordClearsMutex_);
        pendingExactDrawRecordClears_.insert(pendingExactDrawRecordClears_.end(), clears.begin(), clears.end());
        return;
    }

    // Synchronize against the last submitted render work before mutating resident draw-record buffers.
    if (renderFence_ != nullptr && renderFenceValue_ > 0)
    {
        exactGpuContext_.waitForFence(renderFence_, renderFenceValue_);
    }

    struct PageClearBatch
    {
        UINT64 epoch{0};
        std::vector<std::uint32_t> recordIndices{};
    };

    // Keep batches bounded so we never risk exhausting the per-submission upload scratch.
    static constexpr std::size_t kMaxClearIndicesPerPage = 4096u;

    // Group by page so we can dispatch one clear per page.
    std::unordered_map<std::uint32_t, PageClearBatch> pageToBatches;
    pageToBatches.reserve(clears.size());
    std::vector<PendingExactDrawRecordClear> deferred;

    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        for (const PendingExactDrawRecordClear& clear : clears)
        {
            if (clear.pageIndex >= bufferPages_.size())
            {
                continue;
            }

            ChunkBufferPage& page = bufferPages_[clear.pageIndex];
            if (page.usage != ChunkBufferPageUsage::ExactGpu ||
                page.drawRecordBuffer == nullptr ||
                page.drawRecordEpoch != clear.pageEpoch)
            {
                continue;
            }

            PageClearBatch& batch = pageToBatches[clear.pageIndex];
            if (batch.epoch == 0)
            {
                batch.epoch = clear.pageEpoch;
            }
            if (batch.epoch != clear.pageEpoch)
            {
                continue;
            }

            if (batch.recordIndices.size() < kMaxClearIndicesPerPage)
            {
                batch.recordIndices.push_back(clear.recordIndex);
            }
            else
            {
                deferred.push_back(clear);
            }
        }

        for (auto& [pageIndex, batch] : pageToBatches)
        {
            if (pageIndex >= bufferPages_.size() || batch.recordIndices.empty())
            {
                continue;
            }

            ChunkBufferPage& page = bufferPages_[pageIndex];
            if (page.drawRecordEpoch != batch.epoch)
            {
                continue;
            }

            // Deduplicate to avoid wasted dispatch work under churn.
            std::sort(batch.recordIndices.begin(), batch.recordIndices.end());
            batch.recordIndices.erase(std::unique(batch.recordIndices.begin(), batch.recordIndices.end()),
                                      batch.recordIndices.end());
            if (batch.recordIndices.empty())
            {
                continue;
            }

            const D3D12_RESOURCE_STATES desiredState =
                (page.state == ChunkBufferPageState::OpenWritable)
                    ? D3D12_RESOURCE_STATE_UNORDERED_ACCESS
                    : D3D12_RESOURCE_STATE_COMMON;

            if (page.drawRecordState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS)
            {
                exactGpuContext_.transition(page.drawRecordBuffer.Get(),
                                            page.drawRecordState,
                                            D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
                page.drawRecordState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
            }

            const bool cleared =
                exactGpuContext_.clearExactDrawRecordReservedFlags(page.drawRecordBuffer.Get(),
                                                                  std::span<const std::uint32_t>(batch.recordIndices));
            if (!cleared)
            {
                // If we fail to record the clear (typically scratch exhaustion), keep the work queued.
                for (std::uint32_t recordIndex : batch.recordIndices)
                {
                    deferred.push_back(PendingExactDrawRecordClear{pageIndex, recordIndex, batch.epoch});
                }
            }

            if (page.drawRecordState != desiredState)
            {
                exactGpuContext_.transition(page.drawRecordBuffer.Get(),
                                            page.drawRecordState,
                                            desiredState);
                page.drawRecordState = desiredState;
            }
        }
    }

    const FarLodGpuContext::FlushResult flushResult = exactGpuContext_.flush();
    if (flushResult.fenceValue != 0)
    {
        exactGpuContext_.releaseSubmissionSlot(flushResult.submissionSlotIndex);
    }

    if (!deferred.empty())
    {
        std::lock_guard<std::mutex> lock(pendingExactDrawRecordClearsMutex_);
        pendingExactDrawRecordClears_.insert(pendingExactDrawRecordClears_.end(), deferred.begin(), deferred.end());
    }
}

ChunkManager::Impl::ChunkBufferPage ChunkManager::Impl::createBufferPage(std::size_t vertexCount,
                                                                         std::size_t indexCount,
                                                                         ChunkBufferPageUsage usage)
{
    static constexpr std::size_t kDefaultVertexCapacity = 65536;
    static constexpr std::size_t kDefaultIndexCapacity = 98304;

    ChunkBufferPage page;
    page.usage = usage;
    if (usage == ChunkBufferPageUsage::ExactGpu)
    {
        page.faceCapacity = std::max(nextPowerOfTwo(std::max<std::size_t>(vertexCount, 1u)),
                                     kDefaultExactFaceCapacity);
        page.recordCapacity = std::max<std::size_t>(1u, page.faceCapacity / kExactGpuInitialFaceCapacity);
    }
    else
    {
        page.vertexCapacity = std::max(nextPowerOfTwo(vertexCount), kDefaultVertexCapacity);
        page.indexCapacity = std::max(nextPowerOfTwo(indexCount), kDefaultIndexCapacity);
        page.recordCapacity = std::max<std::size_t>(
            1,
            std::min(page.vertexCapacity / 4u, page.indexCapacity / 6u));
        page.vertexBuffer = createDefaultBuffer(device_.Get(),
                                                static_cast<std::uint64_t>(page.vertexCapacity * sizeof(Vertex)),
                                                D3D12_RESOURCE_STATE_COMMON,
                                                D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
        page.indexBuffer = createDefaultBuffer(device_.Get(),
                                               static_cast<std::uint64_t>(page.indexCapacity * sizeof(std::uint32_t)),
                                               D3D12_RESOURCE_STATE_COMMON,
                                               D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
    }
    page.drawRecordBuffer = createDefaultBuffer(device_.Get(),
                                                static_cast<std::uint64_t>(
                                                    page.recordCapacity *
                                                    ((usage == ChunkBufferPageUsage::ExactGpu)
                                                         ? sizeof(ExactChunkRenderBatch::GpuCullRecord)
                                                         : sizeof(ChunkRenderBatch::GpuCullRecord))),
                                                D3D12_RESOURCE_STATE_COMMON,
                                                D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
    if (usage == ChunkBufferPageUsage::ExactGpu)
    {
        page.faceDescriptorBuffer = createDefaultBuffer(
            device_.Get(),
            static_cast<std::uint64_t>(page.faceCapacity * 32u),
            D3D12_RESOURCE_STATE_COMMON,
            D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
        page.drawRecordMetadataBuffer = createDefaultBuffer(
            device_.Get(),
            static_cast<std::uint64_t>(page.recordCapacity * sizeof(FarLodGpuContext::ExactDrawRecordMetadata)),
            D3D12_RESOURCE_STATE_COMMON,
            D3D12_RESOURCE_FLAG_ALLOW_UNORDERED_ACCESS);
        page.exactFaceDescriptorUavDescriptorIndex = exactGpuContext_.allocatePersistentDescriptorRange(3u);
        page.exactDrawRecordUavDescriptorIndex = page.exactFaceDescriptorUavDescriptorIndex + 1u;
        page.exactDrawRecordMetadataUavDescriptorIndex = page.exactFaceDescriptorUavDescriptorIndex + 2u;
        exactGpuContext_.writePersistentStructuredUavDescriptor(
            page.exactFaceDescriptorUavDescriptorIndex,
            page.faceDescriptorBuffer.Get(),
            0,
            static_cast<std::uint32_t>(page.faceCapacity),
            32u);
        exactGpuContext_.writePersistentStructuredUavDescriptor(
            page.exactDrawRecordUavDescriptorIndex,
            page.drawRecordBuffer.Get(),
            0,
            static_cast<std::uint32_t>(page.recordCapacity),
            static_cast<std::uint32_t>(sizeof(ExactChunkRenderBatch::GpuCullRecord)));
        exactGpuContext_.writePersistentStructuredUavDescriptor(
            page.exactDrawRecordMetadataUavDescriptorIndex,
            page.drawRecordMetadataBuffer.Get(),
            0,
            static_cast<std::uint32_t>(page.recordCapacity),
            static_cast<std::uint32_t>(sizeof(FarLodGpuContext::ExactDrawRecordMetadata)));
    }
    if (usage == ChunkBufferPageUsage::CpuUpload)
    {
        ensureChunkBufferPageUploadBuffers(page);
    }
    page.vertexView.BufferLocation = page.vertexBuffer ? page.vertexBuffer->GetGPUVirtualAddress() : 0;
    page.vertexView.SizeInBytes = static_cast<UINT>(page.vertexCapacity * sizeof(Vertex));
    page.vertexView.StrideInBytes = sizeof(Vertex);
    page.indexView.BufferLocation = page.indexBuffer ? page.indexBuffer->GetGPUVirtualAddress() : 0;
    page.indexView.SizeInBytes = static_cast<UINT>(page.indexCapacity * sizeof(std::uint32_t));
    page.indexView.Format = DXGI_FORMAT_R32_UINT;
    resetChunkBufferPage(page);

    if (exactUploadDebugLoggingEnabled())
    {
        std::ostringstream stream;
        const std::uint64_t vertexBytes = static_cast<std::uint64_t>(page.vertexCapacity * sizeof(Vertex));
        const std::uint64_t indexBytes = static_cast<std::uint64_t>(page.indexCapacity * sizeof(std::uint32_t));
        const std::uint64_t faceDescriptorBytes = static_cast<std::uint64_t>(page.faceCapacity * 32u);
        const std::uint64_t recordBytes =
            static_cast<std::uint64_t>(
                page.recordCapacity *
                ((usage == ChunkBufferPageUsage::ExactGpu)
                     ? sizeof(ExactChunkRenderBatch::GpuCullRecord)
                     : sizeof(ChunkRenderBatch::GpuCullRecord)));
        const std::uint64_t metadataBytes =
            (page.drawRecordMetadataBuffer != nullptr)
                ? static_cast<std::uint64_t>(page.recordCapacity * sizeof(FarLodGpuContext::ExactDrawRecordMetadata))
                : 0u;
        stream << "exact upload page created"
               << " usage=" << chunkBufferPageUsageLabel(page.usage)
               << " faceCapacity=" << page.faceCapacity
               << " vertexCapacity=" << page.vertexCapacity
               << " indexCapacity=" << page.indexCapacity
               << " recordCapacity=" << page.recordCapacity
               << " totalPageMiB="
               << std::fixed << std::setprecision(2)
               << (static_cast<double>(vertexBytes + indexBytes + faceDescriptorBytes + recordBytes + metadataBytes +
                                       ((page.vertexUploadBuffer != nullptr) ? vertexBytes : 0u) +
                                       ((page.indexUploadBuffer != nullptr) ? indexBytes : 0u)) /
                   (1024.0 * 1024.0));
        exactUploadDebugLog(stream.str());
    }

    return page;
}

void ChunkManager::Impl::resetChunkBufferPage(ChunkBufferPage& page) noexcept
{
    page.drawRecordEpoch = (page.drawRecordEpoch == std::numeric_limits<UINT64>::max())
                               ? 1u
                               : (page.drawRecordEpoch + 1u);
    page.vertexCursor = 0;
    page.indexCursor = 0;
    page.faceCursor = 0;
    page.recordCursor = 0;
    page.recordActiveCount = 0;
    page.vertexState = D3D12_RESOURCE_STATE_COMMON;
    page.indexState = D3D12_RESOURCE_STATE_COMMON;
    page.faceDescriptorState = D3D12_RESOURCE_STATE_COMMON;
    page.drawRecordState = D3D12_RESOURCE_STATE_COMMON;
    page.drawRecordMetadataState = D3D12_RESOURCE_STATE_COMMON;
    page.residentChunks = 0;
    page.pendingChunks = 0;
    page.allocatorShard = 0;
    page.lastWriteFenceValue = 0;
    page.sealRequested = false;
    page.liveResidentChunkCount = 0;
    page.inactiveResidentRecordCount = 0;
    page.abandonedOpenReservationCount = 0;
    page.lastReservationAt = SteadyClock::time_point{};
    page.pendingBatchId = 0;
    page.uploadFenceValue = 0;
    page.retireFenceValue = 0;
    page.exactChunkMembers.clear();
    page.exactPendingPublishCoords.clear();
    page.exactChunkMemberCount = 0;
    page.exactPendingPublishCount = 0;
    page.sealRequestedQueued = false;
    page.sealedPendingResidentQueued = false;
    page.readyToResidentQueued = false;
    page.residentQueued = false;
    page.state = ChunkBufferPageState::Free;
}

void ChunkManager::Impl::addChunkToExactPageMembers(std::uint32_t pageIndex, const glm::ivec3& coord)
{
    if (pageIndex >= bufferPages_.size())
    {
        return;
    }

    ChunkBufferPage& page = bufferPages_[pageIndex];
    if (page.usage != ChunkBufferPageUsage::ExactGpu)
    {
        return;
    }

    page.exactChunkMembers.insert(coord);
    page.exactChunkMemberCount = page.exactChunkMembers.size();
}

void ChunkManager::Impl::removeChunkFromExactPageMembers(std::uint32_t pageIndex, const glm::ivec3& coord)
{
    if (pageIndex >= bufferPages_.size())
    {
        return;
    }

    ChunkBufferPage& page = bufferPages_[pageIndex];
    if (page.usage != ChunkBufferPageUsage::ExactGpu)
    {
        return;
    }

    page.exactChunkMembers.erase(coord);
    page.exactChunkMemberCount = page.exactChunkMembers.size();
    page.exactPendingPublishCoords.erase(
        std::remove(page.exactPendingPublishCoords.begin(), page.exactPendingPublishCoords.end(), coord),
        page.exactPendingPublishCoords.end());
    page.exactPendingPublishCount = page.exactPendingPublishCoords.size();
}

void ChunkManager::Impl::queueChunkForExactPagePublish(std::uint32_t pageIndex, const glm::ivec3& coord)
{
    if (pageIndex >= bufferPages_.size())
    {
        return;
    }

    ChunkBufferPage& page = bufferPages_[pageIndex];
    if (page.usage != ChunkBufferPageUsage::ExactGpu ||
        !page.exactChunkMembers.contains(coord))
    {
        return;
    }

    const auto it = std::find(page.exactPendingPublishCoords.begin(),
                              page.exactPendingPublishCoords.end(),
                              coord);
    if (it == page.exactPendingPublishCoords.end())
    {
        page.exactPendingPublishCoords.push_back(coord);
        page.exactPendingPublishCount = page.exactPendingPublishCoords.size();
    }
}

std::vector<glm::ivec3> ChunkManager::Impl::drainExactPagePublishList(std::uint32_t pageIndex)
{
    if (pageIndex >= bufferPages_.size())
    {
        return {};
    }

    ChunkBufferPage& page = bufferPages_[pageIndex];
    if (page.usage != ChunkBufferPageUsage::ExactGpu || page.exactPendingPublishCoords.empty())
    {
        return {};
    }

    std::vector<glm::ivec3> publishCoords = std::move(page.exactPendingPublishCoords);
    page.exactPendingPublishCoords.clear();
    page.exactPendingPublishCount = 0;
    return publishCoords;
}

std::size_t ChunkManager::Impl::exactReservationShardIndexForChunk(const glm::ivec3& chunkCoord) const noexcept
{
    const std::uint64_t x = static_cast<std::uint64_t>(static_cast<std::int64_t>(chunkCoord.x));
    const std::uint64_t z = static_cast<std::uint64_t>(static_cast<std::int64_t>(chunkCoord.z));
    const std::uint64_t mixed = (x * 0x9E3779B185EBCA87ull) ^ (z * 0xC2B2AE3D27D4EB4Full);
    return static_cast<std::size_t>(mixed % kExactReservationShardCount);
}

bool ChunkManager::Impl::shouldSealExactOpenPageForAbandonment(const ChunkBufferPage& page) noexcept
{
    if (page.recordCapacity == 0u)
    {
        return true;
    }

    const std::size_t sealThreshold = std::max<std::size_t>(1u, page.recordCapacity / 4u);
    return page.abandonedOpenReservationCount >= sealThreshold;
}

void ChunkManager::Impl::requestExactPageLifecycleSeals()
{
    const SteadyClock::time_point now = SteadyClock::now();
    for (ExactReservationShard& shard : exactReservationShards_)
    {
        std::lock_guard<std::mutex> shardLock(shard.mutex);
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        shard.openPageIndices.erase(std::remove_if(shard.openPageIndices.begin(),
                                                   shard.openPageIndices.end(),
                                                   [this](std::uint32_t pageIndex)
                                                   {
                                                       if (pageIndex >= bufferPages_.size())
                                                       {
                                                           return true;
                                                       }

                                                       const ChunkBufferPage& page = bufferPages_[pageIndex];
                                                       return page.usage != ChunkBufferPageUsage::ExactGpu ||
                                                              page.state != ChunkBufferPageState::OpenWritable ||
                                                              page.sealRequested;
                                                   }),
                                   shard.openPageIndices.end());

        std::vector<std::uint32_t> openPages = shard.openPageIndices;
        std::sort(openPages.begin(),
                  openPages.end(),
                  [this](std::uint32_t lhs, std::uint32_t rhs)
                  {
                      const ChunkBufferPage& left = bufferPages_[lhs];
                      const ChunkBufferPage& right = bufferPages_[rhs];
                      if (left.lastReservationAt != right.lastReservationAt)
                      {
                          return left.lastReservationAt < right.lastReservationAt;
                      }
                      return lhs < rhs;
                  });

        for (const std::uint32_t pageIndex : openPages)
        {
            ChunkBufferPage& page = bufferPages_[pageIndex];
            if (page.sealRequested)
            {
                continue;
            }

            const bool idleTooLong =
                page.lastReservationAt != SteadyClock::time_point{} &&
                now - page.lastReservationAt >= kExactOpenPageIdleSealTimeout;
            if (idleTooLong)
            {
                requestSealExactPageLocked(pageIndex, ExactPageSealReason::Idle);
            }
        }

        if (openPages.size() > kExactReservationShardSoftOpenPageLimit)
        {
            const std::size_t excessCount = openPages.size() - kExactReservationShardSoftOpenPageLimit;
            for (std::size_t i = 0; i < excessCount; ++i)
            {
                if (openPages[i] < bufferPages_.size())
                {
                    requestSealExactPageLocked(openPages[i], ExactPageSealReason::AllocatorBackpressure);
                }
            }
        }
    }
}

void ChunkManager::Impl::transitionExactPageToWritable(std::uint32_t pageIndex, ChunkBufferPage& page)
{
    (void)pageIndex;
    assert(page.usage == ChunkBufferPageUsage::ExactGpu);
    assert(page.state == ChunkBufferPageState::OpenWritable);
    if (page.faceDescriptorBuffer != nullptr)
    {
        exactGpuContext_.transition(page.faceDescriptorBuffer.Get(),
                                    page.faceDescriptorState,
                                    D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
        page.faceDescriptorState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
    }
    if (page.drawRecordBuffer != nullptr)
    {
        exactGpuContext_.transition(page.drawRecordBuffer.Get(),
                                    page.drawRecordState,
                                    D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
        page.drawRecordState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
    }
    if (page.drawRecordMetadataBuffer != nullptr)
    {
        exactGpuContext_.transition(page.drawRecordMetadataBuffer.Get(),
                                    page.drawRecordMetadataState,
                                    D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
        page.drawRecordMetadataState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
    }
}

void ChunkManager::Impl::transitionExactPageToResident(std::uint32_t pageIndex, ChunkBufferPage& page)
{
    (void)pageIndex;
    assert(page.usage == ChunkBufferPageUsage::ExactGpu);
    assert(page.state == ChunkBufferPageState::SealedPendingResident);
    if (page.faceDescriptorBuffer != nullptr)
    {
        exactGpuContext_.transition(page.faceDescriptorBuffer.Get(),
                                    page.faceDescriptorState,
                                    D3D12_RESOURCE_STATE_COMMON);
        page.faceDescriptorState = D3D12_RESOURCE_STATE_COMMON;
    }
    if (page.drawRecordBuffer != nullptr)
    {
        exactGpuContext_.transition(page.drawRecordBuffer.Get(), page.drawRecordState, D3D12_RESOURCE_STATE_COMMON);
        page.drawRecordState = D3D12_RESOURCE_STATE_COMMON;
    }
    if (page.drawRecordMetadataBuffer != nullptr)
    {
        exactGpuContext_.transition(page.drawRecordMetadataBuffer.Get(),
                                    page.drawRecordMetadataState,
                                    D3D12_RESOURCE_STATE_COMMON);
        page.drawRecordMetadataState = D3D12_RESOURCE_STATE_COMMON;
    }
}

ChunkManager::Impl::ChunkBufferPage* ChunkManager::Impl::acquireOrCreateOpenExactPage(ExactReservationShard& shard,
                                                                                        std::size_t minFaceCount,
                                                                                        std::size_t minRecordCount,
                                                                                        UINT64 uploadBatchId,
                                                                                        std::uint32_t& pageIndex,
                                                                                        bool& hardResourceFailure)
{
    hardResourceFailure = false;
    const std::size_t predictedFaceCapacity =
        std::max(nextPowerOfTwo(std::max<std::size_t>(minFaceCount, 1u)), kDefaultExactFaceCapacity);
    const std::size_t predictedRecordCapacity =
        std::max<std::size_t>(1u, predictedFaceCapacity / kExactGpuInitialFaceCapacity);
    std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
    shard.openPageIndices.erase(std::remove_if(shard.openPageIndices.begin(),
                                               shard.openPageIndices.end(),
                                               [this](std::uint32_t candidateIndex)
                                               {
                                                   if (candidateIndex >= bufferPages_.size())
                                                   {
                                                       return true;
                                                   }

                                                   const ChunkBufferPage& page = bufferPages_[candidateIndex];
                                                   return page.usage != ChunkBufferPageUsage::ExactGpu ||
                                                          page.state != ChunkBufferPageState::OpenWritable ||
                                                          page.sealRequested;
                                               }),
                               shard.openPageIndices.end());
    const std::size_t openPageCount = shard.openPageIndices.size();
    for (std::size_t openPageOrdinal = 0; openPageOrdinal < openPageCount; ++openPageOrdinal)
    {
        const std::uint32_t candidateIndex = shard.openPageIndices[openPageOrdinal];
        ChunkBufferPage& page = bufferPages_[candidateIndex];
        page.pendingBatchId = uploadBatchId;
        pageIndex = candidateIndex;
        return &page;
    }

    for (std::uint32_t candidateIndex = 0; candidateIndex < bufferPages_.size(); ++candidateIndex)
    {
        ChunkBufferPage& page = bufferPages_[candidateIndex];
        if (page.usage != ChunkBufferPageUsage::ExactGpu ||
            page.state != ChunkBufferPageState::Free ||
            page.faceCapacity < minFaceCount ||
            page.recordCapacity < minRecordCount)
        {
            continue;
        }

        resetChunkBufferPage(page);
        page.usage = ChunkBufferPageUsage::ExactGpu;
        page.state = ChunkBufferPageState::OpenWritable;
        page.pendingBatchId = uploadBatchId;
        page.allocatorShard = static_cast<std::uint32_t>(&shard - exactReservationShards_.data());
        if (freeExactGpuPageCount_ > 0)
        {
            --freeExactGpuPageCount_;
        }
        pageIndex = candidateIndex;
        shard.openPageIndices.push_back(pageIndex);
        noteExactGpuPageMetadataChange(pageIndex);
        return &page;
    }

    ChunkBufferPage newPage{};
    std::size_t exactOpenWritablePages = 0u;
    std::size_t exactSealedPendingResidentPages = 0u;
    std::size_t exactResidentImmutablePages = 0u;
    std::size_t exactFreePages = 0u;
    for (const ChunkBufferPage& page : bufferPages_)
    {
        if (page.usage != ChunkBufferPageUsage::ExactGpu)
        {
            continue;
        }

        switch (page.state)
        {
        case ChunkBufferPageState::OpenWritable:
            ++exactOpenWritablePages;
            break;
        case ChunkBufferPageState::SealedPendingResident:
            ++exactSealedPendingResidentPages;
            break;
        case ChunkBufferPageState::ResidentImmutable:
            ++exactResidentImmutablePages;
            break;
        case ChunkBufferPageState::Free:
            ++exactFreePages;
            break;
        case ChunkBufferPageState::Retiring:
            break;
        }
    }
    try
    {
        newPage = createBufferPage(minFaceCount, minRecordCount, ChunkBufferPageUsage::ExactGpu);
    }
    catch (const std::exception& ex)
    {
        pageIndex = kInvalidChunkBufferPage;
        hardResourceFailure = true;
        recordExactGpuReservationFailureDebug(static_cast<std::uint32_t>(
                                                  std::min<std::size_t>(minFaceCount,
                                                                        static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max()))),
                                              predictedFaceCapacity,
                                              predictedRecordCapacity,
                                              freeExactGpuPageCount_,
                                              exactOpenWritablePages,
                                              exactSealedPendingResidentPages,
                                              exactResidentImmutablePages,
                                              exactFreePages,
                                              ex.what());
        return nullptr;
    }
    catch (...)
    {
        pageIndex = kInvalidChunkBufferPage;
        hardResourceFailure = true;
        recordExactGpuReservationFailureDebug(static_cast<std::uint32_t>(
                                                  std::min<std::size_t>(minFaceCount,
                                                                        static_cast<std::size_t>(std::numeric_limits<std::uint32_t>::max()))),
                                              predictedFaceCapacity,
                                              predictedRecordCapacity,
                                              freeExactGpuPageCount_,
                                              exactOpenWritablePages,
                                              exactSealedPendingResidentPages,
                                              exactResidentImmutablePages,
                                              exactFreePages,
                                              "non-std exception");
        return nullptr;
    }

    newPage.usage = ChunkBufferPageUsage::ExactGpu;
    newPage.state = ChunkBufferPageState::OpenWritable;
    newPage.pendingBatchId = uploadBatchId;
    newPage.allocatorShard = static_cast<std::uint32_t>(&shard - exactReservationShards_.data());
    bufferPages_.push_back(std::move(newPage));
    noteExactGpuEmitConfigRefresh();
    pageIndex = static_cast<std::uint32_t>(bufferPages_.size() - 1u);
    shard.openPageIndices.push_back(pageIndex);
    noteExactGpuPageMetadataChange(pageIndex);
    return &bufferPages_.back();
}

ChunkManager::Impl::ExactReservationResult ChunkManager::Impl::reserveExactOutputRange(
    const glm::ivec3& chunkCoord,
    std::uint32_t requiredFaceCount,
    UINT64 uploadBatchId,
    ChunkAllocation& allocation,
    std::uint32_t& reservedFaceCapacity)
{
    allocation = {};
    reservedFaceCapacity = 0u;
    if (requiredFaceCount == 0u ||
        uploadBatchId == 0u)
    {
        return ExactReservationResult::HardResourceFailure;
    }

    ExactReservationShard& shard = exactReservationShards_[exactReservationShardIndexForChunk(chunkCoord)];
    std::lock_guard<std::mutex> shardLock(shard.mutex);
    std::size_t attemptsRemaining = shard.openPageIndices.size() + 1u;
    while (attemptsRemaining-- > 0u)
    {
        std::uint32_t openPageIndex = kInvalidChunkBufferPage;
        bool hardResourceFailure = false;
        ChunkBufferPage* openPage = acquireOrCreateOpenExactPage(
            shard,
            requiredFaceCount,
            1u,
            uploadBatchId,
            openPageIndex,
            hardResourceFailure);
        if (openPage == nullptr)
        {
            return hardResourceFailure ? ExactReservationResult::HardResourceFailure
                                       : ExactReservationResult::TemporaryAllocatorExhaustion;
        }

        if (openPage->faceCursor + requiredFaceCount > openPage->faceCapacity ||
            openPage->recordCursor + 1u > openPage->recordCapacity)
        {
            requestSealExactPage(openPageIndex, ExactPageSealReason::Capacity);
            continue;
        }

        allocation.pageIndex = openPageIndex;
        allocation.faceOffset = openPage->faceCursor;
        allocation.recordIndex = static_cast<std::uint32_t>(openPage->recordCursor);
        openPage->allocatorShard = static_cast<std::uint32_t>(exactReservationShardIndexForChunk(chunkCoord));
        openPage->faceCursor += requiredFaceCount;
        ++openPage->recordCursor;
        ++openPage->pendingChunks;
        openPage->lastReservationAt = SteadyClock::now();
        if (openPage->faceCursor == openPage->faceCapacity ||
            openPage->recordCursor == openPage->recordCapacity)
        {
            requestSealExactPage(openPageIndex, ExactPageSealReason::Capacity);
        }
        reservedFaceCapacity = requiredFaceCount;
        noteExactGpuPageMetadataChange(openPageIndex);
        return ExactReservationResult::Success;
    }

    return ExactReservationResult::TemporaryAllocatorExhaustion;
}

void ChunkManager::Impl::requestSealExactPageLocked(std::uint32_t pageIndex, ExactPageSealReason reason)
{
    switch (reason)
    {
    case ExactPageSealReason::Capacity:
    case ExactPageSealReason::AllocatorBackpressure:
    case ExactPageSealReason::Idle:
    case ExactPageSealReason::Abandonment:
        break;
    }

    if (pageIndex >= bufferPages_.size())
    {
        return;
    }

    ChunkBufferPage& page = bufferPages_[pageIndex];
    if (page.usage != ChunkBufferPageUsage::ExactGpu || page.state != ChunkBufferPageState::OpenWritable)
    {
        return;
    }

    page.sealRequested = true;
    if (!page.sealRequestedQueued)
    {
        sealRequestedPageIndices_.push_back(pageIndex);
        page.sealRequestedQueued = true;
    }
}

void ChunkManager::Impl::requestSealExactPage(std::uint32_t pageIndex, ExactPageSealReason reason)
{
    std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
    requestSealExactPageLocked(pageIndex, reason);
}

void ChunkManager::Impl::drainSealRequestedExactPages()
{
    std::array<std::unique_lock<std::mutex>, kExactReservationShardCount> shardLocks{};
    for (std::size_t shardIndex = 0; shardIndex < kExactReservationShardCount; ++shardIndex)
    {
        shardLocks[shardIndex] = std::unique_lock<std::mutex>(exactReservationShards_[shardIndex].mutex);
    }

    std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
    while (!sealRequestedPageIndices_.empty())
    {
        const std::uint32_t pageIndex = sealRequestedPageIndices_.front();
        sealRequestedPageIndices_.pop_front();
        if (pageIndex >= bufferPages_.size())
        {
            continue;
        }

        ChunkBufferPage& page = bufferPages_[pageIndex];
        page.sealRequestedQueued = false;
        if (page.usage != ChunkBufferPageUsage::ExactGpu ||
            page.state != ChunkBufferPageState::OpenWritable ||
            !page.sealRequested)
        {
            continue;
        }

        ExactReservationShard& shard = exactReservationShards_[page.allocatorShard];
        shard.openPageIndices.erase(std::remove(shard.openPageIndices.begin(),
                                                shard.openPageIndices.end(),
                                                pageIndex),
                                    shard.openPageIndices.end());
        page.state = ChunkBufferPageState::SealedPendingResident;
        page.pendingBatchId = 0;
        if (!page.sealedPendingResidentQueued)
        {
            sealedPendingResidentPageIndices_.push_back(pageIndex);
            page.sealedPendingResidentQueued = true;
        }
        noteExactGpuPageMetadataChange(pageIndex);
    }
}

void ChunkManager::Impl::advanceExactPageResidencyQueues(UINT64 completedGpuFenceValue)
{
    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        std::deque<std::uint32_t> stillSealedPendingResident;
        while (!sealedPendingResidentPageIndices_.empty())
        {
            const std::uint32_t pageIndex = sealedPendingResidentPageIndices_.front();
            sealedPendingResidentPageIndices_.pop_front();
            if (pageIndex >= bufferPages_.size())
            {
                continue;
            }

            ChunkBufferPage& page = bufferPages_[pageIndex];
            if (page.usage != ChunkBufferPageUsage::ExactGpu ||
                page.state != ChunkBufferPageState::SealedPendingResident)
            {
                page.sealedPendingResidentQueued = false;
                continue;
            }

            const bool waitingOnWrites =
                page.pendingChunks > 0 ||
                (page.lastWriteFenceValue != 0 && completedGpuFenceValue < page.lastWriteFenceValue);
            if (waitingOnWrites)
            {
                stillSealedPendingResident.push_back(pageIndex);
                continue;
            }

            page.sealedPendingResidentQueued = false;
            if (!page.readyToResidentQueued)
            {
                readyToResidentPageIndices_.push_back(pageIndex);
                page.readyToResidentQueued = true;
            }
        }
        sealedPendingResidentPageIndices_.swap(stillSealedPendingResident);
    }

    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        if (readyToResidentPageIndices_.empty())
        {
            return;
        }
    }

    std::unique_lock<std::mutex> exactLock(exactGpuExecutionMutex_);
    if (!exactGpuContext_.begin())
    {
        return;
    }

    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        while (!readyToResidentPageIndices_.empty())
        {
            const std::uint32_t pageIndex = readyToResidentPageIndices_.front();
            readyToResidentPageIndices_.pop_front();
            if (pageIndex >= bufferPages_.size())
            {
                continue;
            }

            ChunkBufferPage& page = bufferPages_[pageIndex];
            page.readyToResidentQueued = false;
            if (page.usage != ChunkBufferPageUsage::ExactGpu ||
                page.state != ChunkBufferPageState::SealedPendingResident ||
                page.pendingChunks > 0 ||
                (page.lastWriteFenceValue != 0 && completedGpuFenceValue < page.lastWriteFenceValue))
            {
                continue;
            }

            transitionExactPageToResident(pageIndex, page);
            if (page.liveResidentChunkCount > 0 || page.residentChunks > 0)
            {
                page.state = ChunkBufferPageState::ResidentImmutable;
                page.lastWriteFenceValue = 0;
                page.sealRequested = false;
                page.pendingBatchId = 0;
                releaseChunkBufferPageUploadBuffers(page);
                if (!page.residentQueued)
                {
                    residentPageIndices_.push_back(pageIndex);
                    page.residentQueued = true;
                }
            }
            else
            {
                resetChunkBufferPage(page);
                page.usage = ChunkBufferPageUsage::ExactGpu;
                ++freeExactGpuPageCount_;
            }
            noteExactGpuPageMetadataChange(pageIndex);
        }
    }

    const FarLodGpuContext::FlushResult transitionFlushResult = exactGpuContext_.flush();
    if (transitionFlushResult.fenceValue != 0)
    {
        exactGpuContext_.waitForFence(transitionFlushResult.fenceValue);
        exactGpuContext_.releaseSubmissionSlot(transitionFlushResult.submissionSlotIndex);
    }

    std::vector<std::uint32_t> residentPageIndices;
    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        while (!residentPageIndices_.empty())
        {
            const std::uint32_t pageIndex = residentPageIndices_.front();
            residentPageIndices_.pop_front();
            if (pageIndex >= bufferPages_.size())
            {
                continue;
            }

            bufferPages_[pageIndex].residentQueued = false;
            if (bufferPages_[pageIndex].usage == ChunkBufferPageUsage::ExactGpu &&
                bufferPages_[pageIndex].state == ChunkBufferPageState::ResidentImmutable)
            {
                residentPageIndices.push_back(pageIndex);
            }
        }
    }

    for (const std::uint32_t pageIndex : residentPageIndices)
    {
        publishResidentExactGpuPageChunksReady(pageIndex);
    }
}

void ChunkManager::Impl::releasePendingExactBuildAllocation(PendingExactGpuBuild& pending, bool emittedRecordWritten)
{
    if (!pending.hasAllocation())
    {
        pending.faceCapacity = 0u;
        return;
    }

    if (emittedRecordWritten &&
        pending.allocation.pageIndex < bufferPages_.size() &&
        pending.allocation.recordIndex != kInvalidExactGpuDrawRecordIndex)
    {
        enqueueExactDrawRecordInactive(pending.allocation.pageIndex,
                                       pending.allocation.recordIndex,
                                       false);
    }

    bool handledPersistentReservation = false;
    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        if (pending.allocation.pageIndex < bufferPages_.size())
        {
            ChunkBufferPage& page = bufferPages_[pending.allocation.pageIndex];
            if (page.usage == ChunkBufferPageUsage::ExactGpu)
            {
                if (page.pendingChunks > 0)
                {
                    --page.pendingChunks;
                }

                if (page.state == ChunkBufferPageState::OpenWritable)
                {
                    ++page.abandonedOpenReservationCount;
                    if (shouldSealExactOpenPageForAbandonment(page))
                    {
                        requestSealExactPageLocked(pending.allocation.pageIndex,
                                                   ExactPageSealReason::Abandonment);
                    }
                    noteExactGpuPageMetadataChange(pending.allocation.pageIndex);
                    handledPersistentReservation = true;
                }
                else if (page.state == ChunkBufferPageState::ResidentImmutable ||
                         page.state == ChunkBufferPageState::SealedPendingResident ||
                         page.state == ChunkBufferPageState::Retiring)
                {
                    ++page.inactiveResidentRecordCount;
                    noteExactGpuPageMetadataChange(pending.allocation.pageIndex);
                    handledPersistentReservation = true;
                }
                else if (page.state == ChunkBufferPageState::Free)
                {
                    handledPersistentReservation = true;
                }
            }
        }
    }

    if (!handledPersistentReservation)
    {
        releaseChunkAllocationRange(pending.allocation.pageIndex,
                                    0,
                                    0,
                                    0,
                                    0,
                                    false);
    }

    pending.allocation = {};
    pending.faceCapacity = 0u;
}

ChunkManager::Impl::ChunkAllocation ChunkManager::Impl::acquireChunkAllocation(std::size_t vertexCount,
                                                                               std::size_t indexCount,
                                                                               UINT64 uploadBatchId,
                                                                               ChunkBufferPageUsage usage)
{
    ChunkAllocation allocation{};
    if (vertexCount == 0 || indexCount == 0 || uploadBatchId == 0)
    {
        return allocation;
    }

    auto tryAllocateInPage = [&](ChunkBufferPage& page, std::uint32_t pageIndex) -> bool
    {
        if (page.state == ChunkBufferPageState::ResidentImmutable ||
            page.state == ChunkBufferPageState::Retiring)
        {
            assert(false && "exact persistent lifecycle forbids reserving from resident/retiring pages");
            return false;
        }

        if (page.state == ChunkBufferPageState::Retiring ||
            page.state == ChunkBufferPageState::SealedPendingResident)
        {
            return false;
        }

        if (page.state == ChunkBufferPageState::Free)
        {
            if (usage == ChunkBufferPageUsage::ExactGpu &&
                page.usage != ChunkBufferPageUsage::ExactGpu)
            {
                return false;
            }
            if (page.usage != usage && usage == ChunkBufferPageUsage::CpuUpload)
            {
                return false;
            }
            resetChunkBufferPage(page);
            page.usage = usage;
            page.state = ChunkBufferPageState::OpenWritable;
            page.pendingBatchId = uploadBatchId;
            if (usage == ChunkBufferPageUsage::ExactGpu && freeExactGpuPageCount_ > 0)
            {
                --freeExactGpuPageCount_;
            }
        }

        if (page.usage != usage)
        {
            return false;
        }
        if (page.state != ChunkBufferPageState::OpenWritable || page.pendingBatchId != uploadBatchId)
        {
            return false;
        }

        if (usage == ChunkBufferPageUsage::CpuUpload)
        {
            ensureChunkBufferPageUploadBuffers(page);
        }

        if (page.vertexCursor + vertexCount > page.vertexCapacity ||
            page.indexCursor + indexCount > page.indexCapacity ||
            page.recordCursor + 1 > page.recordCapacity)
        {
            return false;
        }

        allocation.pageIndex = pageIndex;
        allocation.vertexOffset = page.vertexCursor;
        allocation.indexOffset = page.indexCursor;
        allocation.recordIndex = static_cast<std::uint32_t>(page.recordCursor);
        page.vertexCursor += vertexCount;
        page.indexCursor += indexCount;
        ++page.recordCursor;
        ++page.pendingChunks;
        return true;
    };

    std::lock_guard<std::mutex> lock(bufferPageMutex_);
    for (std::uint32_t pageIndex = 0; pageIndex < bufferPages_.size(); ++pageIndex)
    {
        ChunkBufferPage& page = bufferPages_[pageIndex];
        if (tryAllocateInPage(page, pageIndex))
        {
            noteExactGpuPageMetadataChange(pageIndex);
            return allocation;
        }
    }

    ChunkBufferPage newPage{};
    try
    {
        newPage = createBufferPage(vertexCount, indexCount, usage);
    }
    catch (const std::exception& ex)
    {
        if (exactUploadDebugLoggingEnabled())
        {
            std::ostringstream stream;
            stream << "exact upload page creation failed"
                   << " usage=" << chunkBufferPageUsageLabel(usage)
                   << " requestVerts=" << vertexCount
                   << " requestIdx=" << indexCount
                   << " uploadBatchId=" << uploadBatchId
                   << " error=" << ex.what()
                   << " | " << summarizeChunkBufferPagesLocked();
            exactUploadDebugLog(stream.str());
        }
        throw;
    }
    newPage.usage = usage;
    newPage.state = ChunkBufferPageState::OpenWritable;
    newPage.pendingBatchId = uploadBatchId;
    bufferPages_.push_back(std::move(newPage));
    noteExactGpuEmitConfigRefresh();
    const std::uint32_t newIndex = static_cast<std::uint32_t>(bufferPages_.size() - 1);
    ChunkBufferPage& page = bufferPages_.back();
    const bool allocated = tryAllocateInPage(page, newIndex);
    (void)allocated;
    noteExactGpuPageMetadataChange(newIndex);
    return allocation;
}

void ChunkManager::Impl::sealPendingChunkUploadPages(UINT64 uploadBatchId, UINT64 uploadFenceValue)
{
    if (uploadBatchId == 0 || uploadFenceValue == 0)
    {
        return;
    }

    std::lock_guard<std::mutex> lock(bufferPageMutex_);
    for (ChunkBufferPage& page : bufferPages_)
    {
        if (page.usage != ChunkBufferPageUsage::CpuUpload ||
            page.state != ChunkBufferPageState::OpenWritable ||
            page.pendingBatchId != uploadBatchId)
        {
            continue;
        }

        page.state = ChunkBufferPageState::SealedPendingResident;
        page.pendingBatchId = 0;
        page.uploadFenceValue = uploadFenceValue;
        noteExactGpuPageMetadataChange(static_cast<std::uint32_t>(&page - bufferPages_.data()));
        if (exactUploadDebugLoggingEnabled())
        {
            std::ostringstream stream;
            stream << "exact upload page sealed"
                   << " page=" << (&page - bufferPages_.data())
                   << " uploadFence=" << uploadFenceValue
                   << " residentChunks=" << page.residentChunks
                   << " pendingChunks=" << page.pendingChunks
                   << " state=" << chunkBufferPageStateLabel(page.state);
            exactUploadDebugLog(stream.str());
        }
    }
}

std::size_t ChunkManager::Impl::targetWorldgenPageDependencyJobs() const noexcept
{
    if (shouldStop_.load(std::memory_order_acquire) || columnHeightPrefetchWorkerCount_ == 0)
    {
        return 0;
    }

    const std::size_t latencySensitiveBacklog =
        jobQueue_.outstanding(JobServiceClass::InitialVisible) +
        jobQueue_.outstanding(JobServiceClass::LocalInteraction);
    const bool exactOnly = renderSettings_.totalChunks <= renderSettings_.exactChunks;
    if (stationaryExactFillModeActive_)
    {
        return std::min<std::size_t>(columnHeightPrefetchWorkerCount_, 4u);
    }
    if (exactOnly && lastMissingChunks_ > 0)
    {
        if (severeProtectedPressureActive_ || latencySensitiveBacklog > 0)
        {
            return std::min<std::size_t>(columnHeightPrefetchWorkerCount_, 2u);
        }
        if (protectedPressureActive_)
        {
            return std::min<std::size_t>(columnHeightPrefetchWorkerCount_, 3u);
        }
        return columnHeightPrefetchWorkerCount_;
    }
    if (severeProtectedPressureActive_ || latencySensitiveBacklog > 0)
    {
        return 1;
    }
    if (protectedPressureActive_)
    {
        return std::min<std::size_t>(columnHeightPrefetchWorkerCount_, 1);
    }
    return columnHeightPrefetchWorkerCount_;
}

std::size_t ChunkManager::Impl::targetStructureRegionDependencyJobs() const noexcept
{
    if (shouldStop_.load(std::memory_order_acquire) || workerThreadCount_ == 0)
    {
        return 0;
    }

    const std::size_t latencySensitiveBacklog =
        jobQueue_.outstanding(JobServiceClass::InitialVisible) +
        jobQueue_.outstanding(JobServiceClass::LocalInteraction);
    if (stationaryExactFillModeActive_)
    {
        return std::min<std::size_t>(workerThreadCount_, 2u);
    }
    if (severeProtectedPressureActive_ || latencySensitiveBacklog > 0)
    {
        return 1;
    }
    if (protectedPressureActive_)
    {
        return std::min<std::size_t>(workerThreadCount_, 1u);
    }
    return std::min<std::size_t>(std::max<std::size_t>(workerThreadCount_ / 4, 1u), 2u);
}

JobServiceClass ChunkManager::Impl::highestQueuedWorldgenDependencyServiceClass() const noexcept
{
    std::lock_guard<std::mutex> lock(columnHeightPrefetchMutex_);
    if (pendingWorldgenPageDependencyQueue_.empty())
    {
        return JobServiceClass::Standard;
    }

    return pendingWorldgenPageDependencyQueue_.top().serviceClass;
}

JobServiceClass ChunkManager::Impl::highestQueuedStructureRegionDependencyServiceClass() const noexcept
{
    std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
    JobServiceClass best = JobServiceClass::Refinement;
    bool found = false;
    for (const auto& [_, entry] : structureRegionEntries_)
    {
        if (!entry.dependencyJobQueued || entry.state != StructureRegionState::Queued)
        {
            continue;
        }

        if (!found || jobServiceClassIndex(entry.serviceClass) < jobServiceClassIndex(best))
        {
            best = entry.serviceClass;
            found = true;
        }
    }

    return found ? best : JobServiceClass::Standard;
}

std::size_t ChunkManager::Impl::targetBulkShellOracleJobs() const noexcept
{
    if (shouldStop_.load(std::memory_order_acquire) || bulkShellOracleWorkerCount_ == 0 || !bulkShellOracleBatch_)
    {
        return 0;
    }

    if (bulkShellOracleBatch_->remainingFragments.load(std::memory_order_acquire) == 0)
    {
        return 0;
    }

    if (stationaryExactFillModeActive_)
    {
        return std::min<std::size_t>(bulkShellOracleWorkerCount_, 2u);
    }

    if (severeProtectedPressureActive_ || protectedPressureActive_)
    {
        return 0;
    }

    const std::size_t latencySensitiveBacklog =
        jobQueue_.outstanding(JobServiceClass::InitialVisible) +
        jobQueue_.outstanding(JobServiceClass::LocalInteraction);
    if (latencySensitiveBacklog > 0)
    {
        return 0;
    }

    return bulkShellOracleWorkerCount_;
}

std::size_t ChunkManager::Impl::worldgenPageDependencyQueueLimit(DependencyPriority priority,
                                                                 bool buildOccupancy) const noexcept
{
    const std::size_t workerScale = std::clamp<std::size_t>(columnHeightPrefetchWorkerCount_, 1u, 4u);
    if (stationaryExactFillModeActive_)
    {
        switch (priority)
        {
        case DependencyPriority::Critical:
            return 4096u * workerScale;
        case DependencyPriority::Visible:
            return (buildOccupancy ? 3072u : 2048u) * workerScale;
        case DependencyPriority::Background:
            return 256u * workerScale;
        }
    }

    switch (priority)
    {
    case DependencyPriority::Critical:
        return 512u * workerScale;
    case DependencyPriority::Visible:
        return (buildOccupancy ? 320u : 224u) * workerScale;
    case DependencyPriority::Background:
        return 48u * workerScale;
    }

    return 256u;
}

void ChunkManager::Impl::exactSupportWorldgenWindowBounds(const glm::ivec3& center,
                                                          int horizontalRadius,
                                                          int& minWorldX,
                                                          int& maxWorldX,
                                                          int& minWorldZ,
                                                          int& maxWorldZ) const noexcept
{
    const int radius = std::max(horizontalRadius, 0);
    const int exactMinWorldX = (center.x - radius) * kChunkSizeX;
    const int exactMaxWorldX = (center.x + radius + 1) * kChunkSizeX - 1;
    const int exactMinWorldZ = (center.z - radius) * kChunkSizeZ;
    const int exactMaxWorldZ = (center.z + radius + 1) * kChunkSizeZ - 1;
    constexpr int kStructureWorldgenPadding = kMaxStructureHorizontalRadius + 4;
    const int minRegionX = floorDiv(exactMinWorldX - kMaxStructureHorizontalRadius, kStructureRegionSize);
    const int maxRegionX = floorDiv(exactMaxWorldX + kMaxStructureHorizontalRadius, kStructureRegionSize);
    const int minRegionZ = floorDiv(exactMinWorldZ - kMaxStructureHorizontalRadius, kStructureRegionSize);
    const int maxRegionZ = floorDiv(exactMaxWorldZ + kMaxStructureHorizontalRadius, kStructureRegionSize);

    minWorldX = minRegionX * kStructureRegionSize - kStructureWorldgenPadding;
    maxWorldX = (maxRegionX + 1) * kStructureRegionSize - 1 + kStructureWorldgenPadding;
    minWorldZ = minRegionZ * kStructureRegionSize - kStructureWorldgenPadding;
    maxWorldZ = (maxRegionZ + 1) * kStructureRegionSize - 1 + kStructureWorldgenPadding;
}

void ChunkManager::Impl::resetFullRadiusWorldgenPageDiscovery(const glm::ivec3& center, int horizontalRadius) noexcept
{
    int minWorldX = 0;
    int maxWorldX = 0;
    int minWorldZ = 0;
    int maxWorldZ = 0;
    exactSupportWorldgenWindowBounds(center, horizontalRadius, minWorldX, maxWorldX, minWorldZ, maxWorldZ);
    fullRadiusWorldgenPageDiscovery_.centerPage = worldgenPageKeyForChunkColumn({center.x, center.z});
    fullRadiusWorldgenPageDiscovery_.minPage = worldgenPageKeyForWorld(minWorldX, minWorldZ);
    fullRadiusWorldgenPageDiscovery_.maxPage = worldgenPageKeyForWorld(maxWorldX, maxWorldZ);
    fullRadiusWorldgenPageDiscovery_.nextRing = 0;
    fullRadiusWorldgenPageDiscovery_.nextEdge = 0;
    fullRadiusWorldgenPageDiscovery_.nextOffset = 0;
    fullRadiusWorldgenPageDiscovery_.initialized = true;
}

bool ChunkManager::Impl::nextFullRadiusWorldgenPageDiscoveryPage(glm::ivec2& outPageKey,
                                                                 ColumnHeightPrefetchPriority& outPriority) noexcept
{
    if (!fullRadiusWorldgenPageDiscovery_.initialized)
    {
        return false;
    }

    const glm::ivec2 centerPage = fullRadiusWorldgenPageDiscovery_.centerPage;
    const glm::ivec2 minPage = fullRadiusWorldgenPageDiscovery_.minPage;
    const glm::ivec2 maxPage = fullRadiusWorldgenPageDiscovery_.maxPage;
    const int maxRing = std::max({std::abs(minPage.x - centerPage.x),
                                  std::abs(maxPage.x - centerPage.x),
                                  std::abs(minPage.y - centerPage.y),
                                  std::abs(maxPage.y - centerPage.y)});
    constexpr int kChunkColumnsPerWorldgenPage = WorldgenPage::kSize / kChunkSizeX;
    const int criticalChunkRadius = std::max(8, startupState_.exactNearCurrentChunks + 2);
    const int criticalPageRadius = std::max(0, (criticalChunkRadius + kChunkColumnsPerWorldgenPage - 1) /
                                                   kChunkColumnsPerWorldgenPage);
    auto tryEmit = [&](int pageX, int pageZ) -> bool
    {
        if (pageX < minPage.x || pageX > maxPage.x || pageZ < minPage.y || pageZ > maxPage.y)
        {
            return false;
        }

        outPageKey = {pageX, pageZ};
        return true;
    };
    while (fullRadiusWorldgenPageDiscovery_.nextRing <= maxRing)
    {
        const int ring = fullRadiusWorldgenPageDiscovery_.nextRing;
        outPriority = (ring <= criticalPageRadius)
            ? ColumnHeightPrefetchPriority::Critical
            : ColumnHeightPrefetchPriority::Visible;

        if (ring == 0)
        {
            ++fullRadiusWorldgenPageDiscovery_.nextRing;
            fullRadiusWorldgenPageDiscovery_.nextEdge = 0;
            fullRadiusWorldgenPageDiscovery_.nextOffset = 0;
            if (tryEmit(centerPage.x, centerPage.y))
            {
                return true;
            }
            continue;
        }

        if (fullRadiusWorldgenPageDiscovery_.nextEdge < 2)
        {
            if (fullRadiusWorldgenPageDiscovery_.nextOffset <= ring * 2)
            {
                const int dx = -ring + fullRadiusWorldgenPageDiscovery_.nextOffset;
                const int z = (fullRadiusWorldgenPageDiscovery_.nextEdge == 0) ? -ring : ring;
                ++fullRadiusWorldgenPageDiscovery_.nextOffset;
                if (tryEmit(centerPage.x + dx, centerPage.y + z))
                {
                    return true;
                }
                continue;
            }

            ++fullRadiusWorldgenPageDiscovery_.nextEdge;
            fullRadiusWorldgenPageDiscovery_.nextOffset = 1;
            continue;
        }

        if (fullRadiusWorldgenPageDiscovery_.nextOffset <= ring * 2 - 1)
        {
            const int dz = -ring + fullRadiusWorldgenPageDiscovery_.nextOffset;
            const int x = (fullRadiusWorldgenPageDiscovery_.nextEdge == 2) ? -ring : ring;
            ++fullRadiusWorldgenPageDiscovery_.nextOffset;
            if (tryEmit(centerPage.x + x, centerPage.y + dz))
            {
                return true;
            }
            continue;
        }

        ++fullRadiusWorldgenPageDiscovery_.nextRing;
        fullRadiusWorldgenPageDiscovery_.nextEdge = 0;
        fullRadiusWorldgenPageDiscovery_.nextOffset = 0;
    }

    return false;
}

void ChunkManager::Impl::precomputeFullRadiusWorldgenPageWindow(const glm::ivec3& center, int horizontalRadius)
{
    if (horizontalRadius <= 0 || shouldStop_.load(std::memory_order_acquire))
    {
        return;
    }

    int minWorldX = 0;
    int maxWorldX = 0;
    int minWorldZ = 0;
    int maxWorldZ = 0;
    exactSupportWorldgenWindowBounds(center, horizontalRadius, minWorldX, maxWorldX, minWorldZ, maxWorldZ);
    const glm::ivec2 centerPage = worldgenPageKeyForChunkColumn({center.x, center.z});
    const glm::ivec2 minPage = worldgenPageKeyForWorld(minWorldX, minWorldZ);
    const glm::ivec2 maxPage = worldgenPageKeyForWorld(maxWorldX, maxWorldZ);
    constexpr int kChunkColumnsPerWorldgenPage = WorldgenPage::kSize / kChunkSizeX;
    const int criticalChunkRadius = std::max(8, startupState_.exactNearCurrentChunks + 2);
    const int criticalPageRadius = std::max(0, (criticalChunkRadius + kChunkColumnsPerWorldgenPage - 1) /
                                                   kChunkColumnsPerWorldgenPage);

    struct PageCandidate
    {
        glm::ivec2 pageKey{0};
        ColumnHeightPrefetchPriority priority{ColumnHeightPrefetchPriority::Visible};
        int ringDistance{0};
    };

    std::vector<PageCandidate> candidates;
    candidates.reserve(static_cast<std::size_t>(std::max(maxPage.x - minPage.x + 1, 0)) *
                       static_cast<std::size_t>(std::max(maxPage.y - minPage.y + 1, 0)));
    for (int pageZ = minPage.y; pageZ <= maxPage.y; ++pageZ)
    {
        for (int pageX = minPage.x; pageX <= maxPage.x; ++pageX)
        {
            const int ringDistance = std::max(std::abs(pageX - centerPage.x), std::abs(pageZ - centerPage.y));
            candidates.push_back(PageCandidate{
                {pageX, pageZ},
                ringDistance <= criticalPageRadius ? ColumnHeightPrefetchPriority::Critical
                                                   : ColumnHeightPrefetchPriority::Visible,
                ringDistance});
        }
    }

    std::sort(candidates.begin(),
              candidates.end(),
              [](const PageCandidate& lhs, const PageCandidate& rhs)
              {
                  if (lhs.priority != rhs.priority)
                  {
                      return lhs.priority > rhs.priority;
                  }
                  if (lhs.ringDistance != rhs.ringDistance)
                  {
                      return lhs.ringDistance < rhs.ringDistance;
                  }
                  if (lhs.pageKey.x != rhs.pageKey.x)
                  {
                      return lhs.pageKey.x < rhs.pageKey.x;
                  }
                  return lhs.pageKey.y < rhs.pageKey.y;
              });

    for (const PageCandidate& candidate : candidates)
    {
        const DependencyPriority dependencyPriority =
            candidate.priority >= ColumnHeightPrefetchPriority::Critical ? DependencyPriority::Critical
            : candidate.priority >= ColumnHeightPrefetchPriority::Visible ? DependencyPriority::Visible
                                                                         : DependencyPriority::Background;
        (void)requestWorldgenPageDependency(candidate.pageKey,
                                            dependencyPriority,
                                            true,
                                            true,
                                            supportDependencyServiceClass(candidate.priority));
    }
}

bool ChunkManager::Impl::windowContainsColumn(const ExactWindowKey& key,
                                              const glm::ivec2& column,
                                              int margin) const noexcept
{
    const int effectiveRadius = std::max(key.preloadRadius + margin, 0);
    return std::abs(column.x - key.centerColumn.x) <= effectiveRadius &&
           std::abs(column.y - key.centerColumn.y) <= effectiveRadius;
}

bool ChunkManager::Impl::windowOverlapsWorldgenPage(const ExactWindowKey& key,
                                                    const glm::ivec2& pageKey,
                                                    int marginChunks) const noexcept
{
    glm::ivec2 minColumn{0};
    glm::ivec2 maxColumn{0};
    worldgenPageChunkColumnBounds(pageKey, minColumn, maxColumn);
    const int minWindowX = key.centerColumn.x - key.preloadRadius - 1 - marginChunks;
    const int maxWindowX = key.centerColumn.x + key.preloadRadius + 1 + marginChunks;
    const int minWindowZ = key.centerColumn.y - key.preloadRadius - 1 - marginChunks;
    const int maxWindowZ = key.centerColumn.y + key.preloadRadius + 1 + marginChunks;
    return !(maxColumn.x < minWindowX || minColumn.x > maxWindowX ||
             maxColumn.y < minWindowZ || minColumn.y > maxWindowZ);
}

bool ChunkManager::Impl::windowOverlapsStructureRegion(const ExactWindowKey& key,
                                                       const StructureRegionKey& regionKey,
                                                       int marginChunks) const noexcept
{
    const int minWorldX = regionKey.regionX * kStructureRegionSize - kMaxStructureHorizontalRadius;
    const int maxWorldX = (regionKey.regionX + 1) * kStructureRegionSize - 1 + kMaxStructureHorizontalRadius;
    const int minWorldZ = regionKey.regionZ * kStructureRegionSize - kMaxStructureHorizontalRadius;
    const int maxWorldZ = (regionKey.regionZ + 1) * kStructureRegionSize - 1 + kMaxStructureHorizontalRadius;
    const int minChunkX = floorDiv(minWorldX, kChunkSizeX);
    const int maxChunkX = floorDiv(maxWorldX, kChunkSizeX);
    const int minChunkZ = floorDiv(minWorldZ, kChunkSizeZ);
    const int maxChunkZ = floorDiv(maxWorldZ, kChunkSizeZ);
    const int minWindowX = key.centerColumn.x - key.preloadRadius - 1 - marginChunks;
    const int maxWindowX = key.centerColumn.x + key.preloadRadius + 1 + marginChunks;
    const int minWindowZ = key.centerColumn.y - key.preloadRadius - 1 - marginChunks;
    const int maxWindowZ = key.centerColumn.y + key.preloadRadius + 1 + marginChunks;
    return !(maxChunkX < minWindowX || minChunkX > maxWindowX ||
             maxChunkZ < minWindowZ || minChunkZ > maxWindowZ);
}

void ChunkManager::Impl::resetExactCoverageCache() noexcept
{
    std::lock_guard<std::mutex> lock(exactPlanMutex_);
    exactCoverageCache_ = ExactCoverageCacheState{};
}

void ChunkManager::Impl::notifyDiscontinuousCameraMove() noexcept
{
    pendingDiscontinuousCameraMove_.store(true, std::memory_order_release);
}

bool ChunkManager::Impl::consumePendingDiscontinuousCameraMove() noexcept
{
    return pendingDiscontinuousCameraMove_.exchange(false, std::memory_order_acq_rel);
}

bool ChunkManager::Impl::isDiscontinuousCameraMove(const glm::ivec3& centerChunk,
                                                   const glm::ivec3& previousCenterChunk) const noexcept
{
    if (updateFrameIndex_ <= 1)
    {
        return false;
    }

    const glm::ivec3 delta = centerChunk - previousCenterChunk;
    const int horizontalShift = std::max(std::abs(delta.x), std::abs(delta.z));
    const int verticalShift = std::abs(delta.y);
    const int horizontalThreshold = std::max(renderSettings_.exactChunks + 8, 24);
    const int verticalThreshold = std::max(lastVerticalRadius_ + 4, 16);
    return horizontalShift >= horizontalThreshold || verticalShift >= verticalThreshold;
}

void ChunkManager::Impl::resetStreamingForDiscontinuousMove(const glm::ivec3& centerChunk)
{
    stopExactGpuWorkerThread();
    stopWorkerThreads();
    uploadContext_.waitForIdle();
    stopExactPlanBuild();
    {
        std::lock_guard<std::mutex> lock(exactPlanMutex_);
        activeExactPlan_.reset();
    }
    stopBulkShellOracle();

    {
        std::lock_guard<std::mutex> lock(uploadQueueMutex_);
        for (auto& queue : uploadQueues_)
        {
            queue = {};
        }
        queuedUploadCount_ = 0;
        initialVisibleUploadCount_ = 0;
    }
    {
        std::lock_guard<std::mutex> lock(pendingCommitQueueMutex_);
        pendingCommitQueue_.clear();
    }
    deferredPendingChunkReleases_.clear();

    {
        std::lock_guard<std::mutex> localEditLock(queuedLocalEditMutex_);
        queuedLocalEditBatches_.clear();
    }
    {
        std::lock_guard<std::mutex> localUploadLock(dedicatedLocalUploadMutex_);
        queuedDedicatedLocalUploads_.clear();
    }
    {
        std::lock_guard<std::mutex> lock(queuedSkyLightColumnRefreshMutex_);
        queuedSkyLightColumnRefreshes_.clear();
    }
    {
        std::lock_guard<std::mutex> lock(queuedRelightMutex_);
        queuedRelightRequests_.clear();
    }
    {
        std::lock_guard<std::mutex> lock(relightStateMutex_);
        pendingRelightRegions_.clear();
        pendingRelightCoordGenerations_.clear();
        activeRelightCoordGenerations_.clear();
        activeRelightRegions_.clear();
        relightBudgetUnitsThisFrame_ = 0;
        relightBudgetUnitsRemaining_ = 0;
        relightBatchBudgetThisFrame_ = 0;
        relightBatchBudgetRemaining_ = 0;
        nextRelightGeneration_ = 1;
        nextPendingRelightSequence_ = 1;
    }
    activeRelightProcessors_.store(0, std::memory_order_release);
    {
        std::lock_guard<std::mutex> lock(queuedFarInvalidationMutex_);
        queuedFarInvalidationValid_ = false;
        queuedFarInvalidationMin_ = glm::ivec3{0};
        queuedFarInvalidationMax_ = glm::ivec3{0};
    }

    std::vector<std::shared_ptr<Chunk>> loadedChunks;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        loadedChunks.reserve(chunks_.size());
        for (auto& [coord, chunk] : chunks_)
        {
            (void)coord;
            loadedChunks.push_back(std::move(chunk));
        }
        chunks_.clear();
    }
    for (auto& chunk : loadedChunks)
    {
        if (!chunk)
        {
            continue;
        }
        recycleChunkGPU(*chunk);
        recycleChunkObject(std::move(chunk));
    }

    while (!pendingChunkRetires_.empty())
    {
        drainPendingChunkRetires();
    }
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        denseTrackedCoords_.clear();
    }
    clearResidencyIndex();
    pendingEvictionDiscoveryColumns_.clear();
    pendingEvictionDiscoveryColumnSet_.clear();
    pendingEvictionCandidates_.clear();
    pendingEvictionCandidateSet_.clear();
    lastEvictionQueryState_ = EvictionQueryState{};
    lastEvictionQueryStateValid_ = false;
    nextEvictionQueryGeneration_ = 1;

    farTerrainManager_.clear();
    columnManager_.clear();
    {
        std::lock_guard<std::mutex> lock(worldgenPageMutex_);
        worldgenPageEntries_.clear();
        pinnedWorldgenPageKeys_.clear();
        prefetchPageFrontier_ = PrefetchPageFrontierState{};
        structureRegionWorldgenPages_.clear();
    }
    invalidateAllColumnSlabOccupancy();
    {
        std::lock_guard<std::mutex> lock(predictedColumnMutex_);
        predictedColumnHeights_.clear();
    }
    {
        std::lock_guard<std::mutex> lock(skyLightCacheMutex_);
        skyLightColumnGenerations_.clear();
    }

    resetStreamingFrontier();
    clearStreamingChunkLifecycleStates();
    resetExactCoverageCache();
    fullRadiusWorldgenPageDiscovery_ = FullRadiusWorldgenPageDiscoveryState{};
    evictionCenterChunkY_ = centerChunk.y;
    evictionCenterInitialized_ = false;

    lastMissingChunks_ = 0;
    cachedExactReadyChunks_ = 0;
    cachedExactRequiredChunks_ = 0;
    lastProtectedMissingChunks_ = 0;
    lastProtectedReadyChunks_ = 0;
    lastProtectedRequiredChunks_ = 0;
    protectedPressureActive_ = false;
    severeProtectedPressureActive_ = false;
    stationaryExactFillModeActive_ = false;
    refinementBackpressureActive_.store(false, std::memory_order_release);
    smoothedFrameMs_ = 16.0;

    startupState_ = StartupStreamingState{};
    if (startupEnabled_)
    {
        startupState_.phase = StreamingPhase::ExactPreload;
        startupState_.preloadStarted = true;
        startupState_.spawnChunk = centerChunk;
        startupState_.exactNearCurrentChunks =
            std::clamp(startupExactPreloadChunks_, 1, renderSettings_.exactChunks);
        startupState_.playerReleaseReady = false;
    }
    else
    {
        startupState_.phase = StreamingPhase::SteadyState;
        startupState_.exactNearCurrentChunks = renderSettings_.exactChunks;
        startupState_.playerReleaseReady = true;
    }
    startupState_.farCurrentBlocks = 0;
    targetViewDistance_ = std::clamp(startupState_.exactNearCurrentChunks, 1, renderSettings_.exactChunks);
    if (viewDistance_ > targetViewDistance_)
    {
        viewDistance_ = targetViewDistance_;
    }

    const glm::vec2 forwardXZ = normalizePriorityForwardXZ(lastCameraForward_);
    movementEnvelopeForwardXZ_ = glm::dot(forwardXZ, forwardXZ) > kEpsilon ? forwardXZ : glm::vec2{0.0f, -1.0f};
    lastCameraForwardXZ_ = movementEnvelopeForwardXZ_;
    lastHorizontalMovementShift_ = 0;
    lastVerticalMovementShift_ = 0;
    movementEnvelopeStationarySeconds_ = 0.0;
    movementEnvelopeIdleMode_ = false;
    movementEnvelopeTurnActive_ = false;
    lastCenterChunk_ = centerChunk;
    lastJobQueuePriorityOrigin_ = centerChunk;
    lastJobQueuePriorityForwardXZ_ = movementEnvelopeForwardXZ_;
    lastJobQueuePriorityRefreshTime_ = SteadyClock::time_point{};
    {
        std::lock_guard<std::mutex> lock(schedulingPriorityMutex_);
        schedulingPriorityOrigin_ = centerChunk;
        schedulingPriorityForward_ = lastCameraForward_;
    }

    farTerrainManager_.setEnabled(renderSettings_.totalChunks > renderSettings_.exactChunks);
    farTerrainManager_.setDistanceBlocks(startupState_.farCurrentBlocks);
    startWorkerThreads();
    startExactGpuWorkerThread();
}

ChunkManager::Impl::ColumnPlanSummary
ChunkManager::Impl::buildExactCoverageColumnSummary(const glm::ivec2& column,
                                                    const glm::ivec2& cameraColumn,
                                                    int cameraChunkY,
                                                    int verticalRadius) const
{
    const ColumnSlabOccupancy occupancy = cachedColumnSlabOccupancy(column);
    const ColumnChunkIntervals playerBand =
        playerBandIntervalsForColumn(column, cameraColumn, cameraChunkY, verticalRadius);
    ColumnChunkIntervals requiredIntervals{};
    mergeColumnChunkIntervals(requiredIntervals, playerBand);
    if (!playerBand.empty())
    {
        mergeColumnChunkIntervals(requiredIntervals, occupancy.occupiedIntervals);
    }
    else
    {
        mergeColumnChunkIntervals(requiredIntervals, occupancy.surfaceShellIntervals);
        mergeColumnChunkIntervals(requiredIntervals, occupancy.waterIntervals);
        mergeColumnChunkIntervals(requiredIntervals, occupancy.structureIntervals);
        mergeColumnChunkIntervals(requiredIntervals, occupancy.editIntervals);
    }
    mergeColumnChunkIntervals(requiredIntervals, occupancy.maybeIntervals);
    return ColumnPlanSummary{playerBand, requiredIntervals, occupancy, occupancy.supportComplete};
}

ColumnChunkIntervals ChunkManager::Impl::materializeRequiredIntervals(const ColumnPlanSummary& summary) const
{
    ColumnChunkIntervals materialized{};
    if (summary.requiredIntervals.empty())
    {
        return materialized;
    }

    for (int chunkY = summary.requiredIntervals.minChunkY(); chunkY <= summary.requiredIntervals.maxChunkY(); ++chunkY)
    {
        if (!chunkYWithinIntervals(chunkY, summary.requiredIntervals))
        {
            continue;
        }

        const bool forceResident = chunkYWithinIntervals(chunkY, summary.playerBand);
        const bool required =
            forceResident ||
            !summary.supportComplete ||
            classifyColumnSlab(summary.occupancy, chunkY) != ColumnSlabOccupancyState::DefinitelyEmpty;
        if (required)
        {
            addColumnChunkInterval(materialized, chunkY, chunkY);
        }
    }

    return materialized;
}

int ChunkManager::Impl::countRequiredChunks(const ColumnChunkIntervals& intervals) noexcept
{
    int total = 0;
    for (std::uint8_t i = 0; i < intervals.count; ++i)
    {
        total += intervals.intervals[i].maxChunkY - intervals.intervals[i].minChunkY + 1;
    }
    return total;
}

void ChunkManager::Impl::removeStreamingFrontierColumnDemandsLocked(const glm::ivec2& column,
                                                                    const ColumnChunkIntervals& oldIntervals)
{
    if (oldIntervals.empty())
    {
        return;
    }

    for (int chunkY = oldIntervals.minChunkY(); chunkY <= oldIntervals.maxChunkY(); ++chunkY)
    {
        if (!chunkYWithinIntervals(chunkY, oldIntervals))
        {
            continue;
        }

        const glm::ivec3 coord{column.x, chunkY, column.y};
        auto it = streamingFrontierDemands_.find(coord);
        if (it == streamingFrontierDemands_.end() || it->second.planGeneration == 0)
        {
            continue;
        }
        streamingFrontierDemands_.erase(it);
    }
}

void ChunkManager::Impl::syncStreamingFrontierColumnDemandsLocked(const glm::ivec2& column,
                                                                  const ColumnChunkIntervals& oldIntervals,
                                                                  const ColumnChunkIntervals& newIntervals,
                                                                  const ColumnChunkIntervals& forceResidentIntervals,
                                                                  const glm::ivec2& centerColumn,
                                                                  int visibleRadius,
                                                                  int exactRadius)
{
    const int horizontalDistance =
        std::max(std::abs(column.x - centerColumn.x), std::abs(column.y - centerColumn.y));
    const bool countedVisible = horizontalDistance <= visibleRadius;
    const bool countedExact = horizontalDistance <= exactRadius;
    const int minChunkY = std::min(oldIntervals.empty() ? std::numeric_limits<int>::max() : oldIntervals.minChunkY(),
                                   newIntervals.empty() ? std::numeric_limits<int>::max() : newIntervals.minChunkY());
    const int maxChunkY = std::max(oldIntervals.empty() ? std::numeric_limits<int>::min() : oldIntervals.maxChunkY(),
                                   newIntervals.empty() ? std::numeric_limits<int>::min() : newIntervals.maxChunkY());
    if (minChunkY > maxChunkY)
    {
        return;
    }

    for (int chunkY = minChunkY; chunkY <= maxChunkY; ++chunkY)
    {
        const bool wasRequired = chunkYWithinIntervals(chunkY, oldIntervals);
        const bool isRequired = chunkYWithinIntervals(chunkY, newIntervals);
        const glm::ivec3 coord{column.x, chunkY, column.y};
        if (!isRequired)
        {
            if (wasRequired)
            {
                auto it = streamingFrontierDemands_.find(coord);
                if (it != streamingFrontierDemands_.end() && it->second.planGeneration != 0)
                {
                    streamingFrontierDemands_.erase(it);
                }
            }
            continue;
        }

        auto demandIt = streamingFrontierDemands_.find(coord);
        if (demandIt == streamingFrontierDemands_.end())
        {
            FrontierChunkDemand demand{};
            demand.forceResident = chunkYWithinIntervals(chunkY, forceResidentIntervals);
            demand.countedVisible = countedVisible;
            demand.countedExact = countedExact;
            demand.planGeneration = 1;
            auto stateIt = streamingChunkLifecycleStates_.find(coord);
            if (stateIt != streamingChunkLifecycleStates_.end())
            {
                demand.state = stateIt->second.state;
            }
            auto [insertIt, inserted] = streamingFrontierDemands_.emplace(coord, demand);
            (void)inserted;
            demandIt = insertIt;
        }

        FrontierChunkDemand& demand = demandIt->second;
        const bool forceResident = chunkYWithinIntervals(chunkY, forceResidentIntervals);
        const bool flagsChanged =
            demand.forceResident != forceResident ||
            demand.countedVisible != countedVisible ||
            demand.countedExact != countedExact ||
            demand.planGeneration == 0;
        demand.forceResident = forceResident;
        demand.countedVisible = countedVisible;
        demand.countedExact = countedExact;
        demand.planGeneration = 1;
        if ((!wasRequired || flagsChanged) && demand.state == FrontierDemandState::Missing)
        {
            ++demand.version;
            queueStreamingFrontierDispatchEntryLocked(coord, demand);
        }
    }
}

void ChunkManager::Impl::refreshStreamingFrontierCoverageCountsLocked()
{
    streamingFrontierVisibleRequired_ = 0;
    streamingFrontierExactRequired_ = 0;
    streamingFrontierVisibleReady_ = 0;
    streamingFrontierExactReady_ = 0;
    for (const auto& [coord, demand] : streamingFrontierDemands_)
    {
        (void)coord;
        if (demand.countedVisible)
        {
            ++streamingFrontierVisibleRequired_;
        }
        if (demand.countedExact)
        {
            ++streamingFrontierExactRequired_;
        }
        if (demand.state == FrontierDemandState::Ready)
        {
            if (demand.countedVisible)
            {
                ++streamingFrontierVisibleReady_;
            }
            if (demand.countedExact)
            {
                ++streamingFrontierExactReady_;
            }
        }
    }
}

void ChunkManager::Impl::updateExactCoverageCountsLocked(ExactCoverageCacheState& state)
{
    std::array<int, static_cast<std::size_t>(kMaxExactRenderDistanceChunks + 1)> ringDelta{};
    ringDelta.fill(0);
    bool complete = state.active;
    int cachedColumnsInRange = 0;
    for (const auto& [column, entry] : state.columnSummaries)
    {
        const int distance =
            std::max(std::abs(column.x - state.centerColumn.x), std::abs(column.y - state.centerColumn.y));
        if (distance > state.trackedRadiusChunks)
        {
            continue;
        }
        ++cachedColumnsInRange;
        if (!entry.authoritative)
        {
            complete = false;
            continue;
        }
        ringDelta[static_cast<std::size_t>(distance)] += entry.requiredChunkCount;
    }
    const bool noCoverageWorkQueued =
        state.batch.pendingColumns.empty() &&
        state.batch.queuedColumns.empty() &&
        state.dirtyColumns.empty() &&
        state.dirtyPages.empty() &&
        state.dirtyRegions.empty();
    const int trackedDiameter = state.trackedRadiusChunks * 2 + 1;
    const int expectedColumnsInRange = trackedDiameter * trackedDiameter;
    if (!complete &&
        state.active &&
        noCoverageWorkQueued &&
        cachedColumnsInRange >= expectedColumnsInRange)
    {
        complete = true;
        ringDelta.fill(0);
        for (auto& [column, entry] : state.columnSummaries)
        {
            const int distance =
                std::max(std::abs(column.x - state.centerColumn.x), std::abs(column.y - state.centerColumn.y));
            if (distance > state.trackedRadiusChunks)
            {
                continue;
            }
            entry.authoritative = true;
            ringDelta[static_cast<std::size_t>(distance)] += entry.requiredChunkCount;
        }
    }

    int running = 0;
    for (int radius = 0; radius <= kMaxExactRenderDistanceChunks; ++radius)
    {
        running += ringDelta[static_cast<std::size_t>(radius)];
        state.displayRequiredByRadius[static_cast<std::size_t>(radius)] = running;
    }

    if (!complete)
    {
        state.authoritativeCountsValid = false;
        state.reconciling = true;
        return;
    }

    running = 0;
    for (int radius = 0; radius <= kMaxExactRenderDistanceChunks; ++radius)
    {
        running += ringDelta[static_cast<std::size_t>(radius)];
        state.authoritativeRequiredByRadius[static_cast<std::size_t>(radius)] = running;
    }
    state.authoritativeCountsValid = true;
    state.reconciling = !noCoverageWorkQueued;
}

void ChunkManager::Impl::ensureExactCoverageCache(const glm::ivec3& center,
                                                  int trackedRadius,
                                                  int verticalRadius,
                                                  int schedulingRadius,
                                                  int exactRadius)
{
    int coverageColumnsPerUpdate = 96;
    const glm::ivec2 centerColumn{center.x, center.z};
    std::unique_lock<std::mutex> exactLock(exactPlanMutex_);
    ExactCoverageCacheState& state = exactCoverageCache_;
    const bool firstActivation = !state.active;
    const glm::ivec2 previousCenter = state.centerColumn;
    const int previousCameraChunkY = state.cameraChunkY;
    const int previousVerticalRadius = state.verticalRadius;
    const int previousTrackedRadius = state.trackedRadiusChunks;
    const bool movingWindow =
        firstActivation ||
        previousCenter != centerColumn ||
        previousCameraChunkY != center.y ||
        previousVerticalRadius != verticalRadius ||
        previousTrackedRadius != trackedRadius;
    if (!movingWindow)
    {
        // Coverage discovery uses cached column occupancy and should keep moving even when
        // the renderer is heavy; otherwise denominator growth gets pinned behind render cost.
        coverageColumnsPerUpdate = 192;
        if (smoothedFrameMs_ >= 50.0)
        {
            coverageColumnsPerUpdate = 96;
        }
        else if (smoothedFrameMs_ >= 40.0)
        {
            coverageColumnsPerUpdate = 128;
        }
        else if (smoothedFrameMs_ >= 28.0)
        {
            coverageColumnsPerUpdate = 160;
        }
    }
    if (firstActivation)
    {
        state.active = true;
        state.displayRequiredByRadius.fill(0);
        state.authoritativeRequiredByRadius.fill(0);
    }

    trackedRadius = std::clamp(trackedRadius, 0, kMaxExactRenderDistanceChunks);
    state.centerColumn = centerColumn;
    state.cameraChunkY = center.y;
    state.verticalRadius = verticalRadius;
    state.trackedRadiusChunks = trackedRadius;
    state.lastMovingWindow = movingWindow;
    state.lastCoverageColumnsBudget = coverageColumnsPerUpdate;
    state.lastSmoothedFrameMs = smoothedFrameMs_;

    auto queueColumn = [&state, centerColumn, trackedRadius](const glm::ivec2& column)
    {
        const int distance = std::max(std::abs(column.x - centerColumn.x), std::abs(column.y - centerColumn.y));
        if (distance > trackedRadius)
        {
            return;
        }
        if (state.batch.queuedColumns.insert(column).second)
        {
            state.batch.pendingColumns.push_back(column);
        }
    };

    if (firstActivation || previousTrackedRadius != trackedRadius || previousCenter != centerColumn)
    {
        state.authoritativeCountsValid = false;
        for (auto it = state.columnSummaries.begin(); it != state.columnSummaries.end();)
        {
            const int distance =
                std::max(std::abs(it->first.x - centerColumn.x), std::abs(it->first.y - centerColumn.y));
            if (distance > trackedRadius)
            {
                {
                    std::lock_guard<std::mutex> frontierLock(streamingFrontierMutex_);
                    removeStreamingFrontierColumnDemandsLocked(it->first, it->second.materializedRequiredIntervals);
                }
                it = state.columnSummaries.erase(it);
            }
            else
            {
                ++it;
            }
        }

        for (int dz = -trackedRadius; dz <= trackedRadius; ++dz)
        {
            for (int dx = -trackedRadius; dx <= trackedRadius; ++dx)
            {
                const glm::ivec2 column{centerColumn.x + dx, centerColumn.y + dz};
                if (state.columnSummaries.find(column) == state.columnSummaries.end())
                {
                    queueColumn(column);
                }
            }
        }
    }

    auto queueBandColumns = [&queueColumn](const glm::ivec2& bandCenter)
    {
        for (int dz = -kExactPlayerBandHorizontalRadius; dz <= kExactPlayerBandHorizontalRadius; ++dz)
        {
            for (int dx = -kExactPlayerBandHorizontalRadius; dx <= kExactPlayerBandHorizontalRadius; ++dx)
            {
                queueColumn({bandCenter.x + dx, bandCenter.y + dz});
            }
        }
    };
    if (firstActivation ||
        previousCenter != centerColumn ||
        previousCameraChunkY != center.y ||
        previousVerticalRadius != verticalRadius)
    {
        state.authoritativeCountsValid = false;
        queueBandColumns(centerColumn);
        if (!firstActivation)
        {
            queueBandColumns(previousCenter);
        }
    }

    state.lastDirtyPageCount = static_cast<int>(state.dirtyPages.size());
    if (!state.dirtyPages.empty())
    {
        for (const glm::ivec2& pageKey : state.dirtyPages)
        {
            glm::ivec2 minColumn{0};
            glm::ivec2 maxColumn{0};
            worldgenPageChunkColumnBounds(pageKey, minColumn, maxColumn);
            for (int chunkZ = minColumn.y; chunkZ <= maxColumn.y; ++chunkZ)
            {
                for (int chunkX = minColumn.x; chunkX <= maxColumn.x; ++chunkX)
                {
                    state.dirtyColumns.insert({chunkX, chunkZ});
                }
            }
        }
        state.dirtyPages.clear();
    }
    state.lastDirtyRegionCount = static_cast<int>(state.dirtyRegions.size());
    if (!state.dirtyRegions.empty())
    {
        for (const StructureRegionKey& key : state.dirtyRegions)
        {
            const int minChunkX = floorDiv(key.regionX * kStructureRegionSize - kMaxStructureHorizontalRadius, kChunkSizeX);
            const int maxChunkX =
                floorDiv((key.regionX + 1) * kStructureRegionSize - 1 + kMaxStructureHorizontalRadius, kChunkSizeX);
            const int minChunkZ = floorDiv(key.regionZ * kStructureRegionSize - kMaxStructureHorizontalRadius, kChunkSizeZ);
            const int maxChunkZ =
                floorDiv((key.regionZ + 1) * kStructureRegionSize - 1 + kMaxStructureHorizontalRadius, kChunkSizeZ);
            for (int chunkZ = minChunkZ; chunkZ <= maxChunkZ; ++chunkZ)
            {
                for (int chunkX = minChunkX; chunkX <= maxChunkX; ++chunkX)
                {
                    state.dirtyColumns.insert({chunkX, chunkZ});
                }
            }
        }
        state.dirtyRegions.clear();
    }
    state.lastDirtyColumnCount = static_cast<int>(state.dirtyColumns.size());
    for (const glm::ivec2& column : state.dirtyColumns)
    {
        queueColumn(column);
    }
    state.dirtyColumns.clear();

    if ((state.reconciling || !state.authoritativeCountsValid) &&
        state.batch.pendingColumns.empty() &&
        state.batch.queuedColumns.empty() &&
        state.dirtyColumns.empty() &&
        state.dirtyPages.empty() &&
        state.dirtyRegions.empty())
    {
        int cachedColumnsInRange = 0;
        for (const auto& [column, entry] : state.columnSummaries)
        {
            (void)entry;
            const int distance =
                std::max(std::abs(column.x - centerColumn.x), std::abs(column.y - centerColumn.y));
            if (distance <= trackedRadius)
            {
                ++cachedColumnsInRange;
            }
        }
        const int trackedDiameter = trackedRadius * 2 + 1;
        const int expectedColumnsInRange = trackedDiameter * trackedDiameter;
        if (cachedColumnsInRange < expectedColumnsInRange)
        {
            state.authoritativeCountsValid = false;
            for (int dz = -trackedRadius; dz <= trackedRadius; ++dz)
            {
                for (int dx = -trackedRadius; dx <= trackedRadius; ++dx)
                {
                    const glm::ivec2 column{centerColumn.x + dx, centerColumn.y + dz};
                    if (state.columnSummaries.find(column) == state.columnSummaries.end())
                    {
                        queueColumn(column);
                    }
                }
            }
        }
    }

    {
        std::lock_guard<std::mutex> frontierLock(streamingFrontierMutex_);
        if (previousCenter != centerColumn || schedulingRadius != exactRadius || firstActivation)
        {
            for (auto& [column, entry] : state.columnSummaries)
            {
                syncStreamingFrontierColumnDemandsLocked(column,
                                                         entry.materializedRequiredIntervals,
                                                         entry.materializedRequiredIntervals,
                                                         entry.summary.playerBand,
                                                         centerColumn,
                                                         schedulingRadius,
                                                         exactRadius);
            }
        }
    }

    state.lastPendingColumnsBeforeUpdate = static_cast<int>(state.batch.pendingColumns.size());
    state.batch.columnsProcessedLastUpdate = 0;
    while (state.batch.columnsProcessedLastUpdate < coverageColumnsPerUpdate)
    {
        if (state.batch.pendingColumns.empty())
        {
            break;
        }

        const glm::ivec2 column = state.batch.pendingColumns.front();
        state.batch.pendingColumns.pop_front();
        state.batch.queuedColumns.erase(column);
        ExactCoverageCacheColumnState oldState{};
        bool hadOldState = false;
        if (auto it = state.columnSummaries.find(column); it != state.columnSummaries.end())
        {
            oldState = it->second;
            hadOldState = true;
        }

        exactLock.unlock();
        ExactCoverageCacheColumnState newState{};
        newState.summary = buildExactCoverageColumnSummary(column, centerColumn, center.y, verticalRadius);
        newState.materializedRequiredIntervals = materializeRequiredIntervals(newState.summary);
        newState.requiredChunkCount = countRequiredChunks(newState.materializedRequiredIntervals);
        newState.authoritative = true;
        exactLock.lock();
        state.columnSummaries[column] = newState;

        {
            std::lock_guard<std::mutex> frontierLock(streamingFrontierMutex_);
            syncStreamingFrontierColumnDemandsLocked(column,
                                                     hadOldState ? oldState.materializedRequiredIntervals : ColumnChunkIntervals{},
                                                     newState.materializedRequiredIntervals,
                                                     newState.summary.playerBand,
                                                     centerColumn,
                                                     schedulingRadius,
                                                     exactRadius);
        }
        ++state.batch.columnsProcessedLastUpdate;
    }

    state.lastPendingColumnsAfterUpdate = static_cast<int>(state.batch.pendingColumns.size());
    state.lastQueuedColumnCount = static_cast<int>(state.batch.queuedColumns.size());
    state.reconciling = !state.batch.pendingColumns.empty();
    updateExactCoverageCountsLocked(state);
    const bool reconciling = state.reconciling;
    exactLock.unlock();
    {
        std::lock_guard<std::mutex> frontierLock(streamingFrontierMutex_);
        refreshStreamingFrontierCoverageCountsLocked();
    }
    updatePlayerSafetyOverlay(center, verticalRadius, reconciling);
}

void ChunkManager::Impl::markPlanDirtyColumn(const glm::ivec2& column) const
{
    std::lock_guard<std::mutex> lock(exactPlanMutex_);
    exactCoverageCache_.dirtyColumns.insert(column);
    exactCoverageCache_.authoritativeCountsValid = false;
    exactCoverageCache_.reconciling = true;
}

void ChunkManager::Impl::markPlanDirtyWorldgenPage(const glm::ivec2& pageKey) const
{
    std::lock_guard<std::mutex> lock(exactPlanMutex_);
    exactCoverageCache_.dirtyPages.insert(pageKey);
    exactCoverageCache_.authoritativeCountsValid = false;
    exactCoverageCache_.reconciling = true;
}

void ChunkManager::Impl::markPlanDirtyStructureRegion(const StructureRegionKey& key) const
{
    std::lock_guard<std::mutex> lock(exactPlanMutex_);
    exactCoverageCache_.dirtyRegions.insert(key);
    exactCoverageCache_.authoritativeCountsValid = false;
    exactCoverageCache_.reconciling = true;
}

void ChunkManager::Impl::markActiveWindowReplanNeeded(const char* reason) const
{
    std::lock_guard<std::mutex> lock(exactPlanMutex_);
    (void)reason;
    exactCoverageCache_.authoritativeCountsValid = false;
    exactCoverageCache_.reconciling = true;
    for (const auto& [column, entry] : exactCoverageCache_.columnSummaries)
    {
        (void)entry;
        exactCoverageCache_.dirtyColumns.insert(column);
    }
}

ChunkManager::Impl::ExactPlanSnapshot ChunkManager::Impl::activePlanSnapshot() const
{
    std::lock_guard<std::mutex> lock(exactPlanMutex_);
    return ExactPlanSnapshot{
        activeExactPlan_,
        activeWindowReplanNeeded_ ||
            pendingExactPlanStatus_ == ExactWindowPlanStatus::Building ||
            (pendingExactPlanStatus_ == ExactWindowPlanStatus::Ready && pendingExactPlan_ != nullptr)};
}

void ChunkManager::Impl::launchExactWindowPlanBuild(const ExactWindowKey& key,
                                                    std::uint64_t generation,
                                                    bool startupCritical)
{
    exactPlanBuildThread_ = std::thread(
        [this, key, generation, startupCritical]()
        {
            try
            {
                SetThreadPriority(GetCurrentThread(),
                                  startupCritical ? THREAD_PRIORITY_ABOVE_NORMAL
                                                  : THREAD_PRIORITY_BELOW_NORMAL);
                std::shared_ptr<ExactWindowPlan> plan = buildExactWindowPlan(key, generation, startupCritical);
                std::lock_guard<std::mutex> lock(exactPlanMutex_);
                if (!pendingExactPlanKeyValid_ ||
                    pendingExactPlanStatus_ != ExactWindowPlanStatus::Building ||
                    !(pendingExactPlanKey_ == key))
                {
                    return;
                }

                pendingExactPlan_ = plan;
                pendingExactPlanStatus_ = plan ? plan->status : ExactWindowPlanStatus::Failed;
            }
            catch (...)
            {
                std::lock_guard<std::mutex> lock(exactPlanMutex_);
                if (pendingExactPlanKeyValid_ &&
                    pendingExactPlanStatus_ == ExactWindowPlanStatus::Building &&
                    pendingExactPlanKey_ == key)
                {
                    pendingExactPlan_.reset();
                    pendingExactPlanStatus_ = ExactWindowPlanStatus::Failed;
                }
            }
        });
}

void ChunkManager::Impl::requestExactWindowPlan(const ExactWindowKey& key)
{
    if (shouldStop_.load(std::memory_order_acquire))
    {
        return;
    }

    bool joinCompletedThread = false;
    bool startupCritical = false;
    std::uint64_t generation = 0;
    {
        std::lock_guard<std::mutex> lock(exactPlanMutex_);
        const bool sameActive = activeExactPlan_ && activeExactPlan_->key == key;
        const bool samePendingKey = pendingExactPlanKeyValid_ && pendingExactPlanKey_ == key;
        if (samePendingKey && pendingExactPlanStatus_ == ExactWindowPlanStatus::Building)
        {
            return;
        }
        if (samePendingKey &&
            pendingExactPlanStatus_ == ExactWindowPlanStatus::Ready &&
            pendingExactPlan_ &&
            !activeWindowReplanNeeded_)
        {
            return;
        }
        if (sameActive && !activeWindowReplanNeeded_)
        {
            return;
        }
        if (exactPlanBuildThread_.joinable() && pendingExactPlanStatus_ == ExactWindowPlanStatus::Building)
        {
            return;
        }

        joinCompletedThread = exactPlanBuildThread_.joinable();
        pendingExactPlan_.reset();
        pendingExactPlanKey_ = key;
        pendingExactPlanKeyValid_ = true;
        pendingExactPlanStatus_ = ExactWindowPlanStatus::Building;
        generation = nextExactPlanGeneration_++;
        startupCritical =
            startupEnabled_ &&
            startupState_.preloadStarted &&
            activeExactPlan_ == nullptr;
        activeWindowReplanNeeded_ = false;
        dirtyPlanColumns_.clear();
        dirtyPlanPages_.clear();
        dirtyPlanRegions_.clear();
        activeWindowReplanReason_.clear();
    }

    if (joinCompletedThread)
    {
        exactPlanBuildThread_.join();
    }

    launchExactWindowPlanBuild(key, generation, startupCritical);
}

void ChunkManager::Impl::tryCommitReadyExactPlan(const ExactWindowKey& key)
{
    std::shared_ptr<const ExactWindowPlan> oldPlan{};
    std::shared_ptr<const ExactWindowPlan> newPlan{};
    bool shouldJoin = false;
    {
        std::lock_guard<std::mutex> lock(exactPlanMutex_);
        if (pendingExactPlanStatus_ == ExactWindowPlanStatus::Ready && pendingExactPlan_)
        {
            shouldJoin = exactPlanBuildThread_.joinable();
            const bool staleReadyPlan = activeWindowReplanNeeded_;
            if (pendingExactPlan_->key == key && !staleReadyPlan)
            {
                oldPlan = activeExactPlan_;
                activeExactPlan_ = pendingExactPlan_;
                newPlan = activeExactPlan_;
            }
            else if (staleReadyPlan)
            {
                activeWindowReplanNeeded_ = true;
                if (activeWindowReplanReason_.empty())
                {
                    activeWindowReplanReason_ = "exact_plan_invalidated_during_build";
                }
            }
            pendingExactPlan_.reset();
            pendingExactPlanKeyValid_ = false;
            pendingExactPlanStatus_ = ExactWindowPlanStatus::Idle;
        }
        else if (pendingExactPlanStatus_ == ExactWindowPlanStatus::Failed)
        {
            shouldJoin = exactPlanBuildThread_.joinable();
            pendingExactPlan_.reset();
            pendingExactPlanKeyValid_ = false;
            pendingExactPlanStatus_ = ExactWindowPlanStatus::Idle;
            activeWindowReplanNeeded_ = true;
            if (activeWindowReplanReason_.empty())
            {
                activeWindowReplanReason_ = "exact_plan_build_failed";
            }
        }
    }

    if (shouldJoin)
    {
        exactPlanBuildThread_.join();
    }

    if (newPlan)
    {
        applyPlanDiff(oldPlan, newPlan);
    }
}

std::shared_ptr<ChunkManager::Impl::ExactWindowPlan>
ChunkManager::Impl::buildExactWindowPlan(const ExactWindowKey& key,
                                         std::uint64_t generation,
                                         bool startupCritical) const
{
    auto plan = std::make_shared<ExactWindowPlan>();
    plan->key = key;
    plan->generation = generation;
    plan->status = ExactWindowPlanStatus::Building;
    struct PlannerSupportBuildScope
    {
        std::atomic<int>& depth;
        explicit PlannerSupportBuildScope(std::atomic<int>& inDepth) : depth(inDepth)
        {
            depth.fetch_add(1, std::memory_order_acq_rel);
        }
        ~PlannerSupportBuildScope()
        {
            depth.fetch_sub(1, std::memory_order_acq_rel);
        }
    } plannerSupportBuildScope(const_cast<ChunkManager::Impl*>(this)->exactPlanSupportBuildDepth_);

    if (key.preloadRadius <= 0 || shouldStop_.load(std::memory_order_acquire) || !surfaceMap_ || !climateMap_)
    {
        plan->status = ExactWindowPlanStatus::Ready;
        return plan;
    }

    const auto plannerCancelled = [this]()
    {
        return shouldStop_.load(std::memory_order_acquire);
    };
    const auto runPlannerParallel =
        [this, &plannerCancelled, startupCritical](std::size_t workCount, const auto& workItem)
    {
        if (workCount == 0 || plannerCancelled())
        {
            return;
        }

        const std::size_t hardwareWorkers = std::max<std::size_t>(std::thread::hardware_concurrency(), 4u);
        const std::size_t maxPlannerWorkers = startupCritical ? 8u : 4u;
        const std::size_t desiredWorkers = startupCritical
            ? std::max<std::size_t>(workerThreadCount_,
                                    std::clamp<std::size_t>(hardwareWorkers, 4u, maxPlannerWorkers))
            : std::max<std::size_t>(workerThreadCount_,
                                    std::clamp<std::size_t>(hardwareWorkers / 2u, 2u, maxPlannerWorkers));
        const std::size_t workerCount =
            std::clamp<std::size_t>(desiredWorkers,
                                    1u,
                                    std::min<std::size_t>(workCount, maxPlannerWorkers));
        std::atomic<std::size_t> nextIndex{0};
        std::exception_ptr firstError{};
        std::mutex errorMutex;
        auto worker = [startupCritical, &plannerCancelled, &nextIndex, workCount, &workItem, &firstError, &errorMutex]()
        {
            try
            {
                SetThreadPriority(GetCurrentThread(),
                                  startupCritical ? THREAD_PRIORITY_ABOVE_NORMAL
                                                  : THREAD_PRIORITY_BELOW_NORMAL);
                while (!plannerCancelled())
                {
                    const std::size_t index = nextIndex.fetch_add(1, std::memory_order_relaxed);
                    if (index >= workCount)
                    {
                        break;
                    }
                    workItem(index);
                }
            }
            catch (...)
            {
                std::lock_guard<std::mutex> lock(errorMutex);
                if (!firstError)
                {
                    firstError = std::current_exception();
                }
            }
        };

        std::vector<std::thread> workers;
        workers.reserve(workerCount > 0 ? workerCount - 1 : 0);
        for (std::size_t workerIndex = 1; workerIndex < workerCount; ++workerIndex)
        {
            workers.emplace_back(worker);
        }
        worker();
        for (std::thread& thread : workers)
        {
            if (thread.joinable())
            {
                thread.join();
            }
        }

        if (firstError)
        {
            std::rethrow_exception(firstError);
        }
    };

    const int preloadRadius = std::max(key.preloadRadius, 0);
    const int preloadMinChunkX = key.centerColumn.x - preloadRadius;
    const int preloadMaxChunkX = key.centerColumn.x + preloadRadius;
    const int preloadMinChunkZ = key.centerColumn.y - preloadRadius;
    const int preloadMaxChunkZ = key.centerColumn.y + preloadRadius;
    const int analysisMinChunkX = preloadMinChunkX - 1;
    const int analysisMaxChunkX = preloadMaxChunkX + 1;
    const int analysisMinChunkZ = preloadMinChunkZ - 1;
    const int analysisMaxChunkZ = preloadMaxChunkZ + 1;
    const int analysisMinWorldX = analysisMinChunkX * kChunkSizeX - 1;
    const int analysisMaxWorldX = (analysisMaxChunkX + 1) * kChunkSizeX;
    const int analysisMinWorldZ = analysisMinChunkZ * kChunkSizeZ - 1;
    const int analysisMaxWorldZ = (analysisMaxChunkZ + 1) * kChunkSizeZ;
    const glm::ivec2 minAnalysisPage = worldgenPageKeyForWorld(analysisMinWorldX, analysisMinWorldZ);
    const glm::ivec2 maxAnalysisPage = worldgenPageKeyForWorld(analysisMaxWorldX, analysisMaxWorldZ);
    const glm::ivec2 cameraColumn = key.centerColumn;

    std::vector<StructureRegionKey> structureRegionKeys;
    appendStructureRegionKeysForWorldBounds(analysisMinChunkX * kChunkSizeX,
                                            (analysisMaxChunkX + 1) * kChunkSizeX - 1,
                                            analysisMinChunkZ * kChunkSizeZ,
                                            (analysisMaxChunkZ + 1) * kChunkSizeZ - 1,
                                            structureRegionKeys);
    std::sort(structureRegionKeys.begin(),
              structureRegionKeys.end(),
              [](const StructureRegionKey& lhs, const StructureRegionKey& rhs)
              {
                  if (lhs.regionX != rhs.regionX)
                  {
                      return lhs.regionX < rhs.regionX;
                  }
                  return lhs.regionZ < rhs.regionZ;
              });
    structureRegionKeys.erase(std::unique(structureRegionKeys.begin(),
                                          structureRegionKeys.end(),
                                          [](const StructureRegionKey& lhs, const StructureRegionKey& rhs)
                                          {
                                              return lhs.regionX == rhs.regionX && lhs.regionZ == rhs.regionZ;
                                          }),
                              structureRegionKeys.end());

    std::unordered_set<glm::ivec2, ColumnHasher> requiredPageKeySet{};
    for (int pageZ = minAnalysisPage.y; pageZ <= maxAnalysisPage.y; ++pageZ)
    {
        for (int pageX = minAnalysisPage.x; pageX <= maxAnalysisPage.x; ++pageX)
        {
            requiredPageKeySet.insert({pageX, pageZ});
        }
    }
    for (const StructureRegionKey& regionKey : structureRegionKeys)
    {
        const std::vector<glm::ivec2> regionPageKeys = collectRegionWorldgenPageKeys(regionKey);
        requiredPageKeySet.insert(regionPageKeys.begin(), regionPageKeys.end());
    }

    std::vector<glm::ivec2> requiredPageKeys(requiredPageKeySet.begin(), requiredPageKeySet.end());
    const glm::ivec2 centerPage = worldgenPageKeyForChunkColumn(cameraColumn);
    std::sort(requiredPageKeys.begin(),
              requiredPageKeys.end(),
              [centerPage](const glm::ivec2& lhs, const glm::ivec2& rhs)
              {
                  const int lhsDistance = std::max(std::abs(lhs.x - centerPage.x), std::abs(lhs.y - centerPage.y));
                  const int rhsDistance = std::max(std::abs(rhs.x - centerPage.x), std::abs(rhs.y - centerPage.y));
                  if (lhsDistance != rhsDistance)
                  {
                      return lhsDistance < rhsDistance;
                  }
                  if (lhs.x != rhs.x)
                  {
                      return lhs.x < rhs.x;
                  }
                  return lhs.y < rhs.y;
              });

    const int analysisWidth = analysisMaxChunkX - analysisMinChunkX + 1;
    const int analysisDepth = analysisMaxChunkZ - analysisMinChunkZ + 1;
    const std::size_t analysisColumnCount =
        static_cast<std::size_t>(std::max(analysisWidth, 0)) *
        static_cast<std::size_t>(std::max(analysisDepth, 0));
    if (analysisColumnCount == 0)
    {
        plan->status = ExactWindowPlanStatus::Ready;
        return plan;
    }

    auto analysisColumnIndex = [analysisMinChunkX, analysisMinChunkZ, analysisWidth](int chunkX, int chunkZ) noexcept
    {
        return static_cast<std::size_t>(chunkZ - analysisMinChunkZ) * static_cast<std::size_t>(analysisWidth) +
               static_cast<std::size_t>(chunkX - analysisMinChunkX);
    };

    const DependencyPriority plannerDependencyPriority =
        startupCritical ? DependencyPriority::Critical : DependencyPriority::Visible;
    const JobServiceClass plannerServiceClass =
        startupCritical ? JobServiceClass::InitialVisible : JobServiceClass::Standard;
    bool missingPlannerDependencies = false;
    for (const glm::ivec2& pageKey : requiredPageKeys)
    {
        if (tryGetReadyWorldgenPage(pageKey))
        {
            continue;
        }

        missingPlannerDependencies = true;
        (void)requestWorldgenPageDependency(pageKey,
                                            plannerDependencyPriority,
                                            true,
                                            true,
                                            plannerServiceClass);
    }
    if (missingPlannerDependencies)
    {
        plan->status = ExactWindowPlanStatus::Failed;
        return plan;
    }

    std::vector<std::shared_ptr<const WorldgenPage>> readyPageValues(requiredPageKeys.size());
    runPlannerParallel(requiredPageKeys.size(),
                       [this, &requiredPageKeys, &readyPageValues](std::size_t index)
                       {
                           readyPageValues[index] = tryGetReadyWorldgenPage(requiredPageKeys[index]);
                       });
    if (plannerCancelled())
    {
        plan->status = ExactWindowPlanStatus::Failed;
        return plan;
    }

    std::unordered_map<glm::ivec2, std::shared_ptr<const WorldgenPage>, ColumnHasher> readyPages{};
    readyPages.reserve(requiredPageKeys.size());
    for (std::size_t index = 0; index < requiredPageKeys.size(); ++index)
    {
        if (!readyPageValues[index])
        {
            plan->status = ExactWindowPlanStatus::Failed;
            return plan;
        }

        readyPages.emplace(requiredPageKeys[index], std::move(readyPageValues[index]));
    }

    const auto findReadyWorldgenColumn = [&readyPages](int worldX, int worldZ) -> const WorldgenColumnValue*
    {
        const glm::ivec2 pageKey = worldgenPageKeyForWorld(worldX, worldZ);
        auto it = readyPages.find(pageKey);
        if (it == readyPages.end() || !it->second)
        {
            return nullptr;
        }

        const std::shared_ptr<const WorldgenPage>& page = it->second;
        return &page->column(worldX - page->baseWorld.x, worldZ - page->baseWorld.y);
    };

    std::unordered_map<glm::ivec2, StructureChunkColumnSpan, StructureChunkColumnHasher> editSpans{};
    {
        std::lock_guard<std::mutex> lock(pendingStructureMutex_);
        editSpans.reserve(pendingStructureEdits_.size());
        for (const auto& [coord, edits] : pendingStructureEdits_)
        {
            if (coord.x < analysisMinChunkX ||
                coord.x > analysisMaxChunkX ||
                coord.z < analysisMinChunkZ ||
                coord.z > analysisMaxChunkZ)
            {
                continue;
            }

            const bool hasSolidEdit = std::any_of(edits.begin(),
                                                  edits.end(),
                                                  [](const PendingStructureEdit& edit)
                                                  {
                                                      return edit.block != BlockId::Air;
                                                  });
            if (hasSolidEdit)
            {
                editSpans[{coord.x, coord.z}].include(coord.y, coord.y);
            }
        }
    }
    for (const auto& [coord, count] : worldEditStore_.snapshotEditedChunks())
    {
        (void)count;
        if (coord.x < analysisMinChunkX ||
            coord.x > analysisMaxChunkX ||
            coord.z < analysisMinChunkZ ||
            coord.z > analysisMaxChunkZ)
        {
            continue;
        }

        if (worldEditStore_.chunkHasSolidEdits(coord))
        {
            editSpans[{coord.x, coord.z}].include(coord.y, coord.y);
        }
    }

    struct PlannerColumnData
    {
        int highestTerrainWorld{ColumnManager::kNoHeight};
        int lowestTerrainWorld{ColumnManager::kNoHeight};
        int minWaterBottomWorld{std::numeric_limits<int>::max()};
        int maxWaterTopWorld{std::numeric_limits<int>::min()};
    };

    std::vector<PlannerColumnData> columnData(analysisColumnCount);
    runPlannerParallel(analysisColumnCount,
                       [analysisMinChunkX,
                        analysisMinChunkZ,
                        analysisWidth,
                        &findReadyWorldgenColumn,
                        &columnData,
                        this](std::size_t index)
                       {
                           const int chunkX = analysisMinChunkX +
                                              static_cast<int>(index % static_cast<std::size_t>(analysisWidth));
                           const int chunkZ = analysisMinChunkZ +
                                              static_cast<int>(index / static_cast<std::size_t>(analysisWidth));
                           const int baseWorldX = chunkX * kChunkSizeX;
                           const int baseWorldZ = chunkZ * kChunkSizeZ;
                           constexpr int kSampleExtentX = kChunkSizeX + 2;
                           constexpr int kSampleExtentZ = kChunkSizeZ + 2;
                           std::array<WorldgenColumnValue, static_cast<std::size_t>(kSampleExtentX * kSampleExtentZ)>
                               worldgenColumns{};
                           auto sampleIndex = [](int sampleX, int sampleZ) noexcept
                           {
                               return static_cast<std::size_t>(sampleZ * kSampleExtentX + sampleX);
                           };

                           for (int sampleX = -1; sampleX <= kChunkSizeX; ++sampleX)
                           {
                               for (int sampleZ = -1; sampleZ <= kChunkSizeZ; ++sampleZ)
                               {
                                   const WorldgenColumnValue* worldgenColumn =
                                       findReadyWorldgenColumn(baseWorldX + sampleX, baseWorldZ + sampleZ);
                                   if (worldgenColumn == nullptr)
                                   {
                                       return;
                                   }
                                   worldgenColumns[sampleIndex(sampleX + 1, sampleZ + 1)] = *worldgenColumn;
                               }
                           }

                           auto computeNeighborAverage = [&](int localX, int localZ) noexcept
                           {
                               float sum = 0.0f;
                               int count = 0;
                               for (int dx = -1; dx <= 1; ++dx)
                               {
                                   for (int dz = -1; dz <= 1; ++dz)
                                   {
                                       if (dx == 0 && dz == 0)
                                       {
                                           continue;
                                       }
                                       sum += static_cast<float>(
                                           worldgenColumns[sampleIndex(localX + dx + 1, localZ + dz + 1)].surface.surfaceY);
                                       ++count;
                                   }
                               }
                               return count > 0 ? sum / static_cast<float>(count) : 0.0f;
                           };

                           int highestTerrainWorld = std::numeric_limits<int>::min();
                           int lowestTerrainWorld = std::numeric_limits<int>::max();
                           int minWaterBottomWorld = std::numeric_limits<int>::max();
                           int maxWaterTopWorld = std::numeric_limits<int>::min();
                           for (int localX = 0; localX < kChunkSizeX; ++localX)
                           {
                               for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
                               {
                                   const WorldgenColumnValue& worldgenColumn =
                                       worldgenColumns[sampleIndex(localX + 1, localZ + 1)];
                                   if (worldgenColumn.surface.dominantBiome == nullptr)
                                   {
                                       continue;
                                   }

                                   const int adjustedSurfaceY =
                                       adjustedSurfaceYForColumn(worldgenColumn, computeNeighborAverage(localX, localZ));
                                   highestTerrainWorld = std::max(highestTerrainWorld, adjustedSurfaceY);
                                   lowestTerrainWorld = std::min(lowestTerrainWorld, adjustedSurfaceY);

                                   if (!worldgenColumn.waterFillEnabled || adjustedSurfaceY >= globalSeaLevel_)
                                   {
                                       continue;
                                   }

                                   int waterBottomWorld = adjustedSurfaceY + 1;
                                   int waterTopWorld = globalSeaLevel_;
                                   if (worldgenColumn.waterFillMaxDepth > 0)
                                   {
                                       waterBottomWorld = std::max(
                                           waterBottomWorld,
                                           waterTopWorld - static_cast<int>(worldgenColumn.waterFillMaxDepth) + 1);
                                   }
                                   minWaterBottomWorld = std::min(minWaterBottomWorld, waterBottomWorld);
                                   maxWaterTopWorld = std::max(maxWaterTopWorld, waterTopWorld);
                               }
                           }

                           PlannerColumnData& data = columnData[index];
                           if (highestTerrainWorld != std::numeric_limits<int>::min())
                           {
                               data.highestTerrainWorld = highestTerrainWorld;
                               data.lowestTerrainWorld = lowestTerrainWorld;
                           }
                           if (maxWaterTopWorld >= 0 && minWaterBottomWorld <= maxWaterTopWorld)
                           {
                               data.minWaterBottomWorld = minWaterBottomWorld;
                               data.maxWaterTopWorld = maxWaterTopWorld;
                           }
                       });
    if (plannerCancelled())
    {
        plan->status = ExactWindowPlanStatus::Failed;
        return plan;
    }

    std::vector<std::shared_ptr<const StructureRegion>> readyStructureRegions(structureRegionKeys.size());
    bool missingPlannerRegions = false;
    for (std::size_t index = 0; index < structureRegionKeys.size(); ++index)
    {
        readyStructureRegions[index] = tryGetReadyRegion(structureRegionKeys[index]);
        if (readyStructureRegions[index])
        {
            continue;
        }

        missingPlannerRegions = true;
        (void)requestStructureRegionDependency(structureRegionKeys[index],
                                              plannerDependencyPriority,
                                              plannerServiceClass);
    }
    if (missingPlannerRegions)
    {
        plan->status = ExactWindowPlanStatus::Failed;
        return plan;
    }

    std::unordered_map<glm::ivec2, StructureChunkColumnSpan, StructureChunkColumnHasher> plannerStructureSpans{};
    plannerStructureSpans.reserve(analysisColumnCount);
    const auto mergeStructureSpans = [&plannerStructureSpans,
                                      analysisMinChunkX,
                                      analysisMaxChunkX,
                                      analysisMinChunkZ,
                                      analysisMaxChunkZ](const auto& spans)
    {
        for (const auto& [column, span] : spans)
        {
            if (!span.valid() ||
                column.x < analysisMinChunkX ||
                column.x > analysisMaxChunkX ||
                column.y < analysisMinChunkZ ||
                column.y > analysisMaxChunkZ)
            {
                continue;
            }

            plannerStructureSpans[column].include(span.minChunkY, span.maxChunkY);
        }
    };
    for (std::size_t index = 0; index < structureRegionKeys.size(); ++index)
    {
        mergeStructureSpans(readyStructureRegions[index]->chunkColumnSpans);
    }

    std::vector<ColumnSlabOccupancy> analysisOccupancies(analysisColumnCount);
    runPlannerParallel(analysisColumnCount,
                       [analysisMinChunkX,
                        analysisMinChunkZ,
                        analysisWidth,
                        analysisMaxChunkX,
                        analysisMaxChunkZ,
                        &columnData,
                        &plannerStructureSpans,
                        &analysisOccupancies,
                        &editSpans,
                        analysisColumnIndex](std::size_t index)
                       {
                           const int chunkX = analysisMinChunkX +
                                              static_cast<int>(index % static_cast<std::size_t>(analysisWidth));
                           const int chunkZ = analysisMinChunkZ +
                                              static_cast<int>(index / static_cast<std::size_t>(analysisWidth));
                           const glm::ivec2 column{chunkX, chunkZ};
                           const PlannerColumnData& data = columnData[index];
                           ColumnSlabOccupancy occupancy{};
                           occupancy.supportComplete = true;
                           auto noteChunkInterval = [&](int minChunkY, int maxChunkY)
                           {
                               occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, maxChunkY);
                               addColumnChunkInterval(occupancy.terrainIntervals, minChunkY, maxChunkY);
                           };

                           if (data.highestTerrainWorld != ColumnManager::kNoHeight)
                           {
                               const int highestChunkY = floorDiv(data.highestTerrainWorld, kChunkSizeY);
                               noteChunkInterval(0, highestChunkY);

                               int minNeighborHeight = data.highestTerrainWorld;
                               constexpr std::array<glm::ivec2, 4> kNeighborOffsets{
                                   glm::ivec2{1, 0},
                                   glm::ivec2{-1, 0},
                                   glm::ivec2{0, 1},
                                   glm::ivec2{0, -1},
                               };
                               for (const glm::ivec2& offset : kNeighborOffsets)
                               {
                                   const int neighborX = chunkX + offset.x;
                                   const int neighborZ = chunkZ + offset.y;
                                   if (neighborX < analysisMinChunkX ||
                                       neighborX > analysisMaxChunkX ||
                                       neighborZ < analysisMinChunkZ ||
                                       neighborZ > analysisMaxChunkZ)
                                   {
                                       continue;
                                   }

                                   const PlannerColumnData& neighborData =
                                       columnData[analysisColumnIndex(neighborX, neighborZ)];
                                   if (neighborData.highestTerrainWorld != ColumnManager::kNoHeight)
                                   {
                                       minNeighborHeight = std::min(minNeighborHeight, neighborData.highestTerrainWorld);
                                   }
                               }

                               const int lowestExposedWorldY = std::min(data.highestTerrainWorld, minNeighborHeight + 1);
                               int shellFloorWorldY = lowestExposedWorldY;
                               if (data.lowestTerrainWorld != ColumnManager::kNoHeight &&
                                   data.highestTerrainWorld - data.lowestTerrainWorld >=
                                       kExactSurfaceShellInternalReliefThresholdBlocks)
                               {
                                   shellFloorWorldY = std::min(shellFloorWorldY, data.lowestTerrainWorld);
                               }
                               const int shellFloorChunk =
                                   std::max(0,
                                            floorDiv(std::max(0, shellFloorWorldY), kChunkSizeY) -
                                                kExactSurfaceShellBelowSlackChunks);
                               addColumnChunkInterval(occupancy.surfaceShellIntervals,
                                                      shellFloorChunk,
                                                      std::max(highestChunkY,
                                                               highestChunkY + kExactSurfaceShellAirAboveChunks));
                           }

                           if (data.maxWaterTopWorld >= 0 && data.minWaterBottomWorld <= data.maxWaterTopWorld)
                           {
                               const int minChunkY = floorDiv(std::max(0, data.minWaterBottomWorld), kChunkSizeY);
                               const int maxChunkY = floorDiv(std::max(0, data.maxWaterTopWorld), kChunkSizeY);
                               occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, maxChunkY);
                               addColumnChunkInterval(occupancy.waterIntervals, minChunkY, maxChunkY);
                           }

                           auto structureIt = plannerStructureSpans.find(column);
                           if (structureIt != plannerStructureSpans.end() && structureIt->second.valid())
                           {
                               occupancy.highestOccupiedChunkY =
                                   std::max(occupancy.highestOccupiedChunkY, structureIt->second.maxChunkY);
                               addColumnChunkInterval(occupancy.structureIntervals,
                                                      structureIt->second.minChunkY,
                                                      structureIt->second.maxChunkY);
                           }

                           const auto editIt = editSpans.find(column);
                           if (editIt != editSpans.end() && editIt->second.valid())
                           {
                               occupancy.highestOccupiedChunkY =
                                   std::max(occupancy.highestOccupiedChunkY, editIt->second.maxChunkY);
                               addColumnChunkInterval(occupancy.editIntervals,
                                                      editIt->second.minChunkY,
                                                      editIt->second.maxChunkY);
                           }

                           mergeColumnChunkIntervals(occupancy.occupiedIntervals, occupancy.terrainIntervals);
                           mergeColumnChunkIntervals(occupancy.occupiedIntervals, occupancy.waterIntervals);
                           mergeColumnChunkIntervals(occupancy.occupiedIntervals, occupancy.structureIntervals);
                           mergeColumnChunkIntervals(occupancy.occupiedIntervals, occupancy.editIntervals);
                           analysisOccupancies[index] = occupancy;
                       });
    if (plannerCancelled())
    {
        plan->status = ExactWindowPlanStatus::Failed;
        return plan;
    }

    {
        std::lock_guard<std::mutex> lock(predictedColumnMutex_);
        for (int chunkZ = analysisMinChunkZ; chunkZ <= analysisMaxChunkZ; ++chunkZ)
        {
            for (int chunkX = analysisMinChunkX; chunkX <= analysisMaxChunkX; ++chunkX)
            {
                const PlannerColumnData& data = columnData[analysisColumnIndex(chunkX, chunkZ)];
                if (data.highestTerrainWorld == ColumnManager::kNoHeight)
                {
                    continue;
                }

                auto [it, inserted] = predictedColumnHeights_.try_emplace(glm::ivec2{chunkX, chunkZ},
                                                                          data.highestTerrainWorld);
                if (!inserted)
                {
                    it->second = std::max(it->second, data.highestTerrainWorld);
                }
            }
        }
    }
    {
        std::lock_guard<std::mutex> lock(columnSlabOccupancyMutex_);
        for (int chunkZ = analysisMinChunkZ; chunkZ <= analysisMaxChunkZ; ++chunkZ)
        {
            for (int chunkX = analysisMinChunkX; chunkX <= analysisMaxChunkX; ++chunkX)
            {
                columnSlabOccupancyCache_[glm::ivec2{chunkX, chunkZ}] =
                    analysisOccupancies[analysisColumnIndex(chunkX, chunkZ)];
            }
        }
    }

    plan->columnSummaries.reserve(static_cast<std::size_t>((preloadRadius * 2 + 1) * (preloadRadius * 2 + 1)));
    for (int chunkZ = preloadMinChunkZ; chunkZ <= preloadMaxChunkZ; ++chunkZ)
    {
        for (int chunkX = preloadMinChunkX; chunkX <= preloadMaxChunkX; ++chunkX)
        {
            const glm::ivec2 column{chunkX, chunkZ};
            const int horizontalDistance =
                std::max(std::abs(column.x - key.centerColumn.x), std::abs(column.y - key.centerColumn.y));
            const bool countedVisible = horizontalDistance <= key.visibleRadius;
            const bool countedExact = horizontalDistance <= key.exactRadius;
            const ColumnSlabOccupancy& occupancy = analysisOccupancies[analysisColumnIndex(chunkX, chunkZ)];
            const ColumnChunkIntervals playerBand =
                playerBandIntervalsForColumn(column, cameraColumn, key.cameraChunkY, key.verticalRadius);
            ColumnChunkIntervals requiredIntervals{};
            mergeColumnChunkIntervals(requiredIntervals, playerBand);
            if (!playerBand.empty())
            {
                mergeColumnChunkIntervals(requiredIntervals, occupancy.occupiedIntervals);
            }
            else
            {
                mergeColumnChunkIntervals(requiredIntervals, occupancy.surfaceShellIntervals);
                mergeColumnChunkIntervals(requiredIntervals, occupancy.waterIntervals);
                mergeColumnChunkIntervals(requiredIntervals, occupancy.structureIntervals);
                mergeColumnChunkIntervals(requiredIntervals, occupancy.editIntervals);
            }
            mergeColumnChunkIntervals(requiredIntervals, occupancy.maybeIntervals);
            plan->columnSummaries.emplace(column,
                                          ColumnPlanSummary{
                                              playerBand,
                                              requiredIntervals,
                                              occupancy,
                                              occupancy.supportComplete});
            if (requiredIntervals.empty())
            {
                continue;
            }

            for (int chunkY = requiredIntervals.minChunkY(); chunkY <= requiredIntervals.maxChunkY(); ++chunkY)
            {
                if (!chunkYWithinIntervals(chunkY, requiredIntervals))
                {
                    continue;
                }

                const bool forceResident = chunkYWithinIntervals(chunkY, playerBand);
                const bool required =
                    forceResident ||
                    !occupancy.supportComplete ||
                    classifyColumnSlab(occupancy, chunkY) != ColumnSlabOccupancyState::DefinitelyEmpty;
                if (!required)
                {
                    continue;
                }

                plan->requiredChunks.emplace(glm::ivec3{column.x, chunkY, column.y},
                                             PlannedChunkEntry{
                                                 countedExact,
                                                 countedVisible,
                                                 forceResident,
                                                 true});
                if (countedExact)
                {
                    ++plan->exactRequiredCount;
                }
                if (countedVisible)
                {
                    ++plan->visibleRequiredCount;
                }
            }
        }
    }

    plan->status = ExactWindowPlanStatus::Ready;
    return plan;
}

void ChunkManager::Impl::refillWorldgenPageDependencyJobs()
{
    if (shouldStop_.load(std::memory_order_acquire))
    {
        return;
    }

    const std::size_t targetJobs = targetWorldgenPageDependencyJobs();
    const std::size_t outstandingJobs = jobQueue_.outstanding(JobType::WorldgenPageDependency);
    const JobServiceClass serviceClass = highestQueuedWorldgenDependencyServiceClass();
    if (outstandingJobs >= targetJobs)
    {
        return;
    }

    for (std::size_t i = outstandingJobs; i < targetJobs; ++i)
    {
        enqueueJob(nullptr,
                   JobType::WorldgenPageDependency,
                   schedulingPriorityOrigin_,
                   0,
                   false,
                   serviceClass);
    }
}

void ChunkManager::Impl::refillStructureRegionDependencyJobs()
{
    if (shouldStop_.load(std::memory_order_acquire))
    {
        return;
    }

    repairWaitingStructureRegionDependencies();

    const std::size_t targetJobs = targetStructureRegionDependencyJobs();
    const std::size_t outstandingJobs = jobQueue_.outstanding(JobType::StructureRegionDependency);
    const JobServiceClass serviceClass = highestQueuedStructureRegionDependencyServiceClass();
    if (outstandingJobs >= targetJobs)
    {
        return;
    }

    for (std::size_t i = outstandingJobs; i < targetJobs; ++i)
    {
        enqueueJob(nullptr,
                   JobType::StructureRegionDependency,
                   schedulingPriorityOrigin_,
                   0,
                   false,
                   serviceClass);
    }
}

void ChunkManager::Impl::repairWaitingStructureRegionDependencies()
{
    struct RegionRepairSnapshot
    {
        StructureRegionKey key{};
        DependencyPriority priority{DependencyPriority::Background};
        JobServiceClass serviceClass{JobServiceClass::Refinement};
        std::vector<glm::ivec2> missingPages;
    };

    std::vector<RegionRepairSnapshot> waitingRegions;
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        waitingRegions.reserve(structureRegionEntries_.size());
        for (const auto& [key, entry] : structureRegionEntries_)
        {
            if (entry.state != StructureRegionState::WaitingOnWorldgenPages)
            {
                continue;
            }

            RegionRepairSnapshot snapshot{};
            snapshot.key = key;
            snapshot.priority = entry.priority;
            snapshot.serviceClass = entry.serviceClass;
            snapshot.missingPages.reserve(entry.missingWorldgenPages.size());
            for (const glm::ivec2& pageKey : entry.missingWorldgenPages)
            {
                snapshot.missingPages.push_back(pageKey);
            }
            waitingRegions.push_back(std::move(snapshot));
        }
    }

    for (const RegionRepairSnapshot& snapshot : waitingRegions)
    {
        std::vector<glm::ivec2> readyPages;
        std::vector<glm::ivec2> retryPages;
        readyPages.reserve(snapshot.missingPages.size());
        retryPages.reserve(snapshot.missingPages.size());
        for (const glm::ivec2& pageKey : snapshot.missingPages)
        {
            if (tryGetReadyWorldgenPage(pageKey))
            {
                readyPages.push_back(pageKey);
                continue;
            }

            if (!worldgenPageDependencyHasOutstandingWork(pageKey))
            {
                retryPages.push_back(pageKey);
            }
        }

        for (const glm::ivec2& pageKey : retryPages)
        {
            requestWorldgenPageDependency(pageKey, snapshot.priority, false, false, snapshot.serviceClass);
        }

        if (readyPages.empty() && retryPages.empty())
        {
            continue;
        }

        bool shouldQueueRegion = false;
        {
            std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
            auto entryIt = structureRegionEntries_.find(snapshot.key);
            if (entryIt == structureRegionEntries_.end() ||
                entryIt->second.state != StructureRegionState::WaitingOnWorldgenPages)
            {
                continue;
            }

            StructureRegionDependencyEntry& entry = entryIt->second;
            for (const glm::ivec2& pageKey : readyPages)
            {
                if (entry.missingWorldgenPages.erase(pageKey) == 0)
                {
                    continue;
                }

                auto waiterIt = worldgenPageStructureRegionWaiters_.find(pageKey);
                if (waiterIt != worldgenPageStructureRegionWaiters_.end())
                {
                    waiterIt->second.erase(snapshot.key);
                    if (waiterIt->second.empty())
                    {
                        worldgenPageStructureRegionWaiters_.erase(waiterIt);
                    }
                }
            }

            if (!entry.missingWorldgenPages.empty())
            {
                continue;
            }

            const StructureRegionKey centerRegion{
                floorDiv(lastCenterChunk_.x * kChunkSizeX, kStructureRegionSize),
                floorDiv(lastCenterChunk_.z * kChunkSizeZ, kStructureRegionSize)};
            const std::uint32_t distance =
                static_cast<std::uint32_t>(std::max(std::abs(snapshot.key.regionX - centerRegion.regionX),
                                                    std::abs(snapshot.key.regionZ - centerRegion.regionZ)));
            entry.state = StructureRegionState::Queued;
            entry.dependencyJobQueued = true;
            entry.lastError = {};
            entry.token = nextStructureRegionDependencyToken_++;
            pendingStructureRegionDependencyQueue_.push(
                StructureRegionDependencyRequest{
                    snapshot.key,
                    entry.token,
                    nextStructureRegionDependencySequence_++,
                    distance,
                    entry.priority,
                    entry.serviceClass});
            shouldQueueRegion = true;
        }

        if (shouldQueueRegion)
        {
            if (exactDependencyStallDebugLoggingEnabled())
            {
                std::ostringstream stream;
                stream << "exact_dep_region_repaired region=(" << snapshot.key.regionX << "," << snapshot.key.regionZ
                       << ") ready_pages_cleared=" << readyPages.size()
                       << " retried_pages=" << retryPages.size();
                exactDependencyStallDebugLog(stream.str());
            }
        }
    }
}

void ChunkManager::Impl::refillBulkShellOracleJobs()
{
    if (shouldStop_.load(std::memory_order_acquire) || !bulkShellOracleBatch_)
    {
        return;
    }

    const std::size_t targetJobs = targetBulkShellOracleJobs();
    const std::size_t outstandingJobs = jobQueue_.outstanding(JobType::BulkShellOracle);
    if (outstandingJobs >= targetJobs)
    {
        return;
    }

    for (std::size_t i = outstandingJobs; i < targetJobs; ++i)
    {
        enqueueJob(nullptr,
                   JobType::BulkShellOracle,
                   schedulingPriorityOrigin_,
                   0,
                   false,
                   JobServiceClass::Refinement);
    }
}

void ChunkManager::Impl::warmReadyWorldgenPageColumns(const glm::ivec2& pageKey,
                                                      const std::shared_ptr<const WorldgenPage>& page,
                                                      bool buildOccupancy) const
{
    (void)pageKey;
    if (!page)
    {
        return;
    }

    glm::ivec2 minColumn{0};
    glm::ivec2 maxColumn{0};
    worldgenPageChunkColumnBounds(pageKey, minColumn, maxColumn);
    for (int columnZ = minColumn.y; columnZ <= maxColumn.y; ++columnZ)
    {
        for (int columnX = minColumn.x; columnX <= maxColumn.x; ++columnX)
        {
            const glm::ivec2 column{columnX, columnZ};
            const int worldX = column.x * kChunkSizeX + kChunkSizeX / 2;
            const int worldZ = column.y * kChunkSizeZ + kChunkSizeZ / 2;
            int cachedHeight = ColumnManager::kNoHeight;
            const bool haveHeight = tryGetCachedColumnHeight(column, worldX, worldZ, cachedHeight);
            ColumnSlabOccupancy occupancy{};
            const bool haveOccupancy = tryGetCachedColumnSlabOccupancy(column, occupancy);

            if (haveHeight)
            {
                refreshWorldgenPageHeightSupportForColumn(column, true);
            }
            if (haveOccupancy)
            {
                refreshWorldgenPageOccupancySupportForColumn(column, true);
            }

            ColumnSlabOccupancy resolvedOccupancy = occupancy;
            bool resolvedHaveOccupancy = haveOccupancy;
            if (buildOccupancy && !haveOccupancy)
            {
                resolvedOccupancy = cachedColumnSlabOccupancy(column);
                resolvedHaveOccupancy = resolvedOccupancy.supportComplete;
            }

            if (resolvedHaveOccupancy)
            {
                refreshWorldgenPageOccupancySupportForColumn(column, true);
            }
            else if (buildOccupancy)
            {
                refreshWorldgenPageOccupancySupportForColumn(column, false);
            }

            if (!haveHeight)
            {
                if (resolvedHaveOccupancy && resolvedOccupancy.highestOccupiedChunkY >= 0)
                {
                    mergePredictedColumnHeight(
                        column,
                        resolvedOccupancy.highestOccupiedChunkY * kChunkSizeY + (kChunkSizeY - 1));
                }
                else
                {
                    const int localX = worldX - page->baseWorld.x;
                    const int localZ = worldZ - page->baseWorld.y;
                    mergePredictedColumnHeight(column, page->column(localX, localZ).surface.surfaceY);
                }
            }

        }
    }
}

bool ChunkManager::Impl::processWorldgenPageDependencyJob()
{
    glm::ivec2 pageKey{0};
    std::uint64_t token = 0;
    DependencyPriority priority = DependencyPriority::Background;
    JobServiceClass serviceClass = JobServiceClass::Refinement;
    bool buildOccupancy = false;
    bool warmStructures = false;
    if (!acquireNextWorldgenPageDependency(pageKey,
                                           token,
                                           priority,
                                           serviceClass,
                                           buildOccupancy,
                                           warmStructures))
    {
        return false;
    }
    (void)token;

    try
    {
        std::shared_ptr<WorldgenPage> page{};
        {
            std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
            auto entryIt = worldgenPageEntries_.find(pageKey);
            if (entryIt != worldgenPageEntries_.end())
            {
                page = entryIt->second.page;
            }
        }
        if (!page)
        {
            page = buildWorldgenPage(pageKey);
        }

        glm::ivec2 minColumn{0};
        glm::ivec2 maxColumn{0};
        worldgenPageChunkColumnBounds(pageKey, minColumn, maxColumn);
        const auto mergeLatestRequestState = [&]()
        {
            std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
            auto entryIt = worldgenPageEntries_.find(pageKey);
            if (entryIt == worldgenPageEntries_.end())
            {
                return;
            }

            const WorldgenPageDependencyEntry& entry = entryIt->second;
            priority = std::max(priority, entry.priority);
            serviceClass = mergeDependencyServiceClass(serviceClass, entry.serviceClass);
            buildOccupancy = buildOccupancy || entry.buildOccupancy;
            warmStructures = warmStructures || entry.warmStructures;
        };

        mergeLatestRequestState();
        warmReadyWorldgenPageColumns(pageKey, page, buildOccupancy);
        const bool warmedOccupancy = buildOccupancy;
        mergeLatestRequestState();
        if (buildOccupancy && !warmedOccupancy)
        {
            warmReadyWorldgenPageColumns(pageKey, page, true);
        }

        publishWorldgenPageReady(pageKey, page);

        if (warmStructures)
        {
            for (int columnZ = minColumn.y; columnZ <= maxColumn.y; ++columnZ)
            {
                for (int columnX = minColumn.x; columnX <= maxColumn.x; ++columnX)
                {
                    warmStructureRegionsForColumn({columnX, columnZ}, priority, serviceClass);
                }
            }
        }

        return true;
    }
    catch (...)
    {
        publishWorldgenPageFailure(pageKey, std::current_exception());
        return false;
    }
}

bool ChunkManager::Impl::processStructureRegionDependencyJob()
{
    StructureRegionKey regionKey{};
    std::uint64_t token = 0;
    DependencyPriority priority = DependencyPriority::Background;
    JobServiceClass serviceClass = JobServiceClass::Refinement;
    if (!acquireNextStructureRegionDependency(regionKey, token, priority, serviceClass))
    {
        return false;
    }
    (void)token;

    const auto requeueWaitingOnPages = [&](const std::vector<glm::ivec2>& missingPageKeys)
    {
        if (missingPageKeys.empty())
        {
            return;
        }

        for (const glm::ivec2& pageKey : missingPageKeys)
        {
            requestWorldgenPageDependency(pageKey, priority, false, false, serviceClass);
        }

        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        StructureRegionDependencyEntry& entry = structureRegionEntries_[regionKey];
        for (const glm::ivec2& pageKey : entry.missingWorldgenPages)
        {
            auto waiterIt = worldgenPageStructureRegionWaiters_.find(pageKey);
            if (waiterIt == worldgenPageStructureRegionWaiters_.end())
            {
                continue;
            }

            waiterIt->second.erase(regionKey);
            if (waiterIt->second.empty())
            {
                worldgenPageStructureRegionWaiters_.erase(waiterIt);
            }
        }

        entry.priority = std::max(entry.priority, priority);
        entry.serviceClass = mergeDependencyServiceClass(entry.serviceClass, serviceClass);
        entry.state = StructureRegionState::WaitingOnWorldgenPages;
        entry.dependencyJobQueued = false;
        entry.region.reset();
        entry.lastError = {};
        entry.missingWorldgenPages.clear();
        for (const glm::ivec2& pageKey : missingPageKeys)
        {
            if (entry.missingWorldgenPages.insert(pageKey).second)
            {
                worldgenPageStructureRegionWaiters_[pageKey].insert(regionKey);
            }
        }
    };

    const std::vector<glm::ivec2> requiredPageKeys = collectRegionWorldgenPageKeys(regionKey);
    std::vector<glm::ivec2> missingPageKeys;
    missingPageKeys.reserve(requiredPageKeys.size());
    for (const glm::ivec2& pageKey : requiredPageKeys)
    {
        if (!tryGetReadyWorldgenPage(pageKey))
        {
            missingPageKeys.push_back(pageKey);
        }
    }
    if (!missingPageKeys.empty())
    {
        requeueWaitingOnPages(missingPageKeys);
        return false;
    }

    try
    {
        const std::shared_ptr<StructureRegion> region = buildStructureRegionFromReadyPages(regionKey);
        publishStructureRegionReady(regionKey, region);
        return true;
    }
    catch (...)
    {
        missingPageKeys.clear();
        for (const glm::ivec2& pageKey : requiredPageKeys)
        {
            if (!tryGetReadyWorldgenPage(pageKey))
            {
                missingPageKeys.push_back(pageKey);
            }
        }
        if (!missingPageKeys.empty())
        {
            requeueWaitingOnPages(missingPageKeys);
            return false;
        }

        publishStructureRegionFailure(regionKey, std::current_exception());
        return false;
    }
}

bool ChunkManager::Impl::processBulkShellOracleJob()
{
    const std::shared_ptr<BulkShellOracleBatch> batch = bulkShellOracleBatch_;
    if (!batch || !surfaceMap_)
    {
        return false;
    }

    const int fragmentWorldSpan = terrain::SurfaceFragment::kSize;
    while (!shouldStop_.load(std::memory_order_acquire))
    {
        const std::size_t index = batch->nextFragmentIndex.fetch_add(1, std::memory_order_acq_rel);
        if (index >= batch->fragmentCoords.size())
        {
            return false;
        }

        const glm::ivec2 fragmentCoord = batch->fragmentCoords[index];
        const terrain::SurfaceFragment& fragment = surfaceMap_->getFragment(fragmentCoord);
        const glm::ivec2 baseWorld = fragment.baseWorld();

        const int fragmentMinChunkX = floorDiv(baseWorld.x, kChunkSizeX);
        const int fragmentMaxChunkX = floorDiv(baseWorld.x + fragmentWorldSpan - 1, kChunkSizeX);
        const int fragmentMinChunkZ = floorDiv(baseWorld.y, kChunkSizeZ);
        const int fragmentMaxChunkZ = floorDiv(baseWorld.y + fragmentWorldSpan - 1, kChunkSizeZ);

        for (int chunkX = std::max(fragmentMinChunkX, batch->minChunk.x);
             chunkX <= std::min(fragmentMaxChunkX, batch->maxChunk.x);
             ++chunkX)
        {
            const int localMinX = std::max(0, chunkX * kChunkSizeX - baseWorld.x);
            const int localMaxX = std::min(fragmentWorldSpan - 1,
                                           (chunkX + 1) * kChunkSizeX - 1 - baseWorld.x);

            for (int chunkZ = std::max(fragmentMinChunkZ, batch->minChunk.y);
                 chunkZ <= std::min(fragmentMaxChunkZ, batch->maxChunk.y);
                 ++chunkZ)
            {
                const int localMinZ = std::max(0, chunkZ * kChunkSizeZ - baseWorld.y);
                const int localMaxZ = std::min(fragmentWorldSpan - 1,
                                               (chunkZ + 1) * kChunkSizeZ - 1 - baseWorld.y);

                int highestSurfaceY = ColumnManager::kNoHeight;
                for (int localX = localMinX; localX <= localMaxX; ++localX)
                {
                    for (int localZ = localMinZ; localZ <= localMaxZ; ++localZ)
                    {
                        highestSurfaceY = std::max(highestSurfaceY, fragment.column(localX, localZ).surfaceY);
                    }
                }

                if (highestSurfaceY != ColumnManager::kNoHeight)
                {
                    mergePredictedColumnHeight({chunkX, chunkZ}, highestSurfaceY);
                }
            }
        }

        batch->remainingFragments.fetch_sub(1, std::memory_order_acq_rel);
        return true;
    }
    return false;
}

void ChunkManager::Impl::collectReusableChunkBufferPages()
{
    const UINT64 completedRenderFenceValue = (renderFence_ != nullptr)
        ? renderFence_->GetCompletedValue()
        : std::numeric_limits<UINT64>::max();

    std::lock_guard<std::mutex> lock(bufferPageMutex_);
    for (ChunkBufferPage& page : bufferPages_)
    {
        if (page.state == ChunkBufferPageState::Retiring && completedRenderFenceValue >= page.retireFenceValue)
        {
            const std::uint32_t pageIndex = static_cast<std::uint32_t>(&page - bufferPages_.data());
            releaseChunkBufferPageUploadBuffers(page);
            resetChunkBufferPage(page);
            if (page.usage == ChunkBufferPageUsage::ExactGpu)
            {
                ++freeExactGpuPageCount_;
            }
            noteExactGpuPageMetadataChange(pageIndex);
            if (exactUploadDebugLoggingEnabled())
            {
                std::ostringstream stream;
                stream << "exact upload page recycled"
                       << " page=" << pageIndex
                       << " completedRenderFence=" << completedRenderFenceValue;
                exactUploadDebugLog(stream.str());
            }
        }
    }
}

void ChunkManager::Impl::releaseChunkAllocationRange(std::uint32_t pageIndex,
                                                     std::size_t vertexOffset,
                                                     std::size_t vertexCount,
                                                     std::size_t indexOffset,
                                                     std::size_t indexCount,
                                                     bool residentAllocation)
{
    (void)vertexOffset;
    (void)vertexCount;
    (void)indexOffset;
    (void)indexCount;
    if (pageIndex == kInvalidChunkBufferPage)
    {
        return;
    }

    const UINT64 completedRenderFenceValue = (renderFence_ != nullptr)
        ? renderFence_->GetCompletedValue()
        : std::numeric_limits<UINT64>::max();

    bool pageBecameResident = false;
    {
        std::lock_guard<std::mutex> lock(bufferPageMutex_);
        if (pageIndex >= bufferPages_.size())
        {
            return;
        }

        ChunkBufferPage& page = bufferPages_[pageIndex];
        if (residentAllocation)
        {
            if (page.residentChunks > 0)
            {
                --page.residentChunks;
            }

            if (page.residentChunks == 0)
            {
                if (page.pendingChunks > 0)
                {
                    if (page.usage != ChunkBufferPageUsage::ExactGpu)
                    {
                        page.state = ChunkBufferPageState::SealedPendingResident;
                    }
                    if (exactUploadDebugLoggingEnabled())
                    {
                        std::ostringstream stream;
                        stream << "exact upload page returned to pending_uploaded"
                               << " page=" << pageIndex
                               << " residentChunks=" << page.residentChunks
                               << " pendingChunks=" << page.pendingChunks;
                        exactUploadDebugLog(stream.str());
                    }
                }
                else if (renderFence_ != nullptr &&
                         renderFenceValue_ > 0 &&
                         completedRenderFenceValue < renderFenceValue_)
                {
                    page.state = ChunkBufferPageState::Retiring;
                    page.retireFenceValue = renderFenceValue_;
                    if (exactUploadDebugLoggingEnabled())
                    {
                        std::ostringstream stream;
                        stream << "exact upload page retiring"
                               << " page=" << pageIndex
                               << " retireFence=" << page.retireFenceValue;
                        exactUploadDebugLog(stream.str());
                    }
                }
                else
                {
                    releaseChunkBufferPageUploadBuffers(page);
                    resetChunkBufferPage(page);
                    if (page.usage == ChunkBufferPageUsage::ExactGpu)
                    {
                        ++freeExactGpuPageCount_;
                    }
                    if (exactUploadDebugLoggingEnabled())
                    {
                        std::ostringstream stream;
                        stream << "exact upload page released to available"
                               << " page=" << pageIndex;
                        exactUploadDebugLog(stream.str());
                    }
                }
            }
            noteExactGpuPageMetadataChange(pageIndex);
            return;
        }

        if (page.pendingChunks > 0)
        {
            --page.pendingChunks;
        }

        if (page.pendingChunks == 0)
        {
            if (page.usage == ChunkBufferPageUsage::ExactGpu)
            {
                if (page.state == ChunkBufferPageState::SealedPendingResident &&
                    !page.sealedPendingResidentQueued)
                {
                    sealedPendingResidentPageIndices_.push_back(pageIndex);
                    page.sealedPendingResidentQueued = true;
                }
                else if (page.state == ChunkBufferPageState::OpenWritable &&
                         page.sealRequested &&
                         !page.sealRequestedQueued)
                {
                    sealRequestedPageIndices_.push_back(pageIndex);
                    page.sealRequestedQueued = true;
                }
            }
            else if (page.residentChunks > 0)
            {
                page.state = ChunkBufferPageState::ResidentImmutable;
                page.uploadFenceValue = 0;
                page.pendingBatchId = 0;
                releaseChunkBufferPageUploadBuffers(page);
                pageBecameResident = true;
                if (exactUploadDebugLoggingEnabled())
                {
                    std::ostringstream stream;
                    stream << "exact upload page resident"
                           << " page=" << pageIndex
                           << " residentChunks=" << page.residentChunks;
                    exactUploadDebugLog(stream.str());
                }
            }
            else
            {
                releaseChunkBufferPageUploadBuffers(page);
                resetChunkBufferPage(page);
                if (page.usage == ChunkBufferPageUsage::ExactGpu)
                {
                    ++freeExactGpuPageCount_;
                }
                if (exactUploadDebugLoggingEnabled())
                {
                    std::ostringstream stream;
                    stream << "exact upload page pending release completed"
                           << " page=" << pageIndex;
                    exactUploadDebugLog(stream.str());
                }
            }
        }
        noteExactGpuPageMetadataChange(pageIndex);
    }

    if (pageBecameResident)
    {
        publishResidentExactGpuPageChunksReady(pageIndex);
    }
}

void ChunkManager::Impl::collectDeferredPendingChunkReleases()
{
    const UINT64 completedUploadFenceValue = uploadContext_.completedFenceValue();
    std::deque<DeferredPendingChunkRelease> stillPending;
    while (!deferredPendingChunkReleases_.empty())
    {
        DeferredPendingChunkRelease pending = deferredPendingChunkReleases_.front();
        deferredPendingChunkReleases_.pop_front();
        if (pending.uploadFenceValue != 0 && completedUploadFenceValue < pending.uploadFenceValue)
        {
            stillPending.push_back(pending);
            continue;
        }

        releaseChunkAllocationRange(pending.pageIndex,
                                    pending.vertexOffset,
                                    pending.vertexCount,
                                    pending.indexOffset,
                                    pending.indexCount,
                                    false);
    }

    deferredPendingChunkReleases_.swap(stillPending);
}

void ChunkManager::Impl::deferPendingChunkRelease(const Chunk::PendingRenderMesh& pendingMesh)
{
    if (!pendingMesh.valid())
    {
        return;
    }

    deferredPendingChunkReleases_.push_back(DeferredPendingChunkRelease{
        pendingMesh.pageIndex,
        pendingMesh.vertexOffset,
        pendingMesh.indexOffset,
        pendingMesh.vertexCount,
        pendingMesh.indexCount,
        pendingMesh.uploadFenceValue});
}

void ChunkManager::Impl::releaseResidentChunkDrawAllocation(const ResidentChunkDrawAllocation& allocation)
{
    if (!allocation.valid())
    {
        return;
    }

    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        removeChunkFromExactPageMembers(allocation.pageIndex, allocation.chunkCoord);
    }

    releaseChunkAllocationRange(allocation.pageIndex,
                                allocation.exactDraw ? 0u : allocation.vertexOffset,
                                allocation.exactDraw ? 0u : allocation.vertexCount,
                                allocation.exactDraw ? 0u : allocation.indexOffset,
                                allocation.exactDraw ? 0u : allocation.indexCount,
                                true);

    if (allocation.exactDraw &&
        allocation.recordIndex != kInvalidExactGpuDrawRecordIndex)
    {
        enqueueExactDrawRecordInactive(allocation.pageIndex, allocation.recordIndex, true);
    }
}

void ChunkManager::Impl::releaseChunkAllocation(Chunk& chunk)
{
    ResidentChunkDrawAllocation liveAllocation{};
    liveAllocation.chunkCoord = chunk.coord;
    liveAllocation.pageIndex = chunk.bufferPageIndex.load(std::memory_order_acquire);
    liveAllocation.vertexOffset = chunk.vertexOffset.load(std::memory_order_acquire);
    liveAllocation.vertexCount = chunk.vertexCount.load(std::memory_order_acquire);
    liveAllocation.indexOffset = chunk.indexOffset.load(std::memory_order_acquire);
    liveAllocation.indexCount = static_cast<std::size_t>(chunk.indexCount.load(std::memory_order_acquire));
    liveAllocation.recordIndex = chunk.exactGpuRecordIndex.load(std::memory_order_acquire);
    liveAllocation.exactDraw = chunk.exactGpuResident.load(std::memory_order_acquire);

    ResidentChunkDrawAllocation pendingExactAllocation{};
    pendingExactAllocation.chunkCoord = chunk.coord;
    if (chunk.pendingExactDraw.valid())
    {
        pendingExactAllocation.pageIndex = chunk.pendingExactDraw.pageIndex;
        pendingExactAllocation.recordIndex = chunk.pendingExactDraw.recordIndex;
        pendingExactAllocation.exactDraw = true;
    }

    chunk.bufferPageIndex.store(kInvalidChunkBufferPage, std::memory_order_release);
    chunk.vertexCount.store(0, std::memory_order_release);
    chunk.indexCount.store(0, std::memory_order_release);
    chunk.vertexOffset.store(0, std::memory_order_release);
    chunk.indexOffset.store(0, std::memory_order_release);
    chunk.exactGpuResident.store(false, std::memory_order_release);
    chunk.exactGpuPublishPending.store(false, std::memory_order_release);
    chunk.exactGpuFaceOffset.store(0, std::memory_order_release);
    chunk.exactGpuFaceCount.store(0, std::memory_order_release);
    chunk.exactGpuRecordIndex.store(kInvalidExactGpuDrawRecordIndex, std::memory_order_release);
    chunk.exactGpuRecordFlags.store(0, std::memory_order_release);
    chunk.pendingExactDraw.reset();
    chunk.pendingExactDrawReady.store(false, std::memory_order_release);

    releaseResidentChunkDrawAllocation(liveAllocation);
    if (pendingExactAllocation.valid() &&
        (pendingExactAllocation.pageIndex != liveAllocation.pageIndex ||
         pendingExactAllocation.recordIndex != liveAllocation.recordIndex))
    {
        releaseResidentChunkDrawAllocation(pendingExactAllocation);
    }
}

void ChunkManager::Impl::recycleChunkGPU(Chunk& chunk)
{
    std::lock_guard<std::mutex> exactLock(exactGpuExecutionMutex_);
    Chunk::PendingRenderMesh pendingMesh;
    bool wasQueuedForUpload = false;
    std::uint8_t queuedBucket = std::numeric_limits<std::uint8_t>::max();
    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        releaseChunkAllocation(chunk);
        pendingMesh = chunk.pendingMesh;
        wasQueuedForUpload = chunk.queuedForUpload.load(std::memory_order_acquire);
        queuedBucket = chunk.queuedUploadBucket.load(std::memory_order_acquire);
        chunk.pendingMesh = {};
        chunk.pendingMeshPresent.store(false, std::memory_order_release);
        chunk.meshData.clear();
        chunk.meshReady.store(false, std::memory_order_release);
        chunk.queuedForUpload.store(false, std::memory_order_release);
        chunk.queuedUploadBucket.store(std::numeric_limits<std::uint8_t>::max(), std::memory_order_release);
        chunk.uploadQueueTicket.store(0, std::memory_order_release);
        chunk.queuedForCommit.store(false, std::memory_order_release);
        chunk.commitQueueTicket.store(0, std::memory_order_release);
        chunk.exactGpuResident.store(false, std::memory_order_release);
        chunk.exactGpuPendingNeighborMask.store(0, std::memory_order_release);
        chunk.exactGpu.reset();
    }
    refreshPendingExactGpuBuildCount(chunk);

    if (wasQueuedForUpload)
    {
        std::lock_guard<std::mutex> uploadLock(uploadQueueMutex_);
        if (queuedUploadCount_ > 0)
        {
            --queuedUploadCount_;
        }
        if (queuedBucket == static_cast<std::uint8_t>(UploadQueueBucket::InitialVisible) &&
            initialVisibleUploadCount_ > 0)
        {
            --initialVisibleUploadCount_;
        }
    }

    if (!pendingMesh.valid())
    {
        return;
    }

    const UINT64 completedUploadFenceValue = uploadContext_.completedFenceValue();
    if (pendingMesh.uploadFenceValue != 0 && completedUploadFenceValue < pendingMesh.uploadFenceValue)
    {
        deferPendingChunkRelease(pendingMesh);
        return;
    }

    releaseChunkAllocationRange(pendingMesh.pageIndex,
                                pendingMesh.vertexOffset,
                                pendingMesh.vertexCount,
                                pendingMesh.indexOffset,
                                pendingMesh.indexCount,
                                false);
}

std::size_t ChunkManager::Impl::estimateChunkRetainedBytes(const Chunk& chunk) noexcept
{
    return sizeof(Chunk) +
           chunk.blocks.capacity() * sizeof(BlockId) +
           chunk.lightLevels.capacity() * sizeof(std::uint8_t) +
           chunk.structureVoxelEdits.capacity() * sizeof(StructureVoxelEdit) +
           chunk.gpuExactSparseVoxels.capacity() * sizeof(GpuExactSparseVoxel) +
           chunk.meshData.retainedBytes();
}

std::size_t ChunkManager::Impl::chunkPoolBudgetBytes() const noexcept
{
    const double horizontalPressure =
        std::max(1.0, static_cast<double>(std::max(targetViewDistance_, 1)) /
                          static_cast<double>(kDefaultNearRenderDistance));
    const double verticalPressure =
        std::max(1.0, static_cast<double>(std::max(lastVerticalRadius_, kVerticalStreamingConfig.minRadiusChunks)) /
                          static_cast<double>(std::max(kVerticalStreamingConfig.minRadiusChunks, 1)));
    const double uploadPressure =
        1.0 + std::min(kChunkPoolMaxUploadPressure,
                       static_cast<double>(pendingUploadsLastFrame_) / kChunkPoolUploadPressureDivisor);

    double pressure = horizontalPressure * std::sqrt(verticalPressure) * uploadPressure;
    const std::size_t budget = static_cast<std::size_t>(
        static_cast<double>(kChunkPoolBaseBudgetBytes) / std::max(pressure, 1.0));
    return std::clamp(budget, kChunkPoolMinBudgetBytes, kChunkPoolBaseBudgetBytes);
}

void ChunkManager::Impl::trimChunkPoolToBudgetLocked(std::size_t budgetBytes)
{
    chunkPoolBudgetBytes_ = budgetBytes;
    while (chunkPoolBytes_ > budgetBytes && !chunkPool_.empty())
    {
        const std::size_t retainedBytes = chunkPool_.front().retainedBytes;
        chunkPool_.pop_front();
        chunkPoolBytes_ = (retainedBytes >= chunkPoolBytes_) ? 0 : (chunkPoolBytes_ - retainedBytes);
    }
}

void ChunkManager::Impl::trimChunkPoolToBudget()
{
    const std::size_t budgetBytes = chunkPoolBudgetBytes();
    std::lock_guard<std::mutex> lock(chunkPoolMutex_);
    trimChunkPoolToBudgetLocked(budgetBytes);
}

void ChunkManager::Impl::recycleChunkObject(std::shared_ptr<Chunk> chunk)
{
    if (!chunk)
    {
        return;
    }

    std::size_t retainedBytes = 0;
    {
        std::lock_guard<std::mutex> meshLock(chunk->meshMutex);
        clearPendingExactGpuBuildCount(*chunk);
        chunk->reset(chunk->coord);
        retainedBytes = estimateChunkRetainedBytes(*chunk);
    }

    const std::size_t budgetBytes = chunkPoolBudgetBytes();
    std::lock_guard<std::mutex> lock(chunkPoolMutex_);
    chunkPoolBudgetBytes_ = budgetBytes;
    if (retainedBytes <= budgetBytes)
    {
        chunkPool_.push_back(PooledChunkEntry{std::move(chunk), retainedBytes});
        chunkPoolBytes_ += retainedBytes;
    }
    trimChunkPoolToBudgetLocked(budgetBytes);
}

void ChunkManager::Impl::destroyBufferPages()
{
    std::lock_guard<std::mutex> lock(bufferPageMutex_);
    for (auto& page : bufferPages_)
    {
        page.vertexBuffer.Reset();
        page.indexBuffer.Reset();
        page.faceDescriptorBuffer.Reset();
        page.drawRecordBuffer.Reset();
        page.drawRecordMetadataBuffer.Reset();
        releaseChunkBufferPageUploadBuffers(page);
    }
    bufferPages_.clear();
    exactGpuDirtyPageIndices_.clear();
    exactGpuPageMetadataQueued_.clear();
    freeExactGpuPageCount_ = 0;
    sealRequestedPageIndices_.clear();
    sealedPendingResidentPageIndices_.clear();
    readyToResidentPageIndices_.clear();
    residentPageIndices_.clear();
    noteExactGpuEmitConfigRefresh();
}

void ChunkManager::Impl::resetColumnBudgets()
{
    jobsScheduledThisFrame_.clear();
}

int ChunkManager::Impl::baseUploadsPerColumnLimit(int verticalRadius) const noexcept
{
    const int ramp = std::max(0, verticalRadius - kVerticalStreamingConfig.minRadiusChunks);
    const int divisor = std::max(1, kVerticalStreamingConfig.uploadRampDivisor);
    const int bonus = ramp / divisor;
    const bool exactOnly = renderSettings_.totalChunks <= renderSettings_.exactChunks;
    const bool idleRadialFill =
        movementEnvelopeIdleMode_ &&
        !movementEnvelopeTurnActive_ &&
        lastHorizontalMovementShift_ == 0 &&
        lastVerticalMovementShift_ == 0;
    const int base = kVerticalStreamingConfig.uploadBasePerColumn;
    const int maxLimit = kVerticalStreamingConfig.uploadMaxPerColumn;
    int limit = base + bonus;
    if (exactOnly)
    {
        limit += 4;
        if (idleRadialFill)
        {
            limit += 3;
        }
        if (protectedPressureActive_)
        {
            limit += 3;
        }
        if (severeProtectedPressureActive_)
        {
            limit += 4;
        }
    }
    return std::clamp(limit, base, maxLimit);
}

std::size_t ChunkManager::Impl::estimateUploadQueueSize()
{
    std::lock_guard<std::mutex> lock(uploadQueueMutex_);
    return queuedUploadCount_;
}

std::size_t ChunkManager::Impl::estimatePendingExactGpuBuilds() const
{
    return pendingExactGpuBuildsCached_.load(std::memory_order_acquire);
}

std::size_t ChunkManager::Impl::estimateInitialReadyUploadQueueSize()
{
    std::lock_guard<std::mutex> lock(uploadQueueMutex_);
    return initialVisibleUploadCount_;
}

ChunkManager::Impl::UploadBudgets ChunkManager::Impl::computeUploadBudgets(int verticalRadius)
{
    UploadBudgets budgets{};
    budgets.columnLimit = baseUploadsPerColumnLimit(verticalRadius);
    const bool exactOnly = renderSettings_.totalChunks <= renderSettings_.exactChunks;
    const bool idleRadialFill =
        movementEnvelopeIdleMode_ &&
        !movementEnvelopeTurnActive_ &&
        lastHorizontalMovementShift_ == 0 &&
        lastVerticalMovementShift_ == 0;
    budgets.chunkLimit = exactOnly ? 12 : 3;
    budgets.queueSize = estimateUploadQueueSize();
    const std::size_t initialReadyUploads = estimateInitialReadyUploadQueueSize();
    const double previousQueueAgeMs = uploadQueueAgeMsLastFrame_;
    const int uploadDebtSteps = computeBacklogSteps(static_cast<int>(std::min<std::size_t>(
                                                        budgets.queueSize,
                                                        static_cast<std::size_t>(std::numeric_limits<int>::max()))),
                                                    12,
                                                    8);
    const bool exactPreload = startupEnabled_ &&
                              startupState_.preloadStarted &&
                              startupState_.phase == StreamingPhase::ExactPreload;
    const bool interactiveUploadWindow = startupEnabled_ &&
                                         startupState_.preloadStarted &&
                                         (startupState_.phase == StreamingPhase::InteractiveNearOnly ||
                                          startupState_.phase == StreamingPhase::FarRamp);
    if (startupEnabled_ && startupState_.preloadStarted)
    {
        if (exactPreload)
        {
            budgets.byteBudget = exactOnly ? 56ull * 1024ull * 1024ull : 16ull * 1024ull * 1024ull;
            budgets.columnLimit = std::min(budgets.columnLimit + (exactOnly ? 10 : 2), exactOnly ? 28 : 9);
            budgets.chunkLimit = exactOnly ? 14 : 4;
            budgets.timeBudgetMs = exactOnly ? 7.0 : 2.0;
        }
        else if (interactiveUploadWindow)
        {
            budgets.byteBudget = exactOnly ? 48ull * 1024ull * 1024ull : 16ull * 1024ull * 1024ull;
            budgets.columnLimit = std::min(budgets.columnLimit + (exactOnly ? 8 : 1), exactOnly ? 26 : 7);
            budgets.chunkLimit = exactOnly ? 13 : 3;
            budgets.timeBudgetMs = exactOnly ? 6.25 : 1.5;
        }
        else
        {
            budgets.byteBudget = exactOnly ? 48ull * 1024ull * 1024ull : 20ull * 1024ull * 1024ull;
            budgets.columnLimit = std::min(budgets.columnLimit + (exactOnly ? 7 : 0), exactOnly ? 24 : budgets.columnLimit);
            budgets.chunkLimit = exactOnly ? 13 : 3;
            budgets.timeBudgetMs = exactOnly ? 6.0 : 2.0;
        }
    }
    else
    {
        budgets.byteBudget = exactOnly ? 48ull * 1024ull * 1024ull : 20ull * 1024ull * 1024ull;
        budgets.columnLimit = std::min(budgets.columnLimit + (exactOnly ? 7 : 0), exactOnly ? 24 : budgets.columnLimit);
        budgets.chunkLimit = exactOnly ? 13 : 3;
        budgets.timeBudgetMs = exactOnly ? 6.0 : 2.0;
    }

    if (exactOnly && idleRadialFill)
    {
        budgets.byteBudget += 24ull * 1024ull * 1024ull;
        budgets.columnLimit = std::min(budgets.columnLimit + 4, 28);
        budgets.chunkLimit = std::max(budgets.chunkLimit, 16);
        budgets.timeBudgetMs = std::max(budgets.timeBudgetMs, 7.5);
    }

    if (stationaryExactFillModeActive_)
    {
        budgets.byteBudget += 80ull * 1024ull * 1024ull;
        budgets.columnLimit = std::min(std::max(budgets.columnLimit, 32) + 16, 64);
        budgets.chunkLimit = std::min(std::max(budgets.chunkLimit, 24) + 8, 40);
        budgets.timeBudgetMs = std::max(budgets.timeBudgetMs, 12.0);
    }

    if (uploadDebtSteps > 0)
    {
        if (exactPreload)
        {
            const int clampedSteps = std::min(uploadDebtSteps, 2);
            budgets.byteBudget += 4ull * 1024ull * 1024ull * static_cast<std::size_t>(clampedSteps);
            budgets.chunkLimit += clampedSteps;
            budgets.columnLimit = std::min(budgets.columnLimit + 3, exactOnly ? 30 : 10);
            budgets.timeBudgetMs =
                std::min(exactOnly ? 8.5 : 2.5, budgets.timeBudgetMs + 0.65 * static_cast<double>(clampedSteps));
        }
        else if (interactiveUploadWindow)
        {
            budgets.byteBudget += 4ull * 1024ull * 1024ull;
            budgets.chunkLimit = std::min(budgets.chunkLimit + 3, exactOnly ? 18 : 4);
            budgets.columnLimit = std::min(budgets.columnLimit + 3, exactOnly ? 28 : 8);
            if (exactOnly)
            {
                budgets.timeBudgetMs = std::min(7.5, budgets.timeBudgetMs + 0.65);
            }
        }
        else
        {
            const int clampedSteps = std::min(uploadDebtSteps, 2);
            budgets.byteBudget += 4ull * 1024ull * 1024ull * static_cast<std::size_t>(clampedSteps);
            budgets.chunkLimit += clampedSteps;
            budgets.columnLimit = std::min(budgets.columnLimit + 3, exactOnly ? 28 : 10);
            budgets.timeBudgetMs =
                std::min(exactOnly ? 8.0 : 2.5, budgets.timeBudgetMs + 0.65 * static_cast<double>(clampedSteps));
        }
    }

    if (initialReadyUploads > 0)
    {
        const int urgencySteps = std::min<int>(static_cast<int>(initialReadyUploads), 2);
        budgets.byteBudget += (exactOnly ? 8ull : 4ull) * 1024ull * 1024ull * static_cast<std::size_t>(urgencySteps);
        budgets.chunkLimit = std::min(budgets.chunkLimit + urgencySteps + (exactOnly ? 2 : 0), exactOnly ? 20 : 6);
        budgets.columnLimit = std::min(budgets.columnLimit + (exactOnly ? 3 : 2), exactOnly ? 28 : 10);
        budgets.timeBudgetMs =
            std::min(exactOnly ? 8.5 : 3.0, budgets.timeBudgetMs + 0.75 * static_cast<double>(urgencySteps));
    }

    const int queueAgePressureSteps = computeBacklogSteps(
        static_cast<int>(std::min(previousQueueAgeMs, 5000.0)),
        150,
        150);
    int latencyPressureSteps =
        std::min(queueAgePressureSteps + static_cast<int>(std::min<std::size_t>(initialReadyUploads, 4)), 4);
    const double frameBudgetMs = 1000.0 / 60.0;
    const double frameHeadroomMs = std::clamp(frameBudgetMs + 2.0 - smoothedFrameMs_, -4.0, 4.0);
    int latencyPressureCap = (frameHeadroomMs >= 1.5) ? 4 : ((frameHeadroomMs >= 0.0) ? 3 : 2);
    if (initialReadyUploads == 0 && frameHeadroomMs < 0.0)
    {
        latencyPressureCap = 1;
    }
    latencyPressureSteps = std::min(latencyPressureSteps, latencyPressureCap);
    if (latencyPressureSteps > 0)
    {
        const int maxChunkLimit = exactPreload ? (exactOnly ? 22 : 10)
                                               : (interactiveUploadWindow ? (exactOnly ? 20 : 8)
                                                                          : (exactOnly ? 20 : 7));
        const int maxColumnLimit = exactPreload ? (exactOnly ? 32 : 12) : (exactOnly ? 30 : 10);
        const double maxTimeBudgetMs = exactPreload ? (exactOnly ? 10.0 : 5.0)
                                                    : (interactiveUploadWindow ? (exactOnly ? 9.5 : 4.5)
                                                                               : (exactOnly ? 9.0 : 4.0));

        budgets.byteBudget += 8ull * 1024ull * 1024ull * static_cast<std::size_t>(latencyPressureSteps);
        budgets.chunkLimit = std::min(maxChunkLimit, budgets.chunkLimit + latencyPressureSteps);
        budgets.columnLimit =
            std::min(maxColumnLimit, budgets.columnLimit + (latencyPressureSteps + 1) / 2);
        budgets.timeBudgetMs =
            std::min(maxTimeBudgetMs, budgets.timeBudgetMs + 0.50 * static_cast<double>(latencyPressureSteps));
    }

    if (protectedPressureActive_)
    {
        budgets.byteBudget += exactOnly ? 16ull * 1024ull * 1024ull : 8ull * 1024ull * 1024ull;
        budgets.columnLimit = std::min(budgets.columnLimit + (exactOnly ? 4 : 3), exactOnly ? 30 : 11);
        budgets.chunkLimit = std::max(budgets.chunkLimit, exactOnly ? 18 : 5);
        budgets.timeBudgetMs = std::max(budgets.timeBudgetMs, exactOnly ? 8.5 : 3.0);
    }

    if (severeProtectedPressureActive_)
    {
        budgets.byteBudget += exactOnly ? 16ull * 1024ull * 1024ull : 8ull * 1024ull * 1024ull;
        budgets.columnLimit = std::min(budgets.columnLimit + (exactOnly ? 5 : 4), exactOnly ? 32 : 12);
        budgets.chunkLimit = std::max(budgets.chunkLimit, exactOnly ? 20 : 6);
        budgets.timeBudgetMs = std::max(budgets.timeBudgetMs, exactOnly ? 10.0 : 3.5);
    }

    return budgets;
}

int ChunkManager::Impl::computeBacklogSteps(int backlog, int threshold, int stepSize) noexcept
{
    if (backlog <= threshold)
    {
        return 0;
    }

    if (stepSize <= 0)
    {
        return 1;
    }

    const long long safeOver = static_cast<long long>(backlog) - static_cast<long long>(threshold);
    const long long safeStep = std::max(stepSize, 1);
    const long long steps = (safeOver + safeStep - 1) / safeStep;
    return static_cast<int>(std::min(steps, static_cast<long long>(std::numeric_limits<int>::max())));
}

int ChunkManager::Impl::computeGenerationBudget(int horizontalRadius, int verticalRadius, int backlogSteps) const
{
    const auto& tuning = kVerticalStreamingConfig.generationBudget;
    const int safeHorizontal = std::max(horizontalRadius, 0);
    const int safeVertical = std::max(verticalRadius, 0);

    double budget = static_cast<double>(tuning.baseJobsPerFrame);
    budget += static_cast<double>(tuning.jobsPerHorizontalRing) * static_cast<double>(safeHorizontal);
    budget += static_cast<double>(tuning.jobsPerVerticalLayer) * static_cast<double>(safeVertical);
    budget += static_cast<double>(tuning.backlogBoostPerStep)
              * static_cast<double>(std::max(backlogSteps, 0));

    long long result = static_cast<long long>(std::ceil(budget));
    if (tuning.maxJobsPerFrame > 0)
    {
        result = std::min(result, static_cast<long long>(tuning.maxJobsPerFrame));
    }

    result = std::max(result, 1ll);
    return static_cast<int>(std::min(result, static_cast<long long>(std::numeric_limits<int>::max())));
}

int ChunkManager::Impl::computeRingExpansionBudget(int backlogChunks) const
{
    const auto& tuning = kVerticalStreamingConfig.generationBudget;
    const int minRings = std::max(0, tuning.minRingExpansionsPerFrame);
    const int maxRings = std::max(minRings, tuning.maxRingExpansionsPerFrame);

    if (maxRings == 0)
    {
        return 0;
    }

    if (tuning.backlogRingStepSize <= 0)
    {
        return maxRings;
    }

    const int steps = computeBacklogSteps(backlogChunks,
                                          tuning.backlogStartThreshold,
                                          tuning.backlogRingStepSize);

    int budget = minRings + steps;
    budget = std::clamp(budget, minRings, maxRings);
    return budget;
}

int ChunkManager::Impl::computeColumnJobCap(int backlogSteps, int backlogChunks) const
{
    int baseCap = kVerticalStreamingConfig.maxGenerationJobsPerColumn;
    if (baseCap <= 0)
    {
        return std::numeric_limits<int>::max();
    }

    if (kVerticalStreamingConfig.backlogColumnCapReleaseThreshold > 0 &&
        backlogChunks >= kVerticalStreamingConfig.backlogColumnCapReleaseThreshold)
    {
        return std::numeric_limits<int>::max();
    }

    const int boostPerStep = kVerticalStreamingConfig.generationBudget.columnCapBoostPerStep;
    if (boostPerStep > 0 && backlogSteps > 0)
    {
        const long long boosted = static_cast<long long>(baseCap) +
                                  static_cast<long long>(backlogSteps) *
                                      static_cast<long long>(boostPerStep);
        baseCap = static_cast<int>(std::min(boosted, static_cast<long long>(std::numeric_limits<int>::max())));
    }

    return std::max(baseCap, 0);
}

void ChunkManager::Impl::resetStreamingFrontier() noexcept
{
    std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
    streamingFrontierDemands_.clear();
    playerSafetyOverlayCoords_.clear();
    streamingFrontierDispatchQueue_ = {};
    streamingFrontierVisibleRequired_ = 0;
    streamingFrontierVisibleReady_ = 0;
    streamingFrontierExactRequired_ = 0;
    streamingFrontierExactReady_ = 0;
    nextStreamingFrontierSequence_ = 1;
    streamingFrontierDispatchOrigin_ = glm::ivec3{0};
    streamingFrontierDispatchForwardXZ_ = glm::vec2{0.0f, -1.0f};
    streamingFrontierDispatchPriorityEpoch_ = 1;
}

void ChunkManager::Impl::clearStreamingChunkLifecycleStates() noexcept
{
    std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
    streamingChunkLifecycleStates_.clear();
}

ChunkManager::Impl::FrontierCoverage ChunkManager::Impl::streamingFrontierCoverageSnapshot() const noexcept
{
    std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
    FrontierCoverage coverage{
        streamingFrontierVisibleRequired_,
        streamingFrontierVisibleReady_,
        streamingFrontierExactRequired_,
        streamingFrontierExactReady_};
    for (const auto& [coord, demand] : streamingFrontierDemands_)
    {
        (void)coord;
        if (demand.forceResident)
        {
            ++coverage.protectedRequired;
            if (demand.state == FrontierDemandState::Ready)
            {
                ++coverage.protectedReady;
            }
        }

        if (!demand.countedExact)
        {
            continue;
        }

        switch (demand.state)
        {
        case FrontierDemandState::Missing:
            ++coverage.exactMissingState;
            break;
        case FrontierDemandState::WaitingDependencies:
            ++coverage.exactWaitingDependencies;
            break;
        case FrontierDemandState::QueuedGenerate:
            ++coverage.exactQueuedGenerate;
            break;
        case FrontierDemandState::Generating:
            ++coverage.exactGenerating;
            break;
        case FrontierDemandState::Meshing:
            ++coverage.exactMeshing;
            break;
        case FrontierDemandState::Ready:
            break;
        }
    }

    return coverage;
}

void ChunkManager::Impl::setStreamingFrontierDemandState(const glm::ivec3& coord, FrontierDemandState state)
{
    std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
    auto it = streamingFrontierDemands_.find(coord);
    if (it == streamingFrontierDemands_.end())
    {
        return;
    }

    FrontierChunkDemand& demand = it->second;
    const bool oldReady = demand.state == FrontierDemandState::Ready;
    const bool newReady = state == FrontierDemandState::Ready;
    if (oldReady != newReady)
    {
        if (demand.countedVisible)
        {
            streamingFrontierVisibleReady_ += newReady ? 1 : -1;
        }
        if (demand.countedExact)
        {
            streamingFrontierExactReady_ += newReady ? 1 : -1;
        }
    }

    if (demand.state != state)
    {
        demand.state = state;
        ++demand.version;
        if (state == FrontierDemandState::Missing)
        {
            queueStreamingFrontierDispatchEntryLocked(coord, demand);
        }
    }
}

void ChunkManager::Impl::queueStreamingFrontierDispatchEntryLocked(const glm::ivec3& coord,
                                                                   const FrontierChunkDemand& demand)
{
    if (demand.state != FrontierDemandState::Missing)
    {
        return;
    }

    const glm::vec3 priorityForward{
        streamingFrontierDispatchForwardXZ_.x,
        0.0f,
        streamingFrontierDispatchForwardXZ_.y};
    const bool localInteraction =
        demand.forceResident || shouldKeepChunkInteractive(coord, streamingFrontierDispatchOrigin_);
    streamingFrontierDispatchQueue_.push(FrontierDispatchEntry{
        coord,
        buildUploadPriorityKey(coord, streamingFrontierDispatchOrigin_, priorityForward),
        localInteraction,
        demand.version,
        nextStreamingFrontierSequence_++,
        streamingFrontierDispatchPriorityEpoch_});
}

void ChunkManager::Impl::refreshStreamingFrontierDispatchPriorityStateLocked(const glm::ivec3& center,
                                                                             const glm::vec3& priorityForward)
{
    glm::vec2 desiredForwardXZ = normalizePriorityForwardXZ(priorityForward);
    if (glm::dot(desiredForwardXZ, desiredForwardXZ) <= kEpsilon)
    {
        desiredForwardXZ = glm::vec2{0.0f, -1.0f};
    }

    const float facingDot =
        (glm::dot(streamingFrontierDispatchForwardXZ_, streamingFrontierDispatchForwardXZ_) > kEpsilon &&
         glm::dot(desiredForwardXZ, desiredForwardXZ) > kEpsilon)
            ? glm::dot(streamingFrontierDispatchForwardXZ_, desiredForwardXZ)
            : 1.0f;

    if (center == streamingFrontierDispatchOrigin_ && facingDot > 0.995f)
    {
        return;
    }

    streamingFrontierDispatchOrigin_ = center;
    streamingFrontierDispatchForwardXZ_ = desiredForwardXZ;
    ++streamingFrontierDispatchPriorityEpoch_;
}

void ChunkManager::Impl::setStreamingChunkLifecycleState(const glm::ivec3& coord, FrontierDemandState state)
{
    {
        std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
        streamingChunkLifecycleStates_[coord].state = state;
    }
    setStreamingFrontierDemandState(coord, state);
}

void ChunkManager::Impl::clearStreamingChunkLifecycleState(const glm::ivec3& coord)
{
    {
        std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
        streamingChunkLifecycleStates_.erase(coord);
    }
    setStreamingFrontierDemandState(coord, FrontierDemandState::Missing);
}

bool ChunkManager::Impl::tryGetStreamingChunkLifecycleState(const glm::ivec3& coord,
                                                            FrontierDemandState& outState) const noexcept
{
    std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
    auto it = streamingChunkLifecycleStates_.find(coord);
    if (it == streamingChunkLifecycleStates_.end())
    {
        return false;
    }

    outState = it->second.state;
    return true;
}

void ChunkManager::Impl::syncStreamingFrontierDemandFromRegistry(const glm::ivec3& coord)
{
    FrontierDemandState state = FrontierDemandState::Missing;
    (void)tryGetStreamingChunkLifecycleState(coord, state);
    setStreamingFrontierDemandState(coord, state);
}

void ChunkManager::Impl::applyPlanDiff(const std::shared_ptr<const ExactWindowPlan>& oldPlan,
                                       const std::shared_ptr<const ExactWindowPlan>& newPlan)
{
    std::lock_guard<std::mutex> lock(streamingFrontierMutex_);

    const std::uint64_t newGeneration = newPlan ? newPlan->generation : 0;
    if (newPlan)
    {
        for (const auto& [coord, entry] : newPlan->requiredChunks)
        {
            if (!entry.required)
            {
                continue;
            }

            auto demandIt = streamingFrontierDemands_.find(coord);
            if (demandIt == streamingFrontierDemands_.end())
            {
                FrontierChunkDemand demand{};
                demand.forceResident = entry.forceResident;
                demand.countedVisible = entry.countedVisible;
                demand.countedExact = entry.countedExact;
                demand.planGeneration = newGeneration;
                auto stateIt = streamingChunkLifecycleStates_.find(coord);
                if (stateIt != streamingChunkLifecycleStates_.end())
                {
                    demand.state = stateIt->second.state;
                }
                auto [insertIt, inserted] = streamingFrontierDemands_.emplace(coord, demand);
                (void)inserted;
                demandIt = insertIt;
                if (demandIt->second.state == FrontierDemandState::Missing)
                {
                    queueStreamingFrontierDispatchEntryLocked(coord, demandIt->second);
                }
                continue;
            }

            FrontierChunkDemand& demand = demandIt->second;
            const bool flagsChanged =
                demand.forceResident != entry.forceResident ||
                demand.countedVisible != entry.countedVisible ||
                demand.countedExact != entry.countedExact ||
                demand.planGeneration != newGeneration;
            demand.forceResident = entry.forceResident;
            demand.countedVisible = entry.countedVisible;
            demand.countedExact = entry.countedExact;
            demand.planGeneration = newGeneration;
            if (flagsChanged && demand.state == FrontierDemandState::Missing)
            {
                ++demand.version;
                queueStreamingFrontierDispatchEntryLocked(coord, demand);
            }
        }
    }

    for (auto it = streamingFrontierDemands_.begin(); it != streamingFrontierDemands_.end();)
    {
        FrontierChunkDemand& demand = it->second;
        const bool planBacked = demand.planGeneration != 0;
        if (!planBacked || demand.planGeneration == newGeneration)
        {
            ++it;
            continue;
        }
        it = streamingFrontierDemands_.erase(it);
    }

    streamingFrontierVisibleRequired_ = newPlan ? newPlan->visibleRequiredCount : 0;
    streamingFrontierExactRequired_ = newPlan ? newPlan->exactRequiredCount : 0;
    streamingFrontierVisibleReady_ = 0;
    streamingFrontierExactReady_ = 0;
    for (const auto& [coord, demand] : streamingFrontierDemands_)
    {
        (void)coord;
        if (demand.state != FrontierDemandState::Ready)
        {
            continue;
        }
        if (demand.countedVisible)
        {
            ++streamingFrontierVisibleReady_;
        }
        if (demand.countedExact)
        {
            ++streamingFrontierExactReady_;
        }
    }

    (void)oldPlan;
}

void ChunkManager::Impl::updatePlayerSafetyOverlay(const glm::ivec3& center,
                                                   int verticalRadius,
                                                   bool reconciling)
{
    std::unordered_set<glm::ivec3, ChunkHasher> desiredOverlay{};
    if (reconciling)
    {
        std::lock_guard<std::mutex> exactLock(exactPlanMutex_);
        desiredOverlay.reserve(static_cast<std::size_t>((kExactPlayerBandHorizontalRadius * 2 + 1) *
                                                        (kExactPlayerBandHorizontalRadius * 2 + 1) *
                                                        (kExactPlayerBandRadiusMax * 2 + 1)));
        const glm::ivec2 cameraColumn{center.x, center.z};
        for (int dx = -kExactPlayerBandHorizontalRadius; dx <= kExactPlayerBandHorizontalRadius; ++dx)
        {
            for (int dz = -kExactPlayerBandHorizontalRadius; dz <= kExactPlayerBandHorizontalRadius; ++dz)
            {
                const glm::ivec2 column{center.x + dx, center.z + dz};
                const ColumnChunkIntervals playerBand =
                    playerBandIntervalsForColumn(column,
                                                 cameraColumn,
                                                 center.y,
                                                 verticalRadius);
                if (playerBand.empty())
                {
                    continue;
                }

                for (int chunkY = playerBand.minChunkY(); chunkY <= playerBand.maxChunkY(); ++chunkY)
                {
                    if (!chunkYWithinIntervals(chunkY, playerBand))
                    {
                        continue;
                    }

                    const glm::ivec3 coord{column.x, chunkY, column.y};
                    const auto it = exactCoverageCache_.columnSummaries.find(column);
                    const bool alreadyTracked =
                        it != exactCoverageCache_.columnSummaries.end() &&
                        it->second.authoritative &&
                        chunkYWithinIntervals(chunkY, it->second.materializedRequiredIntervals);
                    if (!alreadyTracked)
                    {
                        desiredOverlay.insert(coord);
                    }
                }
            }
        }
    }

    std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
    for (auto it = playerSafetyOverlayCoords_.begin(); it != playerSafetyOverlayCoords_.end();)
    {
        if (desiredOverlay.find(*it) != desiredOverlay.end())
        {
            ++it;
            continue;
        }

        auto demandIt = streamingFrontierDemands_.find(*it);
        if (demandIt != streamingFrontierDemands_.end() && demandIt->second.planGeneration == 0)
        {
            streamingFrontierDemands_.erase(demandIt);
        }
        it = playerSafetyOverlayCoords_.erase(it);
    }

    for (const glm::ivec3& coord : desiredOverlay)
    {
        if (playerSafetyOverlayCoords_.insert(coord).second)
        {
            auto demandIt = streamingFrontierDemands_.find(coord);
            if (demandIt == streamingFrontierDemands_.end())
            {
                FrontierChunkDemand demand{};
                demand.forceResident = true;
                demand.planGeneration = 0;
                auto stateIt = streamingChunkLifecycleStates_.find(coord);
                if (stateIt != streamingChunkLifecycleStates_.end())
                {
                    demand.state = stateIt->second.state;
                }
                auto [insertIt, inserted] = streamingFrontierDemands_.emplace(coord, demand);
                (void)inserted;
                demandIt = insertIt;
            }

            if (demandIt->second.planGeneration == 0)
            {
                demandIt->second.forceResident = true;
                if (demandIt->second.state == FrontierDemandState::Missing)
                {
                    ++demandIt->second.version;
                    queueStreamingFrontierDispatchEntryLocked(coord, demandIt->second);
                }
            }
        }
    }
}

int ChunkManager::Impl::dispatchStreamingFrontierGenerateJobs(const glm::ivec3& center,
                                                              const glm::vec3& priorityForward,
                                                              int jobBudget)
{
    if (jobBudget <= 0)
    {
        return 0;
    }

    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const SteadyClock::time_point dispatchStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    {
        std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
        refreshStreamingFrontierDispatchPriorityStateLocked(center, priorityForward);
    }

    std::vector<FrontierDispatchEntry> deferredEntries;
    deferredEntries.reserve(64u);
    std::unordered_map<glm::ivec2, bool, ColumnHasher> columnHeightReadyCache;
    columnHeightReadyCache.reserve(128u);
    const int maxRescoreAttempts = std::max(32, jobBudget * 8);
    int rescoreAttempts = 0;
    int issued = 0;
    while (jobBudget > 0)
    {
        FrontierDispatchEntry entry{};
        FrontierChunkDemand demandSnapshot{};
        glm::ivec3 dispatchOrigin{0};
        glm::vec2 dispatchForwardXZ{0.0f, -1.0f};
        std::uint64_t dispatchPriorityEpoch = 0;
        bool needsRescore = false;
        bool foundEntry = false;
        {
            std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
            while (!streamingFrontierDispatchQueue_.empty())
            {
                entry = streamingFrontierDispatchQueue_.top();
                streamingFrontierDispatchQueue_.pop();
                auto it = streamingFrontierDemands_.find(entry.coord);
                if (it == streamingFrontierDemands_.end() ||
                    it->second.state != FrontierDemandState::Missing ||
                    it->second.version != entry.version)
                {
                    continue;
                }

                demandSnapshot = it->second;
                dispatchOrigin = streamingFrontierDispatchOrigin_;
                dispatchForwardXZ = streamingFrontierDispatchForwardXZ_;
                dispatchPriorityEpoch = streamingFrontierDispatchPriorityEpoch_;
                needsRescore = entry.priorityEpoch != dispatchPriorityEpoch;
                foundEntry = true;
                break;
            }
        }

        if (!foundEntry)
        {
            break;
        }

        if (needsRescore)
        {
            if (rescoreAttempts >= maxRescoreAttempts)
            {
                deferredEntries.push_back(entry);
                break;
            }

            ++rescoreAttempts;
            const glm::vec3 currentPriorityForward{dispatchForwardXZ.x, 0.0f, dispatchForwardXZ.y};
            entry.priority = buildUploadPriorityKey(entry.coord, dispatchOrigin, currentPriorityForward);
            entry.localInteraction =
                demandSnapshot.forceResident || shouldKeepChunkInteractive(entry.coord, dispatchOrigin);
            entry.priorityEpoch = dispatchPriorityEpoch;
            {
                std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
                entry.sequence = nextStreamingFrontierSequence_++;
            }
            deferredEntries.push_back(entry);
            continue;
        }

        const glm::ivec2 column{entry.coord.x, entry.coord.z};
        const bool localInteraction = demandSnapshot.forceResident || entry.localInteraction;
        const int horizontalDistance =
            std::max(std::abs(entry.coord.x - center.x), std::abs(entry.coord.z - center.z));
        const bool schedulable = localInteraction || horizontalDistance <= targetViewDistance_;
        if (!schedulable)
        {
            deferredEntries.push_back(entry);
            continue;
        }
        const bool requireAccurateStructureReady =
            stationaryExactFillModeActive_ && !localInteraction;
        if (requireAccurateStructureReady)
        {
            bool columnHeightReady = false;
            if (auto it = columnHeightReadyCache.find(column); it != columnHeightReadyCache.end())
            {
                columnHeightReady = it->second;
            }
            else
            {
                const int worldX = column.x * kChunkSizeX + kChunkSizeX / 2;
                const int worldZ = column.y * kChunkSizeZ + kChunkSizeZ / 2;
                int columnHeight = ColumnManager::kNoHeight;
                columnHeightReady = tryGetCachedColumnHeight(column, worldX, worldZ, columnHeight);
                columnHeightReadyCache.emplace(column, columnHeightReady);
            }
            if (!columnHeightReady)
            {
                // Keep warming the support caches, but do not block exact-only chunk generation on them.
                // Nonlocal exact chunk inputs are authored from CPU descriptors and sparse structure spans,
                // so a missing column-height cache should not strand the last demanded chunks in Missing.
                requestColumnHeightPrefetch(column, ColumnHeightPrefetchPriority::Critical, true);
            }

        }

        const auto scheduledIt = jobsScheduledThisFrame_.find(column);
        const int scheduledForColumn = (scheduledIt != jobsScheduledThisFrame_.end()) ? scheduledIt->second : 0;
        const bool columnLimited =
            generationColumnCapThisFrame_ > 0 &&
            generationColumnCapThisFrame_ < std::numeric_limits<int>::max() &&
            scheduledForColumn >= generationColumnCapThisFrame_;
        if (columnLimited)
        {
            deferredEntries.push_back(entry);
            ++ensureVolumeColumnCapSkipsLastFrame_;
            continue;
        }

        const EnsureChunkAsyncResult ensureResult =
            ensureChunkAsync(entry.coord, demandSnapshot.forceResident, localInteraction);
        if (ensureResult == EnsureChunkAsyncResult::EnqueuedGenerate)
        {
            jobsScheduledThisFrame_[column] = scheduledForColumn + 1;
            --jobBudget;
            ++issued;
        }
        else if (ensureResult == EnsureChunkAsyncResult::WaitingDependencies)
        {
            continue;
        }
        else
        {
            syncStreamingFrontierDemandFromRegistry(entry.coord);
        }
    }

    if (!deferredEntries.empty())
    {
        std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
        for (const FrontierDispatchEntry& entry : deferredEntries)
        {
            streamingFrontierDispatchQueue_.push(entry);
        }
    }

    if (benchmarkEnabled)
    {
        ensureVolumeDispatchMsLastFrame_ +=
            std::chrono::duration<double, std::milli>(SteadyClock::now() - dispatchStart).count();
    }

    return issued;
}

int ChunkManager::Impl::computeVerticalRadius(const glm::ivec3& center,
                                              int horizontalRadius,
                                              int cameraWorldY)
{
    int verticalRadius = kVerticalStreamingConfig.minRadiusChunks;

    const glm::ivec2 cameraColumn{center.x, center.z};
    const int cameraChunkY = center.y;
    const int cameraWorldChunk = floorDiv(cameraWorldY, kChunkSizeY);
    verticalRadius = std::max(verticalRadius,
                              std::abs(cameraWorldChunk - cameraChunkY) +
                                  kVerticalStreamingConfig.columnSlackChunks);

    const int sampleRadius = std::max(0,
                                      std::min(horizontalRadius, kVerticalStreamingConfig.sampleRadiusChunks));

    for (int dx = -sampleRadius; dx <= sampleRadius; ++dx)
    {
        for (int dz = -sampleRadius; dz <= sampleRadius; ++dz)
        {
            const glm::ivec2 column{center.x + dx, center.z + dz};
            const int worldX = column.x * kChunkSizeX + kChunkSizeX / 2;
            const int worldZ = column.y * kChunkSizeZ + kChunkSizeZ / 2;
            int columnHeight = ColumnManager::kNoHeight;
            if (!tryGetCachedColumnHeight(column, worldX, worldZ, columnHeight))
            {
                requestColumnHeightPrefetch(column, ColumnHeightPrefetchPriority::Critical);
            }

            const int radius = columnRadiusForHeight(column,
                                                     cameraColumn,
                                                     cameraChunkY,
                                                     verticalRadius,
                                                     columnHeight);
            verticalRadius = std::max(verticalRadius, radius);
        }
    }

    return std::clamp(verticalRadius,
                      kVerticalStreamingConfig.minRadiusChunks,
                      kVerticalStreamingConfig.maxRadiusChunks);
}

int ChunkManager::Impl::updateEvictionCenterChunkY(int targetChunkY) noexcept
{
    if (!evictionCenterInitialized_)
    {
        evictionCenterChunkY_ = targetChunkY;
        evictionCenterInitialized_ = true;
        return evictionCenterChunkY_;
    }

    const int deadband = std::max(0, kVerticalStreamingConfig.verticalEvictionDeadbandChunks);
    if (targetChunkY > evictionCenterChunkY_ + deadband)
    {
        evictionCenterChunkY_ = targetChunkY - deadband;
    }
    else if (targetChunkY < evictionCenterChunkY_ - deadband)
    {
        evictionCenterChunkY_ = targetChunkY + deadband;
    }

    return evictionCenterChunkY_;
}

int ChunkManager::Impl::computeEvictionBudget(std::size_t pendingEvictions) const noexcept
{
    const int baseBudget = std::max(1, kVerticalStreamingConfig.baseEvictionChunksPerFrame);
    const int maxBudget = std::max(baseBudget, kVerticalStreamingConfig.maxEvictionChunksPerFrame);
    const int divisor = std::max(1, kVerticalStreamingConfig.evictionBudgetBoostDivisor);
    const std::size_t safeSteps = pendingEvictions / static_cast<std::size_t>(divisor);
    const int boostedBudget = baseBudget + static_cast<int>(std::min<std::size_t>(
                                           safeSteps,
                                           static_cast<std::size_t>(std::max(0, maxBudget - baseBudget))));
    return std::clamp(boostedBudget, baseBudget, maxBudget);
}

bool ChunkManager::Impl::tryGetPredictedColumnHeight(const glm::ivec2& column, int& outHeight) const
{
    std::lock_guard<std::mutex> lock(predictedColumnMutex_);
    auto it = predictedColumnHeights_.find(column);
    if (it == predictedColumnHeights_.end())
    {
        return false;
    }

    outHeight = it->second;
    return true;
}

bool ChunkManager::Impl::tryGetCachedColumnHeight(const glm::ivec2& column,
                                                  int worldX,
                                                  int worldZ,
                                                  int& outHeight) const
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const auto lookupStart = benchmarkEnabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
    (void)worldX;
    (void)worldZ;
    const int highest = columnManager_.highestSolidBlockInChunkColumn(column);
    if (benchmarkEnabled)
    {
        benchmarkMetrics_.columnHeightLookupStage.recordMicros(
            static_cast<std::uint64_t>(
                std::chrono::duration_cast<std::chrono::microseconds>(
                    std::chrono::steady_clock::now() - lookupStart).count()));
    }

    int predictedHeight = ColumnManager::kNoHeight;
    const bool havePredictedHeight = tryGetPredictedColumnHeight(column, predictedHeight);
    if (highest != ColumnManager::kNoHeight)
    {
        outHeight = havePredictedHeight ? std::max(highest, predictedHeight) : highest;
        return true;
    }

    if (havePredictedHeight)
    {
        outHeight = predictedHeight;
        return true;
    }

    return false;
}

int ChunkManager::Impl::cacheSampledColumnHeight(const glm::ivec2& column, int worldX, int worldZ) const
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const auto sampleStart = benchmarkEnabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
    ColumnSample sample{};
    const bool ready = trySampleColumnOrRequest(sample,
                                                worldX,
                                                worldZ,
                                                std::numeric_limits<int>::min(),
                                                std::numeric_limits<int>::max(),
                                                false,
                                                DependencyPriority::Visible,
                                                JobServiceClass::Standard);
    if (benchmarkEnabled)
    {
        benchmarkMetrics_.columnHeightSampleStage.recordMicros(
            static_cast<std::uint64_t>(
                std::chrono::duration_cast<std::chrono::microseconds>(
                    std::chrono::steady_clock::now() - sampleStart).count()));
    }

    if (!ready)
    {
        int height = ColumnManager::kNoHeight;
        if (tryGetCachedColumnHeight(column, worldX, worldZ, height))
        {
            return height;
        }
        return ColumnManager::kNoHeight;
    }

    const int height = sample.surfaceY;
    mergePredictedColumnHeight(column, height);
    return height;
}

bool ChunkManager::Impl::requestWorldgenPageDependency(const glm::ivec2& pageKey,
                                                       DependencyPriority priority,
                                                       bool buildOccupancy,
                                                       bool warmStructures,
                                                       JobServiceClass serviceClass) const
{
    if (shouldStop_.load(std::memory_order_acquire))
    {
        return false;
    }

    const glm::ivec2 centerPage = worldgenPageKeyForChunkColumn({lastCenterChunk_.x, lastCenterChunk_.z});
    const std::uint32_t distance = static_cast<std::uint32_t>(std::max(std::abs(pageKey.x - centerPage.x),
                                                                       std::abs(pageKey.y - centerPage.y)));

    bool shouldNotify = false;
    bool enqueued = false;
    {
        std::lock_guard<std::mutex> queueLock(columnHeightPrefetchMutex_);
        std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
        WorldgenPageDependencyEntry& entry = worldgenPageEntries_[pageKey];
        const bool priorityChanged = priority > entry.priority;
        const bool serviceClassChanged =
            jobServiceClassIndex(serviceClass) < jobServiceClassIndex(entry.serviceClass);
        const bool buildOccupancyChanged = buildOccupancy && !entry.buildOccupancy;
        const bool warmStructuresChanged = warmStructures && !entry.warmStructures;
        const bool alreadyQueued = entry.dependencyJobQueued;
        const bool upgradeQueuedRequest =
            alreadyQueued && (priorityChanged || serviceClassChanged || buildOccupancyChanged || warmStructuresChanged);
        const std::size_t queueLimit = worldgenPageDependencyQueueLimit(std::max(entry.priority, priority),
                                                                        entry.buildOccupancy || buildOccupancy);
        const bool latencySensitive = jobServiceClassIndex(serviceClass) <=
                                          jobServiceClassIndex(JobServiceClass::LocalInteraction) ||
                                      priority >= DependencyPriority::Critical;
        const bool pageReady = entry.state == WorldgenPageState::Ready && entry.page != nullptr;

        if (alreadyQueued &&
            !priorityChanged &&
            !serviceClassChanged &&
            !buildOccupancyChanged &&
            !warmStructuresChanged)
        {
            return false;
        }

        entry.priority = std::max(entry.priority, priority);
        entry.serviceClass = mergeDependencyServiceClass(entry.serviceClass, serviceClass);
        entry.buildOccupancy = entry.buildOccupancy || buildOccupancy;
        entry.warmStructures = entry.warmStructures || warmStructures;

        if (entry.warmStructures)
        {
            ensureWorldgenPageWarmStructureLinksLocked(pageKey, entry);
        }

        if (entry.dependencyJobInFlight || entry.state == WorldgenPageState::Building)
        {
            return false;
        }

        if (worldgenPageSupportSatisfiedLocked(entry, entry.buildOccupancy, entry.warmStructures))
        {
            return false;
        }

        if (!upgradeQueuedRequest &&
            pendingWorldgenPageDependencyQueue_.size() >= queueLimit &&
            !latencySensitive)
        {
            return false;
        }

        if (!pageReady)
        {
            entry.state = WorldgenPageState::Queued;
            entry.page.reset();
        }
        entry.dependencyJobQueued = true;
        entry.lastError = {};
        entry.token = nextWorldgenPageDependencyToken_++;
        pendingWorldgenPageDependencyQueue_.push(
            WorldgenPageDependencyRequest{
                pageKey,
                entry.token,
                nextWorldgenPageDependencySequence_++,
                distance,
                entry.priority,
                entry.serviceClass,
                entry.buildOccupancy,
                entry.warmStructures});
        shouldNotify = true;
        enqueued = true;
    }

    if (shouldNotify)
    {
        const_cast<ChunkManager::Impl*>(this)->refillWorldgenPageDependencyJobs();
    }

    return enqueued;
}

bool ChunkManager::Impl::requestStructureRegionDependency(const StructureRegionKey& key,
                                                          DependencyPriority priority,
                                                          JobServiceClass serviceClass) const
{
    if (shouldStop_.load(std::memory_order_acquire))
    {
        return false;
    }

    if (tryGetReadyRegion(key))
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        StructureRegionDependencyEntry& entry = structureRegionEntries_[key];
        for (const glm::ivec2& pageKey : entry.missingWorldgenPages)
        {
            auto waiterIt = worldgenPageStructureRegionWaiters_.find(pageKey);
            if (waiterIt == worldgenPageStructureRegionWaiters_.end())
            {
                continue;
            }

            waiterIt->second.erase(key);
            if (waiterIt->second.empty())
            {
                worldgenPageStructureRegionWaiters_.erase(waiterIt);
            }
        }
        entry.state = StructureRegionState::Ready;
        entry.priority = std::max(entry.priority, priority);
        entry.serviceClass = mergeDependencyServiceClass(entry.serviceClass, serviceClass);
        entry.dependencyJobQueued = false;
        entry.lastError = {};
        entry.missingWorldgenPages.clear();
        return false;
    }

    const std::vector<glm::ivec2> requiredPageKeys = collectRegionWorldgenPageKeys(key);
    std::vector<glm::ivec2> missingPageKeys;
    missingPageKeys.reserve(requiredPageKeys.size());
    for (const glm::ivec2& pageKey : requiredPageKeys)
    {
        if (!tryGetReadyWorldgenPage(pageKey))
        {
            missingPageKeys.push_back(pageKey);
            requestWorldgenPageDependency(pageKey, priority, false, false, serviceClass);
        }
    }

    const StructureRegionKey centerRegion{
        floorDiv(lastCenterChunk_.x * kChunkSizeX, kStructureRegionSize),
        floorDiv(lastCenterChunk_.z * kChunkSizeZ, kStructureRegionSize)};
    const std::uint32_t distance =
        static_cast<std::uint32_t>(std::max(std::abs(key.regionX - centerRegion.regionX),
                                            std::abs(key.regionZ - centerRegion.regionZ)));

    bool shouldNotify = false;
    bool enqueued = false;
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        StructureRegionDependencyEntry& entry = structureRegionEntries_[key];
        const bool priorityChanged = priority > entry.priority;
        const bool serviceClassChanged =
            jobServiceClassIndex(serviceClass) < jobServiceClassIndex(entry.serviceClass);
        entry.priority = std::max(entry.priority, priority);
        entry.serviceClass = mergeDependencyServiceClass(entry.serviceClass, serviceClass);

        for (const glm::ivec2& pageKey : entry.missingWorldgenPages)
        {
            auto waiterIt = worldgenPageStructureRegionWaiters_.find(pageKey);
            if (waiterIt == worldgenPageStructureRegionWaiters_.end())
            {
                continue;
            }

            waiterIt->second.erase(key);
            if (waiterIt->second.empty())
            {
                worldgenPageStructureRegionWaiters_.erase(waiterIt);
            }
        }
        entry.missingWorldgenPages.clear();

        if (!missingPageKeys.empty())
        {
            entry.state = StructureRegionState::WaitingOnWorldgenPages;
            entry.dependencyJobQueued = false;
            entry.region.reset();
            entry.lastError = {};
            for (const glm::ivec2& pageKey : missingPageKeys)
            {
                if (entry.missingWorldgenPages.insert(pageKey).second)
                {
                    worldgenPageStructureRegionWaiters_[pageKey].insert(key);
                }
            }
            shouldNotify = false;
        }
        else
        {
            if (entry.state == StructureRegionState::Ready || entry.state == StructureRegionState::Building)
            {
                return false;
            }

            if (entry.state == StructureRegionState::Queued && !priorityChanged && !serviceClassChanged)
            {
                return false;
            }

            entry.state = StructureRegionState::Queued;
            entry.dependencyJobQueued = true;
            entry.region.reset();
            entry.lastError = {};
            entry.token = nextStructureRegionDependencyToken_++;
            pendingStructureRegionDependencyQueue_.push(
                StructureRegionDependencyRequest{
                    key,
                    entry.token,
                    nextStructureRegionDependencySequence_++,
                    distance,
                    entry.priority,
                    entry.serviceClass});
            shouldNotify = true;
            enqueued = true;
        }
    }

    if (shouldNotify)
    {
        const_cast<ChunkManager::Impl*>(this)->refillStructureRegionDependencyJobs();
    }
    else if (!missingPageKeys.empty())
    {
        const_cast<ChunkManager::Impl*>(this)->reconcileStructureRegionWaitingPages(key);
    }

    return enqueued;
}

bool ChunkManager::Impl::requestColumnHeightPrefetch(const glm::ivec2& column,
                                                     ColumnHeightPrefetchPriority priority,
                                                     bool buildOccupancy,
                                                     bool warmStructuresOnly) const
{
    if (shouldStop_.load(std::memory_order_acquire))
    {
        return false;
    }

    const bool resolveHeight = !warmStructuresOnly;
    if (resolveHeight && !buildOccupancy)
    {
        const int worldX = column.x * kChunkSizeX + kChunkSizeX / 2;
        const int worldZ = column.y * kChunkSizeZ + kChunkSizeZ / 2;
        int resolvedHeight = ColumnManager::kNoHeight;
        if (tryGetCachedColumnHeight(column, worldX, worldZ, resolvedHeight))
        {
            return false;
        }
    }

    DependencyPriority dependencyPriority = DependencyPriority::Background;
    if (priority >= ColumnHeightPrefetchPriority::Critical)
    {
        dependencyPriority = DependencyPriority::Critical;
    }
    else if (priority >= ColumnHeightPrefetchPriority::Visible)
    {
        dependencyPriority = DependencyPriority::Visible;
    }

    const bool warmStructures =
        warmStructuresOnly || buildOccupancy ||
        priority >= ColumnHeightPrefetchPriority::Visible ||
        stationaryExactFillModeActive_;
    return requestWorldgenPageDependency(worldgenPageKeyForChunkColumn(column),
                                         dependencyPriority,
                                         buildOccupancy,
                                         warmStructures,
                                         supportDependencyServiceClass(priority));
}

void ChunkManager::Impl::requestFullRadiusWorldgenPageDiscovery(const glm::ivec3& center, int horizontalRadius)
{
    if (horizontalRadius <= 0 || shouldStop_.load(std::memory_order_acquire))
    {
        return;
    }

    const int radius = std::max(horizontalRadius, 0);
    const int minWorldX = (center.x - radius) * kChunkSizeX - 1;
    const int maxWorldX = (center.x + radius + 1) * kChunkSizeX;
    const int minWorldZ = (center.z - radius) * kChunkSizeZ - 1;
    const int maxWorldZ = (center.z + radius + 1) * kChunkSizeZ;
    if (!fullRadiusWorldgenPageDiscovery_.initialized ||
        fullRadiusWorldgenPageDiscovery_.centerPage != worldgenPageKeyForChunkColumn({center.x, center.z}) ||
        fullRadiusWorldgenPageDiscovery_.minPage != worldgenPageKeyForWorld(minWorldX, minWorldZ) ||
        fullRadiusWorldgenPageDiscovery_.maxPage != worldgenPageKeyForWorld(maxWorldX, maxWorldZ))
    {
        resetFullRadiusWorldgenPageDiscovery(center, horizontalRadius);
    }

    std::size_t queuedRequests = 0;
    {
        std::lock_guard<std::mutex> lock(columnHeightPrefetchMutex_);
        queuedRequests = pendingWorldgenPageDependencyQueue_.size();
    }

    const std::size_t supportHeadroomLimit =
        worldgenPageDependencyQueueLimit(DependencyPriority::Visible, true);
    if (queuedRequests >= supportHeadroomLimit)
    {
        return;
    }

    const bool exactOnly = renderSettings_.totalChunks <= renderSettings_.exactChunks;
    const int maxNewRequests =
        std::clamp(static_cast<int>(supportHeadroomLimit - queuedRequests),
                   1,
                   stationaryExactFillModeActive_ ? 512 : (exactOnly ? 256 : 96));
    const int maxAttempts = maxNewRequests * 6;
    int attempts = 0;
    int requested = 0;
    while (requested < maxNewRequests && attempts < maxAttempts)
    {
        glm::ivec2 pageKey{0};
        ColumnHeightPrefetchPriority priority = ColumnHeightPrefetchPriority::Visible;
        if (!nextFullRadiusWorldgenPageDiscoveryPage(pageKey, priority))
        {
            break;
        }

        ++attempts;
        const DependencyPriority dependencyPriority =
            priority >= ColumnHeightPrefetchPriority::Critical ? DependencyPriority::Critical
            : priority >= ColumnHeightPrefetchPriority::Visible ? DependencyPriority::Visible
                                                                : DependencyPriority::Background;
        if (requestWorldgenPageDependency(pageKey,
                                          dependencyPriority,
                                          true,
                                          true,
                                          supportDependencyServiceClass(priority)))
        {
            ++requested;
        }
    }
}

void ChunkManager::Impl::rebuildPrefetchPageFrontier(const PrefetchPageFrontierWindow& window)
{
    if (window.mode == PrefetchPageFrontierMode::Inactive)
    {
        std::lock_guard<std::mutex> lock(worldgenPageMutex_);
        prefetchPageFrontier_.initialized = true;
        prefetchPageFrontier_.window = window;
        prefetchPageFrontier_.desiredPages.clear();
        prefetchPageFrontier_.pendingPages.clear();
        prefetchPageFrontier_.queuedPages.clear();
        return;
    }

    std::vector<PrefetchPageFrontierCandidate> candidates;
    candidates.reserve(96u);
    std::unordered_map<glm::ivec2, std::size_t, ColumnHasher> candidatePages;
    candidatePages.reserve(128u);

    auto addCandidate = [&](const glm::ivec2& pageKey,
                            ColumnHeightPrefetchPriority priority,
                            float score)
    {
        PrefetchPageFrontierRequestLevel request{};
        request.priority = priority;
        request.dependencyPriority =
            priority >= ColumnHeightPrefetchPriority::Critical ? DependencyPriority::Critical
            : priority >= ColumnHeightPrefetchPriority::Visible ? DependencyPriority::Visible
                                                                : DependencyPriority::Background;
        request.serviceClass = supportDependencyServiceClass(priority);
        request.buildOccupancy = priority >= ColumnHeightPrefetchPriority::Visible;
        request.warmStructures =
            priority >= ColumnHeightPrefetchPriority::Visible || window.stationaryExactFill;

        auto queuedIt = candidatePages.find(pageKey);
        if (queuedIt != candidatePages.end())
        {
            PrefetchPageFrontierCandidate& existing = candidates[queuedIt->second];
            if (priority > existing.request.priority)
            {
                existing.request = request;
                existing.score = score;
            }
            else if (priority == existing.request.priority)
            {
                existing.request.dependencyPriority = std::max(existing.request.dependencyPriority,
                                                               request.dependencyPriority);
                existing.request.serviceClass =
                    mergeDependencyServiceClass(existing.request.serviceClass, request.serviceClass);
                existing.request.buildOccupancy = existing.request.buildOccupancy || request.buildOccupancy;
                existing.request.warmStructures = existing.request.warmStructures || request.warmStructures;
                existing.score = std::min(existing.score, score);
            }
            return;
        }

        candidatePages.emplace(pageKey, candidates.size());
        candidates.push_back(PrefetchPageFrontierCandidate{pageKey, request, score});
    };

    auto addCandidateColumn = [&](const glm::ivec2& column,
                                  ColumnHeightPrefetchPriority priority,
                                  float score)
    {
        addCandidate(worldgenPageKeyForChunkColumn(column), priority, score);
    };

    if (window.mode == PrefetchPageFrontierMode::MovementCorridor)
    {
        glm::vec2 forward = normalizePriorityForwardXZ(lastCameraForward_);
        const glm::vec2 movementVector(static_cast<float>(window.movementDelta.x),
                                       static_cast<float>(window.movementDelta.y));
        if (glm::dot(movementVector, movementVector) > kEpsilon)
        {
            forward = glm::normalize(movementVector);
        }
        const glm::vec2 side{-forward.y, forward.x};
        const int startDistance = std::max(window.horizontalRadius - 1, 1);
        const int lookahead = std::clamp(window.horizontalRadius / 4, 4, 10);
        const int endDistance = window.horizontalRadius + lookahead;
        const int nearHalfWidth = std::clamp(window.horizontalRadius / 16, 1, 2);
        const int farHalfWidth = std::clamp(window.horizontalRadius / 12, 2, 4);

        for (int distance = startDistance; distance <= endDistance; distance += 2)
        {
            const bool insideExact = distance <= window.horizontalRadius;
            const bool justOutside = distance <= window.horizontalRadius + 2;
            const int sideHalfWidth = insideExact ? nearHalfWidth : farHalfWidth;
            const glm::vec2 anchor = glm::vec2(static_cast<float>(window.center.x),
                                               static_cast<float>(window.center.z)) +
                                     forward * static_cast<float>(distance);

            for (int sideOffset = -sideHalfWidth; sideOffset <= sideHalfWidth; ++sideOffset)
            {
                const glm::vec2 sample = anchor + side * static_cast<float>(sideOffset);
                const glm::ivec2 column{static_cast<int>(std::lround(sample.x)),
                                        static_cast<int>(std::lround(sample.y))};

                ColumnHeightPrefetchPriority priority = ColumnHeightPrefetchPriority::Normal;
                if (insideExact && std::abs(sideOffset) <= 1)
                {
                    priority = ColumnHeightPrefetchPriority::Critical;
                }
                else if (insideExact || justOutside)
                {
                    priority = ColumnHeightPrefetchPriority::Visible;
                }

                addCandidateColumn(column,
                                   priority,
                                   static_cast<float>(distance) +
                                       static_cast<float>(std::abs(sideOffset)) * 0.4f);
            }
        }
    }
    else
    {
        auto addPerimeter = [&](int ring)
        {
            const int stride = ring < 16 ? 2 : 4;
            for (int dx = -ring; dx <= ring; dx += stride)
            {
                addCandidateColumn(glm::ivec2{window.center.x + dx, window.center.z - ring},
                                   ColumnHeightPrefetchPriority::Visible,
                                   static_cast<float>(ring));
                addCandidateColumn(glm::ivec2{window.center.x + dx, window.center.z + ring},
                                   ColumnHeightPrefetchPriority::Visible,
                                   static_cast<float>(ring));
            }

            for (int dz = -ring + stride; dz <= ring - stride; dz += stride)
            {
                addCandidateColumn(glm::ivec2{window.center.x - ring, window.center.z + dz},
                                   ColumnHeightPrefetchPriority::Visible,
                                   static_cast<float>(ring));
                addCandidateColumn(glm::ivec2{window.center.x + ring, window.center.z + dz},
                                   ColumnHeightPrefetchPriority::Visible,
                                   static_cast<float>(ring));
            }
        };

        const int ringStart = std::max(window.viewDistance + 1, 1);
        const int ringEnd = std::min(window.targetViewDistance, ringStart + 2);
        for (int ring = ringStart; ring <= ringEnd; ++ring)
        {
            addPerimeter(ring);
        }
    }

    std::sort(candidates.begin(),
              candidates.end(),
              [](const PrefetchPageFrontierCandidate& lhs, const PrefetchPageFrontierCandidate& rhs)
              {
                  if (lhs.request.priority != rhs.request.priority)
                  {
                      return lhs.request.priority > rhs.request.priority;
                  }
                  if (lhs.score != rhs.score)
                  {
                      return lhs.score < rhs.score;
                  }
                  if (lhs.pageKey.x != rhs.pageKey.x)
                  {
                      return lhs.pageKey.x < rhs.pageKey.x;
                  }
                  return lhs.pageKey.y < rhs.pageKey.y;
              });

    std::unordered_map<glm::ivec2, PrefetchPageFrontierRequestLevel, ColumnHasher> desiredPages{};
    desiredPages.reserve(candidates.size());
    for (const PrefetchPageFrontierCandidate& candidate : candidates)
    {
        desiredPages.emplace(candidate.pageKey, candidate.request);
    }

    std::lock_guard<std::mutex> lock(worldgenPageMutex_);

    std::deque<glm::ivec2> filteredPendingPages{};
    std::unordered_set<glm::ivec2, ColumnHasher> filteredQueuedPages{};
    filteredQueuedPages.reserve(prefetchPageFrontier_.queuedPages.size());
    while (!prefetchPageFrontier_.pendingPages.empty())
    {
        const glm::ivec2 pageKey = prefetchPageFrontier_.pendingPages.front();
        prefetchPageFrontier_.pendingPages.pop_front();
        const auto desiredIt = desiredPages.find(pageKey);
        const auto entryIt = worldgenPageEntries_.find(pageKey);
        const bool keepPending =
            desiredIt != desiredPages.end() ||
            (entryIt != worldgenPageEntries_.end() &&
             (entryIt->second.buildOccupancy || entryIt->second.warmStructures));
        if (!keepPending || !filteredQueuedPages.insert(pageKey).second)
        {
            continue;
        }
        filteredPendingPages.push_back(pageKey);
    }
    prefetchPageFrontier_.pendingPages = std::move(filteredPendingPages);
    prefetchPageFrontier_.queuedPages = std::move(filteredQueuedPages);

    for (const PrefetchPageFrontierCandidate& candidate : candidates)
    {
        auto existingIt = prefetchPageFrontier_.desiredPages.find(candidate.pageKey);
        const bool entering = existingIt == prefetchPageFrontier_.desiredPages.end();
        const bool upgraded =
            !entering && prefetchPageFrontierRequestUpgraded(candidate.request, existingIt->second);
        WorldgenPageDependencyEntry& entry = worldgenPageEntries_[candidate.pageKey];
        if (candidate.request.warmStructures)
        {
            ensureWorldgenPageWarmStructureLinksLocked(candidate.pageKey, entry);
        }
        if (entering || upgraded)
        {
            enqueuePrefetchPageFrontierPageLocked(candidate.pageKey);
        }
    }

    prefetchPageFrontier_.initialized = true;
    prefetchPageFrontier_.window = window;
    prefetchPageFrontier_.desiredPages = std::move(desiredPages);
}

void ChunkManager::Impl::drainPrefetchPageFrontier(int requestBudget)
{
    int requested = 0;
    while (requested < requestBudget)
    {
        glm::ivec2 pageKey{0};
        PrefetchPageFrontierRequestLevel request{};
        bool haveWork = false;
        {
            std::lock_guard<std::mutex> lock(worldgenPageMutex_);
            while (!prefetchPageFrontier_.pendingPages.empty())
            {
                pageKey = prefetchPageFrontier_.pendingPages.front();
                prefetchPageFrontier_.pendingPages.pop_front();
                prefetchPageFrontier_.queuedPages.erase(pageKey);

                auto desiredIt = prefetchPageFrontier_.desiredPages.find(pageKey);
                auto entryIt = worldgenPageEntries_.find(pageKey);
                if (desiredIt == prefetchPageFrontier_.desiredPages.end() &&
                    entryIt == worldgenPageEntries_.end())
                {
                    continue;
                }

                if (entryIt != worldgenPageEntries_.end())
                {
                    request.dependencyPriority = entryIt->second.priority;
                    request.serviceClass = entryIt->second.serviceClass;
                    request.buildOccupancy = entryIt->second.buildOccupancy;
                    request.warmStructures = entryIt->second.warmStructures;
                    request.priority =
                        entryIt->second.priority >= DependencyPriority::Critical
                            ? ColumnHeightPrefetchPriority::Critical
                        : entryIt->second.priority >= DependencyPriority::Visible
                            ? ColumnHeightPrefetchPriority::Visible
                            : ColumnHeightPrefetchPriority::Background;
                }
                if (desiredIt != prefetchPageFrontier_.desiredPages.end())
                {
                    request.priority = std::max(request.priority, desiredIt->second.priority);
                    request.dependencyPriority =
                        std::max(request.dependencyPriority, desiredIt->second.dependencyPriority);
                    request.serviceClass =
                        mergeDependencyServiceClass(request.serviceClass, desiredIt->second.serviceClass);
                    request.buildOccupancy = request.buildOccupancy || desiredIt->second.buildOccupancy;
                    request.warmStructures = request.warmStructures || desiredIt->second.warmStructures;
                }

                if (entryIt != worldgenPageEntries_.end())
                {
                    WorldgenPageDependencyEntry& entry = entryIt->second;
                    if (request.warmStructures)
                    {
                        ensureWorldgenPageWarmStructureLinksLocked(pageKey, entry);
                    }
                    if (worldgenPageSupportSatisfiedLocked(entry,
                                                          request.buildOccupancy,
                                                          request.warmStructures))
                    {
                        continue;
                    }
                    if (entry.dependencyJobQueued ||
                        entry.dependencyJobInFlight ||
                        entry.state == WorldgenPageState::Queued ||
                        entry.state == WorldgenPageState::Building)
                    {
                        continue;
                    }
                }

                haveWork = true;
                break;
            }
        }

        if (!haveWork)
        {
            break;
        }

        const bool queued = requestWorldgenPageDependency(pageKey,
                                                          request.dependencyPriority,
                                                          request.buildOccupancy,
                                                          request.warmStructures,
                                                          request.serviceClass);
        if (!queued)
        {
            std::lock_guard<std::mutex> lock(worldgenPageMutex_);
            auto entryIt = worldgenPageEntries_.find(pageKey);
            if (entryIt != worldgenPageEntries_.end())
            {
                WorldgenPageDependencyEntry& entry = entryIt->second;
                if (request.warmStructures)
                {
                    ensureWorldgenPageWarmStructureLinksLocked(pageKey, entry);
                }
                if (!worldgenPageSupportSatisfiedLocked(entry,
                                                       request.buildOccupancy,
                                                       request.warmStructures) &&
                    !entry.dependencyJobQueued &&
                    !entry.dependencyJobInFlight &&
                    entry.state != WorldgenPageState::Queued &&
                    entry.state != WorldgenPageState::Building)
                {
                    enqueuePrefetchPageFrontierPageLocked(pageKey);
                }
            }
        }
        ++requested;
    }
}

void ChunkManager::Impl::prefetchVisibleWorldgenPages(const glm::ivec3& center,
                                                      const glm::ivec3& previousCenter,
                                                      int horizontalRadius)
{
    if (horizontalRadius <= 0 || shouldStop_.load(std::memory_order_acquire))
    {
        return;
    }

    const bool havePreviousCenter = updateFrameIndex_ > 1;
    const glm::ivec2 movementDelta = havePreviousCenter
        ? glm::ivec2{center.x - previousCenter.x, center.z - previousCenter.z}
        : glm::ivec2{0, 0};
    const int horizontalShift = std::max(std::abs(movementDelta.x), std::abs(movementDelta.y));
    const int verticalShift = havePreviousCenter ? std::abs(center.y - previousCenter.y) : 0;
    const bool horizontalDominant = horizontalShift > 0 && horizontalShift >= verticalShift;
    const bool verticalDominant = verticalShift > horizontalShift;
    const bool exactOnly = renderSettings_.totalChunks <= renderSettings_.exactChunks;
    const bool needsStaticWarmup = !horizontalDominant &&
                                   !verticalDominant &&
                                   targetViewDistance_ > viewDistance_ + 1;
    PrefetchPageFrontierWindow window{};
    if (horizontalDominant)
    {
        window.mode = PrefetchPageFrontierMode::MovementCorridor;
    }
    else if (needsStaticWarmup)
    {
        window.mode = PrefetchPageFrontierMode::StaticWarmup;
    }
    else
    {
        window.mode = PrefetchPageFrontierMode::Inactive;
    }
    window.center = center;
    window.movementDelta = movementDelta;
    window.horizontalRadius = horizontalRadius;
    window.viewDistance = viewDistance_;
    window.targetViewDistance = targetViewDistance_;
    window.exactOnly = exactOnly;
    window.stationaryExactFill = stationaryExactFillModeActive_;

    bool windowChanged = false;
    {
        std::lock_guard<std::mutex> lock(worldgenPageMutex_);
        windowChanged = !prefetchPageFrontier_.initialized || !(prefetchPageFrontier_.window == window);
    }
    if (windowChanged)
    {
        rebuildPrefetchPageFrontier(window);
    }

    if (window.mode == PrefetchPageFrontierMode::Inactive)
    {
        return;
    }

    const int requestBudget =
        window.mode == PrefetchPageFrontierMode::MovementCorridor
            ? (severeProtectedPressureActive_ ? 224 : (protectedPressureActive_ ? 176 : 128))
            : ((movementEnvelopeIdleMode_ && exactOnly) ? 96 : 64);
    drainPrefetchPageFrontier(requestBudget);
}

int ChunkManager::Impl::ensureColumnHeightCached(const glm::ivec2& column,
                                                 int worldX,
                                                 int worldZ) const
{
    int highest = ColumnManager::kNoHeight;
    if (tryGetCachedColumnHeight(column, worldX, worldZ, highest))
    {
        return highest;
    }

    return cacheSampledColumnHeight(column, worldX, worldZ);
}

void ChunkManager::Impl::mergePredictedColumnHeight(const glm::ivec2& column, int height) const
{
    if (height == ColumnManager::kNoHeight)
    {
        return;
    }

    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(predictedColumnMutex_);
        auto [it, inserted] = predictedColumnHeights_.try_emplace(column, height);
        if (!inserted)
        {
            if (height > it->second)
            {
                it->second = height;
                changed = true;
            }
        }
        else
        {
            changed = true;
        }
    }

    bool suppressPendingPlanDirty = false;
    if (changed)
    {
        std::lock_guard<std::mutex> lock(exactPlanMutex_);
        // Background support warmup can improve derived column-height hints while a plan for this
        // same window is building. Let that pending build finish instead of invalidating it.
        suppressPendingPlanDirty =
            exactPlanSupportBuildDepth_.load(std::memory_order_acquire) > 0 &&
            pendingExactPlanKeyValid_ &&
            pendingExactPlanStatus_ == ExactWindowPlanStatus::Building &&
            windowContainsColumn(pendingExactPlanKey_, column, 1);
    }

    if (changed && !suppressPendingPlanDirty)
    {
        markPlanDirtyColumn(column);
    }
    if (changed)
    {
        refreshWorldgenPageHeightSupportForColumn(column, true);
    }
}

void ChunkManager::Impl::refreshPredictedColumnHeightFromLoadedData(const glm::ivec2& column) const
{
    const int highest = columnManager_.highestSolidBlockInChunkColumn(column);

    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(predictedColumnMutex_);
        if (highest == ColumnManager::kNoHeight)
        {
            changed = predictedColumnHeights_.erase(column) > 0;
        }
        else
        {
            auto it = predictedColumnHeights_.find(column);
            changed = it == predictedColumnHeights_.end() || it->second != highest;
            predictedColumnHeights_[column] = highest;
        }
    }

    if (changed)
    {
        markPlanDirtyColumn(column);
    }
    refreshWorldgenPageHeightSupportForColumn(column, highest != ColumnManager::kNoHeight);
}

bool ChunkManager::Impl::materializeChunkForLocalEdit(const glm::ivec3& coord, std::shared_ptr<Chunk>& outChunk)
{
    outChunk = getChunkShared(coord);
    if (outChunk)
    {
        if (!outChunk->cpuDataResident.load(std::memory_order_acquire))
        {
            return ensureChunkCpuDataResident(*outChunk);
        }
        return true;
    }

    std::shared_ptr<Chunk> chunk = acquireChunk(coord);
    ChunkBuildScratch scratch(*chunk);
    std::array<ColumnBuildResult, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> columnResults{};
    buildChunkCpuBlocks(*chunk, scratch, false, columnResults, nullptr);

    chunk->ensureCpuDataAllocated();
    chunk->blocks = std::move(scratch.blocks);
    rebuildChunkBaseLighting(chunk->blocks, chunk->skyLightFromAboveCache, chunk->lightLevels);
    chunk->hasBlocks.store(std::any_of(chunk->blocks.begin(),
                                       chunk->blocks.end(),
                                       [](BlockId id) { return id != BlockId::Air; }),
                           std::memory_order_release);
    chunk->meshData.clear();
    chunk->meshReady.store(false, std::memory_order_release);
    chunk->state.store(ChunkState::Ready, std::memory_order_release);
    chunk->gameplayAuthority.store(ChunkGameplayAuthority::LocalGameplay, std::memory_order_release);
    chunk->residencyMode.store(ExactChunkResidencyMode::CpuAuthoritative, std::memory_order_release);
    chunk->lastDenseFrameTouched = updateFrameIndex_;
    refreshPendingExactGpuBuildCount(*chunk);

    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        auto [it, inserted] = chunks_.emplace(coord, chunk);
        if (inserted)
        {
            registerChunkRenderRegistryEntry(coord, chunk);
        }
        outChunk = inserted ? chunk : it->second;
    }

    setDenseTrackedCoord(outChunk->coord, true);

    if (!outChunk->cpuDataResident.load(std::memory_order_acquire))
    {
        (void)ensureChunkCpuDataResident(*outChunk);
    }

    columnManager_.updateChunk(makeChunkBlockView(*outChunk));
    refreshPredictedColumnHeightFromLoadedData({coord.x, coord.z});
    markSkyLightColumnDirty({coord.x, coord.z});
    return true;
}

bool ChunkManager::Impl::applyLocalBlockEdit(const glm::ivec3& worldPos, BlockId block)
{
    const glm::ivec3 chunkCoord = worldToChunkCoords(worldPos.x, worldPos.y, worldPos.z);
    if (!isChunkInsideEditBubble(chunkCoord, lastCenterChunk_))
    {
        return false;
    }

    std::shared_ptr<Chunk> chunk;
    if (!materializeChunkForLocalEdit(chunkCoord, chunk) || !chunk)
    {
        return false;
    }

    if (worldPos.y < chunk->minWorldY || worldPos.y > chunk->maxWorldY)
    {
        return false;
    }

    const glm::ivec3 local = localBlockCoords(worldPos, chunkCoord);
    const int localY = worldPos.y - chunk->minWorldY;
    const std::size_t blockIdx = blockIndex(local.x, localY, local.z);
    BlockId existing = BlockId::Air;
    std::vector<BlockId> blocksCopy;
    std::vector<std::uint8_t> lightLevelsCopy;

    {
        std::lock_guard<std::mutex> lock(chunk->meshMutex);
        existing = chunk->blocks[blockIdx];
        if (existing == block)
        {
            return false;
        }
        if (block == BlockId::Air && !isSolid(existing))
        {
            return false;
        }
        if (block != BlockId::Air && isSolid(existing))
        {
            return false;
        }

        chunk->blocks[blockIdx] = block;
        chunk->hasBlocks.store(block != BlockId::Air || chunkHasSolidBlocks(*chunk), std::memory_order_relaxed);
        chunk->lastDenseFrameTouched = updateFrameIndex_;
        chunk->gameplayAuthority.store(ChunkGameplayAuthority::LocalGameplay, std::memory_order_release);
        chunk->residencyMode.store(ExactChunkResidencyMode::CpuAuthoritative, std::memory_order_release);
        refreshPendingExactGpuBuildCount(*chunk);
        blocksCopy = chunk->blocks;
        lightLevelsCopy = chunk->lightLevels;
    }

    if (!rebuildChunkWaterResources(*chunk, blocksCopy, lightLevelsCopy))
    {
        std::lock_guard<std::mutex> lock(chunk->meshMutex);
        chunk->blocks[blockIdx] = existing;
        return false;
    }
    setDenseTrackedCoord(chunk->coord, true);

    const std::uint64_t revision = recordBlockEditOverlay(worldPos, block);
    chunk->lastLocalEditMicros.store(steadyMicrosNow(), std::memory_order_release);
    chunk->handoffTargetRevision.store(0, std::memory_order_release);
    chunk->handoffReady.store(false, std::memory_order_release);
    chunk->exactGpuPreferDenseUpload.store(true, std::memory_order_release);
    columnManager_.updateColumn(makeChunkBlockView(*chunk), local.x, local.z);
    refreshPredictedColumnHeightFromLoadedData({chunk->coord.x, chunk->coord.z});
    markSkyLightColumnDirty({chunk->coord.x, chunk->coord.z});
    chunk->exactGpuInputsVersion.store(revision, std::memory_order_release);
    chunk->exactGpuInputsDirty.store(true, std::memory_order_release);

    std::unordered_set<glm::ivec3, ChunkHasher> touchedChunks;
    touchedChunks.insert(chunkCoord);
    if (local.x == 0)
    {
        touchedChunks.insert(chunkCoord + glm::ivec3{-1, 0, 0});
    }
    if (local.x == kChunkSizeX - 1)
    {
        touchedChunks.insert(chunkCoord + glm::ivec3{1, 0, 0});
    }
    if (local.y == 0)
    {
        touchedChunks.insert(chunkCoord + glm::ivec3{0, -1, 0});
    }
    if (local.y == kChunkSizeY - 1)
    {
        touchedChunks.insert(chunkCoord + glm::ivec3{0, 1, 0});
    }
    if (local.z == 0)
    {
        touchedChunks.insert(chunkCoord + glm::ivec3{0, 0, -1});
    }
    if (local.z == kChunkSizeZ - 1)
    {
        touchedChunks.insert(chunkCoord + glm::ivec3{0, 0, 1});
    }

    queueLocalEditBatch(chunkCoord, touchedChunks, true);
    queueFarTerrainInvalidation(worldPos);
    noteRecentEdit(block == BlockId::Air ? "destroy" : "place", worldPos, chunkCoord);
    return true;
}

void ChunkManager::Impl::invalidatePredictedColumn(const glm::ivec2& column) const
{
    bool changed = false;
    {
        std::lock_guard<std::mutex> lock(predictedColumnMutex_);
        changed = predictedColumnHeights_.erase(column) > 0;
    }
    if (changed)
    {
        markPlanDirtyColumn(column);
    }
    refreshWorldgenPageHeightSupportForColumn(column, false);
}

void ChunkManager::Impl::noteRecentEdit(const char* kind,
                                        const glm::ivec3& worldPos,
                                        const glm::ivec3& chunkCoord)
{
    const auto now = std::chrono::steady_clock::now();
    {
        std::lock_guard<std::mutex> lock(recentEditDebugMutex_);
        recentEditDebug_.valid = true;
        recentEditDebug_.kind = kind ? kind : "edit";
        recentEditDebug_.worldPos = worldPos;
        recentEditDebug_.chunkCoord = chunkCoord;
        recentEditDebug_.timestamp = now;
        recentEditDebugEvents_.clear();
    }

    std::ostringstream stream;
    stream << "edit " << (kind ? kind : "edit")
           << " world=(" << worldPos.x << ", " << worldPos.y << ", " << worldPos.z << ")"
           << " chunk=(" << chunkCoord.x << ", " << chunkCoord.y << ", " << chunkCoord.z << ")";
    appendRecentEditDebugEvent(stream.str());
}

void ChunkManager::Impl::appendRecentEditDebugEvent(const std::string& event)
{
    std::lock_guard<std::mutex> lock(recentEditDebugMutex_);
    if (!recentEditDebug_.valid)
    {
        return;
    }

    const double ageMs = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - recentEditDebug_.timestamp).count();

    std::ostringstream stream;
    stream.setf(std::ios::fixed, std::ios::floatfield);
    stream << '[' << std::setprecision(1) << ageMs << " ms] " << event;
    recentEditDebugEvents_.push_back(stream.str());
    while (recentEditDebugEvents_.size() > 48)
    {
        recentEditDebugEvents_.pop_front();
    }
}

bool ChunkManager::Impl::shouldTrackRecentEditChunk(const glm::ivec3& coord) const
{
    std::lock_guard<std::mutex> lock(recentEditDebugMutex_);
    if (!recentEditDebug_.valid)
    {
        return false;
    }

    const double ageSeconds = std::chrono::duration<double>(
        std::chrono::steady_clock::now() - recentEditDebug_.timestamp).count();
    if (ageSeconds > 6.0)
    {
        return false;
    }

    return std::abs(coord.x - recentEditDebug_.chunkCoord.x) <= 1 &&
           std::abs(coord.z - recentEditDebug_.chunkCoord.z) <= 1 &&
           std::abs(coord.y - recentEditDebug_.chunkCoord.y) <= 6;
}

RecentEditHoleDebugSnapshot ChunkManager::Impl::recentEditHoleDebugSnapshot(const glm::vec3& cameraPos) const
{
    RecentEditHoleDebugSnapshot snapshot{};
    RecentEditDebugState recentEdit{};
    {
        std::lock_guard<std::mutex> lock(recentEditDebugMutex_);
        recentEdit = recentEditDebug_;
        snapshot.recentEvents.assign(recentEditDebugEvents_.begin(), recentEditDebugEvents_.end());
    }

    if (!recentEdit.valid)
    {
        return snapshot;
    }

    snapshot.editKind = recentEdit.kind;
    snapshot.editWorldPos = recentEdit.worldPos;
    snapshot.editChunkCoord = recentEdit.chunkCoord;
    snapshot.ageSeconds = std::chrono::duration<double>(
        std::chrono::steady_clock::now() - recentEdit.timestamp).count();
    snapshot.hasRecentEdit = snapshot.ageSeconds <= 6.0;

    const glm::ivec3 cameraChunk = worldToChunkCoords(static_cast<int>(std::floor(cameraPos.x)),
                                                      static_cast<int>(std::floor(cameraPos.y)),
                                                      static_cast<int>(std::floor(cameraPos.z)));
    const glm::ivec3 centerChunk = lastCenterChunk_;
    const glm::ivec2 cameraColumn{centerChunk.x, centerChunk.z};
    const int cameraChunkY = centerChunk.y;
    snapshot.cameraChunkY = cameraChunkY;
    snapshot.verticalRadius = lastVerticalRadius_;

    const int minY = std::max(0, std::min(recentEdit.chunkCoord.y, cameraChunk.y) - 4);
    const int maxY = std::max(recentEdit.chunkCoord.y + 2, cameraChunk.y + 1);
    std::vector<glm::ivec3> coords;
    coords.reserve(static_cast<std::size_t>((maxY - minY + 1) * 9));
    for (int x = recentEdit.chunkCoord.x - 1; x <= recentEdit.chunkCoord.x + 1; ++x)
    {
        for (int z = recentEdit.chunkCoord.z - 1; z <= recentEdit.chunkCoord.z + 1; ++z)
        {
            for (int y = minY; y <= maxY; ++y)
            {
                coords.push_back(glm::ivec3{x, y, z});
            }
        }
    }

    std::unordered_map<glm::ivec3, std::shared_ptr<Chunk>, ChunkHasher> localChunks;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        for (const glm::ivec3& coord : coords)
        {
            auto it = chunks_.find(coord);
            if (it != chunks_.end())
            {
                localChunks.emplace(coord, it->second);
            }
        }
    }

    std::sort(coords.begin(),
              coords.end(),
              [](const glm::ivec3& lhs, const glm::ivec3& rhs)
              {
                  if (lhs.y != rhs.y)
                  {
                      return lhs.y > rhs.y;
                  }
                  if (lhs.x != rhs.x)
                  {
                      return lhs.x < rhs.x;
                  }
                  return lhs.z < rhs.z;
              });

    const int horizontalThreshold = targetViewDistance_ + kVerticalStreamingConfig.horizontalEvictionSlack;

    for (const glm::ivec3& coord : coords)
    {
        RecentEditHoleChunkInfo info{};
        info.coord = coord;

        const glm::ivec2 column{coord.x, coord.z};
        const int worldX = coord.x * kChunkSizeX + kChunkSizeX / 2;
        const int worldZ = coord.z * kChunkSizeZ + kChunkSizeZ / 2;

        int columnHeight = columnManager_.highestSolidBlock(worldX, worldZ);
        if (columnHeight != ColumnManager::kNoHeight)
        {
            info.heightSource = "column";
        }
        else
        {
            int predictedHeight = ColumnManager::kNoHeight;
            if (tryGetPredictedColumnHeight(column, predictedHeight))
            {
                columnHeight = predictedHeight;
                info.heightSource = "predicted";
            }
            else
            {
                requestColumnHeightPrefetch(column, ColumnHeightPrefetchPriority::Background);
                columnHeight = centerChunk.y * kChunkSizeY;
                info.heightSource = "pending";
            }
        }
        info.columnHeight = columnHeight;

        const ColumnChunkIntervals intervals =
            columnIntervalsForHeight(column, cameraColumn, cameraChunkY, lastVerticalRadius_, columnHeight);
        info.columnMinChunkY = intervals.minChunkY();
        info.columnMaxChunkY = intervals.maxChunkY();

        const int horizontalDistance = std::max(std::abs(coord.x - centerChunk.x), std::abs(coord.z - centerChunk.z));
        info.wouldEvict = coord.y < 0 ||
                          horizontalDistance > horizontalThreshold ||
                          !chunkYWithinIntervals(coord.y, intervals, kVerticalStreamingConfig.columnSlackChunks);

        auto it = localChunks.find(coord);
        if (it == localChunks.end())
        {
            snapshot.chunks.push_back(std::move(info));
            continue;
        }

        const std::shared_ptr<Chunk>& chunk = it->second;
        info.present = true;
        info.stateLabel = chunkStateLabel(chunk->state.load(std::memory_order_acquire));
        info.hasBlocks = chunk->hasBlocks.load(std::memory_order_acquire);
        info.meshReady = chunk->meshReady.load(std::memory_order_acquire);
        info.queuedForUpload = chunk->queuedForUpload.load(std::memory_order_acquire);
        info.inFlight = chunk->inFlight.load(std::memory_order_acquire);
        info.indexCount = chunk->indexCount.load(std::memory_order_acquire);
        info.bufferPageIndex = chunk->bufferPageIndex.load(std::memory_order_acquire);
        snapshot.chunks.push_back(std::move(info));
    }

    return snapshot;
}

std::string ChunkManager::Impl::exactLightingDebugSnapshot(const glm::ivec3& worldPos) const
{
    std::ostringstream stream;
    const glm::ivec3 sampleChunkCoord = worldToChunkCoords(worldPos.x, worldPos.y, worldPos.z);
    const glm::ivec3 local = localBlockCoords(worldPos, sampleChunkCoord);
    const glm::ivec3 centerChunk = lastCenterChunk_;
    const glm::ivec3 delta = sampleChunkCoord - centerChunk;
    const std::uint8_t packedLight = packedLightAtWorld(worldPos);

    const std::array<std::pair<const char*, glm::ivec3>, 7> chunkCoords{{
        {"Sample", sampleChunkCoord},
        {"+X", sampleChunkCoord + glm::ivec3(1, 0, 0)},
        {"-X", sampleChunkCoord + glm::ivec3(-1, 0, 0)},
        {"+Y", sampleChunkCoord + glm::ivec3(0, 1, 0)},
        {"-Y", sampleChunkCoord + glm::ivec3(0, -1, 0)},
        {"+Z", sampleChunkCoord + glm::ivec3(0, 0, 1)},
        {"-Z", sampleChunkCoord + glm::ivec3(0, 0, -1)},
    }};

    std::unordered_map<glm::ivec3, std::shared_ptr<const Chunk>, ChunkHasher> localChunks;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        for (const auto& [_, coord] : chunkCoords)
        {
            auto it = chunks_.find(coord);
            if (it != chunks_.end())
            {
                localChunks.emplace(coord, it->second);
            }
        }
    }

    auto appendChunkState = [&](const char* label, const glm::ivec3& coord)
    {
        stream << label << " Chunk: " << coord.x << ", " << coord.y << ", " << coord.z;
        const glm::ivec3 chunkDelta = coord - centerChunk;
        stream << " delta=" << chunkDelta.x << ", " << chunkDelta.y << ", " << chunkDelta.z;
        stream << " interactive=" << (shouldKeepChunkInteractive(coord, centerChunk) ? "yes" : "no");

        const auto it = localChunks.find(coord);
        if (it == localChunks.end() || !it->second)
        {
            stream << " present=no\n";
            return;
        }

        const Chunk& chunk = *it->second;
        stream << " present=yes"
               << " state=" << chunkStateLabel(chunk.state.load(std::memory_order_acquire))
               << " residency="
               << exactChunkResidencyModeLabel(chunk.residencyMode.load(std::memory_order_acquire))
               << " cpuResident=" << (chunk.cpuDataResident.load(std::memory_order_acquire) ? "yes" : "no")
               << " hasBlocks=" << (chunk.hasBlocks.load(std::memory_order_acquire) ? "yes" : "no")
               << " meshReady=" << (chunk.meshReady.load(std::memory_order_acquire) ? "yes" : "no")
               << " uploadQueued=" << (chunk.queuedForUpload.load(std::memory_order_acquire) ? "yes" : "no")
               << " commitQueued=" << (chunk.queuedForCommit.load(std::memory_order_acquire) ? "yes" : "no")
               << " pendingMeshRefresh=" << (chunk.pendingMeshRefresh.load(std::memory_order_acquire) ? "yes" : "no")
               << " inFlight=" << chunk.inFlight.load(std::memory_order_acquire)
               << '\n';
        stream << "  geom: page=" << chunk.bufferPageIndex.load(std::memory_order_acquire)
               << " idx=" << chunk.indexCount.load(std::memory_order_acquire)
               << " verts=" << chunk.vertexCount.load(std::memory_order_acquire)
               << " meshVer=" << chunk.meshVersion.load(std::memory_order_acquire)
               << " genEpoch=" << chunk.generationEpoch.load(std::memory_order_acquire)
               << '\n';
        stream << "  light: revision=" << chunk.lightingRevision.load(std::memory_order_acquire)
               << " applied=" << chunk.appliedLightingRevision.load(std::memory_order_acquire)
               << " skyCacheGen=" << chunk.skyLightCacheGeneration.load(std::memory_order_acquire)
               << '\n';
        const std::uint8_t pendingMask = chunk.exactGpuPendingNeighborMask.load(std::memory_order_acquire);
        stream << "  exact: resident=" << (chunk.exactGpuResident.load(std::memory_order_acquire) ? "yes" : "no")
               << " queued=" << (chunk.exactGpuBuildQueued.load(std::memory_order_acquire) ? "yes" : "no")
               << " inFlight=" << (chunk.exactGpuBuildInFlight.load(std::memory_order_acquire) ? "yes" : "no")
               << " inputsDirty=" << (chunk.exactGpuInputsDirty.load(std::memory_order_acquire) ? "yes" : "no")
               << " buildVer=" << chunk.exactGpuBuildVersion.load(std::memory_order_acquire)
               << " inputs=" << chunk.exactGpuInputsVersion.load(std::memory_order_acquire)
               << " requested=" << chunk.exactGpuRequestedInputVersion.load(std::memory_order_acquire)
               << " ready=" << chunk.exactGpuReadyVersion.load(std::memory_order_acquire)
               << " pendingMask=" << exactGpuSeamMaskLabel(pendingMask)
               << " (" << hexU32(pendingMask) << ")"
               << " record=" << chunk.exactGpuRecordIndex.load(std::memory_order_acquire)
               << '\n';
    };

    stream << "Exact Sample: world=" << worldPos.x << ", " << worldPos.y << ", " << worldPos.z
           << " chunk=" << sampleChunkCoord.x << ", " << sampleChunkCoord.y << ", " << sampleChunkCoord.z
           << " local=" << local.x << ", " << local.y << ", " << local.z
           << " centerDelta=" << delta.x << ", " << delta.y << ", " << delta.z
           << " interactive=" << (shouldKeepChunkInteractive(sampleChunkCoord, centerChunk) ? "yes" : "no")
           << '\n';
    stream << "Exact Sample Light: sky=" << static_cast<int>(skyLightFromPacked(packedLight))
           << " block=" << static_cast<int>(blockLightFromPacked(packedLight))
           << " packed=" << static_cast<int>(packedLight)
           << '\n';

    for (const auto& [label, coord] : chunkCoords)
    {
        appendChunkState(label, coord);
    }

    return stream.str();
}

int ChunkManager::Impl::columnRadiusForHeight(const glm::ivec2& column,
                                              const glm::ivec2& cameraColumn,
                                              int cameraChunkY,
                                              int verticalRadius,
                                              int columnHeight) const
{
    int radius = std::max(verticalRadius, kVerticalStreamingConfig.minRadiusChunks);

    const int falloffStep = kVerticalStreamingConfig.verticalRadiusFalloffStep;
    if (falloffStep > 0)
    {
        const int horizontalDistance = std::max(std::abs(column.x - cameraColumn.x),
                                                std::abs(column.y - cameraColumn.y));
        if (horizontalDistance > 0)
        {
            const int reduction = horizontalDistance / falloffStep;
            if (reduction > 0)
            {
                radius = std::max(kVerticalStreamingConfig.minRadiusChunks, radius - reduction);
            }
        }
    }

    if (columnHeight != ColumnManager::kNoHeight)
    {
        const int highestChunk = floorDiv(columnHeight, kChunkSizeY);
        const int required = std::abs(highestChunk - cameraChunkY) +
                             kVerticalStreamingConfig.columnSlackChunks;
        radius = std::max(radius, required);
    }

    return std::clamp(radius,
                      kVerticalStreamingConfig.minRadiusChunks,
                      kVerticalStreamingConfig.maxRadiusChunks);
}

int ChunkManager::Impl::cameraBandRadiusForColumn(const glm::ivec2& column,
                                                  const glm::ivec2& cameraColumn,
                                                  int verticalRadius) const
{
    int radius = std::max(verticalRadius, kVerticalStreamingConfig.minRadiusChunks);

    const int falloffStep = kVerticalStreamingConfig.verticalRadiusFalloffStep;
    if (falloffStep > 0)
    {
        const int horizontalDistance = std::max(std::abs(column.x - cameraColumn.x),
                                                std::abs(column.y - cameraColumn.y));
        if (horizontalDistance > 0)
        {
            const int reduction = horizontalDistance / falloffStep;
            if (reduction > 0)
            {
                radius = std::max(kVerticalStreamingConfig.minRadiusChunks, radius - reduction);
            }
        }
    }

    return std::clamp(radius,
                      kVerticalStreamingConfig.minRadiusChunks,
                      kExactPlayerBandRadiusMax);
}

int ChunkManager::Impl::surfaceShellFloorChunkForHeight(const glm::ivec2& column, int columnHeight) const
{
    if (columnHeight == ColumnManager::kNoHeight)
    {
        return -1;
    }

    int minNeighborHeight = columnHeight;
    constexpr std::array<glm::ivec2, 4> kNeighborOffsets{
        glm::ivec2{1, 0},
        glm::ivec2{-1, 0},
        glm::ivec2{0, 1},
        glm::ivec2{0, -1},
    };

    for (const glm::ivec2& offset : kNeighborOffsets)
    {
        const glm::ivec2 neighbor = column + offset;
        const int worldX = neighbor.x * kChunkSizeX + kChunkSizeX / 2;
        const int worldZ = neighbor.y * kChunkSizeZ + kChunkSizeZ / 2;
        int neighborHeight = ColumnManager::kNoHeight;
        if (!tryGetCachedColumnHeight(neighbor, worldX, worldZ, neighborHeight))
        {
            continue;
        }

        if (neighborHeight != ColumnManager::kNoHeight)
        {
            minNeighborHeight = std::min(minNeighborHeight, neighborHeight);
        }
    }

    const int lowestExposedWorldY = std::min(columnHeight, minNeighborHeight + 1);
    const int baseChunk = floorDiv(std::max(0, lowestExposedWorldY), kChunkSizeY);
    return std::max(0, baseChunk - kExactSurfaceShellBelowSlackChunks);
}

bool ChunkManager::Impl::columnUsesPlayerBand(const glm::ivec2& column,
                                              const glm::ivec2& cameraColumn) const noexcept
{
    const int horizontalDistance = std::max(std::abs(column.x - cameraColumn.x),
                                            std::abs(column.y - cameraColumn.y));
    return horizontalDistance <= kExactPlayerBandHorizontalRadius;
}

ColumnChunkIntervals ChunkManager::Impl::playerBandIntervalsForColumn(const glm::ivec2& column,
                                                                      const glm::ivec2& cameraColumn,
                                                                      int cameraChunkY,
                                                                      int verticalRadius) const
{
    ColumnChunkIntervals intervals{};
    if (!columnUsesPlayerBand(column, cameraColumn))
    {
        return intervals;
    }

    const int cameraBandRadius = cameraBandRadiusForColumn(column, cameraColumn, verticalRadius);
    addColumnChunkInterval(intervals,
                           std::max(0, cameraChunkY - cameraBandRadius),
                           std::max(0, cameraChunkY + cameraBandRadius));
    return intervals;
}

void ChunkManager::Impl::addColumnChunkInterval(ColumnChunkIntervals& intervals,
                                                int minChunkY,
                                                int maxChunkY) noexcept
{
    if (maxChunkY < minChunkY || maxChunkY < 0)
    {
        return;
    }

    minChunkY = std::max(0, minChunkY);
    maxChunkY = std::max(minChunkY, maxChunkY);

    ChunkYInterval pending{minChunkY, maxChunkY};
    std::array<ChunkYInterval, ColumnChunkIntervals::kMaxIntervals + 1> merged{};
    std::size_t mergedCount = 0;
    bool inserted = false;

    for (std::uint8_t i = 0; i < intervals.count; ++i)
    {
        const ChunkYInterval current = intervals.intervals[i];
        if (current.maxChunkY + 1 < pending.minChunkY)
        {
            merged[mergedCount++] = current;
            continue;
        }

        if (pending.maxChunkY + 1 < current.minChunkY)
        {
            if (!inserted)
            {
                merged[mergedCount++] = pending;
                inserted = true;
            }
            merged[mergedCount++] = current;
            continue;
        }

        pending.minChunkY = std::min(pending.minChunkY, current.minChunkY);
        pending.maxChunkY = std::max(pending.maxChunkY, current.maxChunkY);
    }

    if (!inserted)
    {
        merged[mergedCount++] = pending;
    }

    if (mergedCount > ColumnChunkIntervals::kMaxIntervals)
    {
        intervals.intervals.fill(ChunkYInterval{});
        intervals.intervals[0] = ChunkYInterval{merged.front().minChunkY,
                                                merged[mergedCount - 1].maxChunkY};
        intervals.count = 1;
        return;
    }

    intervals.intervals.fill(ChunkYInterval{});
    for (std::size_t i = 0; i < mergedCount; ++i)
    {
        intervals.intervals[i] = merged[i];
    }
    intervals.count = static_cast<std::uint8_t>(mergedCount);
}

void ChunkManager::Impl::mergeColumnChunkIntervals(ColumnChunkIntervals& dst,
                                                   const ColumnChunkIntervals& src) noexcept
{
    for (std::uint8_t i = 0; i < src.count; ++i)
    {
        addColumnChunkInterval(dst, src.intervals[i].minChunkY, src.intervals[i].maxChunkY);
    }
}

bool ChunkManager::Impl::chunkYWithinIntervals(int chunkY,
                                               const ColumnChunkIntervals& intervals,
                                               int slackChunks) noexcept
{
    for (std::uint8_t i = 0; i < intervals.count; ++i)
    {
        const ChunkYInterval interval = intervals.intervals[i];
        if (chunkY >= interval.minChunkY - slackChunks && chunkY <= interval.maxChunkY + slackChunks)
        {
            return true;
        }
    }
    return false;
}

int ChunkManager::Impl::chunkYDistanceToIntervals(int chunkY,
                                                  const ColumnChunkIntervals& intervals,
                                                  int slackChunks) noexcept
{
    if (intervals.empty())
    {
        return std::numeric_limits<int>::max();
    }

    int bestDistance = std::numeric_limits<int>::max();
    for (std::uint8_t i = 0; i < intervals.count; ++i)
    {
        const ChunkYInterval interval = intervals.intervals[i];
        const int minChunkY = interval.minChunkY - slackChunks;
        const int maxChunkY = interval.maxChunkY + slackChunks;
        if (chunkY < minChunkY)
        {
            bestDistance = std::min(bestDistance, minChunkY - chunkY);
        }
        else if (chunkY > maxChunkY)
        {
            bestDistance = std::min(bestDistance, chunkY - maxChunkY);
        }
        else
        {
            return 0;
        }
    }

    return bestDistance;
}

glm::ivec2 ChunkManager::Impl::worldgenPageKeyForWorld(int worldX, int worldZ) noexcept
{
    constexpr int kPageSize = WorldgenPage::kSize;
    return {floorDiv(worldX, kPageSize), floorDiv(worldZ, kPageSize)};
}

glm::ivec2 ChunkManager::Impl::worldgenPageKeyForChunkColumn(const glm::ivec2& column) noexcept
{
    const int worldX = column.x * kChunkSizeX;
    const int worldZ = column.y * kChunkSizeZ;
    return worldgenPageKeyForWorld(worldX, worldZ);
}

std::size_t ChunkManager::Impl::collectChunkWorldgenPageKeys(const glm::ivec3& chunkCoord,
                                                             std::array<glm::ivec2, 4>& outPageKeys) noexcept
{
    const int minSampleWorldX = chunkCoord.x * kChunkSizeX - 1;
    const int minSampleWorldZ = chunkCoord.z * kChunkSizeZ - 1;
    const int maxSampleWorldX = chunkCoord.x * kChunkSizeX + kChunkSizeX;
    const int maxSampleWorldZ = chunkCoord.z * kChunkSizeZ + kChunkSizeZ;
    const glm::ivec2 minKey = worldgenPageKeyForWorld(minSampleWorldX, minSampleWorldZ);
    const glm::ivec2 maxKey = worldgenPageKeyForWorld(maxSampleWorldX, maxSampleWorldZ);

    std::size_t count = 0;
    const auto appendUnique = [&](const glm::ivec2& key)
    {
        for (std::size_t i = 0; i < count; ++i)
        {
            if (outPageKeys[i] == key)
            {
                return;
            }
        }
        outPageKeys[count++] = key;
    };

    appendUnique(minKey);
    appendUnique({maxKey.x, minKey.y});
    appendUnique({minKey.x, maxKey.y});
    appendUnique(maxKey);
    return count;
}

std::vector<StructureRegionKey> ChunkManager::Impl::collectChunkRegionKeys(const glm::ivec3& chunkCoord) const
{
    return collectStructureRegionKeysForChunk(chunkCoord);
}

std::vector<glm::ivec2> ChunkManager::Impl::collectRegionWorldgenPageKeys(const StructureRegionKey& regionKey) const
{
    constexpr int kStructureWorldgenPadding = kMaxStructureHorizontalRadius + 4;
    const int minWorldX = regionKey.regionX * kStructureRegionSize - kStructureWorldgenPadding;
    const int minWorldZ = regionKey.regionZ * kStructureRegionSize - kStructureWorldgenPadding;
    const int maxWorldX =
        regionKey.regionX * kStructureRegionSize + (kStructureRegionSize - 1) + kStructureWorldgenPadding;
    const int maxWorldZ =
        regionKey.regionZ * kStructureRegionSize + (kStructureRegionSize - 1) + kStructureWorldgenPadding;
    const glm::ivec2 minPageKey = worldgenPageKeyForWorld(minWorldX, minWorldZ);
    const glm::ivec2 maxPageKey = worldgenPageKeyForWorld(maxWorldX, maxWorldZ);

    std::vector<glm::ivec2> pageKeys;
    pageKeys.reserve(static_cast<std::size_t>(std::max(maxPageKey.x - minPageKey.x + 1, 0)) *
                     static_cast<std::size_t>(std::max(maxPageKey.y - minPageKey.y + 1, 0)));
    for (int pageZ = minPageKey.y; pageZ <= maxPageKey.y; ++pageZ)
    {
        for (int pageX = minPageKey.x; pageX <= maxPageKey.x; ++pageX)
        {
            pageKeys.push_back({pageX, pageZ});
        }
    }
    return pageKeys;
}

void ChunkManager::Impl::worldgenPageChunkColumnBounds(const glm::ivec2& pageKey,
                                                       glm::ivec2& outMinColumn,
                                                       glm::ivec2& outMaxColumn) noexcept
{
    const int minWorldX = pageKey.x * WorldgenPage::kSize;
    const int minWorldZ = pageKey.y * WorldgenPage::kSize;
    const int maxWorldX = minWorldX + WorldgenPage::kSize - 1;
    const int maxWorldZ = minWorldZ + WorldgenPage::kSize - 1;
    outMinColumn = {floorDiv(minWorldX, kChunkSizeX), floorDiv(minWorldZ, kChunkSizeZ)};
    outMaxColumn = {floorDiv(maxWorldX, kChunkSizeX), floorDiv(maxWorldZ, kChunkSizeZ)};
}

int ChunkManager::Impl::worldgenPageLocalChunkColumnIndex(const glm::ivec2& pageKey,
                                                          const glm::ivec2& column) noexcept
{
    const int minColumnX = pageKey.x * kWorldgenPageChunkColumnsPerAxis;
    const int minColumnZ = pageKey.y * kWorldgenPageChunkColumnsPerAxis;
    const int localX = std::clamp(column.x - minColumnX, 0, kWorldgenPageChunkColumnsPerAxis - 1);
    const int localZ = std::clamp(column.y - minColumnZ, 0, kWorldgenPageChunkColumnsPerAxis - 1);
    return localZ * kWorldgenPageChunkColumnsPerAxis + localX;
}

void ChunkManager::Impl::refreshWorldgenPageSupportStatusLocked(WorldgenPageDependencyEntry& entry) const noexcept
{
    entry.missingHeightColumns = kWorldgenPageChunkColumnCount - entry.readyHeightColumns;
    entry.missingOccupancyColumns = kWorldgenPageChunkColumnCount - entry.readyOccupancyColumns;
    entry.supportsHeight = entry.missingHeightColumns == 0;
    entry.supportsOccupancy = entry.missingOccupancyColumns == 0;
    entry.supportsWarmStructures =
        entry.warmStructureRegionsInitialized && entry.missingWarmStructureRegions == 0;
}

void ChunkManager::Impl::ensureWorldgenPageWarmStructureLinksLocked(const glm::ivec2& pageKey,
                                                                    WorldgenPageDependencyEntry& entry) const
{
    if (entry.warmStructureRegionsInitialized)
    {
        return;
    }

    constexpr int kStructureWorldgenPadding = kMaxStructureHorizontalRadius + 4;
    const int minWorldX = pageKey.x * WorldgenPage::kSize;
    const int minWorldZ = pageKey.y * WorldgenPage::kSize;
    const int maxWorldX = minWorldX + WorldgenPage::kSize - 1;
    const int maxWorldZ = minWorldZ + WorldgenPage::kSize - 1;
    const int minRegionX = floorDiv(minWorldX - kStructureWorldgenPadding, kStructureRegionSize);
    const int maxRegionX = floorDiv(maxWorldX + kStructureWorldgenPadding, kStructureRegionSize);
    const int minRegionZ = floorDiv(minWorldZ - kStructureWorldgenPadding, kStructureRegionSize);
    const int maxRegionZ = floorDiv(maxWorldZ + kStructureWorldgenPadding, kStructureRegionSize);

    entry.warmStructureRegions.clear();
    for (int regionZ = minRegionZ; regionZ <= maxRegionZ; ++regionZ)
    {
        for (int regionX = minRegionX; regionX <= maxRegionX; ++regionX)
        {
            const StructureRegionKey regionKey{regionX, regionZ};
            entry.warmStructureRegions.insert(regionKey);
            structureRegionWorldgenPages_[regionKey].insert(pageKey);
        }
    }

    entry.warmStructureRegionsInitialized = true;
    refreshWorldgenPageWarmStructureSupportLocked(pageKey, entry);
}

void ChunkManager::Impl::refreshWorldgenPageWarmStructureSupportLocked(const glm::ivec2& pageKey,
                                                                       WorldgenPageDependencyEntry& entry) const
{
    (void)pageKey;
    if (!entry.warmStructureRegionsInitialized)
    {
        entry.missingWarmStructureRegions = 0;
        entry.supportsWarmStructures = false;
        return;
    }

    int missingRegionCount = 0;
    for (const StructureRegionKey& regionKey : entry.warmStructureRegions)
    {
        if (!tryGetReadyRegion(regionKey))
        {
            ++missingRegionCount;
        }
    }

    entry.missingWarmStructureRegions = missingRegionCount;
    refreshWorldgenPageSupportStatusLocked(entry);
}

void ChunkManager::Impl::refreshWorldgenPageHeightSupportForColumn(const glm::ivec2& column, bool ready) const
{
    const glm::ivec2 pageKey = worldgenPageKeyForChunkColumn(column);
    std::lock_guard<std::mutex> lock(worldgenPageMutex_);
    WorldgenPageDependencyEntry& entry = worldgenPageEntries_[pageKey];
    const int bitIndex = worldgenPageLocalChunkColumnIndex(pageKey, column);
    const std::uint32_t bitMask = 1u << bitIndex;
    const bool alreadyReady = (entry.heightReadyBits & bitMask) != 0;
    if (ready == alreadyReady)
    {
        return;
    }

    if (ready)
    {
        entry.heightReadyBits |= bitMask;
        ++entry.readyHeightColumns;
    }
    else
    {
        entry.heightReadyBits &= ~bitMask;
        entry.readyHeightColumns = std::max(entry.readyHeightColumns - 1, 0);
    }

    refreshWorldgenPageSupportStatusLocked(entry);
    if (!ready)
    {
        enqueueDirtyPrefetchPageLocked(pageKey, entry);
    }
}

void ChunkManager::Impl::refreshWorldgenPageOccupancySupportForColumn(const glm::ivec2& column, bool ready) const
{
    const glm::ivec2 pageKey = worldgenPageKeyForChunkColumn(column);
    std::lock_guard<std::mutex> lock(worldgenPageMutex_);
    WorldgenPageDependencyEntry& entry = worldgenPageEntries_[pageKey];
    const int bitIndex = worldgenPageLocalChunkColumnIndex(pageKey, column);
    const std::uint32_t bitMask = 1u << bitIndex;
    const bool alreadyReady = (entry.occupancyReadyBits & bitMask) != 0;
    if (ready == alreadyReady)
    {
        return;
    }

    if (ready)
    {
        entry.occupancyReadyBits |= bitMask;
        ++entry.readyOccupancyColumns;
    }
    else
    {
        entry.occupancyReadyBits &= ~bitMask;
        entry.readyOccupancyColumns = std::max(entry.readyOccupancyColumns - 1, 0);
    }

    refreshWorldgenPageSupportStatusLocked(entry);
    if (!ready)
    {
        enqueueDirtyPrefetchPageLocked(pageKey, entry);
    }
}

bool ChunkManager::Impl::worldgenPageSupportSatisfiedLocked(const WorldgenPageDependencyEntry& entry,
                                                            bool buildOccupancy,
                                                            bool warmStructures) const noexcept
{
    if (entry.state != WorldgenPageState::Ready || !entry.page || !entry.supportsHeight)
    {
        return false;
    }
    if (buildOccupancy && !entry.supportsOccupancy)
    {
        return false;
    }
    if (warmStructures && !entry.supportsWarmStructures)
    {
        return false;
    }
    return true;
}

void ChunkManager::Impl::enqueuePrefetchPageFrontierPageLocked(const glm::ivec2& pageKey) const
{
    if (prefetchPageFrontier_.queuedPages.insert(pageKey).second)
    {
        prefetchPageFrontier_.pendingPages.push_back(pageKey);
    }
}

void ChunkManager::Impl::enqueueDirtyPrefetchPageLocked(const glm::ivec2& pageKey,
                                                        const WorldgenPageDependencyEntry& entry) const
{
    if (!prefetchPageFrontier_.desiredPages.contains(pageKey) &&
        !entry.buildOccupancy &&
        !entry.warmStructures)
    {
        return;
    }

    if (entry.dependencyJobQueued || entry.dependencyJobInFlight)
    {
        return;
    }

    enqueuePrefetchPageFrontierPageLocked(pageKey);
}

bool ChunkManager::Impl::prefetchPageFrontierRequestUpgraded(
    const PrefetchPageFrontierRequestLevel& desired,
    const PrefetchPageFrontierRequestLevel& existing) noexcept
{
    return desired.priority > existing.priority ||
           jobServiceClassIndex(desired.serviceClass) < jobServiceClassIndex(existing.serviceClass) ||
           (desired.buildOccupancy && !existing.buildOccupancy) ||
           (desired.warmStructures && !existing.warmStructures);
}

std::shared_ptr<const ChunkManager::Impl::WorldgenPage>
ChunkManager::Impl::tryGetReadyWorldgenPage(const glm::ivec2& pageKey) const
{
    std::lock_guard<std::mutex> lock(worldgenPageMutex_);
    auto it = worldgenPageEntries_.find(pageKey);
    if (it == worldgenPageEntries_.end() ||
        it->second.state != WorldgenPageState::Ready ||
        !it->second.page)
    {
        return {};
    }
    return it->second.page;
}

std::shared_ptr<ChunkManager::Impl::WorldgenPage>
ChunkManager::Impl::buildWorldgenPage(const glm::ivec2& pageKey) const
{
    if (!surfaceMap_ || !climateMap_)
    {
        throw std::runtime_error("Worldgen page build requires initialized surface and climate maps");
    }

    std::shared_ptr<WorldgenPage> page = std::make_shared<WorldgenPage>();
    page->key = pageKey;
    page->baseWorld = pageKey * WorldgenPage::kSize;

    const terrain::SurfaceFragment& surfaceFragment = surfaceMap_->getFragment(pageKey);
    for (int localZ = 0; localZ < WorldgenPage::kSize; ++localZ)
    {
        for (int localX = 0; localX < WorldgenPage::kSize; ++localX)
        {
            const std::size_t index =
                static_cast<std::size_t>(localZ) * WorldgenPage::kSize + static_cast<std::size_t>(localX);
            WorldgenColumnValue& worldgenColumn = page->columns[index];
            worldgenColumn.surface = surfaceFragment.column(localX, localZ);

            const int worldX = page->baseWorld.x + localX;
            const int worldZ = page->baseWorld.y + localZ;
            const terrain::ClimateSample climateSample = climateMap_->sample(worldX, worldZ);
            const BiomeDefinition* biome = worldgenColumn.surface.dominantBiome;

            worldgenColumn.biomeIndex =
                biome != nullptr
                    ? static_cast<std::uint32_t>(biomeDatabase_.definitionIndex(*biome))
                    : (std::numeric_limits<std::uint32_t>::max)();
            worldgenColumn.distanceToCoast = climateSample.distanceToCoast;
            worldgenColumn.signedDistanceToCoast = climateSample.signedDistanceToCoast;
            worldgenColumn.landBaseHeight = climateSample.landBaseHeight;
            worldgenColumn.oceanBaseHeight = climateSample.oceanBaseHeight;
            worldgenColumn.keepOriginalMix = climateSample.keepOriginalMix;
            worldgenColumn.dominantIsOcean = climateSample.dominantIsOcean;
            worldgenColumn.grassTintIndex = worldgenGrassTintIndexForBiome(biome);

            if (biome != nullptr)
            {
                worldgenColumn.surfaceBlock = biome->surfaceBlock;
                worldgenColumn.fillerBlock = biome->fillerBlock;
                worldgenColumn.smoothBeaches = biome->terrainSettings.smoothBeaches;
                worldgenColumn.taigaBiome = terrain::isTaigaBiome(*biome);
                worldgenColumn.soilCreepStrength = biome->terrainSettings.soilCreep.strength;
                worldgenColumn.soilCreepMaxStep =
                    static_cast<std::uint16_t>(std::max(biome->terrainSettings.soilCreep.maxStep, 0));
                worldgenColumn.soilCreepMaxDepth =
                    static_cast<std::uint16_t>(std::max(biome->terrainSettings.soilCreep.maxDepth, 0));
                worldgenColumn.waterFillEnabled = biome->terrainSettings.waterFill.enabled;
                worldgenColumn.waterFillMaxDepth =
                    static_cast<std::uint16_t>(std::max(biome->terrainSettings.waterFill.maxDepth, 0));
                worldgenColumn.waterBlock = biome->terrainSettings.waterFill.block;
                worldgenColumn.stripesEnabled = biome->terrainSettings.stripes.enabled;
                worldgenColumn.stripePeriod =
                    static_cast<std::uint16_t>(std::max(biome->terrainSettings.stripes.period, 0));
                worldgenColumn.stripeThickness =
                    static_cast<std::uint16_t>(std::max(biome->terrainSettings.stripes.thickness, 0));
                worldgenColumn.stripeNoiseThreshold = biome->terrainSettings.stripes.noiseThreshold;
                worldgenColumn.stripeBlock = biome->terrainSettings.stripes.block;
            }

            page->gpuColumns[index] = packGpuWorldgenPageColumn(worldgenColumn);
        }
    }
    return page;
}

void ChunkManager::Impl::publishWorldgenPageReady(const glm::ivec2& pageKey,
                                                  const std::shared_ptr<WorldgenPage>& page)
{
    std::vector<DeferredChunkDependencies> readyDependencies;
    std::vector<glm::ivec3> readyCoords;
    bool shouldRefillStructureJobs = false;
    bool republishedReadyPage = false;
    {
        std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
        WorldgenPageDependencyEntry& entry = worldgenPageEntries_[pageKey];
        republishedReadyPage =
            entry.state == WorldgenPageState::Ready &&
            entry.page == page;
        entry.state = WorldgenPageState::Ready;
        entry.page = page;
        entry.lastError = {};
        entry.dependencyJobQueued = false;
        entry.dependencyJobInFlight = false;
        if (entry.warmStructures)
        {
            ensureWorldgenPageWarmStructureLinksLocked(pageKey, entry);
        }
        refreshWorldgenPageWarmStructureSupportLocked(pageKey, entry);
    }

    {
        std::lock_guard<std::mutex> lock(deferredChunkDependencyMutex_);
        auto waiterIt = worldgenPageWaiters_.find(pageKey);
        if (waiterIt != worldgenPageWaiters_.end())
        {
            for (const glm::ivec3& coord : waiterIt->second)
            {
                auto deferredIt = deferredChunkDependencies_.find(coord);
                if (deferredIt == deferredChunkDependencies_.end())
                {
                    continue;
                }

                DeferredChunkDependencies& deferred = deferredIt->second;
                if (deferred.missingWorldgenPages.erase(pageKey) > 0 && deferred.outstandingDependencyCount > 0)
                {
                    --deferred.outstandingDependencyCount;
                }
                if (!deferred.missingWorldgenPages.empty() || !deferred.missingStructureRegions.empty())
                {
                    continue;
                }

                readyCoords.push_back(coord);
                readyDependencies.push_back(deferred);
                deferredChunkDependencies_.erase(deferredIt);
            }
            worldgenPageWaiters_.erase(waiterIt);
        }
    }

    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        auto waiterIt = worldgenPageStructureRegionWaiters_.find(pageKey);
        if (waiterIt != worldgenPageStructureRegionWaiters_.end())
        {
            const StructureRegionKey centerRegion{
                floorDiv(lastCenterChunk_.x * kChunkSizeX, kStructureRegionSize),
                floorDiv(lastCenterChunk_.z * kChunkSizeZ, kStructureRegionSize)};
            for (const StructureRegionKey& regionKey : waiterIt->second)
            {
                auto entryIt = structureRegionEntries_.find(regionKey);
                if (entryIt == structureRegionEntries_.end())
                {
                    continue;
                }

                StructureRegionDependencyEntry& entry = entryIt->second;
                entry.missingWorldgenPages.erase(pageKey);
                if (!entry.missingWorldgenPages.empty() ||
                    entry.state != StructureRegionState::WaitingOnWorldgenPages)
                {
                    continue;
                }

                entry.state = StructureRegionState::Queued;
                entry.dependencyJobQueued = true;
                entry.lastError = {};
                entry.token = nextStructureRegionDependencyToken_++;
                pendingStructureRegionDependencyQueue_.push(
                    StructureRegionDependencyRequest{
                        regionKey,
                        entry.token,
                        nextStructureRegionDependencySequence_++,
                        static_cast<std::uint32_t>(std::max(std::abs(regionKey.regionX - centerRegion.regionX),
                                                           std::abs(regionKey.regionZ - centerRegion.regionZ))),
                        entry.priority,
                        entry.serviceClass});
                shouldRefillStructureJobs = true;
            }
            worldgenPageStructureRegionWaiters_.erase(waiterIt);
        }
    }

    for (std::size_t index = 0; index < readyCoords.size(); ++index)
    {
        queueDeferredChunkGenerateIfReady(readyCoords[index], readyDependencies[index]);
    }

    if (shouldRefillStructureJobs)
    {
        refillStructureRegionDependencyJobs();
    }

    if (republishedReadyPage)
    {
        return;
    }

    glm::ivec2 minColumn{0};
    glm::ivec2 maxColumn{0};
    worldgenPageChunkColumnBounds(pageKey, minColumn, maxColumn);
    for (int columnZ = minColumn.y - 1; columnZ <= maxColumn.y + 1; ++columnZ)
    {
        for (int columnX = minColumn.x - 1; columnX <= maxColumn.x + 1; ++columnX)
        {
            invalidateColumnSlabOccupancy({columnX, columnZ});
        }
    }
    markPlanDirtyWorldgenPage(pageKey);
}

void ChunkManager::Impl::publishWorldgenPageFailure(const glm::ivec2& pageKey, std::exception_ptr error)
{
    {
        std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
        WorldgenPageDependencyEntry& entry = worldgenPageEntries_[pageKey];
        entry.state = WorldgenPageState::Failed;
        entry.page.reset();
        entry.lastError = error;
        entry.dependencyJobQueued = false;
        entry.dependencyJobInFlight = false;
        refreshWorldgenPageSupportStatusLocked(entry);
    }
    markPlanDirtyWorldgenPage(pageKey);
}

std::shared_ptr<const StructureRegion> ChunkManager::Impl::tryGetReadyRegion(const StructureRegionKey& key) const
{
    return structureRegistry_.tryGetReadyRegion(key);
}

std::shared_ptr<StructureRegion> ChunkManager::Impl::buildStructureRegionFromReadyPages(
    const StructureRegionKey& key) const
{
    const StructureSampleColumnFn sampleColumnFn = [this](int worldX, int worldZ) -> ColumnSample
    {
        return sampleColumnReadyOrThrow(worldX, worldZ);
    };
    const StructureSurfaceBlockFn surfaceBlockFn =
        [this](int worldX, int worldZ, const ColumnSample& sample) -> BlockId
    {
        if (!sample.dominantBiome)
        {
            return BlockId::Air;
        }
        const terrain::TerrainColumnBlocks blocks =
            terrain::resolveTerrainColumnBlocks(*sample.dominantBiome, sample, worldX, worldZ, globalSeaLevel_);
        return blocks.surfaceBlock;
    };
    const StructureDensityFn densityFn = [this](int worldX, int worldZ) noexcept
    {
        return noise_.fbm(static_cast<float>(worldX) * 0.05f,
                          static_cast<float>(worldZ) * 0.05f,
                          4,
                          0.55f,
                          2.0f);
    };
    return std::make_shared<StructureRegion>(buildStructureRegionData(key, sampleColumnFn, surfaceBlockFn, densityFn));
}

void ChunkManager::Impl::publishStructureRegionReady(const StructureRegionKey& key,
                                                     const std::shared_ptr<StructureRegion>& region)
{
    if (!region)
    {
        return;
    }

    std::vector<DeferredChunkDependencies> readyDependencies;
    std::vector<glm::ivec3> readyCoords;
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        StructureRegionDependencyEntry& entry = structureRegionEntries_[key];
        for (const glm::ivec2& pageKey : entry.missingWorldgenPages)
        {
            auto waiterIt = worldgenPageStructureRegionWaiters_.find(pageKey);
            if (waiterIt == worldgenPageStructureRegionWaiters_.end())
            {
                continue;
            }

            waiterIt->second.erase(key);
            if (waiterIt->second.empty())
            {
                worldgenPageStructureRegionWaiters_.erase(waiterIt);
            }
        }

        entry.state = StructureRegionState::Ready;
        entry.dependencyJobQueued = false;
        entry.region = region;
        entry.lastError = {};
        entry.missingWorldgenPages.clear();
    }

    structureRegistry_.publishReady(key, region);
    {
        std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
        auto linkedPagesIt = structureRegionWorldgenPages_.find(key);
        if (linkedPagesIt != structureRegionWorldgenPages_.end())
        {
            for (const glm::ivec2& pageKey : linkedPagesIt->second)
            {
                auto entryIt = worldgenPageEntries_.find(pageKey);
                if (entryIt == worldgenPageEntries_.end())
                {
                    continue;
                }

                refreshWorldgenPageWarmStructureSupportLocked(pageKey, entryIt->second);
            }
        }
    }
    markPlanDirtyStructureRegion(key);
    for (const auto& [affectedColumn, span] : region->chunkColumnSpans)
    {
        if (span.valid())
        {
            invalidateColumnSlabOccupancy(affectedColumn);
        }
    }

    {
        std::lock_guard<std::mutex> lock(deferredChunkDependencyMutex_);
        auto waiterIt = structureRegionWaiters_.find(key);
        if (waiterIt != structureRegionWaiters_.end())
        {
            for (const glm::ivec3& coord : waiterIt->second)
            {
                auto deferredIt = deferredChunkDependencies_.find(coord);
                if (deferredIt == deferredChunkDependencies_.end())
                {
                    continue;
                }

                DeferredChunkDependencies& deferred = deferredIt->second;
                if (deferred.missingStructureRegions.erase(key) > 0 && deferred.outstandingDependencyCount > 0)
                {
                    --deferred.outstandingDependencyCount;
                }
                if (!deferred.missingWorldgenPages.empty() || !deferred.missingStructureRegions.empty())
                {
                    continue;
                }

                readyCoords.push_back(coord);
                readyDependencies.push_back(deferred);
                deferredChunkDependencies_.erase(deferredIt);
            }
            structureRegionWaiters_.erase(waiterIt);
        }
    }

    for (std::size_t index = 0; index < readyCoords.size(); ++index)
    {
        queueDeferredChunkGenerateIfReady(readyCoords[index], readyDependencies[index]);
    }
}

void ChunkManager::Impl::publishStructureRegionFailure(const StructureRegionKey& key, std::exception_ptr error)
{
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        StructureRegionDependencyEntry& entry = structureRegionEntries_[key];
        for (const glm::ivec2& pageKey : entry.missingWorldgenPages)
        {
            auto waiterIt = worldgenPageStructureRegionWaiters_.find(pageKey);
            if (waiterIt == worldgenPageStructureRegionWaiters_.end())
            {
                continue;
            }

            waiterIt->second.erase(key);
            if (waiterIt->second.empty())
            {
                worldgenPageStructureRegionWaiters_.erase(waiterIt);
            }
        }

        entry.state = StructureRegionState::Failed;
        entry.dependencyJobQueued = false;
        entry.region.reset();
        entry.missingWorldgenPages.clear();
        entry.lastError = error;
    }

    {
        std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
        auto linkedPagesIt = structureRegionWorldgenPages_.find(key);
        if (linkedPagesIt != structureRegionWorldgenPages_.end())
        {
            for (const glm::ivec2& pageKey : linkedPagesIt->second)
            {
                auto entryIt = worldgenPageEntries_.find(pageKey);
                if (entryIt == worldgenPageEntries_.end())
                {
                    continue;
                }

                refreshWorldgenPageWarmStructureSupportLocked(pageKey, entryIt->second);
                enqueueDirtyPrefetchPageLocked(pageKey, entryIt->second);
            }
        }
    }
    markPlanDirtyStructureRegion(key);
}

bool ChunkManager::Impl::requestSampleColumnDependency(const glm::ivec2& pageKey,
                                                       DependencyPriority priority,
                                                       JobServiceClass serviceClass) const
{
    if (tryGetReadyWorldgenPage(pageKey))
    {
        return true;
    }

    (void)requestWorldgenPageDependency(pageKey, priority, false, false, serviceClass);
    return false;
}

bool ChunkManager::Impl::requestColumnOccupancyDependencies(const glm::ivec2& column,
                                                            DependencyPriority priority,
                                                            JobServiceClass serviceClass) const
{
    bool ready = true;

    std::array<glm::ivec2, 4> pageKeys{};
    const std::size_t pageCount = collectChunkWorldgenPageKeys({column.x, 0, column.y}, pageKeys);
    for (std::size_t i = 0; i < pageCount; ++i)
    {
        if (tryGetReadyWorldgenPage(pageKeys[i]))
        {
            continue;
        }

        ready = false;
        (void)requestWorldgenPageDependency(pageKeys[i], priority, true, true, serviceClass);
    }

    const std::vector<StructureRegionKey> regionKeys = collectStructureRegionKeysForColumn(column);
    for (const StructureRegionKey& regionKey : regionKeys)
    {
        if (tryGetReadyRegion(regionKey))
        {
            continue;
        }

        ready = false;
        (void)requestStructureRegionDependency(regionKey, priority, serviceClass);
    }

    return ready;
}

bool ChunkManager::Impl::requestExactGpuPageWindowDependencies(const glm::ivec3& chunkCoord,
                                                               DependencyPriority priority,
                                                               JobServiceClass serviceClass) const
{
    bool ready = true;
    const ExactGpuWorldgenPageWindow pageWindow = exactGpuWorldgenPageWindowForChunk(chunkCoord);
    for (const glm::ivec2& pageKey : pageWindow.pageKeys)
    {
        if (tryGetReadyWorldgenPage(pageKey))
        {
            continue;
        }

        ready = false;
        (void)requestWorldgenPageDependency(pageKey, priority, false, false, serviceClass);
    }

    return ready;
}

bool ChunkManager::Impl::requestSpawnFootprintDependencies(int worldX,
                                                           int worldZ,
                                                           DependencyPriority priority,
                                                           JobServiceClass serviceClass) const
{
    bool ready = true;
    const auto pageSupportReady = [this](const glm::ivec2& pageKey) -> bool
    {
        std::lock_guard<std::mutex> lock(worldgenPageMutex_);
        auto it = worldgenPageEntries_.find(pageKey);
        return it != worldgenPageEntries_.end() &&
               worldgenPageSpawnSupportSatisfiedLocked(it->second);
    };
    const glm::ivec2 minPageKey = worldgenPageKeyForWorld(worldX - kSafeSpawnSampleFootprintRadiusBlocks,
                                                          worldZ - kSafeSpawnSampleFootprintRadiusBlocks);
    const glm::ivec2 maxPageKey = worldgenPageKeyForWorld(worldX + kSafeSpawnSampleFootprintRadiusBlocks,
                                                          worldZ + kSafeSpawnSampleFootprintRadiusBlocks);
    for (int pageZ = minPageKey.y; pageZ <= maxPageKey.y; ++pageZ)
    {
        for (int pageX = minPageKey.x; pageX <= maxPageKey.x; ++pageX)
        {
            const glm::ivec2 pageKey{pageX, pageZ};
            if (pageSupportReady(pageKey))
            {
                continue;
            }

            ready = false;
            (void)requestWorldgenPageDependency(pageKey, priority, false, false, serviceClass);
        }
    }

    return ready;
}

bool ChunkManager::Impl::spawnFootprintReady(int worldX, int worldZ) const
{
    const glm::ivec2 minPageKey = worldgenPageKeyForWorld(worldX - kSafeSpawnSampleFootprintRadiusBlocks,
                                                          worldZ - kSafeSpawnSampleFootprintRadiusBlocks);
    const glm::ivec2 maxPageKey = worldgenPageKeyForWorld(worldX + kSafeSpawnSampleFootprintRadiusBlocks,
                                                          worldZ + kSafeSpawnSampleFootprintRadiusBlocks);
    std::lock_guard<std::mutex> lock(worldgenPageMutex_);
    for (int pageZ = minPageKey.y; pageZ <= maxPageKey.y; ++pageZ)
    {
        for (int pageX = minPageKey.x; pageX <= maxPageKey.x; ++pageX)
        {
            const glm::ivec2 pageKey{pageX, pageZ};
            auto it = worldgenPageEntries_.find(pageKey);
            if (it == worldgenPageEntries_.end())
            {
                return false;
            }

            const WorldgenPageDependencyEntry& entry = it->second;
            if (!worldgenPageSpawnSupportSatisfiedLocked(entry))
            {
                return false;
            }
        }
    }

    return true;
}

bool ChunkManager::Impl::worldgenPageSpawnSupportSatisfiedLocked(
    const WorldgenPageDependencyEntry& entry) noexcept
{
    // Safe-spawn resolution samples directly from ready WorldgenPage data, so it does not need
    // derived column-height support bits or warmed structure-region support.
    return entry.state == WorldgenPageState::Ready &&
           entry.page;
}

void ChunkManager::Impl::pinWorldgenWindow(const glm::ivec3& center, int horizontalRadius)
{
    int minWorldX = 0;
    int maxWorldX = 0;
    int minWorldZ = 0;
    int maxWorldZ = 0;
    exactSupportWorldgenWindowBounds(center, horizontalRadius, minWorldX, maxWorldX, minWorldZ, maxWorldZ);

    std::unordered_set<glm::ivec2, ColumnHasher> desiredKeys{};
    const glm::ivec2 minKey = worldgenPageKeyForWorld(minWorldX, minWorldZ);
    const glm::ivec2 maxKey = worldgenPageKeyForWorld(maxWorldX, maxWorldZ);
    desiredKeys.reserve(static_cast<std::size_t>(std::max(maxKey.x - minKey.x + 1, 0)) *
                        static_cast<std::size_t>(std::max(maxKey.y - minKey.y + 1, 0)));
    for (int pageZ = minKey.y; pageZ <= maxKey.y; ++pageZ)
    {
        for (int pageX = minKey.x; pageX <= maxKey.x; ++pageX)
        {
            desiredKeys.insert({pageX, pageZ});
        }
    }

    {
        std::lock_guard<std::mutex> lock(worldgenPageMutex_);
        pinnedWorldgenPageKeys_ = std::move(desiredKeys);
    }
    trimWorldgenPages();
}

void ChunkManager::Impl::trimWorldgenPages()
{
    std::lock_guard<std::mutex> lock(worldgenPageMutex_);
    const std::size_t keepSlack = 32;
    std::size_t readyPageCount = 0;
    for (const auto& [key, entry] : worldgenPageEntries_)
    {
        (void)key;
        if (entry.state == WorldgenPageState::Ready && entry.page)
        {
            ++readyPageCount;
        }
    }
    if (readyPageCount <= pinnedWorldgenPageKeys_.size() + keepSlack)
    {
        return;
    }

    for (auto it = worldgenPageEntries_.begin(); it != worldgenPageEntries_.end();)
    {
        if (it->second.state != WorldgenPageState::Ready ||
            !it->second.page ||
            it->second.dependencyJobQueued ||
            it->second.dependencyJobInFlight ||
            pinnedWorldgenPageKeys_.contains(it->first))
        {
            ++it;
            continue;
        }

        it->second.state = WorldgenPageState::Unrequested;
        it->second.page.reset();
        it->second.dependencyJobQueued = false;
        it->second.dependencyJobInFlight = false;
        it->second.lastError = {};
        ++it;
        if (--readyPageCount <= pinnedWorldgenPageKeys_.size() + keepSlack)
        {
            break;
        }
    }
}

void ChunkManager::Impl::warmWorldgenPagesForChunk(const glm::ivec3& chunkCoord) const
{
    std::array<glm::ivec2, 4> pageKeys{};
    const std::size_t pageCount = collectChunkWorldgenPageKeys(chunkCoord, pageKeys);
    for (std::size_t i = 0; i < pageCount; ++i)
    {
        const std::shared_ptr<const WorldgenPage> page = tryGetReadyWorldgenPage(pageKeys[i]);
        assert(page && "Generate path reached an unready worldgen page");
    }
}

void ChunkManager::Impl::warmWorldgenPagesForColumn(const glm::ivec2& column) const
{
    const int worldX = column.x * kChunkSizeX + kChunkSizeX / 2;
    const int worldZ = column.y * kChunkSizeZ + kChunkSizeZ / 2;
    (void)requestWorldgenPageDependency(worldgenPageKeyForWorld(worldX, worldZ),
                                        DependencyPriority::Background,
                                        false,
                                        false,
                                        JobServiceClass::Refinement);
}

int ChunkManager::Impl::adjustedSurfaceYForColumn(const WorldgenColumnValue& column,
                                                  float neighborAverage) const noexcept
{
    int adjustedSurfaceY = column.surface.surfaceY;
    if (column.soilCreepStrength <= 0.0f || column.surface.soilCreepCoefficient <= 0.0f)
    {
        return adjustedSurfaceY;
    }

    const float strength = std::clamp(column.surface.soilCreepCoefficient * column.soilCreepStrength, 0.0f, 1.0f);
    float offset = (neighborAverage - static_cast<float>(adjustedSurfaceY)) * strength;
    if (column.soilCreepMaxStep > 0)
    {
        const float maxStep = static_cast<float>(column.soilCreepMaxStep);
        offset = std::clamp(offset, -maxStep, maxStep);
    }
    if (column.soilCreepMaxDepth > 0)
    {
        const float maxDepth = static_cast<float>(column.soilCreepMaxDepth);
        offset = std::clamp(offset, -maxDepth, maxDepth);
    }

    return static_cast<int>(std::round(static_cast<float>(adjustedSurfaceY) + offset));
}

ChunkManager::Impl::ExactGpuWorldgenPageWindow
ChunkManager::Impl::exactGpuWorldgenPageWindowForChunk(const glm::ivec3& chunkCoord) const noexcept
{
    const int minSampleWorldX = chunkCoord.x * kChunkSizeX - 1;
    const int minSampleWorldZ = chunkCoord.z * kChunkSizeZ - 1;
    const int maxSampleWorldX = chunkCoord.x * kChunkSizeX + kChunkSizeX;
    const int maxSampleWorldZ = chunkCoord.z * kChunkSizeZ + kChunkSizeZ;

    ExactGpuWorldgenPageWindow window{};
    window.minPageKey = worldgenPageKeyForWorld(minSampleWorldX, minSampleWorldZ);
    const glm::ivec2 maxPageKey = worldgenPageKeyForWorld(maxSampleWorldX, maxSampleWorldZ);
    window.pageKeys[0] = window.minPageKey;
    window.pageKeys[1] = {maxPageKey.x, window.minPageKey.y};
    window.pageKeys[2] = {window.minPageKey.x, maxPageKey.y};
    window.pageKeys[3] = maxPageKey;
    return window;
}

bool ChunkManager::Impl::computeChunkBaseTerrainState(
    const glm::ivec3& chunkCoord,
    std::uint32_t generationEpoch,
    bool initialReadyPriority,
    bool localInteractionPriority,
    int minWorldY,
    int maxWorldY,
    std::array<int, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)>& highestSolidWorlds,
    bool& outAnyBaseTerrain)
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    highestSolidWorlds.fill(ColumnManager::kNoHeight);
    outAnyBaseTerrain = false;

    constexpr int kSampleExtentX = kChunkSizeX + 2;
    constexpr int kSampleExtentZ = kChunkSizeZ + 2;
    auto sampleIndex = [](int sampleX, int sampleZ) noexcept
    {
        return static_cast<std::size_t>(sampleZ * kSampleExtentX + sampleX);
    };

    std::array<WorldgenColumnValue, static_cast<std::size_t>(kSampleExtentX * kSampleExtentZ)> worldgenColumns{};
    const int baseWorldX = chunkCoord.x * kChunkSizeX;
    const int baseWorldZ = chunkCoord.z * kChunkSizeZ;
    std::uint64_t worldgenPageMutexWaitMicros = 0u;
    std::uint64_t worldgenPagePendingWaitMicros = 0u;
    std::uint64_t worldgenPageBuildMicros = 0u;
    std::uint64_t worldgenPageBuildSurfaceMicros = 0u;
    std::uint64_t worldgenPageBuildPopulateMicros = 0u;
    std::uint32_t worldgenPageAccessCalls = 0u;
    std::uint32_t worldgenPageUniqueKeys = 0u;
    std::uint32_t worldgenPageColdBuilds = 0u;
    std::uint32_t worldgenPagePendingWaits = 0u;
    std::vector<glm::ivec2> uniqueWorldgenPageKeys{};
    std::vector<glm::ivec2> missingWorldgenPageKeys{};
    if (benchmarkEnabled)
    {
        uniqueWorldgenPageKeys.reserve(8);
    }
    missingWorldgenPageKeys.reserve(4);
    const auto recordWorldgenPageStats = [&]()
    {
        if (!benchmarkEnabled)
        {
            return;
        }

        benchmarkMetrics_.generateWorldgenPageMutexWaitStage.recordMicros(worldgenPageMutexWaitMicros);
        benchmarkMetrics_.generateWorldgenPagePendingWaitStage.recordMicros(worldgenPagePendingWaitMicros);
        benchmarkMetrics_.generateWorldgenPageBuildStage.recordMicros(worldgenPageBuildMicros);
        benchmarkMetrics_.generateWorldgenPageBuildSurfaceStage.recordMicros(worldgenPageBuildSurfaceMicros);
        benchmarkMetrics_.generateWorldgenPageBuildPopulateStage.recordMicros(worldgenPageBuildPopulateMicros);
        benchmarkMetrics_.generateWorldgenPageAccessCalls.record(worldgenPageAccessCalls);
        benchmarkMetrics_.generateWorldgenPageUniqueKeys.record(worldgenPageUniqueKeys);
        benchmarkMetrics_.generateWorldgenPageColdBuildCount.record(worldgenPageColdBuilds);
        benchmarkMetrics_.generateWorldgenPagePendingWaitCount.record(worldgenPagePendingWaits);
    };

    for (int sampleX = -1; sampleX <= kChunkSizeX; ++sampleX)
    {
        for (int sampleZ = -1; sampleZ <= kChunkSizeZ; ++sampleZ)
        {
            const int sampleWorldX = baseWorldX + sampleX;
            const int sampleWorldZ = baseWorldZ + sampleZ;
            const glm::ivec2 pageKey = worldgenPageKeyForWorld(sampleWorldX, sampleWorldZ);
            if (benchmarkEnabled)
            {
                ++worldgenPageAccessCalls;
                const auto uniqueIt = std::find(uniqueWorldgenPageKeys.begin(),
                                                uniqueWorldgenPageKeys.end(),
                                                pageKey);
                if (uniqueIt == uniqueWorldgenPageKeys.end())
                {
                    uniqueWorldgenPageKeys.push_back(pageKey);
                    ++worldgenPageUniqueKeys;
                }
            }
            const std::shared_ptr<const WorldgenPage> page = tryGetReadyWorldgenPage(pageKey);
            if (!page)
            {
                if (std::find(missingWorldgenPageKeys.begin(), missingWorldgenPageKeys.end(), pageKey) ==
                    missingWorldgenPageKeys.end())
                {
                    missingWorldgenPageKeys.push_back(pageKey);
                }
                continue;
            }

            const int localPageX = sampleWorldX - page->baseWorld.x;
            const int localPageZ = sampleWorldZ - page->baseWorld.y;
            worldgenColumns[sampleIndex(sampleX + 1, sampleZ + 1)] = page->column(localPageX, localPageZ);
        }
    }

    if (!missingWorldgenPageKeys.empty())
    {
        const DependencyPriority dependencyPriority =
            (initialReadyPriority || localInteractionPriority) ? DependencyPriority::Critical
                                                               : DependencyPriority::Visible;
        const JobServiceClass serviceClass =
            classifyJobServiceClass(initialReadyPriority, localInteractionPriority, false);
        std::vector<glm::ivec2> deferredWorldgenPageKeys;
        deferredWorldgenPageKeys.reserve(missingWorldgenPageKeys.size());
        for (const glm::ivec2& pageKey : missingWorldgenPageKeys)
        {
            requestWorldgenPageDependency(pageKey, dependencyPriority, true, true, serviceClass);
            if (!tryGetReadyWorldgenPage(pageKey) && worldgenPageDependencyHasOutstandingWork(pageKey))
            {
                deferredWorldgenPageKeys.push_back(pageKey);
            }
        }

        if (deferredWorldgenPageKeys.empty())
        {
            if (exactDependencyStallDebugLoggingEnabled())
            {
                std::ostringstream stream;
                stream << "exact_dep_retryable chunk=(" << chunkCoord.x << "," << chunkCoord.y << "," << chunkCoord.z
                       << ") stage=base_terrain reason=no_outstanding_worldgen_page_work"
                       << " missing_pages=" << missingWorldgenPageKeys.size();
                for (const glm::ivec2& pageKey : missingWorldgenPageKeys)
                {
                    stream << " page(" << pageKey.x << "," << pageKey.y << ")_outstanding="
                           << (worldgenPageDependencyHasOutstandingWork(pageKey) ? 1 : 0);
                }
                exactDependencyStallDebugLog(stream.str());
            }
            clearDeferredChunkDependencies(chunkCoord);
            clearStreamingChunkLifecycleState(chunkCoord);
            abandonChunkGenerationPlaceholder(chunkCoord, generationEpoch);
            recordWorldgenPageStats();
            return false;
        }

        registerDeferredChunkDependencies(chunkCoord,
                                          generationEpoch,
                                          initialReadyPriority,
                                          localInteractionPriority,
                                          deferredWorldgenPageKeys);
        setStreamingChunkLifecycleState(chunkCoord, FrontierDemandState::WaitingDependencies);
        if (benchmarkEnabled)
        {
            benchmarkMetrics_.chunkDependencyWorldgenDeferrals.record(
                static_cast<std::uint64_t>(deferredWorldgenPageKeys.size()));
        }
        recordWorldgenPageStats();
        return false;
    }
    recordWorldgenPageStats();

    auto computeNeighborAverage = [&](int localX, int localZ) noexcept
    {
        float sum = 0.0f;
        int count = 0;
        for (int dx = -1; dx <= 1; ++dx)
        {
            for (int dz = -1; dz <= 1; ++dz)
            {
                if (dx == 0 && dz == 0)
                {
                    continue;
                }

                sum += static_cast<float>(
                    worldgenColumns[sampleIndex(localX + dx + 1, localZ + dz + 1)].surface.surfaceY);
                ++count;
            }
        }

        return count > 0 ? sum / static_cast<float>(count) : 0.0f;
    };

    for (int localX = 0; localX < kChunkSizeX; ++localX)
    {
        for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
        {
            const WorldgenColumnValue& worldgenColumn = worldgenColumns[sampleIndex(localX + 1, localZ + 1)];
            if (worldgenColumn.surface.dominantBiome == nullptr)
            {
                continue;
            }

            int adjustedSurfaceY = adjustedSurfaceYForColumn(worldgenColumn, computeNeighborAverage(localX, localZ));
            adjustedSurfaceY = std::clamp(adjustedSurfaceY,
                                          std::min(worldgenColumn.surface.surfaceY, minWorldY),
                                          std::max(worldgenColumn.surface.surfaceY, maxWorldY));

            const std::size_t columnIdx = columnIndex(localX, localZ);
            if (adjustedSurfaceY >= minWorldY)
            {
                highestSolidWorlds[columnIdx] = std::min(adjustedSurfaceY, maxWorldY);
                outAnyBaseTerrain = true;
            }

            if (worldgenColumn.waterFillEnabled && adjustedSurfaceY < globalSeaLevel_)
            {
                int waterBottomWorld = std::max(adjustedSurfaceY + 1, minWorldY);
                const int waterTopWorld = std::min(globalSeaLevel_, maxWorldY);
                if (worldgenColumn.waterFillMaxDepth > 0)
                {
                    waterBottomWorld = std::max(
                        waterBottomWorld,
                        waterTopWorld - static_cast<int>(worldgenColumn.waterFillMaxDepth) + 1);
                }
                if (waterBottomWorld <= waterTopWorld)
                {
                    outAnyBaseTerrain = true;
                }
            }
        }
    }

    return true;
}

ChunkManager::Impl::ColumnSlabOccupancy ChunkManager::Impl::buildColumnSlabOccupancy(const glm::ivec2& column) const
{
    const DependencyPriority dependencyPriority = DependencyPriority::Visible;
    const JobServiceClass serviceClass = JobServiceClass::Standard;
    if (!requestColumnOccupancyDependencies(column, dependencyPriority, serviceClass))
    {
        return conservativeIncompleteColumnSlabOccupancy(column);
    }

    ColumnSlabOccupancy occupancy{};
    auto noteChunkInterval = [&](int minChunkY, int maxChunkY)
    {
        occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, maxChunkY);
        addColumnChunkInterval(occupancy.terrainIntervals, minChunkY, maxChunkY);
    };

    const int baseWorldX = column.x * kChunkSizeX;
    const int baseWorldZ = column.y * kChunkSizeZ;
    constexpr int kSampleExtentX = kChunkSizeX + 2;
    constexpr int kSampleExtentZ = kChunkSizeZ + 2;

    std::array<glm::ivec2, 4> pageKeys{};
    const std::size_t pageCount = collectChunkWorldgenPageKeys({column.x, 0, column.y}, pageKeys);
    std::array<std::shared_ptr<const WorldgenPage>, 4> readyPages{};
    for (std::size_t i = 0; i < pageCount; ++i)
    {
        readyPages[i] = tryGetReadyWorldgenPage(pageKeys[i]);
        if (!readyPages[i])
        {
            return conservativeIncompleteColumnSlabOccupancy(column);
        }
    }

    const auto findReadyPage = [&](const glm::ivec2& pageKey) -> const std::shared_ptr<const WorldgenPage>&
    {
        for (std::size_t i = 0; i < pageCount; ++i)
        {
            if (pageKeys[i] == pageKey)
            {
                return readyPages[i];
            }
        }

        throw std::runtime_error("Column occupancy requires a ready worldgen page neighborhood");
    };

    std::array<WorldgenColumnValue, static_cast<std::size_t>(kSampleExtentX * kSampleExtentZ)> worldgenColumns{};
    auto sampleIndex = [](int sampleX, int sampleZ) noexcept {
        return static_cast<std::size_t>(sampleZ * kSampleExtentX + sampleX);
    };

    if (surfaceMap_ && climateMap_)
    {
        for (int sampleX = -1; sampleX <= kChunkSizeX; ++sampleX)
        {
            for (int sampleZ = -1; sampleZ <= kChunkSizeZ; ++sampleZ)
            {
                const int sampleWorldX = baseWorldX + sampleX;
                const int sampleWorldZ = baseWorldZ + sampleZ;
                const std::shared_ptr<const WorldgenPage>& page =
                    findReadyPage(worldgenPageKeyForWorld(sampleWorldX, sampleWorldZ));
                const int localPageX = sampleWorldX - page->baseWorld.x;
                const int localPageZ = sampleWorldZ - page->baseWorld.y;
                worldgenColumns[sampleIndex(sampleX + 1, sampleZ + 1)] = page->column(localPageX, localPageZ);
            }
        }

        auto computeNeighborAverage = [&](int localX, int localZ) noexcept {
            float sum = 0.0f;
            int count = 0;
            for (int dx = -1; dx <= 1; ++dx)
            {
                for (int dz = -1; dz <= 1; ++dz)
                {
                    if (dx == 0 && dz == 0)
                    {
                        continue;
                    }
                    sum += static_cast<float>(
                        worldgenColumns[sampleIndex(localX + dx + 1, localZ + dz + 1)].surface.surfaceY);
                    ++count;
                }
            }
            return count > 0 ? sum / static_cast<float>(count) : 0.0f;
        };

        int highestTerrainWorld = std::numeric_limits<int>::min();
        int lowestTerrainWorld = std::numeric_limits<int>::max();
        int minWaterBottomWorld = std::numeric_limits<int>::max();
        int maxWaterTopWorld = std::numeric_limits<int>::min();

        for (int localX = 0; localX < kChunkSizeX; ++localX)
        {
            for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
            {
                const WorldgenColumnValue& worldgenColumn = worldgenColumns[sampleIndex(localX + 1, localZ + 1)];
                const BiomeDefinition* biome = worldgenColumn.surface.dominantBiome;
                if (biome == nullptr)
                {
                    continue;
                }

                const int adjustedSurfaceY = adjustedSurfaceYForColumn(worldgenColumn, computeNeighborAverage(localX, localZ));
                highestTerrainWorld = std::max(highestTerrainWorld, adjustedSurfaceY);
                lowestTerrainWorld = std::min(lowestTerrainWorld, adjustedSurfaceY);

                if (!worldgenColumn.waterFillEnabled || adjustedSurfaceY >= globalSeaLevel_)
                {
                    continue;
                }

                int waterBottomWorld = adjustedSurfaceY + 1;
                int waterTopWorld = globalSeaLevel_;
                if (worldgenColumn.waterFillMaxDepth > 0)
                {
                    waterBottomWorld = std::max(waterBottomWorld,
                                                waterTopWorld - static_cast<int>(worldgenColumn.waterFillMaxDepth) + 1);
                }
                minWaterBottomWorld = std::min(minWaterBottomWorld, waterBottomWorld);
                maxWaterTopWorld = std::max(maxWaterTopWorld, waterTopWorld);
            }
        }

        if (highestTerrainWorld >= 0)
        {
            const int highestChunkY = floorDiv(highestTerrainWorld, kChunkSizeY);
            noteChunkInterval(0, highestChunkY);
            int shellFloorChunk = surfaceShellFloorChunkForHeight(column, highestTerrainWorld);
            if (lowestTerrainWorld != std::numeric_limits<int>::max() &&
                highestTerrainWorld - lowestTerrainWorld >= kExactSurfaceShellInternalReliefThresholdBlocks)
            {
                const int internalReliefFloorChunk =
                    std::max(0,
                             floorDiv(std::max(0, lowestTerrainWorld), kChunkSizeY) -
                                 kExactSurfaceShellBelowSlackChunks);
                shellFloorChunk = std::min(shellFloorChunk, internalReliefFloorChunk);
            }
            addColumnChunkInterval(occupancy.surfaceShellIntervals,
                                   std::max(0, shellFloorChunk),
                                   std::max(highestChunkY, highestChunkY + kExactSurfaceShellAirAboveChunks));
        }
        if (maxWaterTopWorld >= 0 && minWaterBottomWorld <= maxWaterTopWorld)
        {
            const int minChunkY = floorDiv(std::max(0, minWaterBottomWorld), kChunkSizeY);
            const int maxChunkY = floorDiv(std::max(0, maxWaterTopWorld), kChunkSizeY);
            occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, maxChunkY);
            addColumnChunkInterval(occupancy.waterIntervals, minChunkY, maxChunkY);
        }
    }

    bool allStructureRegionsReady = true;
    const StructureChunkColumnSpan structureSpan =
        structureRegistry_.queryChunkColumnSpanReady(column, &allStructureRegionsReady);
    if (!allStructureRegionsReady)
    {
        return conservativeIncompleteColumnSlabOccupancy(column);
    }
    if (structureSpan.valid())
    {
        occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, structureSpan.maxChunkY);
        addColumnChunkInterval(occupancy.structureIntervals, structureSpan.minChunkY, structureSpan.maxChunkY);
    }
    occupancy.supportComplete = allStructureRegionsReady;

    {
        std::lock_guard<std::mutex> lock(pendingStructureMutex_);
        for (const auto& [coord, edits] : pendingStructureEdits_)
        {
            if (coord.x != column.x || coord.z != column.y)
            {
                continue;
            }

            const bool hasSolidEdit = std::any_of(edits.begin(),
                                                  edits.end(),
                                                  [](const PendingStructureEdit& edit) {
                                                      return edit.block != BlockId::Air;
                                                  });
            if (hasSolidEdit)
            {
                occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, coord.y);
                addColumnChunkInterval(occupancy.editIntervals, coord.y, coord.y);
            }
        }
    }

    for (const auto& [coord, count] : worldEditStore_.snapshotEditedChunks())
    {
        (void)count;
        if (coord.x != column.x || coord.z != column.y)
        {
            continue;
        }

        if (worldEditStore_.chunkHasSolidEdits(coord))
        {
            occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, coord.y);
            addColumnChunkInterval(occupancy.editIntervals, coord.y, coord.y);
        }
    }

    mergeColumnChunkIntervals(occupancy.occupiedIntervals, occupancy.terrainIntervals);
    mergeColumnChunkIntervals(occupancy.occupiedIntervals, occupancy.waterIntervals);
    mergeColumnChunkIntervals(occupancy.occupiedIntervals, occupancy.structureIntervals);
    mergeColumnChunkIntervals(occupancy.occupiedIntervals, occupancy.editIntervals);
    return occupancy;
}

ChunkManager::Impl::ColumnSlabOccupancy
ChunkManager::Impl::conservativeIncompleteColumnSlabOccupancy(const glm::ivec2& column) const
{
    ColumnSlabOccupancy occupancy{};
    occupancy.supportComplete = false;

    int highestKnownWorldY = columnManager_.highestSolidBlockInChunkColumn(column);
    int predictedHeight = ColumnManager::kNoHeight;
    if (tryGetPredictedColumnHeight(column, predictedHeight))
    {
        highestKnownWorldY = std::max(highestKnownWorldY, predictedHeight);
    }

    int minEditChunkY = std::numeric_limits<int>::max();
    int maxEditChunkY = std::numeric_limits<int>::min();
    const auto noteEditChunk = [&](int chunkY)
    {
        minEditChunkY = std::min(minEditChunkY, chunkY);
        maxEditChunkY = std::max(maxEditChunkY, chunkY);
    };

    {
        std::lock_guard<std::mutex> lock(pendingStructureMutex_);
        for (const auto& [coord, edits] : pendingStructureEdits_)
        {
            if (coord.x != column.x || coord.z != column.y)
            {
                continue;
            }

            const bool hasSolidEdit = std::any_of(edits.begin(),
                                                  edits.end(),
                                                  [](const PendingStructureEdit& edit)
                                                  {
                                                      return edit.block != BlockId::Air;
                                                  });
            if (hasSolidEdit)
            {
                noteEditChunk(coord.y);
            }
        }
    }

    for (const auto& [coord, count] : worldEditStore_.snapshotEditedChunks())
    {
        (void)count;
        if (coord.x != column.x || coord.z != column.y)
        {
            continue;
        }

        if (worldEditStore_.chunkHasSolidEdits(coord))
        {
            noteEditChunk(coord.y);
        }
    }

    if (highestKnownWorldY != ColumnManager::kNoHeight)
    {
        const int highestChunkY = floorDiv(std::max(0, highestKnownWorldY), kChunkSizeY);
        const int shellFloorChunk = surfaceShellFloorChunkForHeight(column, highestKnownWorldY);
        const int maybeTopChunkY =
            floorDiv(std::max(0, highestKnownWorldY + kMaxStructureVerticalReachBlocks), kChunkSizeY);
        occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, maybeTopChunkY);
        addColumnChunkInterval(occupancy.maybeIntervals,
                               std::max(0, shellFloorChunk),
                               std::max(highestChunkY, maybeTopChunkY));
    }
    else
    {
        const int maybeTopChunkY = floorDiv(kMaxStructureVerticalReachBlocks, kChunkSizeY);
        occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, maybeTopChunkY);
        addColumnChunkInterval(occupancy.maybeIntervals, 0, maybeTopChunkY);
    }

    if (minEditChunkY <= maxEditChunkY)
    {
        occupancy.highestOccupiedChunkY = std::max(occupancy.highestOccupiedChunkY, maxEditChunkY);
        addColumnChunkInterval(occupancy.maybeIntervals, std::max(0, minEditChunkY), std::max(0, maxEditChunkY));
    }

    return occupancy;
}

ChunkManager::Impl::ColumnSlabOccupancy ChunkManager::Impl::cachedColumnSlabOccupancy(const glm::ivec2& column) const
{
    {
        std::lock_guard<std::mutex> lock(columnSlabOccupancyMutex_);
        auto it = columnSlabOccupancyCache_.find(column);
        if (it != columnSlabOccupancyCache_.end())
        {
            return it->second;
        }
    }

    ColumnSlabOccupancy built = buildColumnSlabOccupancy(column);
    if (!built.supportComplete)
    {
        refreshWorldgenPageOccupancySupportForColumn(column, false);
        return built;
    }

    {
        std::lock_guard<std::mutex> lock(columnSlabOccupancyMutex_);
        auto [it, inserted] = columnSlabOccupancyCache_.emplace(column, built);
        if (!inserted)
        {
            return it->second;
        }
    }
    refreshWorldgenPageOccupancySupportForColumn(column, true);
    return built;
}

bool ChunkManager::Impl::tryGetCachedColumnSlabOccupancy(const glm::ivec2& column,
                                                         ColumnSlabOccupancy& out) const
{
    std::lock_guard<std::mutex> lock(columnSlabOccupancyMutex_);
    auto it = columnSlabOccupancyCache_.find(column);
    if (it == columnSlabOccupancyCache_.end())
    {
        return false;
    }

    out = it->second;
    return true;
}

ChunkManager::Impl::ColumnSlabOccupancyState
ChunkManager::Impl::classifyColumnSlab(const ColumnSlabOccupancy& occupancy, int chunkY) noexcept
{
    if (chunkYWithinIntervals(chunkY, occupancy.occupiedIntervals))
    {
        return ColumnSlabOccupancyState::DefinitelyOccupied;
    }
    if (chunkYWithinIntervals(chunkY, occupancy.maybeIntervals))
    {
        return ColumnSlabOccupancyState::MaybeOccupied;
    }
    return ColumnSlabOccupancyState::DefinitelyEmpty;
}

void ChunkManager::Impl::invalidateColumnSlabOccupancy(const glm::ivec2& column) const
{
    {
        std::lock_guard<std::mutex> lock(columnSlabOccupancyMutex_);
        columnSlabOccupancyCache_.erase(column);
    }
    markPlanDirtyColumn(column);
    refreshWorldgenPageOccupancySupportForColumn(column, false);
}

void ChunkManager::Impl::invalidateAllColumnSlabOccupancy() const
{
    {
        std::lock_guard<std::mutex> lock(columnSlabOccupancyMutex_);
        columnSlabOccupancyCache_.clear();
    }
    markActiveWindowReplanNeeded("all_column_occupancy_dirty");
}

void ChunkManager::Impl::updateMovementEnvelopeState(const glm::ivec3& center,
                                                     const glm::ivec3& previousCenter,
                                                     double frameSeconds) noexcept
{
    const bool havePreviousCenter = updateFrameIndex_ > 1;
    const glm::ivec2 movementDelta = havePreviousCenter
        ? glm::ivec2{center.x - previousCenter.x, center.z - previousCenter.z}
        : glm::ivec2{0, 0};
    lastHorizontalMovementShift_ = std::max(std::abs(movementDelta.x), std::abs(movementDelta.y));
    lastVerticalMovementShift_ = havePreviousCenter ? std::abs(center.y - previousCenter.y) : 0;

    const glm::vec2 cameraForwardXZ = normalizePriorityForwardXZ(lastCameraForward_);
    float cameraTurnDot = 1.0f;
    if (glm::dot(lastCameraForwardXZ_, lastCameraForwardXZ_) > kEpsilon &&
        glm::dot(cameraForwardXZ, cameraForwardXZ) > kEpsilon)
    {
        cameraTurnDot = glm::dot(lastCameraForwardXZ_, cameraForwardXZ);
    }
    movementEnvelopeTurnActive_ = cameraTurnDot <= kMovementEnvelopeTurnActivityDotThreshold;

    const bool movementOrTurnActive =
        lastHorizontalMovementShift_ > 0 ||
        lastVerticalMovementShift_ > 0 ||
        movementEnvelopeTurnActive_;
    if (movementOrTurnActive)
    {
        movementEnvelopeStationarySeconds_ = 0.0;
    }
    else
    {
        movementEnvelopeStationarySeconds_ += std::max(frameSeconds, 0.0);
    }
    movementEnvelopeIdleMode_ =
        !movementOrTurnActive &&
        movementEnvelopeStationarySeconds_ >= kMovementEnvelopeIdleDelaySeconds;

    if (glm::dot(cameraForwardXZ, cameraForwardXZ) > kEpsilon)
    {
        lastCameraForwardXZ_ = cameraForwardXZ;
    }

    glm::vec2 desiredForward = cameraForwardXZ;
    if (glm::dot(desiredForward, desiredForward) <= kEpsilon)
    {
        desiredForward = movementEnvelopeForwardXZ_;
    }

    glm::vec2 blendedForward = desiredForward;
    const glm::vec2 movementVector(static_cast<float>(movementDelta.x), static_cast<float>(movementDelta.y));
    if (glm::dot(movementVector, movementVector) > kEpsilon)
    {
        const glm::vec2 movementForward = glm::normalize(movementVector);
        const float movementWeight = lastHorizontalMovementShift_ >= 2 ? 0.80f : 0.65f;
        const float facingWeight = 1.0f - movementWeight;
        blendedForward = movementForward * movementWeight + desiredForward * facingWeight;
    }
    else if (movementEnvelopeTurnActive_)
    {
        blendedForward = movementEnvelopeForwardXZ_ * 0.35f + desiredForward * 0.65f;
    }
    else if (movementEnvelopeIdleMode_)
    {
        blendedForward = movementEnvelopeForwardXZ_;
    }
    else if (glm::dot(movementEnvelopeForwardXZ_, movementEnvelopeForwardXZ_) > kEpsilon)
    {
        blendedForward = movementEnvelopeForwardXZ_ * 0.65f + desiredForward * 0.35f;
    }

    if (glm::dot(blendedForward, blendedForward) > kEpsilon)
    {
        movementEnvelopeForwardXZ_ = glm::normalize(blendedForward);
    }
    else
    {
        movementEnvelopeForwardXZ_ = glm::vec2{0.0f, -1.0f};
    }
}

ChunkManager::Impl::MovementEnvelopeBucket ChunkManager::Impl::movementEnvelopeBucketForColumn(
    const glm::ivec2& column,
    const glm::ivec3& center,
    int horizontalRadius,
    int lookaheadChunks) const noexcept
{
    const int dx = column.x - center.x;
    const int dz = column.y - center.z;
    const int horizontalDistance = std::max(std::abs(dx), std::abs(dz));
    if (horizontalDistance == 0)
    {
        return MovementEnvelopeBucket::Core;
    }

    const int safeHorizontalRadius = std::max(horizontalRadius, 1);
    const int coreRadius = std::clamp(safeHorizontalRadius / 8,
                                      kMovementEnvelopeCoreRadiusMin,
                                      kMovementEnvelopeCoreRadiusMax);
    if (horizontalDistance <= coreRadius)
    {
        return MovementEnvelopeBucket::Core;
    }

    const bool idleRadialScheduling =
        movementEnvelopeIdleMode_ &&
        !movementEnvelopeTurnActive_ &&
        lastHorizontalMovementShift_ == 0 &&
        lastVerticalMovementShift_ == 0;
    if (idleRadialScheduling)
    {
        const int idleProtectedUpperBound = std::min(kMovementEnvelopeIdleProtectedRadiusMax, safeHorizontalRadius);
        const int idleProtectedRadius = std::clamp((safeHorizontalRadius * 2) / 3,
                                                   std::min(kMovementEnvelopeIdleProtectedRadiusMin,
                                                            idleProtectedUpperBound),
                                                   idleProtectedUpperBound);
        if (horizontalDistance <= idleProtectedRadius)
        {
            return MovementEnvelopeBucket::TurnReserve;
        }

        return MovementEnvelopeBucket::Background;
    }

    glm::vec2 forward = movementEnvelopeForwardXZ_;
    if (glm::dot(forward, forward) <= kEpsilon)
    {
        forward = normalizePriorityForwardXZ(lastCameraForward_);
    }
    if (glm::dot(forward, forward) <= kEpsilon)
    {
        forward = glm::vec2{0.0f, -1.0f};
    }

    const glm::vec2 side{-forward.y, forward.x};
    const glm::vec2 delta(static_cast<float>(dx), static_cast<float>(dz));
    const float forwardDistance = glm::dot(delta, forward) + static_cast<float>(lookaheadChunks);
    const float sideDistance = std::abs(glm::dot(delta, side));
    const int corridorHalfWidth =
        std::clamp(kMovementEnvelopeCorridorHalfWidthMin +
                       static_cast<int>(std::max(forwardDistance, 0.0f)) / kMovementEnvelopeCorridorWidthStep,
                   kMovementEnvelopeCorridorHalfWidthMin,
                   kMovementEnvelopeCorridorHalfWidthMax);
    const int corridorForwardReach = safeHorizontalRadius + std::clamp(safeHorizontalRadius / 4, 4, 12);
    if (forwardDistance >= -1.0f &&
        forwardDistance <= static_cast<float>(corridorForwardReach) &&
        sideDistance <= static_cast<float>(corridorHalfWidth))
    {
        return MovementEnvelopeBucket::Corridor;
    }

    const int turnReserveRadius = std::clamp(safeHorizontalRadius / 3,
                                             kMovementEnvelopeTurnReserveRadiusMin,
                                             kMovementEnvelopeTurnReserveRadiusMax);
    const int turnReserveHalfWidth = std::clamp(safeHorizontalRadius / 4,
                                                kMovementEnvelopeTurnReserveHalfWidthMin,
                                                kMovementEnvelopeTurnReserveHalfWidthMax);
    if (horizontalDistance <= turnReserveRadius &&
        forwardDistance >= -static_cast<float>(kMovementEnvelopeRearSlackChunks) &&
        sideDistance <= static_cast<float>(turnReserveHalfWidth))
    {
        return MovementEnvelopeBucket::TurnReserve;
    }

    return MovementEnvelopeBucket::Background;
}

ColumnChunkIntervals ChunkManager::Impl::columnIntervalsForHeight(const glm::ivec2& column,
                                                                  const glm::ivec2& cameraColumn,
                                                                  int cameraChunkY,
                                                                  int verticalRadius,
                                                                  int columnHeight) const
{
    ColumnChunkIntervals intervals{};
    const ColumnChunkIntervals playerBand =
        playerBandIntervalsForColumn(column, cameraColumn, cameraChunkY, verticalRadius);
    mergeColumnChunkIntervals(intervals, playerBand);

    ColumnSlabOccupancy occupancy{};
    if (tryGetCachedColumnSlabOccupancy(column, occupancy))
    {
        const bool keepFullOccupiedColumn = !playerBand.empty();
        if (keepFullOccupiedColumn)
        {
            mergeColumnChunkIntervals(intervals, occupancy.occupiedIntervals);
        }
        else
        {
            mergeColumnChunkIntervals(intervals, occupancy.surfaceShellIntervals);
            mergeColumnChunkIntervals(intervals, occupancy.waterIntervals);
            mergeColumnChunkIntervals(intervals, occupancy.structureIntervals);
            mergeColumnChunkIntervals(intervals, occupancy.editIntervals);
        }
        mergeColumnChunkIntervals(intervals, occupancy.maybeIntervals);
        return intervals;
    }

    if (columnHeight != ColumnManager::kNoHeight)
    {
        const int highestChunk = floorDiv(columnHeight, kChunkSizeY);
        const int shellFloorChunk = surfaceShellFloorChunkForHeight(column, columnHeight);
        addColumnChunkInterval(intervals,
                               std::max(0, shellFloorChunk),
                               std::max(highestChunk, highestChunk + kExactSurfaceShellAirAboveChunks));
    }

    return intervals;
}

std::pair<int, int> ChunkManager::Impl::columnSpanForHeight(const glm::ivec2& column,
                                                             const glm::ivec2& cameraColumn,
                                                             int cameraChunkY,
                                                             int verticalRadius,
                                                             int columnHeight) const
{
    const ColumnChunkIntervals intervals =
        columnIntervalsForHeight(column, cameraColumn, cameraChunkY, verticalRadius, columnHeight);
    return {intervals.minChunkY(), intervals.maxChunkY()};
}

void ChunkManager::Impl::removeDistantChunks(const glm::ivec3& center,
                                             int horizontalThreshold,
                                             int verticalRadius)
{
    struct EvictionCandidate
    {
        glm::ivec3 coord{0};
        int horizontalExcess{0};
        int verticalExcess{0};
    };

    const int evictionCenterY = updateEvictionCenterChunkY(center.y);
    const bool deferVerticalEvictions = evictionCenterY != center.y;
    const int evictionSlack =
        std::max(0, kVerticalStreamingConfig.columnSlackChunks) +
        std::max(0, kVerticalStreamingConfig.verticalEvictionExtraSlackChunks);
    EvictionQueryState query{
        center,
        evictionCenterY,
        horizontalThreshold,
        verticalRadius,
        evictionSlack,
        evictionBucketRectForQuery(center, horizontalThreshold),
        0};
    query.generation =
        (lastEvictionQueryStateValid_ && evictionQueryMatches(lastEvictionQueryState_, query))
            ? lastEvictionQueryState_.generation
            : nextEvictionQueryGeneration_++;
    updateEvictionDiscovery(query);
    drainPendingEvictionDiscovery(query);

    struct ColumnQueryCache
    {
        int columnHeight{ColumnManager::kNoHeight};
        ColumnChunkIntervals intervals{};
        bool valid{false};
    };

    std::unordered_map<glm::ivec2, ColumnQueryCache, ColumnHasher> columnCache;
    auto resolveColumnCache = [this, &query, &columnCache](const glm::ivec2& column) -> const ColumnQueryCache&
    {
        auto [cacheIt, inserted] = columnCache.try_emplace(column);
        if (!inserted)
        {
            return cacheIt->second;
        }

        std::uint64_t membershipVersion = 0;
        {
            std::lock_guard<std::mutex> lock(renderRegistryMutex_);
            const auto columnIt = residencyColumns_.find(column);
            if (columnIt == residencyColumns_.end())
            {
                return cacheIt->second;
            }

            membershipVersion = columnIt->second.membershipVersion;
            const auto evictionCacheIt = evictionColumnCache_.find(column);
            if (evictionCacheIt != evictionColumnCache_.end() &&
                evictionCacheIt->second.membershipVersion == membershipVersion &&
                evictionCacheIt->second.queryGeneration == query.generation)
            {
                cacheIt->second.columnHeight = evictionCacheIt->second.columnHeight;
                cacheIt->second.intervals = evictionCacheIt->second.intervals;
                cacheIt->second.valid = true;
                columnIt->second.lastEvictionQueryGeneration = query.generation;
                return cacheIt->second;
            }
        }

        const int worldX = column.x * kChunkSizeX + kChunkSizeX / 2;
        const int worldZ = column.y * kChunkSizeZ + kChunkSizeZ / 2;
        int columnHeight = ColumnManager::kNoHeight;
        if (!tryGetCachedColumnHeight(column, worldX, worldZ, columnHeight) && !stationaryExactFillModeActive_)
        {
            requestColumnHeightPrefetch(column, ColumnHeightPrefetchPriority::Normal);
        }

        cacheIt->second.columnHeight = columnHeight;
        cacheIt->second.intervals = columnIntervalsForHeight(column,
                                                             {query.centerChunk.x, query.centerChunk.z},
                                                             query.evictionCenterY,
                                                             query.verticalRadius,
                                                             columnHeight);
        cacheIt->second.valid = true;

        std::lock_guard<std::mutex> lock(renderRegistryMutex_);
        const auto columnIt = residencyColumns_.find(column);
        if (columnIt != residencyColumns_.end())
        {
            evictionColumnCache_[column] = EvictionColumnCacheEntry{
                columnHeight,
                cacheIt->second.intervals,
                membershipVersion,
                query.generation};
            columnIt->second.lastEvictionQueryGeneration = query.generation;
        }
        return cacheIt->second;
    };

    std::vector<EvictionCandidate> immediateRemovals;
    std::vector<EvictionCandidate> deferredVerticalRemovals;
    immediateRemovals.reserve(pendingEvictionCandidates_.size());
    deferredVerticalRemovals.reserve(pendingEvictionCandidates_.size());

    while (!pendingEvictionCandidates_.empty())
    {
        const glm::ivec3 coord = pendingEvictionCandidates_.front();
        pendingEvictionCandidates_.pop_front();
        pendingEvictionCandidateSet_.erase(coord);

        bool chunkPresent = false;
        {
            std::lock_guard<std::mutex> lock(chunksMutex);
            const auto it = chunks_.find(coord);
            chunkPresent = it != chunks_.end() && it->second != nullptr;
        }
        if (!chunkPresent)
        {
            continue;
        }

        if (coord.y < 0)
        {
            immediateRemovals.push_back(EvictionCandidate{coord, horizontalThreshold + 1, 0});
            continue;
        }

        const int horizontalDistance = std::max(std::abs(coord.x - center.x), std::abs(coord.z - center.z));
        if (horizontalDistance > horizontalThreshold)
        {
            immediateRemovals.push_back(EvictionCandidate{
                coord,
                horizontalDistance - horizontalThreshold,
                0});
            continue;
        }

        const ColumnQueryCache& cache = resolveColumnCache({coord.x, coord.z});
        if (!cache.valid)
        {
            continue;
        }

        const int verticalExcess = chunkYDistanceToIntervals(coord.y, cache.intervals, evictionSlack);
        if (verticalExcess <= 0)
        {
            continue;
        }

        if (deferVerticalEvictions)
        {
            deferredVerticalRemovals.push_back(EvictionCandidate{coord, 0, verticalExcess});
        }
        else
        {
            immediateRemovals.push_back(EvictionCandidate{coord, 0, verticalExcess});
        }
    }

    std::sort(deferredVerticalRemovals.begin(),
              deferredVerticalRemovals.end(),
              [](const EvictionCandidate& lhs, const EvictionCandidate& rhs)
              {
                  if (lhs.verticalExcess != rhs.verticalExcess)
                  {
                      return lhs.verticalExcess > rhs.verticalExcess;
                  }
                  if (lhs.coord.y != rhs.coord.y)
                  {
                      return lhs.coord.y > rhs.coord.y;
                  }
                  if (lhs.coord.x != rhs.coord.x)
                  {
                      return lhs.coord.x < rhs.coord.x;
                  }
                  return lhs.coord.z < rhs.coord.z;
              });

    const int evictionBudget = computeEvictionBudget(deferredVerticalRemovals.size());
    if (static_cast<int>(deferredVerticalRemovals.size()) > evictionBudget)
    {
        for (std::size_t i = static_cast<std::size_t>(evictionBudget); i < deferredVerticalRemovals.size(); ++i)
        {
            enqueuePendingEvictionCandidate(deferredVerticalRemovals[i].coord);
        }
        deferredVerticalRemovals.resize(static_cast<std::size_t>(evictionBudget));
    }

    std::vector<EvictionCandidate> toRemove;
    toRemove.reserve(immediateRemovals.size() + deferredVerticalRemovals.size());
    toRemove.insert(toRemove.end(), immediateRemovals.begin(), immediateRemovals.end());
    toRemove.insert(toRemove.end(), deferredVerticalRemovals.begin(), deferredVerticalRemovals.end());

    int evictedCount = 0;
    const auto shouldRetryCandidate = [this](const glm::ivec3& coord)
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        const auto it = chunks_.find(coord);
        return it != chunks_.end() && it->second != nullptr;
    };
    for (const EvictionCandidate& candidate : toRemove)
    {
        const glm::ivec3& coord = candidate.coord;
        if (!tryMarkChunkForRetire(coord))
        {
            if (shouldRetryCandidate(coord))
            {
                enqueuePendingEvictionCandidate(coord);
            }
            continue;
        }

        if (shouldTrackRecentEditChunk(coord))
        {
            const glm::ivec2 column{coord.x, coord.z};
            const ColumnQueryCache& cache = resolveColumnCache(column);
            const auto [minChunkY, maxChunkY] =
                columnSpanForHeight(column,
                                    {center.x, center.z},
                                    evictionCenterY,
                                    lastVerticalRadius_,
                                    cache.columnHeight);
            const int horizontalDistance =
                std::max(std::abs(coord.x - center.x), std::abs(coord.z - center.z));

            std::ostringstream stream;
            stream << "evict chunk=(" << coord.x << ", " << coord.y << ", " << coord.z
                   << ") hDist=" << horizontalDistance
                   << " hThreshold=" << horizontalThreshold
                   << " hExcess=" << candidate.horizontalExcess
                   << " vExcess=" << candidate.verticalExcess
                   << " evictCenterY=" << evictionCenterY
                   << " spanY=[" << minChunkY << ", " << maxChunkY << "]";
            appendRecentEditDebugEvent(stream.str());
        }

        ++evictedCount;
    }

    if (evictedCount > 0)
    {
        profilingCounters_.evictedChunks.fetch_add(evictedCount, std::memory_order_relaxed);
    }

    drainPendingChunkRetires();
}

ChunkManager::Impl::EnsureChunkAsyncResult ChunkManager::Impl::ensureChunkAsync(const glm::ivec3& coord,
                                                                                bool forceResident,
                                                                                bool localInteractionPriority)
{
    if (coord.y < 0)
    {
        return EnsureChunkAsyncResult::NoAction;
    }

    {
        std::lock_guard<std::mutex> lock(streamingFrontierMutex_);
        if (streamingFrontierDemands_.find(coord) == streamingFrontierDemands_.end())
        {
            return EnsureChunkAsyncResult::NoAction;
        }
    }
    (void)forceResident;

    try
    {
        constexpr bool kInitialReadyPriority = true;
        const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
        const JobQueueSnapshot queueSnapshot = benchmarkEnabled ? jobQueue_.snapshot() : JobQueueSnapshot{};
        const auto clampQueueCount = [](std::size_t value) -> std::uint16_t
        {
            return static_cast<std::uint16_t>(
                std::min<std::size_t>(value, static_cast<std::size_t>(std::numeric_limits<std::uint16_t>::max())));
        };
        {
            std::lock_guard<std::mutex> lock(chunksMutex);
            if (chunks_.find(coord) != chunks_.end())
            {
                return EnsureChunkAsyncResult::NoAction;
            }
        }

        std::shared_ptr<Chunk> chunk = acquireChunk(coord);
        chunk->state.store(ChunkState::Generating, std::memory_order_release);
        chunk->requestTimestampMicros.store(static_cast<long long>(steadyMicrosNow()), std::memory_order_release);
        chunk->initialReadyRecorded.store(false, std::memory_order_release);
        if (benchmarkEnabled)
        {
            for (std::size_t index = 0; index < kJobTypeCount; ++index)
            {
                chunk->requestQueuedByType[index] = clampQueueCount(queueSnapshot.queuedByType[index]);
                chunk->requestActiveByType[index] = clampQueueCount(queueSnapshot.activeByType[index]);
            }
            const std::size_t latencySensitiveOutstanding =
                queueSnapshot.queuedByService[jobServiceClassIndex(JobServiceClass::InitialVisible)] +
                queueSnapshot.activeByService[jobServiceClassIndex(JobServiceClass::InitialVisible)] +
                queueSnapshot.queuedByService[jobServiceClassIndex(JobServiceClass::LocalInteraction)] +
                queueSnapshot.activeByService[jobServiceClassIndex(JobServiceClass::LocalInteraction)];
            chunk->requestLatencySensitiveOutstanding = clampQueueCount(latencySensitiveOutstanding);
        }

        const std::uint32_t generationEpoch =
            chunk->generationEpoch.fetch_add(1, std::memory_order_acq_rel) + 1u;
        std::array<glm::ivec2, 4> pageKeys{};
        const std::size_t pageCount = collectChunkWorldgenPageKeys(coord, pageKeys);
        std::array<glm::ivec2, 4> missingPageKeys{};
        std::array<glm::ivec2, 4> deferredPageKeys{};
        std::size_t missingPageCount = 0;
        std::size_t deferredPageCount = 0;
        std::vector<StructureRegionKey> missingRegionKeys;
        std::vector<StructureRegionKey> deferredRegionKeys;
        for (std::size_t i = 0; i < pageCount; ++i)
        {
            if (tryGetReadyWorldgenPage(pageKeys[i]))
            {
                continue;
            }

            missingPageKeys[missingPageCount++] = pageKeys[i];
        }

        const DependencyPriority dependencyPriority =
            (kInitialReadyPriority || localInteractionPriority) ? DependencyPriority::Critical
                                                                : DependencyPriority::Visible;
        const JobServiceClass dependencyServiceClass =
            classifyJobServiceClass(kInitialReadyPriority, localInteractionPriority, false);
        const std::vector<StructureRegionKey> regionKeys = collectChunkRegionKeys(coord);
        missingRegionKeys.reserve(regionKeys.size());
        for (const StructureRegionKey& regionKey : regionKeys)
        {
            if (tryGetReadyRegion(regionKey))
            {
                continue;
            }

            missingRegionKeys.push_back(regionKey);
        }

        if (missingPageCount > 0 || !missingRegionKeys.empty())
        {
            for (std::size_t i = 0; i < missingPageCount; ++i)
            {
                requestWorldgenPageDependency(missingPageKeys[i],
                                              dependencyPriority,
                                              true,
                                              true,
                                              dependencyServiceClass);
            }
            for (const StructureRegionKey& regionKey : missingRegionKeys)
            {
                requestStructureRegionDependency(regionKey, dependencyPriority, dependencyServiceClass);
            }

            for (std::size_t i = 0; i < missingPageCount; ++i)
            {
                if (!tryGetReadyWorldgenPage(missingPageKeys[i]) &&
                    worldgenPageDependencyHasOutstandingWork(missingPageKeys[i]))
                {
                    deferredPageKeys[deferredPageCount++] = missingPageKeys[i];
                }
            }

            deferredRegionKeys.reserve(missingRegionKeys.size());
            for (const StructureRegionKey& regionKey : missingRegionKeys)
            {
                if (!tryGetReadyRegion(regionKey) && structureRegionDependencyHasOutstandingWork(regionKey))
                {
                    deferredRegionKeys.push_back(regionKey);
                }
            }

            if (deferredPageCount == 0 && deferredRegionKeys.empty())
            {
                if (exactDependencyStallDebugLoggingEnabled())
                {
                    std::ostringstream stream;
                    stream << "exact_dep_retryable chunk=(" << coord.x << "," << coord.y << "," << coord.z
                           << ") reason=no_outstanding_dependency_work"
                           << " missing_pages=" << missingPageCount
                           << " missing_regions=" << missingRegionKeys.size();
                    for (std::size_t i = 0; i < missingPageCount; ++i)
                    {
                        stream << " page(" << missingPageKeys[i].x << "," << missingPageKeys[i].y
                               << ")_outstanding="
                               << (worldgenPageDependencyHasOutstandingWork(missingPageKeys[i]) ? 1 : 0);
                    }
                    for (const StructureRegionKey& regionKey : missingRegionKeys)
                    {
                        stream << " region(" << regionKey.regionX << "," << regionKey.regionZ
                               << ")_outstanding="
                               << (structureRegionDependencyHasOutstandingWork(regionKey) ? 1 : 0);
                    }
                    exactDependencyStallDebugLog(stream.str());
                }
                return EnsureChunkAsyncResult::NoAction;
            }

            {
                std::lock_guard<std::mutex> lock(chunksMutex);
                if (chunks_.find(coord) != chunks_.end())
                {
                    return EnsureChunkAsyncResult::NoAction;
                }

                chunks_.emplace(coord, chunk);
                registerChunkRenderRegistryEntry(coord, chunk);
            }

            registerDeferredChunkDependencies(coord,
                                              generationEpoch,
                                              kInitialReadyPriority,
                                              localInteractionPriority,
                                              std::span<const glm::ivec2>(deferredPageKeys.data(), deferredPageCount),
                                              std::span<const StructureRegionKey>(deferredRegionKeys));
            setStreamingChunkLifecycleState(coord, FrontierDemandState::WaitingDependencies);
            if (benchmarkMetrics_.isEnabled())
            {
                if (deferredPageCount > 0)
                {
                    benchmarkMetrics_.chunkDependencyWorldgenDeferrals.record(deferredPageCount);
                }
                if (!deferredRegionKeys.empty())
                {
                    benchmarkMetrics_.chunkDependencyStructureDeferrals.record(
                        static_cast<std::uint64_t>(deferredRegionKeys.size()));
                }
            }
            return EnsureChunkAsyncResult::WaitingDependencies;
        }

        {
            std::lock_guard<std::mutex> lock(chunksMutex);
            if (chunks_.find(coord) != chunks_.end())
            {
                return EnsureChunkAsyncResult::NoAction;
            }

            chunks_.emplace(coord, chunk);
            registerChunkRenderRegistryEntry(coord, chunk);
        }

        clearDeferredChunkDependencies(coord);
        setStreamingChunkLifecycleState(coord, FrontierDemandState::QueuedGenerate);
        enqueueJob(chunk,
                   JobType::Generate,
                   coord,
                   generationEpoch,
                   kInitialReadyPriority,
                   classifyJobServiceClass(kInitialReadyPriority, localInteractionPriority, false));
        return EnsureChunkAsyncResult::EnqueuedGenerate;
    }
    catch (const std::exception& ex)
    {
        if (exactDependencyStallDebugLoggingEnabled())
        {
            std::ostringstream stream;
            stream << "exact_dep_exception chunk=(" << coord.x << "," << coord.y << "," << coord.z
                   << ") message=" << ex.what();
            exactDependencyStallDebugLog(stream.str());
        }
        std::cerr << "Error creating chunk at (" << coord.x << ", " << coord.y << ", " << coord.z
                  << "): " << ex.what() << std::endl;
        return EnsureChunkAsyncResult::NoAction;
    }
}

void ChunkManager::Impl::uploadDedicatedLocalCpuMeshes()
{
    constexpr std::size_t kDedicatedLocalUploadBudgetPerFrame = 12u;
    std::unordered_map<glm::ivec3, std::weak_ptr<Chunk>, ChunkHasher> pending;
    {
        std::lock_guard<std::mutex> lock(dedicatedLocalUploadMutex_);
        if (queuedDedicatedLocalUploads_.empty())
        {
            return;
        }

        pending.swap(queuedDedicatedLocalUploads_);
    }

    commitPendingChunkUploads();

    if (!uploadContext_.ready() || !uploadContext_.begin())
    {
        for (const auto& [coord, weakChunk] : pending)
        {
            if (auto chunk = weakChunk.lock())
            {
                queueChunkForDedicatedLocalUpload(chunk);
            }
            else
            {
                (void)coord;
            }
        }
        return;
    }

    const UINT64 uploadBatchId = nextUploadBatchId_++;
    bool uploadedAnything = false;
    std::vector<std::shared_ptr<Chunk>> stagedChunks;
    stagedChunks.reserve(std::min(pending.size(), kDedicatedLocalUploadBudgetPerFrame));
    std::size_t uploadsRemaining = kDedicatedLocalUploadBudgetPerFrame;

    for (const auto& [coord, weakChunk] : pending)
    {
        (void)coord;
        const std::shared_ptr<Chunk> chunk = weakChunk.lock();
        if (!chunk || !chunkUsesCpuNearRendering(*chunk))
        {
            continue;
        }

        if (!chunk->meshReady.load(std::memory_order_acquire) ||
            chunk->state.load(std::memory_order_acquire) != ChunkState::Ready)
        {
            queueChunkForDedicatedLocalUpload(chunk);
            continue;
        }

        {
            std::lock_guard<std::mutex> meshLock(chunk->meshMutex);
            if (chunk->pendingMesh.valid())
            {
                queueChunkForDedicatedLocalUpload(chunk);
                continue;
            }
        }

        if (uploadsRemaining == 0u)
        {
            queueChunkForDedicatedLocalUpload(chunk);
            continue;
        }

        if (!uploadChunkMesh(*chunk, uploadBatchId))
        {
            queueChunkForDedicatedLocalUpload(chunk);
            continue;
        }

        --uploadsRemaining;
        chunk->state.store(ChunkState::Uploaded, std::memory_order_release);
        chunk->meshReady.store(false, std::memory_order_release);
        stagedChunks.push_back(chunk);
        uploadedAnything = true;
        profilingCounters_.uploadedChunks.fetch_add(1, std::memory_order_relaxed);
    }

    uploadContext_.flush();
    if (!uploadedAnything)
    {
        return;
    }

    const UINT64 submittedFenceValue = uploadContext_.lastSubmittedFenceValue();
    sealPendingChunkUploadPages(uploadBatchId, submittedFenceValue);
    for (const std::shared_ptr<Chunk>& chunk : stagedChunks)
    {
        if (!chunk)
        {
            continue;
        }

        UINT64 chunkFenceValue = 0;
        std::lock_guard<std::mutex> meshLock(chunk->meshMutex);
        if (chunk->pendingMesh.valid() && chunk->pendingMesh.uploadFenceValue == 0)
        {
            chunk->pendingMesh.uploadFenceValue = submittedFenceValue;
            chunkFenceValue = submittedFenceValue;
        }
        if (chunkFenceValue != 0)
        {
            queueChunkForCommit(chunk, chunkFenceValue);
        }
    }
}

void ChunkManager::Impl::uploadLocalCpuMeshes()
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    uploadQueueAgeMsLastFrame_ = 0.0;
    uploadAttemptsLastFrame_ = 0;
    uploadQueueScanEntriesLastFrame_ = 0;
    uploadSkippedExpiredLastFrame_ = 0;
    uploadSkippedNotReadyLastFrame_ = 0;
    uploadSkippedPendingMeshLastFrame_ = 0;
    uploadColumnLimitedLastFrame_ = 0;
    uploadBudgetDeferredLastFrame_ = 0;
    uploadRetryFailuresLastFrame_ = 0;
    uploadScanLimitHitsLastFrame_ = 0;
    uploadBeginFailuresLastFrame_ = 0;
    uploadStalePendingMeshesLastFrame_ = 0;
    uploadQueuePickMsLastFrame_ = 0.0;
    uploadPrepareMsLastFrame_ = 0.0;
    uploadContextBeginMsLastFrame_ = 0.0;
    uploadFinalizeMsLastFrame_ = 0.0;
    commitCollectMsLastFrame_ = 0.0;
    commitChunkScanMsLastFrame_ = 0.0;
    commitMeshLockWaitMsLastFrame_ = 0.0;
    commitMeshLockedMsLastFrame_ = 0.0;
    commitMeshStateMsLastFrame_ = 0.0;
    commitPageStateMsLastFrame_ = 0.0;
    commitReleaseMsLastFrame_ = 0.0;

    const auto uploadPrepareStart = std::chrono::steady_clock::now();
    commitPendingChunkUploads();
    uploadPrepareMsLastFrame_ =
        std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - uploadPrepareStart).count();

    const std::size_t initialBudget = uploadBudgetBytesThisFrame_;
    std::size_t remainingBudget = initialBudget;
    bool uploadedAnything = false;
    int uploadedChunkCount = 0;
    std::unordered_map<glm::ivec2, int, ColumnHasher> uploadsPerColumn;
    std::size_t attempts = 0;
    const UINT64 uploadBatchId = nextUploadBatchId_++;
    std::vector<std::shared_ptr<Chunk>> stagedChunks;
    const int columnUploadLimit = std::max(1, uploadColumnLimitThisFrame_);
    const int chunkUploadLimit = std::max(1, uploadChunkLimitThisFrame_);
    const auto uploadStart = std::chrono::steady_clock::now();
    const auto uploadContextBeginStart = std::chrono::steady_clock::now();
    if (uploadContext_.ready() && !uploadContext_.begin())
    {
        uploadBeginFailuresLastFrame_ = 1;
        lastUploadBytesUsed_ = 0;
        lastUploadMsUsed_ = 0.0;
        pendingUploadsLastFrame_ = estimateUploadQueueSize();
        if (benchmarkEnabled)
        {
            benchmarkMetrics_.uploadBeginFailuresPerFrame.record(1);
            benchmarkMetrics_.uploadAttemptsPerFrame.record(0);
            benchmarkMetrics_.uploadChunksPerFrame.record(0);
            benchmarkMetrics_.uploadBytesPerFrame.record(0);
            benchmarkMetrics_.uploadQueueScanEntries.record(
                static_cast<std::uint64_t>(std::max(uploadQueueScanEntriesLastFrame_, 0)));
            benchmarkMetrics_.uploadExpiredEntriesPerFrame.record(
                static_cast<std::uint64_t>(std::max(uploadSkippedExpiredLastFrame_, 0)));
            benchmarkMetrics_.uploadSkippedNotReadyPerFrame.record(0);
            benchmarkMetrics_.uploadSkippedPendingMeshPerFrame.record(0);
            benchmarkMetrics_.uploadColumnLimitedPerFrame.record(0);
            benchmarkMetrics_.uploadBudgetDeferredPerFrame.record(0);
            benchmarkMetrics_.uploadRetryFailuresPerFrame.record(0);
            benchmarkMetrics_.uploadScanLimitHitsPerFrame.record(0);
            benchmarkMetrics_.uploadStalePendingMeshesPerFrame.record(
                static_cast<std::uint64_t>(std::max(uploadStalePendingMeshesLastFrame_, 0)));
        }
        return;
    }
    uploadContextBeginMsLastFrame_ =
        std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - uploadContextBeginStart).count();

    while ((remainingBudget > 0 || !uploadedAnything) && attempts < kUploadQueueScanLimit)
    {
        if (uploadedChunkCount >= chunkUploadLimit && uploadedAnything)
        {
            break;
        }

        ++attempts;
        uploadAttemptsLastFrame_ = static_cast<int>(attempts);
        std::shared_ptr<Chunk> chunk;
        if (benchmarkEnabled)
        {
            const auto uploadPickStart = SteadyClock::now();
            chunk = popNextChunkForUpload();
            uploadQueuePickMsLastFrame_ +=
                std::chrono::duration<double, std::milli>(SteadyClock::now() - uploadPickStart).count();
        }
        else
        {
            chunk = popNextChunkForUpload();
        }
        if (!chunk)
        {
            break;
        }

        if (!chunk->meshReady.load(std::memory_order_acquire) ||
            chunk->state.load(std::memory_order_acquire) != ChunkState::Ready)
        {
            ++uploadSkippedNotReadyLastFrame_;
            continue;
        }

        {
            std::lock_guard<std::mutex> meshLock(chunk->meshMutex);
            if (chunk->pendingMesh.valid())
            {
                ++uploadSkippedPendingMeshLastFrame_;
                requeueChunkForLocalCpuUpload(chunk, false);
                continue;
            }
        }

        const glm::ivec2 columnKey{chunk->coord.x, chunk->coord.z};
        int& columnUploads = uploadsPerColumn[columnKey];
        if (columnUploads >= columnUploadLimit)
        {
            ++uploadColumnLimitedLastFrame_;
            requeueChunkForLocalCpuUpload(chunk, false);
            profilingCounters_.throttledUploads.fetch_add(1, std::memory_order_relaxed);
            continue;
        }

        std::size_t vertexBytes = 0;
        std::size_t indexBytes = 0;
        {
            std::lock_guard<std::mutex> meshLock(chunk->meshMutex);
            vertexBytes = chunk->meshData.vertices.size() * sizeof(Vertex);
            indexBytes = chunk->meshData.indices.size() * sizeof(std::uint32_t);
        }
        const std::size_t totalBytes = vertexBytes + indexBytes;

        const bool allowOversizeUpload = !uploadedAnything && pendingUploadsLastFrame_ <= 2;
        if (totalBytes > remainingBudget && totalBytes > 0 && !allowOversizeUpload)
        {
            ++uploadBudgetDeferredLastFrame_;
            requeueChunkForLocalCpuUpload(chunk, false);
            profilingCounters_.deferredUploads.fetch_add(1, std::memory_order_relaxed);
            if (uploadedAnything)
            {
                break;
            }
            continue;
        }

        const auto uploadChunkStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
        if (!uploadChunkMesh(*chunk, uploadBatchId))
        {
            ++uploadRetryFailuresLastFrame_;
            requeueChunkForLocalCpuUpload(chunk, true);
            if (uploadedAnything)
            {
                break;
            }
            continue;
        }
        chunk->state.store(ChunkState::Uploaded, std::memory_order_release);
        chunk->meshReady.store(false, std::memory_order_release);
        uploadedAnything = true;
        ++uploadedChunkCount;
        ++columnUploads;
        stagedChunks.push_back(chunk);

        profilingCounters_.uploadedChunks.fetch_add(1, std::memory_order_relaxed);
        profilingCounters_.uploadedBytes.fetch_add(totalBytes, std::memory_order_relaxed);
        if (benchmarkEnabled)
        {
            const auto uploadChunkEnd = SteadyClock::now();
            const auto uploadMicros =
                std::chrono::duration_cast<std::chrono::microseconds>(uploadChunkEnd - uploadChunkStart).count();
            benchmarkMetrics_.uploadStage.recordMicros(static_cast<std::uint64_t>(uploadMicros));
            benchmarkMetrics_.uploadedChunks.fetch_add(1, std::memory_order_relaxed);
            benchmarkMetrics_.uploadedBytes.fetch_add(totalBytes, std::memory_order_relaxed);
        }

        if (totalBytes >= remainingBudget)
        {
            remainingBudget = 0;
        }
        else
        {
            remainingBudget -= totalBytes;
        }

        const double elapsedMs = std::chrono::duration<double, std::milli>(
            std::chrono::steady_clock::now() - uploadStart).count();
        if (elapsedMs >= uploadBudgetMsThisFrame_ && uploadedAnything)
        {
            break;
        }
    }

    if (attempts >= kUploadQueueScanLimit && estimateUploadQueueSize() > 0)
    {
        uploadScanLimitHitsLastFrame_ = 1;
    }

    const auto uploadFinalizeStart = std::chrono::steady_clock::now();
    uploadContext_.flush();
    if (uploadedAnything)
    {
        const UINT64 submittedFenceValue = uploadContext_.lastSubmittedFenceValue();
        sealPendingChunkUploadPages(uploadBatchId, submittedFenceValue);
        for (const std::shared_ptr<Chunk>& chunk : stagedChunks)
        {
            if (!chunk)
            {
                continue;
            }

            UINT64 chunkFenceValue = 0;
            std::lock_guard<std::mutex> meshLock(chunk->meshMutex);
            if (chunk->pendingMesh.valid() && chunk->pendingMesh.uploadFenceValue == 0)
            {
                chunk->pendingMesh.uploadFenceValue = submittedFenceValue;
                chunkFenceValue = submittedFenceValue;
            }
            if (chunkFenceValue != 0)
            {
                queueChunkForCommit(chunk, chunkFenceValue);
            }
        }
    }

    if (initialBudget > remainingBudget)
    {
        lastUploadBytesUsed_ = initialBudget - remainingBudget;
    }
    else
    {
        lastUploadBytesUsed_ = 0;
    }
    lastUploadMsUsed_ = std::chrono::duration<double, std::milli>(
        std::chrono::steady_clock::now() - uploadStart).count();
    uploadFinalizeMsLastFrame_ =
        std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - uploadFinalizeStart).count();

    pendingUploadsLastFrame_ = estimateUploadQueueSize();
    if (benchmarkEnabled)
    {
        benchmarkMetrics_.uploadQueueScanEntries.record(
            static_cast<std::uint64_t>(std::max(uploadQueueScanEntriesLastFrame_, 0)));
        benchmarkMetrics_.uploadAttemptsPerFrame.record(static_cast<std::uint64_t>(std::max(uploadAttemptsLastFrame_, 0)));
        benchmarkMetrics_.uploadChunksPerFrame.record(static_cast<std::uint64_t>(std::max(uploadedChunkCount, 0)));
        benchmarkMetrics_.uploadBytesPerFrame.record(static_cast<std::uint64_t>(lastUploadBytesUsed_));
        benchmarkMetrics_.uploadExpiredEntriesPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadSkippedExpiredLastFrame_, 0)));
        benchmarkMetrics_.uploadSkippedNotReadyPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadSkippedNotReadyLastFrame_, 0)));
        benchmarkMetrics_.uploadSkippedPendingMeshPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadSkippedPendingMeshLastFrame_, 0)));
        benchmarkMetrics_.uploadColumnLimitedPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadColumnLimitedLastFrame_, 0)));
        benchmarkMetrics_.uploadBudgetDeferredPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadBudgetDeferredLastFrame_, 0)));
        benchmarkMetrics_.uploadRetryFailuresPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadRetryFailuresLastFrame_, 0)));
        benchmarkMetrics_.uploadScanLimitHitsPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadScanLimitHitsLastFrame_, 0)));
        benchmarkMetrics_.uploadBeginFailuresPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadBeginFailuresLastFrame_, 0)));
        benchmarkMetrics_.uploadStalePendingMeshesPerFrame.record(
            static_cast<std::uint64_t>(std::max(uploadStalePendingMeshesLastFrame_, 0)));
    }
}

void ChunkManager::Impl::commitPendingChunkUploads()
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();

    const auto commitCollectStart = benchmarkEnabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
    collectReusableChunkBufferPages();
    collectDeferredPendingChunkReleases();
    const UINT64 completedUploadFenceValue = uploadContext_.completedFenceValue();
    if (benchmarkEnabled)
    {
        commitCollectMsLastFrame_ +=
            std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - commitCollectStart).count();
    }

    while (true)
    {
        const auto commitChunkScanStart =
            benchmarkEnabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
        PendingCommitQueueEntry entry{};
        bool haveEntry = false;
        {
            std::lock_guard<std::mutex> lock(pendingCommitQueueMutex_);
            if (!pendingCommitQueue_.empty())
            {
                const PendingCommitQueueEntry& front = pendingCommitQueue_.front();
                if (front.uploadFenceValue == 0 || completedUploadFenceValue >= front.uploadFenceValue)
                {
                    entry = front;
                    pendingCommitQueue_.pop_front();
                    haveEntry = true;
                }
            }
        }
        if (benchmarkEnabled)
        {
            commitChunkScanMsLastFrame_ +=
                std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - commitChunkScanStart).count();
        }

        if (!haveEntry)
        {
            break;
        }

        const std::shared_ptr<Chunk> chunk = entry.chunk.lock();
        if (!chunk)
        {
            continue;
        }

        if (!chunk->queuedForCommit.load(std::memory_order_acquire) ||
            chunk->commitQueueTicket.load(std::memory_order_acquire) != entry.ticket)
        {
            continue;
        }

        Chunk::PendingRenderMesh pendingMesh{};
        std::uint32_t currentMeshVersion = 0;
        std::uint32_t oldPageIndex = kInvalidChunkBufferPage;
        std::size_t oldVertexOffset = 0;
        std::size_t oldIndexOffset = 0;
        std::size_t oldVertexCount = 0;
        std::size_t oldIndexCount = 0;
        bool stalePending = false;

        const auto commitMeshLockWaitStart =
            benchmarkEnabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
        std::unique_lock<std::mutex> meshLock(chunk->meshMutex);
        if (benchmarkEnabled)
        {
            const double meshLockWaitMs =
                std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() -
                                                          commitMeshLockWaitStart)
                    .count();
            commitMeshLockWaitMsLastFrame_ += meshLockWaitMs;
            commitMeshStateMsLastFrame_ += meshLockWaitMs;
        }

        const auto commitMeshStateStart =
            benchmarkEnabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
        if (!chunk->pendingMesh.valid())
        {
            chunk->queuedForCommit.store(false, std::memory_order_release);
            chunk->commitQueueTicket.store(0, std::memory_order_release);
            if (benchmarkEnabled)
            {
                const double meshLockedMs =
                    std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() -
                                                              commitMeshStateStart)
                        .count();
                commitMeshLockedMsLastFrame_ += meshLockedMs;
                commitMeshStateMsLastFrame_ += meshLockedMs;
            }
            continue;
        }

        if (chunk->pendingMesh.uploadFenceValue != 0 &&
            completedUploadFenceValue < chunk->pendingMesh.uploadFenceValue)
        {
            const UINT64 deferredFenceValue = chunk->pendingMesh.uploadFenceValue;
            chunk->queuedForCommit.store(false, std::memory_order_release);
            chunk->commitQueueTicket.store(0, std::memory_order_release);
            if (benchmarkEnabled)
            {
                const double meshLockedMs =
                    std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() -
                                                              commitMeshStateStart)
                        .count();
                commitMeshLockedMsLastFrame_ += meshLockedMs;
                commitMeshStateMsLastFrame_ += meshLockedMs;
            }
            meshLock.unlock();
            queueChunkForCommit(chunk, deferredFenceValue);
            continue;
        }

        pendingMesh = chunk->pendingMesh;
        chunk->pendingMesh = {};
        chunk->pendingMeshPresent.store(false, std::memory_order_release);
        chunk->queuedForCommit.store(false, std::memory_order_release);
        chunk->commitQueueTicket.store(0, std::memory_order_release);
        currentMeshVersion = chunk->meshVersion.load(std::memory_order_acquire);
        stalePending = currentMeshVersion != pendingMesh.meshVersion;
        if (!stalePending)
        {
            oldPageIndex = chunk->bufferPageIndex.load(std::memory_order_acquire);
            oldVertexOffset = chunk->vertexOffset.load(std::memory_order_acquire);
            oldIndexOffset = chunk->indexOffset.load(std::memory_order_acquire);
            oldVertexCount = chunk->vertexCount.load(std::memory_order_acquire);
            oldIndexCount = static_cast<std::size_t>(chunk->indexCount.load(std::memory_order_acquire));
            chunk->bufferPageIndex.store(pendingMesh.pageIndex, std::memory_order_release);
            chunk->vertexOffset.store(pendingMesh.vertexOffset, std::memory_order_release);
            chunk->indexOffset.store(pendingMesh.indexOffset, std::memory_order_release);
            chunk->vertexCount.store(pendingMesh.vertexCount, std::memory_order_release);
            chunk->indexCount.store(static_cast<std::uint32_t>(pendingMesh.indexCount), std::memory_order_release);
        }
        if (benchmarkEnabled)
        {
            const double meshLockedMs =
                std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() -
                                                          commitMeshStateStart)
                    .count();
            commitMeshLockedMsLastFrame_ += meshLockedMs;
            commitMeshStateMsLastFrame_ += meshLockedMs;
        }
        meshLock.unlock();

        const auto commitPageStateStart =
            benchmarkEnabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
        if (!stalePending && pendingMesh.pageIndex < bufferPages_.size())
        {
            std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
            if (pendingMesh.pageIndex < bufferPages_.size())
            {
                ChunkBufferPage& page = bufferPages_[pendingMesh.pageIndex];
                if (page.pendingChunks > 0)
                {
                    --page.pendingChunks;
                }
                if (!stalePending)
                {
                    ++page.residentChunks;
                    page.state = ChunkBufferPageState::ResidentImmutable;
                    page.uploadFenceValue = 0;
                    page.pendingBatchId = 0;
                    releaseChunkBufferPageUploadBuffers(page);
                    noteExactGpuPageMetadataChange(pendingMesh.pageIndex);
                }
            }
        }
        if (benchmarkEnabled)
        {
            commitPageStateMsLastFrame_ +=
                std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - commitPageStateStart)
                    .count();
        }

        const auto commitReleaseStart =
            benchmarkEnabled ? std::chrono::steady_clock::now() : std::chrono::steady_clock::time_point{};
        if (stalePending)
        {
            ++uploadStalePendingMeshesLastFrame_;
            if (pendingMesh.pageIndex != kInvalidChunkBufferPage)
            {
                releaseChunkAllocationRange(pendingMesh.pageIndex,
                                            pendingMesh.vertexOffset,
                                            pendingMesh.vertexCount,
                                            pendingMesh.indexOffset,
                                            pendingMesh.indexCount,
                                            false);
            }
            if (chunk->meshReady.load(std::memory_order_acquire) &&
                chunk->state.load(std::memory_order_acquire) == ChunkState::Ready)
            {
                queueChunkForLocalCpuUpload(chunk, true);
            }
            if (benchmarkEnabled)
            {
                commitReleaseMsLastFrame_ +=
                    std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - commitReleaseStart)
                        .count();
            }
            continue;
        }

        if (oldPageIndex != kInvalidChunkBufferPage)
        {
            releaseChunkAllocationRange(oldPageIndex,
                                        oldVertexOffset,
                                        oldVertexCount,
                                        oldIndexOffset,
                                        oldIndexCount,
                                        true);
        }

        publishChunkReady(*chunk);
        if (benchmarkEnabled)
        {
            commitReleaseMsLastFrame_ +=
                std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - commitReleaseStart)
                    .count();
        }
    }
}

void ChunkManager::Impl::queueChunkForExactGpuBuild(const std::shared_ptr<Chunk>& chunk,
                                                    std::uint32_t buildVersion,
                                                    bool prioritizeFront)
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    if (!chunk ||
        shouldStop_.load(std::memory_order_acquire) ||
        device_ == nullptr ||
        !exactGpuContext_.ready())
    {
        return;
    }

    chunk->exactGpuBuildVersion.store(buildVersion, std::memory_order_release);
    const bool wasQueued = chunk->exactGpuBuildQueued.exchange(true, std::memory_order_acq_rel);
    refreshPendingExactGpuBuildCount(*chunk);
    if (!wasQueued && !chunk->exactGpuBuildInFlight.load(std::memory_order_acquire))
    {
        chunk->inFlight.fetch_add(1, std::memory_order_relaxed);
    }
    if (wasQueued)
    {
        return;
    }

    ExactGpuBuildRequest request{};
    request.chunk = chunk;
    request.buildVersion = buildVersion;
    request.generationEpoch = chunk->generationEpoch.load(std::memory_order_acquire);
    request.inputVersion = chunk->exactGpuInputsVersion.load(std::memory_order_acquire);
    request.queuedTimestampMicros = benchmarkEnabled ? steadyMicrosNow() : 0u;
    request.rebuildVoxelInputs =
        chunk->exactGpuInputsDirty.load(std::memory_order_acquire) ||
        !chunk->exactGpuResident.load(std::memory_order_acquire) ||
        chunk->exactGpu.voxelBuffer == nullptr;
    request.prioritizeFront = prioritizeFront;
    storeFirstBenchmarkTimestamp(chunk->uploadQueuedTimestampMicros,
                                 request.queuedTimestampMicros != 0u ? request.queuedTimestampMicros
                                                                     : steadyMicrosNow());

    std::lock_guard<std::mutex> lock(pendingExactGpuBuildMutex_);
    if (prioritizeFront)
    {
        pendingExactGpuBuildQueue_.push_front(std::move(request));
    }
    else
    {
        pendingExactGpuBuildQueue_.push_back(std::move(request));
    }
    if (benchmarkEnabled)
    {
        benchmarkMetrics_.exactGpuBuildQueueDepthEnqueue.record(
            static_cast<std::uint64_t>(pendingExactGpuBuildQueue_.size()));
    }
    wakeExactGpuWorker();
}

void ChunkManager::Impl::recordExactGpuResourceFailure(ExactGpuResourceFailureReason reason) noexcept
{
    exactGpuBuildResourceFailures_.fetch_add(1, std::memory_order_relaxed);
    exactGpuResourceFailureCounts_[static_cast<std::size_t>(reason)].fetch_add(1, std::memory_order_relaxed);
}

void ChunkManager::Impl::recordExactGpuReservationFailureDebug(std::uint32_t requestedFaceCount,
                                                               std::size_t pageFaceCapacity,
                                                               std::size_t pageRecordCapacity,
                                                               std::size_t freeExactGpuPageCount,
                                                               std::size_t exactOpenWritablePages,
                                                               std::size_t exactSealedPendingResidentPages,
                                                               std::size_t exactResidentImmutablePages,
                                                               std::size_t exactFreePages,
                                                               std::string_view exceptionText)
{
    std::lock_guard<std::mutex> lock(exactGpuReservationFailureDebugMutex_);
    lastExactGpuReservationFailure_.timestampMicros = steadyMicrosNow();
    lastExactGpuReservationFailure_.requestedFaceCount = requestedFaceCount;
    lastExactGpuReservationFailure_.pageFaceCapacity = pageFaceCapacity;
    lastExactGpuReservationFailure_.pageRecordCapacity = pageRecordCapacity;
    lastExactGpuReservationFailure_.freeExactGpuPageCount = freeExactGpuPageCount;
    lastExactGpuReservationFailure_.exactOpenWritablePages = exactOpenWritablePages;
    lastExactGpuReservationFailure_.exactSealedPendingResidentPages = exactSealedPendingResidentPages;
    lastExactGpuReservationFailure_.exactResidentImmutablePages = exactResidentImmutablePages;
    lastExactGpuReservationFailure_.exactFreePages = exactFreePages;
    lastExactGpuReservationFailure_.exceptionText.assign(exceptionText.begin(), exceptionText.end());
}

bool ChunkManager::Impl::rebuildChunkGpuExactInputsLocked(
    Chunk& chunk,
    std::span<const PendingStructureEdit> pendingStructureEdits,
    std::span<const BlockEditOverlayEntry> blockOverlays)
{
    std::vector<GpuExactSparseVoxel> gpuSparseVoxels;
    gpuSparseVoxels.reserve(chunk.structureVoxelEdits.size() +
                            pendingStructureEdits.size() +
                            blockOverlays.size());
    auto appendSparseVoxel = [&](const glm::ivec3& local,
                                 BlockId block,
                                 bool replaceSolid)
    {
        if (local.x < 0 || local.x >= kChunkSizeX ||
            local.y < 0 || local.y >= kChunkSizeY ||
            local.z < 0 || local.z >= kChunkSizeZ)
        {
            return;
        }

        gpuSparseVoxels.push_back(GpuExactSparseVoxel{
            packGpuExactLocalVoxelPos(local),
            static_cast<std::uint32_t>(block),
            replaceSolid ? 1u : 0u,
            0u});
    };

    for (const StructureVoxelEdit& edit : chunk.structureVoxelEdits)
    {
        appendSparseVoxel(localBlockCoords(edit.worldPos, chunk.coord), edit.block, edit.replaceSolid);
    }
    for (const PendingStructureEdit& edit : pendingStructureEdits)
    {
        appendSparseVoxel(localBlockCoords(edit.worldPos, chunk.coord), edit.block, edit.replaceSolid);
    }
    for (const BlockEditOverlayEntry& overlay : blockOverlays)
    {
        const int localX = overlay.localIndex % kChunkSizeX;
        const int localZ = (overlay.localIndex / kChunkSizeX) % kChunkSizeZ;
        const int localY = overlay.localIndex / (kChunkSizeX * kChunkSizeZ);
        appendSparseVoxel(glm::ivec3(localX, localY, localZ), overlay.block, true);
    }

    chunk.gpuExactSparseVoxels = std::move(gpuSparseVoxels);
    chunk.gpuExactSparseVoxelsReady = true;
    chunk.exactGpuInputsDirty.store(true, std::memory_order_release);

    const bool anyBlocks = chunk.exactBaseTerrainPresent ||
                           !chunk.structureVoxelEdits.empty() ||
                           !pendingStructureEdits.empty() ||
                           !blockOverlays.empty() ||
                           chunkHasPendingStructureEdits(chunk.coord) ||
                           chunkHasBlockEditOverlay(chunk.coord);
    chunk.hasBlocks.store(anyBlocks, std::memory_order_release);
    refreshPendingExactGpuBuildCount(chunk);
    return true;
}

bool ChunkManager::Impl::refreshChunkGpuExactInputs(Chunk& chunk)
{
    std::vector<PendingStructureEdit> pendingStructureEdits = copyPendingStructureEdits(chunk.coord);
    std::vector<BlockEditOverlayEntry> blockOverlays;
    for (const WorldEditStore::Entry& overlay : copyBlockEditOverlayEntries(chunk.coord))
    {
        blockOverlays.push_back(BlockEditOverlayEntry{overlay.localIndex, overlay.block});
    }

    std::lock_guard<std::mutex> lock(chunk.meshMutex);
    return rebuildChunkGpuExactInputsLocked(chunk, pendingStructureEdits, blockOverlays);
}

bool ChunkManager::Impl::shouldPrioritizeExactGpuBuild(const Chunk& chunk) const
{
    return chunkAwaitingInitialVisibleReady(chunk) ||
           chunk.gameplayAuthority.load(std::memory_order_acquire) == ChunkGameplayAuthority::HandoffToGpu;
}

bool ChunkManager::Impl::queuePreparedExactGpuBuildLocked(const std::shared_ptr<Chunk>& chunk,
                                                          bool prioritizeFront)
{
    if (!chunk ||
        (chunk->exactGpuInputsDirty.load(std::memory_order_acquire) && !chunk->gpuExactSparseVoxelsReady))
    {
        return false;
    }

    const std::uint64_t currentInputVersion =
        chunk->exactGpuInputsVersion.load(std::memory_order_acquire);
    const std::uint64_t requestedInputVersion =
        chunk->exactGpuRequestedInputVersion.load(std::memory_order_acquire);
    const bool buildQueued = chunk->exactGpuBuildQueued.load(std::memory_order_acquire);
    const bool buildInFlight = chunk->exactGpuBuildInFlight.load(std::memory_order_acquire);
    const bool publishPending = chunk->exactGpuPublishPending.load(std::memory_order_acquire);
    const bool haloDirty = chunk->exactGpuHaloDirty.load(std::memory_order_acquire);
    const bool drawCurrent =
        (chunk->exactGpuResident.load(std::memory_order_acquire) || publishPending) &&
        !chunk->exactGpuInputsDirty.load(std::memory_order_acquire) &&
        chunk->exactGpuReadyVersion.load(std::memory_order_acquire) == currentInputVersion;
    if ((drawCurrent && !haloDirty) ||
        ((buildQueued || buildInFlight) && requestedInputVersion == currentInputVersion))
    {
        return true;
    }

    const std::uint64_t preparedInputVersion =
        chunk->exactGpuInputsVersion.load(std::memory_order_acquire);
    if ((chunk->exactGpuBuildQueued.load(std::memory_order_acquire) ||
         chunk->exactGpuBuildInFlight.load(std::memory_order_acquire)) &&
        chunk->exactGpuRequestedInputVersion.load(std::memory_order_acquire) == preparedInputVersion)
    {
        return true;
    }

    const bool hasCurrentDraw =
        chunk->exactGpuResident.load(std::memory_order_acquire) ||
        chunk->indexCount.load(std::memory_order_acquire) > 0;
    const ChunkState state = chunk->state.load(std::memory_order_acquire);
    if (state == ChunkState::Uploaded ||
        state == ChunkState::Ready ||
        state == ChunkState::Remeshing)
    {
        chunk->state.store(hasCurrentDraw ? ChunkState::Remeshing : ChunkState::Meshing,
                           std::memory_order_release);
    }

    if (chunkAwaitingInitialVisibleReady(*chunk) ||
        !chunk->exactGpuResident.load(std::memory_order_acquire))
    {
        setStreamingChunkLifecycleState(chunk->coord, FrontierDemandState::Meshing);
    }

    chunk->exactGpuRequestedInputVersion.store(preparedInputVersion, std::memory_order_release);
    const std::uint32_t buildVersion =
        chunk->exactGpuBuildVersion.fetch_add(1, std::memory_order_acq_rel) + 1u;
    queueChunkForExactGpuBuild(chunk, buildVersion, prioritizeFront || shouldPrioritizeExactGpuBuild(*chunk));
    return true;
}

bool ChunkManager::Impl::queueChunkForPreparedExactGpuBuild(const std::shared_ptr<Chunk>& chunk,
                                                            bool prioritizeFront)
{
    if (!chunk ||
        shouldStop_.load(std::memory_order_acquire) ||
        device_ == nullptr ||
        !exactGpuContext_.ready())
    {
        return false;
    }

    std::lock_guard<std::mutex> lock(chunk->meshMutex);
    return queuePreparedExactGpuBuildLocked(chunk, prioritizeFront);
}

void ChunkManager::Impl::queueChunkForExactGpuRefresh(const std::shared_ptr<Chunk>& chunk, bool prioritizeFront)
{
    if (!chunk ||
        shouldStop_.load(std::memory_order_acquire) ||
        device_ == nullptr ||
        !exactGpuContext_.ready())
    {
        return;
    }

    std::lock_guard<std::mutex> lock(chunk->meshMutex);
    const std::uint64_t currentInputVersion =
        chunk->exactGpuInputsVersion.load(std::memory_order_acquire);
    const std::uint64_t requestedInputVersion =
        chunk->exactGpuRequestedInputVersion.load(std::memory_order_acquire);
    const bool buildQueued = chunk->exactGpuBuildQueued.load(std::memory_order_acquire);
    const bool buildInFlight = chunk->exactGpuBuildInFlight.load(std::memory_order_acquire);
    const bool publishPending = chunk->exactGpuPublishPending.load(std::memory_order_acquire);
    const bool haloDirty = chunk->exactGpuHaloDirty.load(std::memory_order_acquire);
    const bool drawCurrent =
        (chunk->exactGpuResident.load(std::memory_order_acquire) || publishPending) &&
        !chunk->exactGpuInputsDirty.load(std::memory_order_acquire) &&
        chunk->exactGpuReadyVersion.load(std::memory_order_acquire) == currentInputVersion;
    if ((drawCurrent && !haloDirty) ||
        ((buildQueued || buildInFlight) && requestedInputVersion == currentInputVersion))
    {
        return;
    }

    if (chunk->exactGpuInputsDirty.load(std::memory_order_acquire))
    {
        const bool canUseDenseUpload =
            chunk->exactGpuPreferDenseUpload.load(std::memory_order_acquire) &&
            chunk->cpuDataResident.load(std::memory_order_acquire) &&
            !chunk->blocks.empty();
        if (canUseDenseUpload)
        {
            chunk->gpuExactSparseVoxels.clear();
            chunk->gpuExactSparseVoxelsReady = true;
        }
        else
        {
            std::vector<PendingStructureEdit> pendingStructureEdits = copyPendingStructureEdits(chunk->coord);
            std::vector<BlockEditOverlayEntry> blockOverlays;
            for (const WorldEditStore::Entry& overlay : copyBlockEditOverlayEntries(chunk->coord))
            {
                blockOverlays.push_back(BlockEditOverlayEntry{overlay.localIndex, overlay.block});
            }

            if (!rebuildChunkGpuExactInputsLocked(*chunk, pendingStructureEdits, blockOverlays))
            {
                return;
            }
        }
    }
    (void)queuePreparedExactGpuBuildLocked(chunk, prioritizeFront);
}

void ChunkManager::Impl::queueChunkForExactGpuBorderRefresh(const std::shared_ptr<Chunk>& chunk)
{
    if (!chunk ||
        shouldStop_.load(std::memory_order_acquire) ||
        device_ == nullptr ||
        !exactGpuContext_.ready())
    {
        return;
    }

    const bool shouldRefresh =
        chunk->exactGpuResident.load(std::memory_order_acquire) ||
        chunk->exactGpuPublishPending.load(std::memory_order_acquire) ||
        chunk->exactGpuBuildQueued.load(std::memory_order_acquire) ||
        chunk->exactGpuBuildInFlight.load(std::memory_order_acquire) ||
        chunk->exactGpuPendingNeighborMask.load(std::memory_order_acquire) != 0u;
    if (!shouldRefresh)
    {
        return;
    }

    const bool alreadyDirty = chunk->exactGpuHaloDirty.exchange(true, std::memory_order_acq_rel);
    if (alreadyDirty &&
        (chunk->exactGpuBuildQueued.load(std::memory_order_acquire) ||
         chunk->exactGpuBuildInFlight.load(std::memory_order_acquire)))
    {
        return;
    }

    queueChunkForExactGpuRefresh(chunk);
}

void ChunkManager::Impl::resolveExactGpuNeighborState(
    Chunk& chunk,
    UINT64 completedExactGpuFenceValue,
    std::array<ID3D12Resource*, 6>& neighborBuffers,
    std::uint32_t& resolvedNeighborMask,
    std::uint8_t& pendingNeighborMask,
    std::array<Chunk*, 6>& neighborChunksToRestore,
    std::size_t& neighborRestoreCount)
{
    const std::array<std::pair<glm::ivec3, std::uint8_t>, 6> seamNeighbors{{
        {glm::ivec3(1, 0, 0), kExactGpuSeamPosXBit},
        {glm::ivec3(-1, 0, 0), kExactGpuSeamNegXBit},
        {glm::ivec3(0, 1, 0), kExactGpuSeamPosYBit},
        {glm::ivec3(0, -1, 0), kExactGpuSeamNegYBit},
        {glm::ivec3(0, 0, 1), kExactGpuSeamPosZBit},
        {glm::ivec3(0, 0, -1), kExactGpuSeamNegZBit},
    }};

    neighborBuffers.fill(exactGpuEmptyVoxelBuffer_.Get());
    resolvedNeighborMask = 0u;
    pendingNeighborMask = 0u;
    neighborRestoreCount = 0u;

    auto rememberNeighborForRestore = [&](Chunk& neighbor)
    {
        if (neighbor.exactGpu.seamBuffer == nullptr)
        {
            return;
        }

        if (neighbor.exactGpu.seamState != D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE)
        {
            exactGpuContext_.transition(neighbor.exactGpu.seamBuffer.Get(),
                                        neighbor.exactGpu.seamState,
                                        D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
            neighbor.exactGpu.seamState = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
        }

        const bool alreadyQueued =
            std::find(neighborChunksToRestore.begin(),
                      neighborChunksToRestore.begin() + static_cast<std::ptrdiff_t>(neighborRestoreCount),
                      &neighbor) !=
            neighborChunksToRestore.begin() + static_cast<std::ptrdiff_t>(neighborRestoreCount);
        if (!alreadyQueued && neighborRestoreCount < neighborChunksToRestore.size())
        {
            neighbor.inFlight.fetch_add(1, std::memory_order_relaxed);
            neighborChunksToRestore[neighborRestoreCount++] = &neighbor;
        }
    };

    auto lookupReadyNeighbor = [&](const glm::ivec3& neighborCoord) -> Chunk*
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        const auto it = chunks_.find(neighborCoord);
        if (it == chunks_.end() || !it->second)
        {
            return nullptr;
        }

        Chunk& neighbor = *it->second;
        if (neighbor.exactGpu.seamBuffer == nullptr ||
            neighbor.exactGpu.readyFenceValue == 0 ||
            completedExactGpuFenceValue < neighbor.exactGpu.readyFenceValue ||
            neighbor.exactGpuBuildInFlight.load(std::memory_order_acquire))
        {
            return nullptr;
        }

        return &neighbor;
    };

    for (std::size_t neighborIndex = 0; neighborIndex < seamNeighbors.size(); ++neighborIndex)
    {
        const auto& [offset, seamBit] = seamNeighbors[neighborIndex];
        const glm::ivec3 neighborCoord = chunk.coord + offset;
        if (Chunk* readyNeighbor = lookupReadyNeighbor(neighborCoord))
        {
            rememberNeighborForRestore(*readyNeighbor);
            neighborBuffers[neighborIndex] = readyNeighbor->exactGpu.seamBuffer.Get();
            resolvedNeighborMask |= seamBit;
            continue;
        }

        bool missingNeighborMayArrive = false;
        {
            std::lock_guard<std::mutex> lock(chunksMutex);
            const auto it = chunks_.find(neighborCoord);
            if (it != chunks_.end() && it->second)
            {
                missingNeighborMayArrive = true;
            }
        }

        FrontierDemandState state{};
        if (tryGetStreamingChunkLifecycleState(neighborCoord, state))
        {
            missingNeighborMayArrive = true;
        }

        if (missingNeighborMayArrive)
        {
            pendingNeighborMask |= seamBit;
        }
    }
}

void ChunkManager::Impl::restoreExactGpuNeighborStates(const std::array<Chunk*, 6>& neighborChunksToRestore,
                                                       std::size_t neighborRestoreCount)
{
    for (std::size_t restoreIndex = 0; restoreIndex < neighborRestoreCount; ++restoreIndex)
    {
        Chunk* neighborChunk = neighborChunksToRestore[restoreIndex];
        if (neighborChunk == nullptr ||
            neighborChunk->exactGpu.seamBuffer == nullptr ||
            neighborChunk->exactGpu.seamState == D3D12_RESOURCE_STATE_COMMON)
        {
            if (neighborChunk != nullptr)
            {
                neighborChunk->inFlight.fetch_sub(1, std::memory_order_relaxed);
            }
            continue;
        }

        exactGpuContext_.transition(neighborChunk->exactGpu.seamBuffer.Get(),
                                    neighborChunk->exactGpu.seamState,
                                    D3D12_RESOURCE_STATE_COMMON);
        neighborChunk->exactGpu.seamState = D3D12_RESOURCE_STATE_COMMON;
        neighborChunk->inFlight.fetch_sub(1, std::memory_order_relaxed);
    }
}

    void ChunkManager::Impl::submitPendingExactGpuBuilds()
    {
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const SteadyClock::time_point submitStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    std::uint64_t prepareMicros = 0u;
    int submitBatchBuilds = 0;
    bool processedRequests = false;

    const auto recordSubmitStats = [&](bool didWork)
    {
        (void)didWork;
    };

    if (device_ == nullptr ||
        !exactGpuContext_.ready() ||
        exactGpuBlockUvBuffer_ == nullptr ||
        exactGpuBlockUvCount_ == 0 ||
        exactGpuBlockUvSrvDescriptorIndex_ == FarLodGpuContext::kInvalidDescriptorIndex ||
        exactGpuEmptyVoxelBuffer_ == nullptr)
    {
        return;
    }

    std::size_t pendingBuildCount = 0u;
    std::size_t pendingBatchCount = 0u;
    {
        std::lock_guard<std::mutex> lock(pendingExactGpuBuildsMutex_);
        for (const PendingExactGpuBatch& batch : pendingExactGpuBatches_)
        {
            pendingBuildCount += batch.builds.size();
        }
        pendingBatchCount = pendingExactGpuBatches_.size();
    }
    if (pendingBuildCount >= kMaxOutstandingExactGpuBuilds ||
        pendingBatchCount >= kMaxOutstandingExactGpuBatches ||
        freeExactGpuScratchSlices_.empty())
    {
        return;
    }
    const std::size_t availableBuildSlots =
        std::min({kMaxOutstandingExactGpuBuilds - pendingBuildCount,
                  exactGpuContext_.maxExactGpuBuildBatches(),
                  freeExactGpuScratchSlices_.size()});
    if (availableBuildSlots == 0u)
    {
        return;
    }
    std::unique_lock<std::mutex> exactLock(exactGpuExecutionMutex_);
    if (!exactGpuContext_.begin())
    {
        return;
    }

    const auto alignUp = [](std::uint64_t value, std::uint64_t alignment) -> std::uint64_t
    {
        if (alignment <= 1u)
        {
            return value;
        }
        return ((value + alignment - 1u) / alignment) * alignment;
    };
    const std::uint64_t exactUploadBudget =
        static_cast<std::uint64_t>(exactGpuContext_.uploadScratchBytesPerSubmission());
    const std::uint64_t exactReadbackBudget =
        static_cast<std::uint64_t>(exactGpuContext_.readbackScratchBytesPerSubmission());
    const auto appendExactUploadBytes = [&](std::uint64_t& cursor,
                                            std::uint64_t sizeInBytes,
                                            std::uint64_t alignment) -> bool
    {
        if (sizeInBytes == 0u)
        {
            return true;
        }

        const std::uint64_t alignedOffset = alignUp(cursor, alignment);
        // Match the actual per-submission allocator budget to avoid staging work that
        // cannot fit into the active submission slot and would immediately requeue.
        if (alignedOffset + sizeInBytes > exactUploadBudget)
        {
            return false;
        }

        cursor = alignedOffset + sizeInBytes;
        return true;
    };
    const auto appendExactReadbackBytes = [&](std::uint64_t& cursor,
                                              std::uint64_t sizeInBytes,
                                              std::uint64_t alignment) -> bool
    {
        if (sizeInBytes == 0u)
        {
            return true;
        }

        const std::uint64_t alignedOffset = alignUp(cursor, alignment);
        if (alignedOffset + sizeInBytes > exactReadbackBudget)
        {
            return false;
        }

        cursor = alignedOffset + sizeInBytes;
        return true;
    };
    std::deque<ExactGpuBuildRequest> deferredRequests;
    struct PreparedExactGpuBuild
    {
        std::shared_ptr<Chunk> chunk;
        std::uint32_t buildVersion{0};
        std::uint32_t generationEpoch{0};
        std::uint64_t inputVersion{0};
        bool rebuildVoxelInputs{false};
        ExactGpuVoxelInputMode voxelInputMode{ExactGpuVoxelInputMode::None};
        std::uint32_t tentativeScratchSliceIndex{std::numeric_limits<std::uint32_t>::max()};
    };
    std::vector<PreparedExactGpuBuild> preparedBuilds;
    preparedBuilds.reserve(availableBuildSlots);
    std::vector<PendingExactGpuBuild> stagedBuilds;
    stagedBuilds.reserve(availableBuildSlots);

    auto requeuePreparedBuildRequest = [&](const PreparedExactGpuBuild& prepared)
    {
        if (!prepared.chunk)
        {
            return;
        }

        const bool prioritizeFront = shouldPrioritizeExactGpuBuild(*prepared.chunk);

        std::lock_guard<std::mutex> lock(pendingExactGpuBuildMutex_);
        ExactGpuBuildRequest request{prepared.chunk,
                                     prepared.buildVersion,
                                     prepared.generationEpoch,
                                     prepared.inputVersion,
                                     benchmarkEnabled ? steadyMicrosNow() : 0u,
                                     prepared.rebuildVoxelInputs,
                                     prioritizeFront};
        if (prioritizeFront)
        {
            pendingExactGpuBuildQueue_.push_front(std::move(request));
        }
        else
        {
            pendingExactGpuBuildQueue_.push_back(std::move(request));
        }
        if (benchmarkEnabled)
        {
            benchmarkMetrics_.exactGpuBuildQueueDepthEnqueue.record(
                static_cast<std::uint64_t>(pendingExactGpuBuildQueue_.size()));
        }
    };

    auto requeueRemainingPreparedBuilds = [&](std::size_t beginIndex)
    {
        for (std::size_t i = beginIndex; i < preparedBuilds.size(); ++i)
        {
            requeuePreparedBuildRequest(preparedBuilds[i]);
        }
        preparedBuilds.resize(beginIndex);
    };

    auto requeueBuildRequest = [&](PendingExactGpuBuild& pending)
    {
        if (pending.scratchSliceIndex != std::numeric_limits<std::uint32_t>::max())
        {
            freeExactGpuScratchSlices_.push_back(pending.scratchSliceIndex);
            clearExactGpuChunkAllocationRecord(pending.scratchSliceIndex);
            pending.scratchSliceIndex = std::numeric_limits<std::uint32_t>::max();
        }
        if (!pending.chunk)
        {
            return;
        }
        pending.chunk->exactGpuBuildQueued.store(true, std::memory_order_release);
        pending.chunk->exactGpuBuildInFlight.store(false, std::memory_order_release);
        refreshPendingExactGpuBuildCount(*pending.chunk);
        releasePendingExactBuildAllocation(pending, false);
        const bool prioritizeFront = shouldPrioritizeExactGpuBuild(*pending.chunk);
        std::lock_guard<std::mutex> lock(pendingExactGpuBuildMutex_);
        ExactGpuBuildRequest request{pending.chunk,
                                     pending.buildVersion,
                                     pending.generationEpoch,
                                     pending.inputVersion,
                                     benchmarkEnabled ? steadyMicrosNow() : 0u,
                                     pending.rebuildVoxelInputs,
                                     prioritizeFront};
        if (prioritizeFront)
        {
            pendingExactGpuBuildQueue_.push_front(std::move(request));
        }
        else
        {
            pendingExactGpuBuildQueue_.push_back(std::move(request));
        }
        if (benchmarkEnabled)
        {
            benchmarkMetrics_.exactGpuBuildQueueDepthEnqueue.record(
                static_cast<std::uint64_t>(pendingExactGpuBuildQueue_.size()));
        }
    };

    auto requeueRemainingStagedBuilds = [&](std::size_t beginIndex)
    {
        for (std::size_t i = beginIndex; i < stagedBuilds.size(); ++i)
        {
            requeueBuildRequest(stagedBuilds[i]);
        }
        stagedBuilds.resize(beginIndex);
    };

    const auto discardOpenSubmission = [&]()
    {
        const FarLodGpuContext::FlushResult discardFlush = exactGpuContext_.flush();
        if (discardFlush.fenceValue != 0)
        {
            exactGpuContext_.waitForFence(discardFlush.fenceValue);
            exactGpuContext_.releaseSubmissionSlot(discardFlush.submissionSlotIndex);
        }
    };

    if (!ensureExactGpuChunkAllocationRecordBuffer())
    {
        discardOpenSubmission();
        return;
    }

    const auto exactBuildRecordUploadBytes = [](std::size_t buildCount) -> std::uint64_t
    {
        return static_cast<std::uint64_t>(buildCount) * sizeof(FarLodGpuContext::ExactChunkAllocationRecord);
    };
    const auto exactPrepassRecordUploadBytes = [](std::size_t buildCount) -> std::uint64_t
    {
        return static_cast<std::uint64_t>(buildCount) * sizeof(GpuExactPrepassRecord);
    };
    const auto exactPrepassFaceTotalsReadbackBytes = [&](std::size_t buildCount) -> std::uint64_t
    {
        return static_cast<std::uint64_t>(exactGpuContext_.exactFaceTotalsReadbackBytes(buildCount));
    };
    const auto exactBatchBuildIndexUploadBytes = [](std::size_t buildCount) -> std::uint64_t
    {
        return static_cast<std::uint64_t>(buildCount) * sizeof(std::uint32_t);
    };
    const auto pendingExactGpuEmitMetadataUploadBytes = [&]() -> std::uint64_t
    {
        std::lock_guard<std::mutex> lock(bufferPageMutex_);
        const std::size_t pageCount = bufferPages_.size();
        const std::uint32_t requiredPageCapacity = static_cast<std::uint32_t>(
            std::max<std::size_t>(1u, nextPowerOfTwo(std::max<std::size_t>(pageCount, 1u))));
        const bool configUploadRequired = exactGpuEmitConfigDirty_ || exactGpuEmitConfigBuffer_ == nullptr;
        const bool pageMetadataFullRefresh =
            exactGpuPageMetadataBuffer_ == nullptr ||
            exactGpuPageMetadataCapacity_ < requiredPageCapacity;

        return (configUploadRequired ? exactGpuEmitConfigBytes() : 0u) +
               static_cast<std::uint64_t>(pageMetadataFullRefresh ? pageCount : exactGpuDirtyPageIndices_.size()) *
                   sizeof(FarLodGpuContext::ExactPageGpuMetadata);
    };
    const auto fitsEmitPhaseResources = [&](std::size_t buildCount) -> bool
    {
        std::uint64_t emitUploadCursor = 0u;
        std::uint64_t emitReadbackCursor = 0u;
        return appendExactUploadBytes(emitUploadCursor,
                                      sizeof(std::uint32_t),
                                      alignof(std::uint32_t)) &&
               appendExactUploadBytes(emitUploadCursor,
                                      pendingExactGpuEmitMetadataUploadBytes(),
                                      alignof(FarLodGpuContext::ExactPageGpuMetadata)) &&
               appendExactUploadBytes(emitUploadCursor,
                                      exactBuildRecordUploadBytes(buildCount),
                                      alignof(FarLodGpuContext::ExactChunkAllocationRecord)) &&
               appendExactUploadBytes(emitUploadCursor,
                                      exactBatchBuildIndexUploadBytes(buildCount),
                                      alignof(std::uint32_t)) &&
               appendExactReadbackBytes(emitReadbackCursor,
                                        exactGpuContext_.exactCompletionReadbackBytes(buildCount),
                                        alignof(FarLodGpuContext::ExactCompletionEntry));
    };
    const auto fitsPrepassPhaseResources = [&](std::size_t buildCount) -> bool
    {
        std::uint64_t prepassReadbackCursor = 0u;
        return appendExactReadbackBytes(prepassReadbackCursor,
                                        exactPrepassFaceTotalsReadbackBytes(buildCount),
                                        alignof(std::uint32_t));
    };

    while (preparedBuilds.size() < availableBuildSlots)
    {
        ExactGpuBuildRequest request{};
        bool haveRequest = false;
        std::size_t queueDepthOnStart = 0u;
        {
            std::lock_guard<std::mutex> lock(pendingExactGpuBuildMutex_);
            if (!pendingExactGpuBuildQueue_.empty())
            {
                queueDepthOnStart = pendingExactGpuBuildQueue_.size();
                constexpr std::uint32_t kMaxInteractiveStreak = 12u;
                const bool forceFairPick =
                    exactGpuInteractiveBuildStreak_ >= kMaxInteractiveStreak &&
                    pendingExactGpuBuildQueue_.size() > 1;
                if (forceFairPick)
                {
                    request = pendingExactGpuBuildQueue_.back();
                    pendingExactGpuBuildQueue_.pop_back();
                }
                else
                {
                    request = pendingExactGpuBuildQueue_.front();
                    pendingExactGpuBuildQueue_.pop_front();
                }
                haveRequest = true;
            }
        }
        if (!haveRequest)
        {
            break;
        }
        if (request.prioritizeFront)
        {
            ++exactGpuInteractiveBuildStreak_;
        }
        else
        {
            exactGpuInteractiveBuildStreak_ = 0;
        }
        if (benchmarkEnabled)
        {
            benchmarkMetrics_.exactGpuBuildQueueDepthStart.record(static_cast<std::uint64_t>(queueDepthOnStart));
            const std::uint64_t queueWaitEndMicros = steadyMicrosNow();
            if (request.queuedTimestampMicros > 0u && queueWaitEndMicros > request.queuedTimestampMicros)
            {
                benchmarkMetrics_.exactGpuBuildQueueWaitStage.recordMicros(
                    queueWaitEndMicros - request.queuedTimestampMicros);
            }
        }
        processedRequests = true;
        if (!request.chunk)
        {
            continue;
        }

        Chunk& chunk = *request.chunk;
        if (!chunk.exactGpuBuildQueued.load(std::memory_order_acquire))
        {
            continue;
        }
        if (chunk.exactGpuBuildInFlight.load(std::memory_order_acquire))
        {
            deferredRequests.push_back(std::move(request));
            continue;
        }
        const bool requestNeedsVoxelInputs =
            request.rebuildVoxelInputs ||
            chunk.exactGpuInputsDirty.load(std::memory_order_acquire) ||
            !chunk.exactGpuResident.load(std::memory_order_acquire) ||
            chunk.exactGpu.voxelBuffer == nullptr;
        if (requestNeedsVoxelInputs && !chunk.gpuExactSparseVoxelsReady)
        {
            // Under rapid edit churn, it is possible for a build request to be in-flight/queued while
            // the CPU-side sparse voxel inputs have not been rebuilt yet. Dropping the request can
            // leave the chunk permanently stale (CPU world updated, GPU draw record still active).
            //
            // Build the sparse voxel list on-demand here and retry; if we cannot, defer without
            // clearing exactGpuBuildQueued so the refresh attempt is not lost.
            const bool rebuiltInputs = refreshChunkGpuExactInputs(chunk);
            if (!rebuiltInputs)
            {
                deferredRequests.push_back(std::move(request));
                continue;
            }
            if (exactUploadDebugLoggingEnabled())
            {
                std::ostringstream stream;
                stream << "exact gpu rebuilt sparse inputs on worker"
                       << " chunk=(" << chunk.coord.x << "," << chunk.coord.y << "," << chunk.coord.z << ")";
                exactUploadDebugLog(stream.str());
            }
        }

        const std::uint32_t currentBuildVersion = chunk.exactGpuBuildVersion.load(std::memory_order_acquire);
        const std::uint32_t currentGenerationEpoch = chunk.generationEpoch.load(std::memory_order_acquire);
        const std::uint64_t currentInputVersion = chunk.exactGpuInputsVersion.load(std::memory_order_acquire);
        if (request.buildVersion != currentBuildVersion || request.generationEpoch != currentGenerationEpoch)
        {
            request.buildVersion = currentBuildVersion;
            request.generationEpoch = currentGenerationEpoch;
            request.inputVersion = currentInputVersion;
            request.rebuildVoxelInputs =
                chunk.exactGpuInputsDirty.load(std::memory_order_acquire) ||
                !chunk.exactGpuResident.load(std::memory_order_acquire) ||
                chunk.exactGpu.voxelBuffer == nullptr;
        }
        if (chunk.exactGpu.readyFenceValue != 0 &&
            exactGpuContext_.completedFenceValue() < chunk.exactGpu.readyFenceValue)
        {
            chunk.exactGpuFenceDeferredCount.fetch_add(1, std::memory_order_relaxed);
            chunk.exactGpuLastFenceDeferredMicros.store(static_cast<long long>(steadyMicrosNow()),
                                                        std::memory_order_release);
            deferredRequests.push_back(std::move(request));
            continue;
        }
        const bool rebuildVoxelInputs =
            request.rebuildVoxelInputs ||
            chunk.exactGpuInputsDirty.load(std::memory_order_acquire) ||
            !chunk.exactGpuResident.load(std::memory_order_acquire) ||
            chunk.exactGpu.voxelBuffer == nullptr;

        const SteadyClock::time_point prepareStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
        const bool resourcesReady = ensureChunkExactGpuBuildResourcesLocked(chunk);
        if (benchmarkEnabled)
        {
            prepareMicros += static_cast<std::uint64_t>(
                std::chrono::duration_cast<std::chrono::microseconds>(SteadyClock::now() - prepareStart).count());
        }
        if (!resourcesReady ||
            chunk.exactGpu.voxelBuffer == nullptr ||
            chunk.exactGpu.haloBuffer == nullptr ||
            chunk.exactGpu.lightScratchBuffer == nullptr ||
            (rebuildVoxelInputs &&
             chunk.gpuExactSparseVoxelsReady &&
             !chunk.gpuExactSparseVoxels.empty() &&
             chunk.exactGpu.sparseVoxelBuffer == nullptr))
        {
            recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepareChunkResources);
            deferredRequests.push_front(std::move(request));
            break;
        }

        PreparedExactGpuBuild pending{};
        pending.chunk = request.chunk;
        pending.buildVersion = request.buildVersion;
        pending.generationEpoch = request.generationEpoch;
        pending.inputVersion = request.inputVersion;
        pending.rebuildVoxelInputs = rebuildVoxelInputs;
        pending.voxelInputMode = ExactGpuVoxelInputMode::None;
        if (rebuildVoxelInputs)
        {
            const bool preferDenseUpload =
                chunk.exactGpuPreferDenseUpload.load(std::memory_order_acquire) &&
                chunk.cpuDataResident.load(std::memory_order_acquire) &&
                !chunk.blocks.empty();
            pending.voxelInputMode = preferDenseUpload ? ExactGpuVoxelInputMode::DenseCpuUpload
                                                       : ExactGpuVoxelInputMode::SparseSynthStamp;
        }
        pending.tentativeScratchSliceIndex =
            freeExactGpuScratchSlices_[freeExactGpuScratchSlices_.size() - 1u - preparedBuilds.size()];
        preparedBuilds.push_back(std::move(pending));
    }

    if (!deferredRequests.empty())
    {
        std::lock_guard<std::mutex> lock(pendingExactGpuBuildMutex_);
        while (!deferredRequests.empty())
        {
            pendingExactGpuBuildQueue_.push_front(std::move(deferredRequests.back()));
            deferredRequests.pop_back();
        }
    }

    if (preparedBuilds.empty())
    {
        (void)exactGpuContext_.flush();
        recordSubmitStats(processedRequests);
        return;
    }

    std::unordered_map<glm::ivec2, std::uint32_t, ColumnHasher> stagedPageIndexByKey{};
    stagedPageIndexByKey.reserve(preparedBuilds.size() * 4u);
    std::vector<std::shared_ptr<const WorldgenPage>> stagedPages{};
    stagedPages.reserve(preparedBuilds.size() * 2u);
    std::vector<GpuExactDescriptorBuildParams> descriptorBuildParams{};
    descriptorBuildParams.reserve(preparedBuilds.size());
    std::vector<std::uint32_t> descriptorSkyLightValues{};
    descriptorSkyLightValues.reserve(preparedBuilds.size() * kExactChunkColumnCount);
    std::uint64_t exactUploadCursor = 0u;
    bool stagingBlockedOnDependencies = false;

    auto tryStageDescriptorInputs = [&](std::size_t buildIndex) -> bool
    {
        const std::size_t candidateBuildCount = buildIndex + 1u;
        const std::uint64_t requiredPrepassDescriptors =
            static_cast<std::uint64_t>(candidateBuildCount) *
            static_cast<std::uint64_t>(exactGpuContext_.exactPrepassDescriptorCountPerBuild());
        if (requiredPrepassDescriptors > exactGpuContext_.descriptorCapacityPerSubmission())
        {
            return false;
        }
        const std::uint64_t requiredEmitDescriptors =
            static_cast<std::uint64_t>(candidateBuildCount) *
            static_cast<std::uint64_t>(exactGpuContext_.exactEmitInputDescriptorCountPerBuild());
        if (requiredEmitDescriptors > exactGpuContext_.descriptorCapacityPerSubmission())
        {
            return false;
        }

        PreparedExactGpuBuild& pending = preparedBuilds[buildIndex];
        Chunk& chunk = *pending.chunk;
        const ExactGpuWorldgenPageWindow pageWindow = exactGpuWorldgenPageWindowForChunk(chunk.coord);
        std::array<std::shared_ptr<const WorldgenPage>, 4> resolvedPages{};
        std::array<std::uint32_t, 4> resolvedPageIndices{};
        std::array<bool, 4> pageIsNew{};

        std::uint64_t candidateCursor = exactUploadCursor;
        for (std::size_t pageSlot = 0; pageSlot < pageWindow.pageKeys.size(); ++pageSlot)
        {
            const glm::ivec2& pageKey = pageWindow.pageKeys[pageSlot];
            auto it = stagedPageIndexByKey.find(pageKey);
            if (it != stagedPageIndexByKey.end())
            {
                resolvedPageIndices[pageSlot] = it->second;
                continue;
            }

            resolvedPages[pageSlot] = tryGetReadyWorldgenPage(pageKey);
            if (!resolvedPages[pageSlot])
            {
                const bool prioritizeDependencies = shouldPrioritizeExactGpuBuild(chunk);
                const DependencyPriority dependencyPriority =
                    prioritizeDependencies ? DependencyPriority::Critical : DependencyPriority::Visible;
                const JobServiceClass dependencyServiceClass =
                    prioritizeDependencies ? JobServiceClass::InitialVisible : JobServiceClass::Standard;
                (void)requestExactGpuPageWindowDependencies(chunk.coord,
                                                            dependencyPriority,
                                                            dependencyServiceClass);
                stagingBlockedOnDependencies = true;
                return false;
            }

            const std::uint64_t pageBytes =
                static_cast<std::uint64_t>(resolvedPages[pageSlot]->gpuColumns.size()) * sizeof(GpuWorldgenPageColumn);
            if (!appendExactUploadBytes(candidateCursor, pageBytes, alignof(GpuWorldgenPageColumn)))
            {
                return false;
            }
            pageIsNew[pageSlot] = true;
        }

        if (!appendExactUploadBytes(candidateCursor,
                                    sizeof(GpuExactDescriptorBuildParams),
                                    alignof(GpuExactDescriptorBuildParams)) ||
            !appendExactUploadBytes(candidateCursor,
                                    static_cast<std::uint64_t>(kExactChunkColumnCount) * sizeof(std::uint32_t),
                                    alignof(std::uint32_t)))
        {
            return false;
        }

        const std::uint32_t sparseVoxelCount =
            static_cast<std::uint32_t>(chunk.gpuExactSparseVoxels.size());
        const bool runSparseSynthStamp = pending.voxelInputMode == ExactGpuVoxelInputMode::SparseSynthStamp;
        if (runSparseSynthStamp && sparseVoxelCount > 0u)
        {
            const std::uint64_t sparseBytes =
                static_cast<std::uint64_t>(sparseVoxelCount) * sizeof(GpuExactSparseVoxel);
            if (!appendExactUploadBytes(candidateCursor, sparseBytes, alignof(GpuExactSparseVoxel)))
            {
                const std::uint64_t denseVoxelBytes =
                    static_cast<std::uint64_t>(kChunkSizeX * kChunkSizeY * kChunkSizeZ) * sizeof(std::uint32_t);
                if (chunk.cpuDataResident.load(std::memory_order_acquire) &&
                    !chunk.blocks.empty() &&
                    appendExactUploadBytes(candidateCursor, denseVoxelBytes, alignof(std::uint32_t)))
                {
                    pending.voxelInputMode = ExactGpuVoxelInputMode::DenseCpuUpload;
                    if (exactUploadDebugLoggingEnabled())
                    {
                        std::ostringstream stream;
                        stream << "exact gpu dense voxel upload fallback"
                               << " chunk=(" << chunk.coord.x << "," << chunk.coord.y << "," << chunk.coord.z << ")"
                               << " sparseVoxels=" << sparseVoxelCount
                               << " denseBytes=" << denseVoxelBytes
                               << " uploadBudget=" << exactUploadBudget;
                        exactUploadDebugLog(stream.str());
                    }
                }
                else
                {
                    return false;
                }
            }
        }
        else if (pending.voxelInputMode == ExactGpuVoxelInputMode::DenseCpuUpload)
        {
            const std::uint64_t denseVoxelBytes =
                static_cast<std::uint64_t>(kChunkSizeX * kChunkSizeY * kChunkSizeZ) * sizeof(std::uint32_t);
            if (!appendExactUploadBytes(candidateCursor, denseVoxelBytes, alignof(std::uint32_t)))
            {
                return false;
            }
        }
        if (!appendExactUploadBytes(candidateCursor,
                                    exactBuildRecordUploadBytes(buildIndex + 1u),
                                    alignof(FarLodGpuContext::ExactChunkAllocationRecord)))
        {
            return false;
        }
        if (!appendExactUploadBytes(candidateCursor,
                                    exactPrepassRecordUploadBytes(buildIndex + 1u),
                                    alignof(GpuExactPrepassRecord)))
        {
            return false;
        }
        if (!fitsPrepassPhaseResources(buildIndex + 1u) ||
            !fitsEmitPhaseResources(buildIndex + 1u))
        {
            return false;
        }

        for (std::size_t pageSlot = 0; pageSlot < pageWindow.pageKeys.size(); ++pageSlot)
        {
            if (!pageIsNew[pageSlot])
            {
                continue;
            }

            const std::uint32_t pageIndex = static_cast<std::uint32_t>(stagedPages.size());
            stagedPageIndexByKey.emplace(pageWindow.pageKeys[pageSlot], pageIndex);
            stagedPages.push_back(resolvedPages[pageSlot]);
            resolvedPageIndices[pageSlot] = pageIndex;
        }

        const std::uint32_t skyLightOffset = static_cast<std::uint32_t>(descriptorSkyLightValues.size());
        descriptorBuildParams.push_back(GpuExactDescriptorBuildParams{
            chunk.coord.x * kChunkSizeX,
            chunk.coord.z * kChunkSizeZ,
            chunk.minWorldY,
            pageWindow.minPageKey.x * WorldgenPage::kSize,
            pageWindow.minPageKey.y * WorldgenPage::kSize,
            resolvedPageIndices[0],
            resolvedPageIndices[1],
            resolvedPageIndices[2],
            resolvedPageIndices[3],
            skyLightOffset,
            pending.tentativeScratchSliceIndex * kExactChunkColumnCount,
            0u});
        for (std::uint8_t skyLight : chunk.skyLightFromAboveCache)
        {
            descriptorSkyLightValues.push_back(static_cast<std::uint32_t>(skyLight));
        }
        exactUploadCursor = candidateCursor;
        return true;
    };

    std::size_t acceptedBuildCount = 0u;
    for (; acceptedBuildCount < preparedBuilds.size(); ++acceptedBuildCount)
    {
        if (!tryStageDescriptorInputs(acceptedBuildCount))
        {
            break;
        }
    }
    if (acceptedBuildCount < preparedBuilds.size())
    {
        if (!stagingBlockedOnDependencies)
        {
            exactGpuSubmitBudgetRejects_.fetch_add(
                static_cast<int>(preparedBuilds.size() - acceptedBuildCount),
                std::memory_order_relaxed);
        }
        requeueRemainingPreparedBuilds(acceptedBuildCount);
    }
    if (preparedBuilds.empty())
    {
        (void)exactGpuContext_.flush();
        recordSubmitStats(processedRequests);
        return;
    }

    std::vector<FarLodGpuContext::ScratchAllocation> prepassOwnedUploads{};
    prepassOwnedUploads.reserve(4u + preparedBuilds.size());
    std::vector<FarLodGpuContext::ScratchAllocation> prepassOwnedReadbacks{};
    prepassOwnedReadbacks.reserve(1u);
    FarLodGpuContext::ScratchAllocation pageUpload{};
    if (!stagedPages.empty())
    {
        const std::uint64_t pageBytes =
            static_cast<std::uint64_t>(stagedPages.size()) * WorldgenPage::kColumnCount * sizeof(GpuWorldgenPageColumn);
        pageUpload = exactGpuContext_.allocateUpload(pageBytes, alignof(GpuWorldgenPageColumn));
        if (pageUpload.resource == nullptr || pageUpload.cpuPtr == nullptr)
        {
            recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepassPageUploadAlloc);
            requeueRemainingPreparedBuilds(0);
            discardOpenSubmission();
            recordSubmitStats(processedRequests);
            return;
        }
        prepassOwnedUploads.push_back(pageUpload);

        std::byte* writePtr = pageUpload.cpuPtr;
        for (const std::shared_ptr<const WorldgenPage>& page : stagedPages)
        {
            std::memcpy(writePtr,
                        page->gpuColumns.data(),
                        page->gpuColumns.size() * sizeof(GpuWorldgenPageColumn));
            writePtr += page->gpuColumns.size() * sizeof(GpuWorldgenPageColumn);
        }
    }

    FarLodGpuContext::ScratchAllocation descriptorBuildUpload{};
    if (!descriptorBuildParams.empty())
    {
        const std::uint64_t buildBytes =
            static_cast<std::uint64_t>(descriptorBuildParams.size()) * sizeof(GpuExactDescriptorBuildParams);
        descriptorBuildUpload =
            exactGpuContext_.allocateUpload(buildBytes, alignof(GpuExactDescriptorBuildParams));
        if (descriptorBuildUpload.resource == nullptr || descriptorBuildUpload.cpuPtr == nullptr)
        {
            recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepassDescriptorUploadAlloc);
            requeueRemainingPreparedBuilds(0);
            discardOpenSubmission();
            recordSubmitStats(processedRequests);
            return;
        }
        prepassOwnedUploads.push_back(descriptorBuildUpload);

        std::memcpy(descriptorBuildUpload.cpuPtr,
                    descriptorBuildParams.data(),
                    static_cast<std::size_t>(buildBytes));
    }

    FarLodGpuContext::ScratchAllocation descriptorSkyLightUpload{};
    if (!descriptorSkyLightValues.empty())
    {
        const std::uint64_t skyLightBytes =
            static_cast<std::uint64_t>(descriptorSkyLightValues.size()) * sizeof(std::uint32_t);
        descriptorSkyLightUpload = exactGpuContext_.allocateUpload(skyLightBytes, alignof(std::uint32_t));
        if (descriptorSkyLightUpload.resource == nullptr || descriptorSkyLightUpload.cpuPtr == nullptr)
        {
            recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepassSkyLightUploadAlloc);
            requeueRemainingPreparedBuilds(0);
            discardOpenSubmission();
            recordSubmitStats(processedRequests);
            return;
        }
        prepassOwnedUploads.push_back(descriptorSkyLightUpload);

        std::memcpy(descriptorSkyLightUpload.cpuPtr,
                    descriptorSkyLightValues.data(),
                    static_cast<std::size_t>(skyLightBytes));
    }

    for (std::size_t buildIndex = 0; buildIndex < preparedBuilds.size(); ++buildIndex)
    {
        PreparedExactGpuBuild& pending = preparedBuilds[buildIndex];
        Chunk& chunk = *pending.chunk;
        if (pending.voxelInputMode == ExactGpuVoxelInputMode::DenseCpuUpload)
        {
            const std::uint64_t voxelBytes =
                static_cast<std::uint64_t>(kChunkSizeX * kChunkSizeY * kChunkSizeZ) * sizeof(std::uint32_t);
            const FarLodGpuContext::ScratchAllocation voxelUpload =
                exactGpuContext_.allocateUpload(voxelBytes, alignof(std::uint32_t));
            if (voxelUpload.resource == nullptr || voxelUpload.cpuPtr == nullptr)
            {
                recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepassVoxelUploadAlloc);
                requeueRemainingPreparedBuilds(0);
                discardOpenSubmission();
                recordSubmitStats(processedRequests);
                return;
            }
            prepassOwnedUploads.push_back(voxelUpload);

            {
                std::lock_guard<std::mutex> lock(chunk.meshMutex);
                std::uint32_t* writePtr = reinterpret_cast<std::uint32_t*>(voxelUpload.cpuPtr);
                const std::size_t voxelCount = chunk.blocks.size();
                for (std::size_t i = 0; i < voxelCount; ++i)
                {
                    writePtr[i] = static_cast<std::uint32_t>(chunk.blocks[i]) & 0xFFu;
                }
            }

            if (chunk.exactGpu.voxelState != D3D12_RESOURCE_STATE_COPY_DEST)
            {
                exactGpuContext_.transition(chunk.exactGpu.voxelBuffer.Get(),
                                            chunk.exactGpu.voxelState,
                                            D3D12_RESOURCE_STATE_COPY_DEST);
                chunk.exactGpu.voxelState = D3D12_RESOURCE_STATE_COPY_DEST;
            }
            exactGpuContext_.copyBuffer(chunk.exactGpu.voxelBuffer.Get(),
                                        0,
                                        voxelUpload.resource,
                                        voxelUpload.offset,
                                        voxelBytes);
            exactGpuContext_.transition(chunk.exactGpu.voxelBuffer.Get(),
                                        chunk.exactGpu.voxelState,
                                        D3D12_RESOURCE_STATE_COMMON);
            chunk.exactGpu.voxelState = D3D12_RESOURCE_STATE_COMMON;
            continue;
        }

        if (pending.voxelInputMode != ExactGpuVoxelInputMode::SparseSynthStamp)
        {
            continue;
        }

        const std::uint32_t sparseVoxelCount =
            static_cast<std::uint32_t>(chunk.gpuExactSparseVoxels.size());
        if (sparseVoxelCount > 0 && chunk.exactGpu.sparseVoxelBuffer != nullptr)
        {
            const std::uint64_t sparseBytes =
                static_cast<std::uint64_t>(sparseVoxelCount) * sizeof(GpuExactSparseVoxel);
            const FarLodGpuContext::ScratchAllocation sparseUpload =
                exactGpuContext_.allocateUpload(sparseBytes, alignof(GpuExactSparseVoxel));
            if (sparseUpload.resource == nullptr || sparseUpload.cpuPtr == nullptr)
            {
                recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepassSparseUploadAlloc);
                requeueRemainingPreparedBuilds(0);
                discardOpenSubmission();
                recordSubmitStats(processedRequests);
                return;
            }
            prepassOwnedUploads.push_back(sparseUpload);

            std::memcpy(sparseUpload.cpuPtr,
                        chunk.gpuExactSparseVoxels.data(),
                        static_cast<std::size_t>(sparseBytes));
            if (chunk.exactGpu.sparseVoxelState != D3D12_RESOURCE_STATE_COPY_DEST)
            {
                exactGpuContext_.transition(chunk.exactGpu.sparseVoxelBuffer.Get(),
                                            chunk.exactGpu.sparseVoxelState,
                                            D3D12_RESOURCE_STATE_COPY_DEST);
                chunk.exactGpu.sparseVoxelState = D3D12_RESOURCE_STATE_COPY_DEST;
            }
            exactGpuContext_.copyBuffer(chunk.exactGpu.sparseVoxelBuffer.Get(),
                                        0,
                                        sparseUpload.resource,
                                        sparseUpload.offset,
                                        sparseBytes);
            exactGpuContext_.transition(chunk.exactGpu.sparseVoxelBuffer.Get(),
                                        chunk.exactGpu.sparseVoxelState,
                                        D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
            chunk.exactGpu.sparseVoxelState = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
        }
    }
    stagedBuilds.reserve(preparedBuilds.size());
    std::vector<std::uint32_t> prepassScratchSliceIndices{};
    prepassScratchSliceIndices.reserve(preparedBuilds.size());
    for (PreparedExactGpuBuild& prepared : preparedBuilds)
    {
        PendingExactGpuBuild pending{};
        pending.chunk = prepared.chunk;
        pending.buildVersion = prepared.buildVersion;
        pending.generationEpoch = prepared.generationEpoch;
        pending.inputVersion = prepared.inputVersion;
        pending.rebuildVoxelInputs = prepared.rebuildVoxelInputs;
        pending.voxelInputMode = prepared.voxelInputMode;
        pending.scratchSliceIndex = freeExactGpuScratchSlices_.back();
        freeExactGpuScratchSlices_.pop_back();
        Chunk& chunk = *pending.chunk;
        chunk.exactGpuBuildQueued.store(false, std::memory_order_release);
        chunk.exactGpuBuildInFlight.store(true, std::memory_order_release);
        refreshPendingExactGpuBuildCount(chunk);
        storeFirstBenchmarkTimestamp(chunk.uploadStartTimestampMicros, steadyMicrosNow());
        updateExactGpuChunkAllocationRecord(pending,
                                            0u,
                                            0u,
                                            kExactChunkAllocationPhasePrepassSubmitted);
        prepassScratchSliceIndices.push_back(pending.scratchSliceIndex);
        stagedBuilds.push_back(std::move(pending));
    }
    preparedBuilds.clear();

    if (!syncExactGpuChunkAllocationRecords(prepassScratchSliceIndices, prepassOwnedUploads))
    {
        recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepassAllocationRecordSync);
        requeueRemainingStagedBuilds(0);
        discardOpenSubmission();
        recordSubmitStats(processedRequests);
        return;
    }

    if (!descriptorBuildParams.empty())
    {
        exactGpuContext_.dispatchExactDescriptorGen(
            globalSeaLevel_,
            static_cast<std::uint32_t>(descriptorBuildParams.size()),
            pageUpload.resource->GetGPUVirtualAddress() + pageUpload.offset,
            descriptorBuildUpload.resource->GetGPUVirtualAddress() + descriptorBuildUpload.offset,
            descriptorSkyLightUpload.resource->GetGPUVirtualAddress() + descriptorSkyLightUpload.offset);
        exactGpuContext_.uavBarrier(exactGpuContext_.exactDescriptorScratchBuffer());
        exactGpuContext_.transitionExactDescriptorScratch(D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
    }

    if (exactGpuBlockUvBufferState_ != D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE)
    {
        exactGpuContext_.transition(exactGpuBlockUvBuffer_.Get(),
                                    exactGpuBlockUvBufferState_,
                                    D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
        exactGpuBlockUvBufferState_ = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
    }
    if (exactGpuEmptyVoxelBufferState_ != D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE)
    {
        exactGpuContext_.transition(exactGpuEmptyVoxelBuffer_.Get(),
                                    exactGpuEmptyVoxelBufferState_,
                                    D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
        exactGpuEmptyVoxelBufferState_ = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
    }
    const std::uint32_t batchBuildCount = static_cast<std::uint32_t>(stagedBuilds.size());
    submitBatchBuilds = static_cast<int>(std::min<std::uint32_t>(
        batchBuildCount,
        static_cast<std::uint32_t>(std::numeric_limits<int>::max())));
    std::vector<GpuExactPrepassRecord> prepassRecords{};
    prepassRecords.reserve(stagedBuilds.size());
    std::vector<std::array<Chunk*, 6>> neighborChunksToRestoreByBuild(stagedBuilds.size());
    std::vector<std::size_t> neighborRestoreCounts(stagedBuilds.size(), 0u);
    const std::uint64_t completedExactGpuFenceValue = exactGpuContext_.completedFenceValue();
    std::uint32_t maxSparseVoxelGroupsAcrossBatch = 0u;
    constexpr std::uint32_t kClosedNeighborMask = 0u;

    auto restoreResolvedNeighborStates = [&]()
    {
        for (std::size_t buildIndex = 0; buildIndex < neighborChunksToRestoreByBuild.size(); ++buildIndex)
        {
            restoreExactGpuNeighborStates(neighborChunksToRestoreByBuild[buildIndex],
                                          neighborRestoreCounts[buildIndex]);
            neighborRestoreCounts[buildIndex] = 0u;
        }
    };

    for (std::size_t buildIndex = 0; buildIndex < stagedBuilds.size(); ++buildIndex)
    {
        PendingExactGpuBuild& pending = stagedBuilds[buildIndex];
        Chunk& chunk = *pending.chunk;
        std::array<ID3D12Resource*, 6> neighborBuffers{};
        std::uint32_t resolvedNeighborMask = 0u;
        std::array<Chunk*, 6> neighborChunksToRestore{};
        std::size_t neighborRestoreCount = 0;
        resolveExactGpuNeighborState(chunk,
                                     completedExactGpuFenceValue,
                                     neighborBuffers,
                                     resolvedNeighborMask,
                                     pending.pendingNeighborMask,
                                     neighborChunksToRestore,
                                     neighborRestoreCount);
        neighborChunksToRestoreByBuild[buildIndex] = neighborChunksToRestore;
        neighborRestoreCounts[buildIndex] = neighborRestoreCount;

        const bool runSparseSynthStamp = pending.voxelInputMode == ExactGpuVoxelInputMode::SparseSynthStamp;
        const std::uint32_t sparseVoxelCount = runSparseSynthStamp
            ? static_cast<std::uint32_t>(chunk.gpuExactSparseVoxels.size())
            : 0u;
        const FarLodGpuContext::ExactPrepassDescriptorIndices descriptorIndices =
            exactGpuContext_.writeExactPrepassInputDescriptors(chunk.exactGpu.voxelBuffer.Get(),
                                                               chunk.exactGpu.haloBuffer.Get(),
                                                               chunk.exactGpu.lightScratchBuffer.Get(),
                                                               chunk.exactGpu.seamBuffer.Get(),
                                                               chunk.exactGpu.sparseVoxelBuffer.Get(),
                                                               sparseVoxelCount,
                                                               neighborBuffers);
        if (!descriptorIndices.valid())
        {
            recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepassDescriptorBind);
            restoreResolvedNeighborStates();
            requeueRemainingStagedBuilds(0);
            discardOpenSubmission();
            recordSubmitStats(processedRequests);
            return;
        }

        maxSparseVoxelGroupsAcrossBatch = std::max(maxSparseVoxelGroupsAcrossBatch, (sparseVoxelCount + 63u) / 64u);
        prepassRecords.push_back(GpuExactPrepassRecord{
            chunk.coord.x * kChunkSizeX,
            chunk.minWorldY,
            chunk.coord.z * kChunkSizeZ,
            pending.scratchSliceIndex,
            pending.scratchSliceIndex * kExactChunkColumnCount,
            runSparseSynthStamp ? 1u : 0u,
            sparseVoxelCount,
            resolvedNeighborMask,
            kClosedNeighborMask,
            pending.pendingNeighborMask,
            descriptorIndices.centerVoxelSrvDescriptorIndex,
            descriptorIndices.centerVoxelUavDescriptorIndex,
            descriptorIndices.haloVoxelSrvDescriptorIndex,
            descriptorIndices.haloVoxelUavDescriptorIndex,
            descriptorIndices.lightScratchVoxelSrvDescriptorIndex,
            descriptorIndices.lightScratchVoxelUavDescriptorIndex,
            descriptorIndices.sparseVoxelSrvDescriptorIndex,
            descriptorIndices.seamVoxelUavDescriptorIndex,
            descriptorIndices.neighborSeamSrvDescriptorIndices[0],
            descriptorIndices.neighborSeamSrvDescriptorIndices[1],
            descriptorIndices.neighborSeamSrvDescriptorIndices[2],
            descriptorIndices.neighborSeamSrvDescriptorIndices[3],
            descriptorIndices.neighborSeamSrvDescriptorIndices[4],
            descriptorIndices.neighborSeamSrvDescriptorIndices[5],
            0u});
    }

    const std::uint64_t prepassRecordBytes =
        static_cast<std::uint64_t>(prepassRecords.size()) * sizeof(GpuExactPrepassRecord);
    const FarLodGpuContext::ScratchAllocation prepassRecordUpload =
        exactGpuContext_.allocateUpload(prepassRecordBytes, alignof(GpuExactPrepassRecord));
    if (prepassRecordUpload.resource == nullptr || prepassRecordUpload.cpuPtr == nullptr)
    {
        recordExactGpuResourceFailure(ExactGpuResourceFailureReason::PrepassRecordUploadAlloc);
        restoreResolvedNeighborStates();
        requeueRemainingStagedBuilds(0);
        discardOpenSubmission();
        recordSubmitStats(processedRequests);
        return;
    }
    prepassOwnedUploads.push_back(prepassRecordUpload);
    std::memcpy(prepassRecordUpload.cpuPtr,
                prepassRecords.data(),
                static_cast<std::size_t>(prepassRecordBytes));

    for (PendingExactGpuBuild& pending : stagedBuilds)
    {
        Chunk& chunk = *pending.chunk;
        if (pending.voxelInputMode == ExactGpuVoxelInputMode::SparseSynthStamp &&
            chunk.exactGpu.voxelState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS)
        {
            exactGpuContext_.transition(chunk.exactGpu.voxelBuffer.Get(),
                                        chunk.exactGpu.voxelState,
                                        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
            chunk.exactGpu.voxelState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
        }
        if (chunk.exactGpu.haloState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS)
        {
            exactGpuContext_.transition(chunk.exactGpu.haloBuffer.Get(),
                                        chunk.exactGpu.haloState,
                                        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
            chunk.exactGpu.haloState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
        }
    }

    exactGpuContext_.beginExactTimingBatch();
    exactGpuContext_.markExactTimingBegin(FarLodGpuContext::ExactTimingPass::Synth);
    exactGpuContext_.dispatchExactSynthBatch(batchBuildCount, prepassRecordUpload.gpuAddress);
    exactGpuContext_.markExactTimingEnd();
    exactGpuContext_.uavBarrier(nullptr);

    exactGpuContext_.markExactTimingBegin(FarLodGpuContext::ExactTimingPass::Stamp);
    exactGpuContext_.dispatchExactStampBatch(batchBuildCount,
                                             maxSparseVoxelGroupsAcrossBatch,
                                             prepassRecordUpload.gpuAddress);
    exactGpuContext_.markExactTimingEnd();
    exactGpuContext_.uavBarrier(nullptr);

    exactGpuContext_.dispatchExactHaloCacheBatch(batchBuildCount, prepassRecordUpload.gpuAddress);
    exactGpuContext_.uavBarrier(nullptr);

    for (PendingExactGpuBuild& pending : stagedBuilds)
    {
        Chunk& chunk = *pending.chunk;
        if (chunk.exactGpu.haloState != D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE)
        {
            exactGpuContext_.transition(chunk.exactGpu.haloBuffer.Get(),
                                        chunk.exactGpu.haloState,
                                        D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
            chunk.exactGpu.haloState = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
        }
    }
    restoreResolvedNeighborStates();

    for (PendingExactGpuBuild& pending : stagedBuilds)
    {
        Chunk& chunk = *pending.chunk;
        if (chunk.exactGpu.voxelState != D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE)
        {
            exactGpuContext_.transition(chunk.exactGpu.voxelBuffer.Get(),
                                        chunk.exactGpu.voxelState,
                                        D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
            chunk.exactGpu.voxelState = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
        }
        if (chunk.exactGpu.lightScratchState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS)
        {
            exactGpuContext_.transition(chunk.exactGpu.lightScratchBuffer.Get(),
                                        chunk.exactGpu.lightScratchState,
                                        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
            chunk.exactGpu.lightScratchState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
        }
    }

    exactGpuContext_.markExactTimingBegin(FarLodGpuContext::ExactTimingPass::Light);
    exactGpuContext_.dispatchExactLightBatch(batchBuildCount,
                                             prepassRecordUpload.gpuAddress,
                                             kExactGpuLightPropagationPassCount);
    exactGpuContext_.markExactTimingEnd();
    exactGpuContext_.uavBarrier(nullptr);

    for (PendingExactGpuBuild& pending : stagedBuilds)
    {
        Chunk& chunk = *pending.chunk;
        if (chunk.exactGpu.lightScratchState != D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE)
        {
            exactGpuContext_.transition(chunk.exactGpu.lightScratchBuffer.Get(),
                                        chunk.exactGpu.lightScratchState,
                                        D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE);
            chunk.exactGpu.lightScratchState = D3D12_RESOURCE_STATE_NON_PIXEL_SHADER_RESOURCE;
        }
        if (chunk.exactGpu.seamState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS)
        {
            exactGpuContext_.transition(chunk.exactGpu.seamBuffer.Get(),
                                        chunk.exactGpu.seamState,
                                        D3D12_RESOURCE_STATE_UNORDERED_ACCESS);
            chunk.exactGpu.seamState = D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
        }
    }

    exactGpuContext_.dispatchExactSeamExportBatch(batchBuildCount, prepassRecordUpload.gpuAddress);
    exactGpuContext_.uavBarrier(nullptr);

    for (PendingExactGpuBuild& pending : stagedBuilds)
    {
        Chunk& chunk = *pending.chunk;
        if (chunk.exactGpu.seamState != D3D12_RESOURCE_STATE_COMMON)
        {
            exactGpuContext_.transition(chunk.exactGpu.seamBuffer.Get(),
                                        chunk.exactGpu.seamState,
                                        D3D12_RESOURCE_STATE_COMMON);
            chunk.exactGpu.seamState = D3D12_RESOURCE_STATE_COMMON;
        }
        std::swap(chunk.exactGpu.voxelBuffer, chunk.exactGpu.lightScratchBuffer);
        std::swap(chunk.exactGpu.voxelState, chunk.exactGpu.lightScratchState);
    }

    exactGpuContext_.markExactTimingBegin(FarLodGpuContext::ExactTimingPass::FaceCount);
    exactGpuContext_.dispatchExactFaceCountBatch(batchBuildCount, prepassRecordUpload.gpuAddress);
    exactGpuContext_.markExactTimingEnd();
    exactGpuContext_.uavBarrier(nullptr);

    exactGpuContext_.markExactTimingBegin(FarLodGpuContext::ExactTimingPass::FacePrefix);
    exactGpuContext_.dispatchExactFacePrefixBatch(batchBuildCount, prepassRecordUpload.gpuAddress);
    exactGpuContext_.markExactTimingEnd();
    exactGpuContext_.uavBarrier(nullptr);

    const FarLodGpuContext::ExactFaceTotalsReadback prepassFaceTotalsReadback =
        exactGpuContext_.queueExactFaceTotalsReadback(prepassScratchSliceIndices);
    if (prepassFaceTotalsReadback.allocation.resource == nullptr ||
        prepassFaceTotalsReadback.allocation.cpuPtr == nullptr ||
        prepassFaceTotalsReadback.buildCount != prepassScratchSliceIndices.size())
    {
        exactGpuBuildReadbackFailures_.fetch_add(1, std::memory_order_relaxed);
        requeueRemainingStagedBuilds(0);
        discardOpenSubmission();
        recordSubmitStats(processedRequests);
        return;
    }
    prepassOwnedReadbacks.push_back(prepassFaceTotalsReadback.allocation);

    const FarLodGpuContext::FlushResult prepassFlushResult = exactGpuContext_.flush();
    exactLock.unlock();
    if (prepassFlushResult.fenceValue == 0)
    {
        requeueRemainingStagedBuilds(0);
        recordSubmitStats(processedRequests);
        return;
    }
    PendingExactGpuBatch batch{};
    batch.builds = std::move(stagedBuilds);
    batch.phase = ExactGpuBatchPhase::PrepassSubmitted;
    batch.phaseEnteredMicros = steadyMicrosNow();
    batch.reservationBatchId = prepassFlushResult.fenceValue;
    batch.prepassResources.fenceValue = prepassFlushResult.fenceValue;
    batch.prepassResources.submissionSlot = prepassFlushResult.submissionSlotIndex;
    batch.prepassResources.uploadAllocations = std::move(prepassOwnedUploads);
    batch.prepassResources.readbackAllocations = std::move(prepassOwnedReadbacks);
    batch.prepassFaceTotalsReadback = prepassFaceTotalsReadback;
    batch.prepassRequiredFaceCounts.resize(batch.builds.size(), 0u);
    {
        std::lock_guard<std::mutex> lock(pendingExactGpuBuildsMutex_);
        pendingExactGpuBatches_.push_back(std::move(batch));
    }
    recordSubmitStats(processedRequests);
}

void ChunkManager::Impl::commitPendingExactGpuBuilds()
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    std::lock_guard<std::mutex> pendingLock(pendingExactGpuBuildsMutex_);
    const UINT64 completedGpuFenceValue = exactGpuContext_.completedFenceValue();
    requestExactPageLifecycleSeals();
    drainSealRequestedExactPages();
    advanceExactPageResidencyQueues(completedGpuFenceValue);
    const FarLodGpuContext::ExactPassTimings latestExactTimings = exactGpuContext_.latestExactPassTimings();
    if (latestExactTimings.totalMs > 0.0)
    {
        FarLodGpuContext::ExactPassTimings combinedTimings = latestExactTimings;
        if (pendingExactGpuPrepassTimingsValid_)
        {
            combinedTimings.synthMs += pendingExactGpuPrepassTimings_.synthMs;
            combinedTimings.stampMs += pendingExactGpuPrepassTimings_.stampMs;
            combinedTimings.lightMs += pendingExactGpuPrepassTimings_.lightMs;
            combinedTimings.faceCountMs += pendingExactGpuPrepassTimings_.faceCountMs;
            combinedTimings.facePrefixMs += pendingExactGpuPrepassTimings_.facePrefixMs;
            combinedTimings.allocateMs += pendingExactGpuPrepassTimings_.allocateMs;
            combinedTimings.faceEmitMs += pendingExactGpuPrepassTimings_.faceEmitMs;
            combinedTimings.totalMs += pendingExactGpuPrepassTimings_.totalMs;
            pendingExactGpuPrepassTimingsValid_ = false;
        }
        if (benchmarkEnabled)
        {
            const auto toMicros = [](double milliseconds) -> std::uint64_t
            {
                return static_cast<std::uint64_t>(std::max(0.0, milliseconds) * 1000.0);
            };
            benchmarkMetrics_.exactGpuSynthStage.recordMicros(toMicros(combinedTimings.synthMs));
            benchmarkMetrics_.exactGpuStampStage.recordMicros(toMicros(combinedTimings.stampMs));
            benchmarkMetrics_.exactGpuLightStage.recordMicros(toMicros(combinedTimings.lightMs));
            benchmarkMetrics_.exactGpuFaceCountStage.recordMicros(toMicros(combinedTimings.faceCountMs));
            benchmarkMetrics_.exactGpuFacePrefixStage.recordMicros(toMicros(combinedTimings.facePrefixMs));
            benchmarkMetrics_.exactGpuAllocateStage.recordMicros(toMicros(combinedTimings.allocateMs));
            benchmarkMetrics_.exactGpuFaceEmitStage.recordMicros(toMicros(combinedTimings.faceEmitMs));
            benchmarkMetrics_.exactGpuTotalStage.recordMicros(toMicros(combinedTimings.totalMs));
        }
        std::lock_guard<std::mutex> statsLock(exactGpuStatsMutex_);
        lastExactGpuPassTimings_ = combinedTimings;
    }
    if (!pendingExactGpuBatches_.empty())
    {
        const auto releaseExactGpuScratch = [](Chunk& chunk)
        {
            chunk.exactGpu.reset();
        };
        const auto releaseExactGpuTransient = [](Chunk& chunk)
        {
            chunk.exactGpu.releaseTransient();
        };
        const auto finalizeBuild = [&](PendingExactGpuBuild& pending, bool keepOutstandingWork)
        {
            if (pending.chunk)
            {
                pending.chunk->exactGpuBuildInFlight.store(false, std::memory_order_release);
                refreshPendingExactGpuBuildCount(*pending.chunk);
                if (!keepOutstandingWork)
                {
                    pending.chunk->inFlight.fetch_sub(1, std::memory_order_relaxed);
                }
            }
        };
        const std::array<std::pair<glm::ivec3, std::uint8_t>, 6> seamNeighbors{{
            {glm::ivec3(1, 0, 0), kExactGpuSeamPosXBit},
            {glm::ivec3(-1, 0, 0), kExactGpuSeamNegXBit},
            {glm::ivec3(0, 1, 0), kExactGpuSeamPosYBit},
            {glm::ivec3(0, -1, 0), kExactGpuSeamNegYBit},
            {glm::ivec3(0, 0, 1), kExactGpuSeamPosZBit},
            {glm::ivec3(0, 0, -1), kExactGpuSeamNegZBit},
        }};
        const auto computeCurrentPendingNeighborMask = [&](const Chunk& targetChunk) -> std::uint8_t
        {
            std::uint8_t pendingMask = 0u;
            for (const auto& [offset, seamBit] : seamNeighbors)
            {
                const glm::ivec3 neighborCoord = targetChunk.coord + offset;
                bool ready = false;
                {
                    std::lock_guard<std::mutex> lock(chunksMutex);
                    const auto it = chunks_.find(neighborCoord);
                    if (it != chunks_.end() && it->second)
                    {
                        const Chunk& neighbor = *it->second;
                        ready = neighbor.exactGpu.seamBuffer != nullptr &&
                                neighbor.exactGpu.readyFenceValue != 0 &&
                                completedGpuFenceValue >= neighbor.exactGpu.readyFenceValue &&
                                !neighbor.exactGpuBuildInFlight.load(std::memory_order_acquire);
                    }
                }
                if (!ready)
                {
                    pendingMask |= seamBit;
                }
            }
            return pendingMask;
        };
        const auto queuePendingNeighborRefreshes = [&](const Chunk& committedChunk)
        {
            for (const auto& [offset, seamBit] : seamNeighbors)
            {
                const std::shared_ptr<Chunk> neighbor = getChunkShared(committedChunk.coord + offset);
                if (!neighbor)
                {
                    continue;
                }
                const std::uint8_t requiredPendingBit = oppositeExactGpuSeamBit(seamBit);
                const bool waitingOnCommittedFace =
                    (neighbor->exactGpuPendingNeighborMask.load(std::memory_order_acquire) & requiredPendingBit) != 0u;
                if (!waitingOnCommittedFace)
                {
                    continue;
                }
                const std::uint8_t currentPendingMask = computeCurrentPendingNeighborMask(*neighbor);
                if ((currentPendingMask & requiredPendingBit) != 0u)
                {
                    continue;
                }
                queueChunkForExactGpuBorderRefresh(neighbor);
            }
        };
        const auto releasePendingAllocation = [&](PendingExactGpuBuild& pending, bool emittedRecordWritten)
        {
            releasePendingExactBuildAllocation(pending, emittedRecordWritten);
        };
        const auto releaseScratchSlice = [&](PendingExactGpuBuild& pending)
        {
            if (pending.scratchSliceIndex != std::numeric_limits<std::uint32_t>::max())
            {
                freeExactGpuScratchSlices_.push_back(pending.scratchSliceIndex);
                clearExactGpuChunkAllocationRecord(pending.scratchSliceIndex);
                pending.scratchSliceIndex = std::numeric_limits<std::uint32_t>::max();
            }
        };
        const auto completionMatchesReservedAllocation = [&](const PendingExactGpuBuild& pending,
                                                             const FarLodGpuContext::ExactCompletionEntry& completion) -> bool
        {
            return completion.pageIndex == pending.allocation.pageIndex &&
                   completion.recordIndex == pending.allocation.recordIndex &&
                   static_cast<std::size_t>(completion.faceBase) == pending.allocation.faceOffset &&
                   completion.reservedFaceCapacity == pending.faceCapacity;
        };
        const auto requeueBuildRequest = [&](PendingExactGpuBuild& pending,
                                             bool emittedRecordWritten,
                                             bool prioritizeFront = true)
        {
            releaseScratchSlice(pending);
            if (!pending.chunk)
            {
                return;
            }
            releasePendingAllocation(pending, emittedRecordWritten);
            pending.chunk->exactGpuBuildQueued.store(true, std::memory_order_release);
            pending.chunk->exactGpuBuildInFlight.store(false, std::memory_order_release);
            refreshPendingExactGpuBuildCount(*pending.chunk);
            pending.chunk->exactGpuRequeueCount.fetch_add(1, std::memory_order_relaxed);
            pending.chunk->exactGpuLastRequeueMicros.store(static_cast<long long>(steadyMicrosNow()),
                                                           std::memory_order_release);
            std::lock_guard<std::mutex> lock(pendingExactGpuBuildMutex_);
            const bool front = prioritizeFront || shouldPrioritizeExactGpuBuild(*pending.chunk);
            ExactGpuBuildRequest request{
                pending.chunk,
                pending.buildVersion,
                pending.generationEpoch,
                pending.inputVersion,
                benchmarkMetrics_.isEnabled() ? steadyMicrosNow() : 0u,
                pending.rebuildVoxelInputs,
                front};
            if (front)
            {
                pendingExactGpuBuildQueue_.push_front(std::move(request));
            }
            else
            {
                pendingExactGpuBuildQueue_.push_back(std::move(request));
            }
            if (benchmarkMetrics_.isEnabled())
            {
                benchmarkMetrics_.exactGpuBuildQueueDepthEnqueue.record(
                    static_cast<std::uint64_t>(pendingExactGpuBuildQueue_.size()));
            }
        };
        const auto releaseBatchScratchSlices = [&](PendingExactGpuBatch& batch)
        {
            for (PendingExactGpuBuild& pending : batch.builds)
            {
                releaseScratchSlice(pending);
            }
        };
        const auto retireBatchPhaseResources = [&](ExactGpuBatchPhaseResources& resources)
        {
            if (resources.submissionSlot != std::numeric_limits<std::uint32_t>::max())
            {
                exactGpuContext_.releaseSubmissionSlot(resources.submissionSlot);
            }
            resources.reset();
        };
        const auto discardExactSubmission = [&]()
        {
            const FarLodGpuContext::FlushResult discardFlush = exactGpuContext_.flush();
            if (discardFlush.fenceValue != 0)
            {
                exactGpuContext_.waitForFence(discardFlush.fenceValue);
                exactGpuContext_.releaseSubmissionSlot(discardFlush.submissionSlotIndex);
            }
        };
        std::size_t writeIndex = 0u;
        std::size_t zeroFaceReadyCount = 0u;
        std::vector<glm::ivec3> zeroFaceReadySampleCoords{};
        zeroFaceReadySampleCoords.reserve(6u);
        for (std::size_t i = 0; i < pendingExactGpuBatches_.size(); ++i)
        {
            PendingExactGpuBatch& batch = pendingExactGpuBatches_[i];
            bool keepBatch = true;

            if (batch.phase == ExactGpuBatchPhase::PrepassSubmitted)
            {
                if (batch.prepassResources.fenceValue == 0 ||
                    completedGpuFenceValue < batch.prepassResources.fenceValue)
                {
                    if (writeIndex != i)
                    {
                        pendingExactGpuBatches_[writeIndex] = std::move(batch);
                    }
                    ++writeIndex;
                    continue;
                }

                if (batch.prepassRequiredFaceCounts.size() != batch.builds.size())
                {
                    batch.prepassRequiredFaceCounts.assign(batch.builds.size(), 0u);
                }
                const SteadyClock::time_point prepassReadbackStart =
                    benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
                const std::byte* faceTotalsBase = batch.prepassFaceTotalsReadback.allocation.cpuPtr;
                const bool hasFaceTotalReadback =
                    faceTotalsBase != nullptr &&
                    batch.prepassFaceTotalsReadback.buildCount >= batch.builds.size() &&
                    batch.prepassFaceTotalsReadback.strideBytes >= sizeof(std::uint32_t);
                if (!hasFaceTotalReadback && !batch.builds.empty())
                {
                    exactGpuBuildReadbackFailures_.fetch_add(1, std::memory_order_relaxed);
                }
                for (std::size_t buildOrdinal = 0; buildOrdinal < batch.builds.size(); ++buildOrdinal)
                {
                    std::uint32_t requiredFaceCount = 0u;
                    if (hasFaceTotalReadback)
                    {
                        std::memcpy(&requiredFaceCount,
                                    faceTotalsBase + buildOrdinal * batch.prepassFaceTotalsReadback.strideBytes,
                                    sizeof(requiredFaceCount));
                    }
                    batch.prepassRequiredFaceCounts[buildOrdinal] = requiredFaceCount;
                    batch.builds[buildOrdinal].requiredFaceCount = requiredFaceCount;
                }
                retireBatchPhaseResources(batch.prepassResources);
                batch.phase = ExactGpuBatchPhase::PrepassReadyForEmit;
                batch.phaseEnteredMicros = steadyMicrosNow();
            }

            if (keepBatch && batch.phase == ExactGpuBatchPhase::PrepassReadyForEmit)
            {
                // The CPU reservation + persistent exact page path never reopens resident pages.
                // Exact emit must target CPU-reserved ranges on pages that are still OpenWritable.
                std::size_t keptBuildCount = 0u;
                for (std::size_t buildIndex = 0; buildIndex < batch.builds.size(); ++buildIndex)
                {
                    PendingExactGpuBuild& pending = batch.builds[buildIndex];
                    if (!pending.chunk)
                    {
                        pending.allocation = {};
                        pending.faceCapacity = 0u;
                        if (keptBuildCount != buildIndex)
                        {
                            batch.builds[keptBuildCount] = std::move(pending);
                        }
                        ++keptBuildCount;
                        continue;
                    }

                    if (pending.requiredFaceCount == 0u)
                    {
                        pending.allocation = {};
                        pending.faceCapacity = 0u;
                        if (keptBuildCount != buildIndex)
                        {
                            batch.builds[keptBuildCount] = std::move(pending);
                        }
                        ++keptBuildCount;
                        continue;
                    }

                    if (pending.hasAllocation())
                    {
                        assert(pending.faceCapacity >= pending.requiredFaceCount);
                        assert(pending.allocation.recordIndex != kInvalidExactGpuDrawRecordIndex);
                        {
                            std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
                            assert(pending.allocation.pageIndex < bufferPages_.size());
                            const ChunkBufferPage& page = bufferPages_[pending.allocation.pageIndex];
                            (void)page;
                            assert(page.state == ChunkBufferPageState::OpenWritable);
                            assert(pending.allocation.recordIndex < page.recordCapacity);
                        }
                        if (keptBuildCount != buildIndex)
                        {
                            batch.builds[keptBuildCount] = std::move(pending);
                        }
                        ++keptBuildCount;
                        continue;
                    }

                    const ExactReservationResult reservationResult =
                        reserveExactOutputRange(pending.chunk->coord,
                                                pending.requiredFaceCount,
                                                batch.reservationBatchId,
                                                pending.allocation,
                                                pending.faceCapacity);
                    if (reservationResult != ExactReservationResult::Success)
                    {
                        if (reservationResult == ExactReservationResult::HardResourceFailure)
                        {
                            recordExactGpuResourceFailure(ExactGpuResourceFailureReason::EmitReservation);
                        }
                        else
                        {
                            exactGpuReservationTempExhaustions_.fetch_add(1, std::memory_order_relaxed);
                        }
                        requeueBuildRequest(pending, false, false);
                        finalizeBuild(pending,
                                      pending.chunk &&
                                          (pending.chunk->exactGpuBuildQueued.load(std::memory_order_acquire) ||
                                           pending.chunk->exactGpuBuildInFlight.load(std::memory_order_acquire)));
                        continue;
                    }

                    assert(pending.hasAllocation());
                    assert(pending.faceCapacity >= pending.requiredFaceCount);
                    assert(pending.allocation.recordIndex != kInvalidExactGpuDrawRecordIndex);
                    {
                        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
                        assert(pending.allocation.pageIndex < bufferPages_.size());
                        const ChunkBufferPage& page = bufferPages_[pending.allocation.pageIndex];
                        (void)page;
                        assert(page.state == ChunkBufferPageState::OpenWritable);
                        assert(pending.allocation.recordIndex < page.recordCapacity);
                    }
                    if (keptBuildCount != buildIndex)
                    {
                        batch.builds[keptBuildCount] = std::move(pending);
                    }
                    ++keptBuildCount;
                }
                batch.builds.resize(keptBuildCount);

                if (batch.builds.empty())
                {
                    keepBatch = false;
                    continue;
                }

                int readyForEmitBacklogBatches = 0;
                int readyForEmitBacklogBuilds = 0;
                int computeInFlightBeforeEmit = 0;
                if (benchmarkEnabled)
                {
                    std::size_t readyBatchCount = 0u;
                    std::size_t readyBuildCount = 0u;
                    for (const PendingExactGpuBatch& pendingBatch : pendingExactGpuBatches_)
                    {
                        if (pendingBatch.phase != ExactGpuBatchPhase::PrepassReadyForEmit)
                        {
                            continue;
                        }
                        ++readyBatchCount;
                        readyBuildCount += pendingBatch.builds.size();
                    }
                    const std::size_t currentBuildCount = batch.builds.size();
                    readyForEmitBacklogBatches = static_cast<int>(std::min<std::size_t>(
                        readyBatchCount > 0u ? (readyBatchCount - 1u) : 0u,
                        static_cast<std::size_t>(std::numeric_limits<int>::max())));
                    readyForEmitBacklogBuilds = static_cast<int>(std::min<std::size_t>(
                        readyBuildCount > currentBuildCount ? (readyBuildCount - currentBuildCount) : 0u,
                        static_cast<std::size_t>(std::numeric_limits<int>::max())));
                }

                // Command recording stays serialized, but page ownership is tracked by CPU
                // reservations plus per-page write fences rather than a global emit gate.
                std::unique_lock<std::mutex> exactLock(exactGpuExecutionMutex_);
                if (exactGpuContext_.begin())
                {
                    if (benchmarkEnabled)
                    {
                        computeInFlightBeforeEmit = static_cast<int>(std::min<std::uint32_t>(
                            exactGpuContext_.inFlightSubmissionCount(),
                            static_cast<std::uint32_t>(std::numeric_limits<int>::max())));
                    }
                    FarLodGpuContext::ScratchAllocation overflowCounterUpload =
                        exactGpuContext_.allocateUpload(sizeof(std::uint32_t), alignof(std::uint32_t));
                    if (overflowCounterUpload.resource == nullptr || overflowCounterUpload.cpuPtr == nullptr)
                    {
                        recordExactGpuResourceFailure(ExactGpuResourceFailureReason::EmitOverflowCounterUploadAlloc);
                        discardExactSubmission();
                    }
                    else if (!exactGpuContext_.clearExactOverflowCounter(overflowCounterUpload))
                    {
                        exactGpuBuildReadbackFailures_.fetch_add(1, std::memory_order_relaxed);
                        discardExactSubmission();
                    }
                    else
                    {
                        std::vector<FarLodGpuContext::ScratchAllocation> emitOwnedUploads{};
                        emitOwnedUploads.reserve(5u);
                        emitOwnedUploads.push_back(overflowCounterUpload);
                        exactGpuContext_.beginExactTimingBatch();

                        if (!batch.builds.empty())
                        {
                            ExactGpuEmitMetadataSyncDebugInfo emitMetadataSyncDebug{};
                            const SteadyClock::time_point emitMetadataSyncStart =
                                benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
                            if (!syncExactGpuEmitMetadata(emitOwnedUploads,
                                                          benchmarkEnabled ? &emitMetadataSyncDebug : nullptr))
                            {
                                recordExactGpuResourceFailure(ExactGpuResourceFailureReason::EmitMetadataSync);
                                exactGpuEmitMetadataSyncFailures_.fetch_add(1, std::memory_order_relaxed);
                                discardExactSubmission();
                                for (PendingExactGpuBuild& pending : batch.builds)
                                {
                                    requeueBuildRequest(pending, false);
                                }
                                keepBatch = false;
                            }
                            (void)emitMetadataSyncStart;
                            (void)emitMetadataSyncDebug;
                            if (keepBatch)
                            {
                                std::vector<std::uint32_t> emitScratchSliceIndices{};
                                emitScratchSliceIndices.reserve(batch.builds.size());
                                for (std::size_t buildIndex = 0; buildIndex < batch.builds.size(); ++buildIndex)
                                {
                                    PendingExactGpuBuild& pending = batch.builds[buildIndex];
                                    Chunk& chunk = *pending.chunk;
                                    const FarLodGpuContext::ExactBuildInputDescriptorIndices descriptorIndices =
                                        exactGpuContext_.writeExactBuildInputDescriptors(chunk.exactGpu.voxelBuffer.Get(),
                                                                                        chunk.exactGpu.haloBuffer.Get());
                                    if (descriptorIndices.centerVoxelSrvDescriptorIndex ==
                                            FarLodGpuContext::kInvalidDescriptorIndex ||
                                        descriptorIndices.haloSrvDescriptorIndex ==
                                            FarLodGpuContext::kInvalidDescriptorIndex)
                                    {
                                        recordExactGpuResourceFailure(ExactGpuResourceFailureReason::EmitDescriptorBind);
                                        discardExactSubmission();
                                        for (PendingExactGpuBuild& requeuePending : batch.builds)
                                        {
                                            requeueBuildRequest(requeuePending, false);
                                        }
                                        keepBatch = false;
                                        break;
                                    }
                                    updateExactGpuChunkAllocationRecord(pending,
                                                                        pending.requiredFaceCount,
                                                                        pending.faceCapacity,
                                                                        kExactChunkAllocationPhaseEmitSubmitted,
                                                                        0u,
                                                                        descriptorIndices.centerVoxelSrvDescriptorIndex,
                                                                        descriptorIndices.haloSrvDescriptorIndex);
                                    emitScratchSliceIndices.push_back(pending.scratchSliceIndex);
                                }
                                if (keepBatch &&
                                    !syncExactGpuChunkAllocationRecords(emitScratchSliceIndices, emitOwnedUploads))
                                {
                                    recordExactGpuResourceFailure(ExactGpuResourceFailureReason::EmitAllocationRecordSync);
                                    exactGpuAllocationRecordSyncFailures_.fetch_add(1, std::memory_order_relaxed);
                                    discardExactSubmission();
                                    for (PendingExactGpuBuild& pending : batch.builds)
                                    {
                                        requeueBuildRequest(pending, false);
                                    }
                                    keepBatch = false;
                                }
                            }
                            if (keepBatch)
                            {
                                const std::uint64_t buildIndexBytes =
                                    static_cast<std::uint64_t>(batch.builds.size()) * sizeof(std::uint32_t);
                                const FarLodGpuContext::ScratchAllocation buildIndexUpload =
                                    exactGpuContext_.allocateUpload(buildIndexBytes, alignof(std::uint32_t));
                                if (buildIndexUpload.resource == nullptr || buildIndexUpload.cpuPtr == nullptr)
                                {
                                    recordExactGpuResourceFailure(ExactGpuResourceFailureReason::EmitBuildIndexUploadAlloc);
                                    discardExactSubmission();
                                    for (PendingExactGpuBuild& pending : batch.builds)
                                    {
                                        requeueBuildRequest(pending, false);
                                    }
                                    keepBatch = false;
                                }
                                else
                                {
                                    std::uint32_t* buildIndexWritePtr =
                                        reinterpret_cast<std::uint32_t*>(buildIndexUpload.cpuPtr);
                                    for (std::size_t buildIndex = 0; buildIndex < batch.builds.size(); ++buildIndex)
                                    {
                                        buildIndexWritePtr[buildIndex] = batch.builds[buildIndex].scratchSliceIndex;
                                    }
                                    emitOwnedUploads.push_back(buildIndexUpload);
                                }
                            }
                        }

                        if (keepBatch && !batch.builds.empty())
                        {
                            std::vector<std::uint32_t> pagesNeedingWritableTransition{};
                            pagesNeedingWritableTransition.reserve(batch.builds.size());
                            std::vector<std::uint32_t> writablePageIndices{};
                            writablePageIndices.reserve(batch.builds.size());
                            for (const PendingExactGpuBuild& pending : batch.builds)
                            {
                                if (!pending.hasAllocation())
                                {
                                    continue;
                                }
                                writablePageIndices.push_back(pending.allocation.pageIndex);
                            }
                            std::sort(writablePageIndices.begin(), writablePageIndices.end());
                            writablePageIndices.erase(std::unique(writablePageIndices.begin(),
                                                                  writablePageIndices.end()),
                                                      writablePageIndices.end());
                            {
                                std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
                                for (const std::uint32_t pageIndex : writablePageIndices)
                                {
                                    if (pageIndex >= bufferPages_.size())
                                    {
                                        continue;
                                    }

                                    ChunkBufferPage& page = bufferPages_[pageIndex];
                                    assert(page.usage == ChunkBufferPageUsage::ExactGpu);
                                    assert(page.state == ChunkBufferPageState::OpenWritable);
                                    const bool pageNeedsWritableTransition =
                                        page.vertexState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS ||
                                        page.indexState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS ||
                                        page.drawRecordState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS ||
                                        page.drawRecordMetadataState != D3D12_RESOURCE_STATE_UNORDERED_ACCESS;
                                    if (pageNeedsWritableTransition)
                                    {
                                        pagesNeedingWritableTransition.push_back(pageIndex);
                                    }
                                }
                                for (const std::uint32_t pageIndex : pagesNeedingWritableTransition)
                                {
                                    ChunkBufferPage& page = bufferPages_[pageIndex];
                                    transitionExactPageToWritable(pageIndex, page);
                                }
                            }

                            const FarLodGpuContext::ScratchAllocation& buildIndexUpload = emitOwnedUploads.back();
                            exactGpuContext_.markExactTimingBegin(FarLodGpuContext::ExactTimingPass::FaceEmit);
                            exactGpuContext_.dispatchExactFaceEmit(
                                static_cast<std::uint32_t>(batch.builds.size()),
                                buildIndexUpload.gpuAddress,
                                exactGpuEmitConfigBuffer_.Get(),
                                exactGpuChunkAllocationRecordBuffer_.Get(),
                                exactGpuPageMetadataBuffer_.Get());
                            exactGpuContext_.markExactTimingEnd();
                            exactGpuContext_.uavBarrier(nullptr);

                            for (PendingExactGpuBuild& pending : batch.builds)
                            {
                                Chunk& chunk = *pending.chunk;
                                if (chunk.exactGpu.sparseVoxelBuffer != nullptr && chunk.exactGpu.sparseVoxelState != D3D12_RESOURCE_STATE_COMMON)
                                {
                                    exactGpuContext_.transition(chunk.exactGpu.sparseVoxelBuffer.Get(),
                                                                chunk.exactGpu.sparseVoxelState,
                                                                D3D12_RESOURCE_STATE_COMMON);
                                    chunk.exactGpu.sparseVoxelState = D3D12_RESOURCE_STATE_COMMON;
                                }
                                if (chunk.exactGpu.lightScratchBuffer != nullptr && chunk.exactGpu.lightScratchState != D3D12_RESOURCE_STATE_COMMON)
                                {
                                    exactGpuContext_.transition(chunk.exactGpu.lightScratchBuffer.Get(),
                                                                chunk.exactGpu.lightScratchState,
                                                                D3D12_RESOURCE_STATE_COMMON);
                                    chunk.exactGpu.lightScratchState = D3D12_RESOURCE_STATE_COMMON;
                                }
                                if (chunk.exactGpu.voxelState != D3D12_RESOURCE_STATE_COMMON)
                                {
                                    exactGpuContext_.transition(chunk.exactGpu.voxelBuffer.Get(),
                                                                chunk.exactGpu.voxelState,
                                                                D3D12_RESOURCE_STATE_COMMON);
                                    chunk.exactGpu.voxelState = D3D12_RESOURCE_STATE_COMMON;
                                }
                                if (chunk.exactGpu.haloBuffer != nullptr && chunk.exactGpu.haloState != D3D12_RESOURCE_STATE_COMMON)
                                {
                                    exactGpuContext_.transition(chunk.exactGpu.haloBuffer.Get(),
                                                                chunk.exactGpu.haloState,
                                                                D3D12_RESOURCE_STATE_COMMON);
                                    chunk.exactGpu.haloState = D3D12_RESOURCE_STATE_COMMON;
                                }
                            }

                            std::vector<std::uint32_t> completionSliceIndices{};
                            completionSliceIndices.reserve(batch.builds.size());
                            for (const PendingExactGpuBuild& pending : batch.builds)
                            {
                                completionSliceIndices.push_back(pending.scratchSliceIndex);
                            }
                            batch.completionReadback =
                                exactGpuContext_.queueExactCompletionReadback(completionSliceIndices);
                            const FarLodGpuContext::FlushResult emitFlushResult = exactGpuContext_.flush();
                            if (emitFlushResult.fenceValue != 0 && batch.completionReadback.allocation.cpuPtr != nullptr)
                            {
                                {
                                    std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
                                    for (const PendingExactGpuBuild& pending : batch.builds)
                                    {
                                        if (!pending.hasAllocation() || pending.allocation.pageIndex >= bufferPages_.size())
                                        {
                                            continue;
                                        }

                                        ChunkBufferPage& page = bufferPages_[pending.allocation.pageIndex];
                                        page.lastWriteFenceValue = emitFlushResult.fenceValue;
                                        noteExactGpuPageMetadataChange(pending.allocation.pageIndex);
                                    }
                                }
                                batch.emitResources.fenceValue = emitFlushResult.fenceValue;
                                batch.emitResources.submissionSlot = emitFlushResult.submissionSlotIndex;
                                batch.emitResources.uploadAllocations = std::move(emitOwnedUploads);
                                batch.emitResources.readbackAllocations.push_back(batch.completionReadback.allocation);
                                batch.phase = ExactGpuBatchPhase::EmitSubmitted;
                                batch.phaseEnteredMicros = steadyMicrosNow();
                                (void)benchmarkEnabled;
                                (void)readyForEmitBacklogBatches;
                                (void)readyForEmitBacklogBuilds;
                                (void)computeInFlightBeforeEmit;
                                for (PendingExactGpuBuild& pending : batch.builds)
                                {
                                    if (pending.chunk)
                                    {
                                        pending.chunk->exactGpu.readyFenceValue = emitFlushResult.fenceValue;
                                        exactGpuBuildsSubmitted_.fetch_add(1, std::memory_order_relaxed);
                                    }
                                }
                            }
                            else
                            {
                                if (emitFlushResult.fenceValue != 0)
                                {
                                    exactGpuContext_.waitForFence(emitFlushResult.fenceValue);
                                    exactGpuContext_.releaseSubmissionSlot(emitFlushResult.submissionSlotIndex);
                                }
                                for (PendingExactGpuBuild& pending : batch.builds)
                                {
                                    requeueBuildRequest(pending, emitFlushResult.fenceValue != 0);
                                }
                                batch.completionReadback = {};
                                keepBatch = false;
                            }
                        }
                        else
                        {
                            discardExactSubmission();
                            keepBatch = false;
                        }
                    }
                }
                exactLock.unlock();
            }

            if (keepBatch && batch.phase == ExactGpuBatchPhase::EmitSubmitted &&
                batch.emitResources.fenceValue != 0 &&
                completedGpuFenceValue >= batch.emitResources.fenceValue)
            {
                const auto* mappedCompletionEntries =
                    (batch.completionReadback.allocation.cpuPtr != nullptr)
                        ? reinterpret_cast<const FarLodGpuContext::ExactCompletionEntry*>(
                              batch.completionReadback.allocation.cpuPtr)
                        : nullptr;

                for (std::size_t buildOrdinal = 0; buildOrdinal < batch.builds.size(); ++buildOrdinal)
                {
                    PendingExactGpuBuild& pending = batch.builds[buildOrdinal];
                    if (!pending.chunk)
                    {
                        finalizeBuild(pending, false);
                        continue;
                    }

                    Chunk& chunk = *pending.chunk;
                    const bool completionPresent =
                        mappedCompletionEntries != nullptr &&
                        buildOrdinal < batch.completionReadback.buildCount;
                    const FarLodGpuContext::ExactCompletionEntry completion =
                        completionPresent
                            ? mappedCompletionEntries[buildOrdinal]
                            : FarLodGpuContext::ExactCompletionEntry{};
                    const bool completionMatchesScratchSlice =
                        completionPresent &&
                        completion.buildIndex == pending.scratchSliceIndex;
                    const bool completionMatchesPending =
                        completionMatchesScratchSlice &&
                        completion.buildVersion == pending.buildVersion &&
                        completion.generationEpoch == pending.generationEpoch &&
                        completion.inputVersionLo == static_cast<std::uint32_t>(pending.inputVersion & 0xffffffffu) &&
                        completion.inputVersionHi == static_cast<std::uint32_t>(pending.inputVersion >> 32u);
                    const bool completionMatchesCpuReservation =
                        completionMatchesScratchSlice &&
                        completionMatchesReservedAllocation(pending, completion);
                    if (!completionMatchesScratchSlice)
                    {
                        pending.allocation = {};
                        pending.faceCapacity = 0u;
                    }

                    const std::uint32_t currentBuildVersion = chunk.exactGpuBuildVersion.load(std::memory_order_acquire);
                    const std::uint32_t currentGenerationEpoch = chunk.generationEpoch.load(std::memory_order_acquire);
                    if (pending.buildVersion != currentBuildVersion ||
                        pending.generationEpoch != currentGenerationEpoch)
                    {
                        exactGpuBuildStaleCancels_.fetch_add(1, std::memory_order_relaxed);
                        releasePendingAllocation(pending, true);
                        releaseExactGpuScratch(chunk);
                        finalizeBuild(pending, chunk.exactGpuBuildQueued.load(std::memory_order_acquire));
                        continue;
                    }

                    if (!completionMatchesPending || !completionMatchesCpuReservation)
                    {
                        exactGpuBuildReadbackFailures_.fetch_add(1, std::memory_order_relaxed);
                        requeueBuildRequest(pending, true);
                        releaseExactGpuTransient(chunk);
                        finalizeBuild(pending, true);
                        continue;
                    }

                    const bool allocatorExhausted =
                        (completion.statusFlags & kExactCompletionStatusAllocatorExhaustedBit) != 0u;
                    if (allocatorExhausted)
                    {
                        assert(false &&
                               "CPU reservation path must fail before emit rather than reporting GPU allocator exhaustion");
                        exactGpuBuildReadbackFailures_.fetch_add(1, std::memory_order_relaxed);
                        queueChunkForExactGpuBuild(pending.chunk, pending.buildVersion);
                        releasePendingAllocation(pending, true);
                        releaseExactGpuScratch(chunk);
                        finalizeBuild(pending, true);
                        continue;
                    }

                    const bool completionCompleted =
                        (completion.statusFlags & kExactCompletionStatusCompletedBit) != 0u;
                    if (!completionCompleted)
                    {
                        exactGpuBuildReadbackFailures_.fetch_add(1, std::memory_order_relaxed);
                        requeueBuildRequest(pending, true);
                        releaseExactGpuTransient(chunk);
                        finalizeBuild(pending, true);
                        continue;
                    }

                    const bool overflowed =
                        (completion.statusFlags & kExactCompletionStatusOverflowBit) != 0u ||
                        completion.requiredFaces > completion.reservedFaceCapacity;
                    if (overflowed)
                    {
                        assert(false && "CPU reservation path overflow indicates a logic bug");
                        exactGpuBuildOverflows_.fetch_add(1, std::memory_order_relaxed);
                        queueChunkForExactGpuBuild(pending.chunk, pending.buildVersion);
                        releasePendingAllocation(pending, true);
                        releaseExactGpuScratch(chunk);
                        finalizeBuild(pending, true);
                        continue;
                    }

                    const bool hasExactDrawAllocation = pending.hasAllocation() && completion.requiredFaces > 0u;
                    const std::uint32_t newPageIndex = pending.allocation.pageIndex;
                    const std::uint32_t newRecordIndex = pending.allocation.recordIndex;
                    const std::uint32_t newFaceOffset = static_cast<std::uint32_t>(pending.allocation.faceOffset);
                    const std::uint32_t newFaceCount = completion.requiredFaces;
                    const std::uint32_t newRecordFlags =
                        exactDrawRecordFlagsFromCompletionStatus(completion.statusFlags);
                    ResidentChunkDrawAllocation liveAllocation{};
                    liveAllocation.chunkCoord = chunk.coord;
                    ResidentChunkDrawAllocation replacedPendingAllocation{};
                    replacedPendingAllocation.chunkCoord = chunk.coord;
 
                    {
                        std::lock_guard<std::mutex> meshLock(chunk.meshMutex);
                        liveAllocation.pageIndex = chunk.bufferPageIndex.load(std::memory_order_acquire);
                        liveAllocation.vertexOffset = chunk.vertexOffset.load(std::memory_order_acquire);
                        liveAllocation.vertexCount = chunk.vertexCount.load(std::memory_order_acquire);
                        liveAllocation.indexOffset = chunk.indexOffset.load(std::memory_order_acquire);
                        liveAllocation.indexCount =
                            static_cast<std::size_t>(chunk.indexCount.load(std::memory_order_acquire));
                        liveAllocation.recordIndex = chunk.exactGpuRecordIndex.load(std::memory_order_acquire);
                        liveAllocation.exactDraw = chunk.exactGpuResident.load(std::memory_order_acquire);

                        if (chunk.pendingExactDraw.valid())
                        {
                            replacedPendingAllocation.pageIndex = chunk.pendingExactDraw.pageIndex;
                            replacedPendingAllocation.recordIndex = chunk.pendingExactDraw.recordIndex;
                            replacedPendingAllocation.exactDraw = true;
                        }

                        chunk.exactGpuPendingNeighborMask.store(pending.pendingNeighborMask, std::memory_order_release);
                        chunk.exactGpuReadyVersion.store(pending.inputVersion, std::memory_order_release);
                        chunk.exactGpuHaloDirty.store(false, std::memory_order_release);
                        if (chunk.exactGpuInputsVersion.load(std::memory_order_acquire) == pending.inputVersion)
                        {
                            chunk.exactGpuInputsDirty.store(false, std::memory_order_release);
                        }
                        chunk.state.store(ChunkState::Uploaded, std::memory_order_release);
                        chunk.meshReady.store(false, std::memory_order_release);
                        const bool hasPendingLocalWork =
                            chunk.pendingMesh.valid() ||
                            chunk.pendingMeshRefresh.load(std::memory_order_acquire) ||
                            chunk.meshReady.load(std::memory_order_acquire) ||
                            chunk.queuedForUpload.load(std::memory_order_acquire) ||
                            chunk.queuedForCommit.load(std::memory_order_acquire);
                        const ChunkGameplayAuthority gameplayAuthority =
                            desiredChunkGameplayAuthorityFromState(
                                chunk,
                                lastCenterChunk_,
                                static_cast<double>(steadyMicrosNow()) / 1'000'000.0,
                                hasPendingLocalWork);
                        chunk.gameplayAuthority.store(gameplayAuthority, std::memory_order_release);
                        chunk.residencyMode.store(
                            gameplayAuthority == ChunkGameplayAuthority::GpuStreaming
                                ? ExactChunkResidencyMode::GpuResidentNonlocal
                                : ExactChunkResidencyMode::GpuPendingRetire,
                            std::memory_order_release);

                        if (hasExactDrawAllocation)
                        {
                            chunk.pendingExactDraw.pageIndex = newPageIndex;
                            chunk.pendingExactDraw.recordIndex = newRecordIndex;
                            chunk.pendingExactDraw.faceOffset = newFaceOffset;
                            chunk.pendingExactDraw.faceCount = newFaceCount;
                            chunk.pendingExactDraw.recordFlags = newRecordFlags;
                            chunk.pendingExactDrawReady.store(false, std::memory_order_release);
                            chunk.exactGpuPublishPending.store(true, std::memory_order_release);
                            recomputeChunkExactGpuHandoffReadiness(chunk);
                        }
                        else
                        {
                            chunk.bufferPageIndex.store(kInvalidChunkBufferPage, std::memory_order_release);
                            chunk.vertexOffset.store(0, std::memory_order_release);
                            chunk.indexOffset.store(0, std::memory_order_release);
                            chunk.vertexCount.store(0, std::memory_order_release);
                            chunk.indexCount.store(0, std::memory_order_release);
                            chunk.exactGpuFaceOffset.store(0, std::memory_order_release);
                            chunk.exactGpuFaceCount.store(0, std::memory_order_release);
                            chunk.exactGpuRecordIndex.store(kInvalidExactGpuDrawRecordIndex, std::memory_order_release);
                            chunk.exactGpuRecordFlags.store(0, std::memory_order_release);
                            chunk.exactGpuResident.store(false, std::memory_order_release);
                            chunk.pendingExactDraw.reset();
                            chunk.pendingExactDrawReady.store(false, std::memory_order_release);
                            chunk.exactGpuPublishPending.store(false, std::memory_order_release);
                            chunk.handoffReady.store(false, std::memory_order_release);
                        }
                    }
                    refreshPendingExactGpuBuildCount(chunk);

                    if (hasExactDrawAllocation)
                    {
                        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
                        if (pending.allocation.pageIndex < bufferPages_.size())
                        {
                            ChunkBufferPage& page = bufferPages_[pending.allocation.pageIndex];
                            if (page.pendingChunks > 0)
                            {
                                --page.pendingChunks;
                            }
                            ++page.residentChunks;
                            ++page.liveResidentChunkCount;
                            page.recordActiveCount =
                                std::max(page.recordActiveCount,
                                         static_cast<std::size_t>(pending.allocation.recordIndex + 1u));
                            assert(page.state == ChunkBufferPageState::OpenWritable ||
                                   page.state == ChunkBufferPageState::SealedPendingResident);
                            addChunkToExactPageMembers(pending.allocation.pageIndex, chunk.coord);
                            queueChunkForExactPagePublish(pending.allocation.pageIndex, chunk.coord);
                            noteExactGpuPageMetadataChange(pending.allocation.pageIndex);
                        }
                    }

                    if (replacedPendingAllocation.valid() &&
                        (!hasExactDrawAllocation ||
                         replacedPendingAllocation.pageIndex != newPageIndex ||
                         replacedPendingAllocation.recordIndex != newRecordIndex))
                    {
                        releaseResidentChunkDrawAllocation(replacedPendingAllocation);
                    }

                    if (!hasExactDrawAllocation && liveAllocation.valid())
                    {
                        exactGpuMeshReplacements_.fetch_add(1, std::memory_order_relaxed);
                        releaseResidentChunkDrawAllocation(liveAllocation);
                    }

                    if (hasExactDrawAllocation)
                    {
                        setStreamingChunkLifecycleState(chunk.coord, FrontierDemandState::Meshing);
                    }
                    else
                    {
                        publishChunkReady(chunk);
                        ++zeroFaceReadyCount;
                        if (zeroFaceReadySampleCoords.size() < 6u)
                        {
                            zeroFaceReadySampleCoords.push_back(chunk.coord);
                        }
                    }
                    releaseExactGpuTransient(chunk);
                    exactGpuBuildsCommitted_.fetch_add(1, std::memory_order_relaxed);
                    if (!chunk.exactGpuInputsDirty.load(std::memory_order_acquire) &&
                        !chunk.exactGpuBuildQueued.load(std::memory_order_acquire))
                    {
                        std::vector<GpuExactSparseVoxel>().swap(chunk.gpuExactSparseVoxels);
                        chunk.gpuExactSparseVoxelsReady = false;
                    }
                    queuePendingNeighborRefreshes(chunk);
                    finalizeBuild(pending, chunk.exactGpuBuildQueued.load(std::memory_order_acquire));
                }

                batch.completionReadback = {};
                retireBatchPhaseResources(batch.emitResources);
                releaseBatchScratchSlices(batch);
                keepBatch = false;
            }

            if (keepBatch)
            {
                if (writeIndex != i)
                {
                    pendingExactGpuBatches_[writeIndex] = std::move(batch);
                }
                ++writeIndex;
            }
        }

        pendingExactGpuBatches_.resize(writeIndex);
        std::sort(freeExactGpuScratchSlices_.begin(), freeExactGpuScratchSlices_.end());
        if (zeroFaceReadyCount > 0u && exactDependencyStallDebugLoggingEnabled())
        {
            std::ostringstream stream;
            stream << "exact_gpu_zero_face_ready count=" << zeroFaceReadyCount;
            for (const glm::ivec3& coord : zeroFaceReadySampleCoords)
            {
                stream << " chunk=(" << coord.x << "," << coord.y << "," << coord.z << ")";
            }
            exactDependencyStallDebugLog(stream.str());
        }
        return;
    }
}

bool ChunkManager::Impl::uploadChunkMesh(Chunk& chunk, UINT64 uploadBatchId)
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const std::uint64_t uploadStartMicros = steadyMicrosNow();
    storeFirstBenchmarkTimestamp(chunk.uploadStartTimestampMicros, uploadStartMicros);
    const std::uint64_t queuedMicros = loadBenchmarkTimestamp(chunk.uploadQueuedTimestampMicros);
    if (queuedMicros > 0 && uploadStartMicros > queuedMicros)
    {
        const std::uint64_t queueAgeMicros = uploadStartMicros - queuedMicros;
        uploadQueueAgeMsLastFrame_ =
            std::max(uploadQueueAgeMsLastFrame_, static_cast<double>(queueAgeMicros) / 1000.0);
        if (benchmarkEnabled)
        {
            benchmarkMetrics_.uploadQueueAgeStage.recordMicros(queueAgeMicros);
        }
    }
    const auto meshLockStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    const auto recordMeshLock = [&]()
    {
        if (!benchmarkEnabled)
        {
            return;
        }

        const auto lockMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(SteadyClock::now() - meshLockStart).count();
        benchmarkMetrics_.uploadChunkMeshLockStage.recordMicros(static_cast<std::uint64_t>(lockMicros));
    };
    std::lock_guard<std::mutex> lock(chunk.meshMutex);
    const std::uint32_t oldPageIndex = chunk.bufferPageIndex.load(std::memory_order_acquire);
    const std::uint32_t oldIndexCount = chunk.indexCount.load(std::memory_order_acquire);

    if (chunk.meshData.empty())
    {
        if (shouldTrackRecentEditChunk(chunk.coord))
        {
            std::ostringstream stream;
            stream << "upload skipped empty chunk=(" << chunk.coord.x << ", " << chunk.coord.y << ", " << chunk.coord.z
                   << ") oldPage=" << oldPageIndex
                   << " oldIdx=" << oldIndexCount;
            appendRecentEditDebugEvent(stream.str());
        }
        recordMeshLock();
        return false;
    }

    const std::size_t vertexCount = chunk.meshData.vertices.size();
    const std::size_t indexCount = chunk.meshData.indices.size();
    const std::uint32_t meshVersion = chunk.meshVersion.load(std::memory_order_acquire);

    ChunkAllocation allocation = acquireChunkAllocation(vertexCount,
                                                        indexCount,
                                                        uploadBatchId,
                                                        ChunkBufferPageUsage::CpuUpload);
    if (allocation.pageIndex == kInvalidChunkBufferPage)
    {
        if (exactUploadDebugLoggingEnabled())
        {
            std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
            std::ostringstream stream;
            stream << "exact upload allocation failed"
                   << " chunk=(" << chunk.coord.x << "," << chunk.coord.y << "," << chunk.coord.z << ")"
                   << " requestVerts=" << vertexCount
                   << " requestIdx=" << indexCount
                   << " uploadBatchId=" << uploadBatchId
                   << " | " << summarizeChunkBufferPagesLocked();
            exactUploadDebugLog(stream.str());
        }
        if (shouldTrackRecentEditChunk(chunk.coord))
        {
            std::ostringstream stream;
            stream << "upload alloc failed chunk=(" << chunk.coord.x << ", " << chunk.coord.y << ", " << chunk.coord.z
                   << ") oldPage=" << oldPageIndex
                   << " verts=" << vertexCount
                   << " idx=" << indexCount;
            appendRecentEditDebugEvent(stream.str());
        }
        recordMeshLock();
        return false;
    }

    std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
    if (allocation.pageIndex >= bufferPages_.size())
    {
        recordMeshLock();
        return false;
    }

    ChunkBufferPage& page = bufferPages_[allocation.pageIndex];
    if (page.mappedVertexData != nullptr && vertexCount > 0)
    {
        std::memcpy(page.mappedVertexData + allocation.vertexOffset * sizeof(Vertex),
                    chunk.meshData.vertices.data(),
                    vertexCount * sizeof(Vertex));
        if (uploadContext_.ready() && page.vertexUploadBuffer != nullptr && page.vertexBuffer != nullptr)
        {
            uploadContext_.copyBuffer(page.vertexBuffer.Get(),
                                      static_cast<std::uint64_t>(allocation.vertexOffset * sizeof(Vertex)),
                                      page.vertexUploadBuffer.Get(),
                                      static_cast<std::uint64_t>(allocation.vertexOffset * sizeof(Vertex)),
                                      static_cast<std::uint64_t>(vertexCount * sizeof(Vertex)));
        }
    }
    if (page.mappedIndexData != nullptr && indexCount > 0)
    {
        std::memcpy(page.mappedIndexData + allocation.indexOffset * sizeof(std::uint32_t),
                    chunk.meshData.indices.data(),
                    indexCount * sizeof(std::uint32_t));
        if (uploadContext_.ready() && page.indexUploadBuffer != nullptr && page.indexBuffer != nullptr)
        {
            uploadContext_.copyBuffer(page.indexBuffer.Get(),
                                      static_cast<std::uint64_t>(allocation.indexOffset * sizeof(std::uint32_t)),
                                      page.indexUploadBuffer.Get(),
                                      static_cast<std::uint64_t>(allocation.indexOffset * sizeof(std::uint32_t)),
                                      static_cast<std::uint64_t>(indexCount * sizeof(std::uint32_t)));
        }
    }

    chunk.pendingMesh.pageIndex = allocation.pageIndex;
    chunk.pendingMesh.vertexOffset = allocation.vertexOffset;
    chunk.pendingMesh.indexOffset = allocation.indexOffset;
    chunk.pendingMesh.vertexCount = vertexCount;
    chunk.pendingMesh.indexCount = indexCount;
    chunk.pendingMesh.meshVersion = meshVersion;
    chunk.pendingMesh.uploadFenceValue = 0;
    chunk.pendingMeshPresent.store(true, std::memory_order_release);
    chunk.meshData.clear();
    recordMeshLock();

    if (shouldTrackRecentEditChunk(chunk.coord))
    {
        std::ostringstream stream;
        stream << "upload complete chunk=(" << chunk.coord.x << ", " << chunk.coord.y << ", " << chunk.coord.z
               << ") oldPage=" << oldPageIndex
               << " pendingPage=" << allocation.pageIndex
               << " idx=" << indexCount;
        appendRecentEditDebugEvent(stream.str());
    }
    return true;
}

ChunkManager::Impl::ChunkNeighborhoodSnapshot ChunkManager::Impl::captureChunkNeighborhoodSnapshot(
    const Chunk& chunk,
    const std::vector<BlockId>& centerBlocks,
    const std::vector<std::uint8_t>& centerLightLevels)
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    ChunkNeighborhoodSnapshot snapshot(chunk.minWorldY);

    for (int localX = 0; localX < kChunkSizeX; ++localX)
    {
        for (int localY = 0; localY < kChunkSizeY; ++localY)
        {
            for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
            {
                const std::size_t voxelIndex = blockIndex(localX, localY, localZ);
                snapshot.set(localX, localY, localZ, centerBlocks[voxelIndex], centerLightLevels[voxelIndex]);
            }
        }
    }

    std::unordered_map<glm::ivec3, std::shared_ptr<Chunk>, ChunkHasher> neighborhoodChunks;
    neighborhoodChunks.reserve(27);
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        for (int dx = -1; dx <= 1; ++dx)
        {
            for (int dy = -1; dy <= 1; ++dy)
            {
                for (int dz = -1; dz <= 1; ++dz)
                {
                    const glm::ivec3 sampleCoord = chunk.coord + glm::ivec3(dx, dy, dz);
                    auto it = chunks_.find(sampleCoord);
                    if (it != chunks_.end())
                    {
                        neighborhoodChunks.emplace(sampleCoord, it->second);
                    }
                }
            }
        }
    }

    std::vector<std::shared_ptr<Chunk>> lockedNeighbors;
    lockedNeighbors.reserve(neighborhoodChunks.size());
    for (const auto& [coord, sampleChunk] : neighborhoodChunks)
    {
        if (!sampleChunk || sampleChunk.get() == &chunk)
        {
            continue;
        }

        lockedNeighbors.push_back(sampleChunk);
    }

    std::sort(lockedNeighbors.begin(),
              lockedNeighbors.end(),
              [](const std::shared_ptr<Chunk>& lhs, const std::shared_ptr<Chunk>& rhs)
              {
                  if (lhs->coord.x != rhs->coord.x)
                  {
                      return lhs->coord.x < rhs->coord.x;
                  }
                  if (lhs->coord.y != rhs->coord.y)
                  {
                      return lhs->coord.y < rhs->coord.y;
                  }
                  return lhs->coord.z < rhs->coord.z;
              });

    std::unordered_map<glm::ivec3, std::vector<BlockId>, ChunkHasher> transientNeighborBlocks;
    std::unordered_map<glm::ivec3, std::vector<std::uint8_t>, ChunkHasher> transientNeighborLightLevels;
    transientNeighborBlocks.reserve(lockedNeighbors.size());
    transientNeighborLightLevels.reserve(lockedNeighbors.size());
    for (const auto& sampleChunk : lockedNeighbors)
    {
        if (!sampleChunk || sampleChunk->cpuDataResident.load(std::memory_order_acquire))
        {
            continue;
        }

        ChunkBuildScratch scratch(*sampleChunk);
        std::array<ColumnBuildResult, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> columnResults{};
        buildChunkCpuBlocks(*sampleChunk, scratch, false, columnResults, nullptr);
        std::array<std::uint8_t, kChunkSizeX * kChunkSizeZ> incomingSky{};
        {
            std::lock_guard<std::mutex> lock(sampleChunk->meshMutex);
            incomingSky = sampleChunk->skyLightFromAboveCache;
        }
        transientNeighborBlocks.emplace(sampleChunk->coord, scratch.blocks);
        auto& transientLightLevels = transientNeighborLightLevels[sampleChunk->coord];
        rebuildChunkBaseLighting(transientNeighborBlocks[sampleChunk->coord], incomingSky, transientLightLevels);
    }

    std::vector<std::unique_lock<std::mutex>> locks;
    locks.reserve(lockedNeighbors.size());
    const auto lockStageStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    for (const auto& sampleChunk : lockedNeighbors)
    {
        if (!sampleChunk || !sampleChunk->cpuDataResident.load(std::memory_order_acquire))
        {
            continue;
        }
        locks.emplace_back(sampleChunk->meshMutex);
    }

    const int baseWorldX = chunk.coord.x * kChunkSizeX;
    const int baseWorldY = chunk.minWorldY;
    const int baseWorldZ = chunk.coord.z * kChunkSizeZ;

    for (int sampleX = -1; sampleX <= kChunkSizeX; ++sampleX)
    {
        for (int sampleY = -1; sampleY <= kChunkSizeY; ++sampleY)
        {
            for (int sampleZ = -1; sampleZ <= kChunkSizeZ; ++sampleZ)
            {
                if (sampleX >= 0 && sampleX < kChunkSizeX &&
                    sampleY >= 0 && sampleY < kChunkSizeY &&
                    sampleZ >= 0 && sampleZ < kChunkSizeZ)
                {
                    continue;
                }

                const glm::ivec3 worldPos(baseWorldX + sampleX, baseWorldY + sampleY, baseWorldZ + sampleZ);
                if (worldPos.y < 0)
                {
                    snapshot.set(sampleX, sampleY, sampleZ, BlockId::Air, packLightLevels(0, 0));
                    continue;
                }

                const glm::ivec3 sampleChunkCoord = worldToChunkCoords(worldPos.x, worldPos.y, worldPos.z);
                auto neighborhoodIt = neighborhoodChunks.find(sampleChunkCoord);
                if (neighborhoodIt == neighborhoodChunks.end() || !neighborhoodIt->second)
                {
                    continue;
                }

                const Chunk& sampleChunk = *neighborhoodIt->second;
                if (worldPos.y < sampleChunk.minWorldY || worldPos.y > sampleChunk.maxWorldY)
                {
                    continue;
                }

                const glm::ivec3 local = localBlockCoords(worldPos, sampleChunkCoord);
                if (local.x < 0 || local.x >= kChunkSizeX ||
                    local.z < 0 || local.z >= kChunkSizeZ)
                {
                    continue;
                }

                const int localY = worldPos.y - sampleChunk.minWorldY;
                const std::size_t voxelIndex = blockIndex(local.x, localY, local.z);
                if (sampleChunk.cpuDataResident.load(std::memory_order_acquire))
                {
                    snapshot.set(sampleX,
                                 sampleY,
                                 sampleZ,
                                 sampleChunk.blocks[voxelIndex],
                                 sampleChunk.lightLevels[voxelIndex]);
                    continue;
                }

                auto transientBlocksIt = transientNeighborBlocks.find(sampleChunkCoord);
                auto transientLightsIt = transientNeighborLightLevels.find(sampleChunkCoord);
                if (transientBlocksIt == transientNeighborBlocks.end() ||
                    transientLightsIt == transientNeighborLightLevels.end())
                {
                    continue;
                }

                snapshot.set(sampleX,
                             sampleY,
                             sampleZ,
                             transientBlocksIt->second[voxelIndex],
                             transientLightsIt->second[voxelIndex]);
            }
        }
    }

    if (benchmarkEnabled)
    {
        const auto lockMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(SteadyClock::now() - lockStageStart).count();
        benchmarkMetrics_.neighborhoodSnapshotLockStage.recordMicros(static_cast<std::uint64_t>(lockMicros));
    }

    return snapshot;
}

namespace
{
constexpr std::uint32_t kWaterQuadFaceTop = 0u;
constexpr std::uint32_t kWaterQuadFaceWall = 1u;

[[nodiscard]] constexpr std::size_t waterHaloColumnIndex(int localX, int localZ) noexcept
{
    return static_cast<std::size_t>(localZ + 1) * static_cast<std::size_t>(kChunkSizeX + 2) +
           static_cast<std::size_t>(localX + 1);
}

[[nodiscard]] bool buildWaterColumnFieldFromSnapshot(
    const auto& snapshot,
    int localX,
    int localZ,
    int chunkMinWorldY,
    WaterColumnField& outField) noexcept
{
    outField = {};
    bool inSpan = false;
    int spanBottomWorld = 0;
    for (int localY = 0; localY < kChunkSizeY; ++localY)
    {
        const bool isWater = snapshot.blockAt(localX, localY, localZ) == BlockId::Water;
        if (isWater)
        {
            if (!inSpan)
            {
                inSpan = true;
                spanBottomWorld = chunkMinWorldY + localY;
            }
            continue;
        }

        if (!inSpan)
        {
            continue;
        }

        if (outField.spanCount >= kMaxWaterSpansPerColumn)
        {
            outField = {};
            return false;
        }

        WaterSpan& span = outField.spans[outField.spanCount++];
        span.bottomY = spanBottomWorld;
        span.topY = chunkMinWorldY + localY - 1;
        span.material = static_cast<std::uint32_t>(BlockId::Water);
        inSpan = false;
    }

    if (inSpan)
    {
        if (outField.spanCount >= kMaxWaterSpansPerColumn)
        {
            outField = {};
            return false;
        }

        WaterSpan& span = outField.spans[outField.spanCount++];
        span.bottomY = spanBottomWorld;
        span.topY = chunkMinWorldY + kChunkSizeY - 1;
        span.material = static_cast<std::uint32_t>(BlockId::Water);
    }

    return true;
}

[[nodiscard]] bool waterFieldsOverlap(const WaterSpan& lhs, const WaterSpan& rhs) noexcept
{
    return lhs.bottomY <= rhs.topY && rhs.bottomY <= lhs.topY;
}

void subtractWaterOverlap(const WaterSpan& source,
                          const WaterColumnField& neighbor,
                          std::vector<std::pair<int, int>>& outIntervals)
{
    outIntervals.clear();
    outIntervals.emplace_back(source.bottomY, source.topY);

    for (std::uint8_t i = 0; i < neighbor.spanCount; ++i)
    {
        const WaterSpan& neighborSpan = neighbor.spans[i];
        std::vector<std::pair<int, int>> next;
        next.reserve(outIntervals.size() + 1u);
        for (const auto& interval : outIntervals)
        {
            const int overlapBottom = std::max(interval.first, neighborSpan.bottomY);
            const int overlapTop = std::min(interval.second, neighborSpan.topY);
            if (overlapBottom > overlapTop)
            {
                next.push_back(interval);
                continue;
            }
            if (interval.first < overlapBottom)
            {
                next.emplace_back(interval.first, overlapBottom - 1);
            }
            if (overlapTop < interval.second)
            {
                next.emplace_back(overlapTop + 1, interval.second);
            }
        }
        outIntervals.swap(next);
        if (outIntervals.empty())
        {
            return;
        }
    }
}

void updateWaterBounds(const glm::vec3& p0,
                       const glm::vec3& p1,
                       const glm::vec3& p2,
                       const glm::vec3& p3,
                       bool& boundsValid,
                       glm::vec3& boundsMin,
                       glm::vec3& boundsMax)
{
    const glm::vec3 quadMin = glm::min(glm::min(p0, p1), glm::min(p2, p3));
    const glm::vec3 quadMax = glm::max(glm::max(p0, p1), glm::max(p2, p3));
    if (!boundsValid)
    {
        boundsValid = true;
        boundsMin = quadMin;
        boundsMax = quadMax;
        return;
    }
    boundsMin = glm::min(boundsMin, quadMin);
    boundsMax = glm::max(boundsMax, quadMax);
}

void appendWaterQuad(std::vector<WaterQuadDescriptor>& outQuads,
                     const glm::vec3& origin,
                     const glm::vec3& axisU,
                     const glm::vec3& axisV,
                     const glm::vec3& normal,
                     float topY,
                     float bottomY,
                     std::uint32_t faceKind,
                     const glm::vec2& atlasBase,
                     const glm::vec2& atlasSize,
                     bool& boundsValid,
                     glm::vec3& boundsMin,
                     glm::vec3& boundsMax)
{
    WaterQuadDescriptor descriptor{};
    descriptor.origin = origin;
    descriptor.topY = topY;
    descriptor.axisU = axisU;
    descriptor.bottomY = bottomY;
    descriptor.axisV = axisV;
    descriptor.faceKind = faceKind;
    descriptor.normal = normal;
    descriptor.atlasBase = atlasBase;
    descriptor.atlasSize = atlasSize;
    outQuads.push_back(descriptor);

    const glm::vec3 p0 = origin;
    const glm::vec3 p1 = origin + axisU;
    const glm::vec3 p2 = origin + axisU + axisV;
    const glm::vec3 p3 = origin + axisV;
    updateWaterBounds(p0, p1, p2, p3, boundsValid, boundsMin, boundsMax);
}

[[nodiscard]] bool buildChunkWaterQuadDescriptors(
    const Chunk& chunk,
    const auto& snapshot,
    const std::pair<glm::vec2, glm::vec2>& topUv,
    const std::pair<glm::vec2, glm::vec2>& sideUv,
    std::vector<WaterQuadDescriptor>& outQuads,
    glm::vec3& outBoundsMin,
    glm::vec3& outBoundsMax)
{
    outQuads.clear();
    outBoundsMin = glm::vec3(0.0f);
    outBoundsMax = glm::vec3(0.0f);
    bool boundsValid = false;

    std::array<WaterColumnField, static_cast<std::size_t>((kChunkSizeX + 2) * (kChunkSizeZ + 2))> fields{};
    for (int localZ = -1; localZ <= kChunkSizeZ; ++localZ)
    {
        for (int localX = -1; localX <= kChunkSizeX; ++localX)
        {
            if (!buildWaterColumnFieldFromSnapshot(snapshot,
                                                   localX,
                                                   localZ,
                                                   chunk.minWorldY,
                                                   fields[waterHaloColumnIndex(localX, localZ)]))
            {
                return false;
            }
        }
    }

    struct TopMaskCell
    {
        bool exists{false};
        WaterSpan span{};
    };

    for (std::uint32_t spanSlot = 0; spanSlot < kMaxWaterSpansPerColumn; ++spanSlot)
    {
        std::array<TopMaskCell, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> mask{};
        auto maskIndex = [](int localX, int localZ) noexcept
        {
            return static_cast<std::size_t>(localZ * kChunkSizeX + localX);
        };

        for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
        {
            for (int localX = 0; localX < kChunkSizeX; ++localX)
            {
                const WaterColumnField& field = fields[waterHaloColumnIndex(localX, localZ)];
                if (field.spanCount <= spanSlot)
                {
                    continue;
                }

                const WaterSpan& span = field.spans[spanSlot];
                const int topLocalY = span.topY - chunk.minWorldY;
                if (snapshot.blockAt(localX, topLocalY + 1, localZ) == BlockId::Water)
                {
                    continue;
                }

                TopMaskCell& cell = mask[maskIndex(localX, localZ)];
                cell.exists = true;
                cell.span = span;
            }
        }

        for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
        {
            int localX = 0;
            while (localX < kChunkSizeX)
            {
                const TopMaskCell& cell = mask[maskIndex(localX, localZ)];
                if (!cell.exists)
                {
                    ++localX;
                    continue;
                }

                int width = 1;
                while (localX + width < kChunkSizeX)
                {
                    const TopMaskCell& next = mask[maskIndex(localX + width, localZ)];
                    if (!next.exists ||
                        next.span.bottomY != cell.span.bottomY ||
                        next.span.topY != cell.span.topY ||
                        next.span.material != cell.span.material)
                    {
                        break;
                    }
                    ++width;
                }

                int height = 1;
                while (localZ + height < kChunkSizeZ)
                {
                    bool rowMatches = true;
                    for (int offsetX = 0; offsetX < width; ++offsetX)
                    {
                        const TopMaskCell& next = mask[maskIndex(localX + offsetX, localZ + height)];
                        if (!next.exists ||
                            next.span.bottomY != cell.span.bottomY ||
                            next.span.topY != cell.span.topY ||
                            next.span.material != cell.span.material)
                        {
                            rowMatches = false;
                            break;
                        }
                    }
                    if (!rowMatches)
                    {
                        break;
                    }
                    ++height;
                }

                const glm::vec3 origin(
                    static_cast<float>(chunk.coord.x * kChunkSizeX + localX),
                    static_cast<float>(cell.span.topY + 1),
                    static_cast<float>(chunk.coord.z * kChunkSizeZ + localZ));
                appendWaterQuad(outQuads,
                                origin,
                                glm::vec3(static_cast<float>(width), 0.0f, 0.0f),
                                glm::vec3(0.0f, 0.0f, static_cast<float>(height)),
                                glm::vec3(0.0f, 1.0f, 0.0f),
                                static_cast<float>(cell.span.topY),
                                static_cast<float>(cell.span.bottomY),
                                kWaterQuadFaceTop,
                                topUv.first,
                                topUv.second,
                                boundsValid,
                                outBoundsMin,
                                outBoundsMax);

                for (int clearZ = 0; clearZ < height; ++clearZ)
                {
                    for (int clearX = 0; clearX < width; ++clearX)
                    {
                        mask[maskIndex(localX + clearX, localZ + clearZ)].exists = false;
                    }
                }

                localX += width;
            }
        }
    }

    std::vector<std::pair<int, int>> exposedIntervals;
    exposedIntervals.reserve(kMaxWaterSpansPerColumn + 1u);
    const glm::ivec2 faceOffsets[4]{
        glm::ivec2(1, 0),
        glm::ivec2(-1, 0),
        glm::ivec2(0, 1),
        glm::ivec2(0, -1)};
    const glm::vec3 normals[4]{
        glm::vec3(1.0f, 0.0f, 0.0f),
        glm::vec3(-1.0f, 0.0f, 0.0f),
        glm::vec3(0.0f, 0.0f, 1.0f),
        glm::vec3(0.0f, 0.0f, -1.0f)};

    for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
    {
        for (int localX = 0; localX < kChunkSizeX; ++localX)
        {
            const WaterColumnField& field = fields[waterHaloColumnIndex(localX, localZ)];
            for (std::uint8_t spanIndex = 0; spanIndex < field.spanCount; ++spanIndex)
            {
                const WaterSpan& span = field.spans[spanIndex];
                for (int faceIndex = 0; faceIndex < 4; ++faceIndex)
                {
                    const glm::ivec2 neighborOffset = faceOffsets[faceIndex];
                    const WaterColumnField& neighborField =
                        fields[waterHaloColumnIndex(localX + neighborOffset.x, localZ + neighborOffset.y)];
                    subtractWaterOverlap(span, neighborField, exposedIntervals);
                    for (const auto& interval : exposedIntervals)
                    {
                        if (interval.first > interval.second)
                        {
                            continue;
                        }

                        const float bottom = static_cast<float>(interval.first);
                        const float top = static_cast<float>(interval.second);
                        const float height = top - bottom + 1.0f;
                        const float worldX = static_cast<float>(chunk.coord.x * kChunkSizeX + localX);
                        const float worldZ = static_cast<float>(chunk.coord.z * kChunkSizeZ + localZ);

                        glm::vec3 origin(0.0f);
                        glm::vec3 axisU(0.0f, height, 0.0f);
                        glm::vec3 axisV(0.0f);
                        switch (faceIndex)
                        {
                        case 0:
                            origin = glm::vec3(worldX + 1.0f, bottom, worldZ);
                            axisV = glm::vec3(0.0f, 0.0f, 1.0f);
                            break;
                        case 1:
                            origin = glm::vec3(worldX, bottom, worldZ + 1.0f);
                            axisV = glm::vec3(0.0f, 0.0f, -1.0f);
                            break;
                        case 2:
                            origin = glm::vec3(worldX + 1.0f, bottom, worldZ + 1.0f);
                            axisV = glm::vec3(-1.0f, 0.0f, 0.0f);
                            break;
                        case 3:
                        default:
                            origin = glm::vec3(worldX, bottom, worldZ);
                            axisV = glm::vec3(1.0f, 0.0f, 0.0f);
                            break;
                        }

                        appendWaterQuad(outQuads,
                                        origin,
                                        axisU,
                                        axisV,
                                        normals[faceIndex],
                                        top,
                                        bottom,
                                        kWaterQuadFaceWall,
                                        sideUv.first,
                                        sideUv.second,
                                        boundsValid,
                                        outBoundsMin,
                                        outBoundsMax);
                    }
                }
            }
        }
    }

    return boundsValid;
}

[[nodiscard]] GpuWaterQuadDescriptor packWaterQuadDescriptor(const WaterQuadDescriptor& descriptor) noexcept
{
    GpuWaterQuadDescriptor gpu{};
    gpu.originTop = glm::vec4(descriptor.origin, descriptor.topY);
    gpu.axisUBottom = glm::vec4(descriptor.axisU, descriptor.bottomY);
    gpu.axisVFaceKind = glm::vec4(descriptor.axisV, static_cast<float>(descriptor.faceKind));
    gpu.normalAtlasBaseX = glm::vec4(descriptor.normal, descriptor.atlasBase.x);
    gpu.atlasRest = glm::vec4(descriptor.atlasBase.y, descriptor.atlasSize.x, descriptor.atlasSize.y, 0.0f);
    return gpu;
}
} // namespace

bool ChunkManager::Impl::rebuildChunkWaterResources(Chunk& chunk,
                                                    const std::vector<BlockId>& centerBlocks,
                                                    const std::vector<std::uint8_t>& centerLightLevels)
{
    if (device_ == nullptr)
    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        chunk.waterGpu.reset();
        return true;
    }

    const ChunkNeighborhoodSnapshot snapshot =
        captureChunkNeighborhoodSnapshot(chunk, centerBlocks, centerLightLevels);
    std::vector<WaterQuadDescriptor> quads;
    glm::vec3 boundsMin(0.0f);
    glm::vec3 boundsMax(0.0f);
    const bool hasWaterGeometry =
        buildChunkWaterQuadDescriptors(chunk,
                                       snapshot,
                                       atlasUvFor(BlockId::Water, BlockFace::Top),
                                       atlasUvFor(BlockId::Water, BlockFace::North),
                                       quads,
                                       boundsMin,
                                       boundsMax);

    if (!hasWaterGeometry || quads.empty())
    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        chunk.waterGpu.reset();
        return true;
    }

    std::byte* mapped = nullptr;
    Microsoft::WRL::ComPtr<ID3D12Resource> buffer =
        createUploadBuffer(device_.Get(),
                           static_cast<std::uint64_t>(quads.size() * sizeof(GpuWaterQuadDescriptor)),
                           mapped);
    if (buffer == nullptr || mapped == nullptr)
    {
        return false;
    }

    auto* gpuDescriptors = reinterpret_cast<GpuWaterQuadDescriptor*>(mapped);
    for (std::size_t i = 0; i < quads.size(); ++i)
    {
        gpuDescriptors[i] = packWaterQuadDescriptor(quads[i]);
    }
    buffer->Unmap(0, nullptr);

    std::lock_guard<std::mutex> lock(chunk.meshMutex);
    chunk.waterGpu.descriptorBuffer = std::move(buffer);
    chunk.waterGpu.quadCount = static_cast<std::uint32_t>(quads.size());
    chunk.waterGpu.boundsMin = boundsMin;
    chunk.waterGpu.boundsMax = boundsMax;
    return true;
}

void ChunkManager::Impl::buildChunkMeshAsync(Chunk& chunk)
{
    if (!chunk.cpuDataResident.load(std::memory_order_acquire) &&
        shouldKeepLoadedChunkInteractive(chunk, lastCenterChunk_) &&
        !ensureChunkCpuDataResident(chunk))
    {
        return;
    }
    std::vector<BlockId> chunkBlocks;
    std::vector<std::uint8_t> chunkLightLevels;
    std::array<std::uint8_t, kChunkSizeX * kChunkSizeZ> incomingSky{};
    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        if (!chunk.hasBlocks.load(std::memory_order_acquire))
        {
            chunk.meshData.clear();
            chunk.meshReady.store(true, std::memory_order_release);
            chunk.hasTranslucentBlocks.store(false, std::memory_order_release);
            chunk.waterGpu.reset();
            return;
        }

        incomingSky = chunk.skyLightFromAboveCache;
        if (chunk.cpuDataResident.load(std::memory_order_acquire))
        {
            chunkBlocks = chunk.blocks;
            chunkLightLevels = chunk.lightLevels;
        }
    }

    if (chunkBlocks.empty())
    {
        ChunkBuildScratch scratch(chunk);
        std::array<ColumnBuildResult, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> columnResults{};
        buildChunkCpuBlocks(chunk, scratch, false, columnResults, nullptr);
        chunkBlocks = std::move(scratch.blocks);
        rebuildChunkBaseLighting(chunkBlocks, incomingSky, chunkLightLevels);
    }

    const bool chunkHasTranslucentBlocks =
        std::any_of(chunkBlocks.begin(), chunkBlocks.end(), [](BlockId block) noexcept
        {
            return block != BlockId::Water && isTranslucentBlock(block);
        });

    const ChunkNeighborhoodSnapshot neighborhood =
        captureChunkNeighborhoodSnapshot(chunk, chunkBlocks, chunkLightLevels);

    (void)rebuildChunkWaterResources(chunk, chunkBlocks, chunkLightLevels);

    MeshData meshData;

    const int baseWorldX = chunk.coord.x * kChunkSizeX;
    const int baseWorldY = chunk.minWorldY;
    const int baseWorldZ = chunk.coord.z * kChunkSizeZ;
    const glm::vec3 chunkOrigin(static_cast<float>(baseWorldX), static_cast<float>(baseWorldY), static_cast<float>(baseWorldZ));
    std::array<std::uint8_t, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> grassTintByColumn{};
    for (int localX = 0; localX < kChunkSizeX; ++localX)
    {
        for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
        {
            const ColumnSample columnSample = sampleColumnReadyOrThrow(baseWorldX + localX,
                                                                       baseWorldZ + localZ,
                                                                       baseWorldY,
                                                                       baseWorldY + kChunkSizeY - 1);
            grassTintByColumn[static_cast<std::size_t>(localZ * kChunkSizeX + localX)] =
                static_cast<std::uint8_t>(grassTintIndexForBiome(columnSample.dominantBiome));
        }
    }

    auto grassTintForLocal = [&](int localX, int localZ) noexcept -> GrassTintIndex
    {
        if (localX < 0 || localX >= kChunkSizeX || localZ < 0 || localZ >= kChunkSizeZ)
        {
            return GrassTintIndex::Default;
        }

        return static_cast<GrassTintIndex>(
            grassTintByColumn[static_cast<std::size_t>(localZ * kChunkSizeX + localX)]);
    };

    auto isInsideChunk = [](const glm::ivec3& local) noexcept
    {
        return local.x >= 0 && local.x < kChunkSizeX &&
               local.y >= 0 && local.y < kChunkSizeY &&
               local.z >= 0 && local.z < kChunkSizeZ;
    };

    auto sampleBlock = [&](int lx, int ly, int lz) -> BlockId
    {
        return neighborhood.blockAt(lx, ly, lz);
    };

    auto samplePackedLight = [&](int lx, int ly, int lz) -> std::uint8_t
    {
        return neighborhood.lightAt(lx, ly, lz);
    };

    enum class Axis : int { X = 0, Y = 1, Z = 2 };
    enum class FaceDir : int { Negative = 0, Positive = 1 };

    struct FaceMaterial
    {
        glm::vec2 uvBase{0.0f};
        glm::vec2 uvSize{1.0f};
        glm::ivec3 uAxis{1, 0, 0};
        glm::ivec3 vAxis{0, 1, 0};
        BlockFace face{BlockFace::Top};
        BlockId blockId{BlockId::Air};
        std::array<std::uint32_t, 4> lightingData{};
        std::uint8_t flags{0};
        bool alphaCutout{false};
        bool mergeable{true};

        bool operator==(const FaceMaterial& other) const noexcept
        {
            return uvBase == other.uvBase &&
                   uvSize == other.uvSize &&
                   uAxis == other.uAxis &&
                   vAxis == other.vAxis &&
                   face == other.face &&
                   blockId == other.blockId &&
                   lightingData == other.lightingData &&
                   flags == other.flags &&
                   alphaCutout == other.alphaCutout &&
                   mergeable == other.mergeable;
        }
    };

    struct MaskCell
    {
        bool exists{false};
        FaceMaterial material{};
    };

	    const std::array<glm::vec3, 3> axisNormals{
	        glm::vec3{1.0f, 0.0f, 0.0f},
	        glm::vec3{0.0f, 1.0f, 0.0f},
	        glm::vec3{0.0f, 0.0f, 1.0f}
	    };

        constexpr std::array<int, 4> kCornerUSigns{-1, 1, 1, -1};
        constexpr std::array<int, 4> kCornerVSigns{-1, -1, 1, 1};

	    auto faceFromNormal = [](const glm::vec3& normal) noexcept -> BlockFace
	    {
	        if (normal.y > 0.5f) return BlockFace::Top;
	        if (normal.y < -0.5f) return BlockFace::Bottom;
	        if (normal.x > 0.5f) return BlockFace::East;
	        if (normal.x < -0.5f) return BlockFace::West;
	        if (normal.z > 0.5f) return BlockFace::South;
	        return BlockFace::North;
	    };

	    auto faceSampleAxes = [](BlockFace face, glm::ivec3& uAxis, glm::ivec3& vAxis) noexcept
	    {
	        switch (face)
	        {
	        case BlockFace::Top:
	        case BlockFace::Bottom:
	            uAxis = glm::ivec3(1, 0, 0);
	            vAxis = glm::ivec3(0, 0, 1);
	            break;
	        case BlockFace::East:
	        case BlockFace::West:
	            uAxis = glm::ivec3(0, 1, 0);
	            vAxis = glm::ivec3(0, 0, 1);
	            break;
	        case BlockFace::South:
	        case BlockFace::North:
	        default:
	            uAxis = glm::ivec3(1, 0, 0);
	            vAxis = glm::ivec3(0, 1, 0);
	            break;
	        }
	    };

	    auto buildCornerLighting = [&](BlockFace face, const glm::ivec3& owningLocal) -> std::array<std::uint32_t, 4>
	    {
	        std::array<std::uint32_t, 4> cornerLighting{};
	        const glm::ivec3 outward = faceOffset(face);
	        glm::ivec3 sideU{0};
	        glm::ivec3 sideV{0};
	        faceSampleAxes(face, sideU, sideV);

	        for (std::size_t cornerIndex = 0; cornerIndex < cornerLighting.size(); ++cornerIndex)
	        {
	            const int uSign = kCornerUSigns[cornerIndex];
	            const int vSign = kCornerVSigns[cornerIndex];
	            const glm::ivec3 fallbackSample = owningLocal + outward;
	            const std::array<glm::ivec3, 4> lightSamples{
	                fallbackSample,
	                fallbackSample + sideU * uSign,
	                fallbackSample + sideV * vSign,
	                fallbackSample + sideU * uSign + sideV * vSign
	            };

	            int skySum = 0;
	            int blockSum = 0;
	            int validSamples = 0;
	            for (const glm::ivec3& samplePos : lightSamples)
	            {
	                const BlockId sampleLightBlock = sampleBlock(samplePos.x, samplePos.y, samplePos.z);
	                if (isOpaqueForLighting(sampleLightBlock))
	                {
	                    continue;
	                }

	                const std::uint8_t packedLight = samplePackedLight(samplePos.x, samplePos.y, samplePos.z);
	                skySum += static_cast<int>(skyLightFromPacked(packedLight));
	                blockSum += static_cast<int>(blockLightFromPacked(packedLight));
	                ++validSamples;
	            }

	            std::uint8_t averagedSky = 0;
	            std::uint8_t averagedBlock = 0;
	            if (validSamples > 0)
	            {
	                averagedSky = static_cast<std::uint8_t>((skySum + validSamples / 2) / validSamples);
	                averagedBlock = static_cast<std::uint8_t>((blockSum + validSamples / 2) / validSamples);
	            }
	            else
	            {
	                const std::uint8_t fallbackPacked =
	                    samplePackedLight(fallbackSample.x, fallbackSample.y, fallbackSample.z);
	                averagedSky = skyLightFromPacked(fallbackPacked);
	                averagedBlock = blockLightFromPacked(fallbackPacked);
	            }

            const glm::ivec3 aoBase = owningLocal + outward;
            const bool side1Solid =
                isAoSolid(sampleBlock(aoBase.x + sideU.x * uSign,
                                      aoBase.y + sideU.y * uSign,
                                      aoBase.z + sideU.z * uSign));
            const bool side2Solid =
                isAoSolid(sampleBlock(aoBase.x + sideV.x * vSign,
                                      aoBase.y + sideV.y * vSign,
                                      aoBase.z + sideV.z * vSign));
            const bool cornerSolid =
                isAoSolid(sampleBlock(aoBase.x + sideU.x * uSign + sideV.x * vSign,
                                      aoBase.y + sideU.y * uSign + sideV.y * vSign,
                                      aoBase.z + sideU.z * uSign + sideV.z * vSign));
	            const std::uint8_t aoLevel =
	                (side1Solid && side2Solid)
	                    ? static_cast<std::uint8_t>(3)
	                    : static_cast<std::uint8_t>(static_cast<int>(side1Solid) +
	                                                static_cast<int>(side2Solid) +
	                                                static_cast<int>(cornerSolid));

	            cornerLighting[cornerIndex] =
	                packVertexLighting(packLightLevels(averagedSky, averagedBlock), aoLevel);
	        }

	        return cornerLighting;
	    };

	    auto makeMaterial = [&](BlockId block, const glm::vec3& normal, const glm::ivec3& owningLocal) -> FaceMaterial
	    {
	        FaceMaterial material{};
	        const BlockFace face = faceFromNormal(normal);

	        material.face = face;
            material.blockId = block;
            material.lightingData = buildCornerLighting(face, owningLocal);
            material.alphaCutout = isAlphaCutoutBlock(block);
	        material.mergeable =
	            !isAlphaCutoutBlock(block) && hasUniformCornerLighting(material.lightingData);

	        if (blockAtlasConfigured_)
	        {
	            const BlockUVSet& uvSet = blockUVTable_[toIndex(block)];
	            const FaceUV& faceUV = uvSet.faces[toIndex(face)];
            material.uvBase = faceUV.base;
            material.uvSize = faceUV.size;
        }
        else
        {
            material.uvBase = glm::vec2(0.0f);
            material.uvSize = glm::vec2(1.0f);
        }

        switch (face)
        {
        case BlockFace::Top:
            material.uAxis = glm::ivec3(1, 0, 0);
            material.vAxis = glm::ivec3(0, 0, 1);
            break;
        case BlockFace::Bottom:
            material.uAxis = glm::ivec3(1, 0, 0);
            material.vAxis = glm::ivec3(0, 0, -1);
            break;
        case BlockFace::East:
            material.uAxis = glm::ivec3(0, 0, 1);
            material.vAxis = glm::ivec3(0, 1, 0);
            break;
        case BlockFace::West:
            material.uAxis = glm::ivec3(0, 0, -1);
            material.vAxis = glm::ivec3(0, 1, 0);
            break;
        case BlockFace::South:
            material.uAxis = glm::ivec3(-1, 0, 0);
            material.vAxis = glm::ivec3(0, 1, 0);
            break;
        case BlockFace::North:
        default:
            material.uAxis = glm::ivec3(1, 0, 0);
            material.vAxis = glm::ivec3(0, 1, 0);
            break;
        }

        if (block == BlockId::Grass)
        {
            const GrassTintIndex tintIndex = grassTintForLocal(owningLocal.x, owningLocal.z);
            if (face == BlockFace::Top)
            {
                material.flags = packGrassTintFlags(tintIndex, false);
            }
            else if (face != BlockFace::Bottom)
            {
                material.flags = packGrassTintFlags(tintIndex, true);
            }
        }

        return material;
    };

    auto emitQuad = [&](Axis axis, FaceDir dir, int slice, int bStart, int cStart, int bSize, int cSize, const FaceMaterial& material)
    {
        const int a = static_cast<int>(axis);
        const int b = (a + 1) % 3;
        const int c = (a + 2) % 3;

        glm::vec3 normal = axisNormals[a];
        if (dir == FaceDir::Negative)
        {
            normal = -normal;
        }

        glm::vec3 base(0.0f);
        base[a] = static_cast<float>(slice);
        base[b] = static_cast<float>(bStart);
        base[c] = static_cast<float>(cStart);

        glm::vec3 du(0.0f);
        du[b] = static_cast<float>(bSize);

        glm::vec3 dv(0.0f);
        dv[c] = static_cast<float>(cSize);

        std::array<glm::vec3, 4> positions{
            chunkOrigin + base,
            chunkOrigin + base + du,
            chunkOrigin + base + du + dv,
            chunkOrigin + base + dv
        };

            std::array<std::uint32_t, 4> cornerLighting = material.lightingData;
	        if (dir == FaceDir::Negative)
	        {
	            std::swap(positions[1], positions[3]);
	        }

            std::array<std::uint32_t, 4> vertexLighting{};
            const glm::vec3 quadCenter = 0.25f * (positions[0] + positions[1] + positions[2] + positions[3]);
            const glm::vec3 uAxisVec = glm::vec3(material.uAxis);
            const glm::vec3 vAxisVec = glm::vec3(material.vAxis);
            for (std::size_t i = 0; i < positions.size(); ++i)
            {
                const glm::vec3 offset = positions[i] - quadCenter;
                const int uSign = glm::dot(offset, uAxisVec) >= 0.0f ? 1 : -1;
                const int vSign = glm::dot(offset, vAxisVec) >= 0.0f ? 1 : -1;
                vertexLighting[i] = cornerLighting[cornerIndexForSigns(uSign, vSign)];
            }

            const int diagonal02 =
                lightingMetricFromPackedVertex(vertexLighting[0]) +
                lightingMetricFromPackedVertex(vertexLighting[2]);
            const int diagonal13 =
                lightingMetricFromPackedVertex(vertexLighting[1]) +
                lightingMetricFromPackedVertex(vertexLighting[3]);
            const bool flipDiagonal = diagonal13 > diagonal02;
            const std::uint32_t alphaCutoutLightingFlag =
                material.alphaCutout ? kLightingFlagAlphaCutoutBitCpu : 0u;

	        const std::size_t vertexStart = meshData.vertices.size();
        for (int i = 0; i < 4; ++i)
        {
            const glm::vec3& pos = positions[i];

            Vertex vertex{};
	            vertex.position = pos;
	            vertex.normal = normal;
	            vertex.tileCoord = glm::vec2(glm::dot(pos, uAxisVec), glm::dot(pos, vAxisVec));
	            vertex.atlasBase = material.uvBase;
	            vertex.atlasSize = material.uvSize;
	            vertex.lightingData =
                    applyVertexFlags(vertexLighting[i], material.flags) | alphaCutoutLightingFlag;
                vertex.blockId = static_cast<std::uint32_t>(material.blockId);
	            meshData.vertices.push_back(vertex);
	        }

            if (flipDiagonal)
            {
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 0));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 1));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 3));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 1));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 2));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 3));
            }
            else
            {
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 0));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 1));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 2));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 2));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 3));
	            meshData.indices.push_back(static_cast<std::uint32_t>(vertexStart + 0));
            }
	    };

    auto greedyMeshAxis = [&](Axis axis)
    {
        const int dims[3] = {kChunkSizeX, kChunkSizeY, kChunkSizeZ};
        const int a = static_cast<int>(axis);
        const int b = (a + 1) % 3;
        const int c = (a + 2) % 3;

        const int sizeA = dims[a];
        const int sizeB = dims[b];
        const int sizeC = dims[c];

        std::vector<MaskCell> mask(static_cast<std::size_t>(sizeB * sizeC));

        auto maskIndex = [&](int bi, int ci) -> int
        {
            return bi * sizeC + ci;
        };

        for (int dirIndex = 0; dirIndex < 2; ++dirIndex)
        {
            const FaceDir dir = static_cast<FaceDir>(dirIndex);

            for (int slice = 0; slice <= sizeA; ++slice)
            {
                std::fill(mask.begin(), mask.end(), MaskCell{});

                for (int bi = 0; bi < sizeB; ++bi)
                {
                    for (int ci = 0; ci < sizeC; ++ci)
                    {
                        const int maskIdx = maskIndex(bi, ci);
                        MaskCell cell{};

                        const glm::ivec3 positiveLocal{
                            (a == 0) ? slice : ((b == 0) ? bi : ci),
                            (a == 1) ? slice : ((b == 1) ? bi : ci),
                            (a == 2) ? slice : ((b == 2) ? bi : ci)
                        };

                        const glm::ivec3 negativeLocal{
                            (a == 0) ? slice - 1 : ((b == 0) ? bi : ci),
                            (a == 1) ? slice - 1 : ((b == 1) ? bi : ci),
                            (a == 2) ? slice - 1 : ((b == 2) ? bi : ci)
                        };

                        const BlockId positiveBlock = sampleBlock(positiveLocal.x, positiveLocal.y, positiveLocal.z);
                        const BlockId negativeBlock = sampleBlock(negativeLocal.x, negativeLocal.y, negativeLocal.z);

                        glm::ivec3 owningLocal{0};
                        bool createFace = false;

                        if (dir == FaceDir::Positive)
                        {
                            if (isInsideChunk(negativeLocal) && shouldRenderBlockFace(negativeBlock, positiveBlock))
                            {
                                owningLocal = negativeLocal;
                                createFace = true;
                            }
                        }
                        else
                        {
                            if (isInsideChunk(positiveLocal) && shouldRenderBlockFace(positiveBlock, negativeBlock))
                            {
                                owningLocal = positiveLocal;
                                createFace = true;
                            }
                        }

	                        if (createFace)
	                        {
	                            const glm::vec3 normal = axisNormals[a] * ((dir == FaceDir::Positive) ? 1.0f : -1.0f);
	                            cell.exists = true;
	                            const std::size_t blockIdx = blockIndex(owningLocal.x, owningLocal.y, owningLocal.z);
	                            const BlockId owningBlock = chunkBlocks[blockIdx];
	                            cell.material = makeMaterial(
	                                owningBlock,
	                                normal,
	                                owningLocal);
	                        }

                        mask[maskIdx] = cell;
                    }
                }

                for (int bi = 0; bi < sizeB; ++bi)
                {
                    int ci = 0;
                    while (ci < sizeC)
                    {
                        const int maskIdx = maskIndex(bi, ci);
                        const MaskCell& cell = mask[maskIdx];
                        if (!cell.exists)
                        {
                            ++ci;
                            continue;
                        }

                        const FaceMaterial material = cell.material;

                        int runLengthC = 1;
                        while (material.mergeable && ci + runLengthC < sizeC)
                        {
                            const MaskCell& nextCell = mask[maskIndex(bi, ci + runLengthC)];
                            if (!nextCell.exists || !(nextCell.material == material))
                            {
                                break;
                            }
                            ++runLengthC;
                        }

                        int runHeightB = 1;
                        while (material.mergeable && bi + runHeightB < sizeB)
                        {
                            bool rowMatches = true;
                            for (int offset = 0; offset < runLengthC; ++offset)
                            {
                                const MaskCell& rowCell = mask[maskIndex(bi + runHeightB, ci + offset)];
                                if (!rowCell.exists || !(rowCell.material == material))
                                {
                                    rowMatches = false;
                                    break;
                                }
                            }

                            if (!rowMatches)
                            {
                                break;
                            }

                            ++runHeightB;
                        }

                        emitQuad(axis, dir, slice, bi, ci, runHeightB, runLengthC, material);

                        for (int bOffset = 0; bOffset < runHeightB; ++bOffset)
                        {
                            for (int cOffset = 0; cOffset < runLengthC; ++cOffset)
                            {
                                mask[maskIndex(bi + bOffset, ci + cOffset)].exists = false;
                            }
                        }

                        ci += runLengthC;
                    }
                }
            }
        }
    };

    greedyMeshAxis(Axis::X);
    greedyMeshAxis(Axis::Y);
    greedyMeshAxis(Axis::Z);

    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        // Keep the previously uploaded mesh alive until the replacement mesh is fully built.
        // Clearing meshData at the start of remeshing lets stale queued uploads observe an
        // empty mesh and momentarily punch holes in the world.
        chunk.meshData = std::move(meshData);
    }
    chunk.hasTranslucentBlocks.store(chunkHasTranslucentBlocks, std::memory_order_release);
    chunk.meshReady.store(true, std::memory_order_release);
}

glm::ivec3 ChunkManager::Impl::worldToChunkCoords(int worldX, int worldY, int worldZ) noexcept
{
    return {floorDiv(worldX, kChunkSizeX), floorDiv(worldY, kChunkSizeY), floorDiv(worldZ, kChunkSizeZ)};
}

glm::ivec2 ChunkManager::Impl::residencyColumnForChunk(const glm::ivec3& coord) noexcept
{
    return {coord.x, coord.z};
}

ChunkManager::Impl::RenderSpatialBucketKey
ChunkManager::Impl::renderSpatialBucketKeyForChunk(const glm::ivec3& coord) noexcept
{
    return RenderSpatialBucketKey{
        floorDiv(coord.x, kRenderSpatialBucketSizeChunks),
        floorDiv(coord.z, kRenderSpatialBucketSizeChunks)};
}

ChunkManager::Impl::EvictionBucketRect
ChunkManager::Impl::evictionBucketRectForQuery(const glm::ivec3& center, int horizontalThreshold) noexcept
{
    return EvictionBucketRect{
        floorDiv(center.x - horizontalThreshold, kRenderSpatialBucketSizeChunks),
        floorDiv(center.x + horizontalThreshold, kRenderSpatialBucketSizeChunks),
        floorDiv(center.z - horizontalThreshold, kRenderSpatialBucketSizeChunks),
        floorDiv(center.z + horizontalThreshold, kRenderSpatialBucketSizeChunks)};
}

bool ChunkManager::Impl::evictionQueryMatches(const EvictionQueryState& lhs,
                                              const EvictionQueryState& rhs) noexcept
{
    return lhs.centerChunk == rhs.centerChunk &&
           lhs.evictionCenterY == rhs.evictionCenterY &&
           lhs.horizontalThreshold == rhs.horizontalThreshold &&
           lhs.verticalRadius == rhs.verticalRadius &&
           lhs.evictionSlack == rhs.evictionSlack &&
           lhs.activeBucketRect == rhs.activeBucketRect;
}

void ChunkManager::Impl::insertResidencyColumnMember(const glm::ivec3& coord,
                                                     const RenderSpatialBucketKey& bucket)
{
    const glm::ivec2 column = residencyColumnForChunk(coord);
    auto& bucketEntry = renderSpatialBuckets_[bucket];
    if (std::find(bucketEntry.columns.begin(), bucketEntry.columns.end(), column) == bucketEntry.columns.end())
    {
        bucketEntry.columns.push_back(column);
    }

    auto& columnEntry = residencyColumns_[column];
    auto insertIt = std::lower_bound(columnEntry.chunkCoordsByY.begin(),
                                     columnEntry.chunkCoordsByY.end(),
                                     coord.y,
                                     [](const glm::ivec3& lhs, int rhsY)
                                     {
                                         return lhs.y < rhsY;
                                     });
    if (insertIt != columnEntry.chunkCoordsByY.end() && *insertIt == coord)
    {
        return;
    }

    columnEntry.chunkCoordsByY.insert(insertIt, coord);
    ++columnEntry.membershipVersion;
    evictionColumnCache_.erase(column);
}

void ChunkManager::Impl::removeResidencyColumnMember(const glm::ivec3& coord,
                                                     const RenderSpatialBucketKey& bucket,
                                                     const glm::ivec2& column)
{
    bool columnStillPresent = false;
    auto columnIt = residencyColumns_.find(column);
    if (columnIt != residencyColumns_.end())
    {
        auto& members = columnIt->second.chunkCoordsByY;
        auto memberIt = std::lower_bound(members.begin(),
                                         members.end(),
                                         coord.y,
                                         [](const glm::ivec3& lhs, int rhsY)
                                         {
                                             return lhs.y < rhsY;
                                         });
        if (memberIt != members.end() && *memberIt == coord)
        {
            members.erase(memberIt);
            ++columnIt->second.membershipVersion;
            evictionColumnCache_.erase(column);
        }

        columnStillPresent = !members.empty();
        if (!columnStillPresent)
        {
            residencyColumns_.erase(columnIt);
            evictionColumnCache_.erase(column);
        }
    }

    auto bucketIt = renderSpatialBuckets_.find(bucket);
    if (bucketIt == renderSpatialBuckets_.end())
    {
        return;
    }

    if (!columnStillPresent)
    {
        auto& bucketColumns = bucketIt->second.columns;
        bucketColumns.erase(std::remove(bucketColumns.begin(), bucketColumns.end(), column), bucketColumns.end());
    }

    if (bucketIt->second.coords.empty() && bucketIt->second.columns.empty())
    {
        renderSpatialBuckets_.erase(bucketIt);
    }
}

void ChunkManager::Impl::clearResidencyIndex()
{
    std::lock_guard<std::mutex> lock(renderRegistryMutex_);
    renderRegistry_.clear();
    renderSpatialBuckets_.clear();
    residencyColumns_.clear();
    evictionColumnCache_.clear();
}

void ChunkManager::Impl::registerChunkRenderRegistryEntry(const glm::ivec3& coord,
                                                          const std::shared_ptr<Chunk>& chunk)
{
    if (!chunk)
    {
        return;
    }

    const RenderSpatialBucketKey bucket = renderSpatialBucketKeyForChunk(coord);
    const glm::ivec2 column = residencyColumnForChunk(coord);
    std::lock_guard<std::mutex> lock(renderRegistryMutex_);
    auto [it, inserted] = renderRegistry_.emplace(coord, RenderRegistryEntry{chunk, bucket, column});
    if (!inserted)
    {
        const RenderSpatialBucketKey oldBucket = it->second.bucket;
        const glm::ivec2 oldColumn = it->second.column;
        it->second.chunk = chunk;
        if (!(oldBucket == bucket))
        {
            auto oldBucketIt = renderSpatialBuckets_.find(oldBucket);
            if (oldBucketIt != renderSpatialBuckets_.end())
            {
                auto& oldCoords = oldBucketIt->second.coords;
                oldCoords.erase(std::remove(oldCoords.begin(), oldCoords.end(), coord), oldCoords.end());
            }
            removeResidencyColumnMember(coord, oldBucket, oldColumn);
        }
        it->second.bucket = bucket;
        it->second.column = column;
    }

    ResidencyBucketEntry& bucketEntry = renderSpatialBuckets_[bucket];
    if (std::find(bucketEntry.coords.begin(), bucketEntry.coords.end(), coord) == bucketEntry.coords.end())
    {
        bucketEntry.coords.push_back(coord);
    }
    insertResidencyColumnMember(coord, bucket);
}

void ChunkManager::Impl::unregisterChunkRenderRegistryEntry(const glm::ivec3& coord)
{
    std::lock_guard<std::mutex> lock(renderRegistryMutex_);
    const auto entryIt = renderRegistry_.find(coord);
    if (entryIt == renderRegistry_.end())
    {
        return;
    }

    const RenderSpatialBucketKey bucket = entryIt->second.bucket;
    const glm::ivec2 column = entryIt->second.column;
    renderRegistry_.erase(entryIt);

    const auto bucketIt = renderSpatialBuckets_.find(bucket);
    if (bucketIt != renderSpatialBuckets_.end())
    {
        auto& bucketCoords = bucketIt->second.coords;
        bucketCoords.erase(std::remove(bucketCoords.begin(), bucketCoords.end(), coord), bucketCoords.end());
    }
    removeResidencyColumnMember(coord, bucket, column);
}

void ChunkManager::Impl::collectRenderRegistryCandidates(const glm::ivec3& cameraChunk,
                                                         int horizontalRadius,
                                                         std::vector<std::shared_ptr<Chunk>>& outChunks) const
{
    outChunks.clear();
    const int minChunkX = cameraChunk.x - horizontalRadius;
    const int maxChunkX = cameraChunk.x + horizontalRadius;
    const int minChunkZ = cameraChunk.z - horizontalRadius;
    const int maxChunkZ = cameraChunk.z + horizontalRadius;
    const RenderSpatialBucketKey minBucket{
        floorDiv(minChunkX, kRenderSpatialBucketSizeChunks),
        floorDiv(minChunkZ, kRenderSpatialBucketSizeChunks)};
    const RenderSpatialBucketKey maxBucket{
        floorDiv(maxChunkX, kRenderSpatialBucketSizeChunks),
        floorDiv(maxChunkZ, kRenderSpatialBucketSizeChunks)};

    std::lock_guard<std::mutex> lock(renderRegistryMutex_);
    const std::size_t reserveEstimate =
        static_cast<std::size_t>(std::max(1, maxBucket.x - minBucket.x + 1)) *
        static_cast<std::size_t>(std::max(1, maxBucket.z - minBucket.z + 1)) *
        static_cast<std::size_t>(kRenderSpatialBucketSizeChunks * kRenderSpatialBucketSizeChunks);
    outChunks.reserve((std::max)(outChunks.capacity(), reserveEstimate));
    for (int bucketZ = minBucket.z; bucketZ <= maxBucket.z; ++bucketZ)
    {
        for (int bucketX = minBucket.x; bucketX <= maxBucket.x; ++bucketX)
        {
            const auto bucketIt = renderSpatialBuckets_.find(RenderSpatialBucketKey{bucketX, bucketZ});
            if (bucketIt == renderSpatialBuckets_.end())
            {
                continue;
            }

            for (const glm::ivec3& coord : bucketIt->second.coords)
            {
                const auto entryIt = renderRegistry_.find(coord);
                if (entryIt == renderRegistry_.end())
                {
                    continue;
                }

                if (coord.x < minChunkX || coord.x > maxChunkX ||
                    coord.z < minChunkZ || coord.z > maxChunkZ)
                {
                    continue;
                }

                if (std::shared_ptr<Chunk> chunk = entryIt->second.chunk.lock())
                {
                    outChunks.push_back(std::move(chunk));
                }
            }
        }
    }
}

void ChunkManager::Impl::enqueueEvictionDiscoveryColumn(const glm::ivec2& column)
{
    if (pendingEvictionDiscoveryColumnSet_.insert(column).second)
    {
        pendingEvictionDiscoveryColumns_.push_back(column);
    }
}

void ChunkManager::Impl::enqueuePendingEvictionCandidate(const glm::ivec3& coord)
{
    if (pendingEvictionCandidateSet_.insert(coord).second)
    {
        pendingEvictionCandidates_.push_back(coord);
    }
}

void ChunkManager::Impl::collectActiveBucketColumns(const EvictionBucketRect& rect,
                                                    std::vector<glm::ivec2>& outColumns) const
{
    outColumns.clear();
    std::lock_guard<std::mutex> lock(renderRegistryMutex_);
    for (int bucketZ = rect.minZ; bucketZ <= rect.maxZ; ++bucketZ)
    {
        for (int bucketX = rect.minX; bucketX <= rect.maxX; ++bucketX)
        {
            const auto bucketIt = renderSpatialBuckets_.find(RenderSpatialBucketKey{bucketX, bucketZ});
            if (bucketIt == renderSpatialBuckets_.end())
            {
                continue;
            }

            outColumns.insert(outColumns.end(), bucketIt->second.columns.begin(), bucketIt->second.columns.end());
        }
    }
}

void ChunkManager::Impl::collectResidencyBucketCoords(const EvictionBucketRect& rect,
                                                      std::vector<glm::ivec3>& outCoords) const
{
    outCoords.clear();
    std::lock_guard<std::mutex> lock(renderRegistryMutex_);
    for (int bucketZ = rect.minZ; bucketZ <= rect.maxZ; ++bucketZ)
    {
        for (int bucketX = rect.minX; bucketX <= rect.maxX; ++bucketX)
        {
            const auto bucketIt = renderSpatialBuckets_.find(RenderSpatialBucketKey{bucketX, bucketZ});
            if (bucketIt == renderSpatialBuckets_.end())
            {
                continue;
            }

            outCoords.insert(outCoords.end(), bucketIt->second.coords.begin(), bucketIt->second.coords.end());
        }
    }
}

void ChunkManager::Impl::enqueueEvictionDiscoveryColumnsForBucketRect(const EvictionBucketRect& rect)
{
    std::vector<glm::ivec2> columns;
    collectActiveBucketColumns(rect, columns);
    for (const glm::ivec2& column : columns)
    {
        enqueueEvictionDiscoveryColumn(column);
    }
}

void ChunkManager::Impl::enqueueEvictionDiscoveryColumnsForBucketShell(const EvictionBucketRect& rect)
{
    std::vector<glm::ivec2> columns;
    std::lock_guard<std::mutex> lock(renderRegistryMutex_);
    for (int bucketZ = rect.minZ; bucketZ <= rect.maxZ; ++bucketZ)
    {
        for (int bucketX = rect.minX; bucketX <= rect.maxX; ++bucketX)
        {
            const bool boundaryBucket =
                bucketX == rect.minX || bucketX == rect.maxX || bucketZ == rect.minZ || bucketZ == rect.maxZ;
            if (!boundaryBucket)
            {
                continue;
            }

            const auto bucketIt = renderSpatialBuckets_.find(RenderSpatialBucketKey{bucketX, bucketZ});
            if (bucketIt == renderSpatialBuckets_.end())
            {
                continue;
            }

            columns.insert(columns.end(), bucketIt->second.columns.begin(), bucketIt->second.columns.end());
        }
    }

    for (const glm::ivec2& column : columns)
    {
        enqueueEvictionDiscoveryColumn(column);
    }
}

void ChunkManager::Impl::enqueueEvictionDiscoveryColumnsForBucketDelta(const EvictionBucketRect& previousRect,
                                                                       const EvictionBucketRect& currentRect)
{
    std::vector<glm::ivec2> columns;
    const auto contains = [](const EvictionBucketRect& rect, int bucketX, int bucketZ) noexcept
    {
        return bucketX >= rect.minX && bucketX <= rect.maxX &&
               bucketZ >= rect.minZ && bucketZ <= rect.maxZ;
    };

    std::lock_guard<std::mutex> lock(renderRegistryMutex_);
    for (int bucketZ = previousRect.minZ; bucketZ <= previousRect.maxZ; ++bucketZ)
    {
        for (int bucketX = previousRect.minX; bucketX <= previousRect.maxX; ++bucketX)
        {
            if (contains(currentRect, bucketX, bucketZ))
            {
                continue;
            }

            const auto bucketIt = renderSpatialBuckets_.find(RenderSpatialBucketKey{bucketX, bucketZ});
            if (bucketIt == renderSpatialBuckets_.end())
            {
                continue;
            }

            columns.insert(columns.end(), bucketIt->second.columns.begin(), bucketIt->second.columns.end());
        }
    }

    for (int bucketZ = currentRect.minZ; bucketZ <= currentRect.maxZ; ++bucketZ)
    {
        for (int bucketX = currentRect.minX; bucketX <= currentRect.maxX; ++bucketX)
        {
            if (contains(previousRect, bucketX, bucketZ))
            {
                continue;
            }

            const auto bucketIt = renderSpatialBuckets_.find(RenderSpatialBucketKey{bucketX, bucketZ});
            if (bucketIt == renderSpatialBuckets_.end())
            {
                continue;
            }

            columns.insert(columns.end(), bucketIt->second.columns.begin(), bucketIt->second.columns.end());
        }
    }

    for (const glm::ivec2& column : columns)
    {
        enqueueEvictionDiscoveryColumn(column);
    }
}

void ChunkManager::Impl::updateEvictionDiscovery(const EvictionQueryState& query)
{
    if (lastEvictionQueryStateValid_ && evictionQueryMatches(lastEvictionQueryState_, query))
    {
        return;
    }

    const bool havePrevious = lastEvictionQueryStateValid_;
    const bool horizontalChanged =
        !havePrevious ||
        query.centerChunk.x != lastEvictionQueryState_.centerChunk.x ||
        query.centerChunk.z != lastEvictionQueryState_.centerChunk.z ||
        query.horizontalThreshold != lastEvictionQueryState_.horizontalThreshold ||
        !(query.activeBucketRect == lastEvictionQueryState_.activeBucketRect);
    const bool verticalChanged =
        !havePrevious ||
        query.centerChunk.y != lastEvictionQueryState_.centerChunk.y ||
        query.evictionCenterY != lastEvictionQueryState_.evictionCenterY ||
        query.verticalRadius != lastEvictionQueryState_.verticalRadius ||
        query.evictionSlack != lastEvictionQueryState_.evictionSlack;

    if (verticalChanged)
    {
        enqueueEvictionDiscoveryColumnsForBucketRect(query.activeBucketRect);
    }
    else if (horizontalChanged)
    {
        if (havePrevious)
        {
            enqueueEvictionDiscoveryColumnsForBucketDelta(lastEvictionQueryState_.activeBucketRect, query.activeBucketRect);
            enqueueEvictionDiscoveryColumnsForBucketShell(lastEvictionQueryState_.activeBucketRect);
        }
        enqueueEvictionDiscoveryColumnsForBucketShell(query.activeBucketRect);
    }

    lastEvictionQueryState_ = query;
    lastEvictionQueryStateValid_ = true;
}

void ChunkManager::Impl::evaluateEvictionColumn(const glm::ivec2& column, const EvictionQueryState& query)
{
    std::vector<glm::ivec3> memberCoords;
    std::uint64_t membershipVersion = 0;
    ColumnChunkIntervals intervals{};
    bool haveIntervals = false;

    {
        std::lock_guard<std::mutex> lock(renderRegistryMutex_);
        const auto columnIt = residencyColumns_.find(column);
        if (columnIt == residencyColumns_.end())
        {
            evictionColumnCache_.erase(column);
            return;
        }

        memberCoords = columnIt->second.chunkCoordsByY;
        membershipVersion = columnIt->second.membershipVersion;

        const auto cacheIt = evictionColumnCache_.find(column);
        if (cacheIt != evictionColumnCache_.end() &&
            cacheIt->second.membershipVersion == membershipVersion &&
            cacheIt->second.queryGeneration == query.generation)
        {
            intervals = cacheIt->second.intervals;
            haveIntervals = true;
        }
    }

    if (!haveIntervals)
    {
        const int worldX = column.x * kChunkSizeX + kChunkSizeX / 2;
        const int worldZ = column.y * kChunkSizeZ + kChunkSizeZ / 2;
        int columnHeight = ColumnManager::kNoHeight;
        if (!tryGetCachedColumnHeight(column, worldX, worldZ, columnHeight) && !stationaryExactFillModeActive_)
        {
            requestColumnHeightPrefetch(column, ColumnHeightPrefetchPriority::Normal);
        }

        intervals = columnIntervalsForHeight(column,
                                             {query.centerChunk.x, query.centerChunk.z},
                                             query.evictionCenterY,
                                             query.verticalRadius,
                                             columnHeight);

        std::lock_guard<std::mutex> lock(renderRegistryMutex_);
        const auto columnIt = residencyColumns_.find(column);
        if (columnIt != residencyColumns_.end())
        {
            evictionColumnCache_[column] = EvictionColumnCacheEntry{
                columnHeight,
                intervals,
                membershipVersion,
                query.generation};
        }
    }

    {
        std::lock_guard<std::mutex> lock(renderRegistryMutex_);
        const auto columnIt = residencyColumns_.find(column);
        if (columnIt != residencyColumns_.end())
        {
            columnIt->second.lastEvictionQueryGeneration = query.generation;
        }
    }

    for (const glm::ivec3& coord : memberCoords)
    {
        if (coord.y < 0)
        {
            enqueuePendingEvictionCandidate(coord);
            continue;
        }

        const int horizontalDistance =
            std::max(std::abs(coord.x - query.centerChunk.x), std::abs(coord.z - query.centerChunk.z));
        if (horizontalDistance > query.horizontalThreshold)
        {
            enqueuePendingEvictionCandidate(coord);
            continue;
        }

        if (chunkYDistanceToIntervals(coord.y, intervals, query.evictionSlack) > 0)
        {
            enqueuePendingEvictionCandidate(coord);
        }
    }
}

void ChunkManager::Impl::drainPendingEvictionDiscovery(const EvictionQueryState& query)
{
    constexpr std::size_t kEvictionDiscoveryColumnBudget = 512;
    std::size_t processedColumns = 0;
    while (processedColumns < kEvictionDiscoveryColumnBudget && !pendingEvictionDiscoveryColumns_.empty())
    {
        const glm::ivec2 column = pendingEvictionDiscoveryColumns_.front();
        pendingEvictionDiscoveryColumns_.pop_front();
        pendingEvictionDiscoveryColumnSet_.erase(column);
        evaluateEvictionColumn(column, query);
        ++processedColumns;
    }
}

bool ChunkManager::Impl::tryMarkChunkForRetire(const glm::ivec3& coord)
{
    std::shared_ptr<Chunk> chunk;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        const auto it = chunks_.find(coord);
        if (it == chunks_.end() || !it->second)
        {
            return false;
        }

        chunk = it->second;
        if (chunk->inFlight.load(std::memory_order_acquire) != 0)
        {
            return false;
        }
        if (chunk->exactGpuBuildInFlight.load(std::memory_order_acquire) ||
            chunk->exactGpuPublishPending.load(std::memory_order_acquire))
        {
            return false;
        }

        if (chunk->pendingRetire.exchange(true, std::memory_order_acq_rel))
        {
            return false;
        }

        clearPendingExactGpuBuildCount(*chunk);
        chunk->queuedForUpload.store(false, std::memory_order_release);
        chunk->queuedUploadBucket.store(std::numeric_limits<std::uint8_t>::max(), std::memory_order_release);
        chunk->uploadQueueTicket.store(0, std::memory_order_release);
        chunk->queuedForCommit.store(false, std::memory_order_release);
        chunk->commitQueueTicket.store(0, std::memory_order_release);
        chunk->exactGpuBuildQueued.store(false, std::memory_order_release);
        chunk->exactGpuPreferDenseUpload.store(false, std::memory_order_release);
        chunk->residencyMode.store(ExactChunkResidencyMode::GpuPendingRetire, std::memory_order_release);

        unregisterChunkRenderRegistryEntry(coord);
        chunks_.erase(it);
        denseTrackedCoords_.erase(coord);
    }

    {
        std::lock_guard<std::mutex> lock(dedicatedLocalUploadMutex_);
        queuedDedicatedLocalUploads_.erase(coord);
    }

    clearDeferredChunkDependencies(coord);
    clearStreamingChunkLifecycleState(coord);
    pendingChunkRetires_.push_back(PendingChunkRetire{coord, std::move(chunk)});
    return true;
}

void ChunkManager::Impl::drainPendingChunkRetires()
{
    constexpr std::size_t kPendingRetireChunkCap = 32;
    constexpr double kPendingRetireTimeBudgetMs = 2.0;
    const auto start = std::chrono::steady_clock::now();

    std::vector<glm::ivec3> retiredCoords;
    retiredCoords.reserve(kPendingRetireChunkCap);

    std::size_t retiredCount = 0;
    while (retiredCount < kPendingRetireChunkCap && !pendingChunkRetires_.empty())
    {
        if (retiredCount > 0)
        {
            const double elapsedMs =
                std::chrono::duration<double, std::milli>(std::chrono::steady_clock::now() - start).count();
            if (elapsedMs >= kPendingRetireTimeBudgetMs)
            {
                break;
            }
        }

        PendingChunkRetire pending = std::move(pendingChunkRetires_.front());
        pendingChunkRetires_.pop_front();
        if (!pending.chunk)
        {
            continue;
        }

        retiredCoords.push_back(pending.coord);
        recycleChunkGPU(*pending.chunk);
        recycleChunkObject(std::move(pending.chunk));
        ++retiredCount;
    }

    if (!retiredCoords.empty())
    {
        columnManager_.removeChunks(std::span<const glm::ivec3>(retiredCoords.data(), retiredCoords.size()));
        for (const glm::ivec3& coord : retiredCoords)
        {
            invalidatePredictedColumn({coord.x, coord.z});
            markSkyLightColumnDirty({coord.x, coord.z});
        }
    }
}

void ChunkManager::Impl::setDenseTrackedCoord(const glm::ivec3& coord, bool tracked)
{
    std::lock_guard<std::mutex> lock(chunksMutex);
    if (tracked)
    {
        denseTrackedCoords_.insert(coord);
    }
    else
    {
        denseTrackedCoords_.erase(coord);
    }
}

void ChunkManager::Impl::collectDenseResidencyCandidateCoords(const glm::ivec3& centerChunk,
                                                              int horizontalRadius,
                                                              std::vector<glm::ivec3>& outCoords) const
{
    outCoords.clear();

    std::unordered_set<glm::ivec3, ChunkHasher> seen;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        seen.reserve(denseTrackedCoords_.size());
        for (const glm::ivec3& coord : denseTrackedCoords_)
        {
            if (seen.insert(coord).second)
            {
                outCoords.push_back(coord);
            }
        }
    }

    std::vector<glm::ivec3> bucketCoords;
    collectResidencyBucketCoords(evictionBucketRectForQuery(centerChunk, horizontalRadius), bucketCoords);
    seen.reserve(seen.size() + bucketCoords.size());
    for (const glm::ivec3& coord : bucketCoords)
    {
        if (seen.insert(coord).second)
        {
            outCoords.push_back(coord);
        }
    }
}

std::shared_ptr<Chunk> ChunkManager::Impl::acquireChunk(const glm::ivec3& coord)
{
    std::shared_ptr<Chunk> chunk;
    {
        std::lock_guard<std::mutex> lock(chunkPoolMutex_);
        if (!chunkPool_.empty())
        {
            PooledChunkEntry entry = std::move(chunkPool_.back());
            chunkPool_.pop_back();
            chunkPoolBytes_ = (entry.retainedBytes >= chunkPoolBytes_) ? 0 : (chunkPoolBytes_ - entry.retainedBytes);
            chunk = std::move(entry.chunk);
        }
    }

    if (!chunk)
    {
        chunk = std::make_shared<Chunk>(coord);
    }

    chunk->reset(coord);
    return chunk;

}

std::shared_ptr<Chunk> ChunkManager::Impl::getChunkShared(const glm::ivec3& coord) noexcept
{
    std::lock_guard<std::mutex> lock(chunksMutex);
    auto it = chunks_.find(coord);
    return (it != chunks_.end()) ? it->second : nullptr;
}

std::shared_ptr<const Chunk> ChunkManager::Impl::getChunkShared(const glm::ivec3& coord) const noexcept
{
    std::lock_guard<std::mutex> lock(chunksMutex);
    auto it = chunks_.find(coord);
    if (it != chunks_.end())
    {
        return it->second;
    }
    return nullptr;
}

Chunk* ChunkManager::Impl::getChunk(const glm::ivec3& coord) noexcept
{
    return getChunkShared(coord).get();
}

const Chunk* ChunkManager::Impl::getChunk(const glm::ivec3& coord) const noexcept
{
    return getChunkShared(coord).get();
}

void ChunkManager::Impl::markNeighborsForRemeshingIfNeeded(const glm::ivec3& coord, int localX, int localY, int localZ)
{
    auto queueNeighbor = [&](const glm::ivec3& neighborCoord)
    {
        auto neighbor = getChunkShared(neighborCoord);
        if (!neighbor)
        {
            return;
        }

        requestChunkRemesh(neighbor, true);
    };

    if (localX == 0)
    {
        queueNeighbor(coord + glm::ivec3{-1, 0, 0});
    }

    if (localX == kChunkSizeX - 1)
    {
        queueNeighbor(coord + glm::ivec3{1, 0, 0});
    }

    if (localZ == 0)
    {
        queueNeighbor(coord + glm::ivec3{0, 0, -1});
    }

    if (localZ == kChunkSizeZ - 1)
    {
        queueNeighbor(coord + glm::ivec3{0, 0, 1});

    }

    if (localY == 0)
    {
        queueNeighbor(coord + glm::ivec3{0, -1, 0});
    }

    if (localY == kChunkSizeY - 1)
    {
        queueNeighbor(coord + glm::ivec3{0, 1, 0});
    }
}

void ChunkManager::Impl::requestChunkRemesh(const std::shared_ptr<Chunk>& chunk, bool localInteractionPriority)
{
    if (!chunk)
    {
        return;
    }

    if (localInteractionPriority)
    {
        refinementBackpressureActive_.store(true, std::memory_order_release);
    }

    const ChunkState state = chunk->state.load(std::memory_order_acquire);
    if (state == ChunkState::Generating)
    {
        chunk->pendingMeshRefresh.store(true, std::memory_order_release);
        if (shouldTrackRecentEditChunk(chunk->coord))
        {
            std::ostringstream stream;
            stream << "remesh defer chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z
                   << ") state=" << chunkStateLabel(state)
                   << " inFlight=" << chunk->inFlight.load(std::memory_order_acquire);
            appendRecentEditDebugEvent(stream.str());
        }
        return;
    }

    const bool cpuVisibleAuthority = chunkUsesCpuNearRendering(*chunk);
    if (device_ != nullptr && exactGpuContext_.ready() && !cpuVisibleAuthority)
    {
        if (benchmarkMetrics_.isEnabled())
        {
            storeFirstBenchmarkTimestamp(chunk->meshQueuedTimestampMicros, steadyMicrosNow());
        }
        queueChunkForExactGpuRefresh(chunk, localInteractionPriority);
        return;
    }

    if (!chunk->hasBlocks.load(std::memory_order_acquire) &&
        chunk->indexCount.load(std::memory_order_acquire) == 0)
    {
        return;
    }

    if (state == ChunkState::Meshing)
    {
        chunk->pendingMeshRefresh.store(true, std::memory_order_release);
        if (shouldTrackRecentEditChunk(chunk->coord))
        {
            std::ostringstream stream;
            stream << "remesh defer chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z
                   << ") state=" << chunkStateLabel(state)
                   << " inFlight=" << chunk->inFlight.load(std::memory_order_acquire);
            appendRecentEditDebugEvent(stream.str());
        }
        return;
    }

    if (state == ChunkState::Remeshing)
    {
        if (chunk->inFlight.load(std::memory_order_acquire) > 0)
        {
            chunk->pendingMeshRefresh.store(true, std::memory_order_release);
            if (shouldTrackRecentEditChunk(chunk->coord))
            {
                std::ostringstream stream;
                stream << "remesh refresh-pending chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z
                       << ") inFlight=" << chunk->inFlight.load(std::memory_order_acquire);
                appendRecentEditDebugEvent(stream.str());
            }
            return;
        }
    }

    if (state == ChunkState::Uploaded || state == ChunkState::Ready || state == ChunkState::Remeshing)
    {
        chunk->state.store(ChunkState::Remeshing, std::memory_order_release);
        if (benchmarkMetrics_.isEnabled())
        {
            storeFirstBenchmarkTimestamp(chunk->meshQueuedTimestampMicros, steadyMicrosNow());
        }
        enqueueJob(chunk,
                   JobType::Mesh,
                   chunk->coord,
                   0,
                   chunkAwaitingInitialVisibleReady(*chunk),
                   classifyJobServiceClass(chunkAwaitingInitialVisibleReady(*chunk),
                                           localInteractionPriority,
                                           false));
        if (shouldTrackRecentEditChunk(chunk->coord))
        {
            std::ostringstream stream;
            stream << "remesh enqueue chunk=(" << chunk->coord.x << ", " << chunk->coord.y << ", " << chunk->coord.z
                   << ") prevState=" << chunkStateLabel(state)
                   << " idx=" << chunk->indexCount.load(std::memory_order_acquire);
            appendRecentEditDebugEvent(stream.str());
        }
    }
}

void ChunkManager::Impl::requestChunkRemeshFromRelight(const std::shared_ptr<Chunk>& chunk)
{
    if (!chunk)
    {
        return;
    }

    const ChunkState state = chunk->state.load(std::memory_order_acquire);
    if (state == ChunkState::Generating)
    {
        chunk->pendingMeshRefresh.store(true, std::memory_order_release);
        return;
    }

    const bool cpuVisibleAuthority = chunkUsesCpuNearRendering(*chunk);
    if (device_ != nullptr && exactGpuContext_.ready() && !cpuVisibleAuthority)
    {
        if (benchmarkMetrics_.isEnabled())
        {
            storeFirstBenchmarkTimestamp(chunk->meshQueuedTimestampMicros, steadyMicrosNow());
        }
        queueChunkForExactGpuRefresh(chunk, false);
        return;
    }

    if (!chunk->hasBlocks.load(std::memory_order_acquire) &&
        chunk->indexCount.load(std::memory_order_acquire) == 0)
    {
        return;
    }

    if (state == ChunkState::Meshing)
    {
        chunk->pendingMeshRefresh.store(true, std::memory_order_release);
        return;
    }

    const int inFlight = chunk->inFlight.load(std::memory_order_acquire);
    if (state == ChunkState::Remeshing && inFlight > 1)
    {
        chunk->pendingMeshRefresh.store(true, std::memory_order_release);
        return;
    }

    if (state == ChunkState::Uploaded || state == ChunkState::Ready || state == ChunkState::Remeshing)
    {
        chunk->state.store(ChunkState::Remeshing, std::memory_order_release);
        if (benchmarkMetrics_.isEnabled())
        {
            storeFirstBenchmarkTimestamp(chunk->meshQueuedTimestampMicros, steadyMicrosNow());
        }
        enqueueJob(chunk,
                   JobType::Mesh,
                   chunk->coord,
                   0,
                   chunkAwaitingInitialVisibleReady(*chunk),
                   classifyJobServiceClass(chunkAwaitingInitialVisibleReady(*chunk),
                                           false,
                                           true));
    }
}

bool ChunkManager::Impl::relightRegionsOverlap(const glm::ivec3& minA,
                                               const glm::ivec3& maxA,
                                               const glm::ivec3& minB,
                                               const glm::ivec3& maxB) noexcept
{
    return minA.x <= maxB.x && maxA.x >= minB.x &&
           minA.y <= maxB.y && maxA.y >= minB.y &&
           minA.z <= maxB.z && maxA.z >= minB.z;
}

glm::ivec3 ChunkManager::Impl::relightRegionAnchor(const PendingRelightBatch& batch) noexcept
{
    return glm::ivec3((batch.minCoord.x + batch.maxCoord.x) / 2,
                      (batch.minCoord.y + batch.maxCoord.y) / 2,
                      (batch.minCoord.z + batch.maxCoord.z) / 2);
}

void ChunkManager::Impl::recomputePendingRelightBatchBounds(PendingRelightBatch& batch) const noexcept
{
    if (batch.dirtyCoordGenerations.empty())
    {
        batch = PendingRelightBatch{};
        return;
    }

    bool first = true;
    std::uint64_t maxGeneration = 0;
    for (const auto& [coord, generation] : batch.dirtyCoordGenerations)
    {
        if (first)
        {
            batch.minCoord = coord;
            batch.maxCoord = coord;
            first = false;
        }
        else
        {
            batch.minCoord = glm::min(batch.minCoord, coord);
            batch.maxCoord = glm::max(batch.maxCoord, coord);
        }
        maxGeneration = std::max(maxGeneration, generation);
    }

    batch.reservedMinCoord = batch.minCoord - kRelightReservationPadding;
    batch.reservedMaxCoord = batch.maxCoord + kRelightReservationPadding;
    batch.maxGeneration = maxGeneration;
    batch.valid = true;
}

void ChunkManager::Impl::mergePendingRelightBatch(PendingRelightBatch& dst, PendingRelightBatch&& src) const
{
    for (auto& [coord, generation] : src.dirtyCoordGenerations)
    {
        auto [it, inserted] = dst.dirtyCoordGenerations.try_emplace(coord, generation);
        if (!inserted)
        {
            it->second = std::max(it->second, generation);
        }
    }
    dst.forceRemeshCoords.insert(src.forceRemeshCoords.begin(), src.forceRemeshCoords.end());
    dst.containsInitialReadyCoord = dst.containsInitialReadyCoord || src.containsInitialReadyCoord;
    dst.sequence = (dst.sequence == 0) ? src.sequence : std::min(dst.sequence, src.sequence);
    dst.estimatedCostUnits = 0;
    recomputePendingRelightBatchBounds(dst);
}

std::unordered_set<glm::ivec3, ChunkHasher> ChunkManager::Impl::expandRelightCoords(
    const RelightCoordGenerationMap& dirtyCoords) const
{
    std::unordered_set<glm::ivec3, ChunkHasher> expanded;
    expanded.reserve(dirtyCoords.size() * 27);

    for (const auto& [coord, _] : dirtyCoords)
    {
        for (int dx = -kRelightNeighborPadding.x; dx <= kRelightNeighborPadding.x; ++dx)
        {
            for (int dy = -kRelightNeighborPadding.y; dy <= kRelightNeighborPadding.y; ++dy)
            {
                for (int dz = -kRelightNeighborPadding.z; dz <= kRelightNeighborPadding.z; ++dz)
                {
                    expanded.insert(coord + glm::ivec3(dx, dy, dz));
                }
            }
        }
    }

    return expanded;
}

std::uint64_t ChunkManager::Impl::estimatePendingRelightBatchCost(const PendingRelightBatch& batch) const
{
    if (!batch.valid || batch.dirtyCoordGenerations.empty())
    {
        return 0;
    }

    const std::unordered_set<glm::ivec3, ChunkHasher> expandedCoords = expandRelightCoords(batch.dirtyCoordGenerations);
    std::unordered_set<glm::ivec3, ChunkHasher> loadedRegionCoords;
    std::unordered_set<glm::ivec3, ChunkHasher> externalCoords;
    std::unordered_map<glm::ivec2, int, ColumnHasher> maxLoadedChunkYByColumn;

    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        loadedRegionCoords.reserve(expandedCoords.size());

        for (const glm::ivec3& coord : expandedCoords)
        {
            auto it = chunks_.find(coord);
            if (it == chunks_.end())
            {
                continue;
            }

            loadedRegionCoords.insert(coord);
            const glm::ivec2 column(coord.x, coord.z);
            auto [columnIt, inserted] = maxLoadedChunkYByColumn.try_emplace(column, coord.y);
            if (!inserted)
            {
                columnIt->second = std::max(columnIt->second, coord.y);
            }
        }

        for (const glm::ivec3& coord : loadedRegionCoords)
        {
            for (BlockFace face : {BlockFace::Top, BlockFace::Bottom, BlockFace::North, BlockFace::South, BlockFace::East, BlockFace::West})
            {
                const glm::ivec3 neighborCoord = coord + faceOffset(face);
                if (loadedRegionCoords.find(neighborCoord) != loadedRegionCoords.end())
                {
                    continue;
                }

                if (chunks_.find(neighborCoord) != chunks_.end())
                {
                    externalCoords.insert(neighborCoord);
                }
            }
        }

        for (const auto& [coord, chunk] : chunks_)
        {
            (void)chunk;
            const glm::ivec2 column(coord.x, coord.z);
            auto maxIt = maxLoadedChunkYByColumn.find(column);
            if (maxIt != maxLoadedChunkYByColumn.end() && coord.y > maxIt->second)
            {
                externalCoords.insert(coord);
            }
        }
    }

    const std::uint64_t regionChunkCount = static_cast<std::uint64_t>(loadedRegionCoords.size());
    const std::uint64_t externalChunkCount = static_cast<std::uint64_t>(externalCoords.size());
    const std::uint64_t dirtyCoordCount = static_cast<std::uint64_t>(batch.dirtyCoordGenerations.size());
    const std::uint64_t forceRemeshCount = static_cast<std::uint64_t>(batch.forceRemeshCoords.size());

    const std::uint64_t estimatedCost =
        regionChunkCount * 2048ull +
        externalChunkCount * 4096ull +
        dirtyCoordCount * 1024ull +
        forceRemeshCount * 512ull;
    return std::max<std::uint64_t>(estimatedCost, 1ull);
}

void ChunkManager::Impl::queueSkyLightColumnVisualRefresh(const glm::ivec2& column, bool localInteractionPriority)
{
    std::lock_guard<std::mutex> lock(queuedSkyLightColumnRefreshMutex_);
    auto [it, inserted] = queuedSkyLightColumnRefreshes_.try_emplace(column, localInteractionPriority);
    if (!inserted && localInteractionPriority)
    {
        it->second = true;
    }
}

void ChunkManager::Impl::markSkyLightColumnDirty(const glm::ivec2& column)
{
    std::lock_guard<std::mutex> lock(skyLightCacheMutex_);
    auto [it, inserted] = skyLightColumnGenerations_.try_emplace(column, 1ull);
    if (!inserted)
    {
        ++it->second;
        if (it->second == 0)
        {
            it->second = 1;
        }
    }
}

std::uint64_t ChunkManager::Impl::currentSkyLightColumnGeneration(const glm::ivec2& column)
{
    std::lock_guard<std::mutex> lock(skyLightCacheMutex_);
    auto [it, inserted] = skyLightColumnGenerations_.try_emplace(column, 1ull);
    if (inserted && it->second == 0)
    {
        it->second = 1;
    }
    return it->second;
}

void ChunkManager::Impl::refreshExactGpuColumnVisualsAfterSkyLightChange(const glm::ivec2& column,
                                                                         bool localInteractionPriority)
{
    std::vector<std::shared_ptr<Chunk>> columnChunks;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        columnChunks.reserve(16);
        for (const auto& [coord, chunk] : chunks_)
        {
            if (coord.x == column.x && coord.z == column.y)
            {
                columnChunks.push_back(chunk);
            }
        }
    }

    if (columnChunks.empty())
    {
        return;
    }

    ensureSkyLightColumnCacheForChunks(columnChunks);

    for (const auto& chunk : columnChunks)
    {
        if (!chunk)
        {
            continue;
        }

        const bool needsVisualRefresh =
            chunk->hasBlocks.load(std::memory_order_acquire) ||
            chunk->exactGpuResident.load(std::memory_order_acquire) ||
            chunkAwaitingInitialVisibleReady(*chunk);
        if (!needsVisualRefresh)
        {
            continue;
        }

    chunk->exactGpuInputsVersion.fetch_add(1, std::memory_order_acq_rel);
    chunk->exactGpuInputsDirty.store(true, std::memory_order_release);
    refreshPendingExactGpuBuildCount(*chunk);
        requestChunkRemesh(chunk, localInteractionPriority);
    }
}

void ChunkManager::Impl::applyQueuedSkyLightColumnVisualRefreshes()
{
    std::unordered_map<glm::ivec2, bool, ColumnHasher> pending;
    {
        std::lock_guard<std::mutex> lock(queuedSkyLightColumnRefreshMutex_);
        if (queuedSkyLightColumnRefreshes_.empty())
        {
            return;
        }
        pending.swap(queuedSkyLightColumnRefreshes_);
    }

    for (const auto& [column, localInteractionPriority] : pending)
    {
        (void)localInteractionPriority;
        markSkyLightColumnDirty(column);
    }
}

void ChunkManager::Impl::queueFarTerrainInvalidation(const glm::ivec3& worldPos)
{
    std::lock_guard<std::mutex> lock(queuedFarInvalidationMutex_);
    if (!queuedFarInvalidationValid_)
    {
        queuedFarInvalidationValid_ = true;
        queuedFarInvalidationMin_ = worldPos;
        queuedFarInvalidationMax_ = worldPos;
        return;
    }

    queuedFarInvalidationMin_ = glm::min(queuedFarInvalidationMin_, worldPos);
    queuedFarInvalidationMax_ = glm::max(queuedFarInvalidationMax_, worldPos);
}

void ChunkManager::Impl::applyQueuedFarTerrainInvalidations()
{
    glm::ivec3 minWorld{0};
    glm::ivec3 maxWorld{0};
    {
        std::lock_guard<std::mutex> lock(queuedFarInvalidationMutex_);
        if (!queuedFarInvalidationValid_)
        {
            return;
        }
        queuedFarInvalidationValid_ = false;
        minWorld = queuedFarInvalidationMin_;
        maxWorld = queuedFarInvalidationMax_;
    }

    farTerrainManager_.invalidateWorldBounds(minWorld, maxWorld);
}

void ChunkManager::Impl::queueLocalEditBatch(const glm::ivec3& anchorCoord,
                                             std::unordered_set<glm::ivec3, ChunkHasher> touchedChunks,
                                             bool forceRemesh)
{
    if (touchedChunks.empty())
    {
        touchedChunks.insert(anchorCoord);
    }

    std::lock_guard<std::mutex> lock(queuedLocalEditMutex_);
    LocalEditBatch& batch = queuedLocalEditBatches_[anchorCoord];
    batch.forceRemesh = batch.forceRemesh || forceRemesh;
    batch.touchedChunks.insert(touchedChunks.begin(), touchedChunks.end());
}

void ChunkManager::Impl::processPendingLocalEditBatches()
{
    std::unordered_map<glm::ivec3, LocalEditBatch, ChunkHasher> pending;
    {
        std::lock_guard<std::mutex> lock(queuedLocalEditMutex_);
        if (queuedLocalEditBatches_.empty())
        {
            return;
        }

        pending.swap(queuedLocalEditBatches_);
    }

    for (auto& [anchorCoord, batch] : pending)
    {
        (void)anchorCoord;

        PendingRelightBatch relightBatch{};
        relightBatch.valid = true;
        relightBatch.sequence = 0;
        for (const glm::ivec3& coord : batch.touchedChunks)
        {
            const std::uint64_t generation = nextRelightGeneration_++;
            relightBatch.dirtyCoordGenerations.emplace(coord, generation);
            if (batch.forceRemesh)
            {
                relightBatch.forceRemeshCoords.insert(coord);
            }

            if (auto chunk = getChunkShared(coord))
            {
                chunk->lightingRevision.store(generation, std::memory_order_release);
            }
        }

        recomputePendingRelightBatchBounds(relightBatch);
        relightBatch.estimatedCostUnits = estimatePendingRelightBatchCost(relightBatch);
        profilingCounters_.relightBatches.fetch_add(1, std::memory_order_relaxed);
        relightChunkRegion(relightBatch);
    }
}

void ChunkManager::Impl::queueRelightAfterEdit(const glm::ivec3& centerCoord, bool forceRemesh)
{
    std::lock_guard<std::mutex> lock(queuedRelightMutex_);
    auto [it, inserted] = queuedRelightRequests_.try_emplace(centerCoord, forceRemesh);
    if (!inserted && forceRemesh)
    {
        it->second = true;
    }
}

void ChunkManager::Impl::applyQueuedRelightRequests()
{
    std::unordered_map<glm::ivec3, bool, ChunkHasher> pending;
    {
        std::lock_guard<std::mutex> lock(queuedRelightMutex_);
        if (queuedRelightRequests_.empty())
        {
            return;
        }
        pending.swap(queuedRelightRequests_);
    }

    for (const auto& [coord, forceRemesh] : pending)
    {
        queueRelightRequest(coord, forceRemesh);
    }
}

void ChunkManager::Impl::queueChunkForDedicatedLocalUpload(const std::shared_ptr<Chunk>& chunk)
{
    if (!chunk || !chunkUsesCpuNearRendering(*chunk))
    {
        return;
    }

    std::lock_guard<std::mutex> lock(dedicatedLocalUploadMutex_);
    queuedDedicatedLocalUploads_[chunk->coord] = chunk;
}

void ChunkManager::Impl::ensureSkyLightColumnCacheForChunks(const std::vector<std::shared_ptr<Chunk>>& chunks)
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    if (chunks.empty())
    {
        return;
    }

    std::unordered_set<glm::ivec2, ColumnHasher> columns;
    columns.reserve(chunks.size());
    for (const auto& chunk : chunks)
    {
        if (chunk)
        {
            columns.insert(glm::ivec2(chunk->coord.x, chunk->coord.z));
        }
    }

    if (columns.empty())
    {
        return;
    }

    std::unordered_map<glm::ivec2, std::uint64_t, ColumnHasher> columnGenerations;
    columnGenerations.reserve(columns.size());
    for (const glm::ivec2& column : columns)
    {
        columnGenerations.emplace(column, currentSkyLightColumnGeneration(column));
    }

    std::unordered_map<glm::ivec2, std::vector<std::shared_ptr<Chunk>>, ColumnHasher> columnStacks;
    columnStacks.reserve(columns.size());
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        for (const auto& [coord, chunk] : chunks_)
        {
            const glm::ivec2 column(coord.x, coord.z);
            if (columns.find(column) != columns.end())
            {
                columnStacks[column].push_back(chunk);
            }
        }
    }

    std::vector<std::shared_ptr<Chunk>> chunksToLock;
    chunksToLock.reserve(chunks.size());
    for (auto& [column, stack] : columnStacks)
    {
        if (stack.empty())
        {
            continue;
        }

        std::sort(stack.begin(),
                  stack.end(),
                  [](const std::shared_ptr<Chunk>& lhs, const std::shared_ptr<Chunk>& rhs)
                  {
                      return lhs->coord.y > rhs->coord.y;
                  });
        for (auto& chunk : stack)
        {
            chunksToLock.push_back(chunk);
        }
    }

    std::sort(chunksToLock.begin(),
              chunksToLock.end(),
              [](const std::shared_ptr<Chunk>& lhs, const std::shared_ptr<Chunk>& rhs)
              {
                  if (lhs->coord.x != rhs->coord.x)
                  {
                      return lhs->coord.x < rhs->coord.x;
                  }
                  if (lhs->coord.y != rhs->coord.y)
                  {
                      return lhs->coord.y < rhs->coord.y;
                  }
                  return lhs->coord.z < rhs->coord.z;
              });
    chunksToLock.erase(std::unique(chunksToLock.begin(), chunksToLock.end()), chunksToLock.end());

    std::unordered_map<glm::ivec3, std::vector<BlockId>, ChunkHasher> transientBlocks;
    transientBlocks.reserve(chunksToLock.size());
    for (const auto& chunk : chunksToLock)
    {
        if (!chunk || chunk->cpuDataResident.load(std::memory_order_acquire))
        {
            continue;
        }

        ChunkBuildScratch scratch(*chunk);
        std::array<ColumnBuildResult, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> columnResults{};
        buildChunkCpuBlocks(*chunk, scratch, false, columnResults, nullptr);
        transientBlocks.emplace(chunk->coord, std::move(scratch.blocks));
    }

    std::vector<std::unique_lock<std::mutex>> locks;
    locks.reserve(chunksToLock.size());
    const auto lockStageStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    for (auto& chunk : chunksToLock)
    {
        locks.emplace_back(chunk->meshMutex);
    }

    for (auto& [column, stack] : columnStacks)
    {
        const std::uint64_t generation = columnGenerations[column];
        bool needsRefresh = false;
        for (const auto& chunk : stack)
        {
            if (chunk->skyLightCacheGeneration.load(std::memory_order_acquire) != generation)
            {
                needsRefresh = true;
                break;
            }
        }
        if (!needsRefresh)
        {
            continue;
        }

        std::array<std::uint8_t, kChunkSizeX * kChunkSizeZ> incomingSky{};
        incomingSky.fill(kMaxLightLevel);

        for (const auto& chunk : stack)
        {
            chunk->skyLightFromAboveCache = incomingSky;
            chunk->skyLightCacheGeneration.store(generation, std::memory_order_release);

            std::array<std::uint8_t, kChunkSizeX * kChunkSizeZ> outgoingSky = incomingSky;
            for (int localX = 0; localX < kChunkSizeX; ++localX)
            {
                for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
                {
                    const std::size_t columnIndex = static_cast<std::size_t>(localZ * kChunkSizeX + localX);
                    std::uint8_t sky = incomingSky[columnIndex];
                    const std::span<const BlockId> blockSpan =
                        chunk->cpuDataResident.load(std::memory_order_acquire)
                            ? std::span<const BlockId>(chunk->blocks)
                            : [&]() -> std::span<const BlockId>
                            {
                                  auto it = transientBlocks.find(chunk->coord);
                                  if (it == transientBlocks.end())
                                  {
                                      return {};
                                  }
                                  return std::span<const BlockId>(it->second);
                              }();
                    for (int localY = kChunkSizeY - 1; localY >= 0 && sky > 0; --localY)
                    {
                        const BlockId block =
                            blockSpan.empty() ? BlockId::Air : blockSpan[blockIndex(localX, localY, localZ)];
                        if (isOpaqueForLighting(block))
                        {
                            sky = 0;
                            break;
                        }

                        const std::uint8_t attenuation = blockLightingProperties(block).skyAttenuation;
                        sky = static_cast<std::uint8_t>(
                            std::max(0, static_cast<int>(sky) - static_cast<int>(attenuation)));
                    }
                    outgoingSky[columnIndex] = sky;
                }
            }

            incomingSky = outgoingSky;
        }
    }

    if (benchmarkEnabled)
    {
        const auto lockMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(SteadyClock::now() - lockStageStart).count();
        benchmarkMetrics_.skyLightCacheLockStage.recordMicros(static_cast<std::uint64_t>(lockMicros));
    }
}

std::uint64_t ChunkManager::Impl::computeRelightBudgetUnits()
{
    const bool exactOnly = renderSettings_.totalChunks <= renderSettings_.exactChunks;
    const std::size_t latencySensitiveBacklog =
        jobQueue_.outstanding(JobServiceClass::InitialVisible) +
        jobQueue_.outstanding(JobServiceClass::LocalInteraction);
    const bool refinementBackpressure =
        refinementBackpressureActive_.load(std::memory_order_acquire) ||
        latencySensitiveBacklog > 0;
    std::size_t pendingRegionCount = 0;
    {
        std::lock_guard<std::mutex> lock(relightStateMutex_);
        pendingRegionCount = pendingRelightRegions_.size();
    }

    std::uint64_t budget = kRelightBaseBudgetUnits;
    budget += std::min<std::uint64_t>(workerThreadCount_, 4u) * kRelightPerWorkerBudgetUnits;
    budget += std::min<std::uint64_t>(pendingRegionCount * kRelightBacklogBudgetUnitsPerRegion,
                                      kRelightMaxBudgetUnits / 2);
    if (exactOnly)
    {
        budget += 2'000'000ull;
    }
    if (!refinementBackpressure && lastMissingChunks_ == 0)
    {
        budget += 750'000ull;
    }
    if (!refinementBackpressure && !protectedPressureActive_)
    {
        budget += 500'000ull;
    }

    const std::uint64_t uploadPenalty =
        std::min<std::uint64_t>(pendingUploadsLastFrame_ * (exactOnly ? 1024ull : 2048ull),
                                kRelightBaseBudgetUnits / 2);
    budget = (budget > uploadPenalty) ? (budget - uploadPenalty / 2) : budget;
    if (refinementBackpressure)
    {
        const std::uint64_t divisor = severeProtectedPressureActive_ ? 6ull :
                                      (latencySensitiveBacklog > 0 ? 4ull : 3ull);
        budget = std::max(kRelightMinBudgetUnits, budget / divisor);
    }
    return std::clamp<std::uint64_t>(budget, kRelightMinBudgetUnits, kRelightMaxBudgetUnits);
}

int ChunkManager::Impl::computeRelightBatchBudget()
{
    const bool exactOnly = renderSettings_.totalChunks <= renderSettings_.exactChunks;
    const std::size_t latencySensitiveBacklog =
        jobQueue_.outstanding(JobServiceClass::InitialVisible) +
        jobQueue_.outstanding(JobServiceClass::LocalInteraction);
    const bool refinementBackpressure =
        refinementBackpressureActive_.load(std::memory_order_acquire) ||
        latencySensitiveBacklog > 0;
    std::size_t pendingRegionCount = 0;
    {
        std::lock_guard<std::mutex> lock(relightStateMutex_);
        pendingRegionCount = pendingRelightRegions_.size();
    }

    int batchBudget = kRelightMinBatchBudget + static_cast<int>(std::min<std::size_t>(workerThreadCount_, 6) / 2);
    batchBudget += static_cast<int>(std::min<std::size_t>(pendingRegionCount / 12, 3));
    if (exactOnly)
    {
        batchBudget += 3;
    }
    if (pendingUploadsLastFrame_ > 256 && !protectedPressureActive_)
    {
        batchBudget = std::max(kRelightMinBatchBudget, batchBudget - 1);
    }
    if (refinementBackpressure)
    {
        batchBudget = kRelightMinBatchBudget;
    }
    return std::clamp(batchBudget, kRelightMinBatchBudget, kRelightMaxBatchBudget);
}

void ChunkManager::Impl::resetRelightBudgetForFrame()
{
    const std::uint64_t budgetUnits = computeRelightBudgetUnits();
    const int batchBudget = computeRelightBatchBudget();

    std::lock_guard<std::mutex> lock(relightStateMutex_);
    relightBudgetUnitsThisFrame_ = budgetUnits;
    relightBudgetUnitsRemaining_ = budgetUnits;
    relightBatchBudgetThisFrame_ = batchBudget;
    relightBatchBudgetRemaining_ = batchBudget;
}

void ChunkManager::Impl::queueRelightRequest(const glm::ivec3& centerCoord, bool forceRemesh)
{
    if (centerCoord.y < 0)
    {
        return;
    }

    std::shared_ptr<Chunk> chunk = getChunkShared(centerCoord);
    const bool initialReadyCoord =
        chunk && chunkAwaitingInitialVisibleReady(*chunk);
    PendingRelightBatch incoming{};
    std::lock_guard<std::mutex> lock(relightStateMutex_);

    if (auto pendingIt = pendingRelightCoordGenerations_.find(centerCoord);
        pendingIt != pendingRelightCoordGenerations_.end())
    {
        const std::uint64_t pendingGeneration = pendingIt->second;
        for (PendingRelightBatch& pendingBatch : pendingRelightRegions_)
        {
            auto dirtyIt = pendingBatch.dirtyCoordGenerations.find(centerCoord);
            if (dirtyIt == pendingBatch.dirtyCoordGenerations.end())
            {
                continue;
            }

            dirtyIt->second = std::max(dirtyIt->second, pendingGeneration);
            if (forceRemesh)
            {
                pendingBatch.forceRemeshCoords.insert(centerCoord);
            }
            pendingBatch.containsInitialReadyCoord =
                pendingBatch.containsInitialReadyCoord || initialReadyCoord;
            pendingBatch.maxGeneration = std::max(pendingBatch.maxGeneration, dirtyIt->second);
            pendingBatch.estimatedCostUnits = 0;
            break;
        }

        if (chunk)
        {
            chunk->lightingRevision.store(pendingGeneration, std::memory_order_release);
        }
        return;
    }

    const std::uint64_t generation = nextRelightGeneration_++;
    incoming.valid = true;
    incoming.sequence = nextPendingRelightSequence_++;
    incoming.dirtyCoordGenerations.emplace(centerCoord, generation);
    if (forceRemesh)
    {
        incoming.forceRemeshCoords.insert(centerCoord);
    }
    incoming.containsInitialReadyCoord = initialReadyCoord;
    recomputePendingRelightBatchBounds(incoming);

    if (chunk)
    {
        chunk->lightingRevision.store(generation, std::memory_order_release);
    }

    for (auto it = pendingRelightRegions_.begin(); it != pendingRelightRegions_.end();)
    {
        if (incoming.dirtyCoordGenerations.size() + it->dirtyCoordGenerations.size() >
            kRelightMaxPendingDirtyCoordsPerRegion)
        {
            ++it;
            continue;
        }

        if (relightRegionsOverlap(incoming.reservedMinCoord,
                                  incoming.reservedMaxCoord,
                                  it->reservedMinCoord,
                                  it->reservedMaxCoord))
        {
            mergePendingRelightBatch(incoming, std::move(*it));
            it = pendingRelightRegions_.erase(it);
            continue;
        }
        ++it;
    }

    for (const auto& [coord, coordGeneration] : incoming.dirtyCoordGenerations)
    {
        auto [it, inserted] = pendingRelightCoordGenerations_.try_emplace(coord, coordGeneration);
        if (!inserted)
        {
            it->second = std::max(it->second, coordGeneration);
        }
    }
    incoming.estimatedCostUnits = 0;
    pendingRelightRegions_.push_back(std::move(incoming));
}

bool ChunkManager::Impl::takePendingRelightBatch(PendingRelightBatch& batch)
{
    glm::ivec3 priorityOrigin{0};
    glm::vec3 priorityForward{0.0f, 0.0f, -1.0f};
    {
        std::lock_guard<std::mutex> priorityLock(schedulingPriorityMutex_);
        priorityOrigin = schedulingPriorityOrigin_;
        priorityForward = schedulingPriorityForward_;
    }

    std::lock_guard<std::mutex> lock(relightStateMutex_);
    if (pendingRelightRegions_.empty() || relightBatchBudgetRemaining_ <= 0)
    {
        batch = PendingRelightBatch{};
        return false;
    }

    auto overlapsActiveRegions = [&](const PendingRelightBatch& candidate) noexcept
    {
        for (const ActiveRelightRegion& region : activeRelightRegions_)
        {
            if (relightRegionsOverlap(candidate.reservedMinCoord,
                                      candidate.reservedMaxCoord,
                                      region.minCoord,
                                      region.maxCoord))
            {
                return true;
            }
        }
        return false;
    };

    const bool allowOverBudgetFallback =
        relightBudgetUnitsRemaining_ == relightBudgetUnitsThisFrame_ &&
        relightBatchBudgetRemaining_ == relightBatchBudgetThisFrame_;

    auto isHigherPriorityBatch = [&](const PendingRelightBatch& lhs, const PendingRelightBatch& rhs) noexcept
    {
        if (lhs.containsInitialReadyCoord != rhs.containsInitialReadyCoord)
        {
            return lhs.containsInitialReadyCoord;
        }

        return isChunkCoordHigherPriority(relightRegionAnchor(lhs),
                                          relightRegionAnchor(rhs),
                                          priorityOrigin,
                                          priorityForward);
    };

    auto bestFitIt = pendingRelightRegions_.end();
    auto bestFallbackIt = pendingRelightRegions_.end();
    for (auto it = pendingRelightRegions_.begin(); it != pendingRelightRegions_.end(); ++it)
    {
        if (!it->valid || overlapsActiveRegions(*it))
        {
            continue;
        }

        if (it->estimatedCostUnits == 0)
        {
            it->estimatedCostUnits = estimatePendingRelightBatchCost(*it);
        }

        if (bestFallbackIt == pendingRelightRegions_.end() ||
            isHigherPriorityBatch(*it, *bestFallbackIt))
        {
            bestFallbackIt = it;
        }

        if (it->estimatedCostUnits <= relightBudgetUnitsRemaining_)
        {
            if (bestFitIt == pendingRelightRegions_.end() ||
                isHigherPriorityBatch(*it, *bestFitIt))
            {
                bestFitIt = it;
            }
        }
    }

    auto chosenIt = bestFitIt;
    if (chosenIt == pendingRelightRegions_.end())
    {
        if (!allowOverBudgetFallback || bestFallbackIt == pendingRelightRegions_.end())
        {
            batch = PendingRelightBatch{};
            return false;
        }
        chosenIt = bestFallbackIt;
    }

    batch = std::move(*chosenIt);
    pendingRelightRegions_.erase(chosenIt);

    for (const auto& [coord, coordGeneration] : batch.dirtyCoordGenerations)
    {
        auto pendingIt = pendingRelightCoordGenerations_.find(coord);
        if (pendingIt != pendingRelightCoordGenerations_.end() && pendingIt->second <= coordGeneration)
        {
            pendingRelightCoordGenerations_.erase(pendingIt);
        }

        auto [activeIt, inserted] = activeRelightCoordGenerations_.try_emplace(coord, coordGeneration);
        if (!inserted)
        {
            activeIt->second = std::max(activeIt->second, coordGeneration);
        }
    }

    activeRelightRegions_.push_back(ActiveRelightRegion{
        batch.reservedMinCoord,
        batch.reservedMaxCoord,
        batch.dirtyCoordGenerations,
        batch.maxGeneration,
        batch.sequence});

    --relightBatchBudgetRemaining_;
    if (batch.estimatedCostUnits >= relightBudgetUnitsRemaining_)
    {
        relightBudgetUnitsRemaining_ = 0;
    }
    else
    {
        relightBudgetUnitsRemaining_ -= batch.estimatedCostUnits;
    }

    return true;
}

void ChunkManager::Impl::releasePendingRelightBatch(const PendingRelightBatch& batch)
{
    if (!batch.valid)
    {
        return;
    }

    std::lock_guard<std::mutex> lock(relightStateMutex_);
    auto activeIt = std::find_if(activeRelightRegions_.begin(),
                                 activeRelightRegions_.end(),
                                 [&](const ActiveRelightRegion& region)
                                 {
                                     return region.sequence == batch.sequence;
                                 });
    if (activeIt != activeRelightRegions_.end())
    {
        activeRelightRegions_.erase(activeIt);
    }

    for (const auto& [coord, coordGeneration] : batch.dirtyCoordGenerations)
    {
        auto coordIt = activeRelightCoordGenerations_.find(coord);
        if (coordIt != activeRelightCoordGenerations_.end() && coordIt->second <= coordGeneration)
        {
            activeRelightCoordGenerations_.erase(coordIt);
        }
    }
}

void ChunkManager::Impl::processPendingRelightRequests(int maxBatches)
{
    if (maxBatches <= 0)
    {
        return;
    }

    const std::size_t latencySensitiveBacklog =
        jobQueue_.outstanding(JobServiceClass::InitialVisible) +
        jobQueue_.outstanding(JobServiceClass::LocalInteraction);
    const bool refinementBackpressure =
        refinementBackpressureActive_.load(std::memory_order_acquire) &&
        latencySensitiveBacklog > 0;
    if (refinementBackpressure)
    {
        maxBatches = 1;
    }

    const int kMaxConcurrentRelightProcessors = refinementBackpressure
        ? 1
        : std::clamp(static_cast<int>(std::max<std::size_t>(workerThreadCount_, 1) / 2), 1, 4);
    int activeProcessors = activeRelightProcessors_.load(std::memory_order_acquire);
    while (activeProcessors < kMaxConcurrentRelightProcessors)
    {
        if (activeRelightProcessors_.compare_exchange_weak(activeProcessors,
                                                           activeProcessors + 1,
                                                           std::memory_order_acq_rel,
                                                           std::memory_order_acquire))
        {
            break;
        }
    }

    if (activeProcessors >= kMaxConcurrentRelightProcessors)
    {
        return;
    }

    struct RelightProcessorGuard
    {
        std::atomic<int>& counter;

        ~RelightProcessorGuard()
        {
            counter.fetch_sub(1, std::memory_order_release);
        }
    } guard{activeRelightProcessors_};

    for (int batchIndex = 0; batchIndex < maxBatches; ++batchIndex)
    {
        PendingRelightBatch batch{};
        if (!takePendingRelightBatch(batch) || !batch.valid)
        {
            return;
        }

        struct RelightBatchReservationGuard
        {
            ChunkManager::Impl& owner;
            PendingRelightBatch& batch;

            ~RelightBatchReservationGuard()
            {
                owner.releasePendingRelightBatch(batch);
            }
        } batchReservationGuard{*this, batch};

        profilingCounters_.relightBatches.fetch_add(1, std::memory_order_relaxed);
        relightChunkRegion(batch);
    }
}

void ChunkManager::Impl::queueChunkForLightingRemesh(const std::shared_ptr<Chunk>& chunk)
{
    requestChunkRemesh(chunk, false);
}

std::uint8_t ChunkManager::Impl::packedLightAtWorld(const glm::ivec3& worldPos) const noexcept
{
    if (worldPos.y < 0)
    {
        return packLightLevels(0, 0);
    }

    const glm::ivec3 chunkCoord = worldToChunkCoords(worldPos.x, worldPos.y, worldPos.z);
    auto chunk = getChunkShared(chunkCoord);
    if (!chunk)
    {
        return packLightLevels(kMaxLightLevel, 0);
    }

    if (worldPos.y < chunk->minWorldY || worldPos.y > chunk->maxWorldY)
    {
        return packLightLevels(kMaxLightLevel, 0);
    }

    const glm::ivec3 local = localBlockCoords(worldPos, chunkCoord);
    if (local.x < 0 || local.x >= kChunkSizeX ||
        local.z < 0 || local.z >= kChunkSizeZ)
    {
        return packLightLevels(kMaxLightLevel, 0);
    }

    if (!chunk->cpuDataResident.load(std::memory_order_acquire) ||
        chunk->lightLevels.size() != static_cast<std::size_t>(kChunkBlockCount))
    {
        return packLightLevels(kMaxLightLevel, 0);
    }

    const int localY = worldPos.y - chunk->minWorldY;
    return chunk->lightLevels[blockIndex(local.x, localY, local.z)];
}

void ChunkManager::Impl::relightChunkRegion(const PendingRelightBatch& batch)
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const SteadyClock::time_point relightStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    const std::unordered_set<glm::ivec3, ChunkHasher> expandedCoords = expandRelightCoords(batch.dirtyCoordGenerations);
    std::vector<std::shared_ptr<Chunk>> regionChunks;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        regionChunks.reserve(expandedCoords.size());
        for (const glm::ivec3& coord : expandedCoords)
        {
            auto it = chunks_.find(coord);
            if (it != chunks_.end())
            {
                regionChunks.push_back(it->second);
            }
        }
    }

    regionChunks.erase(std::remove_if(regionChunks.begin(),
                                      regionChunks.end(),
                                      [](const std::shared_ptr<Chunk>& chunk)
                                      {
                                          return !chunk ||
                                                 chunk->residencyMode.load(std::memory_order_acquire) !=
                                                     ExactChunkResidencyMode::CpuAuthoritative;
                                      }),
                      regionChunks.end());

    if (regionChunks.empty())
    {
        profilingCounters_.relitChunks.fetch_add(1, std::memory_order_relaxed);
        if (benchmarkEnabled)
        {
            benchmarkMetrics_.relightStage.recordMicros(0);
            benchmarkMetrics_.relightRegionChunks.record(0);
            benchmarkMetrics_.relightChangedChunks.record(0);
            benchmarkMetrics_.relightExternalSnapshotChunks.record(0);
            benchmarkMetrics_.relightSkyAboveChunkScans.record(0);
            benchmarkMetrics_.relightSkySeedNodes.record(0);
            benchmarkMetrics_.relightBlockSeedNodes.record(0);
            benchmarkMetrics_.relightSkyNodesProcessed.record(0);
            benchmarkMetrics_.relightBlockNodesProcessed.record(0);
        }
        return;
    }

    for (const auto& chunk : regionChunks)
    {
        if (chunk && !chunk->cpuDataResident.load(std::memory_order_acquire))
        {
            (void)ensureChunkCpuDataResident(*chunk);
        }
    }

    std::sort(regionChunks.begin(),
              regionChunks.end(),
              [](const std::shared_ptr<Chunk>& lhs, const std::shared_ptr<Chunk>& rhs)
              {
                  if (lhs->coord.x != rhs->coord.x)
                  {
                      return lhs->coord.x < rhs->coord.x;
                  }
                  if (lhs->coord.y != rhs->coord.y)
                  {
                      return lhs->coord.y < rhs->coord.y;
                  }
                  return lhs->coord.z < rhs->coord.z;
              });
    regionChunks.erase(std::unique(regionChunks.begin(), regionChunks.end()), regionChunks.end());

    std::unordered_map<glm::ivec3, std::shared_ptr<Chunk>, ChunkHasher> regionLookup;
    regionLookup.reserve(regionChunks.size());
    for (const auto& chunk : regionChunks)
    {
        regionLookup.emplace(chunk->coord, chunk);
        chunk->inFlight.fetch_add(1, std::memory_order_relaxed);
    }

    struct RelightFlightGuard
    {
        std::vector<std::shared_ptr<Chunk>>& chunks;

        ~RelightFlightGuard()
        {
            for (const auto& chunk : chunks)
            {
                if (chunk)
                {
                    chunk->inFlight.fetch_sub(1, std::memory_order_relaxed);
                }
            }
        }
    } relightFlightGuard{regionChunks};

    ensureSkyLightColumnCacheForChunks(regionChunks);

    struct RelightChunkReadSnapshot
    {
        int minWorldY{0};
        int maxWorldY{0};
        std::vector<BlockId> blocks;
        std::vector<std::uint8_t> lightLevels;
    };

    std::unordered_map<glm::ivec3, std::shared_ptr<Chunk>, ChunkHasher> externalSnapshotSources;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        externalSnapshotSources.reserve(regionChunks.size() * 2);

        for (const auto& chunk : regionChunks)
        {
            for (BlockFace face : {BlockFace::Top, BlockFace::Bottom, BlockFace::North, BlockFace::South, BlockFace::East, BlockFace::West})
            {
                const glm::ivec3 neighborCoord = chunk->coord + faceOffset(face);
                if (regionLookup.find(neighborCoord) != regionLookup.end())
                {
                    continue;
                }

                auto it = chunks_.find(neighborCoord);
                if (it != chunks_.end())
                {
                    externalSnapshotSources.try_emplace(neighborCoord, it->second);
                }
            }
        }

        std::unordered_map<glm::ivec2, int, ColumnHasher> maxRegionChunkYByColumn;
        maxRegionChunkYByColumn.reserve(regionChunks.size());
        for (const auto& chunk : regionChunks)
        {
            const glm::ivec2 column(chunk->coord.x, chunk->coord.z);
            auto [it, inserted] = maxRegionChunkYByColumn.try_emplace(column, chunk->coord.y);
            if (!inserted)
            {
                it->second = std::max(it->second, chunk->coord.y);
            }
        }

        for (const auto& [coord, chunk] : chunks_)
        {
            const glm::ivec2 column(coord.x, coord.z);
            auto maxIt = maxRegionChunkYByColumn.find(column);
            if (maxIt != maxRegionChunkYByColumn.end() && coord.y > maxIt->second)
            {
                externalSnapshotSources.try_emplace(coord, chunk);
            }
        }
    }

    std::unordered_map<glm::ivec3, RelightChunkReadSnapshot, ChunkHasher> externalReadSnapshots;
    externalReadSnapshots.reserve(externalSnapshotSources.size());
    for (const auto& [coord, chunk] : externalSnapshotSources)
    {
        if (!chunk ||
            chunk->residencyMode.load(std::memory_order_acquire) != ExactChunkResidencyMode::CpuAuthoritative)
        {
            continue;
        }

        if (!chunk->cpuDataResident.load(std::memory_order_acquire))
        {
            (void)ensureChunkCpuDataResident(*chunk);
        }

        std::lock_guard<std::mutex> lock(chunk->meshMutex);
        RelightChunkReadSnapshot snapshot{};
        snapshot.minWorldY = chunk->minWorldY;
        snapshot.maxWorldY = chunk->maxWorldY;
        snapshot.blocks = chunk->blocks;
        snapshot.lightLevels = chunk->lightLevels;
        externalReadSnapshots.emplace(coord, std::move(snapshot));
    }

    std::vector<std::unique_lock<std::mutex>> locks;
    locks.reserve(regionChunks.size());
    for (auto& chunk : regionChunks)
    {
        locks.emplace_back(chunk->meshMutex);
    }

    std::vector<std::vector<std::uint8_t>> previousLights;
    previousLights.reserve(regionChunks.size());
    std::unordered_map<glm::ivec3, std::size_t, ChunkHasher> regionIndexByCoord;
    regionIndexByCoord.reserve(regionChunks.size());
    for (std::size_t chunkIndex = 0; chunkIndex < regionChunks.size(); ++chunkIndex)
    {
        auto& chunk = regionChunks[chunkIndex];
        previousLights.push_back(chunk->lightLevels);
        chunk->lightBoundaryDirtyMask = 0;
        regionIndexByCoord.emplace(chunk->coord, chunkIndex);
    }

    auto findExternalSnapshot = [&](const glm::ivec3& chunkCoord) -> const RelightChunkReadSnapshot*
    {
        auto it = externalReadSnapshots.find(chunkCoord);
        return (it != externalReadSnapshots.end()) ? &it->second : nullptr;
    };

    struct LightNode
    {
        glm::ivec3 worldPos{0};
        std::uint8_t level{0};
    };

    std::deque<LightNode> skyQueue;
    std::deque<LightNode> blockQueue;
    std::deque<LightNode> skyRemovalQueue;
    std::deque<LightNode> blockRemovalQueue;
    std::uint64_t skyAboveChunkScans = 0;
    std::uint64_t skySeedNodes = 0;
    std::uint64_t blockSeedNodes = 0;
    std::uint64_t skyNodesProcessed = 0;
    std::uint64_t blockNodesProcessed = 0;

    auto accessRegionVoxel = [&](const glm::ivec3& worldPos) -> std::pair<Chunk*, std::size_t>
    {
        const glm::ivec3 chunkCoord = worldToChunkCoords(worldPos.x, worldPos.y, worldPos.z);
        auto it = regionLookup.find(chunkCoord);
        if (it == regionLookup.end())
        {
            return {nullptr, 0};
        }

        const glm::ivec3 local = localBlockCoords(worldPos, chunkCoord);
        if (local.x < 0 || local.x >= kChunkSizeX ||
            local.z < 0 || local.z >= kChunkSizeZ ||
            worldPos.y < it->second->minWorldY ||
            worldPos.y > it->second->maxWorldY)
        {
            return {nullptr, 0};
        }

        const int localY = worldPos.y - it->second->minWorldY;
        return {it->second.get(), blockIndex(local.x, localY, local.z)};
    };

    auto channelFromPacked = [](std::uint8_t packed, bool skyChannel) noexcept -> std::uint8_t
    {
        return skyChannel ? skyLightFromPacked(packed) : blockLightFromPacked(packed);
    };

    auto setPackedChannel = [](std::uint8_t& packed, bool skyChannel, std::uint8_t level) noexcept
    {
        if (skyChannel)
        {
            setSkyLight(packed, level);
        }
        else
        {
            setBlockLight(packed, level);
        }
    };

    std::vector<std::vector<std::uint8_t>> baseLightLevels(
        regionChunks.size(),
        std::vector<std::uint8_t>(kChunkBlockCount, packLightLevels(0, 0)));
    std::unordered_set<glm::ivec2, ColumnHasher> dirtyColumns;
    dirtyColumns.reserve(batch.dirtyCoordGenerations.size());
    for (const auto& [coord, _] : batch.dirtyCoordGenerations)
    {
        dirtyColumns.insert(glm::ivec2(coord.x, coord.z));
    }

    std::unordered_set<glm::ivec3, ChunkHasher> recomputeCoords;
    recomputeCoords.reserve(regionChunks.size());
    for (const auto& chunk : regionChunks)
    {
        if (dirtyColumns.find(glm::ivec2(chunk->coord.x, chunk->coord.z)) != dirtyColumns.end())
        {
            recomputeCoords.insert(chunk->coord);
        }
    }

    auto basePackedAtRegionVoxel = [&](Chunk* chunk, std::size_t idx) -> std::uint8_t
    {
        auto it = regionIndexByCoord.find(chunk->coord);
        if (it == regionIndexByCoord.end())
        {
            return packLightLevels(0, 0);
        }
        return baseLightLevels[it->second][idx];
    };

    auto seedSkyLight = [&](const glm::ivec3& worldPos, std::uint8_t level)
    {
        auto [chunk, idx] = accessRegionVoxel(worldPos);
        if (!chunk || isOpaqueForLighting(chunk->blocks[idx]))
        {
            return;
        }

        if (level > skyLightFromPacked(chunk->lightLevels[idx]))
        {
            setSkyLight(chunk->lightLevels[idx], level);
            if (level > 1)
            {
                skyQueue.push_back({worldPos, level});
                ++skySeedNodes;
            }
        }
    };

    auto seedBlockLight = [&](const glm::ivec3& worldPos, std::uint8_t level)
    {
        auto [chunk, idx] = accessRegionVoxel(worldPos);
        if (!chunk)
        {
            return;
        }

        if (level > blockLightFromPacked(chunk->lightLevels[idx]))
        {
            setBlockLight(chunk->lightLevels[idx], level);
            if (level > 1)
            {
                blockQueue.push_back({worldPos, level});
                ++blockSeedNodes;
            }
        }
    };

    auto packedLightFromBatchSnapshot = [&](const glm::ivec3& worldPos) -> std::uint8_t
    {
        if (worldPos.y < 0)
        {
            return packLightLevels(0, 0);
        }

        const glm::ivec3 chunkCoord = worldToChunkCoords(worldPos.x, worldPos.y, worldPos.z);
        if (auto regionIt = regionLookup.find(chunkCoord); regionIt != regionLookup.end())
        {
            const glm::ivec3 local = localBlockCoords(worldPos, chunkCoord);
            if (local.x < 0 || local.x >= kChunkSizeX ||
                local.z < 0 || local.z >= kChunkSizeZ ||
                worldPos.y < regionIt->second->minWorldY ||
                worldPos.y > regionIt->second->maxWorldY)
            {
                return packLightLevels(kMaxLightLevel, 0);
            }

            const int localY = worldPos.y - regionIt->second->minWorldY;
            return regionIt->second->lightLevels[blockIndex(local.x, localY, local.z)];
        }

        const RelightChunkReadSnapshot* snapshot = findExternalSnapshot(chunkCoord);
        if (!snapshot)
        {
            return packLightLevels(kMaxLightLevel, 0);
        }

        const glm::ivec3 local = localBlockCoords(worldPos, chunkCoord);
        if (local.x < 0 || local.x >= kChunkSizeX ||
            local.z < 0 || local.z >= kChunkSizeZ ||
            worldPos.y < snapshot->minWorldY ||
            worldPos.y > snapshot->maxWorldY)
        {
            return packLightLevels(kMaxLightLevel, 0);
        }

        const int localY = worldPos.y - snapshot->minWorldY;
        return snapshot->lightLevels[blockIndex(local.x, localY, local.z)];
    };

    std::vector<std::shared_ptr<Chunk>> verticalOrder = regionChunks;
    std::sort(verticalOrder.begin(),
              verticalOrder.end(),
              [](const std::shared_ptr<Chunk>& lhs, const std::shared_ptr<Chunk>& rhs)
              {
                  if (lhs->coord.y != rhs->coord.y)
                  {
                      return lhs->coord.y > rhs->coord.y;
                  }
                  if (lhs->coord.x != rhs->coord.x)
                  {
                      return lhs->coord.x < rhs->coord.x;
                  }
                  return lhs->coord.z < rhs->coord.z;
              });

    for (const auto& chunk : verticalOrder)
    {
        auto regionIndexIt = regionIndexByCoord.find(chunk->coord);
        if (regionIndexIt == regionIndexByCoord.end())
        {
            continue;
        }

        auto& baseLights = baseLightLevels[regionIndexIt->second];
        const int baseWorldX = chunk->coord.x * kChunkSizeX;
        const int baseWorldZ = chunk->coord.z * kChunkSizeZ;

        for (int localX = 0; localX < kChunkSizeX; ++localX)
        {
            for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
            {
                const int worldX = baseWorldX + localX;
                const int worldZ = baseWorldZ + localZ;
                const std::size_t columnIndex = static_cast<std::size_t>(localZ * kChunkSizeX + localX);
                std::uint8_t incomingSky = chunk->skyLightFromAboveCache[columnIndex];

                for (int localY = kChunkSizeY - 1; localY >= 0; --localY)
                {
                    const std::size_t idx = blockIndex(localX, localY, localZ);
                    const BlockId block = chunk->blocks[idx];
                    const glm::ivec3 worldPos(worldX, chunk->minWorldY + localY, worldZ);

                    if (isOpaqueForLighting(block))
                    {
                        incomingSky = 0;
                    }
                    else
                    {
                        const std::uint8_t attenuation = blockLightingProperties(block).skyAttenuation;
                        incomingSky = static_cast<std::uint8_t>(
                            std::max(0, static_cast<int>(incomingSky) - static_cast<int>(attenuation)));
                    }

                    setSkyLight(baseLights[idx], incomingSky);
                    const std::uint8_t emission = blockLightingProperties(block).blockEmission;
                    setBlockLight(baseLights[idx], emission);
                }
            }
        }
    }

    for (std::size_t chunkIndex = 0; chunkIndex < regionChunks.size(); ++chunkIndex)
    {
        auto& chunk = regionChunks[chunkIndex];
        if (recomputeCoords.find(chunk->coord) != recomputeCoords.end())
        {
            chunk->lightLevels = baseLightLevels[chunkIndex];
        }
        else
        {
            chunk->lightLevels = previousLights[chunkIndex];
        }
    }

    for (std::size_t chunkIndex = 0; chunkIndex < regionChunks.size(); ++chunkIndex)
    {
        const auto& chunk = regionChunks[chunkIndex];
        if (recomputeCoords.find(chunk->coord) == recomputeCoords.end())
        {
            continue;
        }

        const int baseWorldX = chunk->coord.x * kChunkSizeX;
        const int baseWorldZ = chunk->coord.z * kChunkSizeZ;
        for (int localX = 0; localX < kChunkSizeX; ++localX)
        {
            for (int localY = 0; localY < kChunkSizeY; ++localY)
            {
                for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
                {
                    const std::size_t idx = blockIndex(localX, localY, localZ);
                    const glm::ivec3 worldPos(baseWorldX + localX,
                                              chunk->minWorldY + localY,
                                              baseWorldZ + localZ);
                    const std::uint8_t oldPacked = previousLights[chunkIndex][idx];
                    const std::uint8_t newPacked = chunk->lightLevels[idx];

                    const std::uint8_t oldSky = skyLightFromPacked(oldPacked);
                    const std::uint8_t oldBlock = blockLightFromPacked(oldPacked);
                    const std::uint8_t newSky = skyLightFromPacked(newPacked);
                    const std::uint8_t newBlock = blockLightFromPacked(newPacked);

                    if (oldSky != newSky)
                    {
                        if (oldSky > newSky && oldSky > 1)
                        {
                            skyRemovalQueue.push_back({worldPos, oldSky});
                        }
                        if (newSky > 1)
                        {
                            skyQueue.push_back({worldPos, newSky});
                            ++skySeedNodes;
                        }
                    }

                    if (oldBlock != newBlock)
                    {
                        if (oldBlock > newBlock && oldBlock > 1)
                        {
                            blockRemovalQueue.push_back({worldPos, oldBlock});
                        }
                        if (newBlock > 1)
                        {
                            blockQueue.push_back({worldPos, newBlock});
                            ++blockSeedNodes;
                        }
                    }
                }
            }
        }
    }

    auto propagateLightRemoval = [&](std::deque<LightNode>& removalQueue,
                                     bool skyChannel,
                                     std::deque<LightNode>& addQueue,
                                     std::uint64_t& processedNodeCounter)
    {
        while (!removalQueue.empty())
        {
            const LightNode node = removalQueue.front();
            removalQueue.pop_front();
            ++processedNodeCounter;

            for (BlockFace face : {BlockFace::Top, BlockFace::Bottom, BlockFace::North, BlockFace::South, BlockFace::East, BlockFace::West})
            {
                const glm::ivec3 neighborPos = node.worldPos + faceOffset(face);
                auto [targetChunk, targetIdx] = accessRegionVoxel(neighborPos);
                if (!targetChunk)
                {
                    continue;
                }

                const BlockId targetBlock = targetChunk->blocks[targetIdx];
                if (isOpaqueForLighting(targetBlock))
                {
                    continue;
                }

                const std::uint8_t loss = propagationLossFor(targetBlock);
                if (node.level <= loss)
                {
                    continue;
                }

                const std::uint8_t removedLevel = static_cast<std::uint8_t>(node.level - loss);
                const std::uint8_t existingLevel =
                    channelFromPacked(targetChunk->lightLevels[targetIdx], skyChannel);
                if (existingLevel == 0)
                {
                    continue;
                }

                const std::uint8_t baseLevel =
                    channelFromPacked(basePackedAtRegionVoxel(targetChunk, targetIdx), skyChannel);
                if (existingLevel <= removedLevel)
                {
                    if (existingLevel != baseLevel)
                    {
                        setPackedChannel(targetChunk->lightLevels[targetIdx], skyChannel, baseLevel);
                        if (existingLevel > baseLevel)
                        {
                            removalQueue.push_back({neighborPos, existingLevel});
                        }
                    }

                    if (baseLevel > 1)
                    {
                        addQueue.push_back({neighborPos, baseLevel});
                    }
                }
                else if (existingLevel > 1)
                {
                    addQueue.push_back({neighborPos, existingLevel});
                }
            }
        }
    };

    propagateLightRemoval(skyRemovalQueue, true, skyQueue, skyNodesProcessed);
    propagateLightRemoval(blockRemovalQueue, false, blockQueue, blockNodesProcessed);

    for (auto& chunk : regionChunks)
    {
        for (BlockFace face : {BlockFace::Top, BlockFace::Bottom, BlockFace::North, BlockFace::South, BlockFace::East, BlockFace::West})
        {
            const glm::ivec3 neighborCoord = chunk->coord + faceOffset(face);
            if (regionLookup.find(neighborCoord) != regionLookup.end())
            {
                continue;
            }

            const RelightChunkReadSnapshot* outsideSnapshot = findExternalSnapshot(neighborCoord);
            if (!outsideSnapshot)
            {
                chunk->lightBoundaryDirtyMask |= static_cast<std::uint8_t>(1u << toIndex(face));
                continue;
            }

            const glm::ivec3 offset = faceOffset(face);
            for (int localX = 0; localX < kChunkSizeX; ++localX)
            {
                for (int localY = 0; localY < kChunkSizeY; ++localY)
                {
                    for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
                    {
                        if ((offset.x < 0 && localX != 0) ||
                            (offset.x > 0 && localX != kChunkSizeX - 1) ||
                            (offset.y < 0 && localY != 0) ||
                            (offset.y > 0 && localY != kChunkSizeY - 1) ||
                            (offset.z < 0 && localZ != 0) ||
                            (offset.z > 0 && localZ != kChunkSizeZ - 1))
                        {
                            continue;
                        }

                        const std::size_t idx = blockIndex(localX, localY, localZ);
                        const BlockId block = chunk->blocks[idx];
                        if (isOpaqueForLighting(block))
                        {
                            continue;
                        }

                        const glm::ivec3 worldPos(chunk->coord.x * kChunkSizeX + localX,
                                                  chunk->minWorldY + localY,
                                                  chunk->coord.z * kChunkSizeZ + localZ);
                        const std::uint8_t neighborPacked = packedLightFromBatchSnapshot(worldPos + offset);
                        const std::uint8_t loss = propagationLossFor(block);
                        const std::uint8_t skySeed =
                            (skyLightFromPacked(neighborPacked) > loss)
                                ? static_cast<std::uint8_t>(skyLightFromPacked(neighborPacked) - loss)
                                : 0;
                        const std::uint8_t blockSeed =
                            (blockLightFromPacked(neighborPacked) > loss)
                                ? static_cast<std::uint8_t>(blockLightFromPacked(neighborPacked) - loss)
                                : 0;
                        if (skySeed > 0)
                        {
                            seedSkyLight(worldPos, skySeed);
                        }
                        if (blockSeed > 0)
                        {
                            seedBlockLight(worldPos, blockSeed);
                        }
                    }
                }
            }
        }
    }

    auto propagateLight = [&](std::deque<LightNode>& queue, bool skyChannel, std::uint64_t& processedNodeCounter)
    {
        while (!queue.empty())
        {
            const LightNode node = queue.front();
            queue.pop_front();
            ++processedNodeCounter;

            auto [sourceChunk, sourceIdx] = accessRegionVoxel(node.worldPos);
            if (!sourceChunk)
            {
                continue;
            }

            const std::uint8_t currentLevel =
                skyChannel ? skyLightFromPacked(sourceChunk->lightLevels[sourceIdx])
                           : blockLightFromPacked(sourceChunk->lightLevels[sourceIdx]);
            if (currentLevel != node.level || currentLevel == 0)
            {
                continue;
            }

            for (BlockFace face : {BlockFace::Top, BlockFace::Bottom, BlockFace::North, BlockFace::South, BlockFace::East, BlockFace::West})
            {
                const glm::ivec3 neighborPos = node.worldPos + faceOffset(face);
                auto [targetChunk, targetIdx] = accessRegionVoxel(neighborPos);
                if (!targetChunk)
                {
                    continue;
                }

                const BlockId targetBlock = targetChunk->blocks[targetIdx];
                if (isOpaqueForLighting(targetBlock))
                {
                    continue;
                }

                const std::uint8_t loss = propagationLossFor(targetBlock);
                if (currentLevel <= loss)
                {
                    continue;
                }

                const std::uint8_t nextLevel = static_cast<std::uint8_t>(currentLevel - loss);
                const std::uint8_t existingLevel =
                    skyChannel ? skyLightFromPacked(targetChunk->lightLevels[targetIdx])
                               : blockLightFromPacked(targetChunk->lightLevels[targetIdx]);
                if (nextLevel <= existingLevel)
                {
                    continue;
                }

                if (skyChannel)
                {
                    setSkyLight(targetChunk->lightLevels[targetIdx], nextLevel);
                }
                else
                {
                    setBlockLight(targetChunk->lightLevels[targetIdx], nextLevel);
                }

                if (nextLevel > 1)
                {
                    queue.push_back({neighborPos, nextLevel});
                }
            }
        }
    };

    propagateLight(skyQueue, true, skyNodesProcessed);
    propagateLight(blockQueue, false, blockNodesProcessed);

    std::vector<std::shared_ptr<Chunk>> changedChunks;
    changedChunks.reserve(regionChunks.size());
    std::unordered_set<glm::ivec3, ChunkHasher> changedChunkCoords;
    changedChunkCoords.reserve(regionChunks.size());
    for (std::size_t i = 0; i < regionChunks.size(); ++i)
    {
        if (regionChunks[i]->lightLevels != previousLights[i])
        {
            changedChunkCoords.insert(regionChunks[i]->coord);
            changedChunks.push_back(regionChunks[i]);
        }
    }

    const std::uint64_t relightRegionChunkCount = static_cast<std::uint64_t>(regionChunks.size());
    const std::uint64_t relightChangedChunkCount = static_cast<std::uint64_t>(changedChunks.size());
    const std::uint64_t relightExternalSnapshotChunkCount =
        static_cast<std::uint64_t>(externalReadSnapshots.size());

    locks.clear();

    for (const auto& [coord, generation] : batch.dirtyCoordGenerations)
    {
        auto regionIt = regionLookup.find(coord);
        if (regionIt == regionLookup.end() || !regionIt->second)
        {
            continue;
        }

        if (regionIt->second->lightingRevision.load(std::memory_order_acquire) <= generation)
        {
            regionIt->second->appliedLightingRevision.store(generation, std::memory_order_release);
        }
    }

    for (const auto& chunk : changedChunks)
    {
        requestChunkRemeshFromRelight(chunk);
    }

    if (!batch.forceRemeshCoords.empty())
    {
        for (const glm::ivec3& coord : batch.forceRemeshCoords)
        {
            if (changedChunkCoords.find(coord) != changedChunkCoords.end())
            {
                continue;
            }

            auto chunk = getChunkShared(coord);
            if (!chunk)
            {
                continue;
            }

            requestChunkRemeshFromRelight(chunk);
        }
    }

    const auto relightEnd = SteadyClock::now();
    const auto relightMicros =
        std::chrono::duration_cast<std::chrono::microseconds>(relightEnd - relightStart).count();
    profilingCounters_.relightMicros.fetch_add(relightMicros, std::memory_order_relaxed);
    profilingCounters_.relightRegionChunks.fetch_add(relightRegionChunkCount, std::memory_order_relaxed);
    profilingCounters_.relightChangedChunks.fetch_add(relightChangedChunkCount, std::memory_order_relaxed);
    profilingCounters_.relightExternalSnapshotChunks.fetch_add(relightExternalSnapshotChunkCount, std::memory_order_relaxed);
    profilingCounters_.relightSkyAboveChunkScans.fetch_add(skyAboveChunkScans, std::memory_order_relaxed);
    profilingCounters_.relightSkySeedNodes.fetch_add(skySeedNodes, std::memory_order_relaxed);
    profilingCounters_.relightBlockSeedNodes.fetch_add(blockSeedNodes, std::memory_order_relaxed);
    profilingCounters_.relightSkyNodesProcessed.fetch_add(skyNodesProcessed, std::memory_order_relaxed);
    profilingCounters_.relightBlockNodesProcessed.fetch_add(blockNodesProcessed, std::memory_order_relaxed);
    profilingCounters_.relitChunks.fetch_add(1, std::memory_order_relaxed);
    if (benchmarkEnabled)
    {
        benchmarkMetrics_.relightStage.recordMicros(static_cast<std::uint64_t>(relightMicros));
        benchmarkMetrics_.relightRegionChunks.record(relightRegionChunkCount);
        benchmarkMetrics_.relightChangedChunks.record(relightChangedChunkCount);
        benchmarkMetrics_.relightExternalSnapshotChunks.record(relightExternalSnapshotChunkCount);
        benchmarkMetrics_.relightSkyAboveChunkScans.record(skyAboveChunkScans);
        benchmarkMetrics_.relightSkySeedNodes.record(skySeedNodes);
        benchmarkMetrics_.relightBlockSeedNodes.record(blockSeedNodes);
        benchmarkMetrics_.relightSkyNodesProcessed.record(skyNodesProcessed);
        benchmarkMetrics_.relightBlockNodesProcessed.record(blockNodesProcessed);
    }
}

void ChunkManager::Impl::relightAroundChunk(const glm::ivec3& centerCoord)
{
    PendingRelightBatch batch{};
    batch.valid = true;
    batch.sequence = 0;
    batch.dirtyCoordGenerations.emplace(centerCoord, 1);
    recomputePendingRelightBatchBounds(batch);
    batch.estimatedCostUnits = estimatePendingRelightBatchCost(batch);
    relightChunkRegion(batch);
}

void ChunkManager::Impl::publishChunkReady(Chunk& chunk)
{
    setStreamingChunkLifecycleState(chunk.coord, FrontierDemandState::Ready);
    noteChunkReadyLatency(chunk);
}

void ChunkManager::Impl::publishResidentExactGpuPageChunksReady(std::uint32_t pageIndex)
{
    if (pageIndex == kInvalidChunkBufferPage)
    {
        return;
    }

    std::vector<glm::ivec3> publishCoords;
    {
        std::lock_guard<std::mutex> pageLock(bufferPageMutex_);
        publishCoords = drainExactPagePublishList(pageIndex);
    }
    if (publishCoords.empty())
    {
        return;
    }

    std::vector<std::shared_ptr<Chunk>> residentChunks;
    residentChunks.reserve(publishCoords.size());
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        for (const glm::ivec3& coord : publishCoords)
        {
            const auto it = chunks_.find(coord);
            if (it == chunks_.end() || !it->second)
            {
                continue;
            }

            residentChunks.push_back(it->second);
        }
    }

    for (const auto& chunk : residentChunks)
    {
        if (!chunk)
        {
            continue;
        }

        ResidentChunkDrawAllocation replacedLiveAllocation{};
        replacedLiveAllocation.chunkCoord = chunk->coord;
        bool readyToPublish = false;

        {
            std::lock_guard<std::mutex> meshLock(chunk->meshMutex);
            if (chunk->pendingExactDraw.valid() &&
                chunk->pendingExactDraw.pageIndex == pageIndex)
            {
                if (chunkUsesCpuNearRendering(*chunk))
                {
                    chunk->pendingExactDrawReady.store(true, std::memory_order_release);
                    recomputeChunkExactGpuHandoffReadiness(*chunk);
                    continue;
                }

                replacedLiveAllocation.pageIndex = chunk->bufferPageIndex.load(std::memory_order_acquire);
                replacedLiveAllocation.vertexOffset = chunk->vertexOffset.load(std::memory_order_acquire);
                replacedLiveAllocation.vertexCount = chunk->vertexCount.load(std::memory_order_acquire);
                replacedLiveAllocation.indexOffset = chunk->indexOffset.load(std::memory_order_acquire);
                replacedLiveAllocation.indexCount =
                    static_cast<std::size_t>(chunk->indexCount.load(std::memory_order_acquire));
                replacedLiveAllocation.recordIndex =
                    chunk->exactGpuRecordIndex.load(std::memory_order_acquire);
                replacedLiveAllocation.exactDraw =
                    chunk->exactGpuResident.load(std::memory_order_acquire);

                chunk->bufferPageIndex.store(chunk->pendingExactDraw.pageIndex, std::memory_order_release);
                chunk->vertexOffset.store(0, std::memory_order_release);
                chunk->indexOffset.store(0, std::memory_order_release);
                chunk->vertexCount.store(0, std::memory_order_release);
                chunk->indexCount.store(0, std::memory_order_release);
                chunk->exactGpuFaceOffset.store(chunk->pendingExactDraw.faceOffset, std::memory_order_release);
                chunk->exactGpuFaceCount.store(chunk->pendingExactDraw.faceCount, std::memory_order_release);
                chunk->exactGpuRecordIndex.store(chunk->pendingExactDraw.recordIndex, std::memory_order_release);
                chunk->exactGpuRecordFlags.store(chunk->pendingExactDraw.recordFlags, std::memory_order_release);
                chunk->exactGpuResident.store(true, std::memory_order_release);
                chunk->pendingExactDraw.reset();
                chunk->pendingExactDrawReady.store(false, std::memory_order_release);
                chunk->exactGpuPublishPending.store(false, std::memory_order_release);
                readyToPublish = true;
            }
            else if (chunk->exactGpuResident.load(std::memory_order_acquire) &&
                     chunk->bufferPageIndex.load(std::memory_order_acquire) == pageIndex)
            {
                readyToPublish = true;
            }
        }
        refreshPendingExactGpuBuildCount(*chunk);

        if (replacedLiveAllocation.valid() &&
            (replacedLiveAllocation.pageIndex != pageIndex ||
             replacedLiveAllocation.recordIndex != chunk->exactGpuRecordIndex.load(std::memory_order_acquire)))
        {
            exactGpuMeshReplacements_.fetch_add(1, std::memory_order_relaxed);
            releaseResidentChunkDrawAllocation(replacedLiveAllocation);
        }

        if (readyToPublish)
        {
            publishChunkReady(*chunk);
        }
    }
}

bool ChunkManager::Impl::finalizeChunkExactGpuHandoff(const std::shared_ptr<Chunk>& chunk)
{
    if (!chunk)
    {
        return false;
    }

    ResidentChunkDrawAllocation replacedLiveAllocation{};
    replacedLiveAllocation.chunkCoord = chunk->coord;
    bool switched = false;
    {
        std::lock_guard<std::mutex> meshLock(chunk->meshMutex);
        if (!chunk->pendingExactDraw.valid() ||
            !chunk->pendingExactDrawReady.load(std::memory_order_acquire) ||
            !chunk->handoffReady.load(std::memory_order_acquire))
        {
            return false;
        }

        replacedLiveAllocation.pageIndex = chunk->bufferPageIndex.load(std::memory_order_acquire);
        replacedLiveAllocation.vertexOffset = chunk->vertexOffset.load(std::memory_order_acquire);
        replacedLiveAllocation.vertexCount = chunk->vertexCount.load(std::memory_order_acquire);
        replacedLiveAllocation.indexOffset = chunk->indexOffset.load(std::memory_order_acquire);
        replacedLiveAllocation.indexCount =
            static_cast<std::size_t>(chunk->indexCount.load(std::memory_order_acquire));
        replacedLiveAllocation.recordIndex =
            chunk->exactGpuRecordIndex.load(std::memory_order_acquire);
        replacedLiveAllocation.exactDraw =
            chunk->exactGpuResident.load(std::memory_order_acquire);

        chunk->bufferPageIndex.store(chunk->pendingExactDraw.pageIndex, std::memory_order_release);
        chunk->vertexOffset.store(0, std::memory_order_release);
        chunk->indexOffset.store(0, std::memory_order_release);
        chunk->vertexCount.store(0, std::memory_order_release);
        chunk->indexCount.store(0, std::memory_order_release);
        chunk->exactGpuFaceOffset.store(chunk->pendingExactDraw.faceOffset, std::memory_order_release);
        chunk->exactGpuFaceCount.store(chunk->pendingExactDraw.faceCount, std::memory_order_release);
        chunk->exactGpuRecordIndex.store(chunk->pendingExactDraw.recordIndex, std::memory_order_release);
        chunk->exactGpuRecordFlags.store(chunk->pendingExactDraw.recordFlags, std::memory_order_release);
        chunk->exactGpuResident.store(true, std::memory_order_release);
        chunk->pendingExactDraw.reset();
        chunk->pendingExactDrawReady.store(false, std::memory_order_release);
        chunk->exactGpuPublishPending.store(false, std::memory_order_release);
        chunk->handoffReady.store(false, std::memory_order_release);
        chunk->handoffTargetRevision.store(0, std::memory_order_release);
        chunk->lastLocalEditMicros.store(0, std::memory_order_release);
        chunk->gameplayAuthority.store(ChunkGameplayAuthority::GpuStreaming, std::memory_order_release);
        chunk->residencyMode.store(ExactChunkResidencyMode::GpuResidentNonlocal, std::memory_order_release);
        switched = true;
    }
    refreshPendingExactGpuBuildCount(*chunk);

    if (switched &&
        replacedLiveAllocation.valid() &&
        !replacedLiveAllocation.exactDraw)
    {
        releaseResidentChunkDrawAllocation(replacedLiveAllocation);
    }
    if (switched)
    {
        publishChunkReady(*chunk);
    }
    return switched;
}

void ChunkManager::Impl::noteChunkReadyLatency(Chunk& chunk)
{
    if (!benchmarkMetrics_.isEnabled())
    {
        return;
    }

    if (chunk.initialReadyRecorded.exchange(true, std::memory_order_acq_rel))
    {
        return;
    }

    const long long requestedMicros = chunk.requestTimestampMicros.load(std::memory_order_acquire);
    if (requestedMicros <= 0)
    {
        return;
    }

    const std::uint64_t readyMicros = steadyMicrosNow();
    const std::uint64_t requestMicros = static_cast<std::uint64_t>(requestedMicros);
    if (readyMicros <= requestMicros)
    {
        benchmarkMetrics_.chunkReadyLatency.recordMicros(0);
        return;
    }

    benchmarkMetrics_.chunkReadyLatency.recordMicros(readyMicros - requestMicros);

    const std::uint64_t generateStartMicros = loadBenchmarkTimestamp(chunk.generateStartTimestampMicros);
    const std::uint64_t generateDoneMicros = loadBenchmarkTimestamp(chunk.generateDoneTimestampMicros);
    const std::uint64_t meshQueuedMicros = loadBenchmarkTimestamp(chunk.meshQueuedTimestampMicros);
    const std::uint64_t meshStartMicros = loadBenchmarkTimestamp(chunk.meshStartTimestampMicros);
    const std::uint64_t meshDoneMicros = loadBenchmarkTimestamp(chunk.meshDoneTimestampMicros);
    const std::uint64_t uploadQueuedMicros = loadBenchmarkTimestamp(chunk.uploadQueuedTimestampMicros);
    const std::uint64_t uploadStartMicros = loadBenchmarkTimestamp(chunk.uploadStartTimestampMicros);
    const std::uint64_t firstStructureDeferredMicros =
        loadBenchmarkTimestamp(chunk.firstStructureDeferredTimestampMicros);

    auto recordStage = [&](AtomicLatencyHistogram& stage, std::uint64_t beginMicros, std::uint64_t endMicros)
    {
        if (beginMicros == 0 || endMicros == 0 || endMicros <= beginMicros)
        {
            return;
        }

        stage.recordMicros(endMicros - beginMicros);
    };

    recordStage(benchmarkMetrics_.chunkReadyWaitGenerateStage, requestMicros, generateStartMicros);
    recordStage(benchmarkMetrics_.chunkReadyGenerateStage, generateStartMicros, generateDoneMicros);
    recordStage(benchmarkMetrics_.chunkReadyWaitMeshEnqueueStage, generateDoneMicros, meshQueuedMicros);
    recordStage(benchmarkMetrics_.chunkReadyWaitMeshStartStage, meshQueuedMicros, meshStartMicros);
    recordStage(benchmarkMetrics_.chunkReadyMeshStage, meshStartMicros, meshDoneMicros);
    const std::uint64_t uploadWaitStartMicros = uploadQueuedMicros != 0 ? uploadQueuedMicros : meshDoneMicros;
    recordStage(benchmarkMetrics_.chunkReadyWaitUploadStage, uploadWaitStartMicros, uploadStartMicros);
    recordStage(benchmarkMetrics_.chunkReadyUploadToReadyStage, uploadStartMicros, readyMicros);
    benchmarkMetrics_.chunkReadyGenerateAttempts.record(
        chunk.generateAttemptCount.load(std::memory_order_relaxed));
    benchmarkMetrics_.chunkReadyStructureDeferralCount.record(
        chunk.structureDeferredAttemptCount.load(std::memory_order_relaxed));
    recordStage(benchmarkMetrics_.chunkReadyFirstStructureDeferralToReadyStage,
                firstStructureDeferredMicros,
                readyMicros);
}







bool ChunkManager::Impl::trySampleColumnReady(ColumnSample& outSample,
                                              int worldX,
                                              int worldZ,
                                              int slabMinWorldY,
                                              int slabMaxWorldY,
                                              bool includeBlendDebug) const
{
    const bool usesDefaultSlabBounds =
        slabMinWorldY == std::numeric_limits<int>::min() && slabMaxWorldY == std::numeric_limits<int>::max();
    if (slabMinWorldY > slabMaxWorldY)
    {
        std::swap(slabMinWorldY, slabMaxWorldY);
    }

    if (!surfaceMap_)
    {
        throw std::runtime_error("Surface map is not initialized");
    }
    if (!climateMap_)
    {
        throw std::runtime_error("Climate map is not initialized");
    }

    const std::shared_ptr<const WorldgenPage> page =
        tryGetReadyWorldgenPage(worldgenPageKeyForWorld(worldX, worldZ));
    if (!page)
    {
        return false;
    }

    const int localX = worldX - page->baseWorld.x;
    const int localZ = worldZ - page->baseWorld.y;
    const WorldgenColumnValue worldgenColumn = page->column(localX, localZ);

    ColumnSample sample{};
    sample.dominantBiome = worldgenColumn.surface.dominantBiome;
    sample.dominantWeight = worldgenColumn.surface.dominantWeight;
    sample.surfaceHeight = worldgenColumn.surface.surfaceHeight;
    sample.surfaceY = worldgenColumn.surface.surfaceY;
    sample.originalSurfaceY = worldgenColumn.surface.surfaceY;
    if (usesDefaultSlabBounds)
    {
        slabMinWorldY = sample.surfaceY;
        slabMaxWorldY = sample.surfaceY;
    }
    sample.minSurfaceY = std::min(sample.surfaceY, slabMinWorldY);
    sample.maxSurfaceY = std::max(sample.surfaceY, slabMaxWorldY);
    sample.soilCreepCoefficient = worldgenColumn.surface.soilCreepCoefficient;
    sample.roughAmplitude = worldgenColumn.surface.roughAmplitude;
    sample.hillAmplitude = worldgenColumn.surface.hillAmplitude;
    sample.mountainAmplitude = worldgenColumn.surface.mountainAmplitude;
    sample.dominantIsOcean = worldgenColumn.dominantIsOcean;
    sample.distanceToCoast = worldgenColumn.distanceToCoast;
    sample.distanceToShore = std::isfinite(worldgenColumn.distanceToCoast)
                                 ? worldgenColumn.distanceToCoast
                                 : std::numeric_limits<float>::infinity();
    sample.soilCreepOffset = 0.0f;

    if (includeBlendDebug)
    {
        const terrain::ClimateSample climateSample = climateMap_->sample(worldX, worldZ);
        sample.topBlendCount = std::min(climateSample.blendCount, sample.topBlendDebug.size());
        const glm::vec2 columnPos(static_cast<float>(worldX), static_cast<float>(worldZ));
        for (std::size_t i = 0; i < sample.topBlendCount; ++i)
        {
            const auto& srcBlend = climateSample.blends[i];
            auto& dstBlend = sample.topBlendDebug[i];
            dstBlend.biome = srcBlend.biome;
            dstBlend.weight = srcBlend.weight;
            dstBlend.aggregatedHeight = srcBlend.height;
            dstBlend.normalizedDistance = srcBlend.normalizedDistance;
            dstBlend.seedRadius = srcBlend.falloff;
            dstBlend.worldDistance = glm::length(columnPos - srcBlend.sitePosition);
            dstBlend.isOcean = srcBlend.biome && srcBlend.biome->isOcean();
        }
    }

    sample.slabHasSolid = worldgenColumn.surface.surfaceY >= slabMinWorldY;
    if (sample.slabHasSolid)
    {
        sample.slabHighestSolidY = std::min(worldgenColumn.surface.surfaceY, slabMaxWorldY);
    }

    if (!std::isfinite(sample.distanceToShore))
    {
        if (sample.dominantBiome && sample.dominantBiome->isOcean())
        {
            sample.distanceToShore = 0.0f;
            sample.distanceToCoast = 0.0f;
        }
    }

    outSample = sample;
    return true;
}

ColumnSample ChunkManager::Impl::sampleColumnReadyOrThrow(
    int worldX,
    int worldZ,
    int slabMinWorldY,
    int slabMaxWorldY,
    bool includeBlendDebug) const
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const SteadyClock::time_point sampleStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    ColumnSample sample{};
    if (!trySampleColumnReady(sample, worldX, worldZ, slabMinWorldY, slabMaxWorldY, includeBlendDebug))
    {
        throw std::runtime_error("Column sampling requires ready worldgen dependencies");
    }

    if (benchmarkEnabled)
    {
        const auto sampleEnd = SteadyClock::now();
        const auto sampleMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(sampleEnd - sampleStart).count();
        benchmarkMetrics_.sampleStage.recordMicros(static_cast<std::uint64_t>(sampleMicros));
    }

    return sample;
}

bool ChunkManager::Impl::trySampleColumnOrRequest(ColumnSample& outSample,
                                                  int worldX,
                                                  int worldZ,
                                                  int slabMinWorldY,
                                                  int slabMaxWorldY,
                                                  bool includeBlendDebug,
                                                  DependencyPriority priority,
                                                  JobServiceClass serviceClass) const
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const SteadyClock::time_point sampleStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    const bool ready =
        trySampleColumnReady(outSample, worldX, worldZ, slabMinWorldY, slabMaxWorldY, includeBlendDebug);
    if (!ready)
    {
        (void)requestSampleColumnDependency(worldgenPageKeyForWorld(worldX, worldZ), priority, serviceClass);
    }

    if (benchmarkEnabled)
    {
        const auto sampleEnd = SteadyClock::now();
        const auto sampleMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(sampleEnd - sampleStart).count();
        benchmarkMetrics_.sampleStage.recordMicros(static_cast<std::uint64_t>(sampleMicros));
    }

    return ready;
}

void ChunkManager::Impl::registerDeferredChunkDependencies(
    const glm::ivec3& coord,
    std::uint32_t generationEpoch,
    bool initialReadyPriority,
    bool localInteractionPriority,
    std::span<const glm::ivec2> missingWorldgenPages,
    std::span<const StructureRegionKey> missingStructureRegions)
{
    auto clearLocked = [&](auto it)
    {
        if (it == deferredChunkDependencies_.end())
        {
            return;
        }

        for (const glm::ivec2& pageKey : it->second.missingWorldgenPages)
        {
            auto waiterIt = worldgenPageWaiters_.find(pageKey);
            if (waiterIt == worldgenPageWaiters_.end())
            {
                continue;
            }

            waiterIt->second.erase(coord);
            if (waiterIt->second.empty())
            {
                worldgenPageWaiters_.erase(waiterIt);
            }
        }

        for (const StructureRegionKey& regionKey : it->second.missingStructureRegions)
        {
            auto waiterIt = structureRegionWaiters_.find(regionKey);
            if (waiterIt == structureRegionWaiters_.end())
            {
                continue;
            }

            waiterIt->second.erase(coord);
            if (waiterIt->second.empty())
            {
                structureRegionWaiters_.erase(waiterIt);
            }
        }

        deferredChunkDependencies_.erase(it);
    };
    {
        std::lock_guard<std::mutex> lock(deferredChunkDependencyMutex_);
        clearLocked(deferredChunkDependencies_.find(coord));
        if (missingWorldgenPages.empty() && missingStructureRegions.empty())
        {
            return;
        }

        DeferredChunkDependencies& deferred = deferredChunkDependencies_[coord];
        deferred.generationEpoch = generationEpoch;
        deferred.initialReadyPriority = initialReadyPriority;
        deferred.localInteractionPriority = localInteractionPriority;
        deferred.waitedOnWorldgenDependencies = !missingWorldgenPages.empty();
        deferred.waitedOnStructureDependencies = !missingStructureRegions.empty();
        deferred.outstandingDependencyCount = 0;
        deferred.firstDependencyQueuedTimestampMicros = steadyMicrosNow();
        for (const glm::ivec2& pageKey : missingWorldgenPages)
        {
            if (deferred.missingWorldgenPages.insert(pageKey).second)
            {
                worldgenPageWaiters_[pageKey].insert(coord);
                ++deferred.outstandingDependencyCount;
            }
        }
        for (const StructureRegionKey& regionKey : missingStructureRegions)
        {
            if (deferred.missingStructureRegions.insert(regionKey).second)
            {
                structureRegionWaiters_[regionKey].insert(coord);
                ++deferred.outstandingDependencyCount;
            }
        }
    }

    reconcileDeferredChunkDependencies(coord);
}

void ChunkManager::Impl::reconcileDeferredChunkDependencies(const glm::ivec3& coord)
{
    std::vector<glm::ivec2> pendingWorldgenPages;
    std::vector<StructureRegionKey> pendingStructureRegions;
    {
        std::lock_guard<std::mutex> lock(deferredChunkDependencyMutex_);
        auto it = deferredChunkDependencies_.find(coord);
        if (it == deferredChunkDependencies_.end())
        {
            return;
        }

        pendingWorldgenPages.reserve(it->second.missingWorldgenPages.size());
        for (const glm::ivec2& pageKey : it->second.missingWorldgenPages)
        {
            pendingWorldgenPages.push_back(pageKey);
        }

        pendingStructureRegions.reserve(it->second.missingStructureRegions.size());
        for (const StructureRegionKey& regionKey : it->second.missingStructureRegions)
        {
            pendingStructureRegions.push_back(regionKey);
        }
    }

    std::vector<glm::ivec2> readyWorldgenPages;
    readyWorldgenPages.reserve(pendingWorldgenPages.size());
    for (const glm::ivec2& pageKey : pendingWorldgenPages)
    {
        if (tryGetReadyWorldgenPage(pageKey))
        {
            readyWorldgenPages.push_back(pageKey);
        }
    }

    std::vector<StructureRegionKey> readyStructureRegions;
    readyStructureRegions.reserve(pendingStructureRegions.size());
    for (const StructureRegionKey& regionKey : pendingStructureRegions)
    {
        if (tryGetReadyRegion(regionKey))
        {
            readyStructureRegions.push_back(regionKey);
        }
    }

    DeferredChunkDependencies readyDependencies{};
    bool shouldQueueGenerate = false;
    {
        std::lock_guard<std::mutex> lock(deferredChunkDependencyMutex_);
        auto it = deferredChunkDependencies_.find(coord);
        if (it == deferredChunkDependencies_.end())
        {
            return;
        }

        DeferredChunkDependencies& deferred = it->second;
        for (const glm::ivec2& pageKey : readyWorldgenPages)
        {
            if (deferred.missingWorldgenPages.erase(pageKey) == 0)
            {
                continue;
            }

            auto waiterIt = worldgenPageWaiters_.find(pageKey);
            if (waiterIt != worldgenPageWaiters_.end())
            {
                waiterIt->second.erase(coord);
                if (waiterIt->second.empty())
                {
                    worldgenPageWaiters_.erase(waiterIt);
                }
            }

            if (deferred.outstandingDependencyCount > 0)
            {
                --deferred.outstandingDependencyCount;
            }
        }

        for (const StructureRegionKey& regionKey : readyStructureRegions)
        {
            if (deferred.missingStructureRegions.erase(regionKey) == 0)
            {
                continue;
            }

            auto waiterIt = structureRegionWaiters_.find(regionKey);
            if (waiterIt != structureRegionWaiters_.end())
            {
                waiterIt->second.erase(coord);
                if (waiterIt->second.empty())
                {
                    structureRegionWaiters_.erase(waiterIt);
                }
            }

            if (deferred.outstandingDependencyCount > 0)
            {
                --deferred.outstandingDependencyCount;
            }
        }

        if (!deferred.missingWorldgenPages.empty() || !deferred.missingStructureRegions.empty())
        {
            return;
        }

        readyDependencies = deferred;
        deferredChunkDependencies_.erase(it);
        shouldQueueGenerate = true;
    }

    if (shouldQueueGenerate)
    {
        queueDeferredChunkGenerateIfReady(coord, readyDependencies);
    }
}

void ChunkManager::Impl::reconcileStructureRegionWaitingPages(const StructureRegionKey& key)
{
    std::vector<glm::ivec2> pendingPageKeys;
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        auto it = structureRegionEntries_.find(key);
        if (it == structureRegionEntries_.end() || it->second.state != StructureRegionState::WaitingOnWorldgenPages)
        {
            return;
        }

        pendingPageKeys.reserve(it->second.missingWorldgenPages.size());
        for (const glm::ivec2& pageKey : it->second.missingWorldgenPages)
        {
            pendingPageKeys.push_back(pageKey);
        }
    }

    std::vector<glm::ivec2> readyPageKeys;
    readyPageKeys.reserve(pendingPageKeys.size());
    for (const glm::ivec2& pageKey : pendingPageKeys)
    {
        if (tryGetReadyWorldgenPage(pageKey))
        {
            readyPageKeys.push_back(pageKey);
        }
    }

    bool shouldRefillStructureJobs = false;
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        auto it = structureRegionEntries_.find(key);
        if (it == structureRegionEntries_.end() || it->second.state != StructureRegionState::WaitingOnWorldgenPages)
        {
            return;
        }

        StructureRegionDependencyEntry& entry = it->second;
        for (const glm::ivec2& pageKey : readyPageKeys)
        {
            if (entry.missingWorldgenPages.erase(pageKey) == 0)
            {
                continue;
            }

            auto waiterIt = worldgenPageStructureRegionWaiters_.find(pageKey);
            if (waiterIt != worldgenPageStructureRegionWaiters_.end())
            {
                waiterIt->second.erase(key);
                if (waiterIt->second.empty())
                {
                    worldgenPageStructureRegionWaiters_.erase(waiterIt);
                }
            }
        }

        if (!entry.missingWorldgenPages.empty())
        {
            return;
        }

        const StructureRegionKey centerRegion{
            floorDiv(lastCenterChunk_.x * kChunkSizeX, kStructureRegionSize),
            floorDiv(lastCenterChunk_.z * kChunkSizeZ, kStructureRegionSize)};
        const std::uint32_t distance =
            static_cast<std::uint32_t>(std::max(std::abs(key.regionX - centerRegion.regionX),
                                                std::abs(key.regionZ - centerRegion.regionZ)));

        entry.state = StructureRegionState::Queued;
        entry.dependencyJobQueued = true;
        entry.lastError = {};
        entry.token = nextStructureRegionDependencyToken_++;
        pendingStructureRegionDependencyQueue_.push(
            StructureRegionDependencyRequest{
                key,
                entry.token,
                nextStructureRegionDependencySequence_++,
                distance,
                entry.priority,
                entry.serviceClass});
        shouldRefillStructureJobs = true;
    }

    if (shouldRefillStructureJobs)
    {
        if (exactDependencyStallDebugLoggingEnabled())
        {
            std::ostringstream stream;
            stream << "exact_dep_region_reconciled region=(" << key.regionX << "," << key.regionZ
                   << ") reason=pages_ready_before_waiter_registration";
            exactDependencyStallDebugLog(stream.str());
        }
        refillStructureRegionDependencyJobs();
    }
}

bool ChunkManager::Impl::worldgenPageDependencyHasOutstandingWork(const glm::ivec2& pageKey) const
{
    std::lock_guard<std::mutex> pageLock(worldgenPageMutex_);
    auto it = worldgenPageEntries_.find(pageKey);
    if (it == worldgenPageEntries_.end())
    {
        return false;
    }

    return it->second.dependencyJobQueued ||
           it->second.dependencyJobInFlight ||
           it->second.state == WorldgenPageState::Queued ||
           it->second.state == WorldgenPageState::Building;
}

bool ChunkManager::Impl::structureRegionDependencyHasOutstandingWork(const StructureRegionKey& key) const
{
    StructureRegionState state = StructureRegionState::Unrequested;
    std::vector<glm::ivec2> missingPageKeys;
    {
        std::lock_guard<std::mutex> lock(structureRegionDependencyMutex_);
        auto it = structureRegionEntries_.find(key);
        if (it == structureRegionEntries_.end())
        {
            return false;
        }

        state = it->second.state;
        if (state == StructureRegionState::WaitingOnWorldgenPages)
        {
            missingPageKeys.reserve(it->second.missingWorldgenPages.size());
            for (const glm::ivec2& pageKey : it->second.missingWorldgenPages)
            {
                missingPageKeys.push_back(pageKey);
            }
        }
    }

    if (state == StructureRegionState::Queued || state == StructureRegionState::Building)
    {
        return true;
    }

    if (state != StructureRegionState::WaitingOnWorldgenPages)
    {
        return false;
    }

    if (missingPageKeys.empty())
    {
        return false;
    }

    for (const glm::ivec2& pageKey : missingPageKeys)
    {
        if (tryGetReadyWorldgenPage(pageKey))
        {
            continue;
        }

        if (!worldgenPageDependencyHasOutstandingWork(pageKey))
        {
            return false;
        }
    }

    return true;
}

void ChunkManager::Impl::abandonChunkGenerationPlaceholder(const glm::ivec3& coord, std::uint32_t generationEpoch)
{
    bool removed = false;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        auto it = chunks_.find(coord);
        if (it == chunks_.end() || !it->second)
        {
            return;
        }

        if (it->second->generationEpoch.load(std::memory_order_acquire) != generationEpoch)
        {
            return;
        }

        if (it->second->state.load(std::memory_order_acquire) != ChunkState::Generating)
        {
            return;
        }

        clearPendingExactGpuBuildCount(*it->second);
        unregisterChunkRenderRegistryEntry(coord);
        chunks_.erase(it);
        denseTrackedCoords_.erase(coord);
        removed = true;
    }

    (void)removed;
}

void ChunkManager::Impl::clearDeferredChunkDependencies(const glm::ivec3& coord)
{
    std::lock_guard<std::mutex> lock(deferredChunkDependencyMutex_);
    auto it = deferredChunkDependencies_.find(coord);
    if (it == deferredChunkDependencies_.end())
    {
        return;
    }

    for (const glm::ivec2& pageKey : it->second.missingWorldgenPages)
    {
        auto waiterIt = worldgenPageWaiters_.find(pageKey);
        if (waiterIt == worldgenPageWaiters_.end())
        {
            continue;
        }

        waiterIt->second.erase(coord);
        if (waiterIt->second.empty())
        {
            worldgenPageWaiters_.erase(waiterIt);
        }
    }

    for (const StructureRegionKey& regionKey : it->second.missingStructureRegions)
    {
        auto waiterIt = structureRegionWaiters_.find(regionKey);
        if (waiterIt == structureRegionWaiters_.end())
        {
            continue;
        }

        waiterIt->second.erase(coord);
        if (waiterIt->second.empty())
        {
            structureRegionWaiters_.erase(waiterIt);
        }
    }

    deferredChunkDependencies_.erase(it);
}

void ChunkManager::Impl::queueDeferredChunkGenerateIfReady(const glm::ivec3& coord,
                                                           const DeferredChunkDependencies& deferred)
{
    std::shared_ptr<Chunk> chunk = getChunkShared(coord);
    if (!chunk)
    {
        return;
    }

    if (chunk->generationEpoch.load(std::memory_order_acquire) != deferred.generationEpoch)
    {
        return;
    }

    if (chunk->state.load(std::memory_order_acquire) != ChunkState::Generating ||
        chunk->inFlight.load(std::memory_order_acquire) != 0)
    {
        return;
    }

    if (benchmarkMetrics_.isEnabled() && deferred.firstDependencyQueuedTimestampMicros > 0)
    {
        const long long readyTimestampMicros = static_cast<long long>(steadyMicrosNow());
        if (readyTimestampMicros > deferred.firstDependencyQueuedTimestampMicros)
        {
            const std::uint64_t readyDeltaMicros =
                static_cast<std::uint64_t>(readyTimestampMicros - deferred.firstDependencyQueuedTimestampMicros);
            if (deferred.waitedOnWorldgenDependencies)
            {
                benchmarkMetrics_.worldgenDependencyReadyToGenerate.recordMicros(readyDeltaMicros);
            }
            if (deferred.waitedOnStructureDependencies)
            {
                benchmarkMetrics_.structureDependencyReadyToGenerate.recordMicros(readyDeltaMicros);
            }
        }
    }

    setStreamingChunkLifecycleState(coord, FrontierDemandState::QueuedGenerate);
    enqueueJob(chunk,
               JobType::Generate,
               coord,
               deferred.generationEpoch,
               deferred.initialReadyPriority,
               classifyJobServiceClass(deferred.initialReadyPriority,
                                       deferred.localInteractionPriority,
                                       false));
}



std::vector<StructureInstance> ChunkManager::Impl::queryStructureInstances(const glm::ivec3& minWorld,
                                                                           const glm::ivec3& maxWorld,
                                                                           int lodLevel,
                                                                           bool* outAllRegionsReady,
                                                                           std::vector<StructureRegionKey>* outMissingRegions) const
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const SteadyClock::time_point queryStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    std::vector<StructureInstance> instances =
        structureRegistry_.queryReady(minWorld, maxWorld, lodLevel, outAllRegionsReady, outMissingRegions);
    if (benchmarkEnabled)
    {
        const auto queryMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(SteadyClock::now() - queryStart).count();
        benchmarkMetrics_.structureQueryStage.recordMicros(
            static_cast<std::uint64_t>(std::max<std::int64_t>(queryMicros, 0)));
    }
    return instances;
}

