namespace
{
template <typename WriteBlockFn>
void stampStructureInstanceIntoTarget(const StructureInstance& instance, WriteBlockFn&& writeBlock)
{
    auto setLocalBlock = [&](int worldX, int worldY, int worldZ, BlockId block, bool replaceSolid)
    {
        writeBlock(worldX, worldY, worldZ, block, replaceSolid);
    };

    if (instance.type == StructureType::TaigaSpruce)
    {
        for (int trunkX = 0; trunkX < 2; ++trunkX)
        {
            for (int trunkZ = 0; trunkZ < 2; ++trunkZ)
            {
                for (int dy = 1; dy <= instance.trunkHeight; ++dy)
                {
                    setLocalBlock(instance.origin.x + trunkX,
                                  instance.origin.y + dy,
                                  instance.origin.z + trunkZ,
                                  BlockId::SpruceLog,
                                  true);
                }
            }
        }

        const int canopyBaseWorld = instance.origin.y + instance.bareTrunkHeight + 1;
        const int canopyTopWorld = instance.origin.y + instance.trunkHeight;
        const int totalLayers = std::max(1, canopyTopWorld - canopyBaseWorld + 1);
        for (int worldY = canopyBaseWorld; worldY <= canopyTopWorld; ++worldY)
        {
            const int layerFromBottom = worldY - canopyBaseWorld;
            const int radius = taigaSpruceLeafRadiusForLayer(layerFromBottom, totalLayers);
            if (radius <= 0)
            {
                continue;
            }

            for (int worldX = instance.origin.x - radius; worldX <= instance.origin.x + 1 + radius; ++worldX)
            {
                for (int worldZ = instance.origin.z - radius; worldZ <= instance.origin.z + 1 + radius; ++worldZ)
                {
                    if (!taigaSpruceLeafOccupiesCell(instance.origin.x,
                                                     instance.origin.z,
                                                     worldX,
                                                     worldZ,
                                                     radius,
                                                     layerFromBottom,
                                                     totalLayers))
                    {
                        continue;
                    }
                    setLocalBlock(worldX, worldY, worldZ, BlockId::SpruceLeaves, false);
                }
            }
        }

        const int crownWorldY = canopyTopWorld + 1;
        for (int trunkX = 0; trunkX < 2; ++trunkX)
        {
            for (int trunkZ = 0; trunkZ < 2; ++trunkZ)
            {
                setLocalBlock(instance.origin.x + trunkX,
                              crownWorldY,
                              instance.origin.z + trunkZ,
                              BlockId::SpruceLeaves,
                              false);
            }
        }
        return;
    }

    if (instance.type == StructureType::DarkOak)
    {
        forEachDarkOakTreeBlock(instance.origin.x,
                                instance.origin.z,
                                instance.origin.y,
                                instance.trunkHeight,
                                instance.trunkBlock,
                                instance.leavesBlock,
                                [&](int blockX, int blockY, int blockZ, BlockId block) {
                                    setLocalBlock(blockX, blockY, blockZ, block, block == instance.trunkBlock);
                                    return false;
                                });
        return;
    }

    if (instance.type == StructureType::Acacia)
    {
        forEachAcaciaTreeBlock(instance.origin.x,
                               instance.origin.z,
                               instance.origin.y,
                               instance.trunkHeight,
                               instance.trunkBlock,
                               instance.leavesBlock,
                               [&](int blockX, int blockY, int blockZ, BlockId block) {
                                   setLocalBlock(blockX, blockY, blockZ, block, block == instance.trunkBlock);
                                   return false;
                               });
        return;
    }

    forEachDefaultTreeBlock(instance.origin.x,
                            instance.origin.z,
                            instance.origin.y,
                            instance.trunkHeight,
                            instance.trunkBlock,
                            instance.leavesBlock,
                            [&](int blockX, int blockY, int blockZ, BlockId block) {
                                setLocalBlock(blockX, blockY, blockZ, block, block == instance.trunkBlock);
                                return false;
                            });
}
} // namespace

bool ChunkManager::Impl::generateChunkBlocks(Chunk& chunk, std::uint32_t generationEpoch)
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    if (benchmarkEnabled)
    {
        chunk.generateAttemptCount.fetch_add(1, std::memory_order_relaxed);
    }
    const auto phaseNow = [&]() -> SteadyClock::time_point
    {
        return benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    };
    const auto recordPhase = [&](AtomicLatencyHistogram& stage,
                                 const SteadyClock::time_point& start,
                                 const SteadyClock::time_point& end)
    {
        if (!benchmarkEnabled || end <= start)
        {
            return;
        }

        stage.recordMicros(static_cast<std::uint64_t>(
            std::chrono::duration_cast<std::chrono::microseconds>(end - start).count()));
    };
    const double nowSeconds = static_cast<double>(steadyMicrosNow()) / 1'000'000.0;
    const ChunkGameplayAuthority gameplayAuthority =
        desiredChunkGameplayAuthority(chunk, lastCenterChunk_, nowSeconds);
    chunk.gameplayAuthority.store(gameplayAuthority, std::memory_order_release);
    refreshPendingExactGpuBuildCount(chunk);
    const bool localAuthoritative = gameplayAuthority != ChunkGameplayAuthority::GpuStreaming;
    const bool initialReadyPriority = chunkAwaitingInitialReady(chunk);
    std::array<ColumnBuildResult, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> columnResults{};
    std::array<int, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> highestSolidWorlds{};
    bool anyBaseTerrain = false;
    const auto baseTerrainStart = phaseNow();
    if (!computeChunkBaseTerrainState(chunk.coord,
                                      generationEpoch,
                                      initialReadyPriority,
                                      localAuthoritative,
                                      chunk.minWorldY,
                                      chunk.maxWorldY,
                                      highestSolidWorlds,
                                      anyBaseTerrain))
    {
        recordPhase(benchmarkMetrics_.generateBaseTerrainStateStage, baseTerrainStart, phaseNow());
        return false;
    }
    recordPhase(benchmarkMetrics_.generateBaseTerrainStateStage, baseTerrainStart, phaseNow());
    for (std::size_t i = 0; i < highestSolidWorlds.size(); ++i)
    {
        columnResults[i].highestSolidWorld = highestSolidWorlds[i];
        columnResults[i].wroteSolid = highestSolidWorlds[i] != ColumnManager::kNoHeight;
    }

    const auto structureResolveStart = phaseNow();
    std::vector<StructureVoxelEdit> structureVoxelEdits;
    bool allStructureRegionsReady = true;
    std::vector<StructureRegionKey> missingStructureRegions;
    structureVoxelEdits =
        queryStructureVoxelEditsForChunkReady(chunk.coord, &allStructureRegionsReady, &missingStructureRegions);
    if (!allStructureRegionsReady)
    {
        const DependencyPriority dependencyPriority =
            (initialReadyPriority || localAuthoritative) ? DependencyPriority::Critical
                                                         : DependencyPriority::Visible;
        const JobServiceClass dependencyServiceClass =
            classifyJobServiceClass(initialReadyPriority, localAuthoritative, false);
        std::vector<StructureRegionKey> deferredStructureRegions;
        deferredStructureRegions.reserve(missingStructureRegions.size());
        for (const StructureRegionKey& regionKey : missingStructureRegions)
        {
            requestStructureRegionDependency(regionKey, dependencyPriority, dependencyServiceClass);
            if (!tryGetReadyRegion(regionKey) && structureRegionDependencyHasOutstandingWork(regionKey))
            {
                deferredStructureRegions.push_back(regionKey);
            }
        }

        if (deferredStructureRegions.empty())
        {
            if (exactDependencyStallDebugLoggingEnabled())
            {
                std::ostringstream stream;
                stream << "exact_dep_retryable chunk=(" << chunk.coord.x << "," << chunk.coord.y << "," << chunk.coord.z
                       << ") stage=structure_resolve reason=no_outstanding_structure_region_work"
                       << " missing_regions=" << missingStructureRegions.size();
                for (const StructureRegionKey& regionKey : missingStructureRegions)
                {
                    stream << " region(" << regionKey.regionX << "," << regionKey.regionZ << ")_outstanding="
                           << (structureRegionDependencyHasOutstandingWork(regionKey) ? 1 : 0);
                }
                exactDependencyStallDebugLog(stream.str());
            }
            clearDeferredChunkDependencies(chunk.coord);
            clearStreamingChunkLifecycleState(chunk.coord);
            abandonChunkGenerationPlaceholder(chunk.coord, generationEpoch);
            recordPhase(benchmarkMetrics_.generateStructureResolveStage, structureResolveStart, phaseNow());
            return false;
        }

        registerDeferredChunkDependencies(chunk.coord,
                                          generationEpoch,
                                          initialReadyPriority,
                                          localAuthoritative,
                                          std::span<const glm::ivec2>{},
                                          std::span<const StructureRegionKey>(deferredStructureRegions));
        setStreamingChunkLifecycleState(chunk.coord, FrontierDemandState::WaitingDependencies);
        if (benchmarkEnabled)
        {
            chunk.structureDeferredAttemptCount.fetch_add(1, std::memory_order_relaxed);
            storeFirstBenchmarkTimestamp(chunk.firstStructureDeferredTimestampMicros, steadyMicrosNow());
            benchmarkMetrics_.chunkDependencyStructureDeferrals.record(
                static_cast<std::uint64_t>(deferredStructureRegions.size()));
            benchmarkMetrics_.generateDeferredStructureMissingRegions.record(
                static_cast<std::uint64_t>(deferredStructureRegions.size()));
        }
        recordPhase(benchmarkMetrics_.generateStructureResolveStage, structureResolveStart, phaseNow());
        return false;
    }
    clearDeferredChunkDependencies(chunk.coord);
    recordPhase(benchmarkMetrics_.generateStructureResolveStage, structureResolveStart, phaseNow());

    const auto gpuInputPrepStart = phaseNow();
    const std::vector<PendingStructureEdit> pendingStructureEditsForGpu = copyPendingStructureEdits(chunk.coord);
    std::vector<BlockEditOverlayEntry> blockOverlayEntriesForGpu;
    for (const WorldEditStore::Entry& overlay : copyBlockEditOverlayEntries(chunk.coord))
    {
        blockOverlayEntriesForGpu.push_back(BlockEditOverlayEntry{overlay.localIndex, overlay.block});
    }
    const bool anyBlocks = anyBaseTerrain ||
                           !structureVoxelEdits.empty() ||
                           !pendingStructureEditsForGpu.empty() ||
                           !blockOverlayEntriesForGpu.empty() ||
                           chunkHasPendingStructureEdits(chunk.coord) ||
                           chunkHasBlockEditOverlay(chunk.coord);
    if (auto sharedChunk = getChunkShared(chunk.coord))
    {
        ensureSkyLightColumnCacheForChunks({sharedChunk});
    }
    ChunkBuildScratch scratch(chunk);
    std::vector<PendingStructureEdit> pendingEdits;
    std::vector<GpuExactSparseVoxel> gpuSparseVoxels;
    gpuSparseVoxels.reserve(structureVoxelEdits.size() +
                            pendingStructureEditsForGpu.size() +
                            blockOverlayEntriesForGpu.size());
    for (const StructureVoxelEdit& edit : structureVoxelEdits)
    {
        const glm::ivec3 local = localBlockCoords(edit.worldPos, chunk.coord);
        if (local.x < 0 || local.x >= kChunkSizeX ||
            local.y < 0 || local.y >= kChunkSizeY ||
            local.z < 0 || local.z >= kChunkSizeZ)
        {
            continue;
        }

        gpuSparseVoxels.push_back(GpuExactSparseVoxel{
            packGpuExactLocalVoxelPos(local),
            static_cast<std::uint32_t>(edit.block),
            edit.replaceSolid ? 1u : 0u,
            0u});
    }
    for (const PendingStructureEdit& edit : pendingStructureEditsForGpu)
    {
        const glm::ivec3 local = localBlockCoords(edit.worldPos, chunk.coord);
        if (local.x < 0 || local.x >= kChunkSizeX ||
            local.y < 0 || local.y >= kChunkSizeY ||
            local.z < 0 || local.z >= kChunkSizeZ)
        {
            continue;
        }

        gpuSparseVoxels.push_back(GpuExactSparseVoxel{
            packGpuExactLocalVoxelPos(local),
            static_cast<std::uint32_t>(edit.block),
            edit.replaceSolid ? 1u : 0u,
            0u});
    }
    for (const BlockEditOverlayEntry& overlay : blockOverlayEntriesForGpu)
    {
        const int localX = overlay.localIndex % kChunkSizeX;
        const int localZ = (overlay.localIndex / kChunkSizeX) % kChunkSizeZ;
        const int localY = overlay.localIndex / (kChunkSizeX * kChunkSizeZ);
        gpuSparseVoxels.push_back(GpuExactSparseVoxel{
            packGpuExactLocalVoxelPos(glm::ivec3(localX, localY, localZ)),
            static_cast<std::uint32_t>(overlay.block),
            1u,
            0u});
    }
    recordPhase(benchmarkMetrics_.generateGpuInputPrepStage, gpuInputPrepStart, phaseNow());

    const auto meshLockStart = benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    std::uint64_t publishMicros = 0u;
    const auto firstPublishStart = phaseNow();
    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        const bool staleGeneration =
            chunk.generationEpoch.load(std::memory_order_acquire) != generationEpoch ||
            chunk.state.load(std::memory_order_acquire) != ChunkState::Generating;
        if (staleGeneration)
        {
            if (!pendingEdits.empty())
            {
                std::lock_guard<std::mutex> pendingLock(pendingStructureMutex_);
                auto& restoredEdits = pendingStructureEdits_[chunk.coord];
                restoredEdits.insert(restoredEdits.end(),
                                     std::make_move_iterator(pendingEdits.begin()),
                                     std::make_move_iterator(pendingEdits.end()));
            }

            if (benchmarkEnabled)
            {
                publishMicros += static_cast<std::uint64_t>(
                    std::chrono::duration_cast<std::chrono::microseconds>(phaseNow() - firstPublishStart).count());
                if (publishMicros > 0u)
                {
                    benchmarkMetrics_.generatePublishStage.recordMicros(publishMicros);
                }
                const auto lockMicros =
                    std::chrono::duration_cast<std::chrono::microseconds>(SteadyClock::now() - meshLockStart).count();
                benchmarkMetrics_.generateBlocksMeshLockStage.recordMicros(static_cast<std::uint64_t>(lockMicros));
            }
            return false;
        }

        chunk.exactBaseTerrainPresent = anyBaseTerrain;
        chunk.structureVoxelEdits = std::move(structureVoxelEdits);
        chunk.structureVoxelEditsReady = true;
        chunk.gpuExactSparseVoxels = std::move(gpuSparseVoxels);
        chunk.gpuExactSparseVoxelsReady = true;
        chunk.exactGpuInputsVersion.fetch_add(1, std::memory_order_acq_rel);
        chunk.exactGpuInputsDirty.store(true, std::memory_order_release);
        chunk.hasBlocks.store(anyBlocks, std::memory_order_release);
        if (!localAuthoritative)
        {
            chunk.releaseCpuData();
        }
    }
    refreshPendingExactGpuBuildCount(chunk);
    if (benchmarkEnabled)
    {
        publishMicros += static_cast<std::uint64_t>(
            std::chrono::duration_cast<std::chrono::microseconds>(phaseNow() - firstPublishStart).count());
    }

    if (!localAuthoritative)
    {
        buildChunkCpuBlocks(chunk, scratch, false, columnResults, nullptr);
        std::array<std::uint8_t, kChunkSizeX * kChunkSizeZ> incomingSky{};
        {
            std::lock_guard<std::mutex> lock(chunk.meshMutex);
            incomingSky = chunk.skyLightFromAboveCache;
        }
        std::vector<std::uint8_t> scratchLightLevels;
        rebuildChunkBaseLighting(scratch.blocks, incomingSky, scratchLightLevels);
        (void)rebuildChunkWaterResources(chunk, scratch.blocks, scratchLightLevels);
    }

    if (localAuthoritative)
    {
        const auto cpuMaterializeStart = phaseNow();
        buildChunkCpuBlocks(chunk, scratch, true, columnResults, &pendingEdits);
        recordPhase(benchmarkMetrics_.generateCpuMaterializeStage, cpuMaterializeStart, phaseNow());

        const auto secondPublishStart = phaseNow();
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        const bool staleGeneration =
            chunk.generationEpoch.load(std::memory_order_acquire) != generationEpoch ||
            chunk.state.load(std::memory_order_acquire) != ChunkState::Generating;
        if (staleGeneration)
        {
            if (!pendingEdits.empty())
            {
                std::lock_guard<std::mutex> pendingLock(pendingStructureMutex_);
                auto& restoredEdits = pendingStructureEdits_[chunk.coord];
                restoredEdits.insert(restoredEdits.end(),
                                     std::make_move_iterator(pendingEdits.begin()),
                                     std::make_move_iterator(pendingEdits.end()));
            }

            if (benchmarkEnabled)
            {
                publishMicros += static_cast<std::uint64_t>(
                    std::chrono::duration_cast<std::chrono::microseconds>(phaseNow() - secondPublishStart).count());
                if (publishMicros > 0u)
                {
                    benchmarkMetrics_.generatePublishStage.recordMicros(publishMicros);
                }
                const auto lockMicros =
                    std::chrono::duration_cast<std::chrono::microseconds>(SteadyClock::now() - meshLockStart).count();
                benchmarkMetrics_.generateBlocksMeshLockStage.recordMicros(static_cast<std::uint64_t>(lockMicros));
            }
            return false;
        }

        chunk.ensureCpuDataAllocated();
        chunk.blocks = std::move(scratch.blocks);
        rebuildChunkBaseLighting(chunk.blocks, chunk.skyLightFromAboveCache, chunk.lightLevels);
        chunk.hasBlocks.store(anyBlocks, std::memory_order_release);
        chunk.lastDenseFrameTouched = updateFrameIndex_;
        if (benchmarkEnabled)
        {
            publishMicros += static_cast<std::uint64_t>(
                std::chrono::duration_cast<std::chrono::microseconds>(phaseNow() - secondPublishStart).count());
        }
    }

    if (localAuthoritative)
    {
        std::vector<BlockId> blocksCopy;
        std::vector<std::uint8_t> lightLevelsCopy;
        {
            std::lock_guard<std::mutex> lock(chunk.meshMutex);
            blocksCopy = chunk.blocks;
            lightLevelsCopy = chunk.lightLevels;
        }
        (void)rebuildChunkWaterResources(chunk, blocksCopy, lightLevelsCopy);
    }

    if (benchmarkEnabled)
    {
        const auto lockMicros =
            std::chrono::duration_cast<std::chrono::microseconds>(SteadyClock::now() - meshLockStart).count();
        benchmarkMetrics_.generateBlocksMeshLockStage.recordMicros(static_cast<std::uint64_t>(lockMicros));
    }

    const auto publishTailStart = phaseNow();
    const glm::ivec2 column{chunk.coord.x, chunk.coord.z};
    columnManager_.updateChunkHeights(chunk.coord, highestSolidWorlds);
    mergePredictedColumnHeight(column, columnManager_.highestSolidBlockInChunkColumn(column));
    markSkyLightColumnDirty({chunk.coord.x, chunk.coord.z});
    if (benchmarkEnabled)
    {
        publishMicros += static_cast<std::uint64_t>(
            std::chrono::duration_cast<std::chrono::microseconds>(phaseNow() - publishTailStart).count());
        if (publishMicros > 0u)
        {
            benchmarkMetrics_.generatePublishStage.recordMicros(publishMicros);
        }
    }
    return true;
}

std::vector<PendingStructureEdit> ChunkManager::Impl::takePendingStructureEdits(const glm::ivec3& coord)
{
    std::vector<PendingStructureEdit> edits;
    {
        std::lock_guard<std::mutex> lock(pendingStructureMutex_);
        auto it = pendingStructureEdits_.find(coord);
        if (it != pendingStructureEdits_.end())
        {
            edits = std::move(it->second);
            pendingStructureEdits_.erase(it);
        }
    }
    if (!edits.empty())
    {
        invalidateColumnSlabOccupancy({coord.x, coord.z});
    }
    return edits;
}

std::vector<PendingStructureEdit> ChunkManager::Impl::copyPendingStructureEdits(const glm::ivec3& coord) const
{
    std::vector<PendingStructureEdit> edits;
    std::lock_guard<std::mutex> lock(pendingStructureMutex_);
    auto it = pendingStructureEdits_.find(coord);
    if (it != pendingStructureEdits_.end())
    {
        edits = it->second;
    }
    return edits;
}

std::uint16_t ChunkManager::Impl::blockOverlayLocalIndex(int localX, int localY, int localZ) noexcept
{
    return static_cast<std::uint16_t>(blockIndex(localX, localY, localZ));
}

std::uint64_t ChunkManager::Impl::recordBlockEditOverlay(const glm::ivec3& worldPos, BlockId block)
{
    const glm::ivec3 chunkCoord = worldToChunkCoords(worldPos.x, worldPos.y, worldPos.z);
    const std::uint64_t revision = worldEditStore_.set(worldPos, block);
    invalidateColumnSlabOccupancy({chunkCoord.x, chunkCoord.z});
    return revision;
}

bool ChunkManager::Impl::tryGetBlockEditOverlay(const glm::ivec3& worldPos, BlockId& outBlock) const
{
    WorldEditStore::Entry entry{};
    if (!worldEditStore_.tryGet(worldPos, entry))
    {
        return false;
    }
    outBlock = entry.block;
    return true;
}

bool ChunkManager::Impl::chunkHasBlockEditOverlay(const glm::ivec3& coord) const
{
    return worldEditStore_.hasChunkEdits(coord);
}

std::size_t ChunkManager::Impl::chunkBlockEditOverlayCount(const glm::ivec3& coord) const
{
    return worldEditStore_.chunkEditCount(coord);
}

std::vector<WorldEditStore::Entry> ChunkManager::Impl::copyBlockEditOverlayEntries(const glm::ivec3& coord) const
{
    return worldEditStore_.snapshotChunkEdits(coord);
}

void ChunkManager::Impl::applyBlockEditOverlay(ChunkBuildScratch& scratch, const glm::ivec3& chunkCoord) const
{
    const std::vector<WorldEditStore::Entry> overlays = worldEditStore_.snapshotChunkEdits(chunkCoord);
    for (const WorldEditStore::Entry& overlay : overlays)
    {
        const int localX = overlay.localIndex % kChunkSizeX;
        const int localZ = (overlay.localIndex / kChunkSizeX) % kChunkSizeZ;
        const int localY = overlay.localIndex / (kChunkSizeX * kChunkSizeZ);
        scratch.setWorldBlock(chunkCoord.x * kChunkSizeX + localX,
                              chunkCoord.y * kChunkSizeY + localY,
                              chunkCoord.z * kChunkSizeZ + localZ,
                              overlay.block,
                              true);
    }
}

bool ChunkManager::Impl::chunkHasPendingStructureEdits(const glm::ivec3& coord) const
{
    {
        std::lock_guard<std::mutex> lock(pendingStructureMutex_);
        auto it = pendingStructureEdits_.find(coord);
        if (it != pendingStructureEdits_.end() && !it->second.empty())
        {
            return true;
        }
    }
    return false;
}

bool ChunkManager::Impl::exactGpuWorkerNeedsLifecycleMaintenance()
{
    {
        std::lock_guard<std::mutex> lock(bufferPageMutex_);
        if (!sealRequestedPageIndices_.empty() ||
            !sealedPendingResidentPageIndices_.empty() ||
            !readyToResidentPageIndices_.empty() ||
            !residentPageIndices_.empty())
        {
            return true;
        }
    }

    for (ExactReservationShard& shard : exactReservationShards_)
    {
        std::lock_guard<std::mutex> shardLock(shard.mutex);
        if (!shard.openPageIndices.empty())
        {
            return true;
        }
    }

    return false;
}

void ChunkManager::Impl::buildChunkCpuBlocks(
    const Chunk& chunk,
    ChunkBuildScratch& scratch,
    bool includePendingStructureEdits,
    std::array<ColumnBuildResult, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)>& columnResults,
    std::vector<PendingStructureEdit>* consumedPendingEdits)
{
    const bool benchmarkEnabled = benchmarkMetrics_.isEnabled();
    const auto phaseNow = [&]() -> SteadyClock::time_point
    {
        return benchmarkEnabled ? SteadyClock::now() : SteadyClock::time_point{};
    };
    const auto recordPhase = [&](AtomicLatencyHistogram& stage,
                                 const SteadyClock::time_point& start,
                                 const SteadyClock::time_point& end)
    {
        if (!benchmarkEnabled || end <= start)
        {
            return;
        }

        stage.recordMicros(static_cast<std::uint64_t>(
            std::chrono::duration_cast<std::chrono::microseconds>(end - start).count()));
    };

    const auto warmPagesStart = phaseNow();
    warmWorldgenPagesForChunk(chunk.coord);
    recordPhase(benchmarkMetrics_.buildChunkCpuWarmPagesStage, warmPagesStart, phaseNow());

    std::array<terrain::ExactChunkColumnDescriptor, Chunk::kColumnCount> columnDescriptors{};
    std::vector<StructureVoxelEdit> structureVoxelEdits;
    bool haveStoredStructureEdits = false;
    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        haveStoredStructureEdits = chunk.structureVoxelEditsReady;
        if (haveStoredStructureEdits)
        {
            structureVoxelEdits = chunk.structureVoxelEdits;
        }
    }

    if (terrainGenerator_)
    {
        const auto describeColumnsStart = phaseNow();
        terrainGenerator_->describeChunkColumns(chunk.coord,
                                               chunk.minWorldY,
                                               chunk.maxWorldY,
                                               kChunkSizeX,
                                               kChunkSizeY,
                                               kChunkSizeZ,
                                               columnDescriptors,
                                               columnResults);
        recordPhase(benchmarkMetrics_.buildChunkCpuDescribeColumnsStage, describeColumnsStart, phaseNow());
    }

    auto setBlockDirect = [&](int localX, int localY, int localZ, BlockId block)
    {
        if (localX < 0 || localX >= kChunkSizeX || localZ < 0 || localZ >= kChunkSizeZ)
        {
            return;
        }
        if (localY < 0 || localY >= kChunkSizeY)
        {
            return;
        }
        scratch.setGeneratedLocalBlock(localX, localY, localZ, block);
    };
    if (terrainGenerator_)
    {
        const auto materializeColumnsStart = phaseNow();
        terrainGenerator_->materializeChunkColumns(chunk.minWorldY,
                                                   chunk.maxWorldY,
                                                   kChunkSizeX,
                                                   kChunkSizeY,
                                                   kChunkSizeZ,
                                                   columnDescriptors,
                                                   setBlockDirect);
        recordPhase(benchmarkMetrics_.buildChunkCpuMaterializeColumnsStage, materializeColumnsStart, phaseNow());
    }

    for (std::size_t i = 0; i < columnResults.size(); ++i)
    {
        scratch.highestSolidWorlds[i] = columnDescriptors[i].highestSolidWorld;
    }

    const auto applyStructureEditsStart = phaseNow();
    if (!haveStoredStructureEdits)
    {
        bool allStructureRegionsReady = true;
        structureVoxelEdits = queryStructureVoxelEditsForChunkReady(chunk.coord, &allStructureRegionsReady, nullptr);
        assert(allStructureRegionsReady &&
               "buildChunkCpuBlocks expects structure regions to be ready when cached edits are unavailable");
    }

    for (const StructureVoxelEdit& edit : structureVoxelEdits)
    {
        scratch.setWorldBlock(edit.worldPos.x,
                              edit.worldPos.y,
                              edit.worldPos.z,
                              edit.block,
                              edit.replaceSolid);
    }
    recordPhase(benchmarkMetrics_.buildChunkCpuApplyStructureEditsStage, applyStructureEditsStart, phaseNow());

    const auto applyPendingEditsStart = phaseNow();
    std::vector<PendingStructureEdit> pendingEdits = includePendingStructureEdits
        ? takePendingStructureEdits(chunk.coord)
        : copyPendingStructureEdits(chunk.coord);
    for (const PendingStructureEdit& edit : pendingEdits)
    {
        scratch.setWorldBlock(edit.worldPos.x, edit.worldPos.y, edit.worldPos.z, edit.block, edit.replaceSolid);
    }
    recordPhase(benchmarkMetrics_.buildChunkCpuApplyPendingEditsStage, applyPendingEditsStart, phaseNow());

    const auto applyOverlayStart = phaseNow();
    applyBlockEditOverlay(scratch, chunk.coord);
    recordPhase(benchmarkMetrics_.buildChunkCpuApplyOverlayStage, applyOverlayStart, phaseNow());

    if (consumedPendingEdits != nullptr)
    {
        *consumedPendingEdits = std::move(pendingEdits);
    }
}

void ChunkManager::Impl::rebuildChunkBaseLighting(
    const std::vector<BlockId>& blocks,
    const std::array<std::uint8_t, kChunkSizeX * kChunkSizeZ>& skyLightFromAbove,
    std::vector<std::uint8_t>& outLightLevels) const
{
    outLightLevels.assign(kChunkBlockCount, packLightLevels(0, 0));
    for (int localX = 0; localX < kChunkSizeX; ++localX)
    {
        for (int localZ = 0; localZ < kChunkSizeZ; ++localZ)
        {
            const std::size_t localColumnIndex = static_cast<std::size_t>(localZ * kChunkSizeX + localX);
            std::uint8_t incomingSky = skyLightFromAbove[localColumnIndex];

            for (int localY = kChunkSizeY - 1; localY >= 0; --localY)
            {
                const std::size_t idx = blockIndex(localX, localY, localZ);
                const BlockId block = blocks[idx];
                if (isOpaqueForLighting(block))
                {
                    incomingSky = 0;
                }
                else
                {
                    const std::uint8_t attenuation = blockLightingProperties(block).skyAttenuation;
                    incomingSky = static_cast<std::uint8_t>(
                        std::max(0, static_cast<int>(incomingSky) - static_cast<int>(attenuation)));
                }

                outLightLevels[idx] = packLightLevels(incomingSky, blockLightingProperties(block).blockEmission);
            }
        }
    }
}

void ChunkManager::Impl::rebuildChunkBaseLighting(Chunk& chunk) const
{
    rebuildChunkBaseLighting(chunk.blocks, chunk.skyLightFromAboveCache, chunk.lightLevels);
}

int ChunkManager::Impl::denseCpuHorizontalRadius() const noexcept
{
    return std::clamp(2 + targetViewDistance_ / 4,
                      kDenseCpuHorizontalRadiusMin,
                      kDenseCpuHorizontalRadiusMax);
}

int ChunkManager::Impl::denseCpuVerticalRadius() const noexcept
{
    return std::clamp(3 + targetViewDistance_ / 8,
                      kDenseCpuVerticalRadiusMin,
                      kDenseCpuVerticalRadiusMax);
}

bool ChunkManager::Impl::isChunkInLocalInteractionIsland(const glm::ivec3& coord,
                                                         const glm::ivec3& centerChunk) const noexcept
{
    return isChunkInsideEditBubble(coord, centerChunk);
}

bool ChunkManager::Impl::isChunkInsideEditBubble(const glm::ivec3& coord,
                                                 const glm::ivec3& centerChunk) const noexcept
{
    const int horizontalDistance =
        std::max(std::abs(coord.x - centerChunk.x), std::abs(coord.z - centerChunk.z));
    const int verticalDistance = std::abs(coord.y - centerChunk.y);
    return horizontalDistance <= editBubbleConfig_.horizontalRadius &&
           verticalDistance <= editBubbleConfig_.verticalRadius;
}

bool ChunkManager::Impl::chunkHasPendingLocalWork(const Chunk& chunk) const
{
    return chunk.pendingMeshPresent.load(std::memory_order_acquire) ||
           chunk.pendingMeshRefresh.load(std::memory_order_acquire) ||
           chunk.meshReady.load(std::memory_order_acquire) ||
           chunk.queuedForUpload.load(std::memory_order_acquire) ||
           chunk.queuedForCommit.load(std::memory_order_acquire);
}

bool ChunkManager::Impl::chunkCountsTowardPendingExactGpuBuilds(const Chunk& chunk) const noexcept
{
    if (chunk.gameplayAuthority.load(std::memory_order_acquire) != ChunkGameplayAuthority::GpuStreaming)
    {
        return false;
    }

    const bool hasRenderableContent = chunk.hasBlocks.load(std::memory_order_acquire);
    const bool resident = chunk.exactGpuResident.load(std::memory_order_acquire);
    const bool queued = chunk.exactGpuBuildQueued.load(std::memory_order_acquire);
    const bool inFlight = chunk.exactGpuBuildInFlight.load(std::memory_order_acquire);
    const bool dirtyInputs =
        chunk.exactGpuInputsDirty.load(std::memory_order_acquire) ||
        chunk.exactGpuReadyVersion.load(std::memory_order_acquire) !=
            chunk.exactGpuInputsVersion.load(std::memory_order_acquire);

    return (hasRenderableContent && (!resident || queued || inFlight || dirtyInputs)) ||
           (!hasRenderableContent && (queued || inFlight));
}

void ChunkManager::Impl::refreshPendingExactGpuBuildCount(Chunk& chunk) noexcept
{
    const bool shouldCount = chunkCountsTowardPendingExactGpuBuilds(chunk);
    bool counted = chunk.pendingExactGpuBuildCounted.load(std::memory_order_acquire);
    while (counted != shouldCount)
    {
        if (chunk.pendingExactGpuBuildCounted.compare_exchange_weak(counted,
                                                                    shouldCount,
                                                                    std::memory_order_acq_rel,
                                                                    std::memory_order_acquire))
        {
            if (shouldCount)
            {
                pendingExactGpuBuildsCached_.fetch_add(1, std::memory_order_relaxed);
            }
            else
            {
                pendingExactGpuBuildsCached_.fetch_sub(1, std::memory_order_relaxed);
            }
            return;
        }
    }
}

void ChunkManager::Impl::clearPendingExactGpuBuildCount(Chunk& chunk) noexcept
{
    if (chunk.pendingExactGpuBuildCounted.exchange(false, std::memory_order_acq_rel))
    {
        pendingExactGpuBuildsCached_.fetch_sub(1, std::memory_order_relaxed);
    }
}

bool ChunkManager::Impl::chunkNeedsExactGpuHandoff(const Chunk& chunk) const
{
    if (!chunk.cpuDataResident.load(std::memory_order_acquire))
    {
        return false;
    }

    const std::uint64_t handoffTargetRevision = chunk.handoffTargetRevision.load(std::memory_order_acquire);
    if (handoffTargetRevision > 0)
    {
        const bool liveExactReadyForTarget =
            !chunk.exactGpuPublishPending.load(std::memory_order_acquire) &&
            chunk.exactGpuResident.load(std::memory_order_acquire) &&
            !chunk.exactGpuInputsDirty.load(std::memory_order_acquire) &&
            chunk.exactGpuReadyVersion.load(std::memory_order_acquire) >= handoffTargetRevision &&
            chunk.exactGpuPendingNeighborMask.load(std::memory_order_acquire) == 0u;
        if (liveExactReadyForTarget)
        {
            return false;
        }

        return !chunk.handoffReady.load(std::memory_order_acquire);
    }

    if (device_ == nullptr || !exactGpuContext_.ready())
    {
        return false;
    }

    if (chunk.exactGpuPublishPending.load(std::memory_order_acquire))
    {
        return true;
    }

    if (!chunk.hasBlocks.load(std::memory_order_acquire))
    {
        return false;
    }

    return !chunk.exactGpuResident.load(std::memory_order_acquire) ||
           chunk.exactGpuInputsDirty.load(std::memory_order_acquire) ||
           chunk.exactGpuReadyVersion.load(std::memory_order_acquire) !=
               chunk.exactGpuInputsVersion.load(std::memory_order_acquire) ||
           chunk.exactGpuPendingNeighborMask.load(std::memory_order_acquire) != 0u;
}

void ChunkManager::Impl::recomputeChunkExactGpuHandoffReadiness(Chunk& chunk)
{
    const std::uint64_t handoffTargetRevision = chunk.handoffTargetRevision.load(std::memory_order_acquire);
    const bool handoffReady =
        handoffTargetRevision > 0 &&
        chunk.exactGpuPublishPending.load(std::memory_order_acquire) &&
        chunk.pendingExactDrawReady.load(std::memory_order_acquire) &&
        chunk.exactGpuReadyVersion.load(std::memory_order_acquire) >= handoffTargetRevision &&
        chunk.exactGpuPendingNeighborMask.load(std::memory_order_acquire) == 0u;
    chunk.handoffReady.store(handoffReady, std::memory_order_release);
}

ChunkGameplayAuthority ChunkManager::Impl::desiredChunkGameplayAuthorityFromState(
    const Chunk& chunk,
    const glm::ivec3& centerChunk,
    double nowSeconds,
    bool hasPendingLocalWork) const
{
    if (isChunkInsideEditBubble(chunk.coord, centerChunk))
    {
        return ChunkGameplayAuthority::LocalGameplay;
    }

    const std::uint64_t lastLocalEditMicros = chunk.lastLocalEditMicros.load(std::memory_order_acquire);
    const std::uint64_t handoffTargetRevision = chunk.handoffTargetRevision.load(std::memory_order_acquire);
    const bool activeLocalEditOwnership =
        lastLocalEditMicros > 0 ||
        handoffTargetRevision > 0;
    if (!activeLocalEditOwnership)
    {
        return ChunkGameplayAuthority::GpuStreaming;
    }

    if (hasPendingLocalWork)
    {
        return ChunkGameplayAuthority::LocalGameplay;
    }

    if (lastLocalEditMicros > 0)
    {
        const double editAgeSeconds =
            std::max(0.0, nowSeconds - static_cast<double>(lastLocalEditMicros) / 1'000'000.0);
        if (editAgeSeconds <= editBubbleConfig_.exitGraceSeconds)
        {
            return ChunkGameplayAuthority::LocalGameplay;
        }
    }

    if (chunkNeedsExactGpuHandoff(chunk))
    {
        return ChunkGameplayAuthority::HandoffToGpu;
    }

    return ChunkGameplayAuthority::GpuStreaming;
}

bool ChunkManager::Impl::shouldKeepLoadedChunkInteractive(const Chunk& chunk,
                                                          const glm::ivec3& centerChunk) const
{
    const double nowSeconds = static_cast<double>(steadyMicrosNow()) / 1'000'000.0;
    return desiredChunkGameplayAuthorityFromState(chunk,
                                                  centerChunk,
                                                  nowSeconds,
                                                  chunkHasPendingLocalWork(chunk)) != ChunkGameplayAuthority::GpuStreaming;
}

bool ChunkManager::Impl::chunkUsesCpuNearRendering(const Chunk& chunk) const noexcept
{
    const ChunkGameplayAuthority authority = chunk.gameplayAuthority.load(std::memory_order_acquire);
    return authority == ChunkGameplayAuthority::LocalGameplay ||
           authority == ChunkGameplayAuthority::HandoffToGpu;
}

ChunkGameplayAuthority ChunkManager::Impl::desiredChunkGameplayAuthority(const Chunk& chunk,
                                                                         const glm::ivec3& centerChunk,
                                                                         double nowSeconds) const
{
    return desiredChunkGameplayAuthorityFromState(chunk,
                                                  centerChunk,
                                                  nowSeconds,
                                                  chunkHasPendingLocalWork(chunk));
}

bool ChunkManager::Impl::shouldKeepChunkInteractive(const glm::ivec3& coord,
                                                    const glm::ivec3& centerChunk) const
{
    const std::shared_ptr<const Chunk> chunk = getChunkShared(coord);
    if (!chunk)
    {
        return isChunkInsideEditBubble(coord, centerChunk) || shouldTrackRecentEditChunk(coord);
    }

    return shouldKeepLoadedChunkInteractive(*chunk, centerChunk);
}

JobServiceClass ChunkManager::Impl::mergeDependencyServiceClass(JobServiceClass lhs,
                                                                JobServiceClass rhs) noexcept
{
    return jobServiceClassIndex(lhs) <= jobServiceClassIndex(rhs) ? lhs : rhs;
}

JobServiceClass ChunkManager::Impl::supportDependencyServiceClass(ColumnHeightPrefetchPriority priority) noexcept
{
    switch (priority)
    {
    case ColumnHeightPrefetchPriority::Critical:
        return JobServiceClass::InitialVisible;
    case ColumnHeightPrefetchPriority::Visible:
        return JobServiceClass::Standard;
    case ColumnHeightPrefetchPriority::Normal:
    case ColumnHeightPrefetchPriority::Background:
        return JobServiceClass::Refinement;
    }

    return JobServiceClass::Refinement;
}

JobServiceClass ChunkManager::Impl::supportDependencyServiceClass(DependencyPriority priority) noexcept
{
    switch (priority)
    {
    case DependencyPriority::Critical:
        return JobServiceClass::InitialVisible;
    case DependencyPriority::Visible:
        return JobServiceClass::Standard;
    case DependencyPriority::Background:
        return JobServiceClass::Refinement;
    }

    return JobServiceClass::Refinement;
}

ExactChunkResidencyMode ChunkManager::Impl::classifyExactChunkResidencyMode(const Chunk& chunk,
                                                                            const glm::ivec3& centerChunk) const
{
    const double nowSeconds = static_cast<double>(steadyMicrosNow()) / 1'000'000.0;
    const ChunkGameplayAuthority authority =
        desiredChunkGameplayAuthority(chunk, centerChunk, nowSeconds);
    if (authority == ChunkGameplayAuthority::LocalGameplay)
    {
        return chunk.cpuDataResident.load(std::memory_order_acquire)
            ? ExactChunkResidencyMode::CpuAuthoritative
            : ExactChunkResidencyMode::CpuMaterializing;
    }

    if (authority == ChunkGameplayAuthority::HandoffToGpu)
    {
        return chunk.cpuDataResident.load(std::memory_order_acquire)
            ? ExactChunkResidencyMode::GpuPendingRetire
            : ExactChunkResidencyMode::CpuMaterializing;
    }

    if (device_ != nullptr && exactGpuContext_.ready())
    {
        return chunk.cpuDataResident.load(std::memory_order_acquire)
            ? ExactChunkResidencyMode::GpuPendingRetire
            : ExactChunkResidencyMode::GpuResidentNonlocal;
    }

    if (chunk.exactGpuResident.load(std::memory_order_acquire))
    {
        return chunk.cpuDataResident.load(std::memory_order_acquire)
            ? ExactChunkResidencyMode::GpuPendingRetire
            : ExactChunkResidencyMode::GpuResidentNonlocal;
    }

    if (chunk.exactGpuBuildQueued.load(std::memory_order_acquire) ||
        chunk.exactGpuBuildInFlight.load(std::memory_order_acquire))
    {
        return ExactChunkResidencyMode::CpuMaterializing;
    }

    return chunk.cpuDataResident.load(std::memory_order_acquire)
        ? ExactChunkResidencyMode::GpuPendingRetire
        : ExactChunkResidencyMode::GpuResidentNonlocal;
}

JobServiceClass ChunkManager::Impl::classifyJobServiceClass(bool initialReadyPriority,
                                                            bool localInteractionPriority,
                                                            bool refinementPriority) noexcept
{
    if (initialReadyPriority)
    {
        return JobServiceClass::InitialVisible;
    }
    if (localInteractionPriority)
    {
        return JobServiceClass::LocalInteraction;
    }
    if (refinementPriority)
    {
        return JobServiceClass::Refinement;
    }
    return JobServiceClass::Standard;
}

bool ChunkManager::Impl::ensureChunkCpuDataResident(Chunk& chunk)
{
    chunk.residencyMode.store(ExactChunkResidencyMode::CpuMaterializing, std::memory_order_release);
    bool existingResident = false;
    const auto desiredResidencyModeWhileLocked = [this, &chunk]() noexcept
    {
        const bool hasPendingLocalWork =
            chunk.pendingMesh.valid() ||
            chunk.pendingMeshRefresh.load(std::memory_order_acquire) ||
            chunk.meshReady.load(std::memory_order_acquire) ||
            chunk.queuedForUpload.load(std::memory_order_acquire) ||
            chunk.queuedForCommit.load(std::memory_order_acquire);
        const double nowSeconds = static_cast<double>(steadyMicrosNow()) / 1'000'000.0;
        const ChunkGameplayAuthority authority =
            desiredChunkGameplayAuthorityFromState(chunk, lastCenterChunk_, nowSeconds, hasPendingLocalWork);
        return authority != ChunkGameplayAuthority::GpuStreaming
            ? ExactChunkResidencyMode::CpuAuthoritative
            : ExactChunkResidencyMode::CpuMaterializing;
    };
    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        if (chunk.cpuDataResident.load(std::memory_order_acquire) &&
            chunk.blocks.size() == static_cast<std::size_t>(kChunkBlockCount))
        {
            chunk.lastDenseFrameTouched = updateFrameIndex_;
            chunk.residencyMode.store(desiredResidencyModeWhileLocked(), std::memory_order_release);
            existingResident = true;
        }
    }
    if (existingResident)
    {
        setDenseTrackedCoord(chunk.coord, true);
        return true;
    }

    ChunkBuildScratch scratch(chunk);
    std::array<ColumnBuildResult, static_cast<std::size_t>(kChunkSizeX * kChunkSizeZ)> columnResults{};
    buildChunkCpuBlocks(chunk, scratch, false, columnResults, nullptr);

    {
        std::lock_guard<std::mutex> lock(chunk.meshMutex);
        chunk.ensureCpuDataAllocated();
        chunk.blocks = std::move(scratch.blocks);
        chunk.hasBlocks.store(std::any_of(chunk.blocks.begin(),
                                          chunk.blocks.end(),
                                          [](BlockId block) { return block != BlockId::Air; }),
                              std::memory_order_release);
        chunk.lastDenseFrameTouched = updateFrameIndex_;
        chunk.residencyMode.store(desiredResidencyModeWhileLocked(), std::memory_order_release);
    }
    setDenseTrackedCoord(chunk.coord, true);
    return true;
}

void ChunkManager::Impl::releaseChunkCpuData(Chunk& chunk)
{
    std::lock_guard<std::mutex> lock(chunk.meshMutex);
    if (!chunk.cpuDataResident.load(std::memory_order_acquire))
    {
        return;
    }

    if (chunk.exactGpuResident.load(std::memory_order_acquire))
    {
        chunk.releaseCpuData();
        chunk.residencyMode.store(ExactChunkResidencyMode::GpuResidentNonlocal, std::memory_order_release);
        return;
    }

    const ChunkState state = chunk.state.load(std::memory_order_acquire);
    if (state != ChunkState::Uploaded ||
        chunk.inFlight.load(std::memory_order_acquire) > 0 ||
        chunk.queuedForUpload.load(std::memory_order_acquire) ||
        chunk.pendingMesh.valid() ||
        chunk.pendingMeshRefresh.load(std::memory_order_acquire) ||
        chunk.meshReady.load(std::memory_order_acquire))
    {
        return;
    }

    chunk.releaseCpuData();
    chunk.residencyMode.store(ExactChunkResidencyMode::GpuResidentNonlocal, std::memory_order_release);
}

void ChunkManager::Impl::updateDenseChunkResidency(const glm::ivec3& centerChunk)
{
    const double nowSeconds = static_cast<double>(steadyMicrosNow()) / 1'000'000.0;
    const int horizontalRadius = denseCpuHorizontalRadius();
    const int baseHydrationBudget = std::clamp(1 + horizontalRadius / 3,
                                               kDenseCpuHydrationBudgetMin,
                                               kDenseCpuHydrationBudgetMax);
    const int demotionBudget = std::clamp(baseHydrationBudget * 8,
                                          kDenseCpuDemotionBudgetMin,
                                          kDenseCpuDemotionBudgetMax);

    std::vector<glm::ivec3> candidateCoords;
    collectDenseResidencyCandidateCoords(centerChunk, horizontalRadius, candidateCoords);

    std::vector<std::shared_ptr<Chunk>> chunks;
    std::vector<glm::ivec3> staleTrackedCoords;
    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        chunks.reserve(candidateCoords.size());
        staleTrackedCoords.reserve(candidateCoords.size());
        for (const glm::ivec3& coord : candidateCoords)
        {
            const auto it = chunks_.find(coord);
            if (it == chunks_.end() || !it->second)
            {
                staleTrackedCoords.push_back(coord);
                continue;
            }

            chunks.push_back(it->second);
        }
    }

    std::vector<std::shared_ptr<Chunk>> toHydrate;
    std::vector<std::shared_ptr<Chunk>> toDemote;
    toHydrate.reserve(chunks.size());
    toDemote.reserve(chunks.size());

    const auto interactionPriority = [this, &centerChunk](const std::shared_ptr<Chunk>& chunk)
    {
        return shouldKeepLoadedChunkInteractive(*chunk, centerChunk) ? 0 : 1;
    };

    const auto densePriority = [&centerChunk, &interactionPriority](const std::shared_ptr<Chunk>& chunk)
    {
        const int horizontalDistance =
            std::max(std::abs(chunk->coord.x - centerChunk.x), std::abs(chunk->coord.z - centerChunk.z));
        const int verticalDistance = std::abs(chunk->coord.y - centerChunk.y);
        return std::tuple<int, int, int, int, int>{
            interactionPriority(chunk),
            horizontalDistance,
            verticalDistance,
            chunk->coord.y,
            chunk->coord.x};
    };

    for (const std::shared_ptr<Chunk>& chunk : chunks)
    {
        if (!chunk)
        {
            continue;
        }

        const ChunkGameplayAuthority gameplayAuthority =
            desiredChunkGameplayAuthority(*chunk, centerChunk, nowSeconds);
        chunk->gameplayAuthority.store(gameplayAuthority, std::memory_order_release);
        const ExactChunkResidencyMode residencyMode = classifyExactChunkResidencyMode(*chunk, centerChunk);
        chunk->residencyMode.store(residencyMode, std::memory_order_release);
        const bool keepDense = gameplayAuthority != ChunkGameplayAuthority::GpuStreaming;
        if (keepDense)
        {
            if (gameplayAuthority == ChunkGameplayAuthority::LocalGameplay)
            {
                chunk->handoffTargetRevision.store(0, std::memory_order_release);
                chunk->handoffReady.store(false, std::memory_order_release);
            }

            if (gameplayAuthority == ChunkGameplayAuthority::HandoffToGpu)
            {
                const std::uint64_t inputVersion = chunk->exactGpuInputsVersion.load(std::memory_order_acquire);
                if (chunk->handoffTargetRevision.load(std::memory_order_acquire) != inputVersion)
                {
                    chunk->handoffTargetRevision.store(inputVersion, std::memory_order_release);
                }
                recomputeChunkExactGpuHandoffReadiness(*chunk);
                if (!chunk->handoffReady.load(std::memory_order_acquire) &&
                    device_ != nullptr && exactGpuContext_.ready())
                {
                    chunk->exactGpuPreferDenseUpload.store(true, std::memory_order_release);
                    queueChunkForExactGpuRefresh(chunk, true);
                }
            }

            if (chunk->cpuDataResident.load(std::memory_order_acquire))
            {
                std::lock_guard<std::mutex> lock(chunk->meshMutex);
                chunk->lastDenseFrameTouched = updateFrameIndex_;
            }
            else
            {
                toHydrate.push_back(chunk);
            }

            const bool needsCpuMeshForVisibleOwnership =
                chunk->state.load(std::memory_order_acquire) == ChunkState::Uploaded &&
                chunk->indexCount.load(std::memory_order_acquire) == 0 &&
                !chunk->meshReady.load(std::memory_order_acquire) &&
                !chunk->queuedForUpload.load(std::memory_order_acquire) &&
                !chunk->queuedForCommit.load(std::memory_order_acquire);
            if (needsCpuMeshForVisibleOwnership)
            {
                requestChunkRemesh(chunk, true);
            }
            refreshPendingExactGpuBuildCount(*chunk);
            continue;
        }

        if (gameplayAuthority == ChunkGameplayAuthority::GpuStreaming &&
            chunk->handoffReady.load(std::memory_order_acquire))
        {
            (void)finalizeChunkExactGpuHandoff(chunk);
        }

        if (gameplayAuthority == ChunkGameplayAuthority::GpuStreaming &&
            !chunk->exactGpuPublishPending.load(std::memory_order_acquire))
        {
            chunk->handoffTargetRevision.store(0, std::memory_order_release);
            chunk->handoffReady.store(false, std::memory_order_release);
            chunk->lastLocalEditMicros.store(0, std::memory_order_release);
        }

        const bool needsNonlocalExactGpuRefresh =
            device_ != nullptr &&
            exactGpuContext_.ready() &&
            chunk->state.load(std::memory_order_acquire) == ChunkState::Uploaded &&
            chunk->hasBlocks.load(std::memory_order_acquire) &&
            !chunk->cpuDataResident.load(std::memory_order_acquire) &&
            (!chunk->exactGpuResident.load(std::memory_order_acquire) ||
             chunk->exactGpuInputsDirty.load(std::memory_order_acquire) ||
             chunk->exactGpuReadyVersion.load(std::memory_order_acquire) !=
                 chunk->exactGpuInputsVersion.load(std::memory_order_acquire));
        if (needsNonlocalExactGpuRefresh &&
            !chunk->exactGpuBuildQueued.load(std::memory_order_acquire) &&
            !chunk->exactGpuBuildInFlight.load(std::memory_order_acquire))
        {
            queueChunkForExactGpuRefresh(chunk);
        }

        if (chunk->cpuDataResident.load(std::memory_order_acquire))
        {
            std::uint64_t lastTouched = 0;
            {
                std::lock_guard<std::mutex> lock(chunk->meshMutex);
                lastTouched = chunk->lastDenseFrameTouched;
            }
            if (updateFrameIndex_ > lastTouched + kDenseCpuDemotionGraceFrames)
            {
                toDemote.push_back(chunk);
            }
        }

        refreshPendingExactGpuBuildCount(*chunk);
    }

    std::sort(toHydrate.begin(),
              toHydrate.end(),
              [&densePriority](const std::shared_ptr<Chunk>& lhs, const std::shared_ptr<Chunk>& rhs)
              {
                  return densePriority(lhs) < densePriority(rhs);
              });
    std::sort(toDemote.begin(),
              toDemote.end(),
              [&densePriority](const std::shared_ptr<Chunk>& lhs, const std::shared_ptr<Chunk>& rhs)
              {
                  return densePriority(lhs) > densePriority(rhs);
              });

    const int stickyInteractionHydrationBudget = static_cast<int>(std::min<std::size_t>(
        static_cast<std::size_t>(kDenseCpuHydrationBudgetMax * 3),
        static_cast<std::size_t>(std::count_if(toHydrate.begin(),
                                               toHydrate.end(),
                                               [&interactionPriority](const std::shared_ptr<Chunk>& chunk)
                                               {
                                                   return interactionPriority(chunk) == 0;
                                               }))));
    const int hydrationBudget = std::max(baseHydrationBudget, stickyInteractionHydrationBudget);

    // Keep dense CPU hydration incremental so altitude changes do not rebuild hundreds of chunks
    // on the main thread in a single frame.
    const std::size_t hydrateCount =
        std::min<std::size_t>(toHydrate.size(), static_cast<std::size_t>(std::max(0, hydrationBudget)));
    const std::size_t demoteCount =
        std::min<std::size_t>(toDemote.size(), static_cast<std::size_t>(std::max(0, demotionBudget)));

    for (std::size_t i = 0; i < hydrateCount; ++i)
    {
        const std::shared_ptr<Chunk>& chunk = toHydrate[i];
        if (chunk && ensureChunkCpuDataResident(*chunk))
        {
            std::lock_guard<std::mutex> lock(chunk->meshMutex);
            columnManager_.updateChunk(makeChunkBlockView(*chunk));
        }
        if (chunk)
        {
            requestChunkRemesh(chunk, true);
        }
    }

    for (std::size_t i = 0; i < demoteCount; ++i)
    {
        const std::shared_ptr<Chunk>& chunk = toDemote[i];
        if (chunk)
        {
            const bool requiresGpuHandoff =
                device_ != nullptr &&
                exactGpuContext_.ready() &&
                chunk->hasBlocks.load(std::memory_order_acquire) &&
                (!chunk->exactGpuResident.load(std::memory_order_acquire) ||
                 chunk->exactGpuInputsDirty.load(std::memory_order_acquire) ||
                 chunk->exactGpuReadyVersion.load(std::memory_order_acquire) !=
                     chunk->exactGpuInputsVersion.load(std::memory_order_acquire));
            if (requiresGpuHandoff)
            {
                if (!chunk->exactGpuBuildQueued.load(std::memory_order_acquire) &&
                    !chunk->exactGpuBuildInFlight.load(std::memory_order_acquire))
                {
                    queueChunkForExactGpuRefresh(chunk);
                }

                if (!chunk->exactGpuResident.load(std::memory_order_acquire) ||
                    chunk->exactGpuInputsDirty.load(std::memory_order_acquire) ||
                    chunk->exactGpuReadyVersion.load(std::memory_order_acquire) !=
                        chunk->exactGpuInputsVersion.load(std::memory_order_acquire) ||
                    chunk->exactGpuBuildQueued.load(std::memory_order_acquire) ||
                    chunk->exactGpuBuildInFlight.load(std::memory_order_acquire))
                {
                    continue;
                }
            }

            releaseChunkCpuData(*chunk);
        }
    }

    {
        std::lock_guard<std::mutex> lock(chunksMutex);
        for (const glm::ivec3& coord : staleTrackedCoords)
        {
            denseTrackedCoords_.erase(coord);
        }

        for (const std::shared_ptr<Chunk>& chunk : chunks)
        {
            if (!chunk)
            {
                continue;
            }

            const bool shouldTrack =
                chunk->cpuDataResident.load(std::memory_order_acquire) ||
                chunk->gameplayAuthority.load(std::memory_order_acquire) != ChunkGameplayAuthority::GpuStreaming;
            if (shouldTrack)
            {
                denseTrackedCoords_.insert(chunk->coord);
            }
            else
            {
                denseTrackedCoords_.erase(chunk->coord);
            }
        }
    }
}

bool ChunkManager::Impl::applyPendingStructureEditsLocked(Chunk& chunk)
{
    std::vector<PendingStructureEdit> edits = takePendingStructureEdits(chunk.coord);
    if (!edits.empty())
    {
        if (!chunk.structureVoxelEditsReady)
        {
            chunk.structureVoxelEdits.clear();
            chunk.structureVoxelEditsReady = true;
        }
        chunk.structureVoxelEdits.reserve(chunk.structureVoxelEdits.size() + edits.size());
        for (const PendingStructureEdit& edit : edits)
        {
            chunk.structureVoxelEdits.push_back(StructureVoxelEdit{edit.worldPos, edit.block, edit.replaceSolid});
        }
    }

    bool wroteSolid = false;
    for (const PendingStructureEdit& edit : edits)
    {
        const glm::ivec3 local = localBlockCoords(edit.worldPos, chunk.coord);
        if (local.x < 0 || local.x >= kChunkSizeX ||
            edit.worldPos.y < chunk.minWorldY || edit.worldPos.y > chunk.maxWorldY ||
            local.z < 0 || local.z >= kChunkSizeZ)
        {
            continue;
        }

        const int localY = edit.worldPos.y - chunk.minWorldY;
        BlockId& destination = chunk.blocks[blockIndex(local.x, localY, local.z)];
        if (!edit.replaceSolid && destination != BlockId::Air)
        {
            continue;
        }

        destination = edit.block;
        if (edit.block != BlockId::Air)
        {
            wroteSolid = true;
        }
    }

    return wroteSolid;
}

void ChunkManager::Impl::dispatchStructureEdits(const std::vector<PendingStructureEdit>& edits)
{
    if (edits.empty())
    {
        return;
    }

    std::unordered_set<glm::ivec3, ChunkHasher> touchedChunks;
    touchedChunks.reserve(edits.size());

    {
        std::lock_guard<std::mutex> lock(pendingStructureMutex_);
        for (const PendingStructureEdit& edit : edits)
        {
            pendingStructureEdits_[edit.chunkCoord].push_back(edit);
            touchedChunks.insert(edit.chunkCoord);
        }
    }

    for (const glm::ivec3& coord : touchedChunks)
    {
        invalidateColumnSlabOccupancy({coord.x, coord.z});
    }

    for (const glm::ivec3& coord : touchedChunks)
    {
        auto chunk = getChunkShared(coord);
        if (!chunk)
        {
            continue;
        }

        if (!shouldKeepLoadedChunkInteractive(*chunk, lastCenterChunk_))
        {
            chunk->hasBlocks.store(true, std::memory_order_release);
            chunk->exactGpuInputsVersion.fetch_add(1, std::memory_order_acq_rel);
            chunk->exactGpuInputsDirty.store(true, std::memory_order_release);
            refreshPendingExactGpuBuildCount(*chunk);
            queueChunkForExactGpuRefresh(chunk);
            continue;
        }

        if (!chunk->cpuDataResident.load(std::memory_order_acquire) &&
            !ensureChunkCpuDataResident(*chunk))
        {
            continue;
        }

        ChunkState state = chunk->state.load(std::memory_order_acquire);
        if (state == ChunkState::Generating)
        {
            continue;
        }

        bool wroteSolid = false;
        bool refreshColumnCaches = false;
        {
            std::lock_guard<std::mutex> lock(chunk->meshMutex);
            wroteSolid = applyPendingStructureEditsLocked(*chunk);
            if (wroteSolid)
            {
                chunk->hasBlocks.store(true, std::memory_order_release);
                columnManager_.updateChunk(makeChunkBlockView(*chunk));
                refreshColumnCaches = true;
            }
        }

        if (!wroteSolid)
        {
            continue;
        }

        if (refreshColumnCaches)
        {
            refreshPredictedColumnHeightFromLoadedData({chunk->coord.x, chunk->coord.z});
            markSkyLightColumnDirty({chunk->coord.x, chunk->coord.z});
        }

        chunk->exactGpuInputsVersion.fetch_add(1, std::memory_order_acq_rel);
        chunk->exactGpuInputsDirty.store(true, std::memory_order_release);
        refreshPendingExactGpuBuildCount(*chunk);
        refreshExactGpuColumnVisualsAfterSkyLightChange({coord.x, coord.z}, true);

        (void)state;
    }
}

bool ChunkManager::Impl::chunkHasSolidBlocks(const Chunk& chunk) noexcept
{
    return std::any_of(chunk.blocks.begin(), chunk.blocks.end(), [](BlockId block) { return block != BlockId::Air; });

}

